INSERT INTO exercise_library (name, professional_id, is_active, exercise_type, catalog_region, catalog_subcategory, instructions, source_exercise_id)
VALUES
  ('MOVILIZACIÓN DE LA 1RA COSTILLA - CINTO O TOALLA - A', NULL, true, 'pasivo', 'Cervical', NULL, 'Sentado sobre un extremo de un cinto o cincha, pasala por detrás tuyo y por encima del hombro opuesto, cerca de la base de la columna cervical/cuello. Con una mano tirá del cinto hacia abajo y adelante, en dirección al hombro opuesto, como se muestra. Tirá con firmeza, sin dolor, y mantené.', 5933),
  ('MOVILIZACIÓN DE LA 1RA COSTILLA - CINTO O TOALLA - B', NULL, true, 'pasivo', 'Cervical', NULL, 'Sentado sobre un extremo de un cinto o cincha, pasala por detrás tuyo y por encima del hombro opuesto, cerca de la base de la columna cervical/cuello. Con una mano tirá del cinto hacia abajo y adelante, en dirección al hombro opuesto, como se muestra. Tirá con firmeza, sin dolor, y mantené. Luego, rotá la cabeza hacia el lado del cinto.', 5970),
  ('MOVILIZACIÓN DE LA 1RA COSTILLA - CINTO O TOALLA - C', NULL, true, 'pasivo', 'Cervical', NULL, 'Sentado sobre un extremo de un cinto o cincha, pasala por detrás tuyo y por encima del hombro opuesto, cerca de la base de la columna cervical/cuello. Con una mano tirá del cinto hacia abajo y adelante, en dirección al hombro opuesto, como se muestra. Tirá con firmeza, sin dolor, y mantené. Luego, inclina la cabeza hacia el lado contrario al del cinto.', 5969),
  ('ISOMÉTRICO DE EXTENSIÓN CERVICAL - PELOTA', NULL, true, 'fortalecimiento', 'Cervical', NULL, 'Parate con una pared por detrás y colocá una pelota entre la pared y la parte posterior de tu cabeza. Después, extendé la cabeza hacia atrás mientras hacés presión contra la pelota. Mantené, relajá y repetí.', 98275),
  ('ISOMÉTRICO DE EXTENSIÓN CERVICAL - DEDOS', NULL, true, 'fortalecimiento', 'Cervical', NULL, 'Colocá dos dedos en la parte posterior de la cabeza y presioná suavemente contra ella. Usá los músculos del cuello para evitar cualquier movimiento. Mantené, relajá y repetí.', 361),
  ('EXTENSIÓN CERVICAL CON TOALLA - CURVA DEL CUELLO', NULL, true, 'activo', 'Cervical', NULL, 'Empezá con una toalla de mano enrollada alrededor de la curva del cuello, sosteniendo las puntas hacia adelante como se muestra. Después, extendé el cuello hacia atrás sobre la toalla, como si miraras al techo. Luego volvé a la posición inicial. Las manos deben permanecer quietas y sosteniendo las puntas de la toalla todo el tiempo.', 5932),
  ('EXTENSIÓN CERVICAL CON APOYO DE TOALLA', NULL, true, 'activo', 'Cervical', NULL, 'Empezá con una toalla de mano enrollada alrededor de la base del cráneo, sosteniendo las puntas hacia adelante como se muestra. Después, hacé una retracción de mentón y extendé el cuello hacia atrás y hacia arriba, como si fueras a mirar el techo. Luego volvé a la posición inicial. Las manos deben acompañar el movimiento de la cabeza.', 5931),
  ('FLEXIÓN CERVICAL - DECÚBITO DORSAL', NULL, true, 'activo', 'Cervical', NULL, 'Acostado boca arriba, con una toalla chica enrollada bajo la curva del cuello, levantá lentamente la cabeza hacia arriba y adelante, como se muestra.', 356),
  ('ISOMÉTRICO DE FLEXIÓN CERVICAL - DEDOS', NULL, true, 'fortalecimiento', 'Cervical', NULL, 'Colocá dos dedos sobre la frente y presioná suavemente contra ella. Usá los músculos del cuello para evitar cualquier movimiento. Mantené, relajá y repetí.', 362),
  ('ASENTIMIENTOS CERVICALES - FLEXIÓN Y EXTENSIÓN - RETRACCIÓN DE MENTÓN Y EXTENSIONES', NULL, true, 'activo', 'Cervical', NULL, 'Acostado boca arriba, inclina suavemente la cabeza hacia arriba y hacia abajo, manteniendo en todo momento la parte posterior de la cabeza apoyada sobre la almohada/cama/camilla.', 81669),
  ('ISOMÉTRICO DE ROTACIÓN CERVICAL - DEDOS', NULL, true, 'fortalecimiento', 'Cervical', NULL, 'Colocá dos dedos sobre el pómulo y presioná suavemente contra él. Usá los músculos del cuello para evitar cualquier movimiento. Mantené, relajá y repetí.', 363),
  ('ROTACIÓN CERVICAL CON TOALLA - BASE DEL CRÁNEO', NULL, true, 'activo', 'Cervical', NULL, 'Empezá con una toalla de mano enrollada alrededor de la base del cráneo, sosteniendo las puntas hacia adelante como se muestra. Después, rotá la cabeza hacia un costado. Luego volvé a la posición inicial. Las manos deben acompañar el movimiento de la cabeza.', 6569),
  ('AUTOMOVILIZACIÓN ROTACIONAL CERVICAL', NULL, true, 'activo_asistido', 'Cervical', NULL, 'Colocá 2 dedos apenas al costado del centro de la columna cervical, en el nivel que te indique tu terapeuta, y girá la cabeza hacia el lado opuesto. Empujá suavemente hacia adelante con los dedos mientras girás la cabeza.', 6159),
  ('ROTACIONES CERVICALES - DECÚBITO DORSAL', NULL, true, 'activo', 'Cervical', NULL, 'Acostado boca arriba, girá la cabeza hacia un lado y después hacia el otro, y repetí. Movete dentro de un rango de movimiento cómodo.', 81671),
  ('AUTOTRACCIÓN CERVICAL', NULL, true, 'pasivo', 'Cervical', NULL, 'Armá una hamaca para la cabeza con una toalla. Atala con una soga y después atá el otro extremo a un objeto estable, como el picaporte de una puerta, como se muestra. Después, acostate boca arriba y acomodá la toalla sosteniendo tu cabeza, de modo que la soga quede a unos 2 a 5 cm del piso y con un ángulo de 30 a 45 grados respecto del picaporte. Tenés que sentirte completamente relajado.', 372),
  ('ISOMÉTRICO DE INCLINACIÓN LATERAL CERVICAL - PELOTA', NULL, true, 'fortalecimiento', 'Cervical', NULL, 'Parate con una pared a un costado y colocá una pelota entre la pared y el lateral de tu cabeza. Después, presioná la cabeza contra la pelota. Mantené, relajá y repetí.', 98276),
  ('ISOMÉTRICO DE INCLINACIÓN LATERAL CERVICAL - DEDOS', NULL, true, 'fortalecimiento', 'Cervical', NULL, 'Colocá dos dedos en el lateral de la cabeza y presioná suavemente contra ella. Usá los músculos del cuello para evitar cualquier movimiento. Mantené, relajá y repetí.', 364),
  ('PROM DE COLUMNA CERVICAL - FLEXIÓN - EXTENSIÓN', NULL, true, 'pasivo', 'Cervical', NULL, 'La persona debe estar completamente relajada mientras el cuidador realiza todo el trabajo (rango de movimiento pasivo) para mover su cabeza. El cuidador empieza sosteniendo la base de la cabeza, separándola de la cama, y luego la mueve suavemente hacia arriba y hacia abajo, de modo que el mentón se acerque al pecho y después vuelva hacia la cama. Repetir.', 121168),
  ('PROM DE COLUMNA CERVICAL - MULTIDIRECCIONAL', NULL, true, 'pasivo', 'Cervical', NULL, 'La persona debe estar completamente relajada mientras el cuidador realiza todo el trabajo (rango de movimiento pasivo) para mover su cabeza. El cuidador empieza sosteniendo la base de la cabeza, separándola de la cama, y luego rota suavemente la cabeza hacia un lado y después hacia el otro, y repite. Después, sosteniendo la base de la cabeza fuera de la cama, inclina suavemente la cabeza de lado a lado. Luego, sosteniendo la base de la cabeza fuera de la cama, mueve suavemente la cabeza hacia arriba y hacia abajo, de modo que el mentón se acerque al pecho y después vuelva hacia la cama.', 121166),
  ('PROM DE COLUMNA CERVICAL - ROTACIÓN', NULL, true, 'pasivo', 'Cervical', NULL, 'La persona debe estar completamente relajada mientras el cuidador realiza todo el trabajo (rango de movimiento pasivo) para mover su cabeza. El cuidador empieza sosteniendo la base de la cabeza, separándola de la cama, y luego rota suavemente la cabeza de lado a lado. Repetir.', 121170),
  ('PROM DE COLUMNA CERVICAL - INCLINACIÓN LATERAL', NULL, true, 'pasivo', 'Cervical', NULL, 'La persona debe estar completamente relajada mientras el cuidador realiza todo el trabajo (rango de movimiento pasivo) para mover su cabeza. El cuidador empieza sosteniendo la base de la cabeza, separándola de la cama, y luego inclina suavemente la cabeza de lado a lado. Repetir.', 121171),
  ('RETRACCIÓN DE MENTÓN CON SOBREPRESIÓN', NULL, true, 'activo', 'Cervical', NULL, 'Hacé una retracción de mentón y agregá sobrepresión con la mano sobre el mentón. Asegurate de que tus ojos, nariz y mentón queden mirando directamente hacia adelante. No dejes que la cabeza se incline hacia arriba.', 36384),
  ('RESPIRACIÓN DIAFRAGMÁTICA', NULL, true, 'sin_clasificar', 'Cervical', NULL, 'Acostado boca arriba, colocá una mano sobre el esternón y la otra sobre el abdomen, cerca del ombligo. Inspirá profundo y lento, concentrándote en que suba la mano del abdomen mientras la del esternón queda quieta. Al inspirar, la mano del abdomen debe subir. Al espirar, la mano del abdomen debe bajar.', 357),
  ('RESPIRACIÓN DIAFRAGMÁTICA - SENTADO', NULL, true, 'sin_clasificar', 'Cervical', NULL, 'Sentado en una silla, colocá una mano sobre el esternón y la otra sobre el abdomen, cerca del ombligo. Inspirá profundo y lento, concentrándote en que suba la mano del abdomen mientras la del esternón queda quieta.', 145856),
  ('RESPIRACIÓN DIAFRAGMÁTICA - DE PIE', NULL, true, 'sin_clasificar', 'Cervical', NULL, 'De pie, colocá una mano sobre el esternón y la otra sobre el abdomen, cerca del ombligo. Inspirá profundo y lento, concentrándote en que suba la mano del abdomen mientras la del esternón queda quieta. Al inspirar profundo, la mano del abdomen debe subir. Al espirar, la mano del abdomen debe bajar.', 91905),
  ('ISOMÉTRICO DE RETRACCIÓN CERVICAL CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cervical', NULL, 'Sentate en una silla con buena postura (orejas alineadas sobre los hombros, cabeza sin adelantarse, omóplatos hacia abajo y atrás, cabeza levemente retraída) y hacé una retracción de mentón. Colocá una banda elástica por detrás de la cabeza y sostené las puntas adelante de la cara, como se muestra. Tirá de la banda hacia adelante con ambos brazos, generando tensión, mientras mantenés la buena postura cervical y no dejás que la cabeza se mueva. Soltá la tensión llevando los brazos de nuevo hacia la cabeza y repetí.', 66097),
  ('ESTIRAMIENTO DEL ELEVADOR DE LA ESCÁPULA', NULL, true, 'activo', 'Cervical', NULL, 'Inclina la cabeza hacia un costado, después rotala hacia ese lado y luego llevala hacia abajo, como si miraras el bolsillo del lado opuesto. Deberías sentir un estiramiento suave en el costado y la parte posterior del cuello.', 97309),
  ('ESTIRAMIENTO DEL ELEVADOR DE LA ESCÁPULA - SOSTENIENDO LA SILLA Y LA PARTE SUPERIOR DE LA CABEZA', NULL, true, 'pasivo', 'Cervical', NULL, 'Agarrate del asiento de la silla y después inclina la cabeza hacia el otro lado, rotala hacia ese lado y llevala hacia abajo, como si miraras el bolsillo del lado opuesto. Con la otra mano aplicá sobrepresión tirando suavemente. Tenés que quedar mirando hacia el bolsillo opuesto al lado que estás trabajando.', 97311),
  ('ESTIRAMIENTO DEL ELEVADOR DE LA ESCÁPULA - SOSTENIENDO LA PARTE SUPERIOR DE LA CABEZA', NULL, true, 'activo', 'Cervical', NULL, 'Inclina la cabeza hacia un costado, después rotala hacia ese lado y luego llevala hacia abajo, como si miraras el bolsillo del lado opuesto. Con la mano tirá de la cabeza hacia abajo y hacia el lado contrario para lograr un estiramiento suave. Tenés que quedar mirando hacia el bolsillo opuesto al lado que estás trabajando. Deberías sentir un estiramiento suave en el costado y la parte posterior del cuello.', 97312),
  ('ESTIRAMIENTO DE ESCALENOS - MANOS SOBRE EL PECHO - ESTIRAMIENTO DE FLEXORES PROFUNDOS ANTERIORES DEL CUELLO', NULL, true, 'activo', 'Cervical', NULL, 'Colocá las manos superpuestas sobre el esternón. Después, inclina la cabeza hacia arriba y hacia el lado contrario al afectado, hasta sentir un estiramiento suave en la parte anterior y lateral del cuello.', 371),
  ('AUTOMASAJE CON PELOTA - SUBOCCIPITALES Y TRAPECIO SUPERIOR', NULL, true, 'activo', 'Cervical', NULL, 'Apoyá la cabeza y usá una pelota de masaje para masajear suavemente los músculos y tendones pequeños de la base del cráneo y el costado del cuello. No pases por encima de zonas óseas.', 99581),
  ('AUTOMASAJE CON PELOTA - TRAPECIO SUPERIOR EN DECÚBITO DORSAL', NULL, true, 'activo', 'Cervical', NULL, 'Acostate en el piso y colocá una pelota en la parte posterior del trapecio superior. No la pongas sobre zonas óseas. Movela hacia las zonas tensas y mantené. Podés usar una pelota de tenis, una de lacrosse (como se muestra) o una de paleta.', 99570),
  ('AUTOMASAJE CON PELOTA - TRAPECIO SUPERIOR', NULL, true, 'activo', 'Cervical', NULL, 'Parate de espaldas a una pared. Colocá una pelota de lacrosse, de tenis o de paleta sobre la parte posterior del trapecio superior, como se muestra. Recostate contra la pelota para aplicar presión suave sobre las zonas tensas. No pases por encima de zonas óseas. Podés mantener la presión en un punto o mover el cuerpo para rodar la pelota con movimientos chicos.', 99633),
  ('AUTOMASAJE CON PELOTA - TRAPECIO SUPERIOR - DE PIE', NULL, true, 'activo', 'Cervical', NULL, 'Parate cerca de la abertura de una puerta. Inclinate hacia adelante desde la cintura, de modo que la cabeza pase por el vano y el hombro quede alineado con la pared. Colocá una pelota de lacrosse, de tenis o de paleta sobre el trapecio superior y recostate contra ella aplicando presión en la zona. Movela hacia las zonas tensas y mantené. No pases por encima de zonas óseas.', 99575),
  ('AUTOMASAJE CON DOBLE PELOTA (MANÍ) - SUBOCCIPITALES', NULL, true, 'activo', 'Cervical', NULL, 'Acostate boca arriba. Colocá una toalla enrollada bajo la curva del cuello. Después colocá una doble pelota de lacrosse o 2 pelotas de tenis/paleta unidas con cinta en la base del cráneo. Luego movés la cabeza con movimientos chicos: podés asentir hacia arriba y abajo, rotar de lado a lado o hacer círculos pequeños.', 99573),
  ('POSTURA CONTRA LA PARED', NULL, true, 'activo', 'Cervical', NULL, 'Parate con los talones contra la pared. Tratá de que los talones, los glúteos, los hombros y la cabeza toquen la pared al mismo tiempo.', 378),
  ('DIAGONALES CERVICALES', NULL, true, 'activo', 'Cervical', 'AROM (activo)', 'Movés la cabeza siguiendo un patrón en diagonal (hacia abajo y a la derecha, y después hacia arriba y a la izquierda). Hacelo de un lado y después repetí del otro (hacia abajo y a la izquierda, y después hacia arriba y a la derecha).', 67955),
  ('FLEXIÓN Y EXTENSIÓN CERVICAL CON PELOTA EN LA PARED - NUCA', NULL, true, 'activo', 'Cervical', 'AROM (activo)', 'Parate con una pared por detrás y colocá una pelota entre la pared y la nuca. Después, movés la cabeza hacia arriba y hacia abajo, flexionando y extendiendo el cuello, como se muestra. Repetí. NOTA: dejá que la pelota ruede durante los movimientos de la cabeza.', 98280),
  ('ROTACIÓN CERVICAL EN DESCARGA', NULL, true, 'activo', 'Cervical', 'AROM (activo)', 'Sentate en una silla frente a una mesa. Apoyá los antebrazos con las manos superpuestas sobre la mesa. Después, apoyá la frente sobre el dorso de las manos mientras rotás la cabeza de lado a lado.', 60373),
  ('ROTACIÓN CERVICAL CON TOALLA - DECÚBITO DORSAL', NULL, true, 'activo', 'Cervical', 'AROM (activo)', 'Empezá con una toalla de mano enrollada alrededor de la base del cráneo, sosteniendo las puntas hacia adelante como se muestra. Después, rotá el cuello hacia un costado. Luego volvé a la posición inicial. Las manos deben acompañar el movimiento de la cabeza.', 5935),
  ('RETRACCIÓN DE MENTÓN - PELOTA', NULL, true, 'activo; fortalecimiento', 'Cervical', 'AROM (activo)', 'Parate con una pared por detrás y colocá una pelota entre la pared y la nuca. Después, retraé la cabeza llevando el mentón hacia el pecho y hacé presión contra la pelota. Mantené, relajá y repetí.', 98263),
  ('RETRACCIÓN DE MENTÓN CON SOBREPRESIÓN Y EXTENSIÓN', NULL, true, 'activo', 'Cervical', 'AROM (activo)', 'Empezá colocando los dedos sobre el mentón y llevá lentamente la cabeza hacia atrás, a una posición de retracción, de modo que las orejas queden alineadas con los hombros. Mantené esa posición mientras extendés la cabeza hacia arriba, como se muestra, y después volvé a la posición inicial y repetí.', 10245),
  ('CÍRCULOS CERVICALES GRANDES - AROM', NULL, true, 'activo', 'Cervical', 'AROM (activo)', 'Movés la cabeza haciendo círculos amplios pero cómodos. Hacé algunas repeticiones en sentido horario y después algunas en sentido antihorario, y repetí.', 67969),
  ('ELEVACIONES LATERALES EN DECÚBITO LATERAL', NULL, true, 'activo', 'Cervical', 'AROM (activo)', 'Empezá acostado de costado sobre una camilla o cama. Después, levantá la cabeza hacia el techo. Los ojos, la nariz y el mentón deben apuntar directamente hacia el costado durante todo el movimiento.', 6288),
  ('EXTENSIÓN CERVICAL BAJA', NULL, true, 'activo', 'Cervical', 'AROM (activo)', 'Colocá las manos por detrás de la base de la cabeza. Después movés la cabeza y los brazos hacia arriba y juntos, como se muestra. Volvé a la posición inicial y repetí. Las manos ayudan a bloquear el movimiento de las articulaciones cervicales altas y permiten enfocar el movimiento en las cervicales bajas.', 36383),
  ('RETRACCIÓN DE MENTÓN EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Cervical', 'AROM (activo)', 'Empezá acostado boca abajo con la cabeza fuera del borde de la cama o camilla. Después, llevá la nuca hacia el techo mientras metés el mentón hacia el pecho. Los ojos, la nariz y el mentón deben apuntar hacia el piso todo el tiempo.', 6289),
  ('CÍRCULOS CERVICALES CHICOS - AROM', NULL, true, 'activo', 'Cervical', 'AROM (activo)', 'Movés la cabeza haciendo círculos chicos y cómodos. Hacé algunas repeticiones en sentido horario y después algunas en sentido antihorario, y repetí.', 67968),
  ('INCLINACIÓN LATERAL CERVICAL - PELOTA EN LA PARED', NULL, true, 'activo', 'Cervical', 'AROM (activo); Pelota', 'Parate con una pared a un costado y colocá una pelota entre la pared y el lateral de la cabeza. Después, llevá la cabeza hacia el costado y volvé a la posición vertical, y repetí. NOTA: dejá que la pelota ruede durante los movimientos de la cabeza.', 98283),
  ('RETRACCIÓN DE MENTÓN CONTRA TOALLA ENROLLADA', NULL, true, 'activo', 'Cervical', 'AROM (activo); Varios; Estabilización', 'Colocá una toalla chica enrollada debajo del mentón, como se muestra. Después, hacé una retracción de mentón llevando la cabeza hacia atrás y bajando el mentón, presionando contra la toalla, y mantené. Relajá y repetí.', 145402),
  ('ESTIRAMIENTO SUBOCCIPITAL CON SOBREPRESIÓN EN EL MENTÓN - IPSILATERAL', NULL, true, 'activo', 'Cervical', 'AROM (activo); Movilización; Estiramientos', 'Retraé la cabeza y aplicá una sobrepresión suave con una mano sobre el mentón. Colocá la otra mano en la nuca y aplicá una fuerza hacia adelante y hacia arriba para generar una pequeña rotación que estire los músculos chicos de la base del cráneo. Después, manteniendo eso, inclina la cabeza hacia un costado y mantené. Relajá y repetí.', 97734),
  ('ELEVACIÓN DE CABEZA EN DECÚBITO VENTRAL - CERVICALES PROFUNDOS', NULL, true, 'activo', 'Cervical', 'AROM (activo); Estabilización', 'Acostate boca abajo y apoyá la cabeza sobre el dorso de las manos. Después, girá levemente la cabeza hacia un costado y despegala de las manos, y mantené. Mantené el mentón metido hacia el pecho todo el tiempo. Volvé a la posición inicial y repetí.', 39423),
  ('RETRACCIÓN DE MENTÓN DE PIE - TOALLA', NULL, true, 'activo', 'Cervical', 'AROM (activo); Estabilización; Estiramientos', 'Parate con una pared por detrás y colocá una toalla chica enrollada en la base/curva del cuello, como se muestra. Después, llevá la cabeza hacia atrás contra la toalla mientras metés el mentón hacia atrás y abajo, en dirección al pecho, y mantené. Relajá y repetí.', 97731),
  ('DECÚBITO VENTRAL SOBRE CODOS - RETRACCIÓN DE MENTÓN', NULL, true, 'activo', 'Cervical', 'AROM (activo); Estabilización; Estiramientos', 'Acostate boca abajo y apoyate sobre los codos. Después, llevá la cabeza a una posición de retracción de mentón (mentón y cabeza hacia atrás, con el mentón acercándose al pecho, como se muestra). Mantené, relajá y repetí.', 97622),
  ('DECÚBITO VENTRAL SOBRE CODOS - RETRACCIÓN DE MENTÓN CON ROTACIONES', NULL, true, 'activo', 'Cervical', 'AROM (activo); Estabilización; Estiramientos', 'Acostate boca abajo y apoyate sobre los codos. Después, llevá la cabeza a una posición de retracción de mentón (mentón y cabeza hacia atrás, con el mentón acercándose al pecho, como se muestra). Manteniendo esa posición, empezá a rotar lentamente la cabeza de lado a lado, sin perder la retracción.', 97623),
  ('CUADRUPEDIA - RETRACCIÓN DE MENTÓN', NULL, true, 'activo; fortalecimiento', 'Cervical', 'AROM (activo); Estabilización; Estiramientos', 'Empezá en cuatro apoyos, sobre manos y rodillas. Después, mirando al frente, llevá la cabeza a una posición de retracción de mentón (mentón y cabeza hacia atrás, con el mentón acercándose al pecho, como se muestra). Mantené, relajá y repetí.', 97621),
  ('CUADRUPEDIA - RETRACCIÓN DE MENTÓN CON ROTACIONES', NULL, true, 'activo; fortalecimiento', 'Cervical', 'AROM (activo); Estabilización; Estiramientos', 'Empezá en cuatro apoyos, sobre manos y rodillas. Después, mirando al frente, llevá la cabeza a una posición de retracción de mentón (mentón y cabeza hacia atrás, con el mentón acercándose al pecho, como se muestra). Manteniendo esa posición, empezá a rotar lentamente la cabeza de lado a lado, sin perder la retracción.', 97620),
  ('FLEXIÓN Y EXTENSIÓN CERVICAL CON PELOTA EN LA PARED - FRENTE', NULL, true, 'activo', 'Cervical', 'AROM (activo); Estiramientos', 'Parate frente a una pared y colocá una pelota entre la pared y tu frente. Después, movés la cabeza hacia arriba y hacia abajo, flexionando y extendiendo el cuello, como se muestra. Repetí. NOTA: dejá que la pelota ruede durante los movimientos de la cabeza.', 98279),
  ('ROTACIÓN CERVICAL - BILATERAL', NULL, true, 'activo', 'Cervical', 'AROM (activo); Estiramientos', 'Girá la cabeza hacia un costado y después hacia el otro. Repetí.', 162828),
  ('ROTACIÓN CERVICAL CON ESTIRAMIENTO POR SOBREPRESIÓN', NULL, true, 'activo', 'Cervical', 'AROM (activo); Estiramientos', 'Girá la cabeza hacia un lado y después usá la mano del lado opuesto para aplicar sobrepresión sobre la mandíbula y lograr un estiramiento más profundo. Mantené, relajá y repetí.', 97732),
  ('INCLINACIÓN LATERAL CERVICAL - AROM', NULL, true, 'activo', 'Cervical', 'AROM (activo); Estiramientos', 'Empezá con la cabeza derecha y en buena postura. Inclina la cabeza hacia un costado y después volvé a la posición inicial. (Asegurate de mantener los ojos y la nariz apuntando al frente todo el tiempo).', 162825),
  ('ESTIRAMIENTO SUBOCCIPITAL CON SOBREPRESIÓN EN EL MENTÓN', NULL, true, 'activo', 'Cervical', 'AROM (activo); Estiramientos', 'Retraé la cabeza y aplicá una sobrepresión suave con una mano sobre el mentón. Colocá la otra mano en la nuca y aplicá una fuerza hacia adelante y hacia abajo para generar una pequeña rotación que estire los músculos chicos de la base del cráneo.', 97733),
  ('MASAJE - PELOTAS DE TENIS EN UNA MEDIA', NULL, true, 'sin_clasificar', 'Cervical', 'Pelota; Varios', 'Colocá dos pelotas de tenis dentro de una media y hacé un nudo para que queden firmes. Después, ubicalas debajo de la base del cráneo, como se muestra. Para automasajearte, podés rodar lentamente la cabeza hacia arriba y hacia abajo, como si dijeras que sí. También podés probar girando levemente la cabeza de lado a lado.', 167406),
  ('MASAJE - PELOTAS DE TENIS UNIDAS CON CINTA', NULL, true, 'sin_clasificar', 'Cervical', 'Pelota; Varios', 'Uní dos pelotas de tenis con cinta para que queden firmes. Después, ubicalas debajo de la base del cráneo, como se muestra. Para automasajearte, podés rodar lentamente la cabeza hacia arriba y hacia abajo, como si dijeras que sí. También podés probar girando levemente la cabeza de lado a lado.', 167405),
  ('ISOMÉTRICO DE EXTENSIÓN CERVICAL - MANOS', NULL, true, 'fortalecimiento', 'Cervical', 'Isométrico', 'Colocá las manos en la nuca y empujá suavemente. Usá los músculos del cuello para evitar cualquier movimiento. Mantené, relajá y repetí.', 162871),
  ('ISOMÉTRICO DE FLEXIÓN CERVICAL - 2 MANOS', NULL, true, 'fortalecimiento', 'Cervical', 'Isométrico', 'Colocá las palmas de ambas manos sobre la frente. Empujá con las manos contra la frente pero resistí el movimiento con los músculos del cuello. Mantené, relajá y repetí.', 53533),
  ('ISOMÉTRICO DE FLEXIÓN CERVICAL - MANO', NULL, true, 'fortalecimiento', 'Cervical', 'Isométrico', 'Colocá la mano sobre la frente y empujá suavemente. Usá los músculos del cuello para evitar cualquier movimiento. Mantené, relajá y repetí.', 162868),
  ('ISOMÉTRICO DE ROTACIÓN CERVICAL - MANO', NULL, true, 'fortalecimiento', 'Cervical', 'Isométrico', 'Colocá la mano sobre el pómulo y empujá suavemente. Usá los músculos del cuello para evitar cualquier movimiento. Mantené, relajá y repetí.', 162869),
  ('ISOMÉTRICO DE INCLINACIÓN LATERAL CERVICAL - MANO', NULL, true, 'fortalecimiento', 'Cervical', 'Isométrico', 'Colocá la mano en el lateral de la cabeza y empujá suavemente. Usá los músculos del cuello para evitar cualquier movimiento. Mantené, relajá y repetí.', 162870),
  ('ISOMÉTRICO DE ROTACIÓN CERVICAL CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cervical', 'Isométrico', 'Sentate en una silla con buena postura (orejas alineadas sobre los hombros, cabeza sin adelantarse, omóplatos hacia abajo y atrás, cabeza levemente retraída). Pasá una banda elástica alrededor de la cabeza y sostené las puntas hacia los costados de la cara, como se muestra. Tirá de una de las puntas hacia el costado con el brazo, generando tensión en la banda, mientras mantenés la buena postura cervical y no dejás que la cabeza rote ni se mueva. Soltá la tensión llevando los brazos de nuevo hacia la cabeza y repetí.', 66099),
  ('ISOMÉTRICO DE INCLINACIÓN LATERAL CERVICAL CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cervical', 'Isométrico', 'Sentate en una silla con buena postura (orejas alineadas sobre los hombros, cabeza sin adelantarse, omóplatos hacia abajo y atrás, cabeza levemente retraída). Colocá una banda elástica alrededor del lateral de la cabeza y sostené las puntas hacia ese costado de la cara, como se muestra. Tirá de la banda hacia el costado (lateralmente) con un brazo, generando tensión, mientras mantenés la buena postura cervical y no dejás que la cabeza se mueva. Soltá la tensión llevando el brazo de nuevo hacia la cabeza y repetí.', 66098),
  ('ISOMÉTRICO DE FLEXIÓN CERVICAL ALTA - 2 MANOS', NULL, true, 'fortalecimiento', 'Cervical', 'Isométrico', 'Colocá ambas manos cerradas en puño debajo del mentón. Después, empujá hacia arriba con los dos puños contra la cara inferior del mentón y resistí el movimiento con los músculos altos del cuello. Mantené, relajá y repetí.', 53536),
  ('RETRACCIÓN CERVICAL - PARED Y TOALLA ENROLLADA', NULL, true, 'fortalecimiento', 'Cervical', 'Isométrico; Estabilización', 'Colocá una toalla enrollada entre la nuca y la pared, como se muestra. Después, hacé suavemente una retracción de mentón llevando la cabeza hacia atrás contra el rollo de toalla. Mantené, relajá y repetí.', 151564),
  ('MANÍ CERVICOTORÁCICO - DOBLE PELOTA - AUTOMOVILIZACIÓN DE LA UNIÓN CERVICOTORÁCICA', NULL, true, 'activo_asistido', 'Cervical', 'Movilización', 'Acostate boca arriba con las rodillas flexionadas. Colocá una doble pelota de lacrosse o 2 pelotas de tenis/paleta unidas con cinta en la unión cervicotorácica de la columna (donde el cuello se une con la parte alta de la espalda). Movelas hacia las zonas tensas y mantené.', 99571),
  ('MANÍ CERVICOTORÁCICO CON BRAZOS - DOBLE PELOTA - AUTOMOVILIZACIÓN DE LA UNIÓN CERVICOTORÁCICA', NULL, true, 'activo_asistido', 'Cervical', 'Movilización', 'Acostate boca arriba. Colocá una doble pelota de lacrosse o 2 pelotas de tenis/paleta unidas con cinta en la unión cervicotorácica de la columna (donde el cuello se une con la parte alta de la espalda). No las pongas sobre zonas óseas. Después, movés los brazos hacia arriba y abajo, y de lado a lado.', 99559),
  ('MANÍ CERVICOTORÁCICO CON PUENTE - DOBLE PELOTA - AUTOMOVILIZACIÓN DE LA UNIÓN CERVICOTORÁCICA', NULL, true, 'activo_asistido; fortalecimiento', 'Cervical', 'Movilización', 'Acostate boca arriba con las rodillas flexionadas. Colocá una doble pelota de lacrosse o 2 pelotas de tenis/paleta unidas con cinta en la unión cervicotorácica de la columna (donde el cuello se une con la parte alta de la espalda). No las pongas sobre zonas óseas. Después, hacé un puente levantando la cola del piso y mantené. Manteniendo esa posición, movés los brazos hacia arriba y abajo, y de lado a lado. Bajá la cola, relajá y repetí.', 99557),
  ('RETRACCIÓN DE MENTÓN EN DECÚBITO VENTRAL CON SOBREPRESIÓN', NULL, true, 'activo', 'Cervical', 'Movilización', 'Acostado boca abajo y apoyado sobre los codos, hacé una retracción de mentón y agregá sobrepresión con las manos. Empujá suavemente el mentón con los pulgares para que las orejas queden alineadas con los hombros.', 36376),
  ('AUTOMASAJE CON PELOTA - TRAPECIO SUPERIOR - DECÚBITO DORSAL', NULL, true, 'activo', 'Cervical', 'Movilización', 'Acostate en el piso cerca de la abertura de una puerta, de modo que la cabeza quede del otro lado del vano y el hombro alineado con la pared. Colocá una pelota de lacrosse, de tenis o de paleta sobre el trapecio superior y acercate a la pared para aplicar presión sobre la zona tensa del músculo trapecio superior. No pases por encima de zonas óseas.', 99576),
  ('AUTOMASAJE DEL TRAPECIO SUPERIOR', NULL, true, 'activo', 'Cervical', 'Movilización', 'Cruzá el brazo por delante del cuerpo hasta la zona lateral del cuello/trapecio superior del lado opuesto y deslizá las yemas de los dedos hacia adelante y atrás hasta encontrar una zona tensa. Frotá la zona y después hundí las yemas en el punto de mayor tensión y mantené. Sin soltar la presión, movés el cuello de lado a lado y en círculos o arcos.', 65791),
  ('ISOMÉTRICO DE EXTENSIÓN CERVICAL - CERVICALES PROFUNDOS', NULL, true, 'fortalecimiento', 'Cervical', 'Estabilización', 'Colocá las manos detrás de la cabeza, girá la cabeza levemente hacia un costado y después presioná las manos contra la cabeza. Usá los músculos del cuello para evitar cualquier movimiento. Mantené, relajá y repetí.', 39424),
  ('ISOMÉTRICO DE FLEXIÓN CERVICAL - PELOTA', NULL, true, 'fortalecimiento', 'Cervical', 'Estabilización', 'Parate frente a una pared y colocá una pelota entre la pared y tu frente. Después, presioná la cabeza contra la pelota. Mantené, relajá y repetí.', 98277),
  ('FLEXIÓN LATERAL CERVICAL CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cervical', 'Estabilización', 'Pasá una banda elástica alrededor de la cabeza y sostené las puntas como se muestra. Empezá con la cabeza en posición neutra. Manteniendo las puntas de la banda quietas, inclina la cabeza hacia el lado contrario para hacer una flexión lateral del cuello y después volvé a la posición neutra y repetí.', 381),
  ('RETRACCIÓN CON BANDA ELÁSTICA - PLANCHA CON RODILLAS', NULL, true, 'fortalecimiento', 'Cervical', 'Estabilización', 'Acostate en el piso en posición de plancha, con las rodillas y los codos/antebrazos apoyados. Después, con una banda elástica alrededor de la cabeza y sosteniendo las puntas, retraé la cabeza contra la resistencia de la banda, como se muestra. Volvé a la posición de cabeza adelantada y repetí. Mantené la plancha durante todo el ejercicio.', 39669),
  ('RETRACCIÓN CON BANDA ELÁSTICA - PLANCHAS', NULL, true, 'fortalecimiento', 'Cervical', 'Estabilización', 'Acostate en el piso en posición de plancha, con las puntas de los pies y los codos/antebrazos apoyados. Después, con una banda elástica alrededor de la cabeza y sosteniendo las puntas, retraé la cabeza contra la resistencia de la banda, como se muestra. Volvé a la posición de cabeza adelantada y repetí. Mantené la plancha durante todo el ejercicio.', 39670),
  ('RETRACCIÓN CON BANDA ELÁSTICA - DECÚBITO VENTRAL SOBRE CODOS', NULL, true, 'fortalecimiento', 'Cervical', 'Estabilización', 'Acostate en el piso boca abajo, apoyado sobre los codos. Después, con una banda elástica alrededor de la cabeza y sosteniendo las puntas, retraé la cabeza contra la resistencia de la banda, como se muestra. Volvé a la posición de cabeza adelantada y repetí.', 39671),
  ('RETRACCIÓN CON BANDA ELÁSTICA 1', NULL, true, 'fortalecimiento', 'Cervical', 'Estabilización', 'Empezá con una banda elástica pasada por detrás de la cabeza, como se muestra. Después, llevá la cabeza hacia atrás contra la resistencia de la banda, hasta una posición de retracción de mentón, como se muestra. Mantené, relajá y repetí.', 6568),
  ('RETRACCIÓN CON BANDA ELÁSTICA 2', NULL, true, 'fortalecimiento', 'Cervical', 'Estabilización', 'Sentado, colocá una banda elástica por detrás de la cabeza y sostené las puntas adelante de la cara, como se muestra. Empezá con la cabeza adelantada y después retraela (llevala hacia atrás) contra la banda elástica. Asegurate de meter el mentón hacia el pecho durante la fase de retracción.', 39425),
  ('ESTIRAMIENTO DE ESCALENO ANTERIOR/MEDIO', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Inclina la cabeza hacia un costado y después rotala hacia arriba. Mantené el estiramiento. Volvé a la posición inicial y repetí.', 39697),
  ('ESTIRAMIENTO DE ESCALENO ANTERIOR/MEDIO - BRAZO DETRÁS DE LA ESPALDA', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Colocá el brazo detrás de la espalda. Después, inclina la cabeza hacia un costado y rotala hacia arriba. Mantené el estiramiento. Volvé a la posición inicial y repetí. Levantá el mentón para intensificar el estiramiento.', 39690),
  ('ESTIRAMIENTO DE ESCALENO ANTERIOR/MEDIO - SOSTENIENDO LA SILLA', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Sentado en una silla, agarrate del asiento con una mano. Después, inclina la cabeza hacia el lado opuesto y rotala hacia arriba. Mantené el estiramiento. Volvé a la posición inicial y repetí. Levantá el mentón para intensificar el estiramiento.', 39694),
  ('RETRACCIÓN DE MENTÓN CERVICAL CON SOBREPRESIÓN', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Colocá la mano sobre el mentón y llevá lentamente la cabeza hacia atrás en una retracción de mentón, de modo que las orejas queden alineadas con los hombros. Mantené, después volvé a la posición inicial y repetí.', 97306),
  ('ROTACIÓN CERVICAL - SNAG', NULL, true, 'pasivo', 'Cervical', 'Estiramientos', 'Acostado boca arriba, colocá una funda de almohada o toalla alrededor del cuello, de modo que una punta quede sobre el pecho/abdomen y la otra rodee la parte posterior del cuello y cruce sobre el pómulo, sostenida por la otra mano. Con la mano de arriba tirá suavemente de la funda para asistir la rotación del cuello.', 81657),
  ('INCLINACIÓN LATERAL CERVICAL - ESTIRAMIENTO', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Empezá con la cabeza derecha y en buena postura. Inclina la cabeza hacia un costado hasta sentir un estiramiento suave en el lado que se elonga. Mantené y después volvé a la posición inicial. (Asegurate de mantener los ojos y la nariz apuntando al frente todo el tiempo).', 163149),
  ('ESTIRAMIENTO DE ROTACIÓN CERVICAL CON TOALLA', NULL, true, 'pasivo', 'Cervical', 'Estiramientos', 'Sostené las puntas de una toalla de baño chica doblada y pasala alrededor de la cabeza y el cuello, como se muestra. Ubicá la toalla sobre la cara evitando hacer presión sobre la mandíbula: la presión debe quedar sobre el lateral de la cara/pómulo. Usá el brazo de abajo para fijar la toalla en su lugar. Con el brazo de arriba tirá de la toalla para generar un estiramiento rotacional suave del cuello. Mantené, después volvé a la posición inicial y repetí.', 46068),
  ('RETRACCIÓN DE MENTÓN CON ELEVACIÓN DE CABEZA - DECÚBITO DORSAL', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Acostado boca arriba, meté el mentón hacia el pecho y mantené esa posición. Después levantá la cabeza unos centímetros, bajala de nuevo y repetí. Mantené el mentón metido mientras subís y bajás la cabeza.', 97625),
  ('ESTIRAMIENTO DE TRAPECIO SUPERIOR SENTADO CON PIERNAS CRUZADAS - MANO DETRÁS DE LA ESPALDA Y SOBRE LA CABEZA', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Sentate con las piernas cruzadas y empezá retrayendo la cabeza hacia atrás en una posición de retracción de mentón. Después, colocá una mano detrás de la espalda y con la otra tirá suavemente de la cabeza hacia el lado opuesto. Mantené, volvé a la posición inicial y repetí.', 160181),
  ('ESTIRAMIENTO DE FLEXORES PROFUNDOS ANTERIORES DEL CUELLO', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Empezá con la cabeza en posición neutra, después inclinala hacia arriba, seguí con una inclinación lateral y finalmente rotá hacia el mismo lado y mantené. Mantené los dientes superiores e inferiores en contacto durante el estiramiento. Deberías sentir el estiramiento en la parte anterior/lateral del cuello, del lado opuesto al que rotás.', 39445),
  ('GERIATRÍA - ESTIRAMIENTO DE TRAPECIO SUPERIOR/INCLINACIÓN LATERAL CERVICAL - MANO DETRÁS DE LA ESPALDA', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Empezá colocando una mano detrás de la espalda, con la cabeza en posición neutra. Inclina suavemente la cabeza hacia el lado contrario al del brazo que está atrás. Si no podés llevar el brazo atrás, simplemente inclina la cabeza para el estiramiento sin poner el brazo atrás. Mantené y después volvé a la posición inicial y repetí.', 125320),
  ('ESTIRAMIENTO DEL ELEVADOR DE LA ESCÁPULA - TOMANDO LA MUÑECA', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Agarrate el brazo del lado afectado y tirá suavemente hacia el lado opuesto por delante del cuerpo. Después, inclina la cabeza hacia abajo y hacia el costado, mirando en dirección contraria al lado afectado, hasta sentir el estiramiento.', 366),
  ('ESTIRAMIENTO DEL ELEVADOR DE LA ESCÁPULA - MANO DETRÁS DE LA ESPALDA', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Colocá el brazo del lado afectado detrás de la espalda y después inclina la cabeza hacia un costado, rotala hacia ese lado y llevala hacia abajo, en dirección al lado opuesto, como si miraras el bolsillo contrario. Deberías sentir un estiramiento suave en el costado y la parte posterior del cuello.', 97308),
  ('ESTIRAMIENTO DE ESCALENO POSTERIOR', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Inclina la cabeza hacia un costado y después rotala hacia abajo. Mantené el estiramiento. Volvé a la posición inicial y repetí.', 39696),
  ('ESTIRAMIENTO DE ESCALENO POSTERIOR - BRAZO DETRÁS DE LA ESPALDA', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Colocá el brazo detrás de la espalda. Después, inclina la cabeza hacia un costado y rotala hacia abajo. Mantené el estiramiento. Volvé a la posición inicial y repetí.', 39688),
  ('ESTIRAMIENTO DE ESCALENO POSTERIOR - SOSTENIENDO LA SILLA', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Sentado en una silla, agarrate del asiento con una mano. Después, inclina la cabeza hacia el lado opuesto y rotala hacia abajo. Mantené el estiramiento. Volvé a la posición inicial y repetí.', 39695),
  ('ESTIRAMIENTO ROTACIONAL CON SOBREPRESIÓN', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Girá la cabeza hacia un lado todo lo que puedas y después usá la mano del mismo lado para ayudar a girarla un poco más, logrando un estiramiento suave.', 6160),
  ('ESTIRAMIENTO DE ESCALENOS - UNA MANO', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Colocá la mano sobre el esternón. Después, inclina la cabeza hacia arriba y hacia el lado contrario al afectado, hasta sentir un estiramiento suave en la parte anterior y lateral del cuello.', 97307),
  ('ESTIRAMIENTO SUBOCCIPITAL - 2 DEDOS', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Llevá suavemente el mentón hacia abajo, en dirección al pecho, mientras los dedos ayudan a agregar estiramiento en la parte posterior de la cabeza.', 374),
  ('ESTIRAMIENTO DE TRAPECIO SUPERIOR - MANO DETRÁS DE LA ESPALDA', NULL, true, 'activo', 'Cervical', 'Estiramientos', 'Colocá el brazo detrás de la espalda. Después, inclina la cabeza hacia un costado. Mantené el estiramiento. Volvé a la posición inicial y repetí.', 39693),
  ('POLEA - EXTENSIONES DE TRÍCEPS CON SOGA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Colocá la polea en posición alta. Sostené las puntas de la soga con ambas manos y con los codos flexionados. Tirá de la soga hacia abajo hasta estirar completamente los codos. Volvé a la posición inicial y repetí. Mantené los codos pegados al cuerpo todo el tiempo.', 140458),
  ('POLEA - REMO NEUTRO DE PIE - POLEA SIMPLE', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Colocá la polea en posición media. Parate en posición de estocada. Sostené las manijas del sistema de poleas con los brazos extendidos adelante del cuerpo. Tirá de las poleas hacia atrás dejando que los codos se flexionen y las muñecas se extiendan levemente. Volvé a la posición inicial estirando los codos. Repetí. Los omóplatos deben quedar retraídos hacia abajo y atrás. Mantené los codos cerca del cuerpo.', 140459),
  ('ESTIRAMIENTO EN EL MARCO DE LA PUERTA', NULL, true, 'activo', 'Hombro', NULL, 'Parado en el vano de una puerta, apoyá los brazos sobre el marco y adelantá un pie a través de la puerta, como se muestra. Después, flexioná la rodilla adelantada hasta sentir un estiramiento en la parte anterior del pecho y/o los hombros. Los brazos deben quedar horizontales al piso y los antebrazos apoyados sobre el marco. NOTA: la intensidad del estiramiento la controlás con las piernas, flexionando o estirando la rodilla que pasa por la puerta.', 6281),
  ('BANDA ELÁSTICA - DIAGONAL DE HOMBRO - FLEXIÓN Y ABDUCCIÓN - AUTOFIJADA', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', NULL, 'Empezá sosteniendo una banda elástica al costado del cuerpo con el brazo sano para fijarla. Después, con el brazo afectado, llevá la otra punta de la banda hacia arriba y hacia el lado opuesto, como se muestra. Bajá y repetí.', 6996),
  ('ABDUCCIÓN DE HOMBRO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Hacé un nudo en la punta de una banda elástica, colocala a la altura de la rodilla del otro lado de una puerta y cerrá la puerta sobre ella. Parate al costado de la puerta y sostené la otra punta de la banda al costado del cuerpo. Después, llevá el brazo hacia arriba y hacia el costado. Bajá y repetí. Mantené el codo estirado y el pulgar apuntando hacia arriba todo el tiempo.', 200),
  ('ADUCCIÓN DE HOMBRO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Hacé un nudo en la punta de una banda elástica, colocala a la altura de la cabeza del otro lado de una puerta y cerrá la puerta sobre ella. Parate al costado de la puerta y sostené la otra punta de la banda arriba y hacia el costado, como se muestra. Después, llevá el brazo hacia abajo y hacia el costado del cuerpo. Volvé a la posición inicial y repetí. Mantené el codo estirado y la palma mirando hacia el costado del cuerpo todo el tiempo.', 201),
  ('EXTENSIÓN DE HOMBRO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Hacé un nudo en la punta de una banda elástica, colocala en una posición alta del otro lado de una puerta y cerrá la puerta sobre ella. Sostené las puntas de la banda con los codos estirados y después tirá de la banda hacia abajo, hacia el costado del cuerpo. Apretá el omóplato hacia abajo y hacia atrás durante el movimiento. Volvé a la posición inicial y repetí.', 210),
  ('FLEXIÓN DE HOMBRO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Hacé un nudo en la punta de una banda elástica, colocala a la altura de la rodilla del otro lado de una puerta y cerrá la puerta sobre ella. Parate de espaldas a la puerta y sostené la punta de la banda con el codo completamente estirado. Tirá de la banda hacia adelante y hacia arriba por delante del cuerpo. Volvé a la posición inicial y repetí.', 211),
  ('VENDAJE ELÁSTICO - SOPORTE PARA DOLOR ACROMIOCLAVICULAR DE HOMBRO', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73847),
  ('VENDAJE ELÁSTICO - TÉCNICA DE ASTERISCO - MANEJO DEL DOLOR', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73824),
  ('VENDAJE ELÁSTICO - CLAVÍCULA', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75016),
  ('VENDAJE ELÁSTICO - DRENAJE DE LÍQUIDOS', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73845),
  ('VENDAJE ELÁSTICO - DOLOR CERVICAL BAJO', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73846),
  ('VENDAJE ELÁSTICO - SOPORTE DE ESPALDA MEDIA Y ALTA - EN X', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73841),
  ('VENDAJE ELÁSTICO - SOPORTE POSTURAL Y ESTABILIDAD', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73825),
  ('VENDAJE ELÁSTICO - HOMBRO', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75010),
  ('VENDAJE ELÁSTICO - SOPORTE DE HOMBRO', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73828),
  ('VENDAJE ELÁSTICO - SOPORTE DE HOMBRO', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73830),
  ('RODILLO DE ESPUMA - PECHO', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Empezá acostado boca abajo con el rodillo de espuma debajo de la parte superior del brazo y del pecho. Después, ayudándote con el otro brazo y las piernas, rodá hacia adelante y hacia atrás sobre esa zona.', 494),
  ('RODILLO DE ESPUMA - DORSALES', NULL, true, 'sin_clasificar', 'Hombro', NULL, 'Empezá acostado de costado con el rodillo de espuma debajo de la parte superior del brazo y de la espalda. Después, ayudándote con el otro brazo y las piernas, rodá hacia adelante y hacia atrás sobre esa zona.', 495),
  ('ESTIRAMIENTO DE PECTORAL MENOR CON RODILLO DE ESPUMA', NULL, true, 'activo', 'Hombro', NULL, 'Acostate sobre un rodillo de espuma y agarrate una muñeca, apoyada sobre el abdomen. Después, juntá los omóplatos mientras dejás caer los hombros hacia el piso, como se muestra. Mantené para lograr un estiramiento suave en el pecho.', 28004),
  ('PESO LIBRE - FLEXIÓN ALTERNADA EN ROTACIÓN NEUTRA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Sostené una pesa en cada mano, con los codos estirados y los brazos al costado del cuerpo. Las palmas deben mirar hacia adentro, hacia el costado del cuerpo. Después, elevá lentamente uno de los brazos por delante del cuerpo. Bajá a la posición inicial y repetí del otro lado. Alterná los lados en cada repetición. No dejes que el hombro se encoja hacia arriba, salvo que te hayan indicado pasar por encima de la altura del hombro.', 35138),
  ('PESO LIBRE - ABDUCCIÓN BILATERAL EN NEUTRO - ELEVACIÓN LATERAL', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Sosteniendo una mancuerna en cada mano y con los codos estirados, elevá los brazos desde el costado con las palmas mirando hacia abajo. Bajá y repetí. No dejes que el hombro se encoja hacia arriba y no pases por encima de la altura del hombro.', 35137),
  ('PESO LIBRE - ELEVACIÓN EN PLANO ESCAPULAR BILATERAL', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Sostené una pesa en cada mano y elevá ambos brazos desde el costado en dirección adelante y lateral. Los codos deben estar estirados y el movimiento se hace en el plano de la escápula, es decir, a unos 45 grados hacia el costado, como se muestra. No dejes que el hombro se encoja hacia arriba, salvo que te hayan indicado pasar por encima de la altura del hombro.', 35139),
  ('PESO LIBRE - PRESS DE PECHO', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Acostate boca arriba con los codos flexionados. Después, elevá lentamente los brazos hacia el techo, estirando los codos por encima de la cabeza.', 219),
  ('PESO LIBRE - ROTACIÓN EXTERNA - RE', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Acostate de costado y sostené una pesa con el codo flexionado y apoyado sobre el cuerpo. Colocá una toalla chica enrollada entre el brazo y el tronco. Después, llevá el antebrazo y la mano desde el piso hacia el techo, como se muestra. Bajá y repetí.', 220),
  ('FLEXIÓN CON PESO LIBRE EN ROTACIÓN NEUTRA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Empezá con los brazos al costado del cuerpo. Sosteniendo una pesa con la palma mirando hacia el costado y el codo estirado, elevá los brazos hacia adelante, como se muestra, después volvé a la posición inicial y repetí.', 222),
  ('ELEVACIÓN EN PLANO ESCAPULAR CON PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Elevá lentamente el brazo desde el costado en dirección adelante y lateral. Los codos deben estar estirados y el movimiento debe hacerse en el plano de la escápula, o sea a unos 45 grados hacia el costado.', 8094),
  ('DISCOS DESLIZANTES - FLEXIÓN DE BRAZOS MODIFICADA CON BRAZOS ALTERNADOS', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Empezá en posición de flexión de brazos modificada, con un disco deslizante bajo cada mano, los codos estirados y apoyado sobre las rodillas. Mantené la columna recta todo el tiempo. Deslizá una mano con el disco hacia adelante mientras el otro codo se flexiona para bajar el pecho hacia el piso. Volvé a la posición inicial y repetí del otro lado.', 43354),
  ('DISCOS DESLIZANTES - FLEXIONES DE BRAZOS', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Empezá en posición de flexión de brazos modificada, con un disco deslizante bajo cada mano, los codos estirados y apoyado sobre las rodillas. Mantené la columna recta todo el tiempo. Deslizá ambos discos y manos hacia los costados mientras flexionás los codos y bajás el pecho hacia el piso. Después empujá para volver a subir mientras deslizás los discos otra vez hacia el centro. Repetí.', 43355),
  ('DISCOS DESLIZANTES - CAMINATA DE CARRETILLA INVERTIDA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Colocá un disco deslizante bajo cada talón, sentado con las piernas estiradas. Después, elevá la cola de modo que solo las manos y los talones sostengan el peso del cuerpo. Luego caminá con las manos hacia atrás, dejando que los pies se deslicen en la misma dirección. Después de algunos pasos hacia atrás, cambiá de dirección y caminá con las manos de vuelta a la posición inicial.', 43373),
  ('DISCOS DESLIZANTES - CAMINATA DE CARRETILLA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Colocá un disco deslizante bajo cada pie, en posición de plancha con manos y pies apoyados en el piso, boca abajo. Después, caminá hacia adelante con las manos dejando que los pies se deslicen hacia adelante. Después de algunos pasos, caminá con las manos de vuelta a la posición inicial.', 43369),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA CON TOALLA - RI CON TOALLA', NULL, true, 'activo_asistido', 'Hombro', NULL, 'Con la ayuda de una toalla, subí suavemente el brazo afectado por detrás de la espalda. Mantené el estiramiento, después bajá y repetí.', 237),
  ('ISOMÉTRICO DE ABDUCCIÓN DE HOMBRO - PELOTA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Parate al lado de una pared con el brazo al costado del cuerpo y el codo flexionado a unos 90 grados. Colocá una pelota entre el codo y la pared. Empujá suavemente el codo hacia el costado contra la pelota y mantené. Relajá y repetí.', 69902),
  ('ISOMÉTRICO DE ADUCCIÓN DE HOMBRO - PELOTA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Colocá una pelota entre el codo y el costado del cuerpo. Apretá suavemente la pelota contra el cuerpo y mantené. Relajá y repetí.', 69904),
  ('ISOMÉTRICO DE EXTENSIÓN DE HOMBRO - PELOTA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Parate al lado de una pared con el brazo al costado del cuerpo y el codo flexionado a unos 90 grados. Colocá una pelota entre la parte posterior del codo y la pared. Empujá suavemente el codo hacia atrás contra la pelota y mantené. Relajá y repetí.', 69907),
  ('ISOMÉTRICO DE ROTACIÓN EXTERNA DE HOMBRO - PELOTA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Parate al lado de una pared con el brazo al costado del cuerpo y el codo flexionado a unos 90 grados. Colocá una pelota entre el dorso de la mano y la pared. Empujá suavemente la mano hacia afuera contra la pelota y mantené. Relajá y repetí.', 69905),
  ('ISOMÉTRICO DE FLEXIÓN DE HOMBRO - PELOTA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Parate frente a una pared con el brazo al costado del cuerpo y el codo flexionado a unos 90 grados. Cerrá el puño y colocá una pelota entre el puño y la pared. Empujá suavemente el puño contra la pelota y mantené. Relajá y repetí.', 69910),
  ('ISOMÉTRICO DE ROTACIÓN INTERNA DE HOMBRO - PELOTA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Parate en el vano de una puerta o en una esquina, con el brazo al costado del cuerpo y el codo flexionado a unos 90 grados. Colocá una pelota entre la palma de la mano y la pared. Empujá suavemente la mano hacia adentro contra la pelota y mantené. Relajá y repetí.', 69913),
  ('KETTLEBELL - EXTENSIÓN DE TRÍCEPS', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Empezá acostado boca arriba sosteniendo una kettlebell con el codo extendido hacia el techo. Después, flexioná el codo para bajar la pesa hacia el costado de la cabeza. Luego volvé a subirla a la posición inicial. Repetí.', 79154),
  ('KETTLEBELL ALREDEDOR DE LA CINTURA - ENTRADA EN CALOR/VUELTA A LA CALMA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Pasá la kettlebell de una mano a la otra mientras la movés alrededor de la cintura. Es un ejercicio de entrada en calor o vuelta a la calma con kettlebell.', 28599),
  ('KETTLEBELL BÍCEPS', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Sosteniendo una kettlebell, flexioná el codo y levantá la pesa, como se muestra.', 28600),
  ('HALO CON KETTLEBELL (ENTRADA EN CALOR POR ENCIMA DE LA CABEZA)', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Sostené una kettlebell invertida de las manijas, como se muestra. Después, movela alrededor de la cabeza. Después de algunas vueltas, invertí la dirección.', 28601),
  ('PRESS DE HOMBROS CON KETTLEBELL - BILATERAL', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Sostené una kettlebell como se muestra y después levantala por encima de la cabeza, hacia el techo.', 28606),
  ('PLANCHA CON REMO ALTERNADO CON KETTLEBELL', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Empezá en posición de plancha completa, sobre manos y puntas de pies. Después, agarrá una kettlebell y tirá de ella hacia arriba flexionando el codo. Apoyala de nuevo en el piso y cambiá de brazo. Repetí.', 28621),
  ('PRESS CON KETTLEBELL', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Sostené una kettlebell en posición acunada. Después, empujala hacia arriba, hacia el techo, extendiendo completamente el codo.', 28602),
  ('FLEXIÓN DE HOMBRO CON KETTLEBELL', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Balanceá una kettlebell con un brazo desde entre las piernas hasta por encima de la cabeza, manteniendo el codo relativamente estirado todo el tiempo. Al llegar arriba, la kettlebell debe girar y quedar apoyada sobre el dorso de la muñeca.', 28613),
  ('TRÍCEPS CON KETTLEBELL', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Extendé el codo como se muestra mientras sostenés una kettlebell. Mantené el brazo apuntando hacia arriba y flexioná y estirá solamente el codo.', 28604),
  ('REMO VERTICAL CON KETTLEBELL', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Empezá sosteniendo una kettlebell con ambas manos a la altura de la cintura. Después, levantala hasta la altura del pecho flexionando los codos.', 28628),
  ('REMO VERTICAL CON KETTLEBELL', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Sostené una kettlebell a la altura de la cintura y levantala hasta la altura del pecho, como se muestra. Bajala y repetí.', 28608),
  ('DESLIZAMIENTO DEL NERVIO MEDIANO - A', NULL, true, 'activo', 'Hombro', NULL, 'Empezá con el brazo colgando al costado del cuerpo, con el codo estirado y la palma mirando hacia adelante. Después, flexioná y extendé la muñeca hacia adelante y hacia atrás. Con la otra mano controlá que el hombro se mantenga bajo y hacia atrás todo el tiempo.', 5884),
  ('DESLIZAMIENTO DEL NERVIO MEDIANO - B', NULL, true, 'activo', 'Hombro', NULL, 'Empezá con el brazo colgando al costado del cuerpo, con el codo estirado y la palma mirando hacia adelante. Después, extendé la muñeca hacia atrás mientras inclinás la cabeza hacia el brazo que trabajás, como se muestra. Luego flexioná la muñeca hacia adelante mientras inclinás la cabeza hacia el lado contrario. Con la otra mano controlá que el hombro se mantenga bajo y hacia atrás todo el tiempo.', 5885),
  ('DESLIZAMIENTO DEL NERVIO MEDIANO - C', NULL, true, 'activo', 'Hombro', NULL, 'Empezá con el brazo extendido hacia el costado, con el codo estirado y la palma mirando hacia arriba. Después, flexioná y extendé la muñeca hacia arriba y hacia abajo. Con la otra mano controlá que el hombro se mantenga bajo y hacia atrás todo el tiempo.', 5898),
  ('DESLIZAMIENTO DEL NERVIO MEDIANO - D', NULL, true, 'activo', 'Hombro', NULL, 'Empezá con el brazo elevado y extendido hacia el costado, con el codo estirado, como se muestra. La palma debe mirar hacia arriba. Después, extendé la muñeca hacia arriba mientras inclinás la cabeza hacia el lado contrario al brazo que trabajás, como se muestra. Luego flexioná la muñeca hacia abajo mientras inclinás la cabeza hacia ese brazo.', 5899),
  ('ESTIRAMIENTO DE PECTORALES EN ESQUINA', NULL, true, 'activo', 'Hombro', NULL, 'Parado en la esquina de una pared, apoyá los brazos sobre las paredes con los codos flexionados, de modo que los brazos queden horizontales y los antebrazos apunten hacia arriba, como se muestra. Dá un paso adelante hacia la esquina. Flexioná la rodilla adelantada hasta sentir un estiramiento en la parte anterior del pecho y/o los hombros. NOTA: la intensidad del estiramiento la controlás con las piernas, flexionando o estirando la rodilla adelantada.', 6513),
  ('ESTIRAMIENTO DE PECTORALES EN ESQUINA - EN W', NULL, true, 'activo', 'Hombro', NULL, 'Parado en la esquina de una pared, apoyá los brazos sobre las paredes formando una W, con los codos flexionados y apuntando hacia el piso, como se muestra. Dá un paso adelante hacia la esquina. Flexioná la rodilla adelantada hasta sentir un estiramiento en la parte anterior del pecho y/o los hombros. NOTA: la intensidad del estiramiento la controlás con las piernas, flexionando o estirando la rodilla adelantada.', 6547),
  ('ESTIRAMIENTO DE PECTORALES EN LA PUERTA - ALTO', NULL, true, 'activo', 'Hombro', NULL, 'Parado en el vano de una puerta, apoyá los brazos arriba sobre el marco e inclinate hacia adelante hasta sentir un estiramiento en la parte anterior del pecho y/o los hombros. Los brazos deben quedar apoyados hacia arriba a lo largo del marco. NOTA: la intensidad del estiramiento la controlás con las piernas, flexionando o estirando la rodilla que pasa por la puerta.', 6282),
  ('ESTIRAMIENTO DE PECTORALES EN LA PUERTA - BAJO', NULL, true, 'activo', 'Hombro', NULL, 'Parado en el vano de una puerta, apoyá el brazo hacia abajo sobre el marco e inclinate hacia adelante hasta sentir un estiramiento en la parte anterior del pecho y/o el hombro. El brazo debe apuntar hacia el piso a lo largo del marco. NOTA: la intensidad del estiramiento la controlás con las piernas, flexionando o estirando la rodilla que pasa por la puerta.', 6283),
  ('ESTIRAMIENTO DE PECTORALES EN LA PUERTA - UN SOLO BRAZO', NULL, true, 'activo', 'Hombro', NULL, 'Parado en el vano de una puerta, apoyá el brazo sobre el marco y dá un paso adelante a través de la puerta. Después, flexioná la rodilla adelantada hasta sentir un estiramiento en la parte anterior del pecho y/o el hombro. El brazo debe quedar horizontal al piso y el antebrazo apoyado a lo largo del marco. NOTA: la intensidad del estiramiento la controlás con las piernas, flexionando o estirando la rodilla que pasa por la puerta.', 6284),
  ('CÍRCULOS PENDULARES CON PESO', NULL, true, 'pasivo', 'Hombro', NULL, 'Apoyá una mano sobre una superficie estable, como una mesa o mesada, e inclinate hacia adelante desde la cintura. Sostené una pesa chica o una lata con el brazo afectado y dejalo colgar hacia el piso. Relajá completamente ese brazo: el único músculo activo debe ser el que agarra la pesa. Movés el peso del cuerpo en círculos para que el brazo lesionado oscile libremente en sentido horario. Hacé varias vueltas y después cambiá de dirección en sentido antihorario. El brazo lesionado debe estar completamente relajado todo el tiempo.', 54252),
  ('PÉNDULO ADELANTE Y ATRÁS - CODMAN', NULL, true, 'pasivo', 'Hombro', NULL, 'Movés el peso del cuerpo hacia adelante y hacia atrás para que el brazo lesionado oscile libremente hacia adelante y hacia atrás. El brazo lesionado debe estar completamente relajado.', 163),
  ('PÉNDULO ADELANTE Y ATRÁS CON PESO', NULL, true, 'pasivo', 'Hombro', NULL, 'Apoyá una mano sobre una superficie estable, como una mesa o mesada, e inclinate hacia adelante desde la cintura. Sostené una pesa chica o una lata con el brazo afectado y dejalo colgar hacia el piso. Relajá completamente ese brazo: el único músculo activo debe ser el que agarra la pesa. Movés el peso del cuerpo hacia adelante y hacia atrás para que el brazo lesionado oscile libremente. El brazo lesionado debe estar completamente relajado todo el tiempo.', 54253),
  ('PÉNDULO LATERAL - CODMAN', NULL, true, 'pasivo', 'Hombro', NULL, 'Movés el peso del cuerpo de lado a lado para que el brazo lesionado oscile libremente hacia los costados. El brazo lesionado debe estar completamente relajado.', 167),
  ('EXTENSIÓN EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Hombro', NULL, 'Acostado boca abajo con los codos estirados, elevá lentamente los brazos hacia arriba manteniendo los codos estirados.', 187),
  ('REMO EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Acostado boca abajo con los codos estirados, elevá lentamente los brazos hacia arriba flexionando los codos.', 189),
  ('T EN DECÚBITO VENTRAL - BILATERAL - PULGARES ARRIBA', NULL, true, 'activo', 'Hombro', NULL, 'Acostate boca abajo con los codos estirados y los brazos abiertos hacia los costados. Después, fijá la escápula llevándola hacia la columna y hacia abajo, en dirección a los pies. Luego elevá lentamente los brazos hacia el techo, manteniendo los codos estirados todo el tiempo, como se muestra. Los pulgares deben apuntar hacia arriba mientras subís los brazos.', 19782),
  ('DESLIZAMIENTO DEL NERVIO RADIAL - A', NULL, true, 'activo', 'Hombro', NULL, 'Empezá con el brazo colgando al costado del cuerpo, con el codo estirado y la palma mirando hacia atrás. Después, flexioná y extendé la muñeca hacia adelante y hacia atrás. Con la otra mano controlá que el hombro se mantenga bajo y hacia atrás todo el tiempo.', 5886),
  ('DESLIZAMIENTO DEL NERVIO RADIAL - B', NULL, true, 'activo', 'Hombro', NULL, 'Empezá con el brazo colgando al costado del cuerpo, con el codo estirado y la palma mirando hacia atrás. Después, extendé la muñeca hacia atrás mientras inclinás la cabeza hacia el brazo que trabajás, como se muestra. Luego flexioná la muñeca hacia adelante mientras inclinás la cabeza hacia el lado contrario. Con la otra mano controlá que el hombro se mantenga bajo y hacia atrás todo el tiempo.', 5887),
  ('PROTRACCIÓN ESCAPULAR - PESO LIBRE - GOLPES DE SERRATO', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Acostate boca arriba sosteniendo una pesa chica o una lata con el brazo extendido por delante del cuerpo, hacia el techo. Manteniendo el codo estirado, llevá el hombro hacia adelante en dirección al techo (protracción) y después bajá de manera controlada. No dejes que el hombro suba hacia las orejas. Mantené el codo estirado todo el tiempo.', 224),
  ('AUTOMASAJE CON PELOTA - INFRAESPINOSO', NULL, true, 'activo', 'Hombro', NULL, 'Parate con la espalda a 45 grados respecto de una pared. Colocá la mano sobre el hombro opuesto y ubicá una pelota de masaje entre la pared y la parte blanda del omóplato (músculo infraespinoso), como se muestra. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Podés mantener la presión en un punto o hacer movimientos chicos con el cuerpo para que la pelota ruede hacia arriba y abajo, de lado a lado o en círculos.', 99632),
  ('AUTOMASAJE CON PELOTA - MANÍ - ZONA MEDIA ESCAPULAR - TRAPECIO MEDIO - ROMBOIDES', NULL, true, 'activo', 'Hombro', NULL, 'Parate de espaldas a una pared y colocá una pelota doble de lacrosse (pelota maní) o dos pelotas de tenis/paleta unidas con cinta entre la pared y la zona blanda justo al lado interno del omóplato, en posición vertical. Apoyá la mano sobre el hombro opuesto para llevar la escápula hacia afuera. Recostate contra la pelota para aplicar una presión suave sobre las zonas tensas al lado interno del omóplato. No ruedes sobre zonas óseas. Podés mantener la presión en un punto o mover el cuerpo para que la pelota doble ruede de lado a lado.', 99631),
  ('AUTOMOVILIZACIÓN - DESLIZAMIENTO ANTERIOR - SENTADO', NULL, true, 'activo_asistido', 'Hombro', NULL, 'Apoyá la mano del hombro afectado sobre una mesa detrás tuyo y, con la otra mano, tirá suavemente del brazo hacia adelante.', 226),
  ('AUTOMOVILIZACIÓN - DISTRACCIÓN', NULL, true, 'activo_asistido', 'Hombro', NULL, 'Colocá una toalla chica enrollada debajo del brazo afectado y tirá suavemente de él hacia el lado opuesto.', 199),
  ('AUTOMOVILIZACIÓN - DESLIZAMIENTO INFERIOR - SILLA', NULL, true, 'pasivo; activo_asistido', 'Hombro', NULL, 'Sentado, agarrá el costado del asiento con el brazo afectado e inclinate lentamente hacia el lado contrario hasta sentir un estiramiento suave en el hombro. El hombro afectado debe estar completamente relajado.', 228),
  ('AUTOMOVILIZACIÓN - DESLIZAMIENTO INFERIOR - SOBRE EL RESPALDO', NULL, true, 'pasivo; activo_asistido', 'Hombro', NULL, 'Sentado, dejá que el brazo afectado cuelgue sobre el respaldo de una silla y usá el otro brazo para tirar suavemente del brazo afectado hacia abajo, como se muestra. El brazo afectado debe estar completamente relajado.', 231),
  ('AUTOMOVILIZACIÓN - DESLIZAMIENTO INFERIOR - MESA', NULL, true, 'pasivo; activo_asistido', 'Hombro', NULL, 'Apoyá el codo del hombro afectado sobre una mesa al costado y, con la otra mano, presioná suavemente el brazo hacia abajo. El brazo afectado debe estar completamente relajado.', 5393),
  ('AUTOMOVILIZACIÓN - DESLIZAMIENTO INFERIOR - PARED - EN ABDUCCIÓN', NULL, true, 'activo_asistido', 'Hombro', NULL, 'Apoyá el brazo afectado sobre una pared, hacia el costado. Después, con el brazo sano, empujá el hombro hacia abajo, en dirección al piso.', 232),
  ('AUTOMOVILIZACIÓN - DESLIZAMIENTO INFERIOR - PARED - EN FLEXIÓN', NULL, true, 'activo_asistido', 'Hombro', NULL, 'Apoyá el brazo afectado sobre una pared, por delante tuyo. Después, con el brazo sano, empujá el hombro hacia abajo, en dirección al piso.', 245),
  ('AUTOMOVILIZACIÓN - DESLIZAMIENTO POSTERIOR', NULL, true, 'activo_asistido', 'Hombro', NULL, 'Acostado boca abajo, incorporate apoyándote sobre los codos.', 192),
  ('DESLIZAMIENTO DE SERRATO EN LA PARED', NULL, true, 'activo', 'Hombro', NULL, 'Apoyá los antebrazos y las manos contra una pared, con los codos flexionados y los brazos apuntando hacia el techo. Después, llevá los omóplatos hacia adelante (protracción) y deslizá los brazos hacia arriba por la pared, como se muestra. Volvé a la posición inicial y repetí.', 8253),
  ('DESLIZAMIENTO DE SERRATO EN LA PARED - BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Colocá una banda elástica alrededor de los brazos, a la altura de las muñecas, como se muestra. Después, apoyá los antebrazos y las manos contra una pared, con los codos flexionados y los brazos apuntando hacia el techo. Luego llevá los omóplatos hacia adelante (protracción) y deslizá los brazos hacia arriba por la pared, como se muestra. Volvé a la posición inicial y repetí.', 8252),
  ('HOMBRO - ABDUCCIÓN ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Colocá una toalla chica doblada entre el codo y una pared. Con el codo flexionado a 90 grados, empujá suavemente el codo hacia el costado contra la toalla y la pared. Mantené, relajá y repetí.', 177),
  ('HOMBRO - ADUCCIÓN ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Colocá una toalla chica doblada entre el codo y el costado del cuerpo. Apretá suavemente la toalla. Mantené, relajá y repetí.', 178),
  ('HOMBRO - EXTENSIÓN ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Colocá una toalla chica doblada entre el codo y una pared detrás tuyo. Presioná suavemente el codo hacia atrás contra la pared y la toalla. Mantené, relajá y repetí.', 181),
  ('HOMBRO - ROTACIÓN EXTERNA ISOMÉTRICA - ELEVADO', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Empujá suavemente el dorso de la mano contra una pared, con el brazo elevado a 90 grados y el codo flexionado a 90 grados.', 180),
  ('HOMBRO - ROTACIÓN INTERNA ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Colocá una toalla chica doblada entre la mano y una pared. Presioná suavemente la palma de la mano contra la pared. Mantené el codo flexionado todo el tiempo. Mantené, relajá y repetí.', 533),
  ('HOMBRO - ROTACIÓN INTERNA ISOMÉTRICA - ELEVADO', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Parate cerca de la esquina de una pared o en el vano de una puerta. Elevá el hombro a 90 grados y empujá suavemente la parte anterior de la mano contra la pared, con el codo flexionado y el brazo elevado. Mantené, relajá y repetí.', 183),
  ('FLEXIÓN DE HOMBRO AAROM - UNILATERAL - BASTÓN', NULL, true, 'activo_asistido', 'Hombro', NULL, 'De pie, sostené un bastón con ambos brazos, como se muestra. Elevá el brazo afectado usando el brazo sano para ayudar a empujarlo hacia arriba.', 5894),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA DE HOMBRO - POR DETRÁS DE LA ESPALDA - BASTÓN', NULL, true, 'activo_asistido', 'Hombro', NULL, 'Sosteniendo un bastón por detrás de la espalda, como se muestra, subí lentamente el bastón por la espalda para estirar los hombros. Bajá y repetí.', 10687),
  ('PROM DE HOMBRO - ADUCCIÓN', NULL, true, 'pasivo', 'Hombro', NULL, 'La persona debe estar completamente relajada mientras el cuidador hace todo el trabajo (movilización pasiva) para mover el brazo. Agarrá el brazo y separalo del costado del cuerpo llevándolo hacia la cabeza, si el rango lo permite. Después volvé a la posición inicial y repetí.', 27183),
  ('PROM DE HOMBRO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'pasivo', 'Hombro', NULL, 'La persona debe estar completamente relajada mientras el cuidador hace todo el trabajo (movilización pasiva) para mover el brazo. Agarrá el brazo y elevalo hacia adelante y arriba, por encima de la cabeza, si el rango lo permite. Después bajalo y repetí.', 27176),
  ('PROM DE HOMBRO - ROTACIÓN INTERNA Y EXTERNA', NULL, true, 'pasivo', 'Hombro', NULL, 'La persona debe estar completamente relajada mientras el cuidador hace todo el trabajo (movilización pasiva) para mover el brazo. Sostené el codo separado de la camilla y después rotá el hombro pivoteando sobre el brazo, como se muestra, y repetí.', 27184),
  ('ABDUCCIÓN CON POLEA DE HOMBRO', NULL, true, 'pasivo; activo_asistido', 'Hombro', NULL, 'Con las poleas de puerta y de espaldas a la puerta, tirá lentamente hacia abajo con el brazo sano para que el brazo afectado se eleve hacia el costado sin esfuerzo. El brazo afectado debe estar relajado. El brazo sano hace todo el trabajo.', 5295),
  ('ESTIRAMIENTO EN FLEXIÓN CON POLEA DE HOMBRO', NULL, true, 'pasivo; activo_asistido', 'Hombro', NULL, 'Con las poleas de puerta y de espaldas a la puerta, tirá lentamente hacia abajo con el brazo sano para que el brazo afectado se eleve hacia adelante y arriba sin esfuerzo. El brazo afectado debe estar relajado. El brazo sano hace todo el trabajo.', 5296),
  ('ENCOGIMIENTO DE HOMBROS', NULL, true, 'activo', 'Hombro', NULL, 'Elevá los hombros hacia las orejas, como se muestra. Encogé ambos hombros al mismo tiempo.', 461),
  ('ROTACIÓN EXTERNA EN DECÚBITO LATERAL - RE', NULL, true, 'activo', 'Hombro', NULL, 'Acostate de costado con el codo flexionado y apoyado sobre el cuerpo. Después, llevá el antebrazo desde el piso hacia el techo. Colocá una toalla enrollada debajo del codo si tu profesional te lo indica.', 8450),
  ('ROTACIÓN EXTERNA EN DECÚBITO LATERAL CON TOALLA - RE', NULL, true, 'activo', 'Hombro', NULL, 'Acostate de costado con el codo flexionado a 90 grados. Colocá una toalla enrollada entre el brazo y el costado del cuerpo, como se muestra. Llevá el omóplato hacia atrás y hacia abajo, en dirección a la cola, y mantené esa posición. Después, rotá el brazo desde la zona del abdomen hacia el techo, manteniendo el brazo contra la toalla y el omóplato abajo y atrás todo el tiempo. Bajá el brazo y repetí.', 34145),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA EN DECÚBITO LATERAL - SLEEPER STRETCH', NULL, true, 'activo_asistido', 'Hombro', NULL, 'Empezá acostado de costado con el brazo afectado abajo. Ese brazo debe estar flexionado en el codo, con el antebrazo apuntando hacia el techo, como se muestra. Después, con el brazo sano, llevá suavemente el antebrazo afectado hacia la camilla o la cama para lograr un estiramiento hacia adentro. Mantené, relajá y repetí.', 480),
  ('DESLIZAMIENTO SOBRE LA MESA - ABDUCCIÓN', NULL, true, 'activo', 'Hombro', NULL, 'Sentate en una silla y apoyá el brazo lesionado sobre una mesa. Empezá inclinándote hacia el costado en dirección a la mesa mientras deslizás el brazo hacia afuera, como se muestra. Después volvé a la posición inicial y repetí.', 6847),
  ('DESLIZAMIENTO SOBRE LA MESA - PLANO ESCAPULAR', NULL, true, 'activo', 'Hombro', NULL, 'Sentado en una silla, apoyá el brazo lesionado sobre una mesa. Deslizalo suavemente hacia adelante y hacia el costado inclinándote en esa dirección. Movete en un ángulo de aproximadamente 45 grados y después volvé a la posición inicial y repetí.', 36379),
  ('TRX EN SUSPENSIÓN - REMO', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Sostené las manijas del TRX de frente al anclaje. Parate con los codos flexionados, después inclinate hacia atrás dejando que los codos se estiren. Luego traccioná con los brazos flexionando los codos y llevándolos hacia atrás mientras juntás los omóplatos.', 31419),
  ('TRX EN SUSPENSIÓN - ESTIRAMIENTO EN FLEXIÓN DE HOMBRO', NULL, true, 'activo', 'Hombro', NULL, 'Parate de espaldas al anclaje del TRX. Colocá un pie adelante del otro y flexioná la rodilla adelantada para estirar los brazos por encima de la cabeza. Mantené esta posición para estirar los hombros.', 31413),
  ('TRX EN SUSPENSIÓN - APERTURAS INVERSAS CON BRAZOS SEPARADOS', NULL, true, 'activo', 'Hombro', NULL, 'Sostené las manijas del TRX de frente al anclaje. Inclinate hacia atrás con los brazos extendidos y las palmas enfrentadas. Después, llevá las manijas hacia los costados de modo que un brazo quede por encima de la cabeza y el otro por debajo de la cintura. Durante el movimiento, las palmas pasan de estar enfrentadas a mirar hacia adelante. Volvé a la posición inicial y repetí alternando los lados.', 31418),
  ('TRX EN SUSPENSIÓN - TRÍCEPS', NULL, true, 'activo', 'Hombro', NULL, 'Sostené las manijas del TRX de espaldas al anclaje. Empezá de pie con los brazos extendidos por delante del cuerpo y los codos estirados. Después, flexioná los codos para bajar el cuerpo hacia adelante. Luego volvé a la posición inicial estirando los codos.', 31426),
  ('NERVIO CUBITAL - MÁSCARA', NULL, true, 'activo', 'Hombro', NULL, 'Empezá juntando el pulgar y el dedo índice, como se muestra. Después, girá la mano al revés de modo que los dedos toquen tu mejilla y puedas mirar a través del hueco que formaron los dedos.', 5891),
  ('FLOSSING DEL NERVIO CUBITAL - B', NULL, true, 'activo', 'Hombro', NULL, 'Empezá con el brazo elevado y hacia el costado, con el codo flexionado, como se muestra. La palma debe mirar hacia el costado. Después, flexioná la muñeca hacia vos mientras inclinás la cabeza hacia el brazo que trabajás, como se muestra. Luego llevá la muñeca en sentido contrario mientras inclinás la cabeza hacia el lado opuesto. Con la otra mano controlá que el hombro se mantenga bajo y hacia atrás todo el tiempo.', 5892),
  ('DESLIZAMIENTO DEL NERVIO CUBITAL - A', NULL, true, 'activo', 'Hombro', NULL, 'Empezá con el brazo elevado y hacia el costado, con el codo flexionado, como se muestra. La palma debe mirar hacia el costado. Después, movés la muñeca alejándola y acercándola hacia vos, como se muestra. Con la otra mano controlá que el hombro se mantenga bajo y hacia atrás todo el tiempo.', 5890),
  ('FLEXIONES DE BRAZOS EN LA PARED', NULL, true, 'fortalecimiento', 'Hombro', NULL, 'Parado frente a una pared, extendé los brazos hacia adelante con los codos estirados de modo que las manos apenas lleguen a la pared. Después, flexioná lentamente los codos para acercar el pecho a la pared. Mantené los pies apoyados en el piso todo el tiempo.', 239),
  ('CAMINATA DE DEDOS EN LA PARED', NULL, true, 'activo', 'Hombro', NULL, 'Apoyá la mano afectada sobre la pared con la palma contra la pared. Después, caminá con los dedos hacia arriba por la pared, por encima de la cabeza. Por último, deslizá la mano hacia abajo por la pared hasta la posición inicial.', 194),
  ('ROTACIÓN EXTERNA CON BASTÓN - RE EN DECÚBITO DORSAL', NULL, true, 'pasivo; activo_asistido', 'Hombro', NULL, 'Acostate boca arriba sosteniendo un bastón con ambas manos. Del lado afectado, colocá una toalla chica enrollada o una almohada debajo del codo. Mantené el codo flexionado unos 90 grados y el brazo separado del cuerpo unos 30-45 grados. Con el otro brazo, empujá el bastón para rotar el brazo afectado hacia atrás hasta sentir el estiramiento. Mantené, volvé a la posición inicial y repetí.', 235),
  ('ROTACIÓN CON BASTÓN - RI Y RE DE PIE', NULL, true, 'pasivo; activo_asistido', 'Hombro', NULL, 'De pie, sostené un bastón con ambas manos manteniendo los codos flexionados. Movés los brazos y el bastón de lado a lado. El brazo afectado debe estar parcialmente relajado mientras el brazo sano hace la mayor parte del esfuerzo.', 170),
  ('EXTENSIÓN DE HOMBRO CON BASTÓN - BILATERAL', NULL, true, 'activo_asistido', 'Hombro', NULL, 'De pie, sostené un bastón por detrás de la espalda con ambos brazos y después extendé los brazos hacia atrás, como se muestra. Volvé a la posición inicial y repetí.', 234),
  ('PRESS DE PECHO CON BASTÓN - DECÚBITO DORSAL', NULL, true, 'activo_asistido', 'Hombro', NULL, 'Empezá acostado boca arriba sosteniendo un bastón con los codos apoyados al costado del cuerpo. Después, empujá lentamente el bastón hacia arriba, hacia el techo, hasta estirar completamente los codos. Bajá y repetí.', 479),
  ('POLEA - EXTENSIÓN Y ADUCCIÓN - DIAGONAL DE HOMBRO - D2', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones', 'Colocá la polea en posición alta. Sostené la manija con el brazo separado del costado del cuerpo. Tirá del brazo hacia abajo y hacia el lado opuesto del cuerpo, como se muestra. Volvé a subir el brazo a la posición inicial y repetí. La mano arranca con el pulgar hacia arriba (posición de hacer dedo) y termina con el pulgar hacia abajo, como si metieras la mano en el bolsillo.', 140195),
  ('POLEA - ABDUCCIÓN DE HOMBRO', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones', 'Colocá las poleas en posición baja. Sosteniendo la manija con el pulgar hacia arriba, elevá el brazo hacia el costado, como se muestra. Bajá a la posición inicial y repetí. Mantené el codo estirado todo el tiempo.', 140192),
  ('POLEA - ADUCCIÓN DE HOMBRO', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones', 'Colocá la polea en posición alta. Sostené la manija y empezá con el brazo separado del costado del cuerpo. Tirá del brazo hacia abajo, hacia el costado del cuerpo, como se muestra. Volvé a subir el brazo a la posición inicial y repetí. Mantené el codo estirado todo el tiempo.', 140193),
  ('POLEA - FLEXIÓN DE HOMBRO', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones', 'Colocá la polea en posición baja. Sostené la manija con el brazo hacia abajo, al costado del cuerpo. Elevá el brazo hacia adelante manteniendo el codo estirado. Bajá y repetí.', 140452),
  ('ABDUCCIÓN CON BANDA ELÁSTICA - AUTOFIJADA', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Hombro en 6 direcciones; Banda elástica', 'Fijá una punta de la banda elástica adelante tuyo, sobre la pierna, con el brazo sano. Después, tirá de la banda hacia arriba y hacia el costado con el brazo afectado, manteniendo el codo estirado todo el tiempo.', 20673),
  ('SILLA DE RUEDAS - ABDUCCIÓN CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones; Banda elástica', 'Sujetá una punta de la banda elástica al pie o a una parte lateral de la silla de ruedas y sostené la otra punta. Llevá el brazo hacia arriba desde el costado del cuerpo manteniendo el codo estirado todo el tiempo. Bajá el brazo y repetí.', 104694),
  ('ABDUCCIÓN/PLANO ESCAPULAR CON BANDA ELÁSTICA - AUTOFIJADA', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones; Banda elástica; Estabilización', 'Sostené y fijá una punta de la banda elástica sobre el muslo y agarrá la otra punta con el brazo afectado. Con ese brazo, tirá de la banda hacia arriba y hacia el costado, en dirección a por encima de la cabeza, como se muestra. Bajá y repetí. Mantené el codo estirado todo el tiempo.', 125293),
  ('ROTACIÓN EXTERNA - SENTADO - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones; Peso libre', 'Sentado, apoyá el pie sobre la cama o el sillón y colocá el codo sobre la rodilla. El antebrazo debe apuntar hacia el techo. Después, bajá lentamente la mano hacia el piso dejando que el hombro rote hacia adentro y hacia abajo, como se muestra.', 478),
  ('POLEA - DIAGONAL DE HOMBRO - FLEXIÓN Y ADUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones; Máquinas y poleas', 'Colocá la polea en posición baja. Parate al costado de la polea sosteniendo la manija con el brazo abajo y hacia afuera. Tirá del cable hacia arriba, en dirección al hombro opuesto. Bajá a la posición inicial y repetí. La mano arranca con el pulgar hacia atrás y termina con el pulgar hacia arriba.', 140194),
  ('POLEA - FLEXIÓN BILATERAL DE HOMBRO', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones; Máquinas y poleas; Estabilización', 'Colocá la polea en posición baja. Sosteniendo las manijas con los brazos colgando al costado del cuerpo, elevá los brazos hacia adelante manteniendo los codos estirados. Bajá y repetí.', 140451),
  ('POLEA - EXTENSIÓN DE HOMBRO', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones; Estabilización', 'Colocá la polea en posición alta. Sostené la manija y tirá del cable hacia abajo y hacia atrás, hacia el costado del cuerpo. Volvé a subir el brazo a la posición inicial y repetí.', 140198),
  ('POLEA - ROTACIÓN EXTERNA DE HOMBRO - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones; Estabilización', 'Colocá la polea a la altura del codo. Sostené la manija y flexioná el codo a 90 grados, con el codo pegado al cuerpo. Colocá una toalla chica enrollada entre el brazo y el cuerpo. Empezá con la mano hacia afuera y después tirá de la manija hacia el abdomen. Volvé a la posición inicial y repetí.', 140197),
  ('POLEA - ROTACIÓN INTERNA DE HOMBRO - RI', NULL, true, 'fortalecimiento', 'Hombro', 'Hombro en 6 direcciones; Estabilización', 'Colocá la polea a la altura del codo. Sostené la manija con el codo flexionado a 90 grados y pegado al cuerpo. Colocá una toalla chica enrollada entre el brazo y el cuerpo. Empezá con la mano hacia afuera y después tirá del cable hacia el abdomen. Volvé a la posición inicial y repetí.', 140199),
  ('AAROM DE FLEXIÓN ASISTIDA', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo)', 'Sentado o de pie con el brazo al costado del cuerpo, agarrá el brazo afectado y elevalo lentamente hacia adelante y arriba, por encima de la cabeza. El brazo afectado debe estar relajado y el otro brazo hace el trabajo.', 552),
  ('AAROM - CÍRCULOS DE HOMBRO', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo)', 'Agarrate la muñeca y movés el brazo afectado en círculos, como se muestra. Dejá que el brazo sano ayude a levantar el brazo afectado durante el movimiento. Hacé varias vueltas en sentido horario y después invertí la dirección en sentido antihorario.', 109434),
  ('AAROM DE FLEXIÓN DE HOMBRO - SENTADO - MANOS ENTRELAZADAS', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo)', 'Sentado en una silla, entrelazá la mano del brazo afectado y elevala lentamente hacia arriba, por encima de la cabeza. Ambos brazos pueden ayudar a elevar el brazo.', 70016),
  ('FLEXIÓN CON MANOS ENTRELAZADAS - DECÚBITO DORSAL - AAROM DE FLEXIÓN DE HOMBRO', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo)', 'Acostado boca arriba con el brazo al costado del cuerpo, entrelazá la mano del brazo afectado y elevala lentamente hacia arriba, por encima de la cabeza. Ambos brazos pueden ayudar a elevar el brazo.', 12630),
  ('ABDUCCIÓN DE HOMBRO A 90 GRADOS - BASTÓN - AAROM', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo)', 'Sosteniendo un bastón con la palma hacia arriba del lado lesionado y la palma hacia abajo del lado sano, elevá lentamente el brazo lesionado hacia el costado hasta unos 90 grados. Bajá y repetí.', 107790),
  ('CAMINATA EN LA PARED CON DESPEGUE', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo)', 'Apoyá la mano afectada sobre la pared con la palma contra la pared. Después, caminá con los dedos hacia arriba por la pared, por encima de la cabeza. Luego despegá la mano de la pared y bajá el brazo sin tocarla.', 6712),
  ('FLEXIÓN AGARRANDO LA MUÑECA - DECÚBITO DORSAL - AAROM DE FLEXIÓN DE HOMBRO', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo)', 'Acostado boca arriba con el brazo al costado del cuerpo, agarrá el brazo afectado y elevalo lentamente hacia arriba, por encima de la cabeza. El brazo afectado debe estar relajado y el otro brazo hace el trabajo.', 7165),
  ('ABDUCCIÓN DE HOMBRO EN DECÚBITO DORSAL - BASTÓN - AAROM', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); AROM (activo)', 'Acostate boca arriba y sostené un bastón con la palma hacia arriba del lado lesionado y la palma hacia abajo del lado sano. Usá el brazo sano para elevar lentamente el brazo lesionado hacia el costado. Mantené esta posición y después bajá el brazo al costado del cuerpo y repetí.', 86362),
  ('ABDUCCIÓN/ADUCCIÓN HORIZONTAL CON BASTÓN', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); AROM (activo)', 'Acostado boca arriba sosteniendo un bastón hacia el techo con los codos estirados, llevá los brazos y el bastón hacia un costado y después hacia el otro.', 175),
  ('ESTIRAMIENTO DE ROTACIÓN EXTERNA CON BASTÓN 90/90 - RE', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); AROM (activo); Estiramientos; Bastón', 'Acostado boca arriba sosteniendo un bastón con los codos abiertos hacia los costados y apoyados, rotá los brazos hacia atrás, por encima de la cabeza, hasta sentir un estiramiento.', 176),
  ('FLEXIÓN CON BASTÓN - DE PIE - PALMAS ABAJO', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); AROM (activo); Estiramientos; Bastón', 'De pie, sostené un bastón con ambos brazos, con las palmas hacia abajo de los dos lados. Elevá el bastón dejando que el brazo sano haga la mayor parte del esfuerzo. El brazo afectado debe estar parcialmente relajado. Volvé a la posición inicial y repetí.', 107668),
  ('FLEXIÓN CON BASTÓN HASTA 90 GRADOS - PALMAS ABAJO', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); AROM (activo); Estiramientos; Bastón', 'De pie, sostené un bastón con ambos brazos, con las palmas hacia abajo de los dos lados. Elevá el bastón hasta 90 grados de flexión de hombro. Dejá que el brazo sano haga la mayor parte del esfuerzo. El brazo afectado debe estar parcialmente relajado. Bajá y repetí.', 107683),
  ('PRESS POR ENCIMA DE LA CABEZA CON BASTÓN - PRESS MILITAR', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); AROM (activo); Bastón', 'Empezá sosteniendo un bastón cerca del pecho, con las manos un poco más separadas que el ancho de los hombros. Después, empujá lentamente el bastón hacia arriba, por encima de la cabeza, hasta estirar completamente los codos. Bajá y repetí.', 11059),
  ('FLEXIÓN DE HOMBRO CON BASTÓN - PALMAS ARRIBA - AAROM', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); AROM (activo); Bastón', 'Sostené un bastón con ambos brazos, con las palmas hacia arriba de los dos lados. Elevá el bastón dejando que el brazo sano haga la mayor parte del esfuerzo. Bajá y repetí.', 7009),
  ('FLEXIÓN DE HOMBRO CON BASTÓN - UNA PALMA ARRIBA Y OTRA ABAJO - AAROM', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); AROM (activo); Bastón', 'De pie, sostené un bastón con ambos brazos, con la palma hacia arriba del lado afectado y la palma hacia abajo del lado sano. Elevá el bastón dejando que el brazo sano haga la mayor parte del esfuerzo. El brazo afectado debe estar parcialmente relajado.', 7008),
  ('PRESS CON BASTÓN - DE PIE', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); AROM (activo); Bastón', 'Empezá sosteniendo un bastón a la altura del pecho. Después, empujá lentamente el bastón hacia adelante hasta estirar completamente los codos. Luego volvé a la posición inicial.', 11058),
  ('DESLIZAMIENTO SOBRE LA MESA - ABDUCCIÓN CON PELOTA', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); Pelota; Estiramientos', 'De pie, apoyá el brazo lesionado sobre una pelota apoyada en una mesa y rodala suavemente hacia el costado y de vuelta.', 197),
  ('AAROM DE FLEXIÓN CON BANDA ELÁSTICA', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'AAROM (asistido activo); Banda elástica', 'Tirá hacia abajo de una banda elástica y después dejá que la banda ayude a que el hombro vuelva a elevarse.', 28002),
  ('AAROM DE FLEXIÓN DE HOMBRO A 90 - SENTADO - MANOS ENTRELAZADAS', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); Estiramientos', 'Sentado en una silla, entrelazá la mano del brazo afectado y elevala lentamente hasta la altura del hombro. El brazo sano ayuda a subir y bajar.', 162110),
  ('EXTENSIÓN DE HOMBRO AAROM / ESTIRAMIENTO - EXTENSIÓN CON BASTÓN - DE PIE', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); Estiramientos', 'De pie y sosteniendo un bastón, usá el brazo sano para ayudar a empujar el brazo afectado hacia atrás, como se muestra. El codo debe permanecer estirado todo el tiempo.', 5893),
  ('FLEXIÓN CON POLEA DE HOMBRO', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); Estiramientos', 'Con las poleas de puerta y de espaldas a la puerta, tirá lentamente hacia abajo con el brazo sano para que el brazo afectado se eleve hacia adelante y arriba sin esfuerzo.', 147546),
  ('ESTIRAMIENTO EN FLEXIÓN CON POLEA DE HOMBRO - DE FRENTE A LA PUERTA', NULL, true, 'pasivo; activo_asistido', 'Hombro', 'AAROM (asistido activo); Estiramientos', 'Con las poleas de puerta y de frente a la puerta, tirá lentamente hacia abajo con el brazo sano para que el brazo afectado se eleve sin esfuerzo. El brazo afectado debe estar relajado. El brazo sano hace todo el trabajo.', 5294),
  ('DESLIZAMIENTO SOBRE LA MESA - FLEXIÓN CON PELOTA', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); Estiramientos', 'De pie, apoyá el brazo lesionado sobre una pelota apoyada en una mesa y rodala suavemente hacia adelante y después hacia atrás. Repetí.', 196),
  ('ROTACIÓN EXTERNA - RE DE PIE CON BASTÓN Y TOALLA', NULL, true, 'pasivo; activo_asistido', 'Hombro', 'AAROM (asistido activo); Estiramientos; Bastón', 'De pie, colocá una toalla chica enrollada entre el codo del brazo afectado y el costado del cuerpo. Sostené un bastón con ambas manos manteniendo los codos flexionados a 90 grados. Empezá con el antebrazo apuntando hacia adelante y después usá el brazo sano para ayudar a rotar el brazo afectado hacia afuera, como se muestra. Volvé a la posición inicial y repetí.', 83136),
  ('FLEXIÓN DE HOMBRO HASTA 90 - BASTÓN', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); Estiramientos; Bastón', 'De pie, sostené un bastón con ambos brazos, como se muestra. Elevá el brazo afectado usando el brazo sano para ayudar a empujarlo hacia arriba. Elevalo hasta 90 grados de flexión de hombro. Bajá y repetí.', 107685),
  ('FLEXIÓN CON BASTÓN A 90 - DECÚBITO DORSAL', NULL, true, 'activo_asistido', 'Hombro', 'AAROM (asistido activo); Bastón', 'Empezá acostado boca arriba sosteniendo un bastón sobre el regazo. Elevá lentamente el bastón hacia arriba, por encima de la cabeza. Usá el brazo sano para ayudar con el movimiento. Elevá hasta 90 grados, es decir hasta que los brazos queden apuntando hacia arriba. Detenete y después volvé lentamente a la posición inicial.', 54314),
  ('CÍRCULOS DE HOMBRO EN ABDUCCIÓN', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Elevá los brazos hacia los costados y después movelos en círculos durante varias vueltas. Después repetí en la dirección contraria. Continuá alternando las direcciones.', 177480),
  ('AROM DE HOMBRO - 45 DE ABDUCCIÓN - ROTACIÓN INTERNA Y EXTERNA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate boca arriba con una toalla doblada o una almohada debajo del codo, con el codo apoyado a unos 45 grados del costado del cuerpo. Después, con el codo flexionado a 90 grados, rotá el hombro de modo que la mano se mueva hacia adentro, hacia el abdomen, y después hacia afuera, alejándose del abdomen.', 77897),
  ('AROM DE HOMBRO - 45 DE ABDUCCIÓN - DE NEUTRO A ROTACIÓN EXTERNA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate boca arriba con una toalla doblada o una almohada debajo del codo, con el codo apoyado a unos 45 grados del costado del cuerpo. Después, con el codo flexionado a 90 grados, rotá el hombro de modo que el antebrazo arranque apuntando hacia arriba y se mueva hacia afuera, alejándose del cuerpo, como se muestra. Volvé a la posición inicial y repetí.', 77898),
  ('AROM DE HOMBRO - 45 DE ABDUCCIÓN - DE NEUTRO A ROTACIÓN INTERNA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate boca arriba con una toalla doblada o una almohada debajo del codo, con el codo apoyado a unos 45 grados del costado del cuerpo. Después, con el codo flexionado a 90 grados, rotá el hombro de modo que el antebrazo arranque apuntando hacia arriba y se mueva hacia adentro, hacia el abdomen, como se muestra. Volvé a la posición inicial y repetí.', 77900),
  ('AROM DE HOMBRO - 90 DE ABDUCCIÓN - DE NEUTRO A ROTACIÓN EXTERNA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate boca arriba con una toalla doblada o una almohada debajo del codo, con el codo apoyado a unos 90 grados del costado del cuerpo. Después, con el codo flexionado a 90 grados, rotá el hombro de modo que el antebrazo arranque apuntando hacia arriba y se mueva hacia atrás, como se muestra. Volvé a la posición inicial y repetí.', 77902),
  ('AROM DE HOMBRO - 90 DE ABDUCCIÓN - DE NEUTRO A ROTACIÓN INTERNA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate boca arriba con una toalla doblada o una almohada debajo del codo, con el codo apoyado a unos 90 grados del costado del cuerpo. Después, con el codo flexionado a 90 grados, rotá el hombro de modo que el antebrazo arranque apuntando hacia arriba y se mueva hacia adentro, hacia la cadera, como se muestra. Volvé a la posición inicial y repetí.', 77901),
  ('AROM DE HOMBRO - ROTACIÓN INTERNA Y EXTERNA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate boca arriba con una almohada debajo del codo y el codo apoyado cerca del costado del cuerpo. Después, con el codo flexionado a 90 grados, rotá el hombro de modo que la mano se mueva hacia adentro, hacia el abdomen, y después hacia afuera, alejándose del abdomen, como se muestra. Repetí.', 77895),
  ('AROM DE HOMBRO - DE NEUTRO A ROTACIÓN INTERNA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate boca arriba con una toalla doblada o una almohada debajo del codo, con el codo apoyado al costado del cuerpo. Después, con el codo flexionado a 90 grados, rotá el hombro de modo que el antebrazo arranque apuntando hacia arriba y se mueva hacia adentro, hacia el abdomen, como se muestra. Volvé a la posición inicial (neutra) y repetí.', 77899),
  ('AROM DE ABDUCCIÓN DE HOMBRO', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Empezá con el brazo al costado del cuerpo y la palma de la mano mirando hacia adelante. Después, elevá el brazo hacia el costado y por encima de la cabeza. Bajá y repetí.', 164),
  ('AROM DE ABDUCCIÓN DE HOMBRO - BILATERAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Empezá con los brazos al costado del cuerpo y las palmas mirando hacia adelante. Después, elevá los brazos hacia los costados y por encima de la cabeza. Bajá y repetí.', 7004),
  ('AROM DE ABDUCCIÓN DE HOMBRO - BILATERAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Empezá con los brazos al costado del cuerpo y las palmas mirando hacia adelante. Después, elevá los brazos hacia los costados hasta la altura de los hombros. Bajá y repetí.', 149059),
  ('AROM DE EXTENSIÓN DE HOMBRO', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Empezá con el brazo al costado del cuerpo. Después, llevá el brazo hacia atrás, por detrás de la cintura, como se muestra. Volvé a la posición inicial y repetí.', 165),
  ('AROM DE FLEXIÓN DE HOMBRO', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Empezá con el brazo al costado del cuerpo. Con el pulgar apuntando hacia adelante, elevá el brazo hacia adelante y arriba, por encima de la cabeza. Bajá y repetí.', 531),
  ('AROM DE FLEXIÓN EN DECÚBITO LATERAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostado de costado con el brazo al costado del cuerpo, elevá lentamente el brazo hacia adelante y arriba, por delante del cuerpo.', 12628),
  ('AROM DE ABDUCCIÓN HORIZONTAL EN DECÚBITO LATERAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostado de costado con el brazo extendido por delante del cuerpo, elevá lentamente el brazo hacia arriba, en dirección al techo, como se muestra.', 12629),
  ('AROM DE ABDUCCIÓN EN DECÚBITO LATERAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate de costado con el brazo al costado del cuerpo, como se muestra. Después, elevá el brazo hacia el costado de la cabeza, bajalo y repetí.', 172),
  ('AROM DE ABDUCCIÓN EN DECÚBITO LATERAL - 90', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostado de costado con el brazo al costado del cuerpo, elevá lentamente el brazo hacia arriba, separándolo del cuerpo. Detenete cuando el brazo quede apuntando hacia arriba (90 grados), como se muestra. Bajá el brazo y repetí.', 120512),
  ('FLEXIÓN INCLINADO HACIA ADELANTE', NULL, true, 'activo_asistido', 'Hombro', 'AROM (activo)', 'De pie, inclinate hacia adelante y sostenete con el brazo sano. Con el brazo afectado al costado del cuerpo, retraé el omóplato y después elevá el brazo hacia adelante y arriba, como se muestra. Mantené el omóplato retraído todo el tiempo.', 12626),
  ('ROTACIÓN INTERNA Y EXTERNA BILATERAL DE HOMBRO - AROM', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Empezá sentado con buena postura en una silla y los brazos cruzados, como se muestra. Después, rotá los brazos hacia afuera, como se muestra. Volvé a la posición inicial y repetí.', 163680),
  ('FLEXIÓN DE HOMBRO CON BASTÓN - PALMAS ABAJO - AAROM', NULL, true, 'activo_asistido', 'Hombro', 'AROM (activo)', 'Sostené un bastón con ambos brazos, con las palmas hacia abajo de los dos lados. Elevá el bastón dejando que el brazo sano haga la mayor parte del esfuerzo. El brazo afectado debe estar parcialmente relajado.', 169),
  ('ROTACIÓN EXTERNA - RE', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Parate con el brazo al costado del cuerpo y el codo flexionado a 90 grados. Llevá el omóplato hacia atrás y hacia abajo, en dirección a la cola, y mantené esa posición. Empezá con el antebrazo y la muñeca cerca del abdomen. Después, rotá el brazo hacia afuera alejándolo del abdomen, manteniendo el brazo cerca del cuerpo y el omóplato abajo y atrás todo el tiempo. Volvé a la posición inicial y repetí.', 61148),
  ('ROTACIÓN EXTERNA CON 70 GRADOS DE ABDUCCIÓN - RE', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Sentado, apoyá el codo sobre una mesa con una almohada o rollo de modo que el brazo quede a unos 70 grados del costado del cuerpo y a unos 70 grados del pecho. Mantené el codo flexionado a 90 grados. Rotá el hombro de modo que el antebrazo apunte hacia arriba y después rotalo hacia abajo hasta que el antebrazo apunte hacia adelante, como se muestra. Repetí de manera lenta y controlada.', 46070),
  ('ROTACIÓN EXTERNA CON 90 GRADOS DE ABDUCCIÓN - RE', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Sentado, apoyá el codo sobre una mesa con una almohada o rollo de modo que el brazo quede a unos 90 grados del costado del cuerpo y a unos 90 grados del pecho. Mantené el codo flexionado a 90 grados. Rotá el hombro de modo que el antebrazo apunte hacia arriba y después rotalo hacia abajo hasta que el antebrazo apunte hacia adelante, como se muestra. Repetí de manera lenta y controlada.', 19776),
  ('ROTACIÓN EXTERNA CON TOALLA - RE', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Parate con el brazo al costado del cuerpo y el codo flexionado a 90 grados. Colocá una toalla enrollada entre el brazo y el costado del cuerpo, como se muestra. Llevá el omóplato hacia atrás y hacia abajo, en dirección a la cola, y mantené esa posición. Empezá con el antebrazo y la muñeca cerca del abdomen. Después, rotá el brazo hacia afuera alejándolo del abdomen, manteniendo el brazo contra la toalla y el omóplato abajo y atrás todo el tiempo. Volvé a la posición inicial y repetí.', 61147),
  ('ÁNGELES DE NIEVE SOBRE RODILLO DE ESPUMA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate sobre un rodillo de espuma y dejá que los brazos caigan hacia el piso con los codos estirados, como se muestra. Después deslizá los brazos hacia arriba, por encima de la cabeza, y volvé a llevarlos hacia los costados, como se muestra, y repetí.', 28005),
  ('GERIÁTRICO - ABDUCCIÓN BILATERAL DE BRAZOS', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Sentate en una silla con buena postura y los brazos abajo al costado del cuerpo. Elevá los brazos hacia los costados manteniendo los codos estirados. Bajá y repetí.', 171536),
  ('GERIÁTRICO - APRETAR OMÓPLATOS Y ABDUCCIÓN - PALMAS ADELANTE', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo)', 'Sentate en una silla con las manos sobre los muslos. Elevá los brazos hacia arriba y atrás con las palmas mirando hacia adelante y los codos estirados. Apretá los omóplatos entre sí, después volvé a la posición inicial y repetí.', 171538),
  ('GERIÁTRICO - SENTADO - ALCANCES POR ENCIMA DE LA CABEZA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Sentate en una silla con buena postura y los brazos a la altura del pecho con los codos flexionados. Estirá un brazo por encima de la cabeza extendiendo el codo. Volvé a la posición inicial y repetí con el otro brazo. Continuá alternando de un lado al otro.', 171429),
  ('GERIÁTRICO - ABDUCCIÓN DE UN SOLO BRAZO', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Sentate en una silla con buena postura y los brazos abajo al costado del cuerpo. Elevá un brazo hacia el costado manteniendo el codo estirado. Bajá y repetí.', 171537),
  ('GERIÁTRICO SENTADO - FLEXIÓN ALTERNADA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Sentate en una silla con buena postura y los brazos abajo al costado del cuerpo. Elevá un brazo hacia adelante y por encima de la cabeza manteniendo el codo estirado. Volvé a la posición inicial y repetí con el otro brazo. Continuá alternando de un lado al otro.', 171430),
  ('PRESS POR ENCIMA DE LA CABEZA - ALTERNADO', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Extendé una mano por encima de la cabeza estirando el codo, como se muestra. Bajala y después elevá el otro brazo por encima de la cabeza. Bajá y repetí este movimiento alternado.', 7006),
  ('FLEXIÓN DE HOMBRO EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate boca abajo con el brazo colgando por el borde de la camilla o la cama. Después, elevá el brazo hacia adelante y arriba, en dirección al techo. Volvé a la posición inicial y repetí.', 85572),
  ('GOLPES Y PATADAS - SENTADO', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Sentate en una silla con los codos flexionados. Después, extendé un brazo hacia adelante como si dieras un golpe mientras extendés (pateás) la rodilla del mismo lado, como se muestra. Volvé a la posición inicial y después repetí del otro lado. Continuá alternando de un lado al otro.', 171056),
  ('EMPUJES - DESLIZAMIENTOS NERVIOSOS', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Con las muñecas en extensión, como se muestra, empujá un brazo hacia adelante por delante del cuerpo hasta estirar completamente el codo. Al mismo tiempo, llevá el otro brazo desde la posición estirada a la posición flexionada, como se muestra. Repetí este movimiento alternando los brazos en simultáneo.', 21670),
  ('DESCENSOS ESCAPULARES', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Empezá apretando los omóplatos entre sí. Después, empujá el brazo hacia abajo en dirección al piso. Al hacerlo, el hombro debe descender unos pocos centímetros. Mantené el codo estirado y las muñecas extendidas todo el tiempo.', 21669),
  ('ESTIRAMIENTO EN PLEGARIA POR ENCIMA DE LA CABEZA - SENTADO', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Sentate en una silla con las palmas mirando hacia adelante. Elevá las manos separándolas del cuerpo y por encima de la cabeza hasta que las palmas se toquen. Después, bajá las manos hasta que queden por delante del pecho. Mantené, volvé a la posición inicial y repetí.', 171425),
  ('GOLPES SENTADO', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Sentado en una silla, extendé los brazos hacia adelante como si dieras golpes. Usá movimientos suaves y controlados.', 6981),
  ('ROTACIÓN DE TRONCO SENTADO - BRAZOS ADELANTE', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Sentate en una silla con los brazos extendidos por delante del cuerpo. Girá lentamente el tronco hacia un costado rotando la columna. Los brazos y la cabeza también deben rotar junto con la columna, como se muestra. Seguí la mano con la mirada. Volvé a la posición inicial y repetí del otro lado.', 171427),
  ('DIAGONAL DE HOMBRO 1 - DE PIE - D1', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'De pie, movés el brazo en un patrón diagonal, a veces descrito como D1 (diagonal 1) o del tipo llevar la comida a la boca. El patrón arranca con el brazo al costado del cuerpo y el pulgar apuntando hacia atrás y hacia abajo. Después, llevá el brazo hacia arriba y cruzando el cuerpo de modo que la palma de la mano quede apuntando hacia la boca. Volvé a la posición inicial y repetí.', 59401),
  ('DIAGONAL DE HOMBRO 1 - DECÚBITO DORSAL - D1', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostado boca arriba, movés el brazo en un patrón diagonal, a veces descrito como D1 (diagonal 1) o del tipo llevar la comida a la boca. El patrón arranca con el brazo al costado del cuerpo y el pulgar apuntando hacia el piso. Después, llevá el brazo hacia arriba y cruzando el cuerpo de modo que la palma de la mano quede apuntando hacia la boca. Volvé a la posición inicial y repetí.', 59399),
  ('DIAGONAL DE HOMBRO 2 - DE PIE - D2', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'De pie, movés el brazo en un patrón diagonal, a veces descrito como D2 (diagonal 2) o del tipo desenvainar la espada. El patrón arranca con el brazo llegando al bolsillo opuesto, junto a la cadera contraria, con la palma mirando hacia esa cadera. Después, llevá el brazo hacia arriba y hacia afuera, cruzando el cuerpo, de modo que la palma quede mirando hacia el techo y el pulgar apunte hacia atrás. Volvé a la posición inicial y repetí.', 59402),
  ('DIAGONAL DE HOMBRO 2 - DECÚBITO DORSAL - D2', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostado boca arriba, movés el brazo en un patrón diagonal, a veces descrito como D2 (diagonal 2) o del tipo desenvainar la espada. El patrón arranca con el brazo llegando al bolsillo opuesto, junto a la cadera, con la palma mirando hacia la cadera. Después, llevá el brazo hacia arriba y hacia afuera, cruzando el cuerpo, de modo que la palma quede mirando hacia el piso. Volvé a la posición inicial y repetí.', 59400),
  ('ENCOGIMIENTO DE HOMBROS CON PESAS', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo)', 'Sosteniendo pesas, elevá los hombros hacia las orejas, como se muestra. Encogé ambos hombros al mismo tiempo.', 16048),
  ('ROTACIÓN INTERNA EN DECÚBITO LATERAL - RI', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate de costado con el hombro flexionado a 90 grados y el codo flexionado y apoyado sobre la camilla o la cama. El antebrazo debe apuntar hacia el techo. Después, dejá que el antebrazo baje hacia la camilla, como se muestra. Volvé a la posición inicial. Colocá una toalla enrollada debajo del codo si tu profesional te lo indica.', 8451),
  ('ABDUCCIÓN EN DECÚBITO DORSAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate boca arriba con el brazo al costado del cuerpo y la palma mirando hacia arriba, como se muestra. Después, elevá lentamente el brazo hacia el costado hasta la altura del hombro. Volvé a la posición inicial y repetí.', 150416),
  ('FLEXIÓN EN DECÚBITO DORSAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostado boca arriba con el brazo al costado del cuerpo, elevalo lentamente hacia adelante y arriba, por encima de la cabeza.', 12631),
  ('ABDUCCIÓN HORIZONTAL EN DECÚBITO DORSAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostado boca arriba con el brazo estirado y elevado por delante del cuerpo, bajá lentamente el brazo hacia el costado, como se muestra. Volvé a la posición inicial.', 12632),
  ('ABECEDARIO DE HOMBRO EN DECÚBITO DORSAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Acostate boca arriba y extendé el brazo hacia el techo. Con el codo estirado, movés el brazo desde el hombro como si escribieras el abecedario en el aire con la mano y el brazo.', 130984),
  ('BARRIDOS SOBRE LA MESA - CÍRCULOS', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Apoyá la mano sobre una toalla chica doblada arriba de una mesa y barré suavemente la mesa en círculos. Hacelo en una dirección y después invertí la dirección de a ratos.', 7166),
  ('BARRIDOS SOBRE LA MESA - ADELANTE Y ATRÁS', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Apoyá la mano sobre una toalla chica doblada arriba de una mesa y barré suavemente la mesa hacia adelante y hacia atrás.', 7167),
  ('BARRIDOS SOBRE LA MESA - ROTACIÓN INTERNA Y EXTERNA', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Apoyá la mano sobre una toalla chica doblada arriba de una mesa y barré suavemente la mesa en arco de lado a lado. Mantené el codo pegado al cuerpo todo el tiempo.', 11805),
  ('BARRIDOS SOBRE LA MESA - LATERAL', NULL, true, 'activo', 'Hombro', 'AROM (activo)', 'Apoyá la mano sobre una toalla chica doblada arriba de una mesa y barré suavemente la mesa de lado a lado.', 7168),
  ('FLEXIÓN CON PELOTA SENTADO', NULL, true, 'activo', 'Hombro', 'AROM (activo); Pelota', 'Empezá sentado en una silla sosteniendo una pelota de ejercicios hacia el costado, junto a una rodilla, con los codos extendidos. Después, elevá lentamente la pelota por encima del hombro del lado contrario y por encima de la cabeza. Volvé a la posición inicial y repetí.', 67489),
  ('FLEXIÓN CON PELOTA SENTADO', NULL, true, 'activo', 'Hombro', 'AROM (activo); Pelota', 'Empezá sentado en una silla sosteniendo una pelota de ejercicios por delante del cuerpo con los codos extendidos. Después, elevá lentamente la pelota por encima de la cabeza. Volvé a la posición inicial y repetí.', 67486),
  ('PRESS FRONTAL CON PELOTA SENTADO', NULL, true, 'activo', 'Hombro', 'AROM (activo); Pelota', 'Empezá sentado en una silla y llevá una pelota de ejercicios contra el pecho. Empujá lentamente la pelota hacia adelante por delante del cuerpo extendiendo los codos. Volvé a llevar la pelota al pecho y repetí.', 67485),
  ('PRESS POR ENCIMA DE LA CABEZA CON PELOTA SENTADO', NULL, true, 'activo', 'Hombro', 'AROM (activo); Pelota', 'Empezá sentado en una silla sosteniendo una pelota de ejercicios contra el pecho. Elevá lentamente la pelota por encima de la cabeza extendiendo los codos. Volvé a llevar la pelota al pecho y repetí.', 67487),
  ('GIRO DE PELOTA SENTADO', NULL, true, 'activo', 'Hombro', 'AROM (activo); Pelota', 'Empezá sentado en una silla y elevá una pelota de ejercicios por delante del cuerpo con los codos extendidos. Después, girá lentamente la pelota de modo que una mano quede arriba y la otra abajo. Después invertí la dirección hasta que la mano de arriba quede abajo y la de abajo quede arriba. Repetí.', 67491),
  ('PELOTA DE EJERCICIOS - ABDUCCIÓN BILATERAL DE HOMBROS', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Pelota; Estabilización', 'Sentado sobre una pelota de ejercicios, activá los músculos abdominales y después elevá los brazos hacia los costados y por encima de la cabeza. Bajá los brazos y repetí. Mantené los abdominales activos y la columna estable y erguida todo el tiempo.', 167394),
  ('ROTACIÓN EXTERNA CON 70 GRADOS DE ABDUCCIÓN - RE CON PESO LIBRE', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Peso libre', 'Sostené un peso libre chico. Sentado, apoyá el codo sobre una mesa con una almohada o rollo de modo que el brazo quede a unos 70 grados del costado del cuerpo y a unos 70 grados del pecho. Mantené el codo flexionado a 90 grados. Rotá el hombro de modo que el antebrazo apunte hacia arriba y después rotalo hacia abajo hasta que el antebrazo apunte hacia adelante, como se muestra. Repetí de manera lenta y controlada.', 46069),
  ('ELEVAR UN PESO CHICO A 90 GRADOS DE FLEXIÓN DE HOMBRO', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Peso libre', 'Sentate o parate de modo que puedas apoyar un peso chico o una lata sobre una mesada o estante que esté a la altura de tus hombros. Empezá con el peso o el objeto sobre el regazo y después apoyalo en el estante o la mesa sin elevar el omóplato. Después, levantá el objeto y volvé a apoyarlo sobre el muslo. Mantené los omóplatos apretados entre sí y no dejes que el hombro se eleve durante el ejercicio.', 50407),
  ('ROTACIÓN EXTERNA CON 90 GRADOS DE ABDUCCIÓN - PESO LIBRE - RE', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Peso libre; Estabilización', 'Sostené un peso libre chico. Sentado, apoyá el codo sobre una mesa con una almohada o rollo de modo que el brazo quede a unos 90 grados del costado del cuerpo y a unos 90 grados del pecho. Mantené el codo flexionado a 90 grados. Rotá el hombro de modo que el antebrazo apunte hacia arriba y después rotalo hacia abajo hasta que el antebrazo apunte hacia adelante, como se muestra. Repetí de manera lenta y controlada.', 19777),
  ('PÉNDULOS INVERSOS - DECÚBITO LATERAL', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Peso libre; Estabilización', 'Acostado de costado, estirá el brazo hacia el techo. Después, movés el brazo en círculos chicos en sentido horario. Después de unos segundos, invertí la dirección en sentido antihorario. Cambiá de dirección cada unos segundos.', 18701),
  ('ABECEDARIO DE HOMBRO', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Peso libre; Estabilización', 'De pie y sosteniendo una pelota chica o un peso libre, escribí el abecedario en el aire con el brazo. Solo el brazo debe moverse mientras lo hacés.', 19783),
  ('ABDUCCIÓN HORIZONTAL INCLINADO HACIA ADELANTE', NULL, true, 'activo_asistido', 'Hombro', 'AROM (activo); Estabilización', 'De pie, inclinate hacia adelante y sostenete con el brazo sano. Con el brazo afectado empezando al costado del cuerpo, llevá el brazo hacia arriba y hacia el costado, como se muestra.', 11045),
  ('ROTACIÓN EXTERNA EN DECÚBITO VENTRAL - RE', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Acostate boca abajo y apoyá el brazo sobre la camilla o la cama con el antebrazo colgando hacia el piso, como se muestra. Después, llevá el antebrazo hacia adelante y arriba, en dirección al techo, manteniendo el brazo apoyado sobre la camilla todo el tiempo. Después volvé a la posición inicial.', 8443),
  ('FLEXIÓN EN DECÚBITO VENTRAL - RANGO FINAL', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Acostado boca abajo con los brazos por encima de la cabeza, elevá los brazos hacia arriba, despegándolos de la superficie, en dirección al techo.', 19781),
  ('RETRACCIÓN EN DECÚBITO VENTRAL', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Estabilización', 'Acostado boca abajo con los brazos al costado del cuerpo, apretá lentamente los omóplatos hacia abajo y hacia la columna.', 14080),
  ('RETRACCIÓN EN DECÚBITO VENTRAL - BRAZOS DETRÁS DE LA ESPALDA', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Acostado boca abajo con los brazos detrás de la espalda, movés lentamente los codos hacia arriba, en dirección al techo, mientras apretás los omóplatos hacia la columna y hacia abajo.', 14077),
  ('ABDUCCIÓN HORIZONTAL DE HOMBRO EN DECÚBITO VENTRAL', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Estabilización', 'Acostate boca abajo con el brazo colgando por el borde de la camilla o la cama. Después, apretá los omóplatos hacia adentro y hacia abajo, en dirección a la columna. Empezá el movimiento elevando el brazo hacia el techo manteniendo el brazo a 90 grados del costado del cuerpo. Volvé a la posición inicial y repetí.', 85573),
  ('EXTENSIÓN DE HOMBRO EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Acostate boca abajo con el brazo colgando por el borde de la camilla o la cama. Después, elevá el brazo hacia atrás y hacia el costado del cuerpo. Volvé a la posición inicial y repetí.', 85576),
  ('W DE HOMBRO EN DECÚBITO VENTRAL', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Estabilización', 'Acostate boca abajo con el brazo colgando por el borde de la camilla o la cama. Después, apretá los omóplatos hacia adentro y hacia abajo, en dirección a la columna. Empezá flexionando el codo y después elevá el brazo hacia el techo manteniendo el codo flexionado. Volvé a la posición inicial y repetí.', 85575),
  ('Y DE HOMBRO EN DECÚBITO VENTRAL', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Estabilización', 'Acostate boca abajo con el brazo colgando por el borde de la camilla o la cama. Después, apretá los omóplatos hacia adentro y hacia abajo, en dirección a la columna. Empezá el movimiento elevando el brazo hacia el costado y hacia arriba, en dirección al techo, con los pulgares apuntando hacia arriba, como se muestra. Volvé a la posición inicial y repetí.', 85574),
  ('W EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Acostado boca abajo con los codos flexionados y las palmas hacia abajo, elevá lentamente los brazos hacia el techo mientras apretás los omóplatos hacia abajo y hacia la columna.', 14081),
  ('PÉNDULOS INVERSOS', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Acostado boca arriba, estirá el brazo hacia el techo. Después, movés el brazo en círculos chicos en sentido horario. Después de unos segundos, invertí la dirección en sentido antihorario. Cambiá de dirección cada unos segundos.', 11056),
  ('ÁNGEL DE NIEVE INVERTIDO', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Acostado boca abajo, elevá lentamente los brazos despegándolos del piso. Estiralos por delante tuyo, por encima de la cabeza. Manteniendo los brazos despegados del piso, movelos en arco hasta que queden detrás de la espalda. Volvé a la posición inicial y repetí.', 159613),
  ('PROTRACCIÓN ESCAPULAR - DECÚBITO DORSAL', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Acostate boca arriba con el brazo extendido por delante del cuerpo y hacia el techo. Manteniendo los codos estirados, llevá los hombros hacia adelante, en dirección al techo. Mantené los codos estirados todo el tiempo.', 39663),
  ('PROTRACCIÓN ESCAPULAR - DECÚBITO DORSAL - BILATERAL', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Acostate boca arriba con los brazos extendidos por delante del cuerpo y hacia el techo. Manteniendo los codos estirados, llevá los hombros hacia adelante, en dirección al techo. Mantené los codos estirados todo el tiempo.', 39662),
  ('RETRACCIÓN ESCAPULAR', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Con el brazo elevado y el codo flexionado, llevá el omóplato hacia atrás y hacia abajo.', 190),
  ('CABESTRILLO - RETRACCIÓN', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Estabilización', 'Con el cabestrillo puesto, apretá los omóplatos hacia atrás y hacia abajo, como se muestra.', 8524),
  ('CABESTRILLO - ENCOGIMIENTO DE HOMBROS', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Con el cabestrillo puesto, elevá los hombros hacia arriba y después bajalos, como se muestra.', 8525),
  ('RETRACCIÓN DE PIE - T', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'De pie, elevá los brazos hacia los costados a 90 grados con los codos casi estirados y las palmas hacia arriba, como se muestra. Después, llevá los brazos hacia atrás mientras apretás los omóplatos entre sí y levemente hacia abajo. Mantené, relajá y repetí.', 60811),
  ('RETRACCIÓN DE PIE - W', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'De pie, elevá los brazos hacia los costados y flexioná los codos a 90 grados. Después, llevá los codos hacia atrás mientras apretás los omóplatos entre sí y levemente hacia abajo. Mantené, relajá y repetí.', 60383),
  ('ELEVACIÓN EN PLANO ESCAPULAR DE PIE', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'De pie, elevá los brazos por encima de la cabeza a unos 45 grados del centro. Bajá y repetí.', 60387),
  ('YTWL DE PIE', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Estabilización', 'De pie, llevá los brazos hacia arriba en dirección al techo como si formaras la letra Y con los brazos y el cuerpo. Manteniendo esa posición, apretá los omóplatos hacia abajo y hacia atrás, en dirección a la columna. Mantené los codos estirados. Después, bajá los brazos hasta que queden extendidos hacia los costados formando la letra T, como se muestra. Apretá los omóplatos hacia abajo y hacia atrás. Mantené los codos estirados. Después, flexioná los codos y bajalos un poco, formando una W con los brazos, de modo que las palmas apunten hacia arriba y los codos queden hacia los costados. Por último, bajá más los codos hasta que los brazos toquen las costillas y los antebrazos apunten hacia adelante. Apretá los omóplatos hacia abajo y hacia atrás formando una L con los brazos. Mantené las palmas mirando hacia el techo todo el tiempo.', 71846),
  ('SUPERMAN - ABDUCCIÓN DE HOMBRO', NULL, true, 'activo; fortalecimiento', 'Hombro', 'AROM (activo); Estabilización', 'Acostate boca abajo sobre una camilla. Empezá con los brazos al costado del cuerpo y las palmas mirando hacia arriba. Después, llevá los brazos hacia los costados y por encima de la cabeza mientras los rotás de modo que las palmas queden mirando hacia abajo. Volvé a la posición inicial y repetí.', 85341),
  ('ÁNGELES EN LA PARED', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Parate de espaldas a una pared con los brazos elevados a 90 grados. Manteniendo el contacto de la cabeza, las muñecas, los codos y los hombros, deslizá los brazos hacia arriba y hacia abajo por la pared, como se muestra.', 60388),
  ('FLEXIÓN DE BRAZOS CON EMPUJE EXTRA EN LA PARED - SERRATO', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estabilización', 'Parate de frente a una pared, a medio metro de distancia. Inclinate hacia la pared en posición de flexión de brazos con los codos estirados. Después, dejá que los omóplatos se acerquen y se alejen entre sí (protracción y retracción), como se muestra. Es un movimiento chico y los codos deben permanecer estirados todo el tiempo.', 39163),
  ('ESTIRAMIENTO CON MANOS ENTRELAZADAS - ADELANTE Y POR ENCIMA DE LA CABEZA', NULL, true, 'activo', 'Hombro', 'AROM (activo); Estiramientos', 'Empezá sentado en una silla con los dedos entrelazados a la altura del pecho. Empujá las palmas hacia afuera, como se muestra, manteniendo los dedos entrelazados. Estirá los codos y después elevá los brazos por encima de la cabeza. Bajá los brazos y volvé a llevar las palmas hacia adentro para regresar a la posición inicial. Repetí.', 171054),
  ('ESTIRAMIENTO CON MANOS ENTRELAZADAS - POR ENCIMA DE LA CABEZA - DE LADO A LADO', NULL, true, 'pasivo', 'Hombro', 'AROM (activo); Estiramientos', 'Entrelazá las manos. Manteniendo los dedos entrelazados, empujá las palmas hacia afuera y elevá los brazos por encima de la cabeza. Después, inclinate hacia un costado para lograr un estiramiento suave del hombro y la columna. Mantené esta posición y después hacelo del otro lado y repetí.', 171055),
  ('SERRATO CON BASTÓN', NULL, true, 'activo_asistido', 'Hombro', 'AROM (activo); Bastón', 'Acostate boca arriba sosteniendo un bastón por encima del pecho con los codos estirados. Manteniendo los codos estirados, llevá los omóplatos hacia adelante, en dirección al techo. Mantené los codos estirados todo el tiempo. Bajá y repetí.', 129116),
  ('REMO AL MENTÓN - BASTÓN - TIRONES ALTOS', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'AROM (activo); Bastón', 'Sostené un bastón a la altura de la cintura con los codos estirados. Después, tirá del bastón hacia arriba, en dirección al mentón, dejando que los codos se flexionen. Bajá y repetí.', 129115),
  ('FLEXIÓN CON BASTÓN - AROM', NULL, true, 'activo_asistido', 'Hombro', 'AROM (activo); Bastón', 'Acostate boca arriba y sostené un bastón o palo entre el pulgar y el índice, como se muestra. Empezá con el bastón sobre el regazo y los codos estirados. Después elevá lentamente el bastón por encima de la cabeza y volvé a llevarlo al regazo. Repetí.', 66923),
  ('CÍRCULOS CON PELOTA', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota', 'Sostené un balón medicinal u otra pelota a la altura del pecho. Después, extendé los codos y empujá la pelota hacia adelante por delante del cuerpo, como se muestra. Después, movés la pelota en círculos durante varias vueltas y después invertí la dirección.', 69309),
  ('DIAGONALES CON PELOTA - FNP', NULL, true, 'pasivo', 'Hombro', 'Pelota', 'Sentado, sostené una pelota con ambas manos y movela en un patrón diagonal desde la cadera hasta por encima del hombro contrario, como se muestra. Repetí.', 55385),
  ('PRESS POR ENCIMA DE LA CABEZA CON PELOTA', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota', 'Sostené un balón medicinal u otra pelota a la altura del pecho. Después, extendé los codos y empujá la pelota por encima de la cabeza, como se muestra. Volvé a la posición inicial y repetí.', 69303),
  ('PRESS CON PELOTA', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota', 'Sostené un balón medicinal u otra pelota a la altura del pecho. Después, extendé los codos y empujá la pelota hacia adelante por delante del cuerpo, como se muestra. Volvé a la posición inicial y repetí.', 69307),
  ('FLEXIÓN DE HOMBRO EN RANGO FINAL - PELOTA EN LA PARED', NULL, true, 'pasivo', 'Hombro', 'Pelota', 'Parate cerca de una pared y sostené una pelota por encima de la cabeza contra la pared. Con ambas manos sobre la pelota, inclinate levemente contra ella. Después, despegá una mano de la pelota y llevala por encima de la cabeza con el pulgar apuntando hacia atrás. Volvé a la posición inicial, alterná los brazos y repetí.', 166988),
  ('ROTACIÓN EXTERNA - LANZAMIENTO DE PELOTA EN DECÚBITO LATERAL - RE CON PELOTA', NULL, true, 'activo', 'Hombro', 'Pelota', 'Acostate de costado y lanzá una pelota al aire y atajala. Mantené el codo flexionado y apoyado sobre el costado del cuerpo todo el tiempo.', 7863),
  ('BALÓN MEDICINAL - FLEXIÓN DE BRAZOS CON PASE', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota', 'Empezá en posición de flexión de brazos con una mano sobre un balón medicinal. Después, rodá el balón hacia la otra mano y hacé una flexión de brazos. Después, pasá el balón al otro lado y repetí.', 6052),
  ('BALÓN MEDICINAL - FLEXIÓN DE BRAZOS CON PASE - MODIFICADA', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota', 'Empezá en posición de flexión de brazos sobre las rodillas y con una mano sobre un balón medicinal. Después, rodá el balón hacia la otra mano y hacé una flexión de brazos. Después, pasá el balón al otro lado y repetí.', 6053),
  ('BALÓN MEDICINAL - FLEXIONES DE BRAZOS', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota', 'Hacé flexiones de brazos con ambas manos apoyadas sobre un balón medicinal. Mantené los codos cerca del costado del cuerpo todo el tiempo.', 6242),
  ('AUTOMASAJE CON PELOTA - HOMBRO ANTERIOR', NULL, true, 'activo', 'Hombro', 'Pelota', 'Parate cerca del vano de una puerta o de la esquina de dos paredes, de modo que el hombro quede alineado con la pared. Colocá una pelota de lacrosse o de tenis en la parte de adelante del hombro, como se muestra. Inclinate contra la pelota aplicando presión en la zona. Podés mantener la posición y hacer movimientos chicos para rodar la pelota sobre las zonas tensas. No pases la pelota sobre zonas óseas.', 99579),
  ('AUTOMASAJE CON PELOTA - BÍCEPS - DE PIE', NULL, true, 'activo', 'Hombro', 'Pelota', 'Parate cerca del vano de una puerta de modo que el hombro quede alineado con la pared. Colocá una pelota de lacrosse o de tenis en la parte de adelante del hombro, como se muestra. Inclinate contra la pelota aplicando presión en la zona mientras movés levemente el cuerpo de lado a lado y extendés el brazo hacia atrás. No pases la pelota sobre zonas óseas.', 99578),
  ('AUTOMASAJE CON PELOTA - DELTOIDES LATERAL', NULL, true, 'activo', 'Hombro', 'Pelota', 'Colocá una pelota entre una pared y el costado del hombro, como se muestra. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Inclinate contra la pelota para aplicar presión suave sobre las zonas tensas. No pases la pelota sobre zonas óseas. Podés mantener la presión en una zona o mover el cuerpo para que la pelota ruede hacia arriba y abajo o de lado a lado.', 99548),
  ('AUTOMASAJE CON PELOTA - PECTORAL', NULL, true, 'activo', 'Hombro', 'Pelota', 'Parate de frente a una pared y colocá una pelota de lacrosse o de tenis sobre la parte de adelante del pecho, en la zona tensa. Llevá el brazo detrás de la espalda y después inclinate contra la pelota aplicando presión en la zona. Podés mantener la posición y hacer movimientos chicos para rodar la pelota sobre las zonas tensas.', 99630),
  ('AUTOMASAJE CON PELOTA - MÚSCULO PECTORAL - EN EL PISO', NULL, true, 'pasivo', 'Hombro', 'Pelota', 'Acostate boca abajo en el piso y colocá una pelota debajo del pecho, en la zona dolorida o tensa. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Relajate sobre la pelota y después deslizá el brazo hacia adelante por encima de la cabeza, como se muestra. Después deslizalo de vuelta hacia abajo y repetí.', 99651),
  ('PIQUE EN LA PARED - ABDUCCIÓN ISOMÉTRICA BILATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota', 'Parate de costado a una pared y elevá los brazos a 90 grados hacia los costados con los codos flexionados. Sostené un balón medicinal con peso con ambas manos y picá una pelota chica contra la pared con el brazo más cercano a la pared. Repetí el pique rápidamente mientras el otro brazo sostiene el segundo balón con peso.', 8230),
  ('PIQUE EN LA PARED 90/90 CON ROTACIONES - RI', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota', 'Parate de frente a una pared y elevá los brazos a 90 grados hacia el costado con el codo flexionado. Sostené un balón medicinal chico y picalo contra la pared. Repetí rápidamente el pique y la atajada.', 8255),
  ('PIQUE EN LA PARED EN ARCO', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota', 'Parate de frente a una pared y sostené el brazo con el codo estirado. Sostené un balón medicinal chico y picalo contra la pared mientras movés el brazo en un arco amplio a lo largo de la pared, como se muestra.', 8256),
  ('FLEXIÓN DE BRAZOS EN LA PARED - PELOTA', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota', 'Colocá una pelota contra una pared y hacé flexiones de brazos sosteniendo la pelota con ambas manos, como se muestra.', 8254),
  ('ROTACIÓN EXTERNA DE HOMBRO CON BANDA ELÁSTICA - SENTADO SOBRE PELOTA - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Banda elástica', 'Sentate sobre una pelota de ejercicios y equilibrate con ambos pies en el piso. Empezá sosteniendo una banda elástica al costado del cuerpo con el codo flexionado. La banda debe estar fijada del lado opuesto al brazo que hace el ejercicio. Empezá con la mano cerca del abdomen y después tirá de la banda hacia afuera. Volvé a la posición inicial y repetí. Colocá una toalla chica enrollada entre el brazo y el costado del cuerpo. Mantené el codo pegado al cuerpo todo el tiempo.', 7854),
  ('ROTACIÓN EXTERNA DE HOMBRO CON BANDA ELÁSTICA - SENTADO SOBRE PELOTA RE - UNA PIERNA', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Banda elástica', 'Sentate y equilibrate sobre una pierna mientras estás sentado sobre una pelota de ejercicios. Sosteniendo una banda elástica al costado del cuerpo con el codo flexionado, empezá con la mano cerca del abdomen y después tirá de la banda hacia afuera. Mantené el codo pegado al cuerpo todo el tiempo.', 7855),
  ('CÍRCULOS CON PELOTA - DE PIE', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Peso libre; Estabilización', 'Sostené una pelota chica u otro peso liviano por delante tuyo con el brazo extendido y hacé círculos con él.', 19775),
  ('MANCUERNAS Y PELOTA DE EJERCICIOS - PRESS DE PECHO EN PUENTE', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Peso libre; Estabilización', 'Empezá sentado sobre una pelota de ejercicios sosteniendo dos mancuernas. Después, activá los abdominales bajos, apretá los glúteos y caminá lentamente con los pies hacia adelante de modo que la cola se despegue de la superficie, formando un puente con el cuerpo. Mantené la cola elevada y en línea recta con la columna. Después, empujá las mancuernas hacia arriba extendiendo los codos. Bajá las mancuernas dejando que los codos se flexionen y repetí el movimiento de press de pecho.', 65354),
  ('MANCUERNAS Y PELOTA DE EJERCICIOS - APERTURAS DE PECHO', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Peso libre; Estabilización', 'Empezá sentado sobre una pelota de ejercicios sosteniendo dos mancuernas. Después, activá los abdominales bajos, apretá los glúteos y caminá lentamente con los pies hacia adelante de modo que la cola se despegue de la superficie, formando un puente con el cuerpo. Mantené la cola elevada y en línea recta con la columna. Sostené las mancuernas por encima del pecho con los codos completamente extendidos y bien arriba. Después, bajá lentamente las pesas hacia los costados y hacia el piso. Flexioná un poco los codos al bajar. No bajes todo lo que puedas: detenete aproximadamente a la altura del tronco, de modo que los codos no queden por debajo de la espalda. Volvé con los brazos a la posición inicial y repetí.', 65355),
  ('ADUCCIÓN ISOMÉTRICA CON PELOTA', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Isométrico', 'Colocá una pelota sobre una mesa y parate a un costado de la mesa. Cerrá el puño y apoyalo sobre la pelota. Después, llevá el omóplato hacia abajo y atrás mientras presionás hacia abajo sobre la pelota con el puño, y mantené. Relajá y repetí.', 83685),
  ('LANZAMIENTO DE PELOTA CON PESO - T EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Balón medicinal; Estabilización', 'Acostate boca abajo sosteniendo una pelota con peso. Ubicate de modo que el brazo pueda colgar por el borde de la camilla a unos 90 grados del costado del cuerpo, con el codo extendido. Lanzá la pelota hacia arriba y atajala rápido. Repetí.', 166245),
  ('AUTOMASAJE CON PELOTA - INFRAESPINOSO', NULL, true, 'activo', 'Hombro', 'Pelota; Movilización', 'Acostate en el piso y colocá una pelota en la parte de atrás del hombro, como se muestra. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Aplicá presión suave sobre la pelota. También podés mantener la presión y rotar el hombro hacia adentro y hacia afuera. No pases la pelota sobre zonas óseas.', 99568),
  ('PELOTA - SOLTAR Y ATAJAR - ABDUCCIÓN', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Empezá sosteniendo una pelota hacia el costado del hombro con el brazo extendido, como se muestra. Después, soltá la pelota para que caiga hacia el piso y bajá rápidamente el brazo y la mano para atajarla. Volvé a la posición inicial y repetí.', 78513),
  ('PELOTA - SOLTAR Y ATAJAR - ROTACIÓN EXTERNA EN ABDUCCIÓN', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Empezá sosteniendo una pelota hacia el costado del hombro, con el hombro en 90 grados de abducción y el codo flexionado a 90 grados. El codo debe quedar elevado y apuntando hacia el costado, con el antebrazo hacia adelante. Después, soltá la pelota para que caiga hacia el piso y dejá que el hombro rote rápidamente bajando el antebrazo y la mano para atajarla. Tratá de mantener el codo elevado a la altura del hombro durante el movimiento. Volvé a la posición inicial y repetí.', 78531),
  ('PELOTA - SOLTAR Y ATAJAR - ROTACIÓN EXTERNA EN FLEXIÓN', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Empezá sosteniendo una pelota por delante del hombro, con el hombro flexionado a 90 grados y el codo flexionado a 90 grados. El codo debe quedar elevado y apuntando hacia adelante, con el antebrazo hacia el costado. Después, soltá la pelota para que caiga hacia el piso y dejá que el hombro rote rápidamente bajando el antebrazo y la mano para atajarla. Tratá de mantener el codo elevado a la altura del hombro durante el movimiento. Volvé a la posición inicial y repetí.', 78526),
  ('PELOTA - SOLTAR Y ATAJAR - FLEXIÓN', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Empezá sosteniendo una pelota por delante del hombro con el brazo extendido, como se muestra. Después, soltá la pelota para que caiga hacia el piso y bajá rápidamente el brazo y la mano para atajarla. Volvé a la posición inicial y repetí.', 78524),
  ('FLEXIONES DE BRAZOS CON PELOTA', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Empezá de rodillas con una pelota de ejercicios adelante tuyo y caminá lentamente con los brazos hacia adelante hasta que la pelota quede debajo de los muslos. Después hacé flexiones de brazos, como se muestra.', 462),
  ('LANZAMIENTO DE PELOTA - POR ARRIBA', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'De pie, lanzá una pelota por encima del hombro contra una pared y atajala manteniendo el equilibrio. Podés progresar parándote con los pies más juntos.', 119350),
  ('LANZAMIENTO DE PELOTA - POR ABAJO', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'De pie, lanzá una pelota por abajo contra una pared y atajala manteniendo el equilibrio. Podés progresar parándote con los pies más juntos.', 119351),
  ('CAMINATA SOBRE PELOTA', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Posición inicial: empezá arrodillado frente a una pelota de ejercicios y apoyá el pecho sobre la pelota. Después empujate lentamente hacia adelante sobre la pelota y apoyá las manos en el piso. Caminá con las manos hacia adelante manteniendo la columna erguida. Volvé caminando a la posición inicial y repetí.', 457),
  ('PELOTA DE EJERCICIOS - FLEXIÓN BILATERAL DE HOMBROS', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Sentado sobre una pelota de ejercicios, activá los músculos abdominales y después elevá los brazos por encima de la cabeza. Bajá los brazos y repetí. Tratá de mantener la pelvis y la columna estables todo el tiempo.', 167027),
  ('PELOTA GIROSCÓPICA - ROTACIÓN INTERNA Y EXTERNA 90/90', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Poné en marcha el giro de una pelota giroscópica y después movés el brazo en rotación externa e interna mientras lo mantenés elevado a 90 grados de abducción.', 57430),
  ('PELOTA GIROSCÓPICA - ABDUCCIÓN', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras elevás el brazo hacia el costado con el codo estirado, como se muestra. Elevá hasta 90 grados, mantené y después bajá. Repetí manteniendo el giro de la pelota giroscópica.', 57642),
  ('PELOTA GIROSCÓPICA - REVÉS / LANZAMIENTO DE ESPALDAS', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras hacés lentamente un movimiento de revés como en tenis o un lanzamiento de disco con el hombro. Repetí manteniendo el giro de la pelota giroscópica.', 57455),
  ('PELOTA GIROSCÓPICA - DIAGONAL 1', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras movés el brazo en diagonal desde la boca, con la palma hacia la cara, hasta detrás del cuerpo con la palma mirando hacia atrás, como se muestra. Repetí manteniendo el giro de la pelota giroscópica todo el tiempo.', 57640),
  ('PELOTA GIROSCÓPICA - DIAGONAL 2', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras movés el brazo en diagonal desde el bolsillo opuesto hasta el brazo elevado hacia arriba y afuera, como si desenvainaras una espada. Mantené el giro de la pelota giroscópica todo el tiempo.', 57462),
  ('PELOTA GIROSCÓPICA - FLEXIÓN', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras elevás el brazo hacia adelante por delante del cuerpo con el codo estirado, como se muestra. Elevá hasta 90 grados, mantené y después bajá. Repetí manteniendo el giro de la pelota giroscópica.', 57643),
  ('PELOTA GIROSCÓPICA - DERECHA / LANZAMIENTO LATERAL', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras hacés lentamente un movimiento de derecha como en tenis o un lanzamiento lateral lento como en béisbol. Repetí manteniendo el giro de la pelota giroscópica.', 57457),
  ('PELOTA GIROSCÓPICA - LANZAMIENTO POR ENCIMA DE LA CABEZA', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras hacés lentamente un lanzamiento por encima del hombro, como el envío de un lanzador de béisbol, como se muestra. Repetí manteniendo el giro de la pelota giroscópica.', 57638),
  ('PELOTA GIROSCÓPICA - T EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Acostate boca abajo sobre una camilla o cama. Después, poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras movés lentamente el brazo hacia arriba y hacia el costado, con 90 grados en el hombro, como se muestra. Apretá el omóplato hacia abajo y hacia la columna durante el ejercicio. Repetí manteniendo el giro de la pelota giroscópica.', 57633),
  ('PELOTA GIROSCÓPICA - W EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Acostate boca abajo sobre una camilla o cama. Después, poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras elevás lentamente la mano y el codo flexionado hacia el techo, retrayendo además el omóplato, como se muestra. Mantené esta posición de retracción, después bajá el brazo y repetí. Mantené el giro de la pelota giroscópica todo el tiempo.', 57460),
  ('PELOTA GIROSCÓPICA - Y EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Acostate boca abajo sobre una camilla o cama. Después, poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras movés lentamente el brazo hacia arriba y adelante, en dirección a por encima de la cabeza, como se muestra. Apretá el omóplato hacia abajo y hacia la columna durante el ejercicio. Repetí manteniendo el giro de la pelota giroscópica.', 57458),
  ('PELOTA GIROSCÓPICA - RETRACCIÓN ESCAPULAR', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras elevás el brazo con el codo flexionado y el omóplato retraído, como se muestra. El omóplato debe quedar llevado hacia la columna y hacia abajo. Mantené el giro de la pelota giroscópica todo el tiempo.', 57461),
  ('PELOTA GIROSCÓPICA - FLEXIÓN EN DECÚBITO DORSAL', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Acostate boca arriba sobre una camilla o cama. Después, poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras sostenés el brazo estirado hacia el techo. Mantené el giro de la pelota giroscópica todo el tiempo.', 57634),
  ('PELOTA GIROSCÓPICA - LANZAMIENTO POR ABAJO', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras hacés un lanzamiento por abajo, como el envío de sóftbol o el movimiento de bowling, con el hombro. Repetí manteniendo el giro de la pelota giroscópica.', 57459),
  ('PLANCHA SOBRE BOSU INVERTIDO - PELOTA DE TENIS', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Hacé una plancha con un Bosu invertido, como se muestra. Pedile a alguien que tire una pelota de tenis sobre el Bosu invertido. Si lo hacés solo, podés apoyar la pelota de tenis a un costado del Bosu antes de ponerte en plancha. En posición de plancha, tratá de equilibrar y mover la pelota inclinando el Bosu hacia adelante y atrás y de lado a lado. Intentá llevar la pelota de tenis hasta el agujero central. Descansá y repetí.', 168278),
  ('FLEXIONES DE BRAZOS EN LA MESA CON BALÓN MEDICINAL', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Hacé una flexión de brazos sosteniendo un balón medicinal u otra superficie inestable apoyada sobre una mesa, como se muestra.', 8446),
  ('PELOTA DE MANÍ - FLEXIONES DE BRAZOS', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Empezá arrodillado con una pelota de maní adelante tuyo. Caminá con las manos hacia adelante de modo que la pelota quede debajo de los muslos. Mantené la espalda recta y usá los brazos para empujarte hacia arriba y hacia abajo, como se muestra.', 61509),
  ('T EN DECÚBITO VENTRAL SOBRE PELOTA - EXTENSIÓN CERVICAL Y TORÁCICA', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Acostate boca abajo sobre una pelota de ejercicios con los codos estirados y sosteniendo pesos libres chicos. Elevá lentamente los brazos hacia los costados. Al mismo tiempo, elevá el pecho y la cabeza. Volvé a la posición inicial y repetí.', 7860),
  ('FLEXIÓN DE BRAZOS - SUPERFICIE INESTABLE', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Hacé flexiones de brazos sobre una superficie inestable, como una almohadilla de espuma y un balón medicinal chico.', 7886),
  ('LANZAMIENTO DE PELOTA DE TENIS - ROTACIÓN EXTERNA - DECÚBITO VENTRAL', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Acostate boca abajo sosteniendo una pelota de tenis. Ubicate de modo que el hombro quede a 90 grados del costado del cuerpo y el codo flexionado a 90 grados, como se muestra. Levantá la pelota, soltala y después atajala rápido. Repetí.', 165867),
  ('LANZAMIENTO DE PELOTA DE TENIS - ROTACIÓN INTERNA - 90/90 - RI', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Acostate boca arriba sosteniendo una pelota de tenis. Ubicate de modo que el hombro quede a 90 grados del costado del cuerpo y el codo flexionado a 90 grados, como se muestra. Lanzá la pelota al aire y después atajala rápido. Repetí.', 166248),
  ('LANZAMIENTO DE PELOTA DE TENIS - T EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Hombro', 'Pelota; Estabilización', 'Acostate boca abajo sosteniendo una pelota de tenis. Ubicate de modo que el brazo pueda colgar por el borde de la camilla a unos 90 grados del costado del cuerpo, con el codo extendido. Lanzá la pelota hacia arriba y después atajala rápido. Repetí.', 166247),
  ('ATAJADA DE PELOTA CON PESO - T EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Acostado boca abajo con el codo estirado y sosteniendo una pelota chica, elevá el brazo hacia arriba en dirección al techo. Soltá la pelota en el aire y después atajala bajando rápidamente los brazos de vuelta a la posición inicial.', 7862),
  ('LANZAMIENTO DE PELOTA CON PESO - ROTACIÓN EXTERNA - DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Acostate boca abajo sosteniendo una pelota con peso. Ubicate de modo que el hombro quede a 90 grados del costado del cuerpo y el codo flexionado a 90 grados, como se muestra. Levantá la pelota, soltala y después atajala rápido. Repetí.', 165866),
  ('LANZAMIENTO DE PELOTA CON PESO - ROTACIÓN INTERNA - 90/90 - RI', NULL, true, 'fortalecimiento', 'Hombro', 'Pelota; Estabilización', 'Acostate boca arriba sosteniendo una pelota con peso. Ubicate de modo que el hombro quede a 90 grados del costado del cuerpo y el codo flexionado a 90 grados, como se muestra. Lanzá la pelota al aire y después atajala rápido. Repetí.', 166246),
  ('BOSU - FLEXIÓN DE BRAZOS MODIFICADA UNILATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Bosu; Estabilización', 'Arrodillado, apoyá las manos sobre el Bosu que está adelante tuyo. Después apoyá una mano en el piso, a un costado, y hacé una flexión de brazos. Volvé a la posición inicial y repetí.', 159106),
  ('CLX - ABDUCCIÓN BILATERAL DE HOMBROS', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Parate con un pie adelante pisando el centro de la banda CLX. Enganchá los aros de las puntas de la CLX en las manos. Después, elevá los brazos hacia los costados manteniendo el codo estirado todo el tiempo. Bajá y repetí.', 40130),
  ('CLX - PRESS DE PECHO', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Empezando con los brazos al costado del cuerpo y los codos flexionados, empujá la banda hacia adelante por delante del cuerpo estirando los codos.', 40089),
  ('CLX - LANZAMIENTO INVERSO CON DOBLE VECTOR', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Parate con un pie adelante sobre el centro de la CLX. Enganchá un aro de la CLX en la mano contraria y el otro aro en el brazo del mismo lado. Movés el brazo y el cuerpo con un gesto de lanzamiento. Movete de manera lenta y controlada.', 40103),
  ('CLX - ABRAZO DINÁMICO', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Pasá la CLX por detrás de la espalda y sostené las puntas separadas por dos o tres aros. Elevá los brazos a la altura del pecho. Después, tirá de las puntas hacia adelante con los codos flexionados, como en posición de abrazo.', 40105),
  ('CLX - EMPUJE RESISTIDO', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Empezá parado sobre el centro de la CLX con un pie y colocá los aros de las puntas en las manos. Después, dá un paso adelante hasta una estocada mientras extendés los brazos por delante del cuerpo con un gesto de empuje. Volvé a la posición inicial y repetí.', 40125),
  ('CLX - FLEXIÓN DE BRAZOS RESISTIDA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Colocá la CLX alrededor de la parte alta de la espalda y enganchada en las manos, como se muestra. Acostado boca abajo, usá los brazos para empujarte hacia arriba, como se muestra, y después bajá. Mantené las puntas de los pies en contacto con el piso y la espalda recta todo el tiempo.', 40126),
  ('CLX - LANZAMIENTO INVERSO', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Parate con un pie adelante y enganchá un aro de la CLX en ese pie. Enganchá la otra punta en la mano contraria. Movés el brazo y el cuerpo con un gesto de lanzamiento. Movete de manera lenta y controlada.', 40128),
  ('BANDA ELÁSTICA - ABRAZO DINÁMICO', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Empezá con una banda elástica pasada por detrás de la espalda y sosteniendo las puntas con las manos. Después, con los brazos separados del cuerpo, llevá las manos y los brazos hacia adelante, como se muestra. Los codos deben estar levemente flexionados todo el tiempo.', 6994),
  ('BANDA ELÁSTICA - FLEXIÓN DE HOMBRO - AUTOFIJADA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Acostate boca arriba y sostené o fijá una banda elástica a la altura de la cintura. Tirá de la banda hacia arriba y por encima de la cabeza con el brazo que trabajás, como se muestra. Volvé a la posición inicial y repetí.', 183373),
  ('BANDA ELÁSTICA - FLEXIÓN DE HOMBRO DE 90 A POR ENCIMA DE LA CABEZA - AUTOFIJADA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Acostate boca arriba y sostené o fijá una banda elástica a la altura de la cintura. Empezá con el otro brazo estirado hacia arriba y después elevalo por encima de la cabeza, como se muestra. Volvé a la posición inicial y repetí.', 183375),
  ('BANDA ELÁSTICA - FLEXIÓN DE HOMBRO HASTA 90 - AUTOFIJADA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Acostate boca arriba y sostené o fijá una banda elástica a la altura de la cintura. Empezá con el otro brazo al costado del cuerpo y después tirá de la banda hacia arriba hasta que quede estirado hacia el techo, como se muestra. Bajá y repetí.', 183374),
  ('PRESS DE PECHO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Sentate en una silla. Pasá una banda elástica alrededor del respaldo de la silla y sostené las puntas, como se muestra. Empezá con los codos flexionados y los brazos al costado del cuerpo, y después empujá la banda hacia adelante por delante del cuerpo estirando los codos. Volvé a la posición inicial y repetí.', 262),
  ('FLEXIÓN CON BANDA ELÁSTICA - AUTOFIJADA', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Banda elástica', 'Sosteniendo una banda elástica adelante tuyo y sobre la pierna con el brazo sano, tirá de la banda hacia arriba, en dirección al techo, con el brazo afectado, como se muestra.', 474),
  ('ROTACIÓN INTERNA CON ABDUCCIÓN CON BANDA ELÁSTICA - RI 90/90', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Empezá sosteniendo una banda elástica o cuerda deportiva con el brazo elevado a 90 grados del costado del cuerpo y el codo flexionado a 90 grados. El antebrazo debe apuntar hacia arriba en la posición inicial, como se muestra. Después, rotá el hombro hacia adelante de modo que el antebrazo quede horizontal al piso. Volvé a la posición inicial y repetí.', 8390),
  ('ADUCCIÓN CON BANDA ELÁSTICA POR ENCIMA DE LA CABEZA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Sosteniendo una banda elástica por encima de la cabeza con los codos estirados, tirá de la banda hacia abajo, hacia el costado del cuerpo, como se muestra.', 476),
  ('DIAGONAL DE HOMBRO CON BANDA ELÁSTICA - FLEXIÓN Y ADUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Fijá la punta de una banda elástica (atada con un nudo y colocada detrás de la puerta) en la posición baja de una puerta. Sosteniendo la banda al costado del cuerpo, tirá de ella hacia arriba, en dirección al hombro contrario. La mano debe arrancar con el pulgar hacia atrás y terminar con el pulgar hacia arriba.', 204),
  ('DIAGONAL DE HOMBRO CON BANDA ELÁSTICA - EXTENSIÓN Y ADUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Atá la punta de una banda elástica con un nudo, colocala en una posición alta del lado opuesto de una puerta y cerrá la puerta sobre ella. Empezá sosteniendo la otra punta de la banda bien arriba y hacia el costado. Después, tirá de la banda hacia abajo, en dirección al muslo contrario. Volvé a la posición inicial y repetí. La mano debe arrancar con el pulgar hacia arriba y terminar con el pulgar hacia atrás.', 206),
  ('DIAGONAL DE HOMBRO CON BANDA ELÁSTICA - FLEXIÓN Y ADUCCIÓN - AUTOFIJADA', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Banda elástica', 'Empezá sosteniendo una banda elástica cruzada hacia el lado contrario para fijarla con el brazo sano. Después, con el brazo afectado, llevá la otra punta de la banda hacia arriba y hacia el lado opuesto, como se muestra.', 6995),
  ('EXTENSIÓN DE HOMBRO CON BANDA ELÁSTICA - AUTOFIJADA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Sosteniendo una banda elástica por delante tuyo con los brazos, tirá de la banda hacia abajo, en dirección al piso, con el brazo afectado, como se muestra.', 6841),
  ('ROTACIÓN EXTERNA - BANDA ELÁSTICA - RE INESTABLE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Parate y equilibrate sobre una superficie inestable, como una almohadilla de espuma, una toalla doblada o una tabla de balanceo, mientras hacés este ejercicio. Empezá sosteniendo una banda elástica con el codo pegado al cuerpo y flexionado a 90 grados, como se muestra. El antebrazo debe apuntar hacia adelante en la posición inicial. Después, rotá el hombro hacia atrás de modo que el antebrazo apunte hacia el costado. Mantené el omóplato retraído y hacia abajo todo el tiempo.', 8422),
  ('GERIÁTRICO - PRESS POR ENCIMA DE LA CABEZA CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Sentate en una silla, pasá una banda elástica larga por debajo de los pies y sostené las puntas con las manos. Empezá con los codos flexionados y cerca del costado del cuerpo. Elevá las manos por encima de la cabeza mientras extendés los codos. Bajá a la posición inicial y repetí.', 124566),
  ('SILLA DE RUEDAS - CURL DE BÍCEPS CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Fijá una punta de una banda elástica al pie y sostené la otra punta con la mano. Movés la mano hacia arriba flexionando el codo. Bajá y repetí.', 104692),
  ('SILLA DE RUEDAS - PRESS POR ENCIMA DE LA CABEZA CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Fijá una punta de una banda elástica a la manija de empuje de la silla de ruedas y sostené la otra punta con la mano. Empezá con el codo flexionado y la mano al lado de la oreja. Después, elevá la mano por encima de la cabeza mientras extendés el codo. Bajá a la posición inicial, a la altura de la oreja, y repetí.', 104772),
  ('SILLA DE RUEDAS - PRESS POR ENCIMA DE LA CABEZA CON BANDA ELÁSTICA - BILATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica', 'Pasá una banda elástica alrededor del respaldo de la silla de ruedas de modo que las manijas de empuje la sujeten. Empezá sosteniendo las puntas de la banda con las manos, con los codos flexionados y las manos al lado de las orejas. Elevá las manos por encima de la cabeza mientras extendés los codos. Bajá a la posición inicial, a la altura de las orejas, y repetí.', 104776),
  ('CAMINATAS ISOMÉTRICAS CON BANDA ELÁSTICA - ABDUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Isométrico; Estabilización', 'Atá la punta de una banda elástica con un nudo, colocala a la altura de la cintura del otro lado de una puerta y cerrá la puerta sobre ella. Empezá sosteniendo la banda al costado del cuerpo, con el brazo que trabajás del lado contrario a la puerta. Después, dá pasos laterales alejándote de la puerta sin permitir que el brazo se mueva. Mantené, dá pasos hacia la puerta para volver a la posición inicial y repetí.', 147544),
  ('CAMINATAS ISOMÉTRICAS CON BANDA ELÁSTICA - ADUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Isométrico; Estabilización', 'Atá la punta de una banda elástica con un nudo, colocala a la altura de la cintura del otro lado de una puerta y cerrá la puerta sobre ella. Empezá sosteniendo la banda al costado del cuerpo, con el brazo que trabajás del lado de la puerta. Después, dá pasos laterales alejándote de la puerta sin permitir que el brazo se mueva. Mantené, dá pasos hacia la puerta para volver a la posición inicial y repetí.', 147325),
  ('CAMINATAS ISOMÉTRICAS CON BANDA ELÁSTICA - EXTENSIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Isométrico; Estabilización', 'Atá la punta de una banda elástica con un nudo, colocala a la altura de la cintura del otro lado de una puerta y cerrá la puerta sobre ella. Empezá sosteniendo la banda al costado del cuerpo, de frente a la puerta. Después, dá pasos hacia atrás alejándote de la puerta sin permitir que el brazo se mueva. Mantené, dá un paso adelante para volver a la posición inicial y repetí.', 147327),
  ('CAMINATAS ISOMÉTRICAS CON BANDA ELÁSTICA - FLEXIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Isométrico; Estabilización', 'Atá la punta de una banda elástica con un nudo, colocala a la altura de la cintura del otro lado de una puerta y cerrá la puerta sobre ella. Empezá sosteniendo la banda al costado del cuerpo, de espaldas a la puerta. Después, dá pasos hacia adelante alejándote de la puerta sin permitir que el brazo se mueva. Mantené, dá un paso atrás para volver a la posición inicial y repetí.', 147326),
  ('CAMINATAS ISOMÉTRICAS CON BANDA ELÁSTICA - ROTACIÓN INTERNA - RI', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Isométrico; Estabilización', 'Atá la punta de una banda elástica con un nudo, colocala a la altura del codo del otro lado de una puerta y cerrá la puerta sobre ella. Empezá sosteniendo la banda al costado del cuerpo con el codo flexionado a 90 grados, con el brazo que trabajás del lado de la puerta. Después, dá pasos laterales alejándote de la puerta sin permitir que el brazo se mueva. Mantené, dá un paso atrás para volver a la posición inicial y repetí.', 147324),
  ('BRUGGER - ROTACIÓN EXTERNA Y RETRACCIÓN ESCAPULAR CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá parado bien derecho, con las palmas enfrentadas y los codos flexionados a 90 grados. Extendé los codos contra la resistencia de la banda elástica mientras llevás las manos por detrás de las caderas. Durante el movimiento, apretá los omóplatos hacia abajo y atrás. Mantené, después volvé a la posición inicial y repetí.', 71731),
  ('CLX - ROTACIÓN EXTERNA BILATERAL - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Colocá las manos en dos aros consecutivos con los codos flexionados. Después, separá las manos una de la otra. Mantené los codos cerca del costado del cuerpo todo el tiempo.', 40090),
  ('CLX - PLANCHA LATERAL CON ROTACIÓN EXTERNA - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Colocá los aros de la CLX en cada mano dejando aros de separación en el medio. Acostado de costado, elevá el cuerpo apoyándote sobre el codo y los pies. Tratá de mantener la columna recta. Después, mantené el codo flexionado a 90 grados mientras elevás el brazo de arriba, como se muestra. Mantené el codo cerca del costado del cuerpo todo el tiempo.', 40137),
  ('BANDA ELÁSTICA - RE - RETRACCIÓN ESCAPULAR - PALMAS ARRIBA - VISTA POSTERIOR', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica con las palmas hacia arriba y los codos flexionados a 90 grados al costado del cuerpo. Después, separá las manos una de la otra. Los omóplatos deben acercarse entre sí mientras los hombros rotan hacia afuera (los antebrazos pasan de apuntar hacia adelante a apuntar hacia el costado). Volvé a la posición inicial y repetí.', 135814),
  ('BANDA ELÁSTICA - EXTENSIÓN Y RETRACCIÓN - ÁNGELES EN LA NIEVE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica con ambos brazos estirados por delante del cuerpo, con los codos extendidos y las palmas hacia arriba. Después, retraé los omóplatos y tirá de la banda hacia abajo y atrás, hacia el costado del cuerpo. Mantené esta posición mientras elevás los brazos en un arco desde el costado del cuerpo hasta que ambos queden por encima de la cabeza. Después, bajá los brazos de modo que vuelvan a quedar estirados por delante del cuerpo y repetí.', 109446),
  ('BANDA ELÁSTICA - ABDUCCIÓN HORIZONTAL', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica o tubo con el brazo estirado por delante y cruzado hacia el lado contrario del cuerpo. Después, tirá de la banda o cuerda en forma horizontal y hacia afuera, como se muestra. El codo debe estar estirado o levemente flexionado todo el tiempo.', 19041),
  ('BANDA ELÁSTICA - ADUCCIÓN HORIZONTAL', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica o tubo con el brazo estirado hacia el costado. Después, tirá de la banda o cuerda en forma horizontal y cruzando por delante del cuerpo, como se muestra. El codo debe estar estirado o levemente flexionado todo el tiempo.', 19042),
  ('BANDA ELÁSTICA - RETRACCIÓN ESCAPULAR - REMO 90, ROTACIÓN EXTERNA Y ARCO POR ENCIMA DE LA CABEZA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica estirada por delante del cuerpo con ambas palmas hacia abajo, como se muestra. Tirá de la banda hacia atrás flexionando los codos y apretando los omóplatos (escápulas). Los codos deben quedar a unos 90 grados del costado del cuerpo, con los antebrazos apuntando hacia adelante. Después, rotá los hombros hacia afuera de modo que los antebrazos apunten hacia arriba. Luego elevá los brazos por encima de la cabeza. Volvé a la posición inicial y repetí.', 109447),
  ('BANDA ELÁSTICA - ABDUCCIÓN HORIZONTAL BILATERAL - PALMAS ARRIBA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica con las palmas hacia arriba y estirada por delante del pecho, con los codos extendidos, como se muestra. Después, separá los brazos hacia los costados. Volvé a la posición inicial y repetí.', 149309),
  ('DIAGONAL CON BANDA ELÁSTICA - FLEXIÓN Y ABDUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Atá la punta de una banda elástica con un nudo, colocala a la altura de la rodilla del lado opuesto de una puerta y cerrá la puerta sobre ella. Sostené la otra punta de la banda cruzada sobre la mitad inferior del cuerpo y después tirá hacia arriba y hacia afuera, en dirección al lado contrario. La mano debe arrancar con el pulgar hacia abajo y terminar con el pulgar hacia arriba. Repetí.', 205),
  ('BANDA ELÁSTICA - RE - PALMAS ARRIBA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica con las palmas hacia arriba y los codos flexionados a 90 grados al costado del cuerpo. Después, separá las manos una de la otra. Los omóplatos deben acercarse entre sí mientras los hombros rotan hacia afuera (los antebrazos pasan de apuntar hacia adelante a apuntar hacia el costado). Volvé a la posición inicial y repetí.', 101861),
  ('BANDA ELÁSTICA - RE - PALMAS ARRIBA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá colocando una toalla de mano chica enrollada entre los brazos y el costado de las costillas, como se muestra. Sostené una banda elástica con las palmas hacia arriba y los codos flexionados a 90 grados al costado del cuerpo. Después, separá las manos una de la otra. Los omóplatos deben acercarse entre sí y bajar mientras los hombros rotan hacia afuera (los antebrazos pasan de apuntar hacia adelante a apuntar hacia el costado). Volvé a la posición inicial y repetí.', 135795),
  ('ROTACIÓN EXTERNA CON BANDA ELÁSTICA - PARADO SOBRE BOSU INVERTIDO - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Parate y equilibrate sobre un Bosu invertido. Sosteniendo una banda elástica al costado del cuerpo con el codo flexionado, empezá con la mano cerca del abdomen y después tirá de la banda hacia afuera. Mantené el codo pegado al cuerpo todo el tiempo.', 8077),
  ('ROTACIÓN EXTERNA CON ABDUCCIÓN CON BANDA ELÁSTICA - RE 90/90', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica o cuerda deportiva con el brazo elevado a 90 grados del costado del cuerpo y el codo flexionado a 90 grados. El antebrazo debe apuntar hacia adelante en la posición inicial, como se muestra. Después, rotá el hombro hacia atrás de modo que el antebrazo apunte hacia arriba. Mantené el omóplato retraído y hacia abajo todo el tiempo.', 7851),
  ('ROTACIÓN EXTERNA CON FLEXIÓN CON BANDA ELÁSTICA - RE 90/90', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica o cuerda deportiva con el brazo elevado a 90 grados de flexión hacia adelante y el codo flexionado a 90 grados. El antebrazo debe apuntar hacia el costado en la posición inicial, como se muestra. Después, llevá el antebrazo hacia arriba de modo que apunte al techo, como se muestra. Mantené el omóplato retraído y hacia abajo todo el tiempo.', 19047),
  ('ROTACIÓN INTERNA CON FLEXIÓN CON BANDA ELÁSTICA - RI 90/90', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica o cuerda deportiva con el brazo elevado a 90 grados de flexión hacia adelante y el codo flexionado a 90 grados. El antebrazo debe apuntar hacia arriba en la posición inicial, como se muestra. Después, llevá el antebrazo hacia abajo de modo que apunte hacia el costado, como se muestra.', 19048),
  ('CAMINATAS ISOMÉTRICAS CON BANDA ELÁSTICA - ROTACIÓN EXTERNA - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Atá la punta de una banda elástica con un nudo, colocala a la altura del codo del otro lado de una puerta y cerrá la puerta sobre ella. Empezá sosteniendo la banda al costado del cuerpo con el codo flexionado a 90 grados, con el brazo que no trabajás del lado de la puerta. Después, dá pasos laterales alejándote de la puerta sin permitir que el brazo se mueva. Mantené, dá un paso atrás para volver a la posición inicial y repetí.', 147323),
  ('PRESS MILITAR CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Sentate en una silla, pasá una banda elástica larga por debajo de los pies y sostené las puntas con las manos. Empezá con los codos flexionados y cerca del costado del cuerpo. Elevá las manos por encima de la cabeza mientras extendés el codo. Bajá a la posición inicial y repetí.', 125287),
  ('REMO CON BANDA ELÁSTICA - ABDUCCIÓN Y RE - AUTOFIJADO', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Fijá la punta de una banda elástica por delante del pecho con el brazo sano. Después, empezá con el brazo afectado también estirado por delante del pecho y tirá de la banda hacia vos dejando que el codo se flexione. Mantené el codo a 90 grados del costado del cuerpo. Después, rotá el hombro hacia afuera de modo que el antebrazo apunte al techo.', 20758),
  ('REMO CON BANDA ELÁSTICA - EN ABDUCCIÓN - AUTOFIJADO', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Fijá la punta de una banda elástica por delante del pecho con el brazo sano. Después, empezá con el brazo afectado también estirado por delante del pecho y tirá de la banda hacia vos dejando que el codo se flexione. Mantené el codo a 90 grados del costado del cuerpo todo el tiempo.', 20757),
  ('REMO CON BANDA ELÁSTICA - AUTOFIJADO', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Fijá la punta de una banda elástica por delante del pecho con el brazo sano. Después, empezá con el brazo afectado también estirado por delante del pecho y tirá de la banda hacia el costado del cuerpo dejando que el codo se flexione.', 20756),
  ('REMOS CON BANDA ELÁSTICA - 45 GRADOS DE ABDUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Atá con un nudo la parte del medio de una banda elástica, colocala a la altura del codo del lado opuesto de una puerta y cerrá la puerta sobre ella. Empezá sosteniendo las puntas de la banda con ambas manos y tirá hacia atrás flexionando los codos. Volvé a la posición inicial y repetí. Mantené los codos a unos 45 grados del cuerpo todo el tiempo.', 10318),
  ('REMOS CON BANDA ELÁSTICA - 90 GRADOS DE ABDUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Atá con un nudo la parte del medio de una banda elástica, colocala a la altura del abdomen del lado opuesto de una puerta y cerrá la puerta sobre ella. Sostené las puntas de la banda con ambas manos y después llevá los codos hacia atrás mientras los flexionás. Mantené los codos elevados, con los hombros a unos 90 grados del costado del cuerpo. Volvé a la posición inicial y repetí.', 214),
  ('REMOS CON BANDA ELÁSTICA - RE 90', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Fijá la punta de una banda elástica (atada con un nudo y colocada detrás de la puerta) en la posición media de una puerta. Sostené las puntas de la banda con ambas manos, elevá los codos hasta 90 grados en el hombro y después tirá de las bandas hacia atrás dejando que los codos se flexionen hasta quedar alineados con el cuerpo. Después, rotá los hombros hacia atrás de modo que las palmas queden apuntando hacia adelante. Invertí los pasos y repetí.', 215),
  ('REMOS CON BANDA ELÁSTICA - SENTADO', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Pasá una banda elástica alrededor de la pata de una mesa y sostené las puntas con ambas manos. Empezá tirando de la banda hacia vos mientras flexionás los codos. Mantené los codos cerca del costado del cuerpo. Volvé a la posición inicial y repetí.', 119352),
  ('SERRATO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Pasá una banda elástica alrededor de la parte alta de la espalda y sostené una punta, como se muestra. Acostate boca arriba con los brazos extendidos por delante del cuerpo y estirados hacia el techo. Manteniendo los codos estirados, protraé el omóplato hacia adelante en dirección al techo. Mantené los codos estirados todo el tiempo.', 8449),
  ('SERRATO CON BANDA ELÁSTICA A 120 GRADOS', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Pasá una banda elástica alrededor de la parte alta de la espalda y sostené una punta, como se muestra. Acostate boca arriba con los brazos extendidos por delante del cuerpo y hacia el techo, a 120 grados de flexión. Manteniendo los codos estirados, protraé el omóplato hacia adelante en dirección al techo. Mantené los codos estirados todo el tiempo.', 8448),
  ('DESCENSO DE HOMBRO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Fijá la punta de una banda elástica (atada con un nudo y colocada detrás de la puerta) en la posición alta de una puerta. Empezá sosteniendo la banda con la mano y con el hombro encogido hacia arriba y el codo estirado. Después, empujá la mano hacia abajo para llevar la banda en dirección al piso. Volvé lentamente a la posición inicial y repetí.', 207),
  ('DIAGONAL DE HOMBRO CON BANDA ELÁSTICA - EXTENSIÓN Y ABDUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Atá la punta de una banda elástica con un nudo, colocala a la altura de la cabeza del lado opuesto de una puerta y cerrá la puerta sobre ella. Empezá sosteniendo la banda cruzada sobre la mitad superior del cuerpo y después tirá hacia abajo y cruzando hacia el otro lado. Volvé a la posición inicial y repetí. La mano debe arrancar con el pulgar hacia arriba y terminar con el pulgar hacia abajo.', 4667),
  ('ROTACIÓN EXTERNA - RE 90/90 - BOSU - INESTABLE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Parate y equilibrate sobre un Bosu invertido con las rodillas levemente flexionadas mientras hacés este ejercicio. Empezá sosteniendo una banda elástica con el brazo elevado a 90 grados del costado del cuerpo y el codo flexionado a 90 grados. El antebrazo debe apuntar hacia adelante en la posición inicial, como se muestra. Después, rotá el hombro hacia atrás de modo que el antebrazo apunte hacia arriba. Mantené el omóplato retraído y hacia abajo todo el tiempo.', 7853),
  ('ROTACIÓN EXTERNA - RE 90/90 - INESTABLE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Parate y equilibrate sobre una superficie inestable, como una almohadilla de espuma, una toalla doblada o una tabla de balanceo, mientras hacés este ejercicio. Empezá sosteniendo una banda elástica con el brazo elevado a 90 grados del costado del cuerpo y el codo flexionado a 90 grados. El antebrazo debe apuntar hacia adelante en la posición inicial, como se muestra. Después, rotá el hombro hacia atrás de modo que el antebrazo apunte hacia arriba. Mantené el omóplato retraído y hacia abajo todo el tiempo.', 7852),
  ('ROTACIÓN EXTERNA CON FLEXIÓN - BANDA ELÁSTICA - RE 90/90', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Sostené una banda elástica como se muestra. Sentado y con el codo apoyado a 90 grados hacia adelante respecto del cuerpo, rotá el hombro de modo que el antebrazo apunte hacia arriba y después volvé a bajarlo, como se muestra.', 19778),
  ('GERIÁTRICO - ABDUCCIÓN HORIZONTAL BILATERAL CON BANDA ELÁSTICA - RETRACCIÓN ESCAPULAR', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica por delante del pecho con los codos estirados. Después, separá los brazos hacia los costados mientras apretás los omóplatos entre sí. Volvé a la posición inicial y repetí.', 124567),
  ('GERIÁTRICO - PRESS DE PECHO CON BANDA ELÁSTICA - GOLPES ALTERNADOS', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Sentado en una silla, pasá una banda elástica larga por detrás de la espalda y sostené ambas puntas. Empezá con los codos flexionados y después extendé un brazo hacia adelante por delante del cuerpo hasta estirar el codo. Volvé a la posición inicial y después repetí con el otro brazo. Repetí alternando los lados.', 124516),
  ('GERIÁTRICO - ROTACIÓN EXTERNA CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica con las palmas hacia arriba y los codos flexionados a 90 grados al costado del cuerpo. Apretá los omóplatos hacia atrás y abajo y mantené esta posición durante el ejercicio. Mientras sostenés la banda, separá las manos una de la otra de modo que los antebrazos pasen de apuntar hacia adelante a apuntar hacia el costado, como se muestra. Volvé a la posición inicial y repetí.', 124565),
  ('ROTACIÓN INTERNA CON FLEXIÓN - BANDA ELÁSTICA - RI 90/90', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Sostené una banda elástica como se muestra. Sentado y con el codo apoyado a 90 grados hacia adelante respecto del cuerpo, rotá el hombro de modo que el antebrazo apunte hacia el costado y después volvé a la posición de arriba, como se muestra.', 19780),
  ('ELEVACIONES DE HOMBRO CON RETRACCIÓN ESCAPULAR - BANDA CERRADA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Con una banda cerrada alrededor de las muñecas y los codos flexionados, separá las muñecas una de la otra mientras juntás los omóplatos. Mantené esta posición mientras elevás los brazos por encima de la cabeza y después bajá. Repetí.', 65801),
  ('RETRACCIONES ESCAPULARES - W CON BANDA ELÁSTICA - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Sosteniendo una banda elástica con ambas manos, tirá de la banda hacia atrás mientras flexionás los codos y retraés los omóplatos (escápulas), como formando la letra W con los brazos, como se muestra. Mantené, después volvé a la posición inicial y repetí.', 8396),
  ('RETRACCIONES ESCAPULARES - W CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica con las palmas hacia adelante y los codos flexionados, como se muestra. Después, separá los brazos hacia los costados. Los omóplatos (escápulas) deben acercarse entre sí durante el ejercicio y después volver a la posición original junto con los brazos.', 18690),
  ('RETRACCIONES ESCAPULARES - W CON BANDA ELÁSTICA - PALMAS ARRIBA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica con las palmas hacia arriba y los codos flexionados a 90 grados al costado del cuerpo. Después, separá las manos una de la otra. Los omóplatos (escápulas) deben acercarse entre sí mientras los codos se alejan del costado del cuerpo, formando una W con los brazos. Volvé a la posición inicial y repetí.', 101849),
  ('ROTACIÓN EXTERNA EXCÉNTRICA DE HOMBRO - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Acostate boca arriba y fijá una banda elástica al pie mientras sostenés la otra punta con el brazo afectado. Con la rodilla flexionada, rotá el brazo hasta la posición 90/90, como se muestra. Después, estirá la pierna y bajá el brazo de modo que rote hacia abajo de manera suave y controlada. Repetí.', 36143),
  ('FLEXIÓN DE HOMBRO - BANDA ELÁSTICA CERRADA - POR ENCIMA DE LA CABEZA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Colocá una banda elástica cerrada alrededor de las muñecas. Empezá con los brazos al costado del cuerpo y después retraé los omóplatos. Mantené esta posición mientras elevás ambos brazos hacia adelante y por encima de la cabeza. Bajá y repetí.', 153696),
  ('FLEXIÓN DE HOMBRO A 90 GRADOS - BANDA ELÁSTICA CERRADA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Colocá una banda elástica cerrada alrededor de las muñecas. Empezá con los brazos al costado del cuerpo y después retraé los omóplatos. Mantené esta posición mientras elevás ambos brazos hacia adelante hasta la altura de los hombros. Bajá y repetí.', 153686),
  ('CUERDA DEPORTIVA - ADUCCIÓN HORIZONTAL', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo una banda elástica o tubo con el brazo estirado hacia el costado. Después, tirá de la banda o cuerda en forma horizontal y cruzando por delante del cuerpo hasta la línea media, como se muestra. Volvé a la posición inicial y repetí. El codo debe estar estirado o levemente flexionado todo el tiempo.', 149303),
  ('CUERDA DEPORTIVA - PRESS MILITAR', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Empezá sosteniendo las puntas de una cuerda deportiva o banda elástica. Después, parate sobre el centro de la cuerda o banda. Flexioná los codos para hacer un curl de bíceps con las palmas hacia arriba. Después, rotá las manos de modo que las palmas queden hacia adelante mientras llevás los codos hacia atrás. Las manos deben quedar cerca de las orejas. Luego elevá las manos por encima de la cabeza extendiendo los codos. Mantené esta posición y después bajá otra vez a la altura de las orejas. Repetí.', 65744),
  ('DECÚBITO DORSAL - ABDUCCIÓN HORIZONTAL CON BANDA ELÁSTICA - PALMAS ARRIBA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Acostate boca arriba sosteniendo una banda elástica hacia el techo, con los codos estirados y las palmas hacia arriba. Después, separá los brazos hacia el piso, como se muestra. Los codos deben estar estirados todo el tiempo. Volvé a la posición inicial y repetí.', 183376),
  ('SILLA DE RUEDAS - ABRAZO DINÁMICO - APERTURAS', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Pasá una banda elástica por detrás de la espalda y sostené las puntas. Elevá los brazos a la altura del pecho y tirá de las puntas hacia adelante con los codos flexionados, como en posición de abrazo. Llevá los brazos de vuelta hacia los costados y repetí.', 104724),
  ('SILLA DE RUEDAS - PRESS DE PECHO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Pasá una banda elástica alrededor del respaldo de la silla de ruedas y, sentado, sostené las puntas de la banda con las manos. Empezá extendiendo ambos brazos hacia adelante al mismo tiempo mientras estirás los codos. Volvé a la posición inicial y repetí.', 104720),
  ('SILLA DE RUEDAS - GOLPES DE SERRATO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Sentado en la silla de ruedas, pasá una banda elástica alrededor de la manija de empuje de la silla y sostené la otra punta con la mano. Empezá extendiendo el brazo hacia adelante por delante del cuerpo con el codo estirado y después protraé el omóplato hacia adelante de modo que la mano y el brazo lleguen unos centímetros más adelante. Volvé a la posición inicial y repetí. Mantené los codos estirados todo el tiempo.', 104698),
  ('SILLA DE RUEDAS - GOLPES DE SERRATO CON BANDA ELÁSTICA - PLANO ESCAPULAR', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Sentado en la silla de ruedas, pasá una banda elástica alrededor de la manija de empuje de la silla y sostené la otra punta con la mano. Empezá extendiendo el brazo hacia adelante por delante del cuerpo a unos 120 grados de elevación del hombro, como se muestra. Con el codo estirado, protraé el omóplato hacia adelante de modo que la mano y el brazo lleguen unos centímetros más adelante. Volvé a la posición inicial y repetí. Mantené los codos estirados todo el tiempo.', 104717),
  ('SILLA DE RUEDAS - ROTACIÓN EXTERNA DE HOMBRO CON BANDA ELÁSTICA - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Fijá una punta de una banda elástica al apoyabrazos de la silla de ruedas y sostené la otra punta con la mano del lado contrario. Colocá una toalla chica doblada entre el brazo y el costado del pecho, como se muestra. Flexioná el codo a 90 grados y mantenelo así todo el tiempo. Empezá tirando de la banda alejándola del abdomen mientras rotás el hombro hacia afuera, después volvé a la posición inicial y repetí.', 104709),
  ('SILLA DE RUEDAS - ROTACIÓN INTERNA DE HOMBRO CON BANDA ELÁSTICA - RI', NULL, true, 'fortalecimiento', 'Hombro', 'Banda elástica; Estabilización', 'Fijá una punta de una banda elástica al apoyabrazos de la silla de ruedas y sostené la otra punta con la mano. Colocá una toalla chica doblada entre el brazo y el costado del pecho, como se muestra. Flexioná el codo a 90 grados y mantenelo así todo el tiempo. Empezá tirando de la banda hacia el abdomen mientras rotás el hombro hacia adentro, después volvé a la posición inicial y repetí.', 104705),
  ('FLEXIÓN DE HOMBRO - PALMAS ABAJO - BASTÓN - BANDA ELÁSTICA', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Banda elástica; Bastón', 'Fijá las dos puntas de una banda elástica a un bastón y pisá la parte del medio de la banda con los pies, como se muestra. Sostené el bastón con las palmas hacia abajo, los brazos a la altura de la cintura y los codos estirados. Elevá los brazos hacia adelante y arriba con los codos estirados todo el tiempo. Bajá y repetí.', 129093),
  ('FLEXIÓN DE HOMBRO - PALMAS ARRIBA - BASTÓN - BANDA ELÁSTICA', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Banda elástica; Bastón', 'Fijá las dos puntas de una banda elástica a un bastón y pisá la parte del medio de la banda con los pies, como se muestra. Sostené el bastón con las palmas hacia arriba, los brazos a la altura de la cintura y los codos estirados. Elevá los brazos hacia adelante y arriba con los codos estirados todo el tiempo. Bajá y repetí.', 129106),
  ('ENCOGIMIENTOS DE HOMBROS - BASTÓN - BANDA ELÁSTICA', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Banda elástica; Bastón', 'Fijá las dos puntas de una banda elástica a un bastón y pisá la parte del medio de la banda con los pies, como se muestra. Sostené el bastón abajo, a la altura de la cintura. Después elevá los hombros como encogiéndolos. Bajá y repetí.', 129109),
  ('REMO VERTICAL - BASTÓN - BANDA ELÁSTICA - TIRONES ALTOS', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Banda elástica; Bastón', 'Fijá las dos puntas de una banda elástica a un bastón y pisá la parte del medio de la banda con los pies, como se muestra. Sostené el bastón a la altura de la cintura con los codos estirados. Después, tirá del bastón hacia arriba, en dirección al mentón, dejando que los codos se flexionen. Bajá y repetí.', 129113),
  ('ABDUCCIÓN 90/90 CON PESO LIBRE - RE ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá sosteniendo pesas al costado del cuerpo con los codos flexionados a 90 grados. Después elevá los codos alejándolos del costado del cuerpo, manteniendo los codos flexionados a 90 grados todo el tiempo.', 16044),
  ('ROTACIÓN EXTERNA 90/90 CON PESOS LIBRES - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá sosteniendo pesas con los codos flexionados a 90 grados y separados 90 grados del costado del cuerpo. Después, rotá los hombros hacia atrás de modo que las palmas de las manos miren hacia adelante y después volvé, como se muestra.', 16045),
  ('PRESS ARNOLD - MANCUERNAS', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sostené las pesas a la altura del pecho alto con las palmas hacia vos, después movés las pesas en un arco hacia el costado y elevalas por encima de la cabeza mientras girás los antebrazos de modo que las palmas queden hacia adelante. Bajá a la posición inicial por el mismo arco lateral mientras girás los antebrazos de modo que las palmas vuelvan a mirarte. Repetí.', 76588),
  ('POLEA - FLEXIÓN D2 DE RODILLAS', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Colocá la polea en posición alta y arrodillate de espaldas a la polea, con la manija en la mano. Tirá de la manija cruzando por delante del cuerpo hacia el muslo contrario. Volvé a la posición inicial. Repetí.', 155341)
INSERT INTO exercise_library (name, professional_id, is_active, exercise_type, catalog_region, catalog_subcategory, instructions, source_exercise_id)
VALUES
  ('PRESS DE PECHO - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá con la barra centrada en el soporte. Acostate en el banco de modo que los ojos queden alineados con la barra. Agarrá la barra con los pulgares rodeándola, un poco más abiertos que el ancho del pecho. Después, empujá los pies contra el piso, apretá los glúteos y sacá la barra del soporte empujándola hacia arriba. Bajá la barra hacia el pecho dejando que los codos se flexionen. Después empujá la barra hacia arriba estirando los codos. Repetí. Si lo hacés solo, no uses trabas en las puntas de la barra, así, si no podés levantarla, podés dejar caer los discos hacia los costados.', 62941),
  ('PRESS DE PECHO - PESOS LIBRES - DE PIE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parate y sostené mancuernas chicas con ambas manos, con los codos flexionados a la altura del pecho. Después, estirá los codos mientras empujás las pesas derecho hacia adelante por delante del cuerpo, como se muestra. Volvé a la posición inicial y repetí.', 120509),
  ('PRESS DE PECHO SOBRE TOPES - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá con los topes ubicados un punto por encima de la altura del pecho y la barra centrada sobre los topes. Acostate en el banco de modo que los ojos queden alineados con la barra. Agarrá la barra con los pulgares rodeándola, un poco más abiertos que el ancho del pecho. Después, empujá los pies contra el piso, apretá los glúteos y levantá la barra de los topes estirando los codos. Después, bajá la barra hacia el pecho dejando que los codos se flexionen y apoyá la barra sobre los topes. Repetí.', 154603),
  ('MANCUERNA - PRESS POR ENCIMA DE LA CABEZA CON IMPULSO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parado con pesos libres sostenidos a la altura de los hombros, usá el impulso de una sentadilla corta y rápida para ayudarte a elevar las mancuernas por encima de la cabeza hasta bloquear los codos en extensión completa. Volvé con las mancuernas a la altura de los hombros y repetí. Durante las sentadillas rápidas, mantené la espalda plana y flexioná desde las caderas al bajar. Mantené el pecho erguido.', 150391),
  ('MANCUERNA - DE SENTADO A PRESS POR ENCIMA DE LA CABEZA CON IMPULSO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado con pesos libres sostenidos a la altura de los hombros, pararte y usá el impulso para ayudarte a elevar las mancuernas por encima de la cabeza hasta bloquear los codos en extensión completa. Hacé sentadilla, sentate y volvé con las mancuernas a la altura de los hombros, y repetí. Al sentarte, mantené la espalda plana y flexioná desde las caderas al bajar. Mantené el pecho erguido.', 163673),
  ('PRESS DE HOMBROS CON MANCUERNAS', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá con las mancuernas apoyadas sobre los hombros. Empujá las mancuernas hacia arriba bloqueando los codos. Controlá las pesas al bajarlas a la posición inicial. Repetí.', 154818),
  ('ROTACIÓN EXTERNA - RE 90/90 - PESOS LIBRES', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá sosteniendo pesos libres con el brazo elevado a 90 grados del costado del cuerpo y el codo flexionado a 90 grados. El antebrazo debe apuntar hacia adelante en la posición inicial, como se muestra. Después, rotá el hombro hacia atrás de modo que el antebrazo apunte hacia arriba. Después volvé a la posición original. Mantené el omóplato retraído y hacia abajo todo el tiempo.', 12909),
  ('PISO - PRESS DE PECHO - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá con la barra en la posición baja del soporte. Acostate en el piso de modo que los ojos queden alineados con la barra. Agarrá la barra con los pulgares rodeándola, un poco más abiertos que el ancho del pecho. Después, empujá los pies contra el piso, apretá los glúteos y sacá la barra del soporte empujándola hacia arriba. Bajá la barra hacia el pecho dejando que los codos se flexionen. Bajala hasta que los tríceps toquen suavemente el piso. Después empujá la barra hacia arriba estirando los codos. Repetí.', 154602),
  ('PESO LIBRE - ABDUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá sosteniendo un peso libre con el codo estirado y al costado del cuerpo, con la palma de la mano hacia adelante. Después, elevá el brazo hacia el costado, luego bajá y repetí.', 217),
  ('PESO LIBRE - FLEXIÓN ALTERNADA PALMAS ABAJO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sosteniendo mancuernas con los codos estirados y hacia abajo al costado del cuerpo, elevalas lentamente por delante del cuerpo con las palmas hacia abajo. Después volvé a la posición inicial y repetí. No dejes que el hombro se encoja hacia arriba, salvo que te hayan indicado pasar por encima de la altura del hombro.', 35136),
  ('PESO LIBRE - LATA VACÍA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sosteniendo una pesa con la parte de arriba del puño apuntando hacia abajo, elevá el brazo desde el costado del cuerpo. Mantené el codo estirado durante este ejercicio.', 218),
  ('PESO LIBRE - LATA VACÍA - BILATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sosteniendo una pesa con ambas manos, con la parte de arriba del puño apuntando hacia abajo, elevá los brazos desde el costado del cuerpo. No dejes que el hombro se encoja hacia arriba y no pases por encima de la altura del hombro. Mantené el codo estirado durante este ejercicio.', 35135),
  ('PESO LIBRE - EXTENSIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sosteniendo una pesa al costado del cuerpo, llevá el brazo hacia atrás, como se muestra. El codo debe estar estirado todo el tiempo.', 171),
  ('PESO LIBRE - ROTACIÓN EXTERNA - RE RANGO COMPLETO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Acostate de costado y sostené una pesa con el codo flexionado y apoyado sobre el costado del cuerpo. Colocá una toalla chica enrollada entre el brazo y el cuerpo. Después, llevá el antebrazo y la mano desde el piso hacia el techo, como se muestra. Bajá y repetí.', 165247),
  ('PESO LIBRE - APERTURAS', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá acostado boca arriba con los brazos extendidos horizontalmente hacia los costados. Después, llevá los brazos hacia arriba y adelante en dirección al techo, como se muestra. Luego bajá los brazos a la posición original. Los codos deben estar parcialmente flexionados todo el tiempo.', 7160),
  ('GERIÁTRICO - ELEVACIÓN ALTERNADA POR ENCIMA DE LA CABEZA - CON PESO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentate en una silla con buena postura sosteniendo una pesa liviana o una botella de agua, con los brazos a la altura del pecho y los codos flexionados. Estirá un brazo por encima de la cabeza mientras extendés el codo. Volvé a la posición inicial y repetí con el otro brazo. Seguí con este movimiento alternando de lado a lado.', 171539),
  ('GERIÁTRICO - FLEXIÓN ALTERNADA - CON PESO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentate en una silla con buena postura sosteniendo una pesa liviana o una botella de agua, con los brazos abajo al costado del cuerpo. Elevá un brazo hacia adelante y por encima de la cabeza manteniendo el codo estirado. Volvé a la posición inicial y repetí con el otro brazo. Seguí con este movimiento alternando de lado a lado.', 171540),
  ('GERIÁTRICO - ABDUCCIÓN BILATERAL - CON PESO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentate en una silla con buena postura sosteniendo una pesa liviana o una botella de agua, con los brazos al costado del cuerpo. Manteniendo los brazos estirados en los codos y las palmas hacia abajo, elevá los brazos hacia arriba y afuera, hacia los costados. Volvé a la posición inicial y repetí.', 172274),
  ('GERIÁTRICO - ABDUCCIÓN BILATERAL 90 - CON PESO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentate en una silla con buena postura sosteniendo una pesa liviana o una botella de agua, con los brazos al costado del cuerpo. Manteniendo los brazos estirados en los codos y las palmas hacia adelante, elevá los brazos hacia arriba y afuera, hacia los costados, hasta 90 grados. Volvé a la posición inicial y repetí.', 172275),
  ('GERIÁTRICO - PRESS POR ENCIMA DE LA CABEZA - CON PESO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentate en una silla con buena postura sosteniendo una pesa liviana o una botella de agua, con las manos cerca del pecho y los codos flexionados. Después, elevá los brazos por encima de la cabeza mientras extendés los codos. Volvé a la posición inicial y repetí.', 172276),
  ('MANCUERNA PESADA - PRESS DE PECHO ALTERNADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco, sostené una mancuerna en cada mano y después acostate boca arriba. Empezá ubicando las pesas cerca del pecho, con los codos flexionados y los hombros en abducción de unos 45 grados, como se muestra. Los pies deben estar bien apoyados en el piso. Después, apretá los glúteos y empujá los pies contra el piso mientras agarrás las mancuernas y las empujás hacia el techo. Los codos deben pasar de flexionados a estirados o casi estirados. Después, bajá una mancuerna flexionando el codo y volvé a subirla extendiendo el codo. Repetí con el otro brazo alternando de lado a lado.', 63249),
  ('MANCUERNA PESADA - PRESS DE PECHO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco, sostené una mancuerna en cada mano y después acostate boca arriba. Empezá ubicando las pesas cerca del pecho, con los codos flexionados y los hombros en abducción de unos 45 grados, como se muestra. Los pies deben estar bien apoyados en el piso. Después, apretá los glúteos y empujá los pies contra el piso mientras agarrás las mancuernas y las empujás hacia el techo. Los codos deben pasar de flexionados a estirados o casi estirados. Después, bajá ambas mancuernas a la posición inicial y repetí.', 63301),
  ('MANCUERNA PESADA - PRESS INCLINADO ALTERNADO POR ENCIMA DE LA CABEZA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco inclinado, sostené una mancuerna en cada mano y después acostate boca arriba. Empezá ubicando las pesas cerca del pecho, con los codos flexionados y los hombros en abducción de unos 45 grados, como se muestra. Los pies deben estar bien apoyados en el piso. Después, apretá los glúteos y empujá los pies contra el piso mientras agarrás las mancuernas y las empujás hacia el techo. Los codos deben pasar de flexionados a estirados o casi estirados. Después, bajá una mancuerna flexionando el codo y volvé a subirla extendiendo el codo. Repetí con el otro brazo alternando de lado a lado.', 63461),
  ('MANCUERNAS PESADAS - REMO INCLINADO - CON APOYO - EN ABDUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Apoyate con una rodilla y una mano sobre un banco. Agarrá la mancuerna con la otra mano. Empezá tirando de la mancuerna hacia el techo mientras flexionás el codo. Llevá el omóplato hacia la columna mientras subís el codo. No eleves el hombro hacia la oreja durante el ejercicio. Se recomienda algo de abducción (codo separado del costado del cuerpo) en el hombro para trabajar los músculos mediales de la escápula (trapecio medio y romboides). Volvé a la posición inicial extendiendo el codo y bajando la pesa. Repetí.', 63336),
  ('MANCUERNAS PESADAS - REMO INCLINADO - CON APOYO - EN ADUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Apoyate con una rodilla y una mano sobre un banco. Agarrá la mancuerna con la otra mano. Empezá tirando de la mancuerna hacia el techo mientras flexionás el codo (movimiento de serrucho). Llevá el omóplato hacia la columna mientras subís. No eleves el hombro hacia la oreja durante el ejercicio. Se recomienda aducción (codo pegado al costado del cuerpo) en el hombro para trabajar los dorsales y el deltoides posterior. Volvé a la posición inicial extendiendo el codo y bajando la pesa. Repetí.', 63337),
  ('MANCUERNAS PESADAS - CURL DE BÍCEPS', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parate sosteniendo una mancuerna en cada mano. Empezá flexionando un codo para llevar la pesa hacia la parte de adelante del hombro. Después, bajala hacia el costado del cuerpo mientras subís el otro lado. Repetí alternando los lados.', 63496),
  ('MANCUERNAS PESADAS - PRESS CON AGARRE APRETADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá acostado boca arriba sosteniendo mancuernas. Sostené las pesas cerca del pecho de modo que se toquen entre sí, como se muestra. Los pies deben estar bien apoyados en el piso y los codos cerca del costado del cuerpo. Después, apretá los glúteos y empujá los pies contra el piso mientras agarrás fuerte las mancuernas y las empujás hacia el techo, manteniéndolas en contacto todo el tiempo. Los codos deben pasar de flexionados a estirados o casi estirados. Volvé a la posición inicial y repetí. Las mancuernas deben mantenerse en contacto durante la fase de subida y de bajada.', 63246),
  ('MANCUERNAS PESADAS - CURL CON PRESS', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parate sosteniendo una mancuerna en cada mano, como se muestra. Empezá flexionando los codos para llevar las pesas hacia los hombros. Después, rotá los brazos y empujá las mancuernas por encima de la cabeza. Volvé a la posición inicial bajando las mancuernas a la altura de los hombros con los codos flexionados. Después, extendé los codos y bajá las pesas hacia el frente de las caderas. Repetí.', 63483),
  ('MANCUERNAS PESADAS - ELEVACIÓN FRONTAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá parado con una mancuerna en cada mano y los brazos abajo, por delante de las caderas. Después, elevá ambos brazos hacia adelante hasta aproximadamente 90 grados de flexión de hombro. Luego bajá a la posición inicial y repetí.', 63499),
  ('MANCUERNAS PESADAS - CURL MARTILLO - BRAQUIORRADIAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parate sosteniendo una mancuerna en cada mano con los brazos al costado del cuerpo. Las palmas deben mirar hacia adentro, hacia la línea media, todo el tiempo. Flexioná ambos codos para llevar las pesas hacia el frente de los hombros. Después, bajá de nuevo hacia el costado. Repetí.', 63500),
  ('MANCUERNAS PESADAS - CURL MARTILLO UNILATERAL - BRAQUIORRADIAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parate sosteniendo una mancuerna con el brazo al costado del cuerpo. La palma debe mirar hacia adentro, hacia la línea media, todo el tiempo. Flexioná el codo para llevar la pesa hacia el frente del hombro. Después, bajá de nuevo hacia el costado. Repetí.', 63516),
  ('MANCUERNAS PESADAS - CURL INVERSO MARTILLO - BRAQUIAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parate sosteniendo una mancuerna con el brazo al costado del cuerpo. Para empezar, la palma debe mirar hacia atrás. Después, flexioná el codo para llevar la pesa hacia el pecho. El dorso de la mano debe ir adelante en el movimiento hacia arriba. Después, bajá de nuevo hacia el costado. Repetí.', 63519),
  ('MANCUERNAS PESADAS - APERTURAS EN BANCO INCLINADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco inclinado, sostené una mancuerna en cada mano y después acostate boca arriba. Los pies deben estar bien apoyados en el piso. Empezá sosteniendo las mancuernas por encima del pecho con los codos completamente extendidos y bien arriba. Después, bajá lentamente las pesas hacia los costados y hacia el piso. Flexioná un poco los codos al bajar. No bajes todo lo que puedas: detenete aproximadamente a la altura del tronco, de modo que los codos no queden por debajo de la espalda. Volvé a la posición inicial y repetí.', 63459),
  ('MANCUERNAS PESADAS - PRESS POR ENCIMA DE LA CABEZA EN BANCO INCLINADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco inclinado, sostené una mancuerna en cada mano y después acostate boca arriba. Empezá ubicando las pesas cerca del pecho, con los codos flexionados y los hombros en abducción de unos 45 grados, como se muestra. Los pies deben estar bien apoyados en el piso. Después, apretá los glúteos y empujá los pies contra el piso mientras agarrás las mancuernas y las empujás hacia el techo. Los codos deben pasar de flexionados a estirados o casi estirados. Después, bajá ambas mancuernas a la posición inicial y repetí.', 63464),
  ('MANCUERNAS PESADAS - TRÍCEPS EN BANCO INCLINADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco, sostené una mancuerna en cada mano y después acostate boca arriba. Los pies deben estar bien apoyados en el piso. Empezá sosteniendo las mancuernas por encima del pecho con los codos extendidos, como se muestra. Después, bajá lentamente las pesas hacia los costados de la cabeza dejando que los codos se flexionen. Los codos deben pasar de estirados a flexionados. Tratá de que el movimiento lo genere solamente el codo y no el hombro, para trabajar los tríceps. Volvé a la posición inicial y repetí.', 63468),
  ('MANCUERNAS PESADAS - ELEVACIÓN LATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sosteniendo una mancuerna en cada mano y con los codos estirados, elevá los brazos hacia arriba desde el costado del cuerpo con las palmas hacia abajo. Bajá y repetí.', 63501),
  ('MANCUERNAS PESADAS - PRESS POR ENCIMA DE LA CABEZA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parate sosteniendo una mancuerna en cada mano cerca de la parte alta de los hombros, con los codos flexionados, como se muestra. Después, empujá las pesas hacia arriba y por encima de la cabeza extendiendo los codos. Bajá de nuevo hacia la parte alta de los hombros y repetí.', 63518),
  ('MANCUERNAS PESADAS - PRESS POR ENCIMA DE LA CABEZA UNILATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parate sosteniendo una mancuerna cerca de la parte alta del hombro, con el codo flexionado, como se muestra. Después, empujá la pesa hacia arriba y por encima de la cabeza extendiendo el codo. Bajá de nuevo hacia la parte alta del hombro y repetí.', 63517),
  ('MANCUERNAS PESADAS - ARRANQUE DE POTENCIA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Colocá los pies separados aproximadamente al ancho de las caderas y sostené un peso libre con una mano. Las rodillas deben estar flexionadas y la pesa debe colgar derecho hacia abajo, al costado de la pierna. Empezá extendiendo las rodillas y al mismo tiempo tirá de la mancuerna hacia arriba con el brazo, dejando que el codo se flexione, y después elevala rápido por encima de la cabeza hasta dejar el codo estirado. Cuando la mancuerna llega arriba, flexioná las rodillas en una sentadilla parcial para meterte debajo de la pesa. Por último, extendé las rodillas por completo para quedar parado derecho con la pesa todavía por encima de la cabeza. Bajá la mancuerna con el brazo a la posición inicial. Repetí.', 63512),
  ('MANCUERNAS PESADAS - APERTURAS INVERSAS', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sostené un peso libre en cada mano mientras estás inclinado desde la cintura (bisagra de cadera), manteniendo la espalda derecha. Con los brazos hacia los costados, elevá y bajá las pesas, como se muestra.', 63510),
  ('MANCUERNAS PESADAS - PRESS MILITAR ALTERNADO SENTADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentate en un banco y sostené una mancuerna en cada mano. Después, flexioná los codos de modo que cada mancuerna quede cerca del costado de la cabeza. Empezá empujando ambas pesas hacia el techo, por encima de la cabeza, extendiendo los codos, como se muestra. Después, bajá un lado a la posición inicial dejando que el codo se flexione hacia el costado de la cabeza. Después volvé a subirla por encima de la cabeza. Repetí alternando de lado a lado.', 63472),
  ('MANCUERNAS PESADAS - PRESS MILITAR SENTADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentate en un banco y sostené mancuernas en cada mano. Después, flexioná los codos de modo que cada mancuerna quede cerca del costado de la cabeza. Empezá empujando ambas pesas hacia el techo, por encima de la cabeza, extendiendo los codos. Después, volvé a la posición inicial dejando que los codos se flexionen hacia el costado de la cabeza. Repetí.', 63473),
  ('MANCUERNAS PESADAS - PRESS MILITAR UNILATERAL SENTADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentate en un banco y sostené una mancuerna con una mano. Después, flexioná el codo de modo que la mancuerna quede cerca del costado de la cabeza. Empezá empujando la pesa hacia el techo, por encima de la cabeza, extendiendo el codo. Después, volvé a la posición inicial dejando que el codo se flexione hacia el costado de la cabeza. Repetí.', 63474),
  ('MANCUERNAS PESADAS - EXTENSIÓN DE TRÍCEPS UNILATERAL SENTADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado, sostené una mancuerna y elevala por encima del hombro con el codo flexionado, cerca del costado de la cabeza, como se muestra. Después, extendé lentamente el codo para levantar la mancuerna derecho por encima de la cabeza. El codo debe pasar de flexionado a estirado. Tratá de que el movimiento lo genere solamente el codo y no el hombro, para trabajar los tríceps. Volvé a la posición inicial y repetí.', 63478),
  ('MANCUERNAS PESADAS - PRESS DE PECHO UNILATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco, sostené una mancuerna y después acostate boca arriba. Empezá ubicando la pesa cerca del pecho, con el codo flexionado y el hombro en abducción de unos 45 grados, como se muestra. Los pies deben estar bien apoyados en el piso. Después, apretá los glúteos y empujá los pies contra el piso mientras agarrás la mancuerna y la empujás hacia el techo. El codo debe pasar de flexionado a estirado o casi estirado. Después, bajá la mancuerna a la posición inicial y repetí.', 63331),
  ('MANCUERNAS PESADAS - PRESS DE PECHO UNILATERAL EN BANCO INCLINADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco inclinado, sostené una mancuerna y después acostate boca arriba. Empezá ubicando la pesa cerca del pecho, con el codo flexionado y el hombro en abducción de unos 45 grados, como se muestra. Los pies deben estar bien apoyados en el piso. Después, apretá los glúteos y empujá los pies contra el piso mientras agarrás la mancuerna y la empujás hacia el techo. El codo debe pasar de flexionado a estirado o casi estirado. Después, bajá la mancuerna a la posición inicial y repetí.', 63463),
  ('MANCUERNAS PESADAS - TRÍCEPS UNILATERAL EN BANCO INCLINADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco, sostené una mancuerna y después acostate boca arriba. Los pies deben estar bien apoyados en el piso. Empezá sosteniendo la mancuerna por encima del pecho con el codo extendido, como se muestra. Después, bajá lentamente la pesa hacia atrás, POR ENCIMA de la cabeza, dejando que el codo se flexione. El codo debe pasar de estirado a flexionado. Tratá de que el movimiento lo genere solamente el codo y no el hombro, para trabajar los tríceps. Volvé a la posición inicial y repetí.', 63465),
  ('MANCUERNAS PESADAS - ROMPECRÁNEOS', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco, sostené una mancuerna y después acostate boca arriba. Empezá sosteniendo la mancuerna por encima del pecho, con ambas manos ahuecadas sobre la punta de la pesa y los dos codos extendidos, como se muestra. Los pies deben estar bien apoyados en el piso. Después, bajá lentamente la pesa hacia atrás, POR ENCIMA de la cabeza, dejando que los codos se flexionen. Los codos deben pasar de estirados a flexionados. Tratá de que el movimiento lo generen solamente los codos y no los hombros, para trabajar los tríceps. Volvé a la posición inicial y repetí.', 63332),
  ('MANCUERNAS PESADAS - APERTURAS EN DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco, sostené una mancuerna en cada mano y después acostate boca arriba. Los pies deben estar bien apoyados en el piso. Empezá sosteniendo las mancuernas por encima del pecho con los codos completamente extendidos y bien arriba. Después, bajá lentamente las pesas hacia los costados y hacia el piso. Flexioná un poco los codos al bajar. No bajes todo lo que puedas: detenete aproximadamente a la altura del tronco, de modo que los codos no queden por debajo de la espalda. Volvé a la posición inicial y repetí.', 63458),
  ('MANCUERNAS PESADAS - EXTENSIÓN DE TRÍCEPS EN DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Acostate boca arriba sosteniendo una mancuerna por encima del pecho con una mano y el codo extendido, como se muestra. Los pies deben estar bien apoyados en el piso. Después, bajá lentamente la pesa hacia el costado de la cabeza dejando que el codo se flexione. El codo debe pasar de estirado a flexionado. Volvé a la posición inicial y repetí.', 63333),
  ('PRESS DE PECHO INCLINADO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco inclinado, agarrá la barra con los pulgares rodeándola, un poco más abiertos que el ancho del pecho. Después, empujá los pies contra el piso, apretá los glúteos y sacá la barra del soporte empujándola hacia arriba mientras estirás los codos. Después, bajá la barra hacia el pecho dejando que los codos se flexionen. Volvé a subir la pesa estirando los codos. Repetí.', 154634),
  ('PRESS DE PECHO INCLINADO SOBRE TOPES - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco inclinado, empezá con los topes ubicados un punto por encima de la altura del pecho y la barra centrada sobre los topes. Agarrá la barra con los pulgares rodeándola, un poco más abiertos que el ancho del pecho. Después, empujá los pies contra el piso, apretá los glúteos y levantá la barra de los topes estirando los codos. Después, bajá la barra hacia el pecho dejando que los codos se flexionen y apoyá la barra sobre los topes. Repetí.', 154633),
  ('PRESS MILITAR - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parate con la barra apoyada sobre los hombros, por delante del cuello. Empujando desde los pies, elevá la barra por encima de la cabeza. Dejá que los codos y las rodillas se flexionen al bajar la barra para amortiguar el peso. Repetí.', 154660),
  ('PRESS DE PECHO INCLINADO PARCIAL - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en un banco inclinado, agarrá la barra con los pulgares rodeándola, un poco más abiertos que el ancho del pecho. Después, empujá los pies contra el piso, apretá los glúteos y sacá la barra del soporte empujándola hacia arriba mientras estirás los codos. Bajá la barra hacia el pecho pero detenete cuando llegues a unos 90 grados de flexión de codo. Volvé a subir la pesa estirando los codos. Repetí.', 154639),
  ('PÉNDULO LATERAL CON PESO', NULL, true, 'pasivo', 'Hombro', 'Peso libre', 'Apoyá una mano sobre una superficie estable, como una mesa o una mesada, e inclinate hacia adelante desde la cintura. Sostené una pesa chica o una lata de conserva con el brazo afectado y dejalo colgar hacia el piso. Relajá completamente el brazo afectado. El único músculo activo debe ser el del agarre de la pesa. Trasladá el peso del cuerpo de lado a lado para que el brazo lesionado se balancee libremente. El brazo lesionado debe estar totalmente relajado todo el tiempo.', 54254),
  ('AGARRE INVERTIDO - PRESS DE PECHO', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá con la barra centrada en el soporte. Acostate en el banco de modo que los ojos queden alineados con la barra. Agarrá la barra con las palmas hacia arriba y las manos un poco más abiertas que el ancho del pecho. Después, empujá los pies contra el piso, apretá los glúteos y sacá la barra del soporte. Bajá la barra hacia el pecho pero detenete cuando llegues a 90 grados de flexión de codo. Después, empujá la barra hacia arriba estirando los codos. Repetí. Si lo hacés solo, no uses trabas en las puntas de la barra, así, si no podés levantarla, podés dejar caer los discos hacia los costados.', 154657),
  ('PRESS MILITAR SENTADO - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado y erguido, agarrá la barra con los pulgares rodeándola, un poco más abiertos que el ancho del pecho. Después, empujá los pies contra el piso, apretá los glúteos y sacá la barra del soporte estirando los codos para levantarla por encima de la cabeza. Después, bajá la barra por delante del mentón dejando que los codos se flexionen. Volvé a subir la pesa estirando los codos. Repetí.', 154673),
  ('PRESS MILITAR SENTADO SOBRE TOPES - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado y erguido en un banco inclinado, empezá con los topes ubicados un punto por encima de la altura del pecho y la barra centrada sobre los topes. Después, empujá los pies contra el piso, apretá los glúteos y levantá la barra de los topes estirando los codos para elevarla por encima de la cabeza. Después, bajá la barra hacia el mentón dejando que los codos se flexionen y apoyá la barra sobre los topes. Repetí.', 154672),
  ('PRESS MILITAR PARCIAL SENTADO - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado y erguido, agarrá la barra con los pulgares rodeándola, un poco más abiertos que el ancho del pecho. Después, empujá los pies contra el piso, apretá los glúteos y sacá la barra del soporte estirando los codos para levantarla por encima de la cabeza. Después, bajá la barra por delante de la nariz dejando que los codos se flexionen. Volvé a subir la pesa estirando los codos. Repetí.', 154661),
  ('ABDUCCIÓN EN DECÚBITO LATERAL - PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Empezá acostado de costado con el brazo al costado del cuerpo y sosteniendo una mancuerna. Después, elevá lentamente el brazo hacia el techo hasta que quede derecho hacia arriba. Volvé a la posición original.', 6032),
  ('ENVIÓN EN TIJERA - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Parate con la barra apoyada sobre los hombros, por delante del cuello, con los pies separados al ancho de los hombros. Flexioná las rodillas y después hacé un salto corto pasando a una posición de tijera mientras elevás la barra por encima de la cabeza. Después, volvé caminando con los pies hasta separarlos al ancho de los hombros. Luego, dejá que los codos y las rodillas se flexionen al bajar la barra para amortiguar el peso. Repetí.', 154671),
  ('SILLA DE RUEDAS - PRESS MILITAR - PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en una silla de ruedas, empezá sosteniendo mancuernas chicas en cada mano con los codos flexionados, de modo que las pesas queden cerca del costado de la cabeza, como se muestra. Después, empujá las pesas hacia arriba y por encima de la cabeza estirando los codos. Bajá a la posición inicial y repetí.', 105322),
  ('SILLA DE RUEDAS - ABDUCCIÓN DE HOMBRO - PESO LIBRE - BILATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en una silla de ruedas, sostené una mancuerna en ambas manos con los codos estirados. Elevá los brazos hacia el costado, después bajá y repetí.', 105289),
  ('SILLA DE RUEDAS - ABDUCCIÓN DE HOMBRO - PESO LIBRE - UNILATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en una silla de ruedas, sostené una mancuerna con el codo estirado. Elevá el brazo hacia el costado, después bajá y repetí.', 105297),
  ('SILLA DE RUEDAS - PRESS MILITAR UNILATERAL - PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en una silla de ruedas, empezá sosteniendo una mancuerna chica con el codo flexionado, de modo que la pesa quede cerca del costado de la cabeza, como se muestra. Después, empujá la pesa hacia arriba y por encima de la cabeza estirando el codo. Bajá a la posición inicial y repetí.', 105325),
  ('SILLA DE RUEDAS - EXTENSIÓN DE TRÍCEPS CON PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en una silla de ruedas, sostené una mancuerna y elevala por encima del hombro con el codo flexionado, cerca del costado de la cabeza, como se muestra. Después, extendé lentamente el codo para levantar la pesa derecho por encima de la cabeza. El codo debe pasar de flexionado a estirado. Tratá de que el movimiento lo genere solamente el codo y no el hombro, para trabajar los tríceps. Volvé a la posición inicial y repetí.', 105299),
  ('SILLA DE RUEDAS - FLEXIÓN DE HOMBRO - BILATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en una silla de ruedas, sostené una pesa con ambas manos, con la palma hacia el costado del cuerpo y los codos estirados. Después, elevá los brazos hacia arriba y adelante, como se muestra; volvé a la posición inicial y repetí.', 105319),
  ('SILLA DE RUEDAS - FLEXIÓN DE HOMBRO - PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre', 'Sentado en una silla de ruedas, sostené una mancuerna con la palma hacia el costado del cuerpo y el codo estirado. Después, elevá el brazo hacia arriba y adelante, como se muestra; volvé a la posición inicial y repetí.', 105318),
  ('ABDUCCIÓN DE HOMBRO CON SOSTÉN ISOMÉTRICO EN FLEXIÓN - PESOS LIBRES', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Isométrico', 'Empezá sosteniendo una mancuerna en cada mano, abajo al costado del cuerpo. Elevá y sostené un brazo derecho hacia adelante con el codo estirado. Después, elevá el otro brazo hacia el costado y bajalo. Repetí mientras el otro brazo se mantiene quieto todo el tiempo.', 170795),
  ('FLEXIÓN DE HOMBRO CON SOSTÉN ISOMÉTRICO EN ABDUCCIÓN - PESOS LIBRES', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Isométrico', 'Empezá sosteniendo una mancuerna en cada mano, abajo al costado del cuerpo. Elevá y sostené un brazo derecho hacia el costado con el codo estirado. Después, elevá el otro brazo hacia adelante y bajalo. Repetí mientras el otro brazo se mantiene quieto todo el tiempo.', 170796),
  ('APERTURA UNILATERAL - PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Isométrico; Estabilización', 'Empezá acostado boca arriba con los brazos hacia el techo sosteniendo mancuernas, como se muestra. Bajá un brazo horizontalmente hacia el costado. Después, elevá el brazo a la posición inicial y repetí. Los codos deben estar parcialmente flexionados todo el tiempo.', 169524),
  ('PRESS DE PECHO PARCIAL - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Máquinas y poleas', 'Empezá con la barra centrada en el soporte. Acostate en el banco de modo que los ojos queden alineados con la barra. Agarrá la barra con los pulgares rodeándola, un poco más abiertos que el ancho del pecho. Después, empujá los pies contra el piso, apretá los glúteos y sacá la barra del soporte. Bajá la barra hacia el pecho pero detenete cuando llegues a 90 grados de flexión de codo. Después, empujá la barra hacia arriba estirando los codos. Repetí. Si lo hacés solo, no uses trabas en las puntas de la barra, así, si no podés levantarla, podés dejar caer los discos hacia los costados.', 62948),
  ('ENCOGIMIENTOS CON CODOS FLEXIONADOS', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Sosteniendo pesas con los codos flexionados, elevá los hombros hacia las orejas, como se muestra. Encogé ambos hombros al mismo tiempo.', 71733),
  ('REMO INCLINADO - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'De pie, mantené la columna derecha e inclinate hacia adelante desde las caderas mientras levantás la barra. Elevá la barra flexionando los codos. Volvé a la posición inicial estirando los codos y bajando la barra. Repetí.', 154604),
  ('REMO INCLINADO - MEDIA RODILLA', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Apoyando una rodilla sobre una superficie firme, inclinate hacia adelante y sostenete con el brazo sano. Con el brazo afectado empezando al costado del cuerpo, tirá del brazo hacia arriba flexionando el codo.', 6979),
  ('ROTACIÓN EXTERNA CON FLEXIÓN - PESO LIBRE RE 90/90', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Sostené una pesa chica, como se muestra. Sentado y con el codo elevado a 90 grados hacia adelante, rotá el hombro de modo que el antebrazo apunte hacia arriba y después volvé hacia abajo, como se muestra.', 19779),
  ('PESO LIBRE - ROTACIÓN EXTERNA EN DECÚBITO VENTRAL - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostate boca abajo y apoyá el brazo sobre la camilla o la cama con la mano colgando hacia el piso. Después, llevá la pesa hacia adelante y arriba, en dirección al techo, manteniendo el brazo apoyado sobre la camilla o cama todo el tiempo.', 221),
  ('PESO LIBRE - ROTACIÓN INTERNA - RI', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostate sobre el lado afectado y sostené una pesa con el codo flexionado y apoyado cerca del costado del cuerpo. Después, llevá el antebrazo desde el piso hacia el techo. CONSEJO: tratá de acostarte sobre el lado afectado pero un poco rotado hacia la espalda, dejando el hombro libre. Puede resultar más cómodo y quitarle presión al hombro.', 223),
  ('MANCUERNAS PESADAS - PRESS ALTERNADO POR ENCIMA DE LA CABEZA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Parate sosteniendo una mancuerna en cada mano cerca de la parte alta de los hombros, con los codos flexionados, como se muestra. Después, alterná empujando una de las pesas hacia arriba y por encima de la cabeza estirando el codo. Bajá de nuevo hacia la parte alta de los hombros y después repetí con el otro lado, alternando los lados.', 75021),
  ('ELEVACIÓN ESCAPULAR POR ENCIMA DE LA CABEZA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Empezá parado con buena postura, sosteniendo pesas chicas o latas de conserva con los brazos extendidos hacia el techo. Manteniendo los codos estirados, elevá los omóplatos y dejá que los brazos suban hacia el techo. Después, bajá de forma controlada. Repetí. Mantené los codos estirados todo el tiempo.', 71734),
  ('REMO EN PLANCHA CON MANCUERNAS', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostate boca abajo sosteniendo una mancuerna en cada mano y con las piernas bien separadas. Después, empujate hacia arriba hasta una plancha completa, de modo que las manos que sostienen las mancuernas y las puntas de los pies sostengan el cuerpo, como se muestra. Después, tirá de una mancuerna hacia arriba flexionando el codo y llevando el omóplato hacia el centro de la columna. Después, apoyá la mancuerna en el piso y repetí del otro lado. Tratá de mantener la columna y la pelvis derechas y estables todo el tiempo.', 65367),
  ('RETRACCIÓN EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostado boca abajo con los codos estirados, llevá lentamente el omóplato hacia atrás, en dirección a la columna. Todo el brazo debe elevarse, incluido el omóplato, como se muestra. El codo debe estar estirado todo el tiempo.', 553),
  ('REMOS EN DECÚBITO VENTRAL - 90', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostado boca abajo con los codos estirados, elevá lentamente los brazos flexionando los codos. Los codos deben quedar aproximadamente a 90 grados del costado del cuerpo.', 6843),
  ('REMOS EN DECÚBITO VENTRAL - 90 GRADOS DE ABDUCCIÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostate boca abajo sobre un banco o la esquina de una cama sosteniendo mancuernas. Mantené los codos a 90 grados del costado del cuerpo y después elevá los brazos de modo que los codos vayan hacia el techo mientras se flexionan. Bajá y repetí. No eleves los hombros hacia las orejas durante este ejercicio.', 169521),
  ('REMOS EN DECÚBITO VENTRAL 90 - PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostate boca abajo sobre un banco o la esquina de una cama sosteniendo mancuernas. Empezá con los brazos colgando hacia el piso. Después, con los codos hacia el costado a unos 90 grados, elevá los brazos dejando que los codos se flexionen, como se muestra. Bajá y repetí. No eleves los hombros hacia las orejas durante este ejercicio.', 170245),
  ('REMOS EN DECÚBITO VENTRAL CON ROTACIÓN EXTERNA - RE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Empezá acostado boca abajo con el brazo colgando derecho hacia abajo y el codo estirado. Después, tirá del brazo hacia arriba flexionando el codo, como se muestra. Luego, rotá lentamente el hombro para elevar el puño hacia la cabeza, como se muestra.', 186),
  ('REMOS TIPO SERRUCHO EN DECÚBITO VENTRAL - PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostate boca abajo sobre un banco o la esquina de una cama sosteniendo mancuernas. Manteniendo los codos pegados al costado del cuerpo, elevá los brazos hacia el techo flexionando los codos. Bajá y repetí. No eleves los hombros hacia las orejas durante este ejercicio.', 169520),
  ('EXTENSIONES DE HOMBRO EN DECÚBITO VENTRAL - PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostate boca abajo sobre un banco o la esquina de una cama sosteniendo mancuernas. Empezá con los brazos colgando hacia el piso. Después, elevá los brazos hacia el costado de los muslos, como se muestra. Bajá y repetí. No eleves los hombros hacia las orejas durante este ejercicio.', 170244),
  ('T EN DECÚBITO VENTRAL - PESO LIBRE', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostate boca abajo sobre un banco o la esquina de una cama sosteniendo mancuernas. Empezá con los brazos colgando hacia el piso. Después, manteniendo los codos estirados y hacia el costado a unos 90 grados, elevá los brazos, como se muestra. Bajá y repetí.', 170246),
  ('T EN DECÚBITO VENTRAL - ABDUCCIÓN HORIZONTAL - PESOS LIBRES', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostate boca abajo sobre un banco o la esquina de una cama sosteniendo mancuernas en posición horizontal. Sostené las mancuernas con las palmas hacia abajo. Mantené los hombros a 90 grados del costado del cuerpo y después elevá los brazos hacia el techo. Bajá y repetí. No eleves los hombros hacia las orejas durante este ejercicio.', 169522),
  ('REMOS EN Y EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'Acostate boca abajo sobre un banco o la esquina de una cama sosteniendo mancuernas. Mantené el brazo por encima de la cabeza, aproximadamente a 120-150 grados del costado del cuerpo, y después elevá los brazos hacia el techo. Bajá y repetí. No eleves los hombros hacia las orejas durante este ejercicio.', 169523),
  ('REMO INCLINADO CON AGARRE INVERTIDO - BARRA', NULL, true, 'fortalecimiento', 'Hombro', 'Peso libre; Estabilización', 'De pie, mantené la columna derecha e inclinate hacia adelante desde las caderas mientras levantás la barra con las palmas hacia arriba. Elevá la barra flexionando los codos. Volvé a la posición inicial estirando los codos y bajando la barra. Repetí.', 154674),
  ('POLEA - PRESS DE PECHO', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá las poleas a la altura del codo y parate de espaldas a ellas con las manijas en las manos. Empezá con los pies en tijera para mantener una posición cómoda y equilibrada, con los codos flexionados unos 90 grados. Manteniendo el core activado, empujá los brazos hacia adelante por delante del pecho hasta estirar completamente los codos. Volvé a la posición inicial. Repetí.', 155327),
  ('POLEA - CRUCES', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá las poleas a la altura del codo y parate de espaldas a ellas con las manijas en las manos. Empezá con los pies en tijera para mantener una posición cómoda y equilibrada, con los codos flexionados unos 90 grados. Manteniendo el core activado, empujá los brazos hacia adelante por delante del pecho estirando los codos hasta que los antebrazos se crucen, como se muestra. Volvé a la posición inicial. Repetí.', 155331),
  ('POLEA - PRESS MARTILLO NEUMÁTICO', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá la polea en posición alta y parate de frente a ella usando el accesorio de barra corta. Empezá con las manos juntas sobre la barra y los codos elevados hacia el costado, como se muestra. Empujá hacia abajo estirando los codos. Volvé a la posición inicial. Repetí.', 155345),
  ('POLEA - DE RODILLAS - PRESS EN X', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá las poleas a la altura del codo y arrodillate de espaldas a ellas con las manijas en las manos. Sentate sobre los talones y mantené los codos flexionados unos 90 grados. Empujá hacia abajo con ambos cables formando una X, dejando que las muñecas se crucen.', 155344),
  ('POLEA - CRUCES DE ABAJO HACIA ARRIBA', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá las poleas a la altura del codo y parate de espaldas a ellas con las manijas en las manos. Empezá con los pies en tijera para mantener una posición cómoda y equilibrada, con los codos levemente flexionados. Manteniendo el core activado, elevá los brazos hacia arriba y adelante cruzando la línea media por delante del cuerpo hasta que las muñecas se crucen aproximadamente a la altura de los hombros, como se muestra. Volvé a la posición inicial. Repetí.', 155337),
  ('POLEA - EXTENSIÓN DE TRÍCEPS POR ENCIMA DEL HOMBRO', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá las poleas en posición alta. Sostené las manijas de espaldas a las poleas, con los pies en tijera. Empezá con las manos por encima de la cabeza y los codos flexionados. Después, estirá los codos mientras llevás las manijas hacia adelante, por delante del pecho. Volvé a la posición inicial y repetí.', 142593),
  ('POLEA - TRÍCEPS CON SOGA - EXTENSIÓN POR ENCIMA DE LA CABEZA - EMPUJES', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá los cables en posición alta. Parate en posición de estocada, como se muestra. Sostené las puntas de la soga con los brazos por encima de la cabeza y los codos flexionados. Tirá de la soga hacia adelante hasta estirar los codos. Volvé a la posición inicial y repetí.', 140457),
  ('POLEA - UNILATERAL - PRESS DE PECHO', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá la polea a la altura del codo y parate de espaldas a ella con la manija en la mano que vas a trabajar. Empezá con los pies en tijera para mantener una posición cómoda y equilibrada, con el codo flexionado unos 90 grados. Manteniendo el core activado, empujá el brazo hacia adelante por delante del pecho hasta estirar completamente el codo. Volvé a la posición inicial. Repetí.', 155328),
  ('POLEA - UNILATERAL - CRUCES', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá la polea a la altura del codo y parate de espaldas a ella con la manija en la mano. Empezá con los pies en tijera para mantener una posición cómoda y equilibrada, con el codo flexionado unos 90 grados. Manteniendo el core activado, empujá el brazo hacia adelante por delante del pecho estirando el codo hasta que el antebrazo cruce el pecho, como se muestra. Volvé a la posición inicial. Repetí.', 155340),
  ('POLEA - UNILATERAL - PRESS DE PECHO DE ARRIBA HACIA ABAJO', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá la polea en posición alta y parate de espaldas a ella con la manija en la mano. Empezá con los pies en tijera para mantener una posición cómoda y equilibrada, con el codo flexionado unos 90 grados. Manteniendo el core activado, empujá el cable hacia abajo por delante del muslo hasta estirar completamente el codo. Volvé a la posición inicial. Repetí.', 155329),
  ('POLEA - UNILATERAL - CRUCE DE ABAJO HACIA ARRIBA', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá la polea en posición baja y parate de espaldas a ella con la manija en la mano. Empezá con los pies en tijera para mantener una posición cómoda y equilibrada, con el codo flexionado. Manteniendo el core activado, elevá el brazo hacia arriba y adelante cruzando la línea media por delante del cuerpo hasta que la muñeca llegue aproximadamente a la altura del hombro, como se muestra. Volvé a la posición inicial. Repetí.', 155336),
  ('POLEA - UNILATERAL - TRÍCEPS POR ENCIMA DE LA CABEZA - EMPUJES', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá la polea en posición alta. Parate de espaldas a la polea y en posición de estocada. Sostené la manija, como se muestra, con el brazo al costado de la cabeza y el codo flexionado. Tirá del cable hacia adelante hasta estirar el codo y que la mano quede por delante del cuerpo. Volvé a la posición inicial y repetí.', 142594),
  ('POLEA - UNILATERAL - ELEVACIÓN UCV', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá la polea en posición baja y parate de espaldas a ella con la manija en la mano. Empezá con los pies en tijera para mantener una posición cómoda y equilibrada, con el codo flexionado. Manteniendo el core activado, tirá del brazo hacia arriba y adelante por delante del pecho estirando el codo hasta que el antebrazo cruce el cuerpo a la altura del hombro, como se muestra. Volvé a la posición inicial. Repetí.', 155338),
  ('POLEA - ELEVACIÓN LATERAL UNILATERAL - DESENVAINE DE ESPADA', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá el cable en posición baja y parate de espaldas a la polea. Empezá sosteniendo la manija cerca de la cadera del lado contrario, como se muestra. Después, tirá del cable en diagonal hacia arriba, en dirección al lado opuesto del cuerpo. Volvé a la posición inicial y repetí.', 142630),
  ('POLEA - ELEVACIÓN UCV', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá las poleas en posición baja y parate de espaldas a ellas con las manijas en las manos. Empezá con los pies en tijera para mantener una posición cómoda y equilibrada, con los codos flexionados. Manteniendo el core activado, tirá de los brazos hacia adelante por delante del pecho estirando los codos hasta que los antebrazos se crucen a la altura de los hombros, como se muestra. Volvé a la posición inicial. Repetí.', 155339),
  ('APERTURAS EN POLEA', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá los cables en posición media. Sostené las manijas con los brazos hacia los costados y los codos flexionados. Empezá tirando de los cables hacia adelante. Las manos deben acercarse entre sí y los codos deben ir estirándose. Volvé con los brazos hacia los costados y repetí.', 140455),
  ('APERTURAS EN POLEA - DE ARRIBA HACIA ABAJO', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá los cables en posición alta. Sostené las manijas con los brazos hacia los costados y los codos flexionados. Empezá tirando de los cables hacia abajo y adelante. Las manos deben acercarse entre sí y los codos deben ir estirándose. Volvé con los brazos hacia los costados y repetí.', 140453),
  ('APERTURAS EN POLEA - DE ABAJO HACIA ARRIBA', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá los cables en posición baja. Sostené las manijas con los brazos hacia los costados y los codos flexionados. Empezá tirando de los cables hacia arriba y adelante. Las manos deben acercarse entre sí y los codos deben ir estirándose. Volvé con los brazos hacia los costados y repetí.', 140454),
  ('POLEA EN Y - JALONES - APERTURA INCLINADA', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas', 'Colocá la polea en posición alta y sentate en un banco inclinado, como se muestra. Usá las manijas y tirá hacia abajo y hacia adentro, en dirección al medio del cuerpo. Volvé a la posición inicial y repetí.', 142585),
  ('POLEA - REMOS A 45 GRADOS', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas; Estabilización', 'Colocá los cables en posición media. Parate en posición de estocada. Sostené las manijas con los brazos hacia adelante y los codos estirados. Ubicá los hombros aproximadamente a 45 grados del costado del cuerpo. Tirá de los cables hacia atrás dejando que los codos se flexionen. Volvé a la posición inicial estirando los codos. Repetí. Los omóplatos deben estar retraídos hacia abajo y atrás, y asegurate de mantener los hombros a unos 45 grados del costado del cuerpo.', 140460),
  ('POLEA - REMO EN MEDIA RODILLA', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas; Estabilización', 'Arrodillate en el piso con una rodilla apoyada y el otro pie en el piso, como se muestra. Colocá la polea a la altura del codo en esta posición. La otra mano puede apoyarse en el banco como sostén. Empezá tirando de la manija hacia vos hasta que el codo se flexione al costado del cuerpo. Volvé a la posición inicial y repetí.', 142588),
  ('POLEA - REMO EN MEDIA RODILLA A NEUTRO', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas; Estabilización', 'Arrodillate en el piso con una rodilla apoyada y el pie del otro lado en el piso, como se muestra. Colocá la polea a la altura del codo en esta posición. La otra mano puede apoyarse en el banco como sostén. Empezá tirando de la manija hacia vos hasta que el codo llegue al costado del cuerpo. Volvé a la posición inicial y repetí.', 142587),
  ('POLEA - PRESS DE PECHO INCLINADO', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas; Estabilización', 'Colocá la polea en posición baja y sentate en un banco inclinado, como se muestra. Usá las manijas y empujá hacia arriba, por encima de la cabeza. Volvé a la posición inicial y repetí.', 142586),
  ('POLEA - JALÓN - UNILATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas; Estabilización', 'Colocá la polea en posición alta y sentate en un banco o en el piso. Usá la manija y tirá hacia abajo para llevar el codo al costado del cuerpo. Volvé a la posición inicial y repetí.', 142590),
  ('POLEA - DESCENSO DE HOMBRO', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas; Estabilización', 'Colocá la polea en posición alta. Empezá sosteniendo la manija del sistema de poleas abajo, al costado del cuerpo, con el codo bloqueado en extensión y el hombro elevado hacia arriba. Después, empujá el brazo hacia abajo mientras descendés el hombro. Mantené el codo completamente estirado todo el tiempo. Volvé lentamente a la posición inicial y repetí.', 140196),
  ('POLEA - APERTURAS INVERSAS UNILATERALES - TAJO DE ESPADA', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas; Estabilización', 'Colocá el cable en posición alta y parate al costado de la polea. Empezá sosteniendo la manija, como se muestra. Después, tirá del cable en diagonal desde arriba hacia abajo, en dirección al lado opuesto del cuerpo. Volvé a la posición inicial y repetí.', 142625),
  ('POLEA - PRESS POR ENCIMA DE LA CABEZA ERGUIDO - PRESS MILITAR', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas; Estabilización', 'Colocá la polea en posición baja y sentate en un banco o silla completamente erguido, como se muestra. Usá las manijas y empujá hacia arriba, por encima de la cabeza. Volvé a la posición inicial y repetí.', 142589),
  ('POLEA EN W - RETRACCIONES ESCAPULARES', NULL, true, 'fortalecimiento', 'Hombro', 'Máquinas y poleas; Estabilización', 'Colocá los cables en posición media. Sostené las manijas del sistema de poleas con ambas manos. Empezá tirando de los cables hacia atrás mientras flexionás los codos y retraés los omóplatos (escápulas), como formando la letra W con los brazos, como se muestra. Volvé a la posición inicial y repetí.', 140202),
  ('AUTOMOVILIZACIÓN - DESLIZAMIENTO ANTERIOR - DECÚBITO DORSAL', NULL, true, 'activo_asistido', 'Hombro', 'Movilización', 'Acostate boca arriba y sostenete apoyado sobre los codos.', 227),
  ('PELOTA EN LA PARED', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Parado cerca de una pared, colocá una pelota a la altura del hombro sobre la pared. Inclinate un poco contra la pelota con la mano y después hacé girar la pelota en círculos chicos. Hacé unas vueltas en sentido horario y después movela en sentido antihorario. Repetí.', 240),
  ('REMOS INCLINADOS', NULL, true, 'activo_asistido', 'Hombro', 'Estabilización', 'De pie, inclinate hacia adelante y sostenete con el brazo sano. Con el brazo afectado empezando al costado del cuerpo, tirá del brazo hacia arriba flexionando el codo.', 173),
  ('BOSU - FLEXIÓN DE BRAZOS CON CAMBIO MODIFICADA', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Colocá una mano encima del Bosu y la otra en el piso. Hacé una flexión de brazos, cambiá la posición de las manos y repetí.', 159110),
  ('BOSU - FLEXIÓN DE BRAZOS CON CAMBIO - MODIFICADA', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Empezá en la posición ARRIBA de una flexión de brazos con ambas manos sobre el Bosu. Después, sacá una mano del Bosu hacia el costado mientras bajás el pecho hacia el piso. Después, volvé a la posición original y repetí del otro lado.', 5732),
  ('BOSU - INESTABLE - FLEXIÓN DE BRAZOS DE RODILLAS', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé flexiones de brazos, como se muestra, con las manos sobre una pelota Bosu y apoyado sobre las rodillas. Mantené las rodillas en contacto con el piso y la espalda derecha todo el tiempo.', 5589),
  ('BOSU - INESTABLE - FLEXIÓN DE BRAZOS', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé flexiones de brazos, como se muestra, con las manos encima de una pelota Bosu. Tratá de mantener la espalda derecha todo el tiempo.', 5588),
  ('BOSU - INESTABLE - FLEXIÓN DE BRAZOS CON BASTÓN', NULL, true, 'activo_asistido; fortalecimiento', 'Hombro', 'Estabilización', 'Hacé flexiones de brazos, como se muestra, sosteniendo un bastón sobre la pelota Bosu. Tratá de mantener el bastón lo más nivelado posible y la espalda derecha todo el tiempo.', 5590),
  ('BOSU CON LAS PUNTAS DE LOS PIES - FLEXIÓN DE BRAZOS', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé flexiones de brazos, como se muestra, con la pelota Bosu debajo de las puntas de los pies. Mantené la columna derecha todo el tiempo.', 5587),
  ('POLEA - JALONES AL PECHO', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Colocá el cable en posición alta. Sentate en un banco o silla y después tirá de la barra hacia abajo y hacia el pecho mientras flexionás los codos. Volvé a la posición inicial y repetí.', 140456),
  ('POLEA - REMO SENTADO', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Sentate en un banco y sostené la manija del sistema de poleas con ambas manos. Empezá estirando los brazos hacia adelante e inclinándote hacia adelante desde las caderas, en lugar de flexionar la columna. Después, tirá de las manijas hacia atrás dejando que los codos se flexionen hacia el costado del cuerpo. Mientras llevás los codos hacia atrás, empezá a inclinarte hacia atrás haciendo bisagra desde las caderas y manteniendo la columna derecha todo el tiempo. No dejes que los hombros se eleven hacia arriba. Volvé a la posición inicial y repetí.', 142591),
  ('POLEA - GOLPE DE SERRATO - PROTRACCIÓN ESCAPULAR', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Colocá la polea a la altura del hombro. Sostené la manija con el brazo derecho hacia adelante, por delante del cuerpo, con el codo estirado, como se muestra. Llevá el omóplato hacia adelante (protracción) de modo que la mano y el brazo avancen unos centímetros. Volvé a la posición inicial y repetí. Mantené los codos estirados todo el tiempo.', 140201),
  ('POLEA - REMOS NEUTROS DE PIE - 2 CABLES', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Colocá los cables en posición media. Sostené la manija del sistema de poleas con ambas manos. Empezá tirando del cable hacia atrás flexionando los codos hacia el costado del cuerpo. No dejes que los hombros se eleven hacia arriba. Volvé a la posición inicial y repetí.', 140200),
  ('POLEA CON SOGA EN W - RETRACCIONES ESCAPULARES - FACE PULLS', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Colocá las poleas en posición alta. Sostené el accesorio de soga y empezá tirando de los cables hacia atrás mientras flexionás los codos y retraés los omóplatos (escápulas), como formando la letra W con los brazos, como se muestra. Asegurate de mantener los omóplatos hacia abajo y atrás. Volvé a la posición inicial y repetí.', 143808),
  ('FONDOS EN LA SILLA', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Sentado en una silla con apoyabrazos, agarrá los apoyabrazos y empujate hacia arriba de modo que la cola se despegue de la silla. Después, bajá de forma controlada hasta la posición sentada normal. Si no podés elevarte, ayudate con las piernas lo menos posible.', 528),
  ('BANDA ELÁSTICA - JALONES AL PECHO / REMOS ALTOS', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé un nudo en la parte del medio de una banda elástica, colocalo en la parte de arriba y del lado opuesto de una puerta y cerrá la puerta. Sostené las puntas de la banda con ambos brazos elevados hacia adelante y los codos estirados. Los brazos deben estar en alto. Después, tirá de la banda hacia abajo flexionando los codos. Volvé a la posición inicial y repetí.', 4665),
  ('PELOTA DE EJERCICIOS - T EN DECÚBITO VENTRAL - PULGARES ARRIBA', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostate boca abajo sobre una pelota de ejercicios con los codos estirados. Elevá lentamente los brazos y volvé a la posición original. Los pulgares deben apuntar hacia arriba todo el tiempo.', 8440),
  ('PELOTA DE EJERCICIOS - Y EN DECÚBITO VENTRAL - PULGARES ARRIBA', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostate boca abajo sobre una pelota de ejercicios con los codos estirados y los brazos hacia adelante, como se muestra. El hombro debe estar en unos 120 grados de abducción. Elevá lentamente los brazos y volvé a la posición original. Los pulgares deben apuntar hacia arriba todo el tiempo.', 8442),
  ('PELOTA DE EJERCICIOS - EXTENSIÓN EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostate boca abajo sobre una pelota de ejercicios con los codos estirados y los brazos al costado del cuerpo, como se muestra. Después, elevá lentamente los brazos a lo largo del costado y volvé a la posición original.', 8439),
  ('PELOTA DE EJERCICIOS - W EN DECÚBITO VENTRAL - RE', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostate boca abajo sobre una pelota de ejercicios con los codos flexionados. Elevá lentamente los brazos mientras retraés los omóplatos y después volvé a la posición original. Las palmas deben mirar hacia abajo todo el tiempo.', 8441),
  ('BOSU INVERTIDO - FLEXIÓN DE BRAZOS MODIFICADA - INESTABLE', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé flexiones de brazos, como se muestra, sosteniendo una pelota Bosu invertida y apoyado sobre las rodillas. Mantené las rodillas en contacto con el piso y la espalda derecha todo el tiempo. Tratá de mantener la plataforma del Bosu lo más nivelada posible.', 5579),
  ('BOSU INVERTIDO - INCLINACIÓN LATERAL EN PLANCHA - INESTABLE - TRASLADO DE PESO', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'En posición de plancha sobre las puntas de los pies y sosteniendo una pelota Bosu invertida, como se muestra, inclina el Bosu de lado a lado mientras trasladás el peso del cuerpo.', 5586),
  ('BOSU INVERTIDO - INCLINACIÓN LATERAL EN PLANCHA - INESTABLE - TRASLADO DE PESO - MODIFICADA', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Empezá en posición de cuatro apoyos y sostené una pelota Bosu invertida u otra superficie inestable multidireccional, como se muestra. Después, inclina el dispositivo de lado a lado alternando el traslado del peso del cuerpo por un brazo y después por el otro.', 8072),
  ('BOSU INVERTIDO - FLEXIONES DE BRAZOS - INESTABLE', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé flexiones de brazos, como se muestra, sosteniendo una pelota Bosu invertida. Tratá de mantener la plataforma del Bosu lo más nivelada posible y la espalda derecha todo el tiempo.', 5578),
  ('BOSU INVERTIDO - CÍRCULOS CON TRASLADO DE PESO EN UN BRAZO', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Empezá en posición de cuatro apoyos y colocá el brazo que vas a trabajar sobre una pelota Bosu invertida u otra superficie inestable multidireccional, como se muestra. Después, trasladá el peso del cuerpo a través de ese brazo mientras movés el dispositivo en un patrón circular.', 8071),
  ('ROTACIONES EXTERNAS CON KETTLEBELL - DECÚBITO LATERAL', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Empezá acostado de costado sosteniendo una kettlebell con el codo flexionado y apoyado sobre el costado del cuerpo. Colocá una toalla chica enrollada entre el brazo y el cuerpo. Después, llevá el antebrazo y la mano desde el piso hacia el techo, como se muestra. Luego bajá a la posición inicial. Repetí.', 79163),
  ('PRESS CON KETTLEBELL', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Acostate boca arriba con el codo apoyado separado del costado del cuerpo. Empezá sosteniendo la kettlebell con el codo flexionado a 90 grados y el antebrazo derecho hacia arriba. Después, empujá la kettlebell derecho hacia arriba y extendé completamente el brazo. Volvé a la posición inicial y repetí.', 79153),
  ('FLEXIÓN DE BRAZOS PARCIAL EN DIAMANTE MODIFICADA', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostado boca abajo, apoyá las manos en el piso formando un diamante con los pulgares y los índices. Usá los brazos para empujarte hacia arriba, como se muestra. Bajá parcialmente y después volvé a empujar hacia arriba. Repetí. Mantené las rodillas en contacto con el piso y la espalda derecha todo el tiempo.', 126752),
  ('PLANCHA PLUS MODIFICADA', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé una plancha sobre las rodillas y los codos, como se muestra, y sostené la posición. Manteniendo esa posición, llevá los omóplatos hacia adelante (protracción) para elevarte unos centímetros más y después volvé a la posición original y repetí.', 8426),
  ('PLANCHA MODIFICADA CON FLEXIÓN PLUS DE SERRATO', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Empezá en posición de flexión de brazos modificada, sobre las manos y las rodillas, con los codos completamente extendidos, como se muestra. Mantené esta posición mientras llevás los omóplatos hacia adelante para elevar el cuerpo unos centímetros. Después, volvé a la posición original y repetí.', 9346),
  ('PLANCHA PLUS', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé una plancha sobre los codos y, manteniendo esa posición, llevá los omóplatos hacia adelante (protracción) para elevarte unos centímetros más; después bajá y repetí.', 8425),
  ('PLANCHA PLUS - MÚSCULO SERRATO', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Empezá en posición de flexión de brazos sobre las manos y las puntas de los pies, con los codos completamente extendidos, como se muestra. Mantené esta posición mientras llevás los omóplatos hacia adelante para elevar el cuerpo unos centímetros. Después, volvé a la posición original.', 8444),
  ('FLEXIÓN PLIOMÉTRICA - MODIFICADA', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostate boca abajo y apoyá las manos hacia los costados, a la altura del pecho. Usá los brazos para empujarte hacia arriba apoyándote sobre las rodillas, de modo que ambas manos se despeguen del piso por un instante. Amortiguá la caída apoyando rápido las manos en el piso para bajar el pecho. Repetí. Mantené las rodillas en contacto con el piso y la espalda derecha todo el tiempo.', 130992),
  ('FLEXIÓN DE BRAZOS PLIOMÉTRICA', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé flexiones de brazos con despegue sobre y fuera de 2 cajones o escalones. Empezá en posición de flexión con los brazos sobre los 2 cajones, como se muestra. Después, empujá el cuerpo hacia arriba con los brazos y caé en el piso. Después, empujate desde el piso hacia arriba y caé sobre los cajones.', 7858),
  ('Y EN DECÚBITO VENTRAL - FLEXIÓN', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostado boca abajo, elevá lentamente los brazos hacia adelante y por encima de la cabeza con los codos estirados.', 188),
  ('RETRACCIÓN Y EXTENSIÓN EN DECÚBITO VENTRAL - I EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostado boca abajo con los brazos al costado del cuerpo, movés lentamente los brazos hacia arriba, en dirección al techo, mientras apretás los omóplatos hacia abajo y hacia la columna.', 14079),
  ('RETRACCIÓN ESCAPULAR EN DECÚBITO VENTRAL - MANOS ENTRELAZADAS', NULL, true, 'pasivo', 'Hombro', 'Estabilización', 'Empezá acostado boca abajo y colocá una toalla o almohada debajo de la frente. Entrelazá las manos detrás de la cabeza. Después, despegá los codos del piso mientras juntás los omóplatos. Mantené, volvé a la posición inicial y repetí.', 160561),
  ('T EN DECÚBITO VENTRAL - PALMA ABAJO', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostate boca abajo con el codo estirado y el brazo colgando hacia el piso. Después, fijá la escápula retrayéndola hacia la columna y hacia abajo, en dirección a los pies. Después, elevá lentamente el brazo manteniendo el codo estirado todo el tiempo, como se muestra. La palma debe mirar hacia abajo mientras el brazo sube.', 7882),
  ('T EN DECÚBITO VENTRAL - PULGAR ARRIBA', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostate boca abajo con el codo estirado y el brazo colgando hacia el piso. Después, fijá la escápula retrayéndola hacia la columna y hacia abajo, en dirección a los pies. Después, elevá lentamente el brazo manteniendo el codo estirado todo el tiempo, como se muestra. El pulgar debe apuntar hacia arriba mientras el brazo sube.', 532),
  ('T EN DECÚBITO VENTRAL SOBRE PELOTA DE EJERCICIOS', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostate boca abajo sobre una pelota de ejercicios con los codos estirados. Elevá lentamente los brazos y volvé a la posición original.', 7859),
  ('Y EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostado boca abajo con los brazos estirados hacia arriba, como se muestra, movés lentamente los brazos hacia el techo mientras apretás los omóplatos hacia abajo y hacia la columna.', 14082),
  ('FLEXIÓN DE BRAZOS', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostado boca abajo, usá los brazos para empujarte hacia arriba, como se muestra. Mantené las puntas de los pies en contacto con el piso y la espalda derecha todo el tiempo.', 529),
  ('FLEXIÓN DE BRAZOS - SUBIDA LATERAL AL ESCALÓN', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Empezá en posición de plancha con los codos completamente extendidos encima de un cajón o superficie elevada. Hacé una flexión de brazos y después caminá con los brazos hacia abajo, saliendo del cajón hacia el piso. Hacé una flexión de brazos en el piso y después volvé caminando con los brazos hasta el cajón, a la posición inicial.', 13124),
  ('FLEXIÓN DE BRAZOS - MODIFICADA', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostado boca abajo, usá los brazos para empujarte hacia arriba, como se muestra. Mantené las rodillas en contacto con el piso y la espalda derecha todo el tiempo.', 460),
  ('FLEXIÓN DE BRAZOS - MODIFICADA - SUPERFICIE INESTABLE', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé flexiones de brazos sobre las rodillas y con las manos apoyadas en una superficie inestable, como una almohadilla de espuma y un balón medicinal chico.', 127515),
  ('FLEXIÓN DE BRAZOS - DIAMANTE', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostado boca abajo, apoyá las manos en el piso formando un diamante con los pulgares y los índices. Usá los brazos para empujarte hacia arriba, como se muestra. Mantené las puntas de los pies en contacto con el piso y la espalda derecha todo el tiempo.', 13122),
  ('FLEXIÓN DE BRAZOS MODIFICADA - DIAMANTE', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostado boca abajo, apoyá las manos en el piso formando un diamante con los pulgares y los índices. Usá los brazos para empujarte hacia arriba, como se muestra. Mantené las rodillas en contacto con el piso y la espalda derecha todo el tiempo.', 13123),
  ('FLEXIÓN PLUS EN LA MESA - SERRATO', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Empezá en posición de flexión de brazos sobre las manos, apoyado contra una mesa o mesada, como se muestra. Mantené esta posición mientras llevás los omóplatos hacia adelante para elevar el cuerpo unos centímetros. Después, volvé a la posición original. Progresá parándote más lejos de la mesa.', 8445),
  ('FLEXIÓN DE BRAZOS CON ROTACIÓN', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Acostado en el piso con las manos separadas al ancho de los hombros y ubicadas debajo de la articulación del hombro, hacé una flexión de brazos. Cerca del final del movimiento, rotá el cuerpo hacia un lado mientras elevás el brazo de ese mismo lado hacia el techo, equilibrándote sobre el otro brazo, como se muestra. Volvé a apoyar el brazo en el piso y bajá el cuerpo con ambos brazos. Repetí del otro lado.', 36381),
  ('VALLAS DE ESTABILIZACIÓN ESCAPULAR - CUATRO APOYOS', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Empezá en posición de gateo. Comenzá elevando un brazo hacia adelante, por delante del cuerpo. Mientras está en el aire, movelo un poco hacia el costado. Bajá y repetí este patrón mientras vas moviendo el brazo hacia abajo, en dirección al costado del cuerpo, como se muestra.', 160563),
  ('DECÚBITO LATERAL - RELOJ ESCAPULAR', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Empezá acostado de costado con el brazo que vas a trabajar apoyado sobre el cuerpo en posición neutra. Después, llevá el omóplato hacia arriba, en dirección a la cabeza (12 en punto), mantené y volvé a la posición inicial. Después, llevá el hombro hacia adelante (3 en punto), mantené y volvé a la posición inicial. Después, llevá el hombro hacia abajo, en dirección a la cintura (6 en punto), mantené y volvé a la posición inicial. Por último, llevá el hombro hacia atrás, en dirección al centro de la columna (9 en punto), mantené y volvé a la posición neutra inicial.', 79164),
  ('DECÚBITO DORSAL - ABDUCCIÓN HORIZONTAL CON BANDA ELÁSTICA - PALMAS ABAJO', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Acostate boca arriba sosteniendo una banda elástica hacia el techo con los codos estirados y las palmas hacia abajo. Después, separá los brazos tirando hacia los costados y hacia el piso, como se muestra. Los codos deben estar estirados todo el tiempo. Volvé a la posición inicial y repetí.', 28008),
  ('FLEXIONES DE BRAZOS EN LA MESA', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Hacé flexiones de brazos, como se muestra, apoyado contra una mesa.', 36),
  ('FONDOS DE TRÍCEPS EN EL BANCO', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Sentate en el borde de un banco. Deslizate hacia adelante. Después, bajá el cuerpo hacia el piso flexionando los codos. Volvé a subir estirando los brazos y repetí.', 170249),
  ('FONDOS DE TRÍCEPS EN LA SILLA', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Sentate en el borde de una silla. Deslizate hacia adelante. Después, bajá el cuerpo hacia el piso flexionando los codos. Volvé a subir estirando los brazos y repetí.', 458),
  ('TRX SUSPENSIÓN - PRESS DE PECHO', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Sostené las manijas del TRX de espaldas al anclaje, con los brazos por delante del cuerpo y los pies ubicados por detrás del anclaje. Después, flexioná los codos para bajar el cuerpo a una posición de flexión de brazos. Mantené el tronco derecho y la columna en posición neutra.', 31456),
  ('TRX SUSPENSIÓN - APERTURAS', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Sostené las manijas del TRX de frente al anclaje. Inclinate hacia atrás y después llevá los brazos hacia adelante, cruzándolos por delante del cuerpo, como si te dieras un abrazo. Alterná qué brazo queda arriba en cada repetición.', 31509),
  ('TRX SUSPENSIÓN - EXTENSIÓN DE HOMBRO', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Sostené las manijas del TRX de frente al anclaje. Mantené los codos estirados y las manijas abajo, a la altura de los muslos. Después, inclinate hacia atrás y dejá que los brazos suban por delante del cuerpo. Después, tirá hacia abajo para volver a la posición de pie original.', 31420),
  ('TRX SUSPENSIÓN - COMBINADO SENTADILLA Y CURL DE BÍCEPS', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Sostené las manijas del TRX de frente al anclaje. Hacé una sentadilla y después un curl de bíceps al acercarte a la posición de pie. No dejes que las rodillas pasen por delante de los dedos de los pies. Mantené las rodillas alineadas con los pies.', 31508),
  ('TRX SUSPENSIÓN - COMBINADO SENTADILLA, REMO Y CURL DE BÍCEPS', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Sostené las manijas del TRX de frente al anclaje. Hacé una sentadilla y después un remo al acercarte a la posición de pie. En la repetición siguiente, hacé una sentadilla y después un curl de bíceps. Alterná estos dos patrones de movimiento en cada repetición.', 31507),
  ('TRX SUSPENSIÓN - W', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Sostené las manijas del TRX de frente al anclaje. Parate con los brazos en posición de W, como se muestra a la derecha. Después, inclinate hacia atrás mientras estirás los brazos. Después, volvé a la posición original traccionando para volver a pararte. Los omóplatos deben quedar retraídos y hacia abajo en la posición de pie.', 31428),
  ('FLEXIÓN DE BRAZOS EN LA PARED - PLIOMÉTRICA', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización', 'Parate inclinado hacia una pared y hacé flexiones de brazos de modo que las manos se despeguen de la pared y no la toquen en el punto más alto del movimiento. Volvé a caer en la flexión y repetí.', 8257),
  ('ELEVACIÓN ESCAPULAR EN LA PARED', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Empezá con buena postura de pie frente a una pared y apoyá las manos en la pared con los brazos extendidos hacia el techo. Manteniendo los codos estirados, elevá los omóplatos dejando que las manos se deslicen hacia arriba, en dirección al techo. Después, bajá de forma controlada. Repetí. Mantené los codos estirados todo el tiempo.', 71743),
  ('CÍRCULOS DESLIZANDO EN LA PARED', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Colocá una toalla doblada sobre una pared o puerta de superficie lisa. Parate de costado con el brazo estirado. Después, deslizá la toalla en un patrón circular. Hacé varias vueltas en sentido horario y después cambiá al sentido antihorario.', 8259),
  ('DESLIZAMIENTOS EN LA PARED - ABDUCCIÓN', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Colocá una toalla doblada sobre una pared o puerta de superficie lisa. Parate de costado y, con el brazo estirado, deslizá la toalla hacia arriba y abajo, como se muestra.', 8258),
  ('DESLIZAMIENTOS EN LA PARED - HORIZONTAL', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Colocá una toalla doblada sobre una pared o puerta de superficie lisa. Parate de costado y, con el brazo estirado, deslizá la toalla de lado a lado, como se muestra.', 8260),
  ('CARGA DE PESO EN MIEMBRO SUPERIOR', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Inclina suavemente el peso del cuerpo sobre la mano o el puño. Mantené el codo estirado todo el tiempo.', 37),
  ('TRASLADO DE PESO - MIEMBRO SUPERIOR - PARED', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Apoyá las manos en una pared e inclina el peso del cuerpo sobre los brazos. Después, trasladá el peso de lado a lado. Mantené los codos estirados todo el tiempo.', 8261),
  ('TRASLADO DE PESO ADELANTE Y ATRÁS - BRAZOS BILATERALES', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Apoyá las manos sobre una mesa con los codos estirados. Después, inclina parte del peso del cuerpo sobre los brazos y balanceate suavemente hacia adelante y atrás (si te molesta en las muñecas, podés apoyar los puños sobre una toalla doblada). Mantené los codos estirados todo el tiempo.', 7081),
  ('TRASLADO DE PESO ADELANTE Y ATRÁS - UN SOLO BRAZO', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Apoyá el puño del brazo afectado sobre una mesa con el codo estirado (colocá una toalla doblada entre el puño y la mesa para mayor comodidad). Después, inclina parte del peso del cuerpo sobre el brazo y trasladá suavemente el peso hacia adelante y atrás por encima del brazo. Mantené el codo estirado todo el tiempo.', 135810),
  ('TRASLADO DE PESO LATERAL - BRAZOS BILATERALES', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Apoyá las manos sobre una mesa con los codos estirados. Después, inclina parte del peso del cuerpo sobre los brazos y balanceate suavemente de lado a lado (si te molesta en las muñecas, podés apoyar los puños sobre una toalla doblada). Mantené los codos estirados todo el tiempo.', 7887),
  ('TRASLADO DE PESO LATERAL - UN SOLO BRAZO', NULL, true, 'activo', 'Hombro', 'Estabilización', 'Apoyá el puño sobre una mesa con el codo estirado (colocá una toalla doblada entre el puño y la mesa para mayor comodidad). Después, inclina parte del peso del cuerpo sobre el brazo y balanceate suavemente de lado a lado. Mantené el codo estirado todo el tiempo.', 135811),
  ('TRASLADO DE PESO - ADELANTE Y ATRÁS', NULL, true, 'activo', 'Hombro', 'Estabilización', 'En posición de cuatro apoyos, trasladá el peso hacia adelante sobre los brazos y después hacia atrás, en dirección a las piernas.', 241),
  ('TRASLADO DE PESO - LATERAL', NULL, true, 'activo', 'Hombro', 'Estabilización', 'En posición de cuatro apoyos, trasladá el peso de lado a lado.', 242),
  ('TRASLADO DE PESO ADELANTE Y ATRÁS - UN SOLO BRAZO', NULL, true, 'activo', 'Hombro', 'Estabilización', 'En posición de cuatro apoyos, elevá un brazo de modo que quedes sostenido por un brazo y las piernas. Después, trasladá el peso hacia adelante y después hacia atrás.', 6975),
  ('TRASLADO DE PESO LATERAL - UN SOLO BRAZO', NULL, true, 'activo', 'Hombro', 'Estabilización', 'En posición de cuatro apoyos, elevá un brazo de modo que quedes sostenido por un brazo y las piernas. Después, trasladá el peso de lado a lado.', 4669),
  ('ROTACIÓN INTERNA CON KETTLEBELL - DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Hombro', 'Estabilización; Estiramientos', 'Acostate boca arriba con una toalla chica enrollada o una almohada debajo del codo, con el codo apoyado a unos 90 grados del costado del cuerpo. Sostené la kettlebell con el codo flexionado a 90 grados y el antebrazo derecho hacia arriba. Empezá el movimiento rotando el hombro hacia atrás de modo que el antebrazo baje hacia la horizontal, como se muestra. Después, volvé a la posición inicial y repetí.', 79152),
  ('BASTÓN POR DETRÁS DE LA ESPALDA - ESTIRAMIENTO DE ROTACIÓN INTERNA Y ADUCCIÓN', NULL, true, 'activo_asistido', 'Hombro', 'Estiramientos', 'Sosteniendo un bastón por detrás de la espalda, tirá lentamente del brazo que trabajás hacia el centro de la espalda.', 10686),
  ('ESTIRAMIENTO DE BÍCEPS CON CINTA MULTIANILLA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Sostené una cinta de estiramiento por detrás de la espalda y después elevala y mantené, como se muestra, para estirar la parte de adelante del hombro.', 38882),
  ('BOSU - ESTIRAMIENTO DE DORSALES', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Empezá arrodillado al lado de un Bosu. Después, inclinate hacia el costado y acostate sobre el Bosu con el brazo por encima de la cabeza. Deberías quedar en decúbito lateral sobre el Bosu.', 5784),
  ('ESTIRAMIENTO DE ROTACIÓN EXTERNA CON BASTÓN - ALMOHADA', NULL, true, 'pasivo; activo_asistido', 'Hombro', 'Estiramientos', 'Acostate boca arriba con una almohada debajo del hombro afectado. Sostené un bastón con ambas manos. Del lado afectado, mantené el codo flexionado a 90 grados con el brazo separado del costado del cuerpo unos 30-45 grados. Usá el otro brazo para empujar el bastón y rotar el brazo afectado hasta sentir el estiramiento. Mantené, volvé a la posición inicial y repetí.', 46067),
  ('ESTIRAMIENTO DE PECHO CON RODILLO DE ESPUMA - 90/90', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Acostate sobre un rodillo de espuma y dejá que los brazos caigan hacia el piso con los codos flexionados y separados 90 grados del costado del cuerpo, como se muestra. Los hombros deben estar en rotación externa, de modo que el dorso de las muñecas se acerque al piso. Mantené para sentir un estiramiento suave en el pecho y los hombros.', 26187),
  ('ESTIRAMIENTO DE PECHO CON RODILLO DE ESPUMA - 90/90', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Acostate sobre un rodillo de espuma y dejá que los brazos caigan hacia el piso con los codos flexionados y separados 90 grados del costado del cuerpo, como se muestra. Los hombros deben estar en rotación externa, de modo que el dorso de las muñecas se acerque al piso. Mantené para sentir un estiramiento suave en el pecho y los hombros.', 85322),
  ('ESTIRAMIENTO DE PECHO CON RODILLO DE ESPUMA - APERTURAS', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Acostate sobre un rodillo de espuma con las manos detrás de la cabeza. Después, bajá los codos hacia el piso. Mantené para sentir un estiramiento suave en el pecho.', 26188),
  ('ESTIRAMIENTO DE PECHO CON RODILLO DE ESPUMA - T', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Acostate sobre un rodillo de espuma y dejá que los brazos caigan hacia el piso con los codos estirados, como se muestra. Mantené para sentir un estiramiento suave en el pecho.', 26190),
  ('ESTIRAMIENTO DE PECHO CON RODILLO DE ESPUMA - Y', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Acostate sobre un rodillo de espuma y elevá los brazos por encima de la cabeza, como se muestra. Mantené para sentir un estiramiento suave en el pecho.', 26189),
  ('ESTIRAMIENTO DE PECHO CON CINTA MULTIANILLA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Sostené una cinta de estiramiento por encima de la cabeza y después bajá el brazo por detrás de la cabeza para estirar la parte de adelante del pecho.', 38884),
  ('ESTIRAMIENTO DE PECHO EN Y - MEDIO RODILLO DE ESPUMA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Acostate sobre un medio rodillo de espuma y llevá los brazos hacia arriba y afuera, hacia los costados, formando la letra Y, como se muestra. Mantené para sentir un estiramiento suave en los hombros y el pecho.', 85339),
  ('ESTIRAMIENTO CRUZANDO EL BRAZO', NULL, true, 'pasivo', 'Hombro', 'Estiramientos', 'Empezá agarrando el codo y tirando de él cruzando por delante del cuerpo para un estiramiento suave. Mantené, volvé a la posición inicial y repetí.', 182),
  ('ESTIRAMIENTO DEL DORSAL ANCHO SENTADO CON PIERNAS CRUZADAS', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Empezá sentado con las piernas cruzadas y el brazo elevado hacia el costado y por encima de la cabeza. Con el otro brazo, agarrate el muslo contrario. Después, inclinate hacia el lado contrario al brazo elevado hasta sentir un estiramiento suave en el costado del cuerpo. Mantené, volvé a la posición inicial y repetí.', 160176),
  ('ESTIRAMIENTO DE BRAZOS EN ÁGUILA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Cruzá los brazos de modo que el codo de un brazo quede por encima del otro, con los codos flexionados, como se muestra. Juntá las palmas. Si no llegás a juntar las palmas, tratá de tocar la palma de una mano con los dedos de la otra. Mantené, volvé a la posición inicial y cambiá de lado.', 177018),
  ('ESTIRAMIENTO DE ROTACIÓN EXTERNA EN RANGO FINAL CON PALO DE GOLF', NULL, true, 'pasivo', 'Hombro', 'Estiramientos', 'Este es un estiramiento agresivo de rango final. Sostené la cabeza de un palo de golf con la mano del hombro que querés trabajar, como se muestra, y usá la otra mano para tirar del palo de modo que estire el hombro hacia una posición de mayor rotación externa.', 16046),
  ('ESTIRAMIENTO DE ROTACIÓN EXTERNA - RE EN LA MESA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Sentado, apoyá el antebrazo sobre una mesa e inclinate hacia adelante hasta sentir un estiramiento.', 174),
  ('GERIÁTRICO - ESTIRAMIENTO CRUZANDO EL BRAZO', NULL, true, 'pasivo', 'Hombro', 'Estiramientos', 'Empezá agarrando el codo y tirando de él cruzando por delante del cuerpo para un estiramiento suave. Mantené, volvé a la posición inicial y repetí.', 125288),
  ('MANO DETRÁS DE LA ESPALDA - ESTIRAMIENTO DE ROTACIÓN EXTERNA Y TRÍCEPS', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Colocá una mano detrás de la espalda y llevala hacia arriba, en dirección al centro de los omóplatos. Al mismo tiempo, llevá la otra mano hacia arriba y por detrás de la parte de arriba del hombro. El objetivo es tocar los dedos de ambas manos. Mantené, bajá, relajá y repetí.', 152511),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA - CINTA HACIA ADELANTE', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Colocá el brazo detrás de la espalda y usá una cinta para tirar del brazo hacia adelante, como se muestra. Asegurate de mantener el omóplato hacia abajo y atrás durante el estiramiento.', 66772),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA - MESA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Empezá de espaldas a una mesa. Colocá la mano detrás de la espalda y apoyala sobre la mesa con la palma hacia arriba y plana. Después, flexioná las rodillas para bajar el cuerpo y estirar el hombro. Mantené el estiramiento. Volvé a la posición inicial y repetí.', 79116),
  ('ESTIRAMIENTO DE RI CON CINTA MULTIANILLA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Colocá el brazo detrás de la espalda y usá una cinta para tirar del brazo hacia arriba a lo largo de la columna, generando un estiramiento en rotación interna del hombro.', 38895),
  ('ESTIRAMIENTO DE DORSAL EN EL MARCO DE LA PUERTA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Llevá el brazo por encima de la cabeza y agarrate de la pared en el vano de una puerta, como se muestra. Después, flexioná las rodillas y la cintura para estirar el hombro y la espalda. Para aumentar la intensidad del estiramiento, rotá levemente el cuerpo hacia el brazo afectado.', 39452),
  ('ESTIRAMIENTO DE DORSAL - ESTIRAMIENTO DEL DORSAL ANCHO', NULL, true, 'pasivo', 'Hombro', 'Estiramientos', 'Empezá erguido y con los brazos por encima de la cabeza. Después, agarrá la muñeca del lado que querés estirar y llevala hacia el costado inclinando el tronco hasta sentir un estiramiento suave en el costado del cuerpo. Puede que necesites inclinarte levemente hacia adelante para sentir el estiramiento.', 6976),
  ('ESTIRAMIENTO DE DORSAL CON CINTA MULTIANILLA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Sentate en el piso sosteniendo una cinta de estiramiento por encima de la cabeza. Después, inclinate hacia el costado para estirar la espalda y el hombro. Puede que necesites inclinarte levemente hacia adelante para sentir el estiramiento.', 38946),
  ('ESTIRAMIENTO DE PECHO MEDIO - MEDIO RODILLO DE ESPUMA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Acostate sobre un medio rodillo de espuma y bajá los brazos hacia los costados formando la letra T, como se muestra. Mantené para sentir un estiramiento suave en los hombros y el pecho.', 85338),
  ('ESTIRAMIENTO DEL TRAPECIO MEDIO', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Juntá las manos y los antebrazos, como se muestra, mientras llevás los hombros y los omóplatos hacia adelante hasta sentir un estiramiento en la parte alta de la espalda.', 5888),
  ('ESTIRAMIENTO DE PECTORALES EN LA ESQUINA - ALTO', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Parado en la esquina de una pared, apoyá los brazos sobre las paredes apuntando hacia arriba, como se muestra. Dá un paso hacia adelante en dirección a la esquina. Flexioná la rodilla de adelante hasta sentir un estiramiento en la parte de adelante del pecho o de los hombros. NOTA: las piernas deben controlar el estiramiento flexionando o estirando la rodilla de adelante.', 6548),
  ('ESTIRAMIENTO DE PECTORALES EN LA ESQUINA - BAJO', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Parado en la esquina de una pared, apoyá los brazos hacia abajo a lo largo de las paredes, como se muestra. Dá un paso hacia adelante en dirección a la esquina. Flexioná la rodilla de adelante hasta sentir un estiramiento en la parte de adelante del pecho o de los hombros. Los brazos deben apuntar hacia abajo, hacia el piso. NOTA: las piernas deben controlar el estiramiento flexionando o estirando la rodilla de adelante.', 6549),
  ('ESTIRAMIENTO DE PECTORALES EN EL MARCO DE LA PUERTA - UN BRAZO - ALTO', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Parado en el vano de una puerta, apoyá el brazo hacia arriba sobre el marco e inclinate hacia adelante hasta sentir un estiramiento en la parte de adelante del pecho o del hombro. El brazo debe apuntar hacia arriba, hacia el techo, a lo largo del marco. NOTA: las piernas deben controlar cuánto estirás, flexionando o estirando la rodilla al pasar por la puerta.', 6285),
  ('ESTIRAMIENTO DE PECTORALES EN EL MARCO DE LA PUERTA - UN BRAZO - BAJO', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Parado en el vano de una puerta, apoyá el brazo hacia abajo sobre el marco y dá un paso hacia adelante atravesando la puerta. Después, flexioná la rodilla de adelante hasta sentir un estiramiento en la parte de adelante del pecho o del hombro. El brazo debe apuntar hacia abajo, hacia el piso, a lo largo del marco. NOTA: las piernas deben controlar cuánto estirás, flexionando o estirando la rodilla al pasar por la puerta.', 6286),
  ('ESTIRAMIENTO DEL PECTORAL MENOR', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Colocá una toalla de cocina chica enrollada entre los omóplatos mientras estás acostado boca arriba. Dejá que los hombros caigan hacia el piso para estirar el pecho. Para un estiramiento más intenso, podés juntar los omóplatos.', 39439),
  ('ESTIRAMIENTO DEL PECTORAL MENOR - RODILLO DE ESPUMA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Acostate sobre un rodillo de espuma y bajá los brazos a los costados, como se muestra. Mantené para sentir un estiramiento suave en los hombros y el pecho.', 85330),
  ('ESTIRAMIENTO DE LA CÁPSULA POSTERIOR', NULL, true, 'pasivo', 'Hombro', 'Estiramientos', 'Acostado de costado, agarrá el codo del brazo de abajo y tirá suavemente hacia arriba y cruzando por delante del cuerpo. Mantené para un estiramiento suave. Bajá el brazo a la posición inicial y repetí.', 18702),
  ('ESTIRAMIENTO ESCAPULAR EN POSICIÓN DE REZO', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Empezá sentado en una silla con las manos juntas y los codos abiertos hacia los costados. Después, llevá los codos hacia adentro y tratá de juntar los antebrazos y los codos, como se muestra. Mantené, relajá y repetí.', 177016),
  ('ESTIRAMIENTO DE EXTENSIÓN DE HOMBRO - MESA', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'De espaldas a una mesa o mesada, apoyá las manos sobre la mesa detrás tuyo y flexioná lentamente las rodillas dejando que los codos se flexionen hasta sentir un estiramiento.', 244),
  ('ESTIRAMIENTO DE ABDUCCIÓN CON POLEA DE HOMBRO', NULL, true, 'activo_asistido', 'Hombro', 'Estiramientos', 'Usá una polea de puerta y sentate de espaldas a la puerta. Tirá lentamente hacia abajo con un brazo para elevar hacia el costado el brazo que querés trabajar. Mantené, bajá y repetí.', 164049),
  ('ESTIRAMIENTO DE ROTACIÓN EXTERNA CON POLEA DE HOMBRO - 45', NULL, true, 'activo_asistido', 'Hombro', 'Estiramientos', 'Usá una polea de puerta y sentate de espaldas a la puerta. Elevá el brazo afectado 45 grados hacia el costado con el codo flexionado. Empezá tirando lentamente hacia abajo con el brazo sano para asistir la rotación externa del hombro afectado hasta sentir un estiramiento suave. Mantené, volvé a la posición inicial y repetí.', 164051),
  ('ESTIRAMIENTO DE ROTACIÓN EXTERNA CON POLEA DE HOMBRO - 90', NULL, true, 'activo_asistido', 'Hombro', 'Estiramientos', 'Usá una polea de puerta y sentate de espaldas a la puerta. Elevá el brazo afectado 90 grados hacia el costado con el codo flexionado. Empezá tirando lentamente hacia abajo con el brazo sano para asistir la rotación externa del hombro afectado hasta sentir un estiramiento suave. Mantené, volvé a la posición inicial y repetí.', 164053),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA CON POLEA DE HOMBRO', NULL, true, 'activo_asistido', 'Hombro', 'Estiramientos', 'Usando poleas de puerta y de espaldas a la puerta, tirá lentamente hacia abajo con el brazo sano de modo que el brazo afectado suba por detrás de la espalda hasta sentir un estiramiento. El brazo afectado debe estar relajado. El brazo sano hace el trabajo.', 5297),
  ('ESTIRAMIENTO EN PLANO ESCAPULAR CON POLEA DE HOMBRO', NULL, true, 'activo_asistido', 'Hombro', 'Estiramientos', 'Usá una polea de puerta y sentate de espaldas a la puerta. Tirá lentamente hacia abajo con un brazo para elevar el brazo que trabajás hacia arriba y levemente hacia el costado, en diagonal. Mantené, bajá y repetí.', 164059),
  ('ESTIRAMIENTO DE ABRAZO AL ÁRBOL', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Parate y llevá los brazos hacia adelante como si estuvieras abrazando un árbol. Los omóplatos deben quedar en protracción. Después, girá hacia un costado e inclinate hasta sentir un estiramiento en la zona media del omóplato del hombro que quedó más adelante.', 21688),
  ('ESTIRAMIENTO DE ABRAZO AL ÁRBOL CON PELOTA - ESTIRAMIENTO DE ROMBOIDES', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Parate y sostené una pelota de ejercicios rodeándola con los brazos lo más posible. Después, girá hacia un costado e inclinate hasta sentir un estiramiento en la zona media del omóplato del hombro que quedó más adelante.', 21687),
  ('ESTIRAMIENTO DE TRÍCEPS CON CINTA MULTIANILLA', NULL, true, 'pasivo', 'Hombro', 'Estiramientos', 'Colocá la anilla de la cinta en la mano del brazo que trabajás, con el brazo por encima de la cabeza, como se muestra. Usá la otra mano para tirar de la cinta hacia abajo, dejando que el codo se flexione hasta sentir un estiramiento en la parte de atrás del brazo de arriba.', 47195),
  ('ESTIRAMIENTO DE TRÍCEPS', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Flexioná el codo y usá el otro brazo para elevarlo cerca de la cabeza. Empujá suavemente el codo hacia arriba y atrás, en dirección a la oreja, hasta sentir un estiramiento en la parte de atrás del brazo. Mantené, relajá y repetí.', 238),
  ('TRX SUSPENSIÓN - ESTIRAMIENTO DE PECTORALES', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Con los pies en tijera (un pie adelante y otro atrás), sostené las manijas del TRX con el anclaje por detrás tuyo. Ubicá los brazos abiertos hacia los costados. Flexioná la rodilla de adelante para controlar un estiramiento suave en el pecho.', 31416),
  ('ESTIRAMIENTO DE ROTACIÓN EXTERNA EN LA PARED - RE', NULL, true, 'activo', 'Hombro', 'Estiramientos', 'Empezá parado en el vano de una puerta o en la esquina de una pared y apoyá la mano en la pared con el codo flexionado, como se muestra. Después, girá suavemente el cuerpo en dirección contraria para llevar el hombro a rotación externa hasta sentir un estiramiento. Mantené, volvé a la posición inicial y repetí.', 195),
  ('ESTIRAMIENTO DE FLEXIÓN CON BASTÓN - BILATERAL CON PULGARES', NULL, true, 'activo_asistido', 'Hombro', 'Estiramientos; Bastón', 'Acostate boca arriba y sostené un bastón o palo entre los pulgares y los índices, como se muestra. Empezá con el bastón sobre el regazo y los codos estirados. Después, elevá lentamente el bastón por encima de la cabeza hasta sentir un estiramiento suave. Mantené la posición y después volvé a bajarlo al regazo. Repetí.', 67069),
  ('ENCOGIMIENTOS DE HOMBROS - BASTÓN', NULL, true, 'activo_asistido', 'Hombro', 'Bastón', 'Sostené un bastón abajo, a la altura de la cintura. Después, elevá los hombros como encogiéndolos. Bajá y repetí.', 129114),
  ('AAROM - DESVIACIÓN RADIAL Y CUBITAL', NULL, true, 'activo', 'Codo y mano', NULL, 'Empezá entrelazando las manos con los dedos cruzados, como se muestra. Después, usá la mano sana para ayudar a mover la muñeca afectada hacia el lado del dedo meñique y después invertí la dirección, llevando la muñeca hacia el lado del pulgar.', 72553),
  ('AAROM - SUPINACIÓN Y PRONACIÓN', NULL, true, 'activo', 'Codo y mano', NULL, 'Empezá entrelazando las manos con los dedos cruzados, como se muestra. Después, usá la mano sana para ayudar a girar la muñeca afectada de modo que la palma quede hacia arriba. Después, usá la mano sana para girar la muñeca afectada en sentido contrario, de modo que la palma quede hacia abajo. Repetí alternando las direcciones.', 72555),
  ('PELOTA - PINZA DE TRES DEDOS', NULL, true, 'activo', 'Codo y mano', NULL, 'Con una pelota elástica, apretala con firmeza usando los primeros 3 dedos, como se muestra.', 5239),
  ('PELOTA - AGARRE CON DOS DEDOS', NULL, true, 'activo', 'Codo y mano', NULL, 'Con una pelota elástica, apretala con firmeza contra la palma de la mano usando el segundo y el tercer dedo.', 5230),
  ('PELOTA - AGARRE PLANO', NULL, true, 'activo', 'Codo y mano', NULL, 'Con una pelota elástica, apretala con firmeza contra la palma de la mano con un agarre plano, como se muestra.', 5231),
  ('PELOTA - AGARRE EN GANCHO', NULL, true, 'activo', 'Codo y mano', NULL, 'Con una pelota elástica, apretala con firmeza contra la palma de la mano con un AGARRE EN GANCHO, como se muestra.', 5233),
  ('PELOTA - AGARRE DE LLAVE', NULL, true, 'activo', 'Codo y mano', NULL, 'Con una pelota elástica, apretala con firmeza como si sostuvieras una llave. Apretala con el pulgar contra el costado del segundo dedo, como se muestra.', 5236),
  ('PELOTA - OPOSICIÓN', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Con una pelota elástica, apretala con firmeza en el fondo de la palma de la mano usando el pulgar y el quinto dedo, como se muestra.', 5234),
  ('PELOTA - PINZA', NULL, true, 'activo', 'Codo y mano', NULL, 'Con una pelota elástica, apretala con firmeza usando el pulgar y un dedo.', 5235),
  ('PELOTA - APRETAR', NULL, true, 'activo', 'Codo y mano', NULL, 'Con una pelota elástica, apretala con firmeza contra la palma de la mano.', 87),
  ('TRÍCEPS INCLINADO - PATADA DE TRÍCEPS', NULL, true, 'activo_asistido; fortalecimiento', 'Codo y mano', NULL, 'De pie, inclinate hacia adelante y apoyate con el brazo sano. Con el brazo afectado, sostené una pesa o mancuerna y mantené el codo pegado al costado del cuerpo en posición flexionada. Empezá extendiendo el codo mientras estirás el brazo y levantás la pesa, como se muestra. Volvé a la posición inicial y repetí. Mantené el codo pegado al cuerpo todo el tiempo.', 11052),
  ('CURL DE BÍCEPS - BRAQUIORRADIAL - CURL MARTILLO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Con el brazo al costado del cuerpo, flexioná el codo para elevar la pesa o mancuerna. Bajá y repetí. Mantené la palma mirando hacia el cuerpo todo el tiempo.', 30),
  ('POLEA - CURL DE BÍCEPS - UN BRAZO - DE FRENTE', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Parate de frente a la polea y sostené la manija con la polea en posición baja. Manteniendo el codo pegado al costado del cuerpo, flexioná el codo mientras elevás la mano. Bajá y repetí. Mantené la palma hacia arriba todo el tiempo.', 142544),
  ('POLEA - CURL DE BÍCEPS CON SOGA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Parate de frente a la polea y sostené el accesorio de soga con la polea en posición baja. Parate de frente a la máquina con los pies separados al ancho de los hombros y las rodillas levemente flexionadas. Sostené la soga con ambas manos. Flexioná y extendé los codos haciendo curls de bíceps.', 142543),
  ('POLEA - CURL DE BÍCEPS CON SOGA - DE ESPALDAS', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Parate de espaldas a la polea y sostené el accesorio de soga con la polea en posición baja. Parate de espaldas a la máquina. Sostené la soga con ambas manos con el cable pasando entre las piernas, como se muestra. Flexioná y extendé los codos haciendo curls de bíceps.', 142522),
  ('POLEA - CURL DE BÍCEPS A UN BRAZO - DE ESPALDAS', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Parate de espaldas a la polea y sostené la manija. Manteniendo el codo pegado al costado del cuerpo, flexioná el codo mientras elevás el antebrazo. Bajá y repetí. Mantené la palma hacia arriba todo el tiempo.', 142533),
  ('POLEA - EXTENSIÓN CRUZADA A UN BRAZO - TRÍCEPS', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Colocá la polea en posición alta. Parate de costado a la polea. Sostené la manija, como se muestra, con la mano elevada y cruzada hacia el pecho del lado contrario, con el codo flexionado. Tirá del cable hacia abajo y cruzando el cuerpo hasta que el codo quede estirado y la mano hacia el costado. Volvé a la posición inicial y repetí.', 142627),
  ('POLEA - CURL DE BÍCEPS CON BARRA RECTA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Parate de frente a la polea y sostené el accesorio de barra recta con la polea en posición baja. Flexioná y extendé los codos haciendo curls de bíceps.', 142534),
  ('POLEA - CURL DE MUÑECA CON BARRA RECTA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Colocá la polea en posición baja y sostené un accesorio de barra recta chica con ambas manos. Parate de frente a la polea con los codos estirados. Flexioná las muñecas hacia el cuerpo, como si aceleraras una moto. Bajá y repetí.', 142629),
  ('MANOS ENTRELAZADAS - AAROM DE FLEXIÓN Y EXTENSIÓN DE MUÑECA', NULL, true, 'activo', 'Codo y mano', NULL, 'Entrelazá los dedos de ambas manos, como se muestra. Después, usá la mano sana para asistir a la mano afectada llevando la muñeca a flexión y después a extensión, y repetí.', 66521),
  ('PINZA CON BROCHE', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Usá 2 dedos y apretá un broche de ropa o un clip.', 63),
  ('CLX - FLEXIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Apoyá el antebrazo sobre el muslo o una mesa. Colocá una punta de la banda CLX en el pie y sostené otra anilla con la palma hacia arriba. Subí y bajá la mano flexionando la muñeca, como se muestra.', 40588),
  ('DAR VUELTA MONEDAS', NULL, true, 'activo', 'Codo y mano', NULL, 'Colocá varias monedas sobre una mesa y dá vuelta cada moneda con la mano afectada.', 91),
  ('DESVIACIÓN RADIAL CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Apoyá el antebrazo sobre el muslo o una mesa. Después, sosteniendo una banda elástica, llevá la muñeca hacia arriba con la muñeca en posición neutra, como se muestra.', 33),
  ('EXTENSIONES DE TRÍCEPS BILATERALES CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá con los codos flexionados sosteniendo una banda elástica, como se muestra. Tirá de la banda hacia abajo mientras extendés los codos. Mantené los codos pegados al costado del cuerpo todo el tiempo.', 109435),
  ('DESVIACIÓN CUBITAL CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Sosteniendo una banda elástica, llevá la muñeca hacia el costado, como se muestra. Sostené una punta de la banda con una mano y estabilizala agarrando la banda a unos 30 cm de distancia. Movés la muñeca que trabajás de lado a lado, como se muestra.', 66),
  ('BANDA ELÁSTICA - CURLS DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Apoyá el antebrazo sobre el muslo o sobre una mesa. Después, sosteniendo una banda elástica, flexioná la muñeca hacia arriba con la palma hacia arriba.', 32),
  ('BANDA ELÁSTICA - EXTENSIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Apoyá el antebrazo sobre el muslo o sobre una mesa. Después, sosteniendo una banda elástica, llevá la muñeca hacia arriba con la palma hacia abajo.', 34),
  ('BANDA ELÁSTICA - PRONACIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Hacé un nudo en cada punta de una banda elástica. Sentado, pisá una punta de la banda y sostené la otra con la palma hacia arriba, apoyada sobre el muslo. La banda elástica tiene que salir de la mano por el lado del meñique, como se muestra. Empezá girando la muñeca y el antebrazo afectados hacia la posición de palma abajo, contra la resistencia de la banda. Volvé a la posición inicial y repetí.', 64),
  ('BANDA ELÁSTICA - SUPINACIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Hacé un nudo en cada punta de una banda elástica. Sentado, pisá una punta de la banda y sostené la otra con la palma hacia abajo, apoyada sobre el muslo. La banda elástica tiene que salir de la mano por el lado del pulgar, como se muestra. Empezá girando la muñeca y el antebrazo afectados hacia la posición de palma arriba, contra la resistencia de la banda. Volvé a la posición inicial y repetí.', 65),
  ('CURL DE BÍCEPS CON BANDA ELÁSTICA - AUTOFIJADA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Sentado, sostené y fijá una punta de la banda elástica sobre la rodilla. Sostené la otra punta con la otra mano, con el hombro extendido derecho hacia adelante y la palma hacia arriba, como se muestra. Flexioná el codo tirando contra la resistencia de la banda. Volvé a la posición inicial y repetí.', 471),
  ('VENDAJE ELÁSTICO - BÍCEPS', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75004),
  ('VENDAJE ELÁSTICO - SOPORTE PARA TÚNEL CARPIANO', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 74046),
  ('VENDAJE ELÁSTICO - PULGAR DEL GAMER', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75017),
  ('VENDAJE ELÁSTICO - CODO DE GOLFISTA - EPICONDILITIS MEDIAL', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73835),
  ('VENDAJE ELÁSTICO - CODO DE GOLFISTA - EPICONDILITIS MEDIAL', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75009),
  ('VENDAJE ELÁSTICO - BURSITIS OLECRANEANA', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75007),
  ('VENDAJE ELÁSTICO - CODO DE TENISTA - EPICONDILITIS LATERAL', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75015),
  ('VENDAJE ELÁSTICO - CODO DE TENISTA - EPICONDILITIS LATERAL', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73829),
  ('VENDAJE ELÁSTICO - FIBROCARTÍLAGO TRIANGULAR (TFC)', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75011),
  ('VENDAJE ELÁSTICO - TRÍCEPS', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75012),
  ('VENDAJE ELÁSTICO - ESGUINCE DE MUÑECA - SOPORTE', NULL, true, 'sin_clasificar', 'Codo y mano', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73833),
  ('CODO A 90 - PRONACIÓN Y SUPINACIÓN', NULL, true, 'activo', 'Codo y mano', NULL, 'Flexioná el codo a 90 grados, como se muestra. Empezá rotando el antebrazo de modo que la palma de la mano quede hacia arriba y después rotá el antebrazo en sentido contrario, de modo que la palma quede hacia abajo.', 83355),
  ('ESTIRAMIENTO DE EXTENSIÓN DE CODO', NULL, true, 'pasivo', 'Codo y mano', NULL, 'Apoyá el codo en el borde de una mesa y usá la otra mano para empujarlo hacia una posición más estirada.', 67),
  ('ESTIRAMIENTO DE EXTENSIÓN DE CODO - DECÚBITO DORSAL', NULL, true, 'pasivo', 'Codo y mano', NULL, 'Acostado boca arriba, apoyá el codo sobre una toalla chica enrollada. Después, dejá que la gravedad ayude a estirar el codo hacia una posición más extendida.', 11219),
  ('ESTIRAMIENTO DE FLEXIÓN DE CODO', NULL, true, 'pasivo', 'Codo y mano', NULL, 'Apoyá el codo sobre una mesa y usá la otra mano para llevarlo hacia una posición más flexionada.', 68),
  ('PROM DE CODO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'pasivo', 'Codo y mano', NULL, 'La persona tiene que estar totalmente relajada mientras quien la asiste hace todo el trabajo (rango de movimiento pasivo) para mover el codo. Sostené la muñeca de la persona y después flexioná y estirá el codo. Repetí.', 135809),
  ('AUTO PROM DE CODO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'activo', 'Codo y mano', NULL, 'Relajá por completo el brazo que trabajás (rango de movimiento pasivo) mientras te agarrás la muñeca con el otro brazo. Flexioná y estirá el codo usando el brazo sano. Repetí.', 75097),
  ('PROM DE DEDOS - FLEXIÓN Y EXTENSIÓN', NULL, true, 'pasivo', 'Codo y mano', NULL, 'La persona tiene que estar totalmente relajada mientras quien la asiste hace todo el trabajo (rango de movimiento pasivo) para mover la mano y los dedos. Agarrá los dedos de la persona y cerralos en puño, y después estiralos. Repetí.', 27174),
  ('ISOMÉTRICO DE ADUCCIÓN DE DEDOS', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Colocá el nudillo entre los dedos y presioná con firmeza.', 70),
  ('ISOMÉTRICO DE EXTENSIÓN DE DEDOS', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Presioná los dedos afectados hacia arriba contra los dedos sanos.', 49),
  ('ISOMÉTRICO DE FLEXIÓN DE DEDOS', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Presioná las puntas de los dedos afectados contra las puntas de los dedos sanos.', 50),
  ('PROM DE DEDOS - COMPUESTO', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', NULL, 'La mano que trabajás tiene que estar totalmente relajada mientras la otra mano hace todo el trabajo (rango de movimiento pasivo asistido por vos). Usá la mano sana para sostener el dedo afectado. Con la mano sana, flexioná el dedo afectado en cada nudillo, como se muestra. Después estirá el dedo y repetí.', 75108),
  ('PROM DE DEDOS - FLEXIÓN Y EXTENSIÓN', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', NULL, 'La mano que trabajás tiene que estar totalmente relajada mientras la otra mano hace todo el trabajo (rango de movimiento pasivo asistido por vos). Usá la mano sana para sostener la punta del dedo afectado. Con la mano sana, flexioná la punta del dedo afectado y el nudillo del medio, como se muestra. Después estirá el dedo. Repetí.', 75107),
  ('FLEXBAR - FLEXIÓN Y EXTENSIÓN', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo un Flexbar en posición horizontal con ambas manos, con una muñeca flexionada y la otra extendida. Después, torcé la barra en un movimiento alternado para trabajar la flexión y la extensión de ambas muñecas.', 51463),
  ('FLEXBAR - SUPINACIÓN Y PRONACIÓN - ABDUCCIÓN DE HOMBRO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo el Flexbar por la punta de abajo y movelo de lado a lado para que oscile en un movimiento de supinación y pronación, como se muestra. Mientras seguís con el movimiento de supinación y pronación, empezá a elevar el hombro por encima de la cabeza en abducción o plano escapular. Después bajá el hombro y seguí subiéndolo y bajándolo mientras continuás haciendo oscilar el Flexbar de lado a lado durante un tiempo determinado.', 51462),
  ('FLEXBAR - TWIST DE TYLER - EXTENSIÓN EXCÉNTRICA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo la parte de abajo del Flexbar en posición vertical con el lado sano y después agarralo por arriba con el lado afectado. Ubicá las muñecas de modo que la de arriba quede en flexión y la de abajo en extensión. Después, bajá los brazos y girá el Flexbar hasta ponerlo horizontal, alineando las muñecas de modo que los nudillos apunten hacia adelante. Esto genera una tensión de torsión en el Flexbar. Luego, dejá que la muñeca afectada se relaje lentamente y se extienda, destorciendo la barra de a poco para lograr una contracción excéntrica de los extensores de muñeca.', 51456),
  ('FLEXBAR - TWIST DE TYLER - FLEXIÓN EXCÉNTRICA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo la parte de abajo del Flexbar en posición vertical con el lado sano y después agarralo por arriba con el lado afectado. Ubicá las muñecas de modo que la de arriba quede en extensión y la de abajo en flexión. Después, bajá los brazos y girá el Flexbar hasta ponerlo horizontal, alineando las muñecas de modo que los nudillos apunten hacia adelante. Esto genera una tensión de torsión en la barra. Luego, dejá que la muñeca afectada se relaje lentamente y se extienda, destorciendo la barra de a poco para lograr una contracción excéntrica de los flexores de muñeca.', 51454),
  ('FLEXBAR - DESVIACIÓN CUBITAL Y RADIAL - ABDUCCIÓN DE HOMBRO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo el Flexbar por la punta de abajo y movelo hacia adelante y atrás para que oscile en un movimiento de desviación cubital y radial, como se muestra. Mientras seguís con el movimiento de desviación radial y cubital, empezá a elevar el hombro por encima de la cabeza en abducción o plano escapular. Después bajá el hombro y seguí subiéndolo y bajándolo mientras continuás haciendo oscilar el Flexbar hacia adelante y atrás durante un tiempo determinado.', 51461),
  ('FLEXBAR - DESVIACIÓN CUBITAL Y RADIAL - FLEXIÓN DE HOMBRO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo el Flexbar por la punta de abajo y movelo hacia adelante y atrás para que oscile en un movimiento de desviación cubital y radial, como se muestra. Mientras seguís con el movimiento de desviación radial y cubital, empezá a elevar el hombro en flexión. Después bajá el hombro y seguí subiéndolo y bajándolo mientras continuás haciendo oscilar el Flexbar hacia adelante y atrás durante un tiempo determinado.', 51459),
  ('FLEXBAR - DESVIACIÓN CUBITAL Y RADIAL - FLEXIÓN DE HOMBRO II', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo el Flexbar por la punta de abajo y movelo hacia adelante y atrás para que oscile en un movimiento de desviación cubital y radial, como se muestra. Mientras seguís con el movimiento de desviación radial y cubital, empezá a elevar el hombro en flexión. Dejá que el codo también se estire. Después bajá el hombro, flexioná el codo y seguí subiendo y bajando el hombro mientras continuás haciendo oscilar el Flexbar hacia adelante y atrás durante un tiempo determinado.', 51460),
  ('FLEXBAR - SUPINACIÓN BILATERAL', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo el Flexbar en posición horizontal por delante tuyo, con ambas manos hacia abajo. Agarralo con firmeza y después torcé el Flexbar de modo que las palmas queden enfrentadas. Volvé a la posición inicial y repetí.', 51444),
  ('FLEXBAR - PRONACIÓN SOBRE LA MESA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá agarrando una punta del Flexbar con una mano, con la palma hacia arriba. La otra punta del Flexbar tiene que estar apoyada sobre una mesa, apuntando hacia adentro. Agarralo con firmeza y después torcé el Flexbar de modo que la palma quede hacia adentro. Volvé a la posición inicial y repetí.', 51450),
  ('FLEXBAR - DESVIACIÓN RADIAL SOBRE LA MESA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá agarrando una punta del Flexbar con una mano, con la palma hacia arriba. La otra punta del Flexbar tiene que estar apoyada sobre una mesa, apuntando hacia vos. Agarralo con firmeza y después torcé el Flexbar hacia vos de modo que la parte de arriba del puño quede hacia arriba. Volvé a la posición inicial y repetí.', 51452),
  ('FLEXBAR - SUPINACIÓN SOBRE LA MESA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá agarrando una punta del Flexbar con una mano, con la palma hacia arriba. La otra punta del Flexbar tiene que estar apoyada sobre una mesa, apuntando hacia afuera. Agarralo con firmeza y después torcé el Flexbar de modo que la palma quede hacia arriba. Volvé a la posición inicial y repetí.', 51451),
  ('FLEXBAR - DESVIACIÓN CUBITAL SOBRE LA MESA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá agarrando una punta del Flexbar con una mano, con la palma hacia el costado. La otra punta del Flexbar tiene que estar apoyada sobre una mesa, apuntando hacia adelante. Agarralo con firmeza y después torcé el Flexbar hacia adelante de modo que la parte de arriba del puño quede hacia adelante y arriba. Volvé a la posición inicial y repetí.', 51453),
  ('FLEXBAR - EXTENSIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo un Flexbar en posición horizontal con ambas manos, con la muñeca afectada en flexión. Después, usá la muñeca afectada y extendela para torcer la barra y generar tensión. Luego, de forma controlada, relajá y flexioná lentamente la muñeca para ir destorciendo la barra de a poco. Repetí.', 51457),
  ('FLEXBAR - FLEXIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo un Flexbar en posición horizontal con ambas manos, con la muñeca afectada en extensión. Después, usá la muñeca afectada y flexionala para torcer la barra y generar tensión. Luego, de forma controlada, relajá y extendé lentamente la muñeca para ir destorciendo la barra de a poco. Repetí.', 51458),
  ('PROM DE ANTEBRAZO - SUPINACIÓN Y PRONACIÓN', NULL, true, 'pasivo', 'Codo y mano', NULL, 'La persona tiene que estar totalmente relajada mientras quien la asiste hace todo el trabajo (rango de movimiento pasivo) para mover el antebrazo. Sostené la muñeca de la persona y rotá el antebrazo, como se muestra. Repetí.', 27172),
  ('AUTO PROM DE ANTEBRAZO - PRONACIÓN Y SUPINACIÓN', NULL, true, 'activo_asistido', 'Codo y mano', NULL, 'El brazo y la mano que trabajás tienen que estar totalmente relajados mientras el otro brazo y mano hacen todo el trabajo (rango de movimiento pasivo asistido por vos). Con la mano sana, agarrá la muñeca del brazo afectado y rotá el antebrazo de modo que la palma quede hacia arriba. Después, girá la muñeca en sentido contrario de modo que la palma rote hacia abajo. Repetí alternando las direcciones.', 75102),
  ('PESO LIBRE - DESVIACIÓN RADIAL SOBRE LA MESA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Sostené un peso libre o mancuerna chica, apoyá el antebrazo sobre una mesa y llevá la muñeca hacia arriba y abajo con la palma mirando hacia el costado, como se muestra.', 34148),
  ('PESO LIBRE - SUPINACIÓN Y PRONACIÓN', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Apoyá el antebrazo sobre la rodilla o una mesa. Después, sosteniendo la punta de un peso libre o mancuerna chica, bajá lentamente la pesa hacia afuera y después rotá el antebrazo hacia adentro del cuerpo, como se muestra.', 22531),
  ('MARTILLO - PRONACIÓN Y SUPINACIÓN', NULL, true, 'activo', 'Codo y mano', NULL, 'Bajá lentamente un martillo hacia adentro y después hacia afuera del cuerpo, como se muestra.', 4675),
  ('BOMBEO DE MANO', NULL, true, 'activo', 'Codo y mano', NULL, 'Sostené la mano en alto, como se muestra. Abrí y cerrá la mano en puño y repetí. Si no podés cerrar el puño completo, hacé un puño parcial. Esto puede ayudar a reducir la hinchazón y la rigidez.', 8423),
  ('ISOMÉTRICO DE PRONACIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Apoyá el antebrazo afectado sobre una mesa (con la palma hacia el costado) y colocá la palma de la mano sana sobre la muñeca y la zona del pulgar del brazo afectado. Intentá rotar el antebrazo afectado para llevar la palma hacia abajo, pero resistí el movimiento con la mano sana. Mantené, relajá y repetí.', 88265),
  ('ISOMÉTRICO DE SUPINACIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Apoyá el antebrazo afectado sobre una mesa (con la palma hacia el costado) y después usá la mano sana para agarrar la muñeca de la mano afectada. Intentá rotar el antebrazo afectado para llevar la palma hacia arriba, pero resistí el movimiento con la mano sana. Mantené, relajá y repetí.', 88267),
  ('BALÓN MEDICINAL - TRÍCEPS', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Empezá sosteniendo un balón medicinal por encima de la cabeza. Después, flexioná los codos mientras bajás lentamente el balón hacia atrás de la cabeza. Volvé a la posición inicial.', 6248),
  ('MASILLA - EXTENSIÓN CON ARO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Armá una tira tubular chica de masilla. Formá un aro alrededor de los dedos y después separalos para estirarla, como se muestra.', 8234),
  ('MASILLA - PRESA TRIDIGITAL', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Amasá un poco de masilla hasta formar una pelota y después aplastala. Después, apretala con firmeza con los primeros 3 dedos, como se muestra. Repetí.', 95852),
  ('MASILLA - ABDUCCIÓN CON ARO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Armá varias tiras tubulares chicas de masilla. Formá un aro alrededor de 2 dedos y después separalos para estirarla, como se muestra.', 8231),
  ('MASILLA - ABDUCCIÓN CON EXTENSIÓN SOBRE LA MESA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Amasá un poco de masilla y después presionala y aplastala sobre una mesa. Después, extendé la masilla hacia los costados con los dedos, como se muestra. Repetí con distintas partes de la masilla.', 8232),
  ('MASILLA - ADUCCIÓN', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Armá bolitas chicas de masilla. De a una por vez, colocá una bolita entre 2 dedos y apretala.', 8233),
  ('MASILLA - GARRA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Colocá la masilla en la mano y después apretala mientras llevás la mano a la posición de garra, como se muestra. Repetí.', 95854),
  ('MASILLA - EXTENSIÓN SOBRE LA MESA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Amasá un poco de masilla hasta formar una pelota y después presionala y aplastala sobre una mesa. Después, extendé la masilla con las puntas de los dedos, como se muestra.', 8236),
  ('MASILLA - PRESA DE LLAVE', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Sostené la masilla en la parte de arriba de la mano. Apretá la masilla entre el pulgar y el costado del 2do dedo, como se muestra.', 8238),
  ('MASILLA - LUMBRICALES', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Sostené la masilla con todos los dedos estirados, como se muestra, y después apretá. Mantené los dedos estirados todo el tiempo.', 8239),
  ('MASILLA - PINZA CON PULPEJO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Amasá un poco de masilla para armar una tira tubular chica. Después, pellizcá la masilla con el pulpejo de los dedos y repetí a lo largo de toda la tira.', 8240),
  ('MASILLA - PELLIZCAR Y TIRAR', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Sostené la masilla con una mano y después pellizcá y tirá de la masilla con la mano que trabajás.', 8241),
  ('MASILLA - AMASADO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Amasá la masilla hasta formar una pelota. Después, amasala hasta formar un tubo. Después volvé a hacer una pelota y de nuevo un tubo. Repetí.', 95857),
  ('MASILLA - FLEXIÓN DE PULGAR', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Presioná la punta del pulgar contra la masilla, como se muestra.', 8242),
  ('MASILLA - PINZA CON PUNTA DE DEDOS', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Amasá un poco de masilla para armar una tira tubular chica. Después, pellizcá la masilla con la punta de los dedos y repetí a lo largo de toda la tira.', 95851),
  ('EXTENSIÓN CON BANDA ELÁSTICA (GOMITA)', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Abrí una gomita elástica colocada alrededor de los dedos.', 100),
  ('TORNILLO Y TUERCA', NULL, true, 'activo', 'Codo y mano', NULL, 'Sostené un tornillo con una mano y enroscá una tuerca en el tornillo con la mano que trabajás.', 4680),
  ('CURLS DE BÍCEPS SENTADO - BILATERAL', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Sentado en una silla y sosteniendo un peso libre o mancuerna sobre cada muslo, subí ambos lados flexionando los codos. Bajá y repetí.', 22417),
  ('AUTOMASAJE CON PELOTA - FRICCIÓN TRANSVERSAL DEL TENDÓN DEL BÍCEPS', NULL, true, 'activo', 'Codo y mano', NULL, 'Sentate en una silla y apoyá el brazo sobre una mesa con la palma hacia arriba. Colocá una pelota de lacrosse o de tenis sobre el brazo, en el pliegue interno del codo. Rodá la pelota de lado a lado para un masaje suave.', 99590),
  ('AUTOMASAJE CON PELOTA - MANO', NULL, true, 'activo', 'Codo y mano', NULL, 'Sentate en una silla y apoyá la mano encima de una pelota de lacrosse o de tenis. Rodá la pelota por la palma de la mano para un masaje suave.', 99594),
  ('AUTOMASAJE CON PELOTA - EXTENSORES DE MUÑECA', NULL, true, 'activo', 'Codo y mano', NULL, 'Sentate en una silla y apoyá el brazo sobre una mesa con la palma hacia arriba. Colocá una pelota de lacrosse o de tenis debajo del antebrazo. Inclinate hacia adelante y atrás para que la pelota ruede a lo largo del antebrazo, para un masaje suave. No pases sobre zonas óseas.', 99593),
  ('AUTOMASAJE CON PELOTA - FLEXORES DE MUÑECA', NULL, true, 'activo', 'Codo y mano', NULL, 'Sentate en una silla y apoyá el brazo sobre una mesa con la palma hacia abajo. Colocá una pelota de lacrosse o de tenis debajo del antebrazo. Inclinate hacia adelante y atrás para que la pelota ruede a lo largo del antebrazo, para un masaje suave. No pases sobre zonas óseas.', 99592),
  ('AUTOMOVILIZACIÓN - DISTRACCIÓN DE CODO', NULL, true, 'activo_asistido', 'Codo y mano', NULL, 'Colocá una toalla chica enrollada en la articulación del codo del brazo afectado y después usá el brazo sano para flexionarlo suavemente sobre la toalla.', 229),
  ('CABESTRILLO - APRETAR PELOTA', NULL, true, 'activo', 'Codo y mano', NULL, 'Agarrá una pelota chica o una toalla chica enrollada y apretala con la mano. Repetí.', 8522),
  ('EJERCITADOR DE AGARRE A RESORTE', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Sostené un ejercitador de agarre a resorte. Apretá, soltá y repetí.', 76591),
  ('EXTENSIÓN DE TRÍCEPS EN DECÚBITO DORSAL CON PESO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Acostado boca arriba, sostené un peso libre o mancuerna derecho hacia arriba. Empezá flexionando el codo mientras bajás la mano y la pesa. Después, extendé el codo mientras volvés a subir la pesa a la posición inicial. Repetí.', 12633),
  ('ISOMÉTRICO DE EXTENSIÓN DE PULGAR', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Presioná el pulgar hacia arriba contra los dedos de la mano sana.', 58),
  ('ISOMÉTRICO DE FLEXIÓN DE PULGAR 2', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Presioná el pulgar hacia adentro contra los dedos de la mano sana.', 60),
  ('PROM DE PULGAR - ABDUCCIÓN Y ADUCCIÓN', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', NULL, 'El brazo y la mano que trabajás tienen que estar totalmente relajados mientras el otro brazo y mano hacen todo el trabajo (rango de movimiento pasivo asistido por vos). Usá la mano sana para sostener el pulgar afectado. Con la mano sana, alejá el pulgar afectado de la palma y después llevalo de vuelta hacia la palma, como se muestra. Repetí.', 75105),
  ('PROM DE PULGAR - CIRCUNDUCCIÓN', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', NULL, 'El brazo y la mano que trabajás tienen que estar totalmente relajados mientras el otro brazo y mano hacen todo el trabajo (rango de movimiento pasivo asistido por vos). Usá la mano sana para sostener el pulgar afectado. Con la mano sana, movés el pulgar afectado en círculos, como se muestra. Hacé varias vueltas y después invertí la dirección del círculo y repetí alternando el movimiento.', 75104),
  ('PROM DE PULGAR - FLEXIÓN Y EXTENSIÓN', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', NULL, 'El brazo y la mano que trabajás tienen que estar totalmente relajados mientras el otro brazo y mano hacen todo el trabajo (rango de movimiento pasivo asistido por vos). Usá la mano sana para sostener el pulgar afectado. Con la mano sana, flexioná el pulgar afectado desde el nudillo de modo que se enrosque hacia la palma. Después, estirá el pulgar y repetí.', 75106),
  ('TOALLA - PINZA DE 3 DEDOS - PRESA TRIDIGITAL', NULL, true, 'activo', 'Codo y mano', NULL, 'Con el pulgar, el índice y el dedo mayor, pellizcá y sostené una toalla chica doblada.', 11223),
  ('TOALLA - PINZA EN PRESA DE LLAVE', NULL, true, 'activo', 'Codo y mano', NULL, 'Con el pulgar y el costado del índice, pellizcá y sostené una toalla chica doblada.', 11224),
  ('TOALLA - PINZA', NULL, true, 'activo', 'Codo y mano', NULL, 'Con el pulgar y el índice, pellizcá y sostené una toalla chica doblada.', 11222),
  ('ESCURRIR TOALLA - FLEXIÓN Y EXTENSIÓN DE MUÑECA', NULL, true, 'activo', 'Codo y mano', NULL, 'Agarrá las puntas de una toalla de mano y empezá a retorcerla en una dirección; después invertí la dirección y retorcela para el otro lado. Repetí.', 87665),
  ('TRX EN SUSPENSIÓN - CURL DE BÍCEPS', NULL, true, 'activo', 'Codo y mano', NULL, 'Parate de frente al anclaje del TRX con los codos flexionados. Después, inclinate hacia atrás dejando que los codos se estiren. Volvé a la posición original haciendo curls de bíceps, como se muestra. Las palmas tienen que mirar hacia arriba mientras flexionás los codos.', 31412),
  ('EXTENSIÓN DE TRÍCEPS CON CODO ERGUIDO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Extendé el codo, como se muestra, mientras sostenés un peso libre o mancuerna. Mantené el brazo apuntando hacia arriba y flexioná y estirá solamente desde el codo.', 8078),
  ('BROCHE EN EL ESPACIO INTERDIGITAL', NULL, true, 'activo', 'Codo y mano', NULL, 'Colocá un broche o pinza en el espacio interdigital entre el 1er y el 2do dedo, como se muestra.', 87612),
  ('SILLA DE RUEDAS - FONDOS', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Con los antebrazos o las manos sobre los apoyabrazos, empujate hacia arriba de modo que la cola se despegue de la silla. Después, bajá de forma controlada hasta la posición sentada normal.', 105305),
  ('SILLA DE RUEDAS - FONDOS - UNA PIERNA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Con los antebrazos o las manos sobre los apoyabrazos, empujate hacia arriba de modo que la cola se despegue de la silla. Mantené un pie en el piso para ayudarte a subir y bajar el cuerpo. Después, bajá de forma controlada hasta la posición sentada normal.', 105309),
  ('AROM DE EXTENSIÓN DE MUÑECA - MESA', NULL, true, 'activo', 'Codo y mano', NULL, 'Apoyá el antebrazo sobre una mesa y llevá la muñeca hacia arriba y abajo con la palma hacia abajo, como se muestra.', 34154),
  ('CURLS DE EXTENSIÓN DE MUÑECA - PESO LIBRE - MUSLO', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Sosteniendo un peso libre o mancuerna chica, apoyá el antebrazo sobre el muslo y llevá la muñeca hacia arriba y abajo con la palma hacia abajo, como se muestra.', 40),
  ('ISOMÉTRICO DE EXTENSIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Llevá la muñeca hacia atrás y hacé resistencia contra la otra mano.', 81),
  ('ESTIRAMIENTO DE EXTENSIÓN DE MUÑECA - MESA', NULL, true, 'activo', 'Codo y mano', NULL, 'Apoyá ambas manos sobre una mesa, como se muestra, e inclinate suavemente hacia adelante hasta sentir el estiramiento.', 42),
  ('FLEXIÓN DE MUÑECA - AROM - MUSLO', NULL, true, 'activo', 'Codo y mano', NULL, 'Apoyá el brazo sobre el muslo y llevá la muñeca hacia arriba y abajo con la palma hacia arriba, como se muestra. Volvé a la posición original y repetí.', 4676),
  ('ISOMÉTRICO DE FLEXIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Llevá la muñeca hacia adelante y hacé resistencia contra la otra mano.', 82),
  ('PROM DE MUÑECA - FLEXIÓN Y EXTENSIÓN', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', NULL, 'El brazo y la mano que trabajás tienen que estar totalmente relajados mientras el otro brazo y mano hacen todo el trabajo (rango de movimiento pasivo asistido por vos). Usá la mano sana para agarrar la mano afectada. Llevá la muñeca hacia arriba y abajo, como se muestra. Repetí.', 75100),
  ('PROM DE MUÑECA - DESVIACIÓN RADIAL Y CUBITAL', NULL, true, 'pasivo', 'Codo y mano', NULL, 'El brazo y la mano que trabajás tienen que estar totalmente relajados mientras el otro brazo y mano hacen todo el trabajo (rango de movimiento pasivo). Usá la mano sana para agarrar la mano afectada, como se muestra. Con la mano sana, movés la mano afectada de lado a lado. Repetí.', 75101),
  ('ESTIRAMIENTO DE PRONACIÓN DE MUÑECA', NULL, true, 'activo', 'Codo y mano', NULL, 'Apoyá el brazo sobre una mesa, después agarrate la muñeca, como se muestra, y girá suavemente la muñeca afectada hacia la posición de palma abajo. Mantené el codo estirado y apoyado sobre la mesa durante este estiramiento.', 73),
  ('DESVIACIÓN RADIAL DE MUÑECA', NULL, true, 'activo', 'Codo y mano', NULL, 'Llevá la muñeca hacia el lado del pulgar y después volvé.', 83),
  ('ISOMÉTRICO DE DESVIACIÓN RADIAL DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Inclina la muñeca hacia arriba y hacé resistencia contra la otra mano.', 84),
  ('SUPINACIÓN DE MUÑECA - DE NEUTRO A SUPINADO', NULL, true, 'activo', 'Codo y mano', NULL, 'Empezá con la palma de la mano apuntando hacia el costado y después rotá la mano y el antebrazo de modo que la palma quede hacia arriba. Volvé a la posición inicial y repetí. Mantené el codo flexionado y pegado al costado del cuerpo.', 76),
  ('ESTIRAMIENTO DE SUPINACIÓN DE MUÑECA', NULL, true, 'activo', 'Codo y mano', NULL, 'Apoyá el brazo sobre una mesa, después agarrate la muñeca, como se muestra, y girá suavemente la muñeca afectada hacia la posición de palma arriba. Mantené el codo estirado y apoyado sobre la mesa durante este estiramiento.', 77),
  ('DESVIACIÓN CUBITAL DE MUÑECA', NULL, true, 'activo', 'Codo y mano', NULL, 'Llevá la muñeca hacia el lado del meñique y después volvé.', 85),
  ('ISOMÉTRICO DE DESVIACIÓN CUBITAL DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', NULL, 'Inclina la muñeca hacia abajo y hacé resistencia contra la otra mano.', 86),
  ('ABDUCCIÓN / ADUCCIÓN DEL 1ER DEDO - ROM', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', 'AAROM (asistido activo); PROM (pasivo); Estiramientos', 'Agarrá el pulgar y alejalo de la palma, como se muestra. Volvé a la posición inicial y repetí.', 173469),
  ('FLEXIÓN DEL 1ER DEDO - ROM', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', 'AAROM (asistido activo); PROM (pasivo); Estiramientos', 'Empezá con la mano abierta y todos los dedos estirados en todos los nudillos. Después, agarrá la punta del pulgar (1er dedo) y flexionalo hacia abajo y cruzando la palma. Volvé a la posición inicial y repetí.', 174018),
  ('ABDUCCIÓN / ADUCCIÓN DEL 2DO DEDO - ROM', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', 'AAROM (asistido activo); PROM (pasivo); Estiramientos', 'Agarrá el índice (2do dedo) y alejalo del dedo mayor (separalos). Volvé a la posición inicial y repetí.', 173446),
  ('ABDUCCIÓN / ADUCCIÓN DEL 3ER DEDO - ROM', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', 'AAROM (asistido activo); PROM (pasivo); Estiramientos', 'Agarrá el dedo mayor (3er dedo) y movelo de lado a lado (separándolo).', 173464),
  ('ABDUCCIÓN / ADUCCIÓN DEL 4TO DEDO - ROM', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', 'AAROM (asistido activo); PROM (pasivo); Estiramientos', 'Agarrá el dedo anular (4to dedo) y movelo de lado a lado (separándolo).', 173468),
  ('FLEXIÓN DE MUÑECA - ROM', NULL, true, 'pasivo; activo_asistido', 'Codo y mano', 'AAROM (asistido activo); PROM (pasivo); Estiramientos', 'Agarrate la mano y llevala hacia adelante en flexión, como se muestra. Volvé a la posición neutra y repetí.', 174241),
  ('AROM DE IF DEL 1ER DEDO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la mano sobre una mesa y bloqueá el pulgar (1er dedo) justo por debajo del último nudillo (IF), como se muestra, y después flexioná activamente esa articulación. Relajá y repetí.', 178342),
  ('AROM DE MCF DEL 1ER DEDO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Bloqueá el pulgar (1er dedo) justo por debajo del primer nudillo (MCF), como se muestra, y después flexioná activamente esa articulación. Relajá y repetí.', 178341),
  ('ARRUGAR TOALLA CON DEDOS 2-5', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Colocá una toalla chica sobre una mesa firme. Estirá bien la toalla y después apoyá la mano sobre una de sus puntas. Después, flexioná los dedos 2 a 5 (del índice al meñique) mientras arrastrás la toalla hacia la mano.', 53551),
  ('AROM DE IFD DEL 2DO DEDO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Agarrá el índice (2do dedo) sujetándolo por debajo del último nudillo y flexioná y estirá activamente el dedo en la última articulación. Relajá y repetí.', 178719),
  ('AROM DE IFD DEL 2DO DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el índice (2do dedo) justo por debajo del último nudillo (IFD), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 177962),
  ('AROM DE MCF DEL 2DO DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una mesa. Bloqueá el índice (2do dedo) justo por debajo del primer nudillo (MCF), como se muestra, y después flexioná activamente esa articulación. Relajá y repetí.', 178340),
  ('AROM DE IFP DEL 2DO DEDO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Agarrá el índice (2do dedo) sujetándolo por debajo del nudillo del medio y flexioná y estirá activamente el dedo en la última articulación.', 179051),
  ('AROM DE IFP DEL 2DO DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el índice (2do dedo) justo por debajo del nudillo del medio (IFP), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 177967),
  ('FLEXIÓN DEL 2DO DEDO CON BLOQUEO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la mano sobre una mesa con la palma hacia arriba. Flexioná el dedo que trabajás mientras bloqueás y sostenés los otros dedos hacia abajo, como se muestra.', 11198),
  ('AROM DE IFD DEL 3ER DEDO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Agarrá el dedo mayor (3er dedo) sujetándolo por debajo del último nudillo y flexioná y estirá activamente el dedo en la última articulación.', 178718),
  ('AROM DE IFD DEL 3ER DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el dedo mayor (3er dedo) justo por debajo del último nudillo (IFD), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 177961),
  ('AROM DE IFP DEL 3ER DEDO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Agarrá el dedo mayor (3er dedo) sujetándolo por debajo del nudillo del medio y flexioná y estirá activamente el dedo en la última articulación.', 179050),
  ('AROM DE IFP DEL 3ER DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el dedo mayor (3er dedo) justo por debajo del nudillo del medio (IFP), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 177966),
  ('FLEXIÓN DEL 3ER DEDO CON BLOQUEO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la mano sobre una mesa con la palma hacia arriba. Flexioná el dedo que trabajás mientras bloqueás y sostenés los otros dedos hacia abajo, como se muestra.', 11199),
  ('AROM DE MCF DEL 3ER DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el dedo mayor (3er dedo) justo por debajo del primer nudillo (MCF), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 178339),
  ('AROM DE IFD DEL 4TO DEDO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Agarrá el anular (4to dedo) sujetándolo por debajo del último nudillo y flexioná y estirá activamente el dedo en la última articulación.', 178717),
  ('AROM DE IFD DEL 4TO DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el anular (4to dedo) justo por debajo del último nudillo (IFD), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 177811),
  ('AROM DE IFP DEL 4TO DEDO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Agarrá el anular (4to dedo) sujetándolo por debajo del nudillo del medio y flexioná y estirá activamente el dedo en la última articulación.', 179049),
  ('AROM DE IFP DEL 4TO DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el anular (4to dedo) justo por debajo del nudillo del medio (IFP), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 177964),
  ('FLEXIÓN DEL 4TO DEDO CON BLOQUEO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la mano sobre una mesa con la palma hacia arriba. Flexioná el dedo que trabajás mientras bloqueás y sostenés los otros dedos hacia abajo, como se muestra.', 11200),
  ('AROM DE MCF DEL 4TO DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el anular (4to dedo) justo por debajo del primer nudillo (MCF), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 178338),
  ('MANO EN 5 POSICIONES', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Hacelo en este orden: 1. Palma abierta: empezá con la mano en posición de palma abierta, con los dedos estirados en todos los nudillos. 2. Mano lumbrical: formá una L con los dedos, como se muestra, de modo que los dedos 2 a 5 queden flexionados en los nudillos grandes más cercanos a la palma. 3. Puño plano: hacé un puño pero con los últimos nudillos (articulaciones chicas) estirados, como se muestra. 4. Mano en garra: flexioná los dedos en las articulaciones distales manteniendo estirada la articulación más cercana (nudillo grande), como se muestra. 5. Puño: hacé un puño cerrado, como se muestra, de modo que todas las articulaciones queden flexionadas.', 53521),
  ('AROM DE IFD DEL 5TO DEDO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Agarrá el meñique (5to dedo) sujetándolo por debajo del último nudillo y flexioná y estirá activamente el dedo en la última articulación.', 178716),
  ('AROM DE IFD DEL 5TO DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el meñique (5to dedo) justo por debajo del último nudillo (IFD), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 177810),
  ('AROM DE IFP DEL 5TO DEDO - FLEXIÓN Y EXTENSIÓN', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Agarrá el meñique (5to dedo) sujetándolo por debajo del nudillo del medio y flexioná y estirá activamente el dedo en la última articulación.', 179048),
  ('AROM DE IFP DEL 5TO DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el meñique (5to dedo) justo por debajo del nudillo del medio (IFP), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 177963),
  ('FLEXIÓN DEL 5TO DEDO CON BLOQUEO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la mano sobre una mesa con la palma hacia arriba. Flexioná el dedo que trabajás mientras bloqueás y sostenés los otros dedos hacia abajo, como se muestra.', 11201),
  ('AROM DE MCF DEL 5TO DEDO - FLEXIÓN Y EXTENSIÓN - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá apoyando la mano con la palma hacia arriba sobre una superficie plana. Bloqueá el meñique (5to dedo) justo por debajo del primer nudillo (MCF), como se muestra, y después flexioná activamente el dedo. Relajá y repetí.', 178337),
  ('AROM DE FLEXIÓN DE IFD', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la mano sobre una mesa con la palma hacia arriba. Bloqueá el dedo afectado con la otra mano por debajo de la línea de la última articulación y flexioná activamente el dedo.', 59993),
  ('AROM DE FLEXIÓN DE MCF', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la mano sobre una mesa con la palma hacia arriba. Flexioná activamente el dedo en la línea del nudillo grande, como se muestra. Volvé a la posición original y repetí.', 59998),
  ('AROM DE FLEXIÓN DE IFP', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la mano sobre una mesa con la palma hacia arriba. Bloqueá el dedo afectado con la otra mano por debajo de la línea de la articulación del medio y flexioná activamente el dedo.', 59999),
  ('CURLS DE BÍCEPS - ALTERNADOS', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Flexioná el codo y llevá el antebrazo hacia arriba. Mientras lo bajás, empezá a flexionar el codo del otro lado hacia arriba.', 7005),
  ('CURLS DE BÍCEPS - BRAQUIAL', NULL, true, 'activo; fortalecimiento', 'Codo y mano', 'AROM (activo)', 'Con el brazo al costado del cuerpo, flexioná el codo para subir el peso libre o mancuerna. Bajá y repetí. Mantené la palma hacia abajo todo el tiempo.', 380),
  ('FLEXIÓN Y EXTENSIÓN BILATERAL DE CODO - 90', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Elevá los brazos hacia adelante hasta la altura de los hombros, como se muestra. Después, flexioná y estirá solamente los codos. Repetí.', 163679),
  ('MOVIMIENTO DE TIRO DE DARDO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá el codo sobre una mesa con el codo flexionado. Juntá el pulgar y el índice como si sostuvieras un dardo. Después movés la muñeca hacia adelante y soltá los dedos como si tiraras un dardo. Repetí.', 87615),
  ('BANDA ELÁSTICA - CURLS DE BÍCEPS - BRAQUIAL', NULL, true, 'activo; fortalecimiento', 'Codo y mano', 'AROM (activo)', 'Hacé un nudo chico en la punta de una banda elástica y pisala. Hacé un aro en la otra punta y sostenelo con la mano. Manteniendo el codo pegado al costado del cuerpo, flexioná el codo mientras subís el antebrazo contra la resistencia de la banda, como se muestra. Bajá y repetí. Mantené la palma hacia abajo todo el tiempo.', 535),
  ('BANDA ELÁSTICA - CURLS DE BÍCEPS - SUPINADOR LARGO - CURL MARTILLO', NULL, true, 'activo; fortalecimiento', 'Codo y mano', 'AROM (activo)', 'Hacé un nudo chico en la punta de una banda elástica y pisala. Hacé un aro en la otra punta y sostenelo con la mano. Manteniendo el codo pegado al costado del cuerpo, flexioná el codo mientras subís el antebrazo contra la resistencia de la banda, como se muestra. Bajá y repetí. Mantené el pulgar apuntando hacia arriba todo el tiempo.', 534),
  ('FLEXIÓN Y EXTENSIÓN DE CODO - 90', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Elevá el brazo hacia adelante hasta la altura del hombro, como se muestra. Después, flexioná y estirá solamente el codo. Repetí.', 163678),
  ('FLEXIÓN Y EXTENSIÓN DE CODO - SIN GRAVEDAD', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Sentado y relajado, sostené el brazo en alto con la ayuda del otro brazo. Después, flexioná y estirá el codo.', 36147),
  ('FLEXIÓN Y EXTENSIÓN DE CODO - DECÚBITO DORSAL', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Acostado boca arriba, apoyá el codo sobre una toalla chica enrollada. Después, flexioná el codo y luego bajá y repetí.', 11220),
  ('ABDUCCIÓN DE DEDOS A PUÑO CERRADO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Abrí y cerrá la mano en puño y repetí. Al abrir, tratá de abrir lo más que puedas separando los dedos al máximo. Trabajá dentro del rango que tengas disponible.', 34150),
  ('AROM DE DEDOS CON BLOQUEO - IFD', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá con la mano sobre una mesa, con la palma hacia arriba. Subí y bajá el dedo en la línea de la última articulación (articulación IFD), como se muestra, mientras bloqueás el movimiento del resto de la mano con la otra mano y los dedos.', 66574),
  ('AROM DE DEDOS CON BLOQUEO - IFD, IFP, MCF', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá con la mano sobre una mesa, con la palma hacia arriba. Subí y bajá el dedo en la primera línea de pliegue (articulación MCF), como se muestra. Después, subí y bajá el dedo en la línea de la articulación del medio (articulación IFP), como se muestra, mientras bloqueás el movimiento del resto de la mano con la otra mano y los dedos. Por último, subí y bajá el dedo en la línea de la última articulación (articulación IFD), como se muestra, mientras bloqueás el movimiento del resto de la mano con la otra mano y los dedos.', 66518),
  ('AROM DE DEDOS CON BLOQUEO - MCF', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá con la mano sobre una mesa, con la palma hacia arriba. Subí y bajá el dedo en la primera línea de pliegue (articulación MCF), como se muestra.', 66576),
  ('AROM DE DEDOS CON BLOQUEO - IFP', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá con la mano sobre una mesa, con la palma hacia arriba. Subí y bajá el dedo en la línea de la articulación del medio (articulación IFP), como se muestra, mientras bloqueás el movimiento del resto de la mano con la otra mano y los dedos.', 66575),
  ('FLEXIÓN DE IFD DE DEDOS', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Agarrá el dedo afectado sujetándolo por debajo del último nudillo y flexioná activamente el dedo en la última articulación.', 47),
  ('EXTENSIÓN DE DEDOS', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá con la mano sobre una mesa, con la palma hacia abajo. Subí y bajá el dedo con un movimiento controlado, como se muestra.', 83138),
  ('DESLIZAMIENTO DE TENDONES EXTENSORES DE LOS DEDOS', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá con el puño cerrado y después, lentamente y de forma controlada, levantá el primer dedo (índice), después el 2do (dedo mayor), después el 3ro, y seguí hasta que los cinco dedos queden completamente extendidos. Después bajá cada dedo uno por uno en orden inverso hasta volver a formar el puño cerrado.', 66513),
  ('FLEXIÓN DE IFP DE DEDOS', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Agarrá el dedo afectado sujetándolo por debajo del nudillo del medio y flexioná activamente el dedo, como se muestra.', 4709),
  ('SEPARACIÓN DE DEDOS - ABDUCCIÓN Y ADUCCIÓN', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la mano sobre una mesa. Empezá con los dedos juntos y después separalos. Volvé a juntarlos y repetí.', 88133),
  ('MANO - DESLIZAMIENTO DEL NERVIO MEDIANO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', '1. Empezá cerrando el puño. 2. Abrí la mano y estirá los dedos. 3. Extendé la muñeca hacia atrás. 4. Alejá el pulgar de la mano en perpendicular. 5. Rotá el antebrazo de modo que los dedos apunten hacia afuera. 6. Con la otra mano, tirá del pulgar hacia abajo. Volvé a la posición inicial y repetí.', 72315),
  ('DESLIZAMIENTOS TENDINOSOS DE LA MANO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Hacé la siguiente serie de movimientos con la mano. Empezá con la palma abierta (imagen del centro) y después flexioná los dedos hasta la mano en garra, como en la imagen de arriba a la izquierda. Después volvé a la palma abierta y pasá a la mano en L, como se muestra en la imagen de arriba a la derecha. Después volvé a la palma abierta y hacé un puño plano, como en la imagen de abajo a la izquierda. Después volvé a la palma abierta y hacé un puño completo con los pulpejos de los dedos contra la palma, como en la imagen de abajo a la derecha. Por último, volvé a la palma abierta y repetí la serie.', 72321),
  ('AROM DE MANO Y MUÑECA - ABECEDARIO CON PELOTA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Hacé rodar una pelota sobre una mesa siguiendo el trazo de las letras del abecedario.', 92521),
  ('DESLIZAMIENTOS LUMBRICALES SOBRE LA MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la palma de la mano plana sobre una mesa. Después, despegá los nudillos grandes (articulaciones MCF) de la mesa mientras deslizás las puntas de los dedos hacia la palma, como se muestra. Las articulaciones más chicas tienen que quedar estiradas todo el tiempo. Bajá mientras deslizás las puntas de los dedos hasta la posición inicial y apoyá la mano plana sobre la mesa. Repetí.', 130993),
  ('AROM DE FLEXIÓN Y EXTENSIÓN DE IFP E IFD - BLOQUEANDO LAS MCF', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Usá la mano sana para bloquear el movimiento de los nudillos grandes mientras flexionás y estirás los dedos, como se muestra. Repetí.', 93288),
  ('PRONACIÓN Y SUPINACIÓN CON APOYO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá el antebrazo y la mano sobre una mesa adelante tuyo, con el codo flexionado. Después, rotá el antebrazo de modo que la palma de la mano quede hacia arriba, y después girá el antebrazo en sentido contrario de modo que la palma mire hacia la mesa. Repetí.', 83153),
  ('TECHO A DOS AGUAS - AROM DE MCF', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Flexioná los dedos en los nudillos más grandes manteniendo el resto de los dedos estirados. Movés el pulgar en paralelo a los otros dedos. Mantené esta posición, relajá y después repetí.', 93289),
  ('CABESTRILLO - FLEXIÓN Y EXTENSIÓN DE CODO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Con cuidado, sacá el brazo del cabestrillo usando el brazo sano. Dejá que el codo afectado se estire y permití que la gravedad lo estire. Después, volvé a flexionar el codo a la posición original y repetí.', 8523),
  ('CABESTRILLO - BOMBEO DE MANO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Abrí y cerrá la mano en puño y repetí. Si no podés cerrar el puño completo, hacé un puño parcial.', 8526),
  ('CABESTRILLO - PRONACIÓN Y SUPINACIÓN', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Con el brazo en el cabestrillo, rotá el antebrazo de modo que la palma quede hacia arriba y después hacia abajo, como se muestra.', 8521),
  ('CABESTRILLO - FLEXIÓN Y EXTENSIÓN DE MUÑECA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Llevá la muñeca hacia arriba y abajo, como se muestra, con el brazo en el cabestrillo.', 8520),
  ('EXTENSIÓN DE TRÍCEPS EN DECÚBITO DORSAL', NULL, true, 'pasivo', 'Codo y mano', 'AROM (activo)', 'Acostado boca arriba, sostené la parte de atrás del brazo que trabajás con la otra mano, como se muestra. Empezá con el codo flexionado y después extendelo hasta que el brazo quede estirado. Bajá y repetí.', 141164),
  ('AROM DE ABDUCCIÓN DE PULGAR', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Estirá la mano de modo que todos los dedos queden alineados, como se muestra. Alejá el pulgar en perpendicular a la mano y mantené. Volvé a llevar el pulgar contra la mano. Repetí.', 72311),
  ('CIRCUNDUCCIÓN DE PULGAR', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Movés el pulgar en círculos, como se muestra. Hacé varias vueltas en sentido horario, después varias en sentido antihorario y repetí.', 90589),
  ('EXTENSIÓN Y FLEXIÓN DE PULGAR - AROM', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá la mano sobre una mesa con la palma hacia abajo, después movés activamente el 1er dedo (pulgar) hacia afuera, hacia el costado, después volvé y repetí.', 59995),
  ('FLEXIÓN DE PULGAR', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Sostené la mano por debajo del pulgar, como se muestra, y flexioná el pulgar por encima de los dedos.', 11197),
  ('FLEXIÓN Y EXTENSIÓN DE PULGAR', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Flexioná el pulgar cruzando la palma de la mano y después extendelo hacia el costado, como se muestra. Repetí.', 90590),
  ('CÍRCULOS DE MUÑECA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Movés la muñeca en círculos. Hacé varias vueltas en sentido horario y después en sentido antihorario. Si hace falta, empezá con círculos chicos para que moleste menos.', 103727),
  ('CURLS DE MUÑECA - PESO LIBRE - SOBRE EL MUSLO', NULL, true, 'activo; fortalecimiento', 'Codo y mano', 'AROM (activo)', 'Sosteniendo una mancuerna chica y apoyando el antebrazo sobre el muslo, flexioná y extendé la muñeca con la palma hacia arriba, como se muestra.', 38),
  ('CURLS DE MUÑECA - DESVIACIÓN RADIAL - PESO LIBRE - SOBRE EL MUSLO', NULL, true, 'activo; fortalecimiento', 'Codo y mano', 'AROM (activo)', 'Sosteniendo una mancuerna chica y apoyando el antebrazo sobre el muslo, flexioná y extendé la muñeca con la muñeca en posición neutra, como se muestra.', 39),
  ('FLEXIÓN DE MUÑECA AROM - MESA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá el antebrazo sobre una mesa y flexioná y extendé la muñeca con la palma hacia arriba, como se muestra.', 34152),
  ('FLEXIÓN Y EXTENSIÓN DE MUÑECA - AGARRE FUNCIONAL', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Flexioná y extendé la muñeca con los dedos relajados. Cuando la muñeca vuelve a extensión, los dedos deben flexionarse/cerrarse solos.', 72314),
  ('FLEXIÓN Y EXTENSIÓN DE MUÑECA - SIN GRAVEDAD - TOALLA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Colocá una toalla chica sobre una mesa y después apoyá la muñeca sobre la toalla de modo que la palma quede apuntando hacia el costado, como se muestra. Después, flexioná y extendé la muñeca mientras deslizás la toalla por la mesa.', 88269),
  ('FLEXIÓN Y EXTENSIÓN DE MUÑECA AROM - MESA - SIN GRAVEDAD', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá el antebrazo sobre una mesa y movés la muñeca de lado a lado con la palma mirando hacia el costado.', 34153),
  ('PRONACIÓN DE MUÑECA - DE NEUTRO A PRONADO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Empezá con la palma de la mano apuntando hacia el costado y después rotá la mano y el antebrazo de modo que la palma quede hacia abajo. Volvé a la posición inicial y repetí. Mantené el codo flexionado y pegado al costado del cuerpo.', 72),
  ('DESVIACIÓN RADIAL DE MUÑECA - AROM', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Apoyá el brazo sobre el muslo con el pulgar hacia arriba. Flexioná y extendé la muñeca hacia arriba y abajo, y repetí.', 4678),
  ('DESVIACIÓN RADIAL Y CUBITAL DE MUÑECA - SIN GRAVEDAD - TOALLA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Colocá una toalla chica sobre una mesa y después apoyá la palma de la mano sobre la toalla, como se muestra. Después, movés la muñeca de lado a lado mientras deslizás la toalla por la mesa.', 88270),
  ('SUPINACIÓN Y PRONACIÓN DE MUÑECA - COMPLETA', NULL, true, 'activo', 'Codo y mano', 'AROM (activo)', 'Rotá la mano y el antebrazo de modo que la palma quede hacia abajo y después rotala hasta que quede hacia arriba. Repetí. Mantené el codo flexionado y pegado al costado del cuerpo.', 88261),
  ('EXTENSIÓN DE PULGAR - GOMITA', NULL, true, 'activo; fortalecimiento', 'Codo y mano', 'AROM (activo); Banda elástica', 'Colocá una gomita elástica alrededor de la mano, incluyendo el pulgar. Apoyá la mano sobre una mesa con la palma hacia abajo, después movés activamente el pulgar hacia el costado, después volvé y repetí.', 59994),
  ('ARRUGADO DE TOALLA CON DEDOS 2-5 ALTERNADOS', NULL, true, 'activo', 'Codo y mano', 'AROM (activo); Varios', 'Colocá una toalla chica sobre una mesa firme. Estirá bien la toalla y después apoyá la mano sobre una punta. Después, flexioná los dedos 2 a 5 (del índice al meñique) de a uno por vez mientras arrastrás la toalla hacia la mano.', 53552),
  ('LEVANTAR UN OBJETO CHICO HASTA 90 GRADOS', NULL, true, 'activo; fortalecimiento', 'Codo y mano', 'AROM (activo); Varios', 'Sostené un objeto chico, como una pesa de 1 kg o una lata de sopa. Apoyá el peso sobre la falda y después elevalo hasta unos 90 grados de flexión de hombro. Inclinate hacia adelante desde las caderas y apoyalo sobre una superficie que esté a la altura del hombro. Asegurate de juntar los omóplatos cuando el codo está flexionado. No levantes por encima de los 90 grados de hombro. No encojas el hombro. No flexiones la columna.', 50543),
  ('ESTIRAMIENTO DE MOVIMIENTO POR ENCIMA DE LA CABEZA EN PRONACIÓN - HOTCHKISS', NULL, true, 'pasivo', 'Codo y mano', 'AROM (activo); Varios; Estiramientos', 'Agarrá la muñeca afectada y llevala a pronación, con la palma hacia abajo, como se muestra. Después, elevá el brazo afectado con la ayuda del brazo sano de modo que suba con la palma hacia afuera hasta la altura de la frente, y después seguí llevando el brazo por encima de la cabeza y luego por detrás de la cabeza. Para cuando esté detrás de la cabeza, la palma queda hacia arriba. Mantené el antebrazo en pronación todo el tiempo.', 50408),
  ('ESTIRAMIENTO DEL ARTESANO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo); Estiramientos', 'Sostené el brazo y la mano a 90 grados por delante del cuerpo, con la palma hacia adelante y la muñeca extendida todo lo que puedas controlar, y mantené. Los dedos deben apuntar hacia arriba. Después, girá el antebrazo de modo que la palma quede hacia arriba y flexioná los dedos de a uno por vez. Después, flexioná el codo todo lo que puedas. Luego, rotá el hombro hacia adentro mientras bajás el puño hacia abajo y afuera. Por último, extendé el codo hasta dejar el brazo estirado con el puño girado hacia afuera, como se muestra.', 50402),
  ('ESTIRAMIENTO DE ROTACIÓN DE MUÑECA EN POSICIÓN DE REZO', NULL, true, 'activo', 'Codo y mano', 'AROM (activo); Estiramientos', 'Empezá sentado en una silla con los codos flexionados y las manos juntas, presionadas una contra la otra. Los dedos deben apuntar en dirección contraria a vos, como se muestra. Después, rotá las manos de modo que los dedos apunten hacia el pecho. Mantené, volvé a la posición inicial y repetí.', 177484),
  ('ADUCCIÓN CON PELOTA', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'Con una pelota elástica, apretala con fuerza entre los dedos.', 5229),
  ('APLASTAR LA PELOTA', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'Con una pelota elástica, aplastala con fuerza sobre una mesa u otra superficie dura usando la palma de la mano.', 5232),
  ('APRETAR LA PELOTA - BILATERAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Pelota', 'Sostené una pelota elástica con una mano y superponé la otra mano, como se muestra. Apretá la pelota con fuerza con ambas manos. Mantené, relajá y repetí.', 163276),
  ('FLEXIÓN DE PULGAR CON PELOTA', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'Con una pelota elástica, presioná con fuerza la punta del pulgar contra ella, como se muestra.', 88),
  ('PELOTA CON PUNTAS DE LOS DEDOS', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'Con una pelota elástica, presionala con fuerza contra una mesa usando solamente las puntas de los dedos, como se muestra.', 5237),
  ('GIRO DE PELOTA', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'Con una pelota elástica entre los dedos, movela pasándola a los dedos vecinos, como se muestra. Tratá de que solo 2 o 3 dedos toquen la pelota a la vez.', 5238),
  ('PELOTA GIROSCÓPICA - FLEXIÓN Y EXTENSIÓN BÁSICA DE MUÑECA', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'Poné en marcha el giro de una pelota giroscópica y después movés la muñeca hacia adelante y atrás, en flexión y extensión, para mantener el giro.', 57431),
  ('PELOTA GIROSCÓPICA - TIRO DE BÁSQUET', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'Poné en marcha el giro de una pelota giroscópica. Mantené la pelota girando mientras hacés el movimiento de un tiro libre de básquet. Repetí manteniendo el giro de la pelota giroscópica.', 57637),
  ('PELOTA GIROSCÓPICA - CÍRCULOS DE MUÑECA', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'Poné en marcha el giro de una pelota giroscópica y después movés la muñeca en círculos para mantener el giro.', 57636),
  ('PELOTA GIROSCÓPICA - PUNTAS DE LOS DEDOS', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'Poné en marcha el giro de una pelota giroscópica. Agarrá la pelota solamente con las puntas de los dedos. Movés la muñeca hacia adelante y atrás en flexión, extensión y en círculos si hace falta, para mantener el giro.', 57433),
  ('BALÓN MEDICINAL - LANZAMIENTO CON BÍCEPS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Pelota', 'Lanzá un balón medicinal al aire flexionando solamente los codos. La posición inicial es con los brazos extendidos sosteniendo el balón por delante tuyo, como se muestra. Después, flexioná los codos para lanzar el balón al aire. Después, atajá el balón con los codos flexionados y frenalo mientras los codos se van estirando hasta volver a la posición inicial.', 6235),
  ('AUTOMASAJE CON PELOTA - MÚSCULO BÍCEPS', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'Sentate en una silla y apoyá el brazo sobre una mesa con la palma hacia arriba. Colocá una pelota de lacrosse o de tenis/paleta sobre la parte de arriba del brazo, en el bíceps. Rodá la pelota hacia arriba y abajo a lo largo del bíceps para un masaje suave.', 99591),
  ('LANZAMIENTO DE PELOTA DE TENIS - ALTERNADO', NULL, true, 'activo', 'Codo y mano', 'Pelota', 'De pie, empezá sosteniendo una pelota de tenis con una mano y después lanzala contra una pared y atajala con la otra mano. Volvé a pasar la pelota a la mano inicial y repetí. Podés progresar parándote con los pies más juntos.', 119355),
  ('PELOTA GIROSCÓPICA - PRONACIÓN Y SUPINACIÓN', NULL, true, 'fortalecimiento', 'Codo y mano', 'Pelota; Peso libre', 'Poné en marcha el giro de una pelota giroscópica. Agarrá la pelota de modo que la bola interna que gira quede entre el pulgar y el índice. Con el codo flexionado, rotá desde el antebrazo como si girases repetidamente el picaporte de una puerta. Repetí manteniendo el giro de la pelota giroscópica todo el tiempo.', 57641),
  ('PELOTA GIROSCÓPICA - PREPARACIÓN CON EL HILO', NULL, true, 'activo', 'Codo y mano', 'Pelota; Varios', 'Para preparar una pelota giroscópica y que empiece a girar, usá el hilo que viene con la pelota e insertá la punta metálica en un agujerito de la bola interna. Girá la bola interna si no encontrás el agujero. Una vez insertado, girá la bola interna para que el hilo se enrolle alrededor de ella. Ahora está lista para tirar del hilo rápidamente y arrancar el giro.', 57639),
  ('CURLS DE BÍCEPS - BASTÓN - BANDA ELÁSTICA', NULL, true, 'activo_asistido; fortalecimiento', 'Codo y mano', 'Banda elástica', 'Fijá las dos puntas de una banda elástica a un bastón y pisá la parte del medio de la banda con los pies, como se muestra. Empezá con los brazos abajo y los codos estirados, y después flexioná los codos para elevar el bastón. Bajá y repetí.', 129088),
  ('CLX - CURLS DE BÍCEPS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'De pie, pisá la CLX dejando una anilla de separación entre los pies. Con los brazos al costado del cuerpo sosteniendo la banda elástica, subí la mano flexionando el codo. Mantené las palmas hacia arriba todo el tiempo.', 40088),
  ('CLX - CURLS DE BÍCEPS - SUPINADOR LARGO - CURL MARTILLO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'De pie, pisá la CLX dejando una anilla de separación entre los pies. Con los brazos al costado del cuerpo sosteniendo la banda elástica, subí la mano flexionando el codo. Mantené las palmas mirando hacia adentro todo el tiempo.', 40087),
  ('CLX - CURL DE BÍCEPS - BRAQUIAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'De pie, pisá la CLX dejando una anilla de separación entre los pies. Con los brazos al costado del cuerpo sosteniendo la banda elástica, subí las manos flexionando el codo. Mantené las palmas hacia abajo todo el tiempo.', 40086),
  ('CLX - DESVIACIÓN RADIAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Apoyá el antebrazo sobre el muslo o sobre una mesa. Colocá una punta de la banda CLX en el pie y agarrá otra anilla con la palma en posición neutra (palma hacia el costado). Subí y bajá la mano flexionando la muñeca, como se muestra.', 40591),
  ('CLX - SUPINACIÓN', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Sentado, colocá una anilla alrededor del pie y otra anilla alrededor del pulgar, con la mano apoyada sobre la rodilla, como se muestra. Empezá con la palma hacia abajo. Después, girá la muñeca afectada hacia la posición de palma hacia arriba.', 40592),
  ('CLX - DESVIACIÓN CUBITAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Sostené una anilla de la banda CLX con una mano y estabilizá agarrando la banda unos 30 cm más allá. Movés la muñeca que trabajás de lado a lado, como se muestra.', 40593),
  ('CLX - EXTENSIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Apoyá el antebrazo sobre el muslo o sobre una mesa. Colocá una punta de la banda CLX en el pie y agarrá otra anilla con la palma hacia abajo. Subí y bajá la mano flexionando la muñeca, como se muestra.', 40587),
  ('CLX - PRONACIÓN DE MUÑECA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Sentado, colocá una anilla alrededor del pie y otra anilla alrededor del pulgar, con la mano apoyada sobre la rodilla, como se muestra. Empezá con la palma hacia arriba. Después, girá la muñeca afectada hacia la posición de palma hacia abajo.', 40124),
  ('EXTENSIÓN DE TODOS LOS DEDOS CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Colocá las puntas de los dedos juntas dentro de un trozo de banda elástica. Después, separá los dedos mientras estirás la banda elástica.', 22419),
  ('DESVIACIÓN RADIAL CON BANDA ELÁSTICA - 2', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Sosteniendo una banda elástica, llevá la muñeca de arriba hacia arriba, como se muestra. La mano de abajo debe quedarse quieta.', 4679),
  ('EXTENSIÓN DE CODO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Sostené una banda elástica o cuerda deportiva con ambas manos. Mantené una mano arriba, por delante del hombro, para fijarla ahí. Elevá el otro hombro a 90 grados con el codo flexionado. Después, estirá el codo que trabajás contra la resistencia mientras estirás la banda. Después, dejá que el codo se flexione al volver a la posición inicial. Repetí.', 67065),
  ('GERIÁTRICO - CURLS DE BÍCEPS CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Sentate en una silla y colocá una banda elástica larga debajo de los pies, sosteniendo las puntas con las manos. Empezá con los brazos al costado del cuerpo sosteniendo las puntas de la banda. Después, flexioná los codos mientras subís las manos y tirás de la banda hacia arriba. Bajá y repetí.', 125295),
  ('GERIÁTRICO - EXTENSIÓN DE TRÍCEPS CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Sentado, sostené y fijá una punta de una banda elástica contra el pecho. Sostené la otra punta con la mano contraria, con el codo flexionado y el brazo al costado del cuerpo. Empezá tirando de la banda hacia abajo de modo que el codo pase de flexionado a estirado, como se muestra. Volvé a la posición inicial y repetí.', 124569),
  ('EJERCITADOR DE AGARRE - PRESA DE LLAVE', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Sostené el ejercitador con el costado del 2do dedo y el pulgar. La presa es parecida a la de sostener una llave. Apretá, soltá y repetí.', 52992),
  ('EJERCITADOR DE AGARRE - LUMBRICALES', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Agarrá con el pulgar abajo y los otros dedos sobre la barra móvil de arriba. Apretá el ejercitador manteniendo los dedos de arriba lo más estirados que puedas todo el tiempo. Apretá, soltá y repetí.', 53002),
  ('EJERCITADOR DE AGARRE - ADUCCIÓN DE PULGAR', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Sostené el ejercitador con el pulgar sobre la barra móvil de arriba y los otros dedos abajo, como se muestra. Apretá, soltá y repetí.', 53005),
  ('EJERCITADOR DE AGARRE - PUÑO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Usá un ejercitador de agarre para apretar hasta cerrar el puño y después soltá. Repetí.', 52991),
  ('DECÚBITO VENTRAL - EXTENSIÓN DE TRÍCEPS CON BANDA ELÁSTICA - AUTOFIJADA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Acostate boca arriba, sostené y fijá una punta de una banda elástica contra el pecho. Sostené la otra punta con la mano contraria, con el codo flexionado y el brazo al costado del cuerpo. Empezá tirando de la banda hacia abajo de modo que el codo pase de flexionado a estirado, como se muestra. Volvé a la posición inicial y repetí.', 183377)
INSERT INTO exercise_library (name, professional_id, is_active, exercise_type, catalog_region, catalog_subcategory, instructions, source_exercise_id)
VALUES
  ('MANO EN FORMA DE C CON GOMITA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Colocá una gomita elástica alrededor de la mano, como se muestra. Empezá en posición relajada y después llevá la mano a una posición en forma de C contra la resistencia de la banda. Volvé a la posición inicial y repetí.', 87312),
  ('CUERDA DEPORTIVA - CURLS DE BÍCEPS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica', 'Empezá sosteniendo las puntas de una cuerda deportiva o banda elástica. Después, parate sobre el centro de la cuerda/banda. Con las palmas hacia adelante, flexioná los codos mientras subís las manos hacia los hombros. Bajá y repetí.', 65745),
  ('EJERCITADOR DE AGARRE - PRESA TRIDIGITAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica; Ejercitador de agarre', 'Sostené el ejercitador con las puntas de los dedos 1 a 3, como se muestra. Apretá, soltá y repetí.', 53001),
  ('EJERCITADOR DE AGARRE - PREPARACIÓN', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica; Ejercitador de agarre', 'Pasá una gomita elástica alrededor de la barra móvil y después tirá de ella hacia arriba y enganchala en el marco. Podés usar una banda o varias para lograr la resistencia deseada.', 53008),
  ('EJERCITADOR DE AGARRE 2-3', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica; Ejercitador de agarre', 'Sostené el ejercitador con el pulgar y los dedos 2do y 3ro. Apretá, soltá y repetí.', 53003),
  ('EJERCITADOR DE AGARRE 4-5 PUÑO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Banda elástica; Ejercitador de agarre', 'Sostené el ejercitador con el pulgar y los dedos 4to y 5to. Apretá, soltá y repetí.', 53004),
  ('MANCUERNA - CURLS DE BÍCEPS - SENTADO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Sentado en una silla, sostené una mancuerna chica de modo que el codo quede estirado y la palma de la mano apunte hacia adelante. Después, elevá la pesa mientras flexionás el codo. Bajá y repetí.', 66138),
  ('MANCUERNA - CURLS DE BÍCEPS 2 - SENTADO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Sentado en una silla, sostené una mancuerna chica de modo que el codo quede estirado y la palma apunte hacia el costado. Después, flexioná el codo y elevá la pesa. Mientras subís, girá la palma para que quede hacia arriba. Al bajar la pesa, destorcé el antebrazo de modo que la pesa vuelva a apuntar hacia el costado. Bajá y repetí.', 66127),
  ('MANCUERNA - CURLS DE BRAQUIAL - SENTADO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Sentado en una silla, sostené una mancuerna chica de modo que el codo quede estirado y la palma apunte hacia atrás. Después, flexioná el codo y elevá la pesa. No rotes el antebrazo: la palma no debe quedar hacia adelante en el punto máximo de la flexión. Bajá y repetí.', 66129),
  ('MANCUERNA - SUPINADOR LARGO - CURLS MARTILLO - SENTADO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Sentado en una silla, sostené una mancuerna chica de modo que el codo quede estirado y la palma apunte hacia el costado del cuerpo. Después, flexioná el codo y elevá la pesa. No rotes el antebrazo: la palma debe mirar hacia el costado del cuerpo todo el tiempo. Bajá y repetí.', 66134),
  ('CURLS DE BÍCEPS EXCÉNTRICOS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Empezá sosteniendo una mancuerna con la palma hacia adelante y el brazo al costado del cuerpo. Después, usá la otra mano para ayudarte a subir la pesa mientras flexionás el codo. Después, sacá la otra mano y bajá la pesa sin la ayuda del otro brazo. Después repetí el proceso.', 78538),
  ('EXTENSIÓN DE MUÑECA EXCÉNTRICA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Apoyá el brazo con la palma hacia abajo sobre una mesa, con la mano por fuera del borde sosteniendo una mancuerna. Empezá usando la mano sana para elevar la mano afectada junto con la pesa. Mantené esa posición con la mano afectada mientras soltás la mano sana. Después, usá solamente la mano afectada que sostiene la pesa para bajarla mientras flexionás la muñeca. Volvé a la posición inicial elevando de nuevo con la mano sana y repetí.', 88137),
  ('FLEXIÓN DE MUÑECA EXCÉNTRICA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Apoyá el brazo con la palma hacia arriba sobre una mesa, con la mano por fuera del borde sosteniendo una mancuerna. Empezá usando la mano sana para elevar la mano afectada junto con la pesa. Mantené esa posición con la mano afectada mientras soltás la mano sana. Después, usá solamente la mano afectada que sostiene la pesa para bajarla mientras flexionás la muñeca. Volvé a la posición inicial elevando de nuevo con la mano sana y repetí.', 88138),
  ('DESVIACIÓN RADIAL DE MUÑECA EXCÉNTRICA - PESO LIBRE', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Apoyá el brazo con el pulgar hacia arriba sobre una mesa, con la mano por fuera del borde sosteniendo una mancuerna. Empezá usando la mano sana para elevar la mano afectada junto con la pesa. Mantené esa posición con la mano afectada mientras soltás la mano sana. Después, usá solamente la mano afectada que sostiene la pesa para bajarla mientras flexionás la muñeca. Volvé a la posición inicial elevando de nuevo con la mano sana y repetí.', 88139),
  ('EXTENSIÓN DE CODO - ROMPECRÁNEOS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Acostado boca arriba con una mancuerna, sostené el brazo derecho hacia arriba, en dirección al techo. Después, flexioná el codo para bajar la pesa hacia el costado de la cabeza. Después volvé a subirla a la posición inicial.', 22541),
  ('PRONACIÓN CON PESO LIBRE', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Apoyá el antebrazo sobre la rodilla o sobre una mesa. Después, sosteniendo la punta de una mancuerna chica, bajá lentamente la pesa hacia afuera del cuerpo y después volvé, como se muestra.', 22426),
  ('DESVIACIÓN RADIAL CON PESO LIBRE', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Empezá sosteniendo la punta de una mancuerna chica con la mano al costado del cuerpo. La mancuerna debe apuntar hacia adelante, como se muestra. Después, flexioná la muñeca de modo que la punta de la pesa suba. Volvé a la posición inicial y repetí.', 19049),
  ('SUPINACIÓN CON PESO LIBRE', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Apoyá el antebrazo sobre la rodilla o sobre una mesa. Después, sosteniendo la punta de una pesa chica, bajá lentamente la pesa hacia adentro del cuerpo y después volvé, como se muestra.', 22530),
  ('DESVIACIÓN CUBITAL CON PESO LIBRE', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Empezá sosteniendo la punta de una mancuerna chica con el brazo al costado del cuerpo. La pesa debe apuntar hacia atrás, como se muestra. Después, flexioná la muñeca de modo que la punta de la pesa suba. Volvé a la posición inicial y repetí.', 19043),
  ('GERIÁTRICO - CURLS DE BÍCEPS - BILATERAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Sentado en una silla y sosteniendo una pesa liviana o una botella de agua sobre cada muslo, levantá ambos lados flexionando los codos. Bajá y repetí.', 171535),
  ('GERIÁTRICO - CURLS DE BÍCEPS - CON PESO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Sentado en una silla y sosteniendo una pesa liviana o una botella de agua, levantá ese lado flexionando el codo. Bajá y repetí.', 172280),
  ('SUPINACIÓN CON MARTILLO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Bajá lentamente un martillo hacia adentro, como se muestra, y después volvé.', 99),
  ('CURLS DE BÍCEPS SENTADO - ALTERNADOS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Sentado en una silla y sosteniendo una mancuerna sobre cada muslo, levantá un lado flexionando el codo. Bajá y repetí. Hacelo de un lado y después alterná al otro lado.', 22416),
  ('EXTENSIÓN DE TRÍCEPS SENTADO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Sentate en una silla e inclinate hacia adelante. Empezá sosteniendo una mancuerna con el codo flexionado y el brazo paralelo al piso. Después, extendé el codo hacia atrás hasta dejarlo estirado. Volvé a la posición inicial y repetí.', 88134),
  ('SILLA DE RUEDAS - CURLS DE BÍCEPS - PESO LIBRE - BILATERAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Sentado en una silla de ruedas, sostené una mancuerna chica en cada mano. Mantené los codos estirados y las palmas hacia adelante. Después, elevá las pesas mientras flexionás los codos. Bajá y repetí.', 105300),
  ('SILLA DE RUEDAS - MANCUERNA - CURLS DE BÍCEPS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre', 'Sentado en una silla de ruedas, sostené una mancuerna chica de modo que el codo quede estirado y la palma de la mano apunte hacia adelante. Después, elevá la pesa mientras flexionás el codo. Bajá y repetí.', 105298),
  ('ESTIRAMIENTO EN DESVIACIÓN CUBITAL DE MUÑECA - PESO LIBRE', NULL, true, 'pasivo', 'Codo y mano', 'Peso libre', 'Empezá sosteniendo una mancuerna chica con el brazo apoyado sobre una mesa. Después, movés el brazo de modo que la muñeca quede por fuera del borde de la mesa, con la palma hacia el costado. Después, dejá que la muñeca caiga hacia abajo, en dirección al piso, como se muestra. Dejá que la gravedad estire la muñeca mientras mantenés esa posición. Volvé a la posición inicial con el brazo y la pesa apoyados sobre la mesa y después repetí.', 90596),
  ('ISOMÉTRICO DE BÍCEPS A 2 MANOS - PESO LIBRE', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre; Isométrico', 'Sentate con una mancuerna sobre una mesa, adelante tuyo. Levantá la mancuerna con ambas manos flexionando los codos. Mantené, bajala de nuevo sobre la mesa y repetí.', 163273),
  ('CURL DE BÍCEPS Y SOSTÉN ISOMÉTRICO - PESO LIBRE', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre; Isométrico', 'Empezá sosteniendo una mancuerna con ambas manos. Mantené un codo flexionado a unos 90 grados y el otro brazo estirado y abajo, al costado del cuerpo. Seguí sosteniendo un brazo a 90 grados. Con el brazo estirado que está al costado, flexioná el codo para subir la mancuerna. Bajá y repetí. Mantené las palmas hacia arriba todo el tiempo.', 170794),
  ('SOSTÉN ISOMÉTRICO DE BÍCEPS CON PESO LIBRE', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre; Isométrico', 'Sentate en una silla y apoyá los brazos sobre la falda. Flexioná el codo que trabajás para despegar la mano de la falda. Después, usá la mano sana para colocar una mancuerna chica en la mano que trabaja. Mantené esa posición con el brazo que trabaja de modo que la articulación del codo no se mueva (contracción isométrica). Mantené y después dejá que el brazo sano retire la pesa de la mano que trabaja para descansar, y después repetí.', 130983),
  ('PALO DE GOLF - PRONACIÓN Y SUPINACIÓN', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre; Varios', 'Sostené un palo de golf apuntando hacia el piso. Después, rotá la muñeca y el antebrazo para mover el palo de lado a lado, como se muestra. Atá una tobillera con peso a la cabeza del palo para agregar resistencia.', 18691),
  ('PALO DE GOLF - DESVIACIÓN RADIAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre; Varios', 'Empezá sosteniendo un palo de golf con una mano, con el pulgar arriba y la cabeza del palo cerca del piso. Después, flexioná la muñeca mientras levantás el palo. Bajá el palo de forma controlada para volver a la posición inicial y repetí.', 174649),
  ('PALO DE GOLF - DESVIACIÓN CUBITAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre; Varios', 'Empezá sosteniendo un palo de golf con una mano, como se muestra. Después, flexioná la muñeca mientras levantás el palo. Bajá el palo de forma controlada para volver a la posición inicial y repetí.', 175087),
  ('PRONACIÓN CON MARTILLO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Peso libre; Varios', 'Bajá lentamente un martillo hacia afuera, como se muestra, y después volvé.', 98),
  ('ESTIRAMIENTO EN EXTENSIÓN DE CODO - PESO LIBRE - MESA', NULL, true, 'pasivo', 'Codo y mano', 'Peso libre; Estiramientos', 'Apoyá el codo sobre una toalla enrollada mientras sostenés una mancuerna chica. La palma de la mano debe apuntar hacia arriba todo el tiempo. Empezá con el codo flexionado y después bajá lentamente el brazo permitiendo un estiramiento suave hacia una posición más extendida. Dejá que la gravedad estire el codo durante el tiempo de sostén indicado. Después, volvé a la posición inicial y repetí.', 90587),
  ('ESTIRAMIENTO EN EXTENSIÓN DE MUÑECA - PESO LIBRE', NULL, true, 'pasivo', 'Codo y mano', 'Peso libre; Estiramientos', 'Empezá sosteniendo una mancuerna chica con el brazo apoyado sobre una mesa. Después, movés el brazo de modo que la muñeca quede por fuera del borde de la mesa, con la palma hacia arriba. Después, dejá que la muñeca caiga hacia atrás y abajo, en dirección al piso, como se muestra. Dejá que la gravedad estire la muñeca mientras mantenés esa posición. Volvé a la posición inicial con el brazo y la pesa apoyados sobre la mesa y después repetí.', 90592),
  ('ESTIRAMIENTO EN FLEXIÓN DE MUÑECA - PESO LIBRE', NULL, true, 'pasivo', 'Codo y mano', 'Peso libre; Estiramientos', 'Empezá sosteniendo una mancuerna chica con el brazo apoyado sobre una mesa. Después, movés el brazo de modo que la muñeca quede por fuera del borde de la mesa, con la palma hacia abajo. Después, dejá que la muñeca caiga hacia abajo, en dirección al piso, como se muestra. Dejá que la gravedad estire la muñeca mientras mantenés esa posición. Volvé a la posición inicial con el brazo y la pesa apoyados sobre la mesa y después repetí.', 90595),
  ('EJERCICIO CON RED ELÁSTICA - PRESA TRIDIGITAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Ejercitador de agarre; Varios', 'Colocá el pulgar y los dedos 2do y 3ro en la red formando un triángulo. Después, apretá los dedos juntándolos. Relajá y repetí.', 117006),
  ('EJERCICIO CON RED ELÁSTICA - GARRA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Ejercitador de agarre; Varios', 'Colocá las puntas de los dedos en la red y hacé una presa en garra flexionando solamente las 2 articulaciones más distales de los dedos.', 117012),
  ('EJERCICIO CON RED ELÁSTICA - ADUCCIÓN DE DEDOS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Ejercitador de agarre; Varios', 'Colocá los dedos 2 a 5 en los agujeros de la red. Después, intentá juntar los dedos apretándolos. Relajá y repetí.', 117020),
  ('EJERCICIO CON RED ELÁSTICA - FLEXIÓN DE DEDOS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Ejercitador de agarre; Varios', 'Sostené el borde del ejercitador de red y colocá los dedos en los agujeros. Flexioná los dedos, relajá y repetí.', 117004),
  ('EJERCICIO CON RED ELÁSTICA - PRESS DE PUÑO', NULL, true, 'activo', 'Codo y mano', 'Ejercitador de agarre; Varios', 'Colocá la red sobre una mesa y sostenela con la mano sana. Apoyá el puño en el centro de la red, presioná hacia adelante y mantené. Relajá y repetí.', 117015),
  ('ISOMÉTRICO DE ABDUCCIÓN DE DEDOS - A', NULL, true, 'fortalecimiento', 'Codo y mano', 'Isométrico', 'Usá la mano sana para resistir el movimiento de separación entre el 2do y el 3er dedo.', 92),
  ('ISOMÉTRICO DE ABDUCCIÓN DE DEDOS - B', NULL, true, 'fortalecimiento', 'Codo y mano', 'Isométrico', 'Usá la mano sana para resistir el movimiento de separación entre el 3er y el 4to dedo.', 93),
  ('ISOMÉTRICO DE ABDUCCIÓN DE DEDOS - C', NULL, true, 'fortalecimiento', 'Codo y mano', 'Isométrico', 'Usá la mano sana para resistir el movimiento de separación entre el 4to y el 5to dedo.', 94),
  ('ISOMÉTRICO DE ABDUCCIÓN DE DEDOS - D', NULL, true, 'fortalecimiento', 'Codo y mano', 'Isométrico', 'Usá la mano sana para resistir el movimiento de separación entre el 1er y el 2do dedo.', 95),
  ('ISOMÉTRICO DE ABDUCCIÓN DE DEDOS - E', NULL, true, 'fortalecimiento', 'Codo y mano', 'Isométrico', 'Usá la mano sana para resistir el movimiento de separación entre el 2do y el 5to dedo.', 96),
  ('ISOMÉTRICO DE ADUCCIÓN DE PULGAR', NULL, true, 'fortalecimiento', 'Codo y mano', 'Isométrico', 'Colocá el índice de la mano sana en el espacio interdigital entre el pulgar y el índice de la mano afectada. Apretá el pulgar contra el índice y mantené. Esto debería hacer que el índice se eleve mientras el músculo se contrae. Después relajá y repetí.', 93290),
  ('FLEXIÓN ISOMÉTRICA DE PULGAR', NULL, true, 'fortalecimiento', 'Codo y mano', 'Isométrico', 'Presioná el pulgar hacia adentro contra los dedos de la mano sana.', 59),
  ('CARGA DE PESO SOBRE ESPONJA - APLASTAR', NULL, true, 'fortalecimiento', 'Codo y mano', 'Isométrico; Varios', 'Colocá una esponja gruesa o varias capas de esponja fina apiladas sobre una mesa. Apoyá la palma de la mano sobre la esponja y aplicá fuerza hacia abajo para aplastarla. Mantené, soltá y repetí.', 92523),
  ('ABOTONAR UNA CAMISA', NULL, true, 'activo', 'Codo y mano', 'Varios', 'Practicá abotonar y desabotonar una camisa con los dedos y la mano. Si te cuesta, quedate en el mismo botón. Si no, andá subiendo y bajando por la camisa trabajando botones a distintas alturas.', 65747),
  ('ENROSCAR Y DESENROSCAR TAPAS', NULL, true, 'activo', 'Codo y mano', 'Varios', 'Colocá varios envases con tapas de distintos tamaños sobre una mesa. Sentado, sacá la tapa de cada envase de a una. Después de sacar todas las tapas, volvé a enroscarlas de a una. Usá la mano que trabajás para sacar y volver a poner cada tapa. Podés progresar el ejercicio haciéndolo parado cerca de la mesa. Si hace falta, usá una silla detrás tuyo o que alguien te asista por seguridad.', 92549),
  ('MASAJE TRANSVERSO PROFUNDO - TENDÓN EXTENSOR DE MUÑECA', NULL, true, 'sin_clasificar', 'Codo y mano', 'Varios', 'Apoyá el brazo sobre una mesa con la palma hacia abajo. Con la otra mano, usá 2 o 3 dedos y masajeá el antebrazo cerca de la parte ósea del codo, donde haya molestia. Movés los dedos cruzando el brazo en dirección horizontal, no en línea con el antebrazo sino de lado a lado.', 87313),
  ('MASAJE TRANSVERSO PROFUNDO - TENDÓN FLEXOR DE MUÑECA', NULL, true, 'sin_clasificar', 'Codo y mano', 'Varios', 'Apoyá el brazo sobre una mesa con la palma hacia arriba. Con la otra mano, usá 2 o 3 dedos y masajeá el antebrazo cerca de la parte ósea del codo, donde haya molestia. Movés los dedos cruzando el brazo en dirección horizontal, no en línea con el antebrazo sino de lado a lado.', 87314),
  ('DIGIFLEX - GARRA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Varios', 'Usando un Digiflex u otro ejercitador de agarre similar, apretá el dispositivo usando solamente las puntas de los dedos, como se muestra.', 20806),
  ('DIGIFLEX - FLEXIÓN DE DEDOS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Varios', 'Usando un Digiflex u otro ejercitador de agarre similar, apretá el dispositivo con un dedo y después hacelo individualmente con los otros, de a uno por vez.', 20807),
  ('DIGIFLEX - FLEXIÓN DE DEDOS - TODOS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Varios', 'Usando un Digiflex u otro ejercitador de agarre similar, apretalo usando los pulpejos de todos los dedos, como se muestra.', 20809),
  ('DIGIFLEX - PRESA DE LLAVE', NULL, true, 'fortalecimiento', 'Codo y mano', 'Varios', 'Usando un Digiflex u otro ejercitador de agarre similar, sostenelo de costado y apretalo con el pulgar y el costado del índice, como si sostuvieras una llave.', 20808),
  ('DIGIFLEX - GATILLO DE PISTOLA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Varios', 'Usando un Digiflex u otro ejercitador de agarre similar, apretá el dispositivo con el índice como si apretaras el gatillo de una pistola.', 20811),
  ('DIGIFLEX - PRESA DE FUERZA', NULL, true, 'fortalecimiento', 'Codo y mano', 'Varios', 'Usando un Digiflex u otro ejercitador de agarre similar, apretá el dispositivo con una presa completa y profunda (presa de fuerza).', 20810),
  ('FLEXBAR - PRONACIÓN BILATERAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Varios', 'Empezá sosteniendo el Flexbar en posición horizontal por delante tuyo, con ambas manos hacia arriba. Agarrá con firmeza y después torcé el Flexbar de modo que las palmas queden enfrentadas. Volvé a la posición inicial y repetí.', 51446),
  ('EJERCICIO CON RED ELÁSTICA - PRESA DE FLEXIÓN BILATERAL', NULL, true, 'pasivo', 'Codo y mano', 'Varios', 'Sostené el borde del ejercitador de red con ambas manos y colocá los dedos en los agujeros. Flexioná los dedos, relajá y repetí.', 117007),
  ('EJERCICIO CON RED ELÁSTICA - ABDUCCIÓN DE DEDOS', NULL, true, 'activo', 'Codo y mano', 'Varios', 'Colocá los dedos 2 a 5 en agujeros contiguos de la red. Después, intentá separar los dedos entre sí. Relajá y repetí.', 117018),
  ('EJERCICIO CON RED ELÁSTICA - EXTENSIÓN DE DEDOS', NULL, true, 'activo', 'Codo y mano', 'Varios', 'Colocá la red sobre una mesa y sostenela con la mano sana. Colocá los 5 dedos en los agujeros de la red, cerca de la primera línea articular. Extendé todos los dedos mientras abrís la mano. Relajá y repetí.', 117021),
  ('EJERCICIO CON RED ELÁSTICA - HIPEREXTENSIÓN DE DEDOS', NULL, true, 'activo', 'Codo y mano', 'Varios', 'Colocá la red plana sobre una mesa y sostenela con la mano sana. Pasá los 5 dedos por los agujeros de la red y sacalos por los agujeros contiguos. Extendé todos los dedos mientras los despegás de la mesa. Relajá y repetí.', 117022),
  ('EJERCICIO CON RED ELÁSTICA - PRESA', NULL, true, 'activo', 'Codo y mano', 'Varios', 'Colocá la red sobre una mesa y sostenela con la mano sana. Colocá los 5 dedos en los agujeros de la red, cerca de la primera línea articular. Flexioná todos los dedos apretando la red, después relajá y repetí.', 117009),
  ('EJERCICIO CON RED ELÁSTICA - PRESA CON TRACCIÓN', NULL, true, 'pasivo', 'Codo y mano', 'Varios', 'Colocá la red sobre una mesa y sostenela con la mano sana. Colocá los 5 dedos en los agujeros de la red, cerca de la primera línea articular. Empezá flexionando todos los dedos apretando la red y después tirá de ella y mantené. Después relajá, volvé a la posición inicial y repetí.', 117008),
  ('EJERCICIO CON RED ELÁSTICA - PRESS CON LA PALMA', NULL, true, 'activo', 'Codo y mano', 'Varios', 'Colocá la red sobre una mesa y sostenela con la mano sana. Apoyá la palma en el centro de la red y después presioná hacia adelante y mantené. Relajá y repetí.', 117014),
  ('EJERCICIO CON RED ELÁSTICA - TRACCIÓN EN PRONACIÓN', NULL, true, 'pasivo', 'Codo y mano', 'Varios', 'Colocá la red sobre una mesa y sostenela con la mano sana. Colocá los 5 dedos en los agujeros de la red, cerca de la primera línea articular. Empezá flexionando todos los dedos apretando la red, después girá la mano como llevando la palma hacia abajo y después tirá y mantené. Después relajá, volvé a la posición inicial y repetí.', 117026),
  ('EJERCICIO CON RED ELÁSTICA - TRACCIÓN EN SUPINACIÓN', NULL, true, 'pasivo', 'Codo y mano', 'Varios', 'Colocá la red sobre una mesa y sostenela con la mano sana. Colocá los 5 dedos en los agujeros de la red, cerca de la primera línea articular. Empezá flexionando todos los dedos apretando la red, después girá la mano como llevando la palma hacia arriba y después tirá y mantené. Después relajá, volvé a la posición inicial y repetí.', 117027),
  ('EJERCICIO CON RED ELÁSTICA - ADUCCIÓN DE PULGAR', NULL, true, 'activo', 'Codo y mano', 'Varios', 'Sostené el borde del ejercitador de red con los 4 dedos y colocá el pulgar en un agujero. Flexioná el pulgar hacia los dedos, relajá y repetí.', 117017),
  ('ESTIRAMIENTO DE MOVIMIENTO POR ENCIMA DE LA CABEZA EN SUPINACIÓN - HOTCHKISS', NULL, true, 'pasivo', 'Codo y mano', 'Varios; Estiramientos', 'Agarrá la muñeca afectada y llevala a supinación, con la palma hacia arriba, como se muestra. Después, elevá el brazo afectado con la ayuda del brazo sano de modo que suba con la palma mirando hacia vos a la altura de la frente, y después seguí llevando el brazo por encima de la cabeza y luego por detrás de la cabeza. Para cuando esté detrás de la cabeza, la palma queda hacia abajo. Mantené el antebrazo en supinación todo el tiempo.', 50409),
  ('FLEXIÓN DEL 2DO DEDO - ROM', NULL, true, 'pasivo', 'Codo y mano', 'PROM (pasivo); Estiramientos', 'Empezá con la mano abierta y todos los dedos extendidos. Después, agarrá la punta del índice (2do dedo) y flexionalo hacia la palma. Volvé a la posición inicial y repetí.', 174019),
  ('FLEXIÓN DEL 3ER DEDO - ROM', NULL, true, 'pasivo', 'Codo y mano', 'PROM (pasivo); Estiramientos', 'Empezá con la mano abierta y todos los dedos extendidos. Después, agarrá la punta del dedo mayor (3er dedo) y flexionalo hacia la palma. Volvé a la posición inicial y repetí.', 174020),
  ('FLEXIÓN DEL 4TO DEDO - ROM', NULL, true, 'pasivo', 'Codo y mano', 'PROM (pasivo); Estiramientos', 'Empezá con la mano abierta y todos los dedos extendidos. Después, agarrá la punta del dedo anular (4to dedo) y flexionalo hacia la palma. Volvé a la posición inicial y repetí.', 174021),
  ('ABDUCCIÓN / ADUCCIÓN DEL 5TO DEDO - ROM', NULL, true, 'pasivo', 'Codo y mano', 'PROM (pasivo); Estiramientos', 'Agarrá el meñique (5to dedo) y movelo de lado a lado (separándolo).', 173467),
  ('FLEXIÓN DE CUATRO DEDOS - ROM', NULL, true, 'pasivo', 'Codo y mano', 'PROM (pasivo); Estiramientos', 'Empezá con la mano abierta y todos los dedos extendidos. Después, agarrá los dedos 2 a 5 y flexionalos hacia la palma, como se muestra. Volvé a la posición inicial y repetí.', 174017),
  ('ESTIRAMIENTO DE LA EMINENCIA TENAR', NULL, true, 'pasivo', 'Codo y mano', 'PROM (pasivo); Estiramientos', 'Usá el pulgar de la mano sana para estirar el espacio interdigital entre el pulgar y el índice, como se muestra. Mantené, relajá y repetí.', 162069),
  ('EXTENSIÓN DE MUÑECA - ROM', NULL, true, 'pasivo', 'Codo y mano', 'PROM (pasivo); Estiramientos', 'Agarrá la mano y llevala hacia atrás, en extensión, como se muestra. Volvé a la posición neutra y repetí.', 174242),
  ('MASILLA - BÚSQUEDA DEL TESORO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Masilla', 'Buscá y sacá distintos objetos escondidos dentro de la masilla.', 87670),
  ('MASILLA - PRESA PENTADIGITAL', NULL, true, 'fortalecimiento', 'Codo y mano', 'Masilla', 'Hacé un bollo de masilla y después aplastalo. Después, apretalo con firmeza con los cinco dedos, como se muestra. Repetí.', 95856),
  ('MASILLA - ADUCCIÓN', NULL, true, 'fortalecimiento', 'Codo y mano', 'Masilla', 'Hacé un bollo de masilla y después aplastalo. Después, apoyá la mano sobre la masilla y apretá 2 dedos juntándolos mientras empujás la masilla, como se muestra. Repetí con todos los dedos.', 95849),
  ('MASILLA - ANILLA DE EXTENSIÓN DE UN DEDO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Masilla', 'Armá una tira tubular chica de masilla. Formá una anilla alrededor de 1 dedo y después tirá hacia arriba, como se muestra.', 8235),
  ('MASILLA - APLASTAR CON CARGA DE PESO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Masilla', 'Colocá un bollo de masilla sobre la mesa y después, con la palma de la mano, cargá peso a través de la mano y aplastá la masilla.', 87969),
  ('MASILLA - SEPARAR EL TUBO', NULL, true, 'fortalecimiento', 'Codo y mano', 'Masilla', 'Hacé un rollo de masilla formando una tira tubular chica. Después, apoyá la mano sobre la masilla y usá los dedos para separarla hacia los costados, como se muestra.', 95855),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA IFD DEL 3ER DEDO', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo mayor (3er dedo) sosteniéndolo por debajo del último nudillo. Usá el índice para flexionar y estirar el dedo en la última articulación. Mantené, relajá y repetí.', 179043),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA IFP DEL 3ER DEDO', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo mayor (3er dedo) sosteniéndolo por debajo del nudillo del medio. Usá el índice para flexionar y estirar el dedo en la articulación del medio. Mantené, relajá y repetí.', 179243),
  ('ESTIRAMIENTO EN FLEXIÓN DE 4 DEDOS', NULL, true, 'fortalecimiento', 'Codo y mano', 'Estiramientos', 'Agarrá la mano afectada como se muestra, apoyando el pulgar de la mano sana sobre las puntas de los dedos, y apretá la mano afectada llevándola a una posición de puño más cerrado. Mantené para un estiramiento suave, relajá y repetí.', 88140),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA IFD DEL 4TO DEDO', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo anular (4to dedo) sosteniéndolo por debajo del último nudillo. Usá el índice para flexionar y estirar el dedo en la última articulación. Mantené, relajá y repetí.', 178721),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA IFP DEL 4TO DEDO', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo anular (4to dedo) sosteniéndolo por debajo del nudillo del medio. Usá el índice para flexionar y estirar el dedo en la articulación del medio. Mantené, relajá y repetí.', 179242),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA IFD DEL 5TO DEDO', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el meñique (5to dedo) sosteniéndolo por debajo del último nudillo. Usá el índice para flexionar y estirar el dedo en la última articulación. Mantené, relajá y repetí.', 178720),
  ('ESTIRAMIENTO EN EXTENSIÓN DEL 5TO DEDO', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Girá la palma hacia abajo y después agarrá el meñique (5to dedo) con la otra mano y tirá de él hacia atrás hasta sentir un estiramiento suave.', 59990),
  ('FLEXIÓN DEL 5TO DEDO - ROM', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Empezá con la mano abierta y todos los dedos extendidos. Después, agarrá la punta del meñique (5to dedo) y flexionalo hacia la palma. Volvé a la posición inicial y repetí.', 174022),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA IFP DEL 5TO DEDO', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el meñique (5to dedo) sosteniéndolo por debajo del nudillo del medio. Usá el índice para flexionar y estirar el dedo en la articulación del medio. Mantené, relajá y repetí.', 179054),
  ('ESTIRAMIENTO EN EXTENSIÓN DEL 5TO DEDO', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Apoyá la mano sobre una mesa con la palma hacia abajo. Después, con la otra mano agarrá el meñique (5to dedo) y tirá de él hacia arriba, y mantené para un estiramiento suave. Bajá el dedo y repetí.', 66515),
  ('ESTIRAMIENTO DE ANTEBRAZO CON MANOS ENTRELAZADAS', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Cruzá los antebrazos uno sobre el otro de modo que el brazo que trabajás quede arriba. Entrelazá los dedos, como se muestra. Después, usá la muñeca de abajo para llevar la muñeca de arriba a una posición más flexionada, buscando el estiramiento. Mantené, relajá y repetí.', 50405),
  ('ESTIRAMIENTO EN GARRA - 1 DEDO POR VEZ', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Usá un dedo del lado sano para presionar sobre la uña del dedo del lado afectado. La mano afectada debe estar relajada. Mantené el estiramiento en el dedo afectado, después relajá y repetí. Buscando estos movimientos: MCF hacia extensión, IFP hacia flexión, IFD hacia flexión.', 50394),
  ('ESTIRAMIENTO EN GARRA - 4 DEDOS', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Usá los dedos del lado sano para presionar sobre las uñas de los dedos del lado afectado. La mano afectada debe estar relajada. Mantené el estiramiento en los dedos afectados. Buscando estos movimientos: MCF hacia extensión, IFP hacia flexión, IFD hacia flexión.', 50393),
  ('ESTIRAMIENTO EN EXTENSIÓN DE CODO - PESO ATADO - MESA', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Apoyá el codo sobre una toalla enrollada con una tobillera con peso atada a la muñeca. La palma de la mano debe apuntar hacia arriba todo el tiempo. Empezá con el codo flexionado y después bajá lentamente el brazo permitiendo un estiramiento suave hacia una posición más extendida. Dejá que la gravedad estire el codo durante el tiempo de sostén indicado. Después, volvé a la posición inicial y repetí.', 90588),
  ('ESTIRAMIENTO EN EXTENSIÓN DE CODO - TOALLA ENROLLADA', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Colocá una toalla enrollada sobre una mesa. Después, apoyá el brazo sobre el rollo de toalla con la palma hacia arriba y el codo cerca de la toalla. Relajá el brazo y dejá que la gravedad estire el codo hacia una posición más extendida.', 88264),
  ('ESTIRAMIENTO EN FLEXIÓN Y EXTENSIÓN DE CODO', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá la muñeca y flexionala hacia arriba buscando el estiramiento, y mantené. Después, bajá y estirala hacia la extensión, y mantené. Repetí.', 75025),
  ('ESTIRAMIENTO EN FLEXIÓN DE CODO 2', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Usá la otra mano para llevarlo a una posición más flexionada.', 69),
  ('ESTIRAMIENTO EN ABDUCCIÓN DE DEDOS', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Tirá del dedo afectado alejándolo del dedo mayor y mantené el estiramiento.', 44),
  ('ESTIRAMIENTO EN ADUCCIÓN DE DEDOS', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo afectado y estiralo suavemente hacia adentro, como se muestra.', 45),
  ('ESTIRAMIENTO EN EXTENSIÓN DE LA IFD', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo afectado por debajo del último nudillo y estiralo suavemente hacia una posición más extendida.', 46),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA IFD', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo afectado por debajo del último nudillo y estiralo suavemente hacia una posición más flexionada.', 53),
  ('EXTENSIÓN DE DEDOS - ESTIRAMIENTO EN POSICIÓN DE REZO', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Juntá las puntas de los dedos. Después, elevá los codos hasta sentir un estiramiento en los dedos. Mantené, volvé a la posición inicial y repetí.', 171053),
  ('ESTIRAMIENTO EN FLEXIÓN DE DEDOS', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Usá una mano para flexionar y estirar los dedos de la mano que trabajás, como se muestra.', 11203),
  ('ESTIRAMIENTO EN EXTENSIÓN DE LA MCF', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá la mano por debajo del nudillo más cercano y estirá suavemente el dedo hacia la extensión, como se muestra.', 8424),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA MCF', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo afectado justo por debajo del nudillo principal y flexionalo suavemente hacia abajo, como se muestra.', 54),
  ('ESTIRAMIENTO EN EXTENSIÓN DE LA IFP', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo afectado por debajo del nudillo del medio y estiralo suavemente hacia una posición más extendida.', 51),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA IFP', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo afectado por debajo del nudillo del medio y estiralo suavemente hacia una posición más flexionada.', 55),
  ('GERIÁTRICO - ESTIRAMIENTO EN POSICIÓN DE REZO - MUÑECA', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Sentado en una silla, juntá las palmas de las manos con los dedos apuntando hacia arriba. Después, bajá las manos por delante del pecho, como se muestra, hasta sentir un estiramiento suave en las muñecas y los antebrazos.', 172279),
  ('GERIÁTRICO - ESTIRAMIENTO DE TRÍCEPS', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Flexioná el codo y usá el otro brazo para elevarlo hacia la cabeza. Empujá suavemente el codo hacia arriba hasta sentir un estiramiento en la parte de atrás del brazo. Mantené, relajá y repetí.', 125318),
  ('ESTIRAMIENTO EN PRONACIÓN - TOALLA', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Colocá una toalla chica enrollada entre el codo y el costado del cuerpo. Con la palma apuntando hacia la línea media, agarrá una punta de una toalla chica con la mano que trabajás y después enrollala alrededor de la muñeca, como se muestra. Después, usá la otra mano para tirar de la toalla generando un estiramiento en rotación del antebrazo. El estiramiento y la dirección de la tracción deben llevar la palma hacia abajo (pronación). Mantené, relajá y repetí.', 175089),
  ('ESTIRAMIENTO EN PRONACIÓN - TOALLA', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Colocá una toalla chica enrollada entre el codo y el costado del cuerpo. Con la palma apuntando hacia la línea media, agarrá una punta de una toalla chica con la mano que trabajás y después enrollala alrededor de la muñeca, como se muestra. Después, usá la otra mano para tirar de la toalla y crear un estiramiento en rotación del antebrazo. El estiramiento y la dirección de la tracción deben llevar la palma hacia abajo (pronación). Mantené, relajá y repetí.', 173466),
  ('ESTIRAMIENTO EN POSICIÓN DE REZO INVERTIDA', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Juntá el dorso de las manos para estirar la muñeca, como se muestra.', 22533),
  ('AAROM AUTOASISTIDO - FLEXIÓN Y EXTENSIÓN DE CODO', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Entrelazá las manos sobre una mesa. Usá el brazo/mano sano para asistir el movimiento del brazo afectado hacia la flexión y la extensión mientras deslizás los brazos por la superficie de la mesa. Usá una funda de almohada o una toalla si hace falta para reducir el rozamiento.', 50546),
  ('ESTIRAMIENTO EN SUPINACIÓN', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Con los codos flexionados, agarrá la mano afectada desde abajo de la palma, por el lado externo de la mano que trabajás, como se muestra. Después, estirá los codos para estirar el antebrazo.', 87616),
  ('ESTIRAMIENTO EN SUPINACIÓN - TOALLA', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Colocá una toalla chica enrollada entre el codo y el costado del cuerpo. Con la palma apuntando hacia la línea media, agarrá una punta de una toalla chica con la mano que trabajás y después enrollala alrededor de la muñeca, como se muestra. Después, usá la otra mano para tirar de la toalla generando un estiramiento en rotación del antebrazo. El estiramiento y la dirección de la tracción deben llevar la palma hacia arriba (supinación). Mantené, relajá y repetí.', 130994),
  ('ESTIRAMIENTO DE LA EMINENCIA TENAR', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Apoyá la mano afectada sobre una mesa con la palma hacia arriba. Después, pasá la otra mano por debajo de la mano afectada y agarrá la palma justo por debajo del pulgar (la eminencia tenar), como se muestra. Tirá hacia abajo para un estiramiento suave.', 66526),
  ('ESTIRAMIENTO DE LA EMINENCIA TENAR - 2', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Sostené la mano contra el pecho, como se muestra, con la mano afectada arriba. Usá la mano sana, pasándola por debajo, para agarrar la parte carnosa de la palma del lado del pulgar de la mano afectada. Sostené así mientras alejás las manos del pecho y tirás hacia abajo de la mano afectada hasta sentir un estiramiento suave en el pulgar y la palma.', 66577),
  ('ESTIRAMIENTO TENAR', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Flexioná el codo para acercar la mano al pecho. Después agarrá la parte gruesa del pulgar y la mano con la otra mano. Después, extendé el codo mientras estirás el pulgar hacia adelante y abajo hasta sentir un estiramiento suave.', 59996),
  ('ESTIRAMIENTO EN ABDUCCIÓN DE PULGAR', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el pulgar y separalo de la palma, como se muestra.', 78),
  ('ESTIRAMIENTO DEL PULGAR Y DEL LIGAMENTO CARPIANO', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Colocá la otra mano por detrás de la mano que trabajás. Usá el pulgar de atrás para enganchar el pulgar de la mano que trabajás. Tirá hacia abajo para un estiramiento suave, como se muestra.', 87315),
  ('ESTIRAMIENTO EN EXTENSIÓN DE PULGAR - MESA', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Apoyá la mano sobre una mesa con la palma hacia abajo y usá la otra mano para separar suavemente el pulgar de la mano, buscando el estiramiento, como se muestra.', 11221),
  ('ESTIRAMIENTO DE LOS EXTENSORES DEL PULGAR', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el pulgar con los dedos y después flexioná la muñeca hacia abajo, como se muestra, para un estiramiento suave a lo largo del antebrazo.', 11803),
  ('ESTIRAMIENTO EN FLEXIÓN DE PULGAR', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Apoyá la mano afectada sobre una mesa. Usá un dedo de la mano sana para empujar hacia abajo el pulgar afectado y flexionarlo en sus articulaciones, como se muestra. Mantené para un estiramiento suave, relajá y repetí.', 66578),
  ('ESTIRAMIENTO EN EXTENSIÓN DE LA IF DEL PULGAR', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el pulgar afectado por debajo del último nudillo y estiralo suavemente hacia una posición más extendida.', 56),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA IF DEL PULGAR', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el dedo afectado por debajo del nudillo y estiralo suavemente hacia una posición más flexionada.', 57),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA IF Y MCF DEL PULGAR', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Apoyá la mano sobre una mesa de modo que el pulgar quede arriba y el meñique en contacto con la mesa. Usá la otra mano para llevar el pulgar a una posición flexionada y mantené para un estiramiento suave.', 59997),
  ('DISTRACCIÓN ARTICULAR DEL PULGAR - ARTICULACIÓN CMC', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Apoyá el antebrazo sobre la cabeza. Después, con la mano sana, agarrá todo el pulgar incluyendo la parte carnosa de la mano y relajá los hombros para que la gravedad genere un estiramiento en distracción de la articulación CMC del pulgar.', 87663),
  ('ESTIRAMIENTO EN EXTENSIÓN DE LA MCF DEL PULGAR', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el pulgar afectado por debajo del último nudillo y estiralo suavemente hacia una posición más extendida.', 61),
  ('ESTIRAMIENTO EN FLEXIÓN DE LA MCF DEL PULGAR', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá el pulgar afectado en la articulación más cercana y estiralo suavemente hacia una posición más flexionada.', 62),
  ('PROM DE PULGAR - ESTIRAMIENTO EN EXTENSIÓN', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'La persona debe estar completamente relajada mientras el asistente hace todo el trabajo (rango de movimiento pasivo) para mover el pulgar. Sostené la muñeca o la mano de la persona y después aplicá un estiramiento suave llevando el pulgar hacia afuera, como se muestra. Mantené, relajá y repetí.', 27186),
  ('ESTIRAMIENTO DEL ESPACIO INTERDIGITAL DEL PULGAR', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Juntá el espacio interdigital entre el pulgar y el índice de ambas manos, como se muestra.', 87671),
  ('ESTIRAMIENTO DE TRÍCEPS CON SOBREPRESIÓN', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Con el codo afectado flexionado y elevado, usá la otra mano y, con sobrepresión, empujá suavemente el codo afectado hacia atrás, por encima de la cabeza, hasta sentir un estiramiento. Intentá deslizar la mano hacia abajo por la espalda.', 87614),
  ('ESTIRAMIENTO EN DESVIACIÓN CUBITAL', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá la mano y flexionala hacia el lado del meñique, como se muestra.', 80),
  ('ESTIRAMIENTO DEL MOZO - ESTIRAMIENTO DE MILLS', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Parate con los brazos al costado del cuerpo y las palmas mirando hacia atrás. Después, flexioná la muñeca hacia atrás y arriba, como si fueras a agarrar algo por detrás. No flexiones el codo: solo se mueven la muñeca y los dedos.', 50548),
  ('ESTIRAMIENTO DE LA MANO CON UN VASO EN EL ESPACIO INTERDIGITAL', NULL, true, 'activo', 'Codo y mano', 'Estiramientos', 'Conseguí un vaso que tenga el ancho justo para entrar en la mano. Colocá el vaso en la mano, como se muestra, para un estiramiento suave. Sacá el vaso, relajá y después repetí.', 66579),
  ('ESTIRAMIENTO EN EXTENSIÓN DE MUÑECA - SOBRE LA MESA', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Apoyá el antebrazo por fuera del borde de una mesa con la palma hacia arriba. Usá la otra mano para flexionar la muñeca hacia abajo, buscando un estiramiento suave.', 87310),
  ('FLEXIÓN / EXTENSIÓN DE MUÑECA - ROM', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá la mano y movela hacia adelante y atrás mientras flexionás y extendés la muñeca, como se muestra. Repetí.', 174243),
  ('ESTIRAMIENTO EN FLEXIÓN DE MUÑECA - SOBRE LA MESA', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Apoyá el antebrazo por fuera del borde de una mesa con la palma hacia abajo. Usá la otra mano para flexionar la muñeca hacia abajo, buscando un estiramiento suave.', 87311),
  ('ESTIRAMIENTO EN DESVIACIÓN RADIAL DE MUÑECA', NULL, true, 'pasivo', 'Codo y mano', 'Estiramientos', 'Agarrá la mano y flexionala hacia el lado del pulgar, como se muestra.', 74),
  ('DESLIZAMIENTOS DE TALÓN CON FIJACIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Acostado boca arriba con las rodillas flexionadas, deslizá lentamente el talón hacia adelante sobre el piso o la cama y después deslizalo de vuelta. Usá los músculos abdominales para evitar que la columna se mueva.', 252),
  ('PUENTE - EXTENSIÓN ALTERNADA DE RODILLA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Acostado boca arriba, elevá la cola del piso o la cama hasta la posición de puente. Después, elevá y estirá una rodilla de modo que solo la otra pierna sostenga el cuerpo. Después, volvé esa pierna al piso y alterná haciéndolo con la otra pierna. Tratá de mantener la pelvis nivelada todo el tiempo.', 326),
  ('PUENTE - MARCHA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Acostado boca arriba, activá los músculos abdominales bajos, apretá los glúteos y después elevá la cola del piso o la cama formando un puente con el cuerpo. Manteniendo esa posición, elevá una pierna manteniendo la pelvis nivelada. Volvé a apoyarla en el piso y después elevá la pierna contraria.', 18209),
  ('POLEA - CRUNCH ABDOMINAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Colocá la polea en posición alta. Parate o arrodillate de espaldas a la polea, como se muestra. Sostené el accesorio de soga por encima de la cabeza y después flexioná el tronco para enrollar el cuerpo hacia el piso. Subí a la posición inicial y repetí.', 142584),
  ('POLEA - CHOP DE ABAJO HACIA ARRIBA - ROTACIONES DE TRONCO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Colocá la polea en posición baja. Empezá sosteniendo el accesorio de soga con ambas manos. Después, tirá hacia arriba y cruzando el cuerpo hacia el lado contrario mientras rotás la columna. Volvé a la posición inicial y repetí. El tronco y las caderas deben rotar durante este movimiento.', 142540),
  ('POLEA - PALLOF PRESS DE PIE - ANTIRROTACIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Colocá la polea a la altura del hombro y hacia un costado del cuerpo. Parate con los pies un poco más separados que el ancho de los hombros y las rodillas levemente flexionadas. Sostené la manija contra el pecho. Después, extendé lentamente los brazos hacia adelante y después volvé. No dejes que el cuerpo rote durante este ejercicio.', 142542),
  ('POLEA - ROTACIÓN DE TRONCO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Colocá la polea a la altura del hombro y hacia un costado del cuerpo. Parate con los pies un poco más separados que los hombros y las rodillas levemente flexionadas. Sostené la manija con las manos extendidas por delante del cuerpo. Girá hacia el costado mientras rotás el tronco y las caderas. Los brazos deben quedar extendidos por delante del pecho todo el tiempo. Rotá de vuelta a la posición inicial y repetí.', 142546),
  ('POSTURA DEL NIÑO - ESTIRAMIENTO DE REZO - LATERAL', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'En posición de cuatro apoyos, bajá lentamente la cola hacia los pies. Además, bajá el pecho hacia el piso mientras estirás los brazos hacia un costado.', 5267),
  ('BICHO MUERTO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Acostado boca arriba con las rodillas y las caderas flexionadas a 90 grados, usá los músculos abdominales y mantené la pelvis en posición neutra. No dejes que la columna se mueva. Mantené la pelvis neutra y después estirá lentamente una pierna sin tocar el piso. Al mismo tiempo, elevá el brazo contrario por encima de la cabeza. No dejes que la columna se arquee durante el movimiento. Volvé a la posición inicial y después repetí del lado contrario.', 400),
  ('VENDAJE ELÁSTICO - SOPORTE DE ESPALDA - H', NULL, true, 'sin_clasificar', 'Lumbar y torácica', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73840),
  ('VENDAJE ELÁSTICO - ESPALDA BAJA EN H', NULL, true, 'sin_clasificar', 'Lumbar y torácica', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75006),
  ('VENDAJE ELÁSTICO - SOPORTE DE ESPALDA BAJA', NULL, true, 'sin_clasificar', 'Lumbar y torácica', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73832),
  ('PELOTA DE EJERCICIOS - PUENTE EN EL PISO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Acostado en el piso, colocá una pelota de ejercicios debajo de las piernas y después elevá la cola.', 299),
  ('PELOTA DE EJERCICIOS - ESTIRAMIENTO DE ESPALDA SENTADO', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Sentate en una silla con una pelota de ejercicios adelante tuyo. Apoyá las manos sobre la pelota y después inclinate hacia adelante mientras rodás la pelota alejándola del cuerpo, hasta sentir un estiramiento a lo largo de la espalda.', 24197),
  ('PELOTA DE EJERCICIOS - ROTACIÓN DE TRONCO EN DECÚBITO DORSAL', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Acostado boca arriba con una pelota de ejercicios debajo de las piernas, rodá lentamente la pelota de lado a lado para rotar suavemente la espalda.', 306),
  ('RODILLO DE ESPUMA - RODADO DE COLUMNA', NULL, true, 'sin_clasificar', 'Lumbar y torácica', NULL, 'Empezá acostado boca arriba con un rodillo de espuma debajo de la espalda. Apoyá las manos sobre el abdomen y después rodá lentamente hacia adelante y atrás a lo largo de la espalda usando las piernas, como se muestra.', 493),
  ('RODILLO DE ESPUMA - EXTENSIÓN DE TRONCO', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Empezá acostado boca arriba con un rodillo de espuma debajo de la espalda. Después colocá las manos detrás del cuello o cruzadas sobre el pecho. Después extendé lentamente la columna sobre el rodillo.', 492),
  ('MASAJE DE COLUMNA CON RODILLO DE ESPUMA - DE PIE', NULL, true, 'sin_clasificar', 'Lumbar y torácica', NULL, 'Parate con un rodillo de espuma detrás de la espalda. Hacé lentamente medias sentadillas y dejá que el rodillo suba y baje por la espalda para un automasaje.', 15322),
  ('DISCOS DESLIZANTES - ABDOMINAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Empezá arrodillado, apoyado sobre los brazos con los codos estirados y discos deslizantes debajo de cada mano, como se muestra. Después, deslizá ambas manos y discos hacia adelante manteniendo la espalda y los codos estirados. Dejá que las caderas se extiendan mientras bajás hacia el piso. Después, deslizá los discos de vuelta a la posición inicial.', 43356),
  ('DISCOS DESLIZANTES - PIKES', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Colocá discos deslizantes debajo de cada pie y empezá en posición de plancha con las manos y los pies en contacto con el piso, boca abajo. Después, deslizá ambos pies hacia adelante mientras dejás que las caderas se flexionen. La cola debe quedar bien alta. Después bajá de nuevo a la posición de plancha. Mantené las rodillas estiradas todo el tiempo.', 43358),
  ('DISCOS DESLIZANTES - RODILLAS AL PECHO EN PLANCHA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Colocá discos deslizantes debajo de cada pie y empezá en posición de plancha con las manos y los pies en contacto con el piso, boca abajo. Después, deslizá ambos pies hacia adelante mientras flexionás las rodillas y las llevás hacia el pecho. Desde esa posición, estirá las piernas de vuelta a la plancha inicial y repetí.', 43374),
  ('BISAGRA DE CADERA - DE SENTADO A PARADO CON BASTÓN', NULL, true, 'activo_asistido; fortalecimiento', 'Lumbar y torácica', NULL, 'Sentate en el borde de una silla y sostené un bastón o palo a lo largo de la espalda, con una mano en la zona lumbar/rabadilla y la otra detrás de la cabeza/cuello. Sentate bien erguido con buena postura mientras te inclinás hacia adelante y después te parás. Después, volvé a la posición sentada y repetí. Mantené el contacto del bastón y de las manos con la zona lumbar/rabadilla, la espalda alta y la cabeza/cuello todo el tiempo.', 65795),
  ('BISAGRA DE CADERA - DE PIE CON BASTÓN', NULL, true, 'activo_asistido', 'Lumbar y torácica', NULL, 'Parate y sostené un bastón o palo a lo largo de la espalda, con una mano en la zona lumbar/rabadilla y la otra detrás de la cabeza/cuello. Con las rodillas levemente flexionadas, inclinate hacia adelante y después volvé a la posición inicial. Repetí. Mantené el contacto del bastón y de las manos con la zona lumbar/rabadilla, la espalda alta y la cabeza/cuello todo el tiempo.', 65799),
  ('ROTACIONES CON KETTLEBELL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Sosteniendo una kettlebell a la altura del pecho, activá el core y rotá rápidamente el cuerpo. Las rotaciones se hacen desde las caderas y la columna.', 28627),
  ('PLANCHA LATERAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Acostado de costado, elevá el cuerpo apoyándote sobre el codo y los pies. Tratá de mantener la columna derecha.', 278),
  ('DESPLAZAMIENTO PÉLVICO DE PIE - PARED', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Parado al lado de una pared, apoyá el codo y el antebrazo sobre la pared. Colocá la mano del lado opuesto sobre la cadera, como se muestra. Después, llevá las caderas hacia la pared dejando que la pelvis se desplace hacia el costado para un estiramiento suave.', 447),
  ('DECÚBITO VENTRAL SOBRE ALMOHADAS', NULL, true, 'pasivo', 'Lumbar y torácica', NULL, 'Acostate boca abajo con 2 o 3 almohadas debajo del abdomen. Relajate en esta posición.', 11212),
  ('EXTENSIONES EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Acostado boca abajo, empujate lentamente hacia arriba y arqueá la espalda usando los brazos.', 336),
  ('TRACCIÓN EN DECÚBITO VENTRAL - TIRONES CON ANTEBRAZOS', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Acostate boca abajo. Después flexioná los codos y apoyá los antebrazos en el piso. Después, tirá de los antebrazos hacia abajo, en dirección a los pies. Esto descomprime la columna. No tires tan fuerte como para mover la mitad inferior del cuerpo. Solo la mitad superior debe moverse levemente.', 69316),
  ('ESTIRAMIENTO ROTACIONAL DEL CUADRADO LUMBAR', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Acostado boca arriba, cruzá una pierna sobre la rodilla, como se muestra. Después, bajá lentamente las rodillas hacia el piso, hacia el lado de la pierna que quedó arriba.', 17389),
  ('ESTIRAMIENTO LUMBAR SENTADO - ESTIRAMIENTO EN FLEXIÓN DE TRONCO', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Sentado en una silla, empezá inclinándote lentamente hacia adelante y llevá las manos hacia el piso. Flexioná el tronco y la cabeza hacia adelante y abajo. Mantené, después volvé a la posición inicial y repetí.', 347),
  ('ROTACIÓN DE TRONCO EN DECÚBITO LATERAL', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Acostado de costado con los brazos extendidos por delante del cuerpo, girá lentamente la parte superior del cuerpo hacia el costado y rotá la columna. Los brazos y la cabeza también deben rotar junto con la columna, como se muestra. Seguí la mano con la mirada.', 6732),
  ('UNA RODILLA AL PECHO - SKTC', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Acostado boca arriba, agarrate la rodilla y tirá suavemente de ella hacia el pecho.', 68189),
  ('SENTADILLA CON BISAGRA DE CADERA - EJERCICIO DE DISOCIACIÓN DE CADERA Y ESPALDA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', NULL, 'Al hacer sentadilla, inclinate desde la cintura, activá los músculos abdominales metiendo el ombligo hacia adentro y mantené la espalda derecha mientras flexionás desde las caderas. Esto protege la espalda de cargas excesivas. La cola debe bajar por detrás de los pies, como si te fueras a sentar en una silla. Enfatizá que el peso pase por los talones. Además, para una buena alineación de la rodilla, no dejes que las rodillas pasen por delante de los dedos del pie y mantené la rodilla alineada con el 2do dedo (el que está al lado del dedo gordo) al flexionar.', 38390),
  ('EXTENSIONES DE PIE', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Empezá parado y colocá las manos sobre las caderas, con los pulgares apoyados en la zona lumbar. Inclinate hacia atrás para arquear la espalda y después volvé a la posición inicial. Usá los pulgares para ayudarte a aislar el punto donde querés flexionar.', 352),
  ('TRACCIÓN DE PIE', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Parate frente a una mesa u otra superficie plana y estable donde puedas apoyar la mano y descargar el peso del cuerpo. Sostenete con los brazos mientras flexionás lenta y suavemente las rodillas para sacarle peso a la columna.', 11213),
  ('ROTACIÓN TORÁCICA - CUATRO APOYOS', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'En posición de gateo, bajá un poco la cola hacia los pies para quedar en una posición más baja, como se muestra. Después, con una mano detrás de la cabeza, rotá el cuerpo y la cabeza hacia el costado, y volvé.', 10688),
  ('EXTENSIÓN DE TRONCO - TOALLA - AROM - MOVILIZACIÓN', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Sentado en una silla, extendé la columna torácica hacia atrás sobre una toalla enrollada apoyada contra el respaldo.', 351),
  ('SUSPENSIÓN TRX - CURLS DE ISQUIOTIBIALES EN DECÚBITO DORSAL', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Sentate en el piso mirando hacia el anclaje del TRX y colocá las cintas en los talones. Una vez sujeto, acostate con las rodillas estiradas y elevá la cola del piso. Mantené esta posición y después flexioná las rodillas haciendo un curl de isquiotibiales. Repetí manteniendo la cola despegada del piso.', 32690),
  ('ROTACIONES DE TRONCO SUPERIOR - UTR', NULL, true, 'activo', 'Lumbar y torácica', NULL, 'Sentado en una silla, cruzá los brazos sobre el pecho y después rotá la parte superior del cuerpo de lado a lado.', 290),
  ('PIERNAS CRUZADAS - ROTACIÓN DE TRONCO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo)', 'Acostado boca arriba, cruzá las piernas y después rotalas de lado a lado. La pelvis debe elevarse con cada rotación.', 6040),
  ('GERIÁTRICO - ROTACIONES DE TRONCO SUPERIOR SENTADO - UTR', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo)', 'Sentado en una silla, cruzá los brazos por delante o sobre el pecho y después rotá la parte superior del cuerpo hacia un lado y después hacia el otro, y repetí.', 124533),
  ('BISAGRA DE CADERA - SENTADO CON BASTÓN', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'AROM (activo)', 'Sentate en el borde de una silla y sostené un bastón o palo a lo largo de la espalda, con una mano en la zona lumbar/rabadilla y la otra detrás de la cabeza/cuello. Sentate bien erguido con buena postura mientras te inclinás hacia adelante y después volvé a la posición erguida. Mantené el contacto del bastón y de las manos con la zona lumbar/rabadilla, la espalda alta y la cabeza/cuello todo el tiempo.', 65746),
  ('INCLINACIÓN HACIA ADELANTE CON BISAGRA DE CADERA - EJERCICIO DE DISOCIACIÓN DE CADERA Y ESPALDA', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo)', 'Al inclinarte hacia adelante, flexioná desde la cintura, activá los músculos abdominales metiendo el ombligo hacia adentro y mantené la espalda derecha mientras flexionás desde las caderas. Esto protege la espalda de cargas excesivas. La cola debe bajar por detrás de los pies, como si te fueras a sentar en una silla. Enfatizá que el peso pase por los talones. Además, para una buena alineación de la rodilla, no dejes que las rodillas pasen por delante de los dedos del pie y mantené la rodilla alineada con el 2do dedo (el que está al lado del dedo gordo) al flexionar.', 39435),
  ('BÁSCULA PÉLVICA - LATERAL - SENTADO - PELOTA DE EJERCICIOS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo)', 'Sentate sobre una pelota de ejercicios grande. Después, inclina la pelvis de lado a lado. La pelvis debe bajar de un lado mientras sube del otro. Hacelo de un lado y después del otro, y repetí. Movete dentro de un rango de movimiento cómodo.', 310),
  ('BISAGRA DE CADERA EN CUATRO APOYOS - EJERCICIO DE DISOCIACIÓN', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo)', 'Empezá en posición de gateo con los hombros sobre las manos y las caderas sobre las rodillas. Después, activá los músculos abdominales metiendo el ombligo hacia adentro y bajá la cola hacia los pies. Mientras bajás la cola, mantené la espalda derecha y flexioná desde las caderas.', 39443),
  ('ROTACIONES DE TRONCO SUPERIOR SENTADO CON MANCUERNAS - UTR', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo)', 'Sentado en una silla, sostené pesos libres cerca del pecho con los codos flexionados. Después, rotá el tronco hacia un lado y después hacia el otro, y repetí.', 163681),
  ('ROTACIÓN TORÁCICA - CUATRO APOYOS - 2', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo)', 'En posición de gateo, bajá un poco la cola hacia los pies para quedar en una posición más baja, como se muestra. Después, con una mano detrás de la espalda, rotá el cuerpo y la cabeza hacia el costado, y volvé.', 10689),
  ('ESTIRAMIENTO EN ROTACIÓN DE TRONCO - SENTADO - CADERAS ABIERTAS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo)', 'Sentate en una silla, erguido y con buena postura. Colocá las piernas separadas y las manos sobre las rodillas. Rotá el tronco y la cabeza hacia un lado para un estiramiento suave y mantené. Después hacelo del otro lado. Repetí.', 177020),
  ('INCLINACIÓN LATERAL DE TRONCO - AROM', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo)', 'Empezá sentado en una silla con los brazos elevados y los codos flexionados, como se muestra. Después, inclinate hacia el costado moviendo los brazos, la cabeza y los hombros como una sola unidad. Inclinate hacia un lado y después hacia el otro, y repetí.', 66804),
  ('PELOTA DE EJERCICIOS - ARCO Y FLECHA', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota', 'Empezá sentado sobre una pelota de ejercicios. Imaginate que tirás hacia atrás con un arco y flecha. Llevá un brazo hacia atrás dejando que el codo se flexione de ese lado y seguilo con la cabeza, como se muestra. Asegurate de rotar el cuerpo durante el movimiento. Volvé a la posición inicial y seguí alternando de lado a lado.', 174799),
  ('PELOTA DE EJERCICIOS - GOLPES CRUZADOS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota', 'Sentado sobre una pelota de ejercicios, rotá la parte superior del cuerpo mientras extendés el brazo hacia adelante y cruzando por delante del cuerpo, como si dieras un golpe, como se muestra. Repetí el movimiento alternando de lado a lado. Usá movimientos controlados y suaves.', 174804),
  ('PELOTA DE EJERCICIOS - ROTACIONES DE TRONCO SENTADO - MANCUERNA', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Pelota', 'Sentado sobre una pelota de ejercicios, sostené una mancuerna con los brazos estirados y elevados por delante del cuerpo. Rotá la parte superior del cuerpo hacia un lado mientras seguís las manos con la cabeza, como se muestra. Rotá hacia el otro lado y repetí.', 174805),
  ('PELOTA DE EJERCICIOS - ROTACIONES DE TRONCO SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota', 'Sentado sobre una pelota de ejercicios, entrelazá las manos con los brazos estirados y elevados por delante del cuerpo. Rotá la parte superior del cuerpo hacia un lado mientras seguís las manos con la cabeza, como se muestra. Rotá hacia el otro lado y repetí.', 174803),
  ('PELOTA DE EJERCICIOS - ROTACIONES DE TRONCO SUPERIOR SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota', 'Sentado sobre una pelota de ejercicios, cruzá los brazos sobre el pecho y después rotá el cuerpo de lado a lado.', 174800),
  ('EMBARAZO - PELOTA DE EJERCICIOS - ROTACIONES DE TRONCO SUPERIOR SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota', 'Sentate sobre una pelota de ejercicios con los pies bien separados. Cruzá los brazos sobre el pecho y después rotá el cuerpo de lado a lado.', 180447),
  ('EMBARAZO - BÁSCULA PÉLVICA LATERAL - SENTADO - PELOTA DE EJERCICIOS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota', 'Sentate sobre una pelota de ejercicios grande con los pies bien separados. Después, inclina la pelvis de lado a lado. La pelvis debe bajar de un lado mientras sube del otro. Hacelo alternando de izquierda a derecha. Movete dentro de un rango de movimiento cómodo.', 180451),
  ('ROTACIONES DE TRONCO CON PELOTA - SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota', 'Empezá sentado en una silla y elevá una pelota de ejercicios por delante del cuerpo con los codos extendidos. Después, rotá lentamente el tronco hacia un lado y después hacia el otro, y repetí.', 67490),
  ('EMBARAZO - PELOTA DE EJERCICIOS - ARCO Y FLECHA', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota; Estabilización', 'Empezá sentado sobre una pelota de ejercicios con los pies bien separados. Imaginate que tirás hacia atrás con un arco y flecha. Llevá un brazo hacia atrás dejando que el codo se flexione de ese lado y seguilo con la cabeza, como se muestra. Asegurate de rotar el cuerpo durante el movimiento. Volvé a la posición inicial y seguí alternando de lado a lado.', 180448),
  ('EMBARAZO - PELOTA DE EJERCICIOS - GOLPES CRUZADOS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota; Estabilización', 'Sentado sobre una pelota de ejercicios, rotá la parte superior del cuerpo mientras extendés el brazo hacia adelante y cruzando por delante del cuerpo, como un golpe, como se muestra. Repetí el movimiento alternando de lado a lado. Usá movimientos controlados y suaves.', 180449),
  ('EMBARAZO - BÁSCULAS PÉLVICAS - SENTADO - PELOTA DE EJERCICIOS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota; Estabilización', 'Sentate sobre una pelota de ejercicios grande y apoyá las manos sobre la pelvis. Después, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo.', 180446),
  ('PELOTA DE EJERCICIOS - ESTIRAMIENTO EN INCLINACIÓN LATERAL SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota; Estiramientos', 'Empezá sentado erguido y con buena postura sobre una pelota de ejercicios. Inclina el tronco hacia el costado mientras deslizás la mano por el costado de la pelota. No te inclines hacia adelante ni hacia atrás. Tratá de mover la columna derecho hacia el costado. Mantené para un estiramiento suave y después volvé a la postura erguida.', 174801),
  ('EMBARAZO - PELOTA - RODADOS PÉLVICOS SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota; Estiramientos', 'Sentado sobre una pelota de ejercicios, movés la pelvis en un patrón circular. Hacelo de forma suave y en las dos direcciones. Mantené las rodillas separadas para dejar lugar a la panza.', 180898),
  ('EMBARAZO - PELOTA DE EJERCICIOS - BÁSCULA PÉLVICA CON RODADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota; Estiramientos', 'Arrodillate con una pelota de ejercicios adelante tuyo. Tenés que estar flexionado desde las caderas y con los codos apoyados sobre la pelota, como se muestra. Arqueá y aplaná la espalda para un estiramiento suave.', 180901),
  ('EMBARAZO - PELOTA DE EJERCICIOS - ESTIRAMIENTO EN INCLINACIÓN LATERAL SENTADO - BILATERAL', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Pelota; Estiramientos', 'Empezá sentado erguido y con buena postura sobre una pelota de ejercicios. Inclina el tronco hacia el costado mientras deslizás la mano por el costado de la pelota. No te inclines hacia adelante ni hacia atrás. Tratá de mover la columna derecho hacia el costado. Mantené para un estiramiento suave, después volvé a la postura erguida y repetí del otro lado.', 180897),
  ('BOSU INVERTIDO - RODADOS PÉLVICOS SENTADO', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Bosu', 'Sentado sobre un Bosu invertido, movés la pelvis en un patrón circular. Hacelo de forma suave y en las dos direcciones.', 5776),
  ('ROTACIÓN LUMBAR EN DECÚBITO DORSAL CON BANDA ELÁSTICA', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Banda elástica; Estabilización', 'Empezá acostado boca arriba con una banda elástica rodeando las rodillas o los muslos. La otra punta de la banda debe estar fijada hacia el costado del cuerpo. Después, girá la parte inferior del cuerpo hacia el costado con movimientos lentos y controlados. El tronco debe rotar y la pelvis debe despegarse del piso durante el ejercicio.', 545),
  ('ROTACIÓN EN POSTURA DE GOLF', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Varios', 'En una postura correcta de golf, sostené un palo de golf cruzado sobre el pecho, como se muestra. Después, rotá el tronco y las caderas como si hicieras un swing de golf.', 18699),
  ('INCLINACIÓN LATERAL EN POSTURA DE GOLF', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Varios', 'En una postura correcta de golf, sostené un palo de golf cruzado sobre el pecho, como se muestra. Después, inclina el cuerpo hacia el costado y después volvé a la posición original. Después hacelo del otro lado.', 18700),
  ('BISAGRA DE CADERA - ROTACIONES DE PIE CON BASTÓN', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'AROM (activo); Varios', 'Parate y sostené un bastón o palo a lo largo de la espalda, con una mano en la zona lumbar/rabadilla y la otra detrás de la cabeza/cuello. Flexioná levemente las rodillas y después inclinate hacia adelante. Después, rotá el tronco de lado a lado. Repetí las rotaciones de tronco en esa posición. Mantené el contacto del bastón y de las manos con la zona lumbar/rabadilla, la espalda alta y la cabeza/cuello todo el tiempo.', 65800),
  ('INCLINACIÓN HACIA ADELANTE CON EJERCICIO DE DISOCIACIÓN DE CADERA Y ESPALDA - PRINCIPIANTE', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Varios', 'Al inclinarte desde la cintura, activá los músculos abdominales metiendo el ombligo hacia adentro y mantené la espalda derecha mientras flexionás desde las caderas. Esto protege la espalda de cargas excesivas. Al principio, agarrate de una silla o mesa con un brazo para sostenerte. La cola debe ir hacia atrás. Dejá que las rodillas se flexionen un poco.', 39433),
  ('INCLINACIÓN CON ALCANCE - EJERCICIO DE DISOCIACIÓN DE CADERA Y ESPALDA - SILLA COMO GUÍA', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Varios', 'Al inclinarte desde la cintura, activá los músculos abdominales metiendo el ombligo hacia adentro y mantené la espalda derecha mientras flexionás desde las caderas. Esto protege la espalda de cargas excesivas. Estirá un brazo hacia adelante mientras te inclinás. La cola debe ir hacia atrás. No dejes que las rodillas pasen por delante de los dedos del pie. Colocá una silla adelante tuyo para ayudar a evitar que las rodillas se adelanten a los dedos.', 39434),
  ('EXTENSIONES EN DECÚBITO VENTRAL CON SÁBANA', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Varios; Movilización; Estiramientos', 'Colocá una sábana a lo largo de la zona lumbar y apoyá las manos sobre ella a ambos lados del cuerpo, como se muestra. Después, empujate lentamente hacia arriba y arqueá la espalda usando los brazos. Volvé a la posición acostada y repetí.', 66805),
  ('ROTACIONES DE TRONCO CON BASTÓN', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'AROM (activo); Varios; Movilización; Estiramientos', 'Parate con un bastón, palo de golf o vara detrás del cuello y por encima de los hombros, como se muestra. Después, con los pies bien apoyados en el piso, rotá y girá el cuerpo de lado a lado.', 75981),
  ('ROTACIÓN TORÁCICA - DECÚBITO VENTRAL', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Movilización', 'Acostate boca abajo apoyado sobre los codos. Después, con una mano detrás de la cabeza, rotá el cuerpo y la cabeza hacia el costado, y volvé.', 10690),
  ('ROTACIÓN TORÁCICA - DECÚBITO VENTRAL 2', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Movilización', 'Acostate boca abajo apoyado sobre los codos. Después, con una mano detrás de la espalda, rotá el cuerpo y la cabeza hacia el costado, y volvé.', 10691),
  ('EXTENSIÓN DE TRONCO - AROM', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Movilización', 'Sentado en una silla con buena postura, colocá las manos detrás de la base de la cabeza. Empezá elevando el pecho, los brazos y la cabeza como una sola unidad. Volvé a la posición inicial y repetí.', 66780),
  ('EXTENSIÓN DE TRONCO - SILLA - AROM - MOVILIZACIÓN', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Movilización', 'Empezá sentado en una silla con los brazos cruzados sobre el pecho. Después, elevá los codos mientras extendés la columna torácica contra el respaldo de la silla. Volvé a la posición inicial y repetí.', 66781),
  ('EXTENSIÓN TORÁCICA - CODOS SOBRE LA SILLA', NULL, true, 'pasivo; activo_asistido', 'Lumbar y torácica', 'AROM (activo); Movilización; Estiramientos', 'Arrodillate sobre una almohada frente a una silla o mesa baja. Sostené una vara, bastón o palo de golf con ambas manos, con las palmas hacia arriba. Apoyá los codos sobre la silla con los codos flexionados. Después, echate hacia atrás llevando la cola hacia los pies mientras dejás que las caderas se flexionen y la columna se extienda, para un estiramiento suave de la espalda alta. Volvé a la posición inicial y repetí.', 75983),
  ('EXTENSIÓN Y ROTACIÓN DE TRONCO - AROM', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Movilización; Estiramientos', 'Sentado en una silla, cruzá los brazos sobre el pecho y rotá suavemente hacia el costado, extendiendo hacia atrás por encima del respaldo de la silla.', 401),
  ('ELEVACIÓN DE CADERA - DECÚBITO DORSAL', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Empezá acostado boca arriba con las manos apoyadas sobre la pelvis, con la pelvis en posición neutra (nivelada). Después, elevá la pelvis de un lado mientras empujás hacia abajo del otro lado. Las piernas deben deslizarse sobre la colchoneta en direcciones opuestas durante el movimiento. Después, llevá la pelvis de vuelta a la posición inicial (pelvis nivelada) y repetí del otro lado. Seguí con este movimiento alternado.', 149062),
  ('ELEVACIÓN DE PIERNAS CON TORSO APOYADO - EXTENSIÓN LUMBAR', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostate boca abajo sobre una silla con las piernas por fuera del borde. Agarrate de las patas de la silla y después elevá las piernas con las rodillas estiradas.', 39686),
  ('RELOJ PÉLVICO 6 Y 12', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostate boca arriba en posición relajada, con las rodillas flexionadas y los pies apoyados en el piso, separados aproximadamente al ancho de la pelvis. Después, imaginate un reloj sobre la zona del abdomen y la pelvis. Bascula la pelvis de modo que el reloj se incline hacia las 12 (retroversión) y la zona lumbar se apoye firme contra el piso. Después invertí la dirección y bascula la pelvis de modo que el reloj imaginario se incline hacia las 6 (anteversión) y se saque la presión de la zona lumbar contra el piso. Puede quedar algo de espacio debajo de la zona lumbar al final del rango. Apoyá los pulgares sobre la parte de adelante del hueso pélvico (EIAS) para sentir el movimiento. Durante el ejercicio la pelvis rueda hacia adelante (anteversión) y hacia atrás (retroversión). Repetí con movimientos suaves y controlados.', 67580),
  ('RELOJ PÉLVICO A LAS 6 - ANTEVERSIÓN PÉLVICA', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostate boca arriba en posición relajada, con las rodillas flexionadas y los pies apoyados en el piso, separados aproximadamente al ancho de la pelvis. Después, imaginate un reloj sobre la zona del abdomen y la pelvis. Bascula la pelvis de modo que el reloj se incline hacia las 6 (anteversión) y se saque la presión de la zona lumbar contra el piso. Puede quedar algo de espacio debajo de la zona lumbar al final del rango. Apoyá los pulgares sobre la parte de adelante del hueso pélvico (EIAS) para sentir el movimiento. Durante el ejercicio la pelvis rueda hacia adelante (anteversión) y después vuelve a una posición relajada. Repetí con movimientos suaves y controlados.', 67644),
  ('BÁSCULA PÉLVICA - MEDIA RODILLA', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Arrodillate con una rodilla sobre una almohada y el otro pie apoyado en el piso. Esta es la posición de media rodilla. En esa posición, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo. Después, hacé el ejercicio arrodillado sobre la otra rodilla, en posición de media rodilla.', 40934),
  ('BÁSCULA PÉLVICA - ISOMÉTRICO DE FLEXIÓN DE CADERA', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostate boca arriba con las rodillas flexionadas. Después, presioná la zona lumbar contra la camilla o colchoneta mientras aplanás la espalda baja. La pelvis debe bascular hacia atrás durante el movimiento. Movete solamente dentro de un rango cómodo. Manteniendo esa posición de la columna, elevá una rodilla y presionala contra la mano.', 85340),
  ('BÁSCULA PÉLVICA - ARRODILLADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Colocá almohadas en el piso y arrodillate sobre ellas. Después, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo.', 39680),
  ('BÁSCULA PÉLVICA - DECÚBITO VENTRAL', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostate boca abajo con almohadas debajo del abdomen. Después, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo.', 39681),
  ('BÁSCULA PÉLVICA - DECÚBITO LATERAL', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostado de costado, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo.', 40935),
  ('BÁSCULA PÉLVICA - DE PIE', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'En posición de pie, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo.', 40576),
  ('RETROVERSIÓN PÉLVICA - CUATRO APOYOS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Empezá en posición de gateo con los hombros sobre las manos y las caderas sobre las rodillas. Después, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo.', 39444),
  ('EMBARAZO - HIDRANTE - ABDUCCIÓN DE CADERA EN CUATRO APOYOS', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Empezá en posición de gateo con las rodillas bien separadas (para dejar lugar a la panza). Elevá la pierna hacia el costado, como se muestra. Mantené la espalda alta y media derecha.', 179245),
  ('EMBARAZO - BÁSCULA PÉLVICA - ARRODILLADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Arrodillate sobre almohadas o una colchoneta de ejercicios. Después, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo.', 179624),
  ('EMBARAZO - BÁSCULA PÉLVICA - DE PIE', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'En posición de pie, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo. Encontrá la posición intermedia que se sienta mejor dentro de ese rango (pelvis neutra) y mantené esa posición durante el día, al estar parado y al caminar.', 179622),
  ('EMBARAZO - BÁSCULA PÉLVICA - DECÚBITO DORSAL', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostate boca arriba con las rodillas flexionadas y la cabeza sobre una almohada. Después, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo.', 179623),
  ('CRUNCH INVERTIDO SENTADO', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Sentate en una silla y después elevá ambas rodillas, como se muestra. Bajá y repetí. Dejá que la pelvis se mueva un poco hacia adelante y atrás para activar los músculos abdominales.', 70019),
  ('ELEVACIÓN DE TORSO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostate boca abajo con una almohada debajo del abdomen. Después, despegá la cabeza y el esternón de la camilla, cama o piso. Después volvé a la posición inicial. Mantené el cuello en posición neutra, con el mentón levemente metido, todo el tiempo.', 39578),
  ('EXTENSIÓN DE ESPALDA ALTA 1', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostado boca abajo con la parte superior del cuerpo colgando por el borde de la cama o camilla, elevá lentamente la cabeza y el pecho hacia arriba, como se muestra. Mantené los brazos colgando derecho hacia el piso.', 407),
  ('EXTENSIÓN DE ESPALDA ALTA 2', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostado boca abajo con la parte superior del cuerpo colgando por el borde de la cama o camilla, elevá lentamente la cabeza y el pecho hacia arriba, como se muestra. Mantené las manos entrelazadas detrás del cuello.', 408),
  ('EXTENSIÓN DE ESPALDA ALTA 3', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostado boca abajo con la parte superior del cuerpo colgando por el borde de la cama o camilla, elevá lentamente la cabeza, el pecho y los brazos hacia arriba, como se muestra.', 409),
  ('LIMPIAPARABRISAS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estabilización', 'Acostate boca arriba con las rodillas flexionadas. Después, estirá una rodilla y elevá la pierna en el aire hasta unos 90 grados de flexión de cadera. Después, elevá la otra pierna. Manteniendo las piernas arriba, rotá desde la columna para dejar que las piernas bajen hacia un costado. Volvé con las piernas derecho hacia arriba y después bajalas hacia el otro lado. Repetí alternando de lado a lado.', 67958),
  ('ESTIRAMIENTO DEL GATO ENOJADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'En posición de gateo, llevá la columna hacia arriba para arquear la espalda.', 246),
  ('ESTIRAMIENTO DEL GATO ENOJADO A NEUTRO', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'En cuatro apoyos, en posición de gateo, elevá la espalda y arqueala hacia el techo como un gato enojado. Después volvé a una posición neutra o de espalda plana. Repetí.', 81354),
  ('BILATERAL - POSTURA DEL GUERRERO CON ALCANCE LATERAL - SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Empezá sentado en una silla con los brazos elevados hacia los costados y las piernas separadas. Extendé una pierna y elevá el brazo del mismo lado hacia el techo mientras te inclinás hacia el lado contrario, para un estiramiento suave. Mantené esta posición con postura erguida, relajá y después repetí el estiramiento en inclinación lateral del lado opuesto.', 177809),
  ('ESTIRAMIENTO DEL CAMELLO A NEUTRO', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'En cuatro apoyos, en posición de gateo, bajá la espalda hacia abajo. Después volvé a una posición neutra o de espalda plana. Repetí.', 81355),
  ('ROTACIÓN CERVICOTORÁCICA Y ESTIRAMIENTO DE ISQUIOTIBIALES - SENTADO LARGO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Empezá sentado en el piso con las rodillas estiradas. Después, estirate hacia adelante cruzando los brazos e intentá agarrarte los dedos del pie, como se muestra. Soltá los dedos con una mano y estirá el brazo hacia arriba y atrás mientras rotás la columna media y el cuello. Seguí la mano con la mirada. Volvé a la posición inicial y alterná los brazos. Repetí.', 159906),
  ('EMBARAZO - ROTACIÓN DE TRONCO EN DECÚBITO LATERAL - LIMPIAPARABRISAS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Empezá acostado de costado con los brazos extendidos por delante del cuerpo y girá lentamente la parte superior del cuerpo hacia el costado, rotando la columna. Los brazos y la cabeza también deben rotar junto con la columna, como se muestra. Seguí la mano con la mirada. Volvé a la posición inicial y repetí.', 180010),
  ('EMBARAZO - GATO Y CAMELLO', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'En cuatro apoyos, en posición de gateo, elevá la espalda y arqueala hacia el techo como un gato enojado. Después bajá y arqueá la espalda en la dirección contraria.', 179244),
  ('EMBARAZO - BÁSCULA PÉLVICA - SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'En posición sentada, arqueá la zona lumbar y después aplanala, repetidamente. La pelvis debe bascular hacia adelante y atrás durante el movimiento. Movete dentro de un rango de movimiento cómodo. Encontrá la posición intermedia que se sienta mejor dentro de ese rango (pelvis neutra) y mantené esa posición durante el día, al estar parado y al caminar.', 180009),
  ('EMBARAZO - BÁSCULAS PÉLVICAS - DECÚBITO LATERAL', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Acostate de costado y después arqueá y aplaná la zona lumbar, repitiendo el movimiento. Movete dentro de un rango de movimiento cómodo.', 180008),
  ('EMBARAZO - ESTIRAMIENTO LATERAL DE TRONCO EN CUATRO APOYOS', NULL, true, 'activo; fortalecimiento', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'En cuatro apoyos, en posición de gateo, inclina el tronco y la cabeza hacia un lado hasta sentir un estiramiento. Mantené, volvé a la posición inicial y después repetí del lado opuesto.', 180006),
  ('EMBARAZO - ENHEBRAR LA AGUJA - CUATRO APOYOS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Empezá en posición de gateo con las rodillas separadas para dejar lugar a la panza. Bajá el pecho y la cabeza hacia el piso mientras pasás un brazo por debajo y cruzando el pecho, rotando la columna. Seguí la mano con la mirada. Mantené, volvé a la posición inicial y después repetí del lado opuesto.', 180007),
  ('SENTADO - GATO Y CAMELLO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Sentado en una silla con las manos sobre los muslos, inclinate hacia adelante y encorvate creando una curva en la espalda. Después, elevá la cabeza mientras enderezás y activás los músculos de la espalda. Volvé a la posición inicial y repetí.', 171051),
  ('SENTADO - ESTIRAMIENTO EN ROTACIÓN DE COLUMNA', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Empezá sentado erguido en una silla con una pierna cruzada sobre la otra. Apoyá la mano por detrás tuyo para ayudarte a rotar la espalda y el cuello, como si miraras por encima del hombro. Mantené, volvé a la posición inicial y repetí.', 177482),
  ('TRONCO SENTADO - FLEXIÓN - EXTENSIÓN', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Empezá en posición sentada con las manos detrás del cuello y la mirada al frente. Después, inclina el torso hacia adelante flexionando la espalda. Después, enderezá la espalda y extendela elevando los brazos lo más alto posible. Volvé a la posición inicial y repetí.', 79194),
  ('FLEXIÓN DE TRONCO SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'En posición sentada, cruzá los brazos sobre el pecho y enrollá lentamente la espalda hacia adelante para redondear la espalda alta.', 350),
  ('ROTACIÓN DE TRONCO EN DECÚBITO LATERAL - MODIFICADA', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Acostado de costado con las rodillas flexionadas, girá lentamente la parte superior del cuerpo hacia el costado y rotá la columna.', 287),
  ('EXTENSIÓN LUMBAR DE PIE - DEDOS ÍNDICE', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Parate con las manos en la espalda y los dedos índice hacia abajo, a la altura de la columna donde querés enfocar el movimiento o el estiramiento. Después, inclinate hacia atrás y extendé la columna a la altura de los dedos índice. Volvé a la posición erguida y repetí.', 70022),
  ('EXTENSIONES LUMBARES DE PIE - MESADA', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Parate con los pies separados al ancho de los hombros mientras te agarrás de una mesada. Empujá la pelvis hacia adelante mientras llevás los hombros hacia atrás, hasta sentir un estiramiento en la zona lumbar y media de la espalda. Volvé a la posición inicial y repetí.', 165455),
  ('ESTIRAMIENTO EN INCLINACIÓN LATERAL DE PIE', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Empezá en posición de pie. Después, inclina el tronco hacia el costado mientras deslizás la mano por el costado de las piernas. No te inclines hacia adelante ni hacia atrás. Tratá de mover la columna derecho hacia el costado. Mantené para un estiramiento suave, después volvé a la posición erguida y repetí.', 68053),
  ('ESTIRAMIENTO EN INCLINACIÓN LATERAL DE PIE - BILATERAL', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Empezá en posición de pie. Después, inclina el tronco hacia el costado mientras deslizás la mano por el costado de las piernas. No te inclines hacia adelante ni hacia atrás. Tratá de mover la columna derecho hacia el costado. Mantené para un estiramiento suave, después volvé a la posición erguida y alterná para hacerlo del otro lado.', 68052),
  ('ENHEBRAR LA AGUJA - CUATRO APOYOS', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Empezá en posición de gateo. Bajá el pecho y la cabeza hacia el piso mientras pasás un brazo por debajo y cruzando el pecho, rotando la columna. Seguí la mano con la mirada. Mantené, volvé a la posición inicial y repetí.', 160178),
  ('FLEXIÓN Y ROTACIÓN DE TRONCO - AROM', NULL, true, 'activo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Sentado en una silla, cruzá los brazos sobre el pecho y rotá suavemente hacia el costado mientras flexionás el tronco hacia adelante.', 403),
  ('ESTIRAMIENTO EN ROTACIÓN DE TRONCO', NULL, true, 'pasivo', 'Lumbar y torácica', 'AROM (activo); Estiramientos', 'Empezá acostado boca arriba con las rodillas flexionadas. Después, dejá caer lentamente las rodillas hacia el costado mientras rotás desde la columna, para un estiramiento suave.', 24216),
  ('PELOTA MANÍ - ESTIRAMIENTO EN DECÚBITO VENTRAL - TRACCIÓN', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota', 'Acostate boca abajo con una pelota maní debajo de la pelvis y el abdomen. Relajá completamente el cuerpo en esta posición.', 61515),
  ('CRUNCH INVERTIDO SENTADO - PELOTA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota', 'Sentate en una silla con una pelota apretada entre las rodillas y después elevá ambas rodillas, como se muestra. Bajá y repetí. Dejá que la pelvis se mueva hacia adelante y atrás para activar los músculos abdominales.', 177251),
  ('BICHO MUERTO SOBRE PELOTA CON EXTENSIÓN DE BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Banda elástica; Estabilización', 'Acostado en el piso con una pelota de ejercicios debajo de las piernas, elevá una pierna mientras tirás de una banda elástica hacia abajo. Mantené la zona lumbar plana contra el piso todo el tiempo.', 395),
  ('ROTACIÓN SOBRE PELOTA - BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Banda elástica; Estabilización', 'Sentate sobre una pelota de ejercicios y sostené una banda elástica con los brazos extendidos por delante del pecho. La otra punta de la banda debe estar fijada hacia el costado, como se muestra. Después, manteniendo los pies bien apoyados en el piso, rotá el cuerpo hacia un lado. Después rotá en la dirección contraria y repetí. Los brazos deben estar extendidos y por delante del pecho todo el tiempo.', 20638),
  ('PELOTA DE EJERCICIOS - PLANCHA CON BANDA CIRCULAR EN RE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Banda elástica; Estabilización', 'Arrodillate en el piso con una pelota de ejercicios adelante tuyo y apoyá los codos y antebrazos sobre la pelota, como se muestra. Colocá una banda elástica circular alrededor de las muñecas y separá un poco los brazos manteniendo esa tensión. Después, elevá las rodillas y el cuerpo hasta la posición de plancha. No dejes que las caderas ni la pelvis caigan de ningún lado. Mantené la tensión de la banda en los brazos mientras hacés el ejercicio. Mantené, relajá, volvé con las rodillas al piso y después repetí.', 8395),
  ('AUTOMASAJE CON DOBLE PELOTA (MANÍ) - COLUMNA LUMBAR - MÚSCULOS PARAVERTEBRALES', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Movilización', 'Colocá una doble pelota de lacrosse o 2 pelotas de tenis o paleta pegadas entre una pared y la zona lumbar, como se muestra. Inclinate contra la pelota para aplicar presión suave sobre las zonas tensas. No pases la pelota sobre zonas óseas. Podés mantener la presión en una zona o flexionar y estirar las rodillas para rodar la doble pelota hacia arriba y abajo por la columna.', 99549),
  ('AUTOMASAJE CON DOBLE PELOTA (MANÍ) - ESPALDA MEDIA - INTERESCAPULAR - TRAPECIO MEDIO', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Movilización', 'Colocá una doble pelota de lacrosse o 2 pelotas de tenis o paleta pegadas entre una pared y la zona entre los omóplatos. Inclinate contra la pelota para aplicar presión suave sobre las zonas tensas. No pases la pelota sobre zonas óseas. Podés mantener la presión en una zona o flexionar y estirar las rodillas para rodar la doble pelota hacia arriba y abajo por la columna.', 99552),
  ('AUTOMASAJE CON DOBLE PELOTA (MANÍ) - COLUMNA TORÁCICA - MÚSCULOS PARAVERTEBRALES', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Movilización', 'Colocá una doble pelota de lacrosse o 2 pelotas de tenis o paleta pegadas entre una pared y la espalda media, como se muestra. Inclinate contra la pelota para aplicar presión suave sobre las zonas tensas. No pases la pelota sobre zonas óseas. Podés mantener la presión en una zona o flexionar y estirar las rodillas para rodar la doble pelota hacia arriba y abajo por la columna.', 99550),
  ('AUTOMOVILIZACIÓN - COLUMNA TORÁCICA - PELOTA MANÍ - DOBLE PELOTA', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Pelota; Movilización', 'Acostate boca arriba. Colocá una doble pelota de lacrosse o 2 pelotas de tenis o paleta pegadas en la espalda media. No sobre zonas óseas. Cruzá los brazos y después hacé movimientos chicos sobre la pelota maní. Podés subir y bajar sobre la pelota o hacer movimientos chicos de lado a lado.', 99653),
  ('PELOTA DE EJERCICIOS - ESTIRAMIENTO EN EXTENSIÓN DE ESPALDA - AVANZADO', NULL, true, 'pasivo', 'Lumbar y torácica', 'Pelota; Movilización; Estiramientos', 'Sentado sobre una pelota de ejercicios, rodá hacia adelante de modo que la espalda quede apoyada contra la pelota. Después, elevá los brazos por encima de la cabeza y hacia el piso. Tenés que quedar acostado horizontalmente con los pies en contacto con el piso. Relajate y estirate.', 323),
  ('PELOTA DE EJERCICIOS - ESTIRAMIENTO EN DECÚBITO VENTRAL - TRACCIÓN', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Movilización; Estiramientos', 'Arrodillate frente a una pelota de ejercicios. Rodá hacia adelante sobre la pelota de modo que quede debajo de la pelvis y el abdomen. Relajá completamente el cuerpo en esta posición.', 312),
  ('PELOTA - PUENTE CON PIES A 90', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá acostado boca arriba con una pelota de ejercicios a la altura de los pies. Apoyá los pies sobre la pelota con las rodillas flexionadas a unos 90 grados. Después, activá los músculos abdominales, apretá los glúteos y presioná los talones contra la pelota mientras elevás la pelvis del piso. Volvé a la posición inicial y repetí.', 68975),
  ('PELOTA ANTIRROTACIÓN - BANDA ELÁSTICA - PALLOF', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Sentate sobre una pelota de ejercicios y sostené una banda elástica con los brazos cerca del pecho. La otra punta de la banda debe estar fijada hacia el costado, como se muestra. Después, manteniendo los pies bien apoyados en el piso, extendé los codos para empujar la banda hacia adelante por delante del cuerpo hasta que los codos queden completamente estirados. Mantené y después flexioná los codos para volver a la posición inicial. Mantené el core activado y estable todo el tiempo. No dejes que el cuerpo rote, se incline ni se desplace.', 20637),
  ('PELOTA - RANA - AVANZADO', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Equilibrate sobre una pelota de ejercicios usando brazos y piernas mientras abrazás la pelota. Mantené el equilibrio sobre la pelota.', 420),
  ('PELOTA - EQUILIBRIO ARRODILLADO - AVANZADO', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Mantené el equilibrio sobre una pelota de ejercicios estando arrodillado sobre ella.', 463),
  ('PELOTA - FLEXIÓN DE HOMBROS SENTADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Sentate sobre una pelota de ejercicios sosteniendo las puntas de una banda elástica con ambas manos. Colocá los omóplatos hacia abajo y atrás y mantené esa posición. Después, subí los brazos con los codos estirados hasta quedar por encima de la cabeza. Después, bajá los brazos a la posición inicial y repetí.', 399),
  ('PELOTA DE EJERCICIOS - EXTENSIONES DE ESPALDA', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Arrodillado con una pelota de ejercicios adelante tuyo, apoyá el pecho sobre la pelota. Después, elevá lentamente el pecho despegándolo de la pelota. Mantené el contacto de la pelota con la zona de la pelvis.', 291),
  ('PELOTA DE EJERCICIOS - PUENTE CON ESPALDA ALTA - UNA PIERNA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá sentado sobre la pelota. Después, caminá lentamente con los pies hacia adelante de modo que la pelota quede en la espalda alta. Mantené la cola y la pelvis despegadas de la pelota y alineadas con los muslos. Después, elevá una pierna y volvé a apoyarla en el piso. Cambiá de lado, elevá la otra pierna y volvé a apoyarla. Alterná y repetí.', 293),
  ('PELOTA DE EJERCICIOS - CRUNCH - MANTENER Y ROTAR', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado en el piso sosteniendo una pelota de ejercicios, hacé un crunch y rotá el cuerpo mientras llevás la pelota hacia el costado. Volvé a la posición original y después repetí del otro lado.', 303),
  ('PELOTA DE EJERCICIOS - CRUNCHS NIVEL 1', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Sentado sobre una pelota de ejercicios, caminá hacia adelante de modo que la espalda quede apoyada contra la pelota. Apoyá las manos sobre los muslos y después usá los músculos abdominales para despegar la espalda alta de la pelota. Tratá de subir lo suficiente para que los omóplatos se despeguen de la pelota (no subas más que eso). Bajá la espalda alta sobre la pelota otra vez y repetí.', 296),
  ('PELOTA DE EJERCICIOS - CRUNCHS NIVEL 2', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Sentado sobre una pelota de ejercicios, caminá hacia adelante de modo que la espalda quede apoyada contra la pelota. Cruzá los brazos sobre el pecho y después usá los músculos abdominales para despegar la espalda alta de la pelota. Tratá de subir lo suficiente para que los omóplatos se despeguen de la pelota (no subas más que eso). Bajá la espalda alta sobre la pelota otra vez y repetí.', 540),
  ('PELOTA DE EJERCICIOS - CRUNCHS NIVEL 3', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Sentado sobre una pelota de ejercicios, caminá hacia adelante de modo que la espalda quede apoyada contra la pelota. Entrelazá las manos detrás de las orejas y después usá los músculos abdominales para despegar la espalda alta de la pelota. Tratá de subir lo suficiente para que los omóplatos se despeguen de la pelota (no subas más que eso). Bajá la espalda alta sobre la pelota otra vez y repetí.', 541),
  ('PELOTA DE EJERCICIOS - PUENTE EN EL PISO CON ELEVACIÓN ALTERNADA DE PIERNA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado en el piso, colocá una pelota de ejercicios debajo de las piernas y después elevá la cola. Manteniendo esa posición, elevá una pierna despegándola de la pelota hacia el techo y después bajala de nuevo a la pelota. Alterná con la otra pierna y repetí.', 300),
  ('PELOTA DE EJERCICIOS - ESTOCADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá en posición de pie sosteniendo una pelota contra el pecho. Dá un paso adelante en estocada mientras extendés los brazos hacia adelante alejando la pelota del pecho. Las rodillas deben quedar alineadas con los dedos del pie y no pasarlos. Volvé a la posición inicial y repetí.', 307),
  ('PELOTA DE EJERCICIOS - PLANCHA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Arrodillado en el piso con una pelota de ejercicios adelante tuyo, usá las manos y los antebrazos para rodar la pelota hacia adelante y apoyar los codos y las manos sobre ella, con los pies en el piso. Después, elevá el cuerpo y mantené esta posición. Tratá de mantener la columna derecha. No dejes que las caderas ni la pelvis caigan de ningún lado.', 8393),
  ('PELOTA DE EJERCICIOS - DECÚBITO VENTRAL CON BRAZO ALTERNADO', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado boca abajo sobre una pelota, sostenete con los pies y las manos. Después, elevá lentamente un brazo. Volvé con el brazo al piso y después elevá el otro brazo.', 314),
  ('PELOTA DE EJERCICIOS - DECÚBITO VENTRAL CON PIERNA ALTERNADA', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado boca abajo sobre una pelota, sostenete con los brazos y las piernas. Después elevá lentamente una pierna. Volvé con la pierna al piso y después elevá la otra pierna.', 316),
  ('PELOTA DE EJERCICIOS - RODADO EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Arrodillate con una pelota de ejercicios adelante tuyo. Tenés que estar flexionado desde las caderas y con los codos apoyados sobre la pelota. Después, inclinate lentamente hacia adelante y dejá que la pelota ruede hacia adelante por los brazos mientras mantenés la columna firme y neutra. Por último, rodá la pelota de vuelta a la posición inicial usando los brazos y el tronco, y repetí.', 497),
  ('PELOTA DE EJERCICIOS - CRUNCHS INVERTIDOS', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado en el piso, colocá una pelota de ejercicios debajo de las piernas de modo que puedas agarrarla con las piernas al flexionar las rodillas. Después, levantá la pelota con las piernas y llevá las rodillas hacia el pecho. Volvé lentamente al piso y repetí.', 318),
  ('PELOTA DE EJERCICIOS - PRESS ALTERNADO POR ENCIMA DE LA CABEZA SENTADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Sentado sobre una pelota de ejercicios, activá los músculos abdominales y después elevá un brazo por encima de la cabeza. Bajá el brazo y después elevá el otro. Tratá de mantener la pelvis y la columna estables todo el tiempo.', 166987),
  ('PELOTA DE EJERCICIOS - SUPERMAN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado boca abajo sobre una pelota, estirá las rodillas y elevá los brazos para formar una línea recta del tronco alineada con los brazos y las piernas.', 317),
  ('SOSTÉN CON PELOTA DE EJERCICIOS - TOCAR LAS RODILLAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá acostado en el piso con las rodillas flexionadas y sosteniendo una pelota por encima de la cabeza. Después, contraé los músculos abdominales y hacé un crunch mientras elevás la pelota hacia el techo. Al mismo tiempo, elevá las rodillas y las caderas para tocar las rodillas con la pelota. Volvé lentamente a la posición original y repetí.', 294),
  ('RODADO CON PELOTA DE EJERCICIOS - CRUNCH', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá acostado boca arriba con una pelota de ejercicios sobre la panza. Usá los músculos abdominales para despegar la cabeza y la espalda alta del piso, de modo que los omóplatos se despeguen. La pelota debe rodar por los muslos hacia las rodillas durante la fase de subida. Después, volvé a la posición inicial bajando la cabeza y la espalda alta al piso, dejando que la pelota ruede por los muslos hacia la panza. Repetí.', 558),
  ('BALÓN MEDICINAL - CRUNCH - POR ENCIMA DE LA CABEZA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá acostado boca arriba con las rodillas flexionadas y sosteniendo un balón medicinal por encima de la cabeza. Después, hacé un crunch de modo que los omóplatos se despeguen del piso, manteniendo el balón por encima de la cabeza todo el tiempo.', 6238),
  ('BALÓN MEDICINAL - ROTACIONES DE TRONCO 90/90', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá sosteniendo firmemente un balón medicinal entre las rodillas, acostado boca arriba con las piernas en posición de MESA, como se muestra. Las caderas y las rodillas deben estar flexionadas a 90 grados. Balanceá la pelvis y las rodillas de lado a lado. No dejes que la espalda se arquee hacia arriba durante el ejercicio.', 6234),
  ('BALÓN MEDICINAL - CÍRCULOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'De pie sosteniendo un balón medicinal por delante tuyo, movés el balón rápido en un patrón circular. Hacé varias repeticiones en una dirección y después en la otra. Tratá de mantener la columna quieta y estable todo el tiempo.', 6237),
  ('BALÓN MEDICINAL - CRUNCH - PECHO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado boca arriba y sosteniendo un balón medicinal a la altura del pecho, elevá el tronco de modo que los omóplatos se despeguen del piso. Después volvé lentamente a la posición inicial.', 6244),
  ('BALÓN MEDICINAL - CRUNCH CON ELEVACIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá acostado boca arriba sosteniendo un balón medicinal estirado hacia el techo con los codos estirados. Después, elevá el tronco de modo que los omóplatos se despeguen del piso. Mantené los codos estirados y dejá que el balón suba hacia el techo. Volvé a la posición inicial.', 6245),
  ('BALÓN MEDICINAL - CHOP EN SENTADILLA BAJA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá sosteniendo un balón medicinal abajo, a la altura del tobillo, en posición de sentadilla, como se muestra. Después, volvé a la posición de pie mientras elevás el balón hacia arriba y en diagonal hacia el hombro contrario. Repetí del otro lado.', 6239),
  ('BALÓN MEDICINAL - PLANCHA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Sostenete en posición de flexión de brazos, como se muestra, con ambas manos sobre un balón medicinal.', 6241),
  ('BALÓN MEDICINAL - ROTACIONES', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'De pie sosteniendo un balón medicinal por delante tuyo, rotá el tronco hacia el costado y después volvé rápido a la posición de frente.', 6243),
  ('BALÓN MEDICINAL - ABDOMINALES CON ROTACIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Hacé abdominales sosteniendo un balón medicinal. Arriba del movimiento, rotá el tronco hacia el costado y después volvé a mirar al frente.', 6246),
  ('BALÓN MEDICINAL - CHOP EN SENTADILLA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá sosteniendo un balón medicinal abajo, a la altura de la rodilla, en posición de sentadilla, como se muestra. Después, volvé a la posición de pie mientras elevás el balón en diagonal hacia el hombro contrario. Repetí del otro lado.', 6240),
  ('BALÓN MEDICINAL - V', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'De pie sosteniendo un balón medicinal por delante tuyo, movés el balón rápido en un patrón de V, como se muestra. El balón debe subir y bajar y después ir al otro lado, repetidamente. Tratá de mantener la columna quieta y estable todo el tiempo.', 6550),
  ('CRUNCH CON BALÓN MEDICINAL - 90/90', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá acostado boca arriba con las piernas en posición de MESA, como se muestra. Las caderas y las rodillas deben estar flexionadas a 90 grados. Colocá un balón medicinal sobre los tobillos. Después, llevá la parte superior del cuerpo hacia adelante en un crunch, de modo que los omóplatos se despeguen del piso. No dejes que la zona lumbar se arquee hacia arriba en todo el ejercicio. Además, las piernas tienen que quedar en posición 90-90 todo el tiempo.', 6233),
  ('PELOTA MANÍ - EXTENSIÓN DE ESPALDA', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá acostado sobre una pelota maní a la altura de la panza y con las puntas de los pies en el piso. Cruzá los brazos y elevá la parte superior del cuerpo, como se muestra. Volvé a la posición inicial y repetí.', 61502),
  ('PELOTA MANÍ - CRUNCH', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá sentado sobre una pelota maní de modo que la espalda quede apoyada contra la pelota. Después, cruzá los brazos sobre el pecho y llevá el pecho hacia arriba para hacer un abdominal parcial. Tratá de despegar los omóplatos de la pelota. Volvé a la posición inicial y repetí.', 61489),
  ('PELOTA MANÍ - CRUNCH OBLICUOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá sentado sobre una pelota maní de modo que la espalda quede apoyada contra la pelota. Después, cruzá los brazos sobre el pecho y llevá el pecho hacia arriba y hacia el costado para hacer un abdominal parcial en diagonal. Tratá de despegar el omóplato de la pelota. En la siguiente repetición, subí hacia el lado contrario y seguí alternando de derecha a izquierda.', 61503),
  ('PELOTA MANÍ - CRUNCH SOBRE LOS MUSLOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado boca arriba con una pelota maní sobre la panza, hacé un crunch de modo que los omóplatos se despeguen del piso y la pelota maní ruede por los muslos.', 61488),
  ('PELOTA MANÍ - PUENTE EN EL PISO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado en el piso, colocá una pelota maní debajo de las piernas y después elevá la cola.', 61491),
  ('PELOTA MANÍ - PUENTE EN EL PISO CON ELEVACIÓN ALTERNADA DE PIERNA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado en el piso, colocá una pelota maní debajo de las piernas y después elevá la cola. Mantené la pelvis nivelada. Manteniendo esa posición, elevá una pierna despegándola de la pelota maní hacia el techo y después bajala de nuevo a la pelota; alterná para elevar la otra pierna.', 61490),
  ('PELOTA MANÍ - PUENTE CON PIES A 90', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá acostado boca arriba con una pelota maní a la altura de los pies. Apoyá los pies sobre la pelota maní con las rodillas flexionadas a unos 90 grados. Después, activá los músculos abdominales, apretá los glúteos y presioná los talones contra la pelota mientras elevás la pelvis del piso. Volvé a la posición inicial y repetí.', 61487),
  ('PELOTA MANÍ - PLANCHA LATERAL CON ADUCCIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostate de costado con una pelota maní entre los tobillos. Apretá la pelota maní con las piernas y, apoyado sobre el codo, elevá la pelvis y el tronco del piso. Mantené, bajá y repetí.', 61499),
  ('PELOTA MANÍ - INCLINACIÓN LATERAL DE TRONCO', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá acostado de costado con una pelota maní debajo del costado del tronco. Después, apoyá la mano de abajo sobre la cabeza y la otra mano a lo largo del costado del cuerpo. Elevá la parte superior del cuerpo hacia el costado mientras deslizás la mano de arriba por la pierna, como se muestra. Volvé a la posición inicial y repetí.', 61517),
  ('PELOTA MANÍ - PLANCHA MODIFICADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Arrodillado en el piso con una pelota maní adelante tuyo, usá las manos y los antebrazos para rodar la pelota hacia adelante y apoyar los codos y las manos sobre ella, con las rodillas en el piso. Tratá de mantener la columna derecha. No dejes que las caderas ni la pelvis caigan de ningún lado.', 61507),
  ('PELOTA MANÍ - PLANCHA CON PIERNA ALTERNADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Arrodillado en el piso con una pelota maní adelante tuyo, usá las manos y los antebrazos para rodar la pelota hacia adelante y apoyar los codos y las manos sobre ella, con los pies en el piso. Después, elevá el cuerpo y mantené esta posición. Tratá de mantener la columna derecha. No dejes que las caderas ni la pelvis caigan de ningún lado. Manteniendo esa posición, elevá una pierna del piso y después apoyala. Después elevá la otra pierna y apoyala. Repetí.', 61505),
  ('PELOTA MANÍ - PLANCHA CON MARCHA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Arrodillado en el piso con una pelota maní adelante tuyo, usá las manos y los antebrazos para rodar la pelota hacia adelante y apoyar los codos y las manos sobre ella, con los pies en el piso. Después, elevá el cuerpo y mantené esta posición. Tratá de mantener la columna derecha. No dejes que las caderas ni la pelvis caigan de ningún lado. Manteniendo esa posición, flexioná una rodilla hacia el pecho, después estirala y apoyala de nuevo en el piso. Después hacelo con la otra pierna y repetí.', 61506),
  ('PELOTA MANÍ - CUATRO APOYOS CON BRAZO Y PIERNA CONTRARIOS', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostate boca abajo sobre una pelota maní. Apoyá los codos y antebrazos en el piso junto con los pies y las rodillas. Después, elevá un brazo y la pierna contraria del piso, como se muestra. Bajá y hacelo con los lados opuestos. Mantené la columna derecha y la pelvis estable todo el tiempo.', 61510),
  ('PELOTA MANÍ - EQUILIBRIO EN CUATRO APOYOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Mantené el equilibrio en posición de gateo sobre una pelota maní, como se muestra.', 61511),
  ('PELOTA MANÍ - CRUNCHS INVERTIDOS', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Acostado en el piso, colocá una pelota maní debajo de las piernas de modo que puedas agarrarla con las piernas al flexionar las rodillas. Después, levantá la pelota con las piernas y llevá las rodillas hacia el pecho. Volvé lentamente al piso y repetí.', 61512),
  ('PELOTA MANÍ - RECLINADO - BÁSCULA PÉLVICA', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Sentate en el piso con una pelota maní detrás tuyo. Usá las piernas y rodá hacia atrás sobre la pelota maní de modo que la espalda quede en contacto con la pelota y la cola despegada del piso. Después, rodá la pelvis hacia arriba como en un empuje pélvico o báscula pélvica. La pelvis debe bascular hacia arriba y hacia abajo durante el movimiento. Movete dentro de un rango cómodo.', 61504),
  ('EXTENSIÓN SOBRE PELOTA EN DECÚBITO VENTRAL - RETRACCIÓN ESCAPULAR', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá acostado boca abajo sobre una pelota de ejercicios. Apoyá las manos al lado de las orejas con los codos apuntando hacia el piso, como se muestra. Elevá la cabeza y la parte superior del cuerpo mientras elevás los codos hacia el costado y arriba, en dirección al techo. Volvé a la posición inicial y repetí.', 174644),
  ('NADO EN DECÚBITO VENTRAL - PELOTA DE EJERCICIOS', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá en posición arrodillada con una pelota de ejercicios adelante tuyo. Después, rodá hacia adelante de modo que quedes boca abajo sobre la pelota, con los pies en el piso y la panza sobre la pelota. Sostené la cabeza y el pecho de modo que exista una línea recta entre los pies y la cabeza. Después, elevá un brazo hacia arriba y adelante mientras llevás el otro brazo hacia atrás, al costado del cuerpo, como en un movimiento de nado.', 38420),
  ('SUPERMAN - NIVEL 1 - PELOTA DE EJERCICIOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá en posición arrodillada con una pelota de ejercicios adelante tuyo. Después, rodá hacia adelante de modo que quedes boca abajo sobre la pelota, con los pies en el piso y la panza sobre la pelota. Apoyate sobre los codos y sostené la cabeza y el pecho de modo que exista una línea recta entre los pies y la cabeza. Mantené esta posición. Volvé a la posición inicial y repetí.', 38417),
  ('SUPERMAN - NIVEL 2 - PELOTA DE EJERCICIOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá en posición arrodillada con una pelota de ejercicios adelante tuyo. Después, rodá hacia adelante de modo que quedes boca abajo sobre la pelota, con los pies en el piso y la panza sobre la pelota. Sostené la cabeza y el pecho de modo que exista una línea recta entre los pies y la cabeza. Además, llevá los brazos hacia atrás, al costado del cuerpo, como se muestra, y mantené esta posición.', 38418),
  ('SUPERMAN - NIVEL 3 - PELOTA DE EJERCICIOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Pelota; Estabilización', 'Empezá en posición arrodillada con una pelota de ejercicios adelante tuyo. Después, rodá hacia adelante de modo que quedes boca abajo sobre la pelota, con los pies en el piso y la panza sobre la pelota. Sostené la cabeza y el pecho de modo que exista una línea recta entre los pies y la cabeza. Además, llevá los brazos hacia arriba y adelante, como se muestra, y mantené esta posición.', 38419),
  ('PELOTA DE EJERCICIOS - ESTIRAMIENTO DE PLEGARIA LATERAL', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estiramientos', 'Empezá arrodillado en el piso con una pelota de ejercicios adelante tuyo. Con las manos sobre la pelota, rodala hacia adelante de modo que el tronco se incline hacia adelante y hacia el costado, hasta sentir un estiramiento suave a lo largo del costado del cuerpo.', 304),
  ('PELOTA DE EJERCICIOS - ESTIRAMIENTO DE PLEGARIA', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estiramientos', 'Arrodillado con una pelota de ejercicios adelante tuyo, inclinate lentamente hacia adelante y rodá la pelota hacia adelante hasta sentir un estiramiento.', 313),
  ('PELOTA DE EJERCICIOS - ESTIRAMIENTO DE ISQUIOTIBIALES SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estiramientos', 'Sentado sobre una pelota de ejercicios, estirá una pierna hacia adelante de modo que el talón toque el piso y la rodilla quede estirada. Después, inclinate suavemente hacia adelante hasta sentir un estiramiento por detrás de la rodilla y la pierna.', 320),
  ('PELOTA DE EJERCICIOS - ESTIRAMIENTO EN INCLINACIÓN LATERAL SENTADO - BILATERAL', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estiramientos', 'Empezá sentado erguido y con buena postura sobre una pelota de ejercicios. Inclina el tronco hacia el costado mientras deslizás la mano por el costado de la pelota. No te inclines hacia adelante ni hacia atrás. Tratá de mover la columna derecho hacia el costado. Mantené para un estiramiento suave, después volvé a la postura erguida y repetí del otro lado.', 175088),
  ('PELOTA MANÍ - ESTIRAMIENTO EN EXTENSIÓN DE ESPALDA', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estiramientos', 'Sentate en el piso con una pelota maní apoyada en la espalda. Después, caminá con los pies hacia atrás hasta que la pelota maní quede en la zona lumbar. Después, elevá los brazos por encima de la cabeza y hacia el piso. Tenés que quedar acostado horizontalmente con los pies en contacto con el piso. Relajá el cuerpo para estirar la espalda.', 61516),
  ('PELOTA MANÍ - ESTIRAMIENTO DE DORSAL ANCHO', NULL, true, 'pasivo', 'Lumbar y torácica', 'Pelota; Estiramientos', 'Empezá arrodillado frente a una pelota maní. Sostenela en posición vertical, como se muestra, con el brazo que querés estirar agarrando la parte de arriba. Después, dejá que la pelota maní se incline hacia el lado contrario al brazo que trabajás. Inclinate hacia el costado y hacia adelante hasta sentir un estiramiento suave a lo largo del costado y la espalda.', 61500),
  ('PELOTA MANÍ - ESTIRAMIENTO DE PLEGARIA - POSTURA DEL NIÑO', NULL, true, 'activo', 'Lumbar y torácica', 'Pelota; Estiramientos', 'Arrodillate sobre una pelota maní y después estirá los brazos hacia adelante para tocar el piso. Bajá lentamente la cola hacia los pies y bajá la cabeza hasta sentir un estiramiento a lo largo de la espalda o la cola.', 61508),
  ('BOSU - BRAZO Y PIERNA ALTERNADOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostate boca abajo sobre una pelota Bosu, apoyado en la panza. Elevá lentamente un brazo y la pierna contraria. Bajá el brazo y la pierna al piso y después elevá el brazo y la pierna del lado contrario. Seguí alternando y repetí. Mantené la zona lumbar nivelada. Imaginate un vaso de agua sobre la zona lumbar que no querés voltear.', 167805),
  ('BOSU - CRUNCH CON RODILLA ALTERNADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Sentado en la punta de adelante de una pelota Bosu, recostate hacia atrás y hacé un crunch parcial mientras llevás la rodilla hacia el pecho. El cuerpo tiene que elevarse de modo que el omóplato se despegue del Bosu. Mantené los dedos tocando el costado de la cabeza todo el tiempo.', 167821),
  ('BOSU - BURPEES', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá parado frente a una pelota Bosu invertida. Bajá y hacé una flexión de brazos mientras sostenés los costados del Bosu. Volvé a la posición de pie mientras elevás el Bosu por encima de la cabeza. Volvé a la posición inicial y repetí.', 168819),
  ('BOSU - ESCALADORES CRUZADOS - PIES SOBRE LA PELOTA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá en posición de plancha completa (posición de flexión de brazos) con los pies sobre una pelota Bosu. Manteniendo la posición de plancha, flexioná una rodilla hacia el hombro contrario y después volvé a la posición de plancha. Alterná los lados y repetí.', 168281),
  ('BOSU - ESCALADORES CRUZADOS - MANOS SOBRE LA PELOTA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá en posición de plancha (posición de flexión de brazos) con las manos sobre una pelota Bosu, como se muestra. Manteniendo la posición de plancha, flexioná una rodilla hacia el hombro contrario y después volvé a la posición de plancha. Alterná los lados y repetí. Seguí alternando de lado.', 168282),
  ('BOSU - BICHO MUERTO CON TOQUE DE PUNTA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostate con la espalda sobre la pelota Bosu y las rodillas y caderas flexionadas a 90 grados. Después, usá los músculos abdominales y mantené la posición neutra de la pelvis. No dejes que la columna se mueva. Elevá y sostené los brazos hacia el techo. Mantené la pelvis neutra y después bajá lentamente una pierna y tocá el piso con la punta del pie. No dejes que la columna se arquee durante este movimiento. Volvé a la posición inicial y después hacelo del lado contrario. Repetí alternando los lados.', 168547),
  ('BOSU - PLANCHA SOBRE CODOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostado boca abajo, elevá el cuerpo con los codos sobre la pelota Bosu para hacer una plancha. Mantené la columna derecha. Sostené, bajá y repetí.', 168549),
  ('BOSU - FLEXIÓN LATERAL DE TRONCO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostate de costado de modo que el Bosu quede en contacto con el costado del tronco. Separá las piernas de modo que la pierna de arriba quede adelante y la de abajo atrás. Después, bajá y elevá lentamente la parte superior del cuerpo, como se muestra.', 5729),
  ('BOSU - ROTACIÓN DE TRONCO INFERIOR SIN APOYO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá sentado sobre un Bosu. Después, elevá ambas rodillas de modo que los pies se despeguen del piso. Después, rotá la mitad inferior del cuerpo de lado a lado, como se muestra.', 5770),
  ('BOSU - CRUNCH CON BALÓN MEDICINAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Sosteniendo un balón medicinal, sentate con la espalda sobre la pelota Bosu. Las rodillas deben estar flexionadas con los pies apoyados en el piso. Manteniendo el balón medicinal por encima de la cabeza, usá los músculos abdominales para hacer un crunch, como se muestra. Volvé a la posición inicial y repetí.', 167985),
  ('BOSU - ESCALADORES', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá en posición de plancha completa (posición de flexión de brazos) con las manos sobre una pelota Bosu. Manteniendo la posición de plancha, flexioná una rodilla hacia el pecho y después volvé a la posición de plancha. Alterná los lados y repetí. Mantené la columna derecha todo el tiempo.', 168545),
  ('BOSU - ESCALADORES - PIES SOBRE LA PELOTA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá en posición de plancha completa (posición de flexión de brazos) con los pies sobre una pelota Bosu. Manteniendo la posición de plancha, flexioná una rodilla hacia el pecho y después volvé a la posición de plancha. Alterná los lados y repetí.', 168280),
  ('BOSU - CRUNCH PARCIAL OBLICUOS 1', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Sentado en la punta de adelante de una pelota Bosu, subí y hacé un crunch parcial mientras llevás las manos hacia la rodilla contraria. Volvé a la posición inicial, alterná los lados y repetí.', 167818),
  ('BOSU - CRUNCH PARCIAL OBLICUOS 2', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostate boca arriba arriba de una pelota Bosu con los brazos cruzados sobre el pecho. Hacé un crunch parcial mientras rotás hacia un lado, llevando el codo hacia el muslo contrario, como se muestra. Volvé a la posición inicial y repetí rotando hacia el lado contrario. Repetí alternando los lados en cada repetición.', 167989),
  ('BOSU - CRUNCH PARCIAL OBLICUOS 3', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostate boca arriba arriba de una pelota Bosu con los dedos al costado de la cabeza. Hacé un crunch parcial mientras rotás hacia un lado, llevando el codo hacia el muslo contrario, como se muestra. Volvé a la posición inicial y repetí rotando hacia el lado contrario. Repetí alternando los lados en cada repetición. El cuerpo tiene que elevarse de modo que el omóplato se despegue del Bosu. Mantené los dedos tocando el costado de la cabeza todo el tiempo.', 167990),
  ('BOSU - PLANCHA CON BRAZO Y PIERNA ALTERNADOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Con el Bosu debajo de las puntas de los pies, hacé una plancha. Después, activá los músculos abdominales y elevá lentamente una pierna y el brazo contrario. Bajá la pierna y el brazo y después repetí del lado contrario. Mantené la pelvis y la columna niveladas y estables todo el tiempo.', 159107),
  ('BOSU - PLANCHA MODIFICADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostado boca abajo, elevá el cuerpo apoyado sobre las rodillas con los codos sobre el Bosu. Mantené la columna derecha.', 168546),
  ('BOSU - CUATRO APOYOS CON PIERNA ALTERNADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá en posición de gateo, sobre manos y rodillas, con las rodillas arriba de una pelota Bosu. Después, elevá un brazo. Volvé a la posición original y después repetí del otro lado. Mantené la pelvis estable todo el tiempo. No dejes que las caderas ni la pelvis caigan.', 6678),
  ('BOSU - CRUNCH INVERTIDO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Sentate arriba de una pelota Bosu. Empezá inclinándote hacia atrás y estirando las piernas hacia adelante. Después, elevá las rodillas hacia el pecho mientras hacés un crunch abdominal. Bajá a la posición inicial y repetí. Mantené las manos a los costados del Bosu para equilibrarte.', 167988),
  ('BOSU - CRUNCH INVERTIDO A MINI-PIKE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostate con la espalda media y baja sobre la pelota Bosu y las piernas estiradas hacia el techo. Manteniendo los hombros apoyados en el piso y usando solo los músculos abdominales, contraé el abdomen para elevar las piernas y la zona lumbar del Bosu. Bajá y repetí.', 167986),
  ('BOSU - CRUNCH INVERTIDO A PIKE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostate con la espalda media y baja sobre la pelota Bosu y las piernas estiradas hacia el techo. Manteniendo los hombros apoyados en el piso y usando solo los músculos abdominales, contraé el abdomen para elevar las piernas y la espalda del Bosu. Bajá y repetí.', 167987),
  ('BOSU - ELEVACIÓN LATERAL DE TRONCO INVERTIDA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá acostado de costado sobre un Bosu. Después, apoyate sobre el codo y elevá las piernas, como se muestra.', 5785),
  ('BOSU - ALCANCE CON ROTACIÓN - PLANCHA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá en posición de plancha (posición de flexión de brazos) con ambas manos sobre la pelota Bosu. Elevá un brazo hacia el costado y por encima de la cabeza mientras rotás la columna, siguiendo la mano con la mirada. Bajá la mano y el brazo y después hacelo del otro lado. Seguí alternando de lado. Mantené el core firme con la espalda derecha, sin dejar que se hunda ni se arquee hacia arriba.', 167801),
  ('BOSU - MARCHA SENTADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Sentado sobre un Bosu, elevá lentamente un pie del piso. Volvé y después elevá el del lado contrario. Tratá de mantener el equilibrio sobre el Bosu.', 6844),
  ('BOSU - PUENTE A UNA PIERNA - FIGURA 4', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá acostado boca arriba con ambos pies sobre el Bosu. Apoyá el tobillo sobre el muslo contrario. Después, elevá la cola del piso y hacé un puente. Bajá la cola al piso. Repetí.', 159109),
  ('BOSU - ABDOMINAL - B', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Sentado sobre un Bosu, cruzá los brazos sobre el pecho y hacé un abdominal parcial, como se muestra.', 6980),
  ('BOSU - ABDOMINAL - C', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Sentado sobre un Bosu, tocate la parte de atrás de la cabeza con ambas manos y hacé un abdominal parcial, como se muestra.', 5733),
  ('BOSU - EXTENSIÓN DE TRONCO NIVEL 2', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostado boca abajo con la parte superior del cuerpo sobre un Bosu, elevá lentamente la cabeza y el pecho, como se muestra. Mantené los brazos cruzados sobre el pecho mientras lo hacés.', 5736),
  ('PLANCHA EN BOSU - ARRASTRES DE KETTLEBELL POR DEBAJO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá en posición de plancha, como se muestra, con las manos sobre la pelota Bosu. Después, agarrá una kettlebell con un brazo para levantarla y moverla por debajo tuyo hacia el hombro contrario. Apoyala y después repetí moviéndola hacia el lado contrario. Mantené la columna derecha mientras movés la kettlebell.', 168548),
  ('PLANCHA DE PUNTAS EN BOSU - ELEVACIONES ALTERNADAS DE BRAZO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostate boca abajo con los pies sobre el Bosu. Elevá el cuerpo apoyado sobre los codos y las puntas de los pies en posición de plancha modificada, como se muestra. Después, trasladá el peso del cuerpo a un codo y elevá el otro brazo hacia adelante tratando de mantener la columna derecha. Volvé a la posición inicial y después elevá el brazo contrario hacia adelante. Repetí alternando los lados. Tratá de mantener la columna derecha todo el tiempo. No dejes que la zona lumbar se hunda.', 168279),
  ('PLANCHA DE PUNTAS EN BOSU - EXTENSIONES ALTERNADAS DE CADERA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostate boca abajo con los pies sobre la pelota Bosu. Elevá el cuerpo apoyado sobre los codos y las puntas de los pies en posición de plancha, como se muestra. Después, trasladá el peso del cuerpo a una pierna y elevá la otra manteniendo la columna derecha. Volvé a la posición inicial y después elevá la pierna contraria. Repetí alternando los lados. Mantené la columna derecha todo el tiempo. Activá los músculos abdominales para evitar que la zona lumbar se hunda.', 168544),
  ('BOSU INVERTIDO - PUENTE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostate boca arriba con las rodillas flexionadas y los pies apoyados arriba de un Bosu invertido. Después, elevá la cola para hacer un puente. Volvé a la posición inicial y repetí.', 159112),
  ('BOSU INVERTIDO - ESCALADORES', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá en posición de plancha (posición de flexión de brazos) sobre una pelota Bosu invertida. Manteniendo la plancha, flexioná una rodilla hacia el pecho y después volvé a la posición de plancha. Después, alterná los lados y flexioná la otra rodilla hacia el pecho. Volvé a la posición de plancha y repetí este movimiento alternado.', 167817),
  ('BOSU INVERTIDO - PLANCHA MODIFICADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Acostado boca abajo, elevá el cuerpo apoyado sobre las rodillas con los codos sobre el Bosu. Tratá de mantener la columna derecha y el Bosu nivelado.', 5782),
  ('BOSU INVERTIDO - BRAZO Y PIERNA ALTERNADOS SENTADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Sentado sobre un Bosu invertido, elevá un brazo y la pierna contraria. No dejes que la pelvis ni la columna se muevan mientras lo hacés.', 5763),
  ('BOSU INVERTIDO - EQUILIBRIO SENTADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Sentate con las piernas cruzadas sobre un Bosu y mantené el equilibrio.', 5777),
  ('BOSU INVERTIDO - MARCHA SENTADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Sentado sobre un Bosu invertido, elevá lentamente un pie del piso. Volvé y después elevá el del lado contrario. Tratá de mantener el Bosu lo más nivelado posible.', 5774),
  ('BOSU INVERTIDO - PUENTE A UNA PIERNA - FIGURA 4', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización', 'Empezá acostado boca arriba con ambos pies sobre un Bosu invertido. Apoyá el tobillo sobre el muslo contrario. Después, elevá la cola del piso y hacé un puente. Bajá la cola al piso. Repetí.', 159108),
  ('BOSU - GUSANITOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estabilización; Estiramientos', 'Empezá en posición de plancha (posición de flexión de brazos) con los pies centrados sobre la pelota Bosu, como se muestra. Manteniendo las rodillas estiradas, caminá lentamente con las manos hacia los pies. La cola tiene que subir hacia el techo con las rodillas estiradas todo el tiempo. Volvé caminando con las manos hasta la posición de plancha y repetí.', 167803),
  ('BOSU - ESTIRAMIENTO DEL GATO ENOJADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estiramientos', 'En posición de gateo sobre un Bosu, mantené el equilibrio y llevá la columna hacia arriba arqueando la espalda.', 5764),
  ('BOSU - ESTIRAMIENTO LATERAL DE TRONCO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estiramientos', 'Sentado sobre un Bosu, elevá un brazo mientras te inclinás hacia el lado contrario hasta sentir un estiramiento a lo largo del costado del cuerpo.', 5775),
  ('BOSU - ESTIRAMIENTO DE PLEGARIA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estiramientos', 'Arrodillado con un Bosu adelante tuyo, inclinate lentamente hacia adelante hasta sentir un estiramiento a lo largo de la espalda o la cola.', 5772),
  ('BOSU - ESTIRAMIENTO EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estiramientos', 'Acostate boca abajo con un Bosu debajo de la pelvis y la panza. Relajá el cuerpo para sentir una sensación de tracción suave en la espalda.', 5773),
  ('BOSU - ESTIRAMIENTO EN DECÚBITO DORSAL', NULL, true, 'pasivo', 'Lumbar y torácica', 'Bosu; Estiramientos', 'Sentado en el piso frente a un Bosu, recostate lentamente sobre el Bosu. Después, elevá los brazos por encima de la cabeza y hacia el piso. Tenés que quedar acostado horizontalmente con los pies en contacto con el piso. Relajate y estirate.', 5779),
  ('BOSU INVERTIDO - ESTIRAMIENTO DE PLEGARIA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Bosu; Estiramientos', 'Arrodillado con un Bosu adelante tuyo, inclinate lentamente hacia adelante hasta sentir un estiramiento a lo largo de la espalda o la cola.', 5783),
  ('CLX - EXTENSIÓN DE TRONCO SENTADO - FORTALECIMIENTO POSTURAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica', 'Sentado, pisá el centro de la CLX dejando una anilla de separación. Colocá las anillas de las puntas en cada mano. Cruzá los brazos por delante del pecho y después enrollá lentamente la columna hacia adelante y abajo, y después volvé a subir a una posición erguida con buena postura, como se muestra, y repetí.', 40134),
  ('BANDA ELÁSTICA - SWING DE GOLF', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica', 'Imitá un swing de golf mientras tirás de una banda elástica o de un sistema de poleas desde arriba. Mantené la técnica correcta como si tuvieras un palo de golf y estuvieras haciendo un swing. El patrón del swing debe tener resistencia hacia abajo para ayudar a fortalecer en la dirección del swing.', 17387),
  ('ESTABILIZACIÓN - BANDA ELÁSTICA - BICICLETA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Acostate boca arriba y pasá una banda elástica alrededor de los pies. Después, hacé una retroversión pélvica llevando la pelvis hacia atrás para aplanar la zona lumbar contra el piso. Mantené esta posición mientras elevás ambos pies y después estirás uno hacia adelante. Después volvé con esa pierna y estirá la otra, como si anduvieras en bicicleta.', 86358),
  ('PUENTE CON MARCHA - BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Acostado boca arriba, colocá una banda elástica alrededor de los pies. Después, activá los músculos abdominales bajos, apretá los glúteos y elevá la cola del piso formando un puente con el cuerpo. Después, elevá un pie, apoyalo de nuevo y después elevá el otro pie y repetí.', 129628),
  ('CLX - BICHO MUERTO ASISTIDO', NULL, true, 'activo_asistido; fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Colocá 2 anillas centrales en los pies con una anilla de separación entre medio. Sostené las puntas en cada mano. Acostado boca arriba con las rodillas y las caderas flexionadas a 90 grados, usá los músculos abdominales y mantené la posición neutra de la pelvis. No dejes que la columna se mueva. Mantené la pelvis neutra y después estirá lentamente una pierna sin tocar el piso. Al mismo tiempo, elevá el brazo contrario por encima de la cabeza. No dejes que la columna se arquee durante este movimiento. Volvé a la posición inicial y después repetí del lado contrario.', 40135),
  ('CLX - CUATRO APOYOS CON BRAZO Y PIERNA ALTERNADOS - BIRD DOG', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Empezá en posición de gateo con las anillas centrales de la CLX en cada pie y una anilla de separación. Enganchá las anillas de las puntas en cada mano, como se muestra. Manteniendo la columna derecha en posición neutra, estirá una pierna hacia atrás mientras elevás el brazo contrario por encima de la cabeza. Volvé a la posición inicial y después repetí del otro lado.', 40138),
  ('BICHO MUERTO - ISOMÉTRICO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Acostate boca arriba con una banda elástica fijada por detrás. Sostené las puntas de la banda con los brazos estirados hacia arriba por delante del cuerpo. Después, hacé una retroversión pélvica llevando la pelvis hacia atrás para aplanar la zona lumbar contra el piso. Mantené esta posición mientras elevás ambos pies y después estirás uno hacia adelante. Después volvé con esa pierna y estirá la otra, alternando las piernas como si anduvieras en bicicleta.', 86359),
  ('BANDA ELÁSTICA - EXTENSIÓN ALTERNADA DE BRAZO Y PIERNA - DE PIE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Enganchá una banda elástica a la muñeca y al tobillo contrario. Fijá la otra punta de la banda a un objeto firme. Empezá en posición de pie y tirá de la banda hacia arriba y atrás con el brazo. Al mismo tiempo, llevá hacia atrás la pierna que tiene la banda enganchada mientras te equilibrás sobre la otra pierna. Volvé a la posición inicial y repetí.', 83354),
  ('BANDA ELÁSTICA - CRUNCH EN LA SILLA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Sentado, fijá una banda elástica alrededor del respaldo de la silla y sostené las puntas de la banda contra el pecho. Usá los músculos abdominales para enrollar y flexionar el tronco hacia adelante y abajo contra la resistencia de la banda elástica. Después, volvé a la posición original y repetí.', 5118),
  ('BANDA ELÁSTICA - ELEVACIÓN DIAGONAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'En posición arrodillada, con la RODILLA DE ABAJO del lado más cercano al anclaje de la banda elástica, tirá de la banda hacia arriba y hacia el lado contrario. Asegurate de no dejar que el tronco se flexione ni se gire durante el ejercicio. Volvé a la posición original.', 5092),
  ('PESO MUERTO RUMANO CON BANDA ELÁSTICA - RDL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Parate arriba de una banda sosteniendo las puntas en cada mano por delante de las caderas y los muslos. Inclinate hacia adelante manteniendo la espalda y las piernas derechas. Asegurate de hacer bisagra desde las caderas y no dejes que la espalda se redondee hacia adelante. Volvé a subir a la posición de pie erguida y repetí.', 165018),
  ('PALLOF PRESS - MEDIO ARRODILLADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Arrodillate con una rodilla sobre una almohadilla de espuma o una toalla doblada para mayor comodidad y apoyá el otro pie en el piso. Sostené una banda elástica, cuerda o polea contra el pecho, fijada hacia el costado. Después, extendé lentamente los brazos hacia adelante y después volvé. No dejes que el cuerpo rote en ningún momento.', 110020),
  ('PALLOF PRESS - ARRODILLADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Arrodillate sobre una almohadilla de espuma o una toalla doblada para mayor comodidad. Sostené una banda elástica, cuerda o polea contra el pecho, fijada hacia el costado. Después, extendé lentamente los brazos hacia adelante y después volvé. No dejes que el cuerpo rote en ningún momento.', 110019),
  ('PALLOF PRESS - SENTADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Sentate en una silla. Sostené una banda elástica, cuerda o polea contra el pecho, fijada hacia el costado. Después, extendé lentamente los brazos hacia adelante y después volvé. No dejes que el cuerpo rote en ningún momento.', 110016),
  ('PALLOF PRESS - SENTADILLA A UNA PIERNA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Parate en una pierna. Sostené una banda elástica, cuerda o polea contra el pecho, fijada hacia el costado. Después, hacé lentamente una sentadilla a una pierna mientras extendés los brazos hacia adelante. Después, volvé a subir a la posición de pie mientras llevás la mano de vuelta hacia el pecho. Tratá de mantener el equilibrio y no dejes que el cuerpo rote en ningún momento.', 110024),
  ('PALLOF PRESS - APOYO EN UNA PIERNA - SLS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Parate en una pierna con la rodilla levemente flexionada. Sostené una banda elástica, cuerda o polea contra el pecho, fijada hacia el costado. Después, extendé lentamente los brazos hacia adelante y después volvé. Tratá de mantener el equilibrio y no dejes que el cuerpo rote en ningún momento.', 110022),
  ('PALLOF PRESS - SENTADILLA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Parate con los pies separados al ancho de los hombros. Sostené una banda elástica, cuerda o polea contra el pecho, fijada hacia el costado. Después, hacé lentamente una sentadilla mientras extendés los brazos hacia adelante. Después, volvé a subir a la posición de pie mientras llevás la mano de vuelta hacia el pecho. No dejes que el cuerpo rote en ningún momento.', 110023),
  ('PALLOF PRESS - PIES EN TIJERA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Parate y dá un paso adelante quedando con los pies en tijera, y mantené esta posición. Sostené una banda elástica, cuerda o polea contra el pecho, fijada hacia el costado. Después, extendé lentamente los brazos hacia adelante y después volvé. No dejes que el cuerpo rote en ningún momento.', 110026),
  ('SUPERMAN - NIVEL 5 - PELOTA DE EJERCICIOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Banda elástica; Estabilización', 'Empezá en posición arrodillada con una pelota de ejercicios adelante tuyo. Después, rodá hacia adelante de modo que quedes boca abajo sobre la pelota, con los pies en el piso y la panza sobre la pelota. Sostené la cabeza y el pecho de modo que exista una línea recta entre los pies y la cabeza. Sosteniendo una banda elástica en cada brazo, elevá un brazo hacia arriba y adelante mientras llevás el otro brazo hacia atrás, al costado del cuerpo, como en un movimiento de nado.', 38421),
  ('RODILLO DE ESPUMA - MARIPOSA 90/90', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Rodillo de espuma; Estabilización', 'Acostate sobre un rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar y presionala contra el rodillo. Después, elevá una pierna por vez hasta una posición de 90 grados en caderas y rodillas, como se muestra. Después, empezá a separar las piernas manteniendo las rodillas flexionadas a 90 grados, como se muestra. Asegurate de no dejar que la zona lumbar se arquee hacia arriba. Mantené el equilibrio y la espalda plana todo el tiempo.', 8979),
  ('RODILLO DE ESPUMA 90/90 - BRAZOS ALTERNADOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Rodillo de espuma; Estabilización', 'Acostate sobre un rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar y presionala contra el rodillo. Después, elevá una pierna por vez hasta una posición de 90 grados en caderas y rodillas, como se muestra. Sostené las piernas y después elevá un brazo hacia el techo, volvé y después alterná con el otro brazo. Mantené el equilibrio y la espalda plana todo el tiempo.', 8973),
  ('RODILLO DE ESPUMA 90/90 - MARIPOSA CON BRAZO ALTERNADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Rodillo de espuma; Estabilización', 'Acostate sobre un rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar y presionala contra el rodillo. Después, elevá una pierna por vez hasta una posición de 90 grados en caderas y rodillas, como se muestra. Después, elevá un brazo y mantené esta posición. Después, empezá a separar las piernas manteniendo las rodillas flexionadas a 90 grados, como se muestra. Asegurate de no dejar que la zona lumbar se arquee hacia arriba. Cambiá de brazo cada un par de repeticiones. Mantené el equilibrio y la espalda plana todo el tiempo.', 8980),
  ('RODILLO DE ESPUMA - MARCHA SEMIAPOYADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Rodillo de espuma; Estabilización', 'Acostate sobre un rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar, presionala contra el rodillo y mantené esta posición. Después, elevá una rodilla hasta unos 90 grados de flexión de cadera. Después bajá la rodilla mientras empezás a elevar la otra y repetí este patrón de movimiento alternado (ver video). Mantené el equilibrio y la espalda plana todo el tiempo.', 157232),
  ('MEDIO RODILLO DE ESPUMA - EXTENSIÓN DE AMBAS PIERNAS 90/90', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Rodillo de espuma; Estabilización', 'Acostate sobre un medio rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar y presionala contra el rodillo. Después, elevá una pierna por vez hasta una posición de 90 grados en caderas y rodillas, como se muestra. Después, empezá a estirar las piernas hacia adelante, como se muestra. Asegurate de no dejar que la zona lumbar se arquee hacia arriba. Acortá el rango si hace falta. Mantené el equilibrio y la espalda plana todo el tiempo.', 8975),
  ('MEDIO RODILLO DE ESPUMA 90/90 - MARIPOSA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Rodillo de espuma; Estabilización', 'Acostate sobre un medio rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar y presionala contra el rodillo. Después, elevá una pierna por vez hasta una posición de 90 grados en caderas y rodillas, como se muestra. Después, empezá a separar las piernas manteniendo las rodillas flexionadas a 90 grados, como se muestra. Asegurate de no dejar que la zona lumbar se arquee hacia arriba. Mantené el equilibrio y la espalda plana todo el tiempo.', 8981),
  ('MEDIO RODILLO DE ESPUMA 90/90 - MARIPOSA CON BRAZO ALTERNADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Rodillo de espuma; Estabilización', 'Acostate sobre un medio rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar y presionala contra el rodillo. Después, elevá una pierna por vez hasta una posición de 90 grados en caderas y rodillas, como se muestra. Después, elevá un brazo y mantené esta posición. Después, empezá a separar las piernas manteniendo las rodillas flexionadas a 90 grados, como se muestra. Asegurate de no dejar que la zona lumbar se arquee hacia arriba. Cambiá de brazo cada un par de repeticiones. Mantené el equilibrio y la espalda plana todo el tiempo.', 8982),
  ('MANCUERNAS PESADAS - CRUNCH ABDOMINAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Varios; Estabilización', 'Sentado en un banco, sostené una mancuerna con ambas manos y después acostate boca arriba. Los pies deben estar bien apoyados en el piso. Empezá sosteniendo la mancuerna por encima del pecho, con cada mano tomando las puntas de la mancuerna. Extendé los codos para elevar la pesa más arriba del pecho. Después, manteniendo los codos completamente extendidos, elevá la parte superior del cuerpo para despegar los omóplatos del banco, como se muestra. Volvé a la posición inicial y repetí.', 63456),
  ('SUSPENSIÓN TRX - PREPARACIÓN EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Lumbar y torácica', 'Varios; Estabilización', 'Para enganchar fácilmente las cintas del TRX a los pies para las posiciones boca abajo (decúbito ventral), empezá sentado de frente a las manijas. Después, colocá la parte delantera del pie en la cinta más baja de la manija y después colocá el otro pie en la cinta de la otra manija. Las cintas deben quedar en contacto con el arco de los pies. Después, date vuelta para quedar mirando al piso.', 31497),
  ('MEDIO RODILLO DE ESPUMA - EXTENSIÓN LUMBAR ESTÁTICA', NULL, true, 'pasivo', 'Lumbar y torácica', 'Movilización', 'Acostate boca arriba con un medio rodillo de espuma debajo de la zona lumbar. Relajate en esta posición.', 490),
  ('MEDIO RODILLO DE ESPUMA - INCLINACIÓN LATERAL LUMBAR ESTÁTICA', NULL, true, 'pasivo', 'Lumbar y torácica', 'Movilización', 'Acostate de costado con un medio rodillo de espuma debajo del costado del tronco. Relajate en esta posición.', 491),
  ('TRACCIÓN EN DECÚBITO VENTRAL FLEXIONADO - FUERZA MÁXIMA', NULL, true, 'activo', 'Lumbar y torácica', 'Movilización', 'Acostate boca abajo en una cama o camilla, con 2 almohadas debajo de la panza. Ubicate de modo que los muslos toquen el borde de la cama o camilla a la altura de la parte alta de los muslos. Permití un estiramiento pasivo cómodo.', 431),
  ('TRACCIÓN EN DECÚBITO VENTRAL FLEXIONADO - FUERZA MÍNIMA', NULL, true, 'activo', 'Lumbar y torácica', 'Movilización', 'Acostate boca abajo en una cama o camilla, con 2 almohadas debajo de la panza. Ubicate de modo que los muslos toquen el borde de la cama o camilla justo por encima de las rodillas. Permití un estiramiento pasivo cómodo.', 433),
  ('TRACCIÓN EN DECÚBITO VENTRAL FLEXIONADO - FUERZA MODERADA', NULL, true, 'activo', 'Lumbar y torácica', 'Movilización', 'Acostate boca abajo en una cama o camilla, con 2 almohadas debajo de la panza. Ubicate de modo que los muslos toquen el borde de la cama o camilla a la mitad del muslo. Permití un estiramiento pasivo cómodo.', 432),
  ('TRACCIÓN SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'Movilización', 'Sentado, usá los brazos para sacarle algo de peso a la columna. Podés usar toallas dobladas o una silla con apoyabrazos para hacer la técnica.', 11206),
  ('AUTOTRACCIÓN - PIERNAS COLGANDO EN DECÚBITO DORSAL', NULL, true, 'activo', 'Lumbar y torácica', 'Movilización', 'Acostate boca arriba y después bajá una pierna por vez para dejarlas colgando por el borde de la camilla, como se muestra. No hagas esta tracción estática por más de 5 minutos por sesión.', 151565),
  ('AUTOTRATAMIENTO PARA FIJACIÓN BILATERAL EN EXTENSIÓN L5-S1 - SI - MÉTODO HESCH 13', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate boca arriba con las caderas y las rodillas flexionadas y los pies sobre almohadas. Colocá un libro de 5 cm de espesor debajo de la pelvis, a la altura de los hoyuelos, como te indique tu profesional. Después de 2 minutos, hacé 30 retroversiones pélvicas. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 434),
  ('AUTOTRATAMIENTO PARA FIJACIÓN BILATERAL DE ILÍACO ANTERIOR TIPO 1 - SI - MÉTODO HESCH 11', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Apoyá la mano IZQUIERDA sobre una mesa para equilibrarte. Después, colocá el pie DERECHO sobre una silla, de modo que la pierna DERECHA apunte hacia afuera 45 grados hacia la DERECHA. Después, llevá la mano DERECHA hacia el piso con el brazo DERECHO por dentro del muslo DERECHO. Después hacelo del otro lado. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 436),
  ('AUTOTRATAMIENTO PARA FIJACIÓN BILATERAL DE ILÍACO EN INFLARE TIPO I - SI - MÉTODO HESCH 10', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate boca abajo. Usá un rollo de toalla de 5 x 20 cm colocado en forma vertical debajo de AMBOS lados de la pelvis o ilíaco. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 437),
  ('AUTOTRATAMIENTO PARA FIJACIÓN DE SACRO EN FLEXIÓN ANTERIOR - SI - MÉTODO HESCH 12', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate boca arriba con los pies elevados sobre almohadas y las caderas flexionadas a 90 grados, como se muestra. Colocá un rollo de toalla chico de 5 x 20 cm en forma horizontal sobre la mitad inferior del sacro, como te indique tu profesional. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 435),
  ('AUTOTRATAMIENTO PARA FIJACIÓN DE DESCENSO DEL ILÍACO IZQUIERDO - SI - MÉTODO HESCH 21', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate boca arriba con la nalga IZQUIERDA contra una pared y la pierna DERECHA estirada a través del vano de la puerta. Apoyá el pie IZQUIERDO en la pared con la cadera y la rodilla flexionadas y apuntando hacia el hombro IZQUIERDO. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante. Más seguido si te resulta útil.', 422),
  ('AUTOTRATAMIENTO PARA FIJACIÓN DE DESCENSO DEL ILÍACO IZQUIERDO CON SOPORTE - SI - MÉTODO HESCH 18', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Sentado e inclinado hacia adelante, atá una sábana enrollada o colocate un cinturón sacroilíaco. Aplicalo por debajo del isquion y alrededor del hombro del mismo lado. Después, enderezá la columna para sentir una tracción hacia arriba. Podés estar sentado, parado o caminando mientras usás el soporte durante 3 a 5 minutos. Después cambiá el soporte pasando la parte de arriba al otro hombro y repetí el tiempo de sostén.', 424),
  ('AUTOTRATAMIENTO PARA FIJACIÓN EN ROTACIÓN LUMBAR IZQUIERDA - SI - MÉTODO HESCH 9', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Sentate e inclinate hacia adelante de forma cómoda. Inclinate suavemente hacia el costado y rotá hacia la DERECHA apoyando el peso sobre la mano DERECHA, como se muestra. Hacé movimientos chicos flexionando el codo para aumentar la inclinación lateral. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 439),
  ('AUTOTRATAMIENTO PARA FIJACIÓN DE ILÍACO POSTERIOR IZQUIERDO - SI - MÉTODO HESCH 5', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate boca arriba con las caderas y las rodillas flexionadas. Deslizá ambas rodillas flexionadas hacia la DERECHA. Dejá colgar la rodilla IZQUIERDA por el borde de la camilla, manteniéndola cruzada por el centro del cuerpo. El peso de la pierna IZQUIERDA debe generar un estiramiento suave. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 446),
  ('AUTOTRATAMIENTO PARA FIJACIÓN DE PUBIS POSTERIOR IZQUIERDO - SI - MÉTODO HESCH - 3-2', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate boca arriba con las caderas y las rodillas en una posición cómoda. Usá un rollo de toalla de 5 x 20 cm colocado en forma horizontal en el centro de la nalga IZQUIERDA. Tené en cuenta que el rollo de toalla debe abarcar la línea media del ilíaco y el isquion izquierdos. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 11719),
  ('AUTOTRATAMIENTO PARA FIJACIÓN DE PUBIS POSTERIOR IZQUIERDO - SI - MÉTODO HESCH 3', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate boca arriba con las caderas y las rodillas en una posición cómoda. Usá un rollo de toalla de 5 x 20 cm colocado en forma vertical en el centro de la nalga IZQUIERDA. Tené en cuenta que el rollo de toalla debe abarcar la línea media del ilíaco y el isquion izquierdos. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 443),
  ('AUTOTRATAMIENTO PARA FIJACIÓN EN DESLIZAMIENTO LATERAL IZQUIERDO DE LA PELVIS - SI - MÉTODO HESCH 1', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate sobre el lado IZQUIERDO con almohadas debajo de la pelvis. Mantené las caderas y las rodillas estiradas y alineadas con el tronco. Las almohadas deben ser lo suficientemente altas como para que percibas un estiramiento suave y cómodo. Agregá o sacá almohadas según haga falta. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 440),
  ('AUTOTRATAMIENTO PARA FIJACIÓN DE RAMA PÚBICA SUPERIOR IZQUIERDA - SI - MÉTODO HESCH 14', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Parado sobre la pierna DERECHA, colocá la pierna IZQUIERDA directamente hacia el costado sobre una silla. Tenés que sentir un estiramiento en la cara interna del muslo. Agarrate de algo para equilibrarte. A medida que el músculo se relaja, podés dar un paso más hacia la DERECHA para aumentar el estiramiento. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 428),
  ('AUTOTRATAMIENTO PARA FIJACIÓN DE ASCENSO IZQUIERDO - SI - MÉTODO HESCH 17', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate sobre el lado DERECHO con la pierna de abajo flexionada y la pierna IZQUIERDA de arriba estirada y alineada con el tronco. La pierna de arriba cuelga por el borde de la camilla y genera una movilización en estiramiento. No dejes que la pierna se vaya hacia adelante. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 426),
  ('AUTOTRATAMIENTO PARA FIJACIÓN DE ILÍACO ANTERIOR DERECHO - SI - MÉTODO HESCH 4', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Apoyá la mano IZQUIERDA sobre una mesa para equilibrarte. Después, colocá el pie DERECHO sobre una silla, de modo que la pierna DERECHA apunte hacia afuera 45 grados hacia la DERECHA. Después, llevá la mano DERECHA hacia el piso con el brazo DERECHO por dentro del muslo DERECHO. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante.', 441),
  ('AUTOTRATAMIENTO PARA FIJACIÓN DE DESCENSO DEL ILÍACO DERECHO - SI - MÉTODO HESCH 20', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate boca arriba con la nalga DERECHA contra una pared y la pierna IZQUIERDA estirada a través del vano de la puerta. Apoyá el pie DERECHO en la pared con la cadera y la rodilla flexionadas y apuntando hacia el hombro DERECHO. Hacelo 1 vez por día durante una semana y 1 vez por semana de ahí en adelante. Más seguido si te resulta útil.', 423),
  ('AUTOTRATAMIENTO PARA FIJACIÓN EN DESCENSO DEL ILÍACO DERECHO CON SOPORTE - SI - MÉTODO HESCH 19', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Sentado e inclinado hacia adelante, atá una sábana enrollada o colocate un soporte sacroilíaco. Aplicalo por debajo del isquion y alrededor del hombro del mismo lado. Después, enderezá la columna hasta sentir una tracción hacia arriba. Podés estar sentado, parado o caminando con el soporte puesto durante 3-5 minutos. Después cambiá el soporte pasando la parte de arriba al otro hombro y repetí el mismo tiempo de sostén.', 425),
  ('AUTOTRATAMIENTO PARA FIJACIÓN EN DESLIZAMIENTO LATERAL DERECHO DE LA PELVIS - SI - MÉTODO HESCH 2', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate sobre el lado DERECHO con almohadas debajo de la pelvis. Mantené las caderas y las rodillas estiradas y alineadas con el tronco. Las almohadas tienen que ser lo suficientemente altas como para que sientas un estiramiento suave y cómodo. Agregá o sacá almohadas según necesites. Hacelo 1 vez por día durante una semana y después 1 vez por semana.', 444),
  ('AUTOTRATAMIENTO PARA FIJACIÓN SUPERIOR DEL PUBIS DERECHO - SI - MÉTODO HESCH 15', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Parado sobre la pierna IZQUIERDA, colocá la pierna DERECHA directamente hacia el costado sobre una silla. Tenés que sentir un estiramiento en la parte interna del muslo. Agarrate de algo para mantener el equilibrio. A medida que el músculo se relaja, podés dar un paso más hacia la IZQUIERDA para aumentar el estiramiento. Hacelo 1 vez por día durante una semana y después 1 vez por semana.', 429),
  ('AUTOTRATAMIENTO PARA FIJACIÓN EN INFLARE TIPO I DERECHO - SI - MÉTODO HESCH 8', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Apoyá la pierna DERECHA sobre un par de almohadas y dejá que la cadera DERECHA se estire pasivamente hacia el costado DERECHO en un ángulo de 90 grados. Mantené un estiramiento suave durante 2 minutos. Hacelo 1 vez por día durante una semana y después 1 vez por semana.', 438),
  ('AUTOTRATAMIENTO PARA FIJACIÓN EN ASCENSO DERECHO - SI - MÉTODO HESCH 17-2', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate sobre el lado IZQUIERDO con la pierna de abajo flexionada y la pierna DERECHA de arriba estirada y alineada con el tronco. La pierna de arriba cuelga por el borde de la camilla y genera una movilización en estiramiento. No dejes que la pierna se vaya hacia adelante. Hacelo 1 vez por día durante una semana y después 1 vez por semana.', 427),
  ('AUTOTRATAMIENTO PARA FIJACIÓN EN INFLARE DEL ILÍACO TIPO I - SI - MÉTODO HESCH 6', NULL, true, 'activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate boca abajo. Usá una toalla enrollada de unos 5 por 20 cm colocada en forma vertical debajo de la pelvis/ilíaco DERECHO. Hacelo 1 vez por día durante una semana y después 1 vez por semana.', 442),
  ('AUTOTRATAMIENTO PARA FIJACIÓN EN OUTFLARE DEL ILÍACO IZQUIERDO TIPO I - SI - MÉTODO HESCH 7', NULL, true, 'pasivo; activo_asistido', 'Lumbar y torácica', 'Movilización', 'Acostate boca arriba con la cadera IZQUIERDA flexionada 90 grados. Agarrá la rodilla IZQUIERDA con la mano DERECHA y tirá de la pierna IZQUIERDA cruzando el cuerpo hasta sentir un estiramiento muy suave. Mantené el estiramiento durante 2 minutos. Hacelo 1 vez por día durante una semana y después 1 vez por semana.', 445),
  ('DESCOMPRESIÓN LUMBAR SENTADO - SI - MÉTODO HESCH 16', NULL, true, 'activo', 'Lumbar y torácica', 'Movilización', 'Sentate sobre una toalla enrollada de unos 5 por 20 cm colocada en forma horizontal debajo de los dos muslos, justo por delante de los isquiones, como te lo haya indicado tu profesional. Puede ser de mucha ayuda si lo hacés de a ratos a lo largo del día.', 430),
  ('ENERGÍA MUSCULAR - ISOMÉTRICO CON BASTÓN', NULL, true, 'activo_asistido; fortalecimiento', 'Lumbar y torácica', 'Movilización; Estabilización', 'Acostado boca arriba, flexioná las rodillas a 90 grados y después elevá ambas piernas y colocá un bastón debajo de un muslo y apoyá la otra punta del bastón encima del otro muslo, como se muestra. Sostené las dos puntas del bastón con las manos y mantenelo en esa posición. Después empujá hacia arriba con el muslo que tiene el bastón encima y empujá hacia abajo con la pierna que tiene el bastón debajo. Esto no debería generar ningún movimiento, ya que una pierna empuja con la misma fuerza contra la otra a través del bastón. Mantené y repetí.', 55386),
  ('PUENTE CON ALCANCE CRUZADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Movilización; Estabilización; Estiramientos', 'Empezá acostado boca arriba con las rodillas flexionadas, activá los músculos abdominales bajos y apretá los glúteos. Después, elevá la cola del piso o de la cama y elevá un brazo por encima de la cabeza mientras despegás los omóplatos del piso y rotás hacia el costado, como se muestra. Mantené, después volvé a la posición inicial y repetí.', 156229),
  ('PUENTE CON ALCANCE CRUZADO - BILATERAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Movilización; Estabilización; Estiramientos', 'Empezá acostado boca arriba con las rodillas flexionadas, activá los músculos abdominales bajos y apretá los glúteos. Después, elevá la cola del piso o de la cama y elevá un brazo por encima de la cabeza mientras despegás los omóplatos del piso y rotás hacia el costado, como se muestra. Mantené, después volvé a la posición inicial y repetí del otro lado. Seguí alternando de lado a lado.', 156230),
  ('BÁSCULAS PÉLVICAS - DECÚBITO LATERAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Movilización; Estabilización; Estiramientos', 'Acostate de costado y después arqueá y aplaná la zona lumbar, y repetí.', 154208),
  ('COBRA - SOBRE LOS CODOS - YOGA', NULL, true, 'activo', 'Lumbar y torácica', 'Movilización; Estiramientos', 'Empezá acostado boca abajo con las palmas hacia el piso y los codos flexionados al costado del cuerpo. Elevá la cabeza y después el tronco de a poco. Dejá que los brazos te ayuden a subir según lo necesites. Mantené esta posición, después bajá y repetí. Respiración diafragmática lenta y profunda todo el tiempo.', 125285),
  ('ESTIRAMIENTO PARA DESVÍO LATERAL 1 - ROTACIÓN DE TRONCO EN DECÚBITO DORSAL EN FIGURA 4', NULL, true, 'activo', 'Lumbar y torácica', 'Movilización; Estiramientos', 'Acostate sobre una superficie firme, como un piso alfombrado. Cruzá una pierna sobre el muslo contrario, como se muestra. El pie que queda apoyado en el piso debe corresponder al lado hacia el que está desviado el tronco. Después, balanceá suavemente las piernas hacia el lado del pie que está arriba, dejando que la presión sobre el piso estabilice la espalda y la articulación sacroilíaca.', 154201),
  ('ESTIRAMIENTO PARA DESVÍO LATERAL 2 - ROTACIÓN ACTIVA, FUERZA DE PUENTE Y RE DE CADERA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Movilización; Estiramientos', 'Acostate sobre una superficie firme, como un piso alfombrado. Cruzá una pierna sobre el muslo contrario, como se muestra. El pie que queda apoyado en el piso debe corresponder al lado hacia el que está desviado el tronco. Rotá las piernas y el tronco levemente hacia el lado de la pierna de arriba y empujá hacia abajo con el pie apoyado contra el piso, con una fuerza que eleve levemente la pelvis. Después agregá un estiramiento de cadera del lado de la rodilla que está arriba, llevando activamente esa rodilla hacia adelante y lejos tuyo. Mantené unos segundos, después relajá y repetí.', 154203),
  ('DESPLAZAMIENTO PÉLVICO EN DECÚBITO LATERAL - PISO', NULL, true, 'activo', 'Lumbar y torácica', 'Movilización; Estiramientos', 'Empezá acostado boca arriba sobre una superficie firme, como un piso alfombrado. Después, rodá hacia un costado. Asegurate de acostarte del lado hacia el que la pelvis está desviada lateralmente. Mantené esta posición y después rodá boca arriba para descansar. Repetí.', 154199),
  ('ESTIRAMIENTO CON PIERNAS CRUZADAS EN DECÚBITO VENTRAL - CORRECCIÓN DE DESVÍO LATERAL', NULL, true, 'pasivo', 'Lumbar y torácica', 'Movilización; Estiramientos', 'Acostate boca abajo en el piso o en la cama. Separá las rodillas y cruzá las piernas a la altura de los tobillos, como se muestra. Después, bajá los pies hacia el piso manteniendo las piernas cruzadas y relajá completamente las caderas y la espalda. Dejá que la gravedad genere el estiramiento, que se debería sentir a lo largo de las caderas y la zona lumbar.', 154200),
  ('REMOS SENTADO SOBRE PELOTA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentado sobre una pelota de ejercicios, tirá de una banda elástica hacia atrás con ambos brazos mientras flexionás los codos. Mantené la postura erguida todo el tiempo.', 396),
  ('EXTENSIÓN DE HOMBROS SENTADO SOBRE PELOTA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentate sobre una pelota de ejercicios sosteniendo las puntas de una banda elástica con ambas manos. Colocá los omóplatos hacia abajo y atrás y mantené esa posición. Después, tirá de los brazos hacia abajo con los codos estirados hasta que queden al costado del cuerpo. Después volvé con los brazos a la posición inicial y repetí. Mantené la postura erguida todo el tiempo.', 397),
  ('BOSU - PUENTE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con los pies apoyados encima del Bosu y las rodillas flexionadas, elevá la cola, como se muestra.', 5727),
  ('BOSU - PUENTE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado adelante de un Bosu, después recostate hacia atrás sobre el Bosu y elevá la cola, como se muestra.', 5766),
  ('BOSU - PUENTE A UNA PIERNA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con los pies apoyados encima del Bosu y las rodillas flexionadas, elevá la cola y después estirá una rodilla en el aire, como se muestra. Después hacelo con la otra pierna.', 5728),
  ('BOSU - PUENTE A UNA PIERNA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado adelante de un Bosu, después recostate hacia atrás sobre el Bosu y elevá la cola. Después estirá una rodilla en el aire, como se muestra. Después hacelo con la otra pierna.', 5768),
  ('BOSU - PLANCHA LATERAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado de costado, elevá el cuerpo apoyándote sobre el codo mientras los pies quedan sobre el Bosu. Tratá de mantener la columna derecha.', 5731),
  ('BOSU - CRUNCH OBLICUO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentado en la parte de adelante de un Bosu, recostate hacia atrás y hacé un crunch parcial en diagonal. El cuerpo tiene que subir y girar hacia el costado, de modo que el omóplato se despegue del Bosu. Tocá la rodilla contraria con el codo. Mantené los dedos apoyados al costado de la cabeza todo el tiempo.', 5786),
  ('BOSU - PLANCHA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo, elevá el cuerpo apoyándote sobre los codos mientras las puntas de los pies quedan sobre el Bosu. Tratá de mantener la columna derecha.', 5730),
  ('BOSU - CUATRO APOYOS CON BRAZO Y PIERNA ALTERNADOS - BIRD DOG', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de gateo con las rodillas encima de una pelota Bosu. Después, elevá un brazo y la pierna contraria. Volvé a la posición original y repetí del otro lado. Mantené la pelvis estable todo el tiempo. No dejes que las caderas ni la pelvis caigan.', 6677),
  ('BOSU - ABDOMINALES - A', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentado sobre un Bosu, llevá los brazos hacia adelante y hacé un abdominal parcial, como se muestra.', 5734),
  ('BOSU - SUPERMAN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo sobre un Bosu, elevá lentamente los brazos y las piernas despegándolos del piso. Después bajá lentamente hasta el piso.', 5778),
  ('BOSU - EXTENSIÓN DE TRONCO NIVEL 1', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo con la parte superior del cuerpo sobre un Bosu, elevá lentamente la cabeza y el pecho, como se muestra. Los brazos pueden ir detrás de la espalda o al costado del cuerpo.', 5737),
  ('BOSU - EXTENSIÓN DE TRONCO NIVEL 3', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo con la parte superior del cuerpo sobre un Bosu, elevá lentamente la cabeza y el pecho, como se muestra. Tocate la nuca con ambas manos mientras lo hacés.', 5735),
  ('ACTIVACIÓN ABDOMINAL - BICICLETA - SIN APOYO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con las rodillas flexionadas, elevá ambos pies y estirá uno hacia adelante. Después volvé con esa pierna y estirá la otra. Usá los músculos abdominales para que la columna no se mueva.', 247),
  ('ACTIVACIÓN ABDOMINAL - ELEVACIÓN BILATERAL DE PIERNAS FLEXIONADAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba con las rodillas flexionadas. Usá los músculos abdominales para llevar la zona lumbar contra el piso o la colchoneta. Mantené eso mientras despegás los pies del piso unos centímetros. Usá los músculos abdominales para que la columna no se mueva en ningún momento.', 248),
  ('ACTIVACIÓN ABDOMINAL - ELEVACIÓN BILATERAL DE PIERNAS ESTIRADAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con las rodillas estiradas, elevá ambas piernas del piso. Usá los músculos abdominales para que la columna no se mueva. Bajá las piernas más cerca del piso para progresar el ejercicio.', 250),
  ('ACTIVACIÓN ABDOMINAL - EXTENSIÓN DE UNA RODILLA CON APOYO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá acostado boca arriba con las rodillas flexionadas. Después, activá los músculos abdominales para que la columna no se mueva mientras estirás una pierna sobre el piso, como se muestra. Volvé con la pierna a la posición inicial y después hacelo del otro lado. Usá los músculos abdominales para evitar que la columna se mueva todo el tiempo.', 254),
  ('PUENTE CON PIERNA CRUZADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, cruzá la pierna como se muestra. Después, activá los músculos abdominales bajos, apretá los glúteos y elevá la cola del piso o de la cama, formando un puente con el cuerpo.', 26178),
  ('PUENTE CON PIERNA CRUZADA - BRAZOS ARRIBA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, cruzá la pierna y juntá las manos como se muestra. Después, activá los músculos abdominales bajos, apretá los glúteos y elevá la cola del piso o de la cama, formando un puente con el cuerpo.', 26181),
  ('PUENTE CON CAMINATA HACIA ADELANTE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá acostado boca arriba con las rodillas flexionadas. Después, activá los músculos abdominales bajos, apretá los glúteos y elevá la cola del piso, formando un puente con el cuerpo. Mantené esta posición mientras caminás lentamente con los pies hacia adelante dando pasitos cortos, hasta que las rodillas queden casi estiradas. Después, bajá la cola al piso y flexioná las rodillas de a una para volver a la posición inicial, y repetí.', 78541),
  ('PUENTE APRETANDO UNA ALMOHADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, colocá una almohada entre las rodillas y apretala. Mantené eso y después activá los músculos abdominales bajos, apretá los glúteos y elevá la cola del piso o de la cama, formando un puente con el cuerpo.', 26177),
  ('PUENTE APRETANDO UNA PELOTA DE GOMA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba con las rodillas flexionadas. Colocá una pelota de goma chica entre las rodillas. Apretá la pelota con las rodillas y mantené esa presión. Manteniendo la presión sobre la pelota, empujá con los talones mientras elevás la cola del piso o de la cama, formando un puente con el cuerpo. Volvé a la posición inicial y repetí.', 106205),
  ('POLEA - PALLOF PRESS EN MEDIA RODILLA - ANTIRROTACIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Arrodillate con una rodilla sobre una almohadilla de espuma o una toalla doblada para mayor comodidad y apoyá el otro pie en el piso. Colocá la polea a la altura del codo cuando estés en esta posición. Sostené una banda elástica, cuerda o polea contra el pecho, fijada del lado de la rodilla que está apoyada. Después, extendé lentamente los brazos hacia adelante y volvé. No dejes que el cuerpo rote en ningún momento.', 142541),
  ('POLEA - CHOP DE ARRIBA HACIA ABAJO - ROTACIONES DE TRONCO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Colocá la polea en posición alta. Empezá sosteniendo el accesorio de soga con ambas manos. Después, tirá hacia abajo y cruzando el cuerpo hacia el lado contrario mientras rotás la columna. Volvé a la posición inicial y repetí. El tronco y las caderas tienen que rotar durante el movimiento.', 142539),
  ('Puente en la silla', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentado en una silla, apoyá las manos sobre el asiento al costado de la cola para sostenerte. Después, activá los músculos abdominales bajos, apretá los glúteos y elevá la cola de la silla, formando un puente con el cuerpo. Mantené, después bajá y repetí.', 81675),
  ('PUENTE EN ALMEJA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba con las rodillas flexionadas y las plantas de los pies en contacto entre sí. Después, activá los músculos abdominales bajos, apretá los glúteos y elevá la cola del piso o de la cama, formando un puente con el cuerpo. Mantené, después bajá y repetí.', 67956),
  ('PLANCHA COMPLETA EN LA MESADA - HACIA ADELANTE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Parate de frente a una mesada. Alejate un paso de la mesada e inclinate hacia ella apoyándote sobre las manos con los codos completamente estirados. Activá los músculos abdominales, los glúteos y los muslos, y mantené la columna derecha.', 164834),
  ('CRUNCH - 90/90', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá acostado boca arriba con las piernas en posición de MESA, como se muestra. Las caderas y las rodillas tienen que estar flexionadas a 90 grados. Después, llevá la parte superior del cuerpo hacia adelante en un crunch, de modo que los omóplatos se despeguen del piso. No dejes que la zona lumbar se arquee hacia arriba durante todo el ejercicio. Además, las piernas tienen que quedar en la posición 90-90 todo el tiempo.', 549),
  ('CRUNCH - MANOS DEBAJO DE LA ZONA LUMBAR', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá acostado en el piso con las manos debajo de la zona lumbar. Usalas para controlar que no haya movimiento en la pelvis ni en la columna durante el ejercicio. Activá los músculos abdominales y después despegate del piso hasta que los omóplatos se separen, y volvé a la posición inicial. CONSEJOS: fijá la mirada en un punto del techo. Tratá de no flexionar el cuello ni la espalda alta durante el ejercicio. Subí derecho y en bloque. Llevá el mentón hacia el pecho para ayudar a estabilizar el cuello.', 46745),
  ('CRUNCH - INVERTIDO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con las rodillas flexionadas, elevá las piernas y despegá la cola. Mantené las rodillas estiradas todo el tiempo.', 284),
  ('CRUNCH - TIPO 1', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con los brazos extendidos hacia adelante, elevá parcialmente el tronco despegando los omóplatos del piso. Volvé a acostarte y repetí.', 256),
  ('CRUNCH - TIPO 2', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con los brazos cruzados sobre el pecho, elevá parcialmente el tronco y despegá los omóplatos del piso. Bajá y repetí.', 257),
  ('CRUNCH - TIPO 3', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con los brazos detrás de la cabeza, elevá parcialmente el tronco despegando los omóplatos del piso. Bajá y repetí.', 258),
  ('CRUNCH - TIPO 4', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con los brazos extendidos por encima de la cabeza, elevá parcialmente el tronco despegando los omóplatos del piso. Bajá y repetí.', 107708),
  ('CRUNCH EN CÍRCULOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba con las rodillas flexionadas. Colocá las manos al costado de las orejas y después elevá la parte superior del cuerpo despegando los omóplatos del piso. Movete en un patrón circular mientras rotás la parte alta del tronco. Bajá, cambiá de dirección y repetí.', 168821),
  ('SENTADILLA CON MANCUERNAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Parate sosteniendo mancuernas en cada mano. Inclinate hacia adelante mientras flexionás las rodillas manteniendo la espalda derecha. Asegurate de flexionar desde las caderas (bisagra) y no dejes que la espalda se redondee hacia adelante. Volvé a subir a la posición de pie y repetí.', 165024),
  ('BANDA ELÁSTICA - ANTIRROTACIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición arrodillada con la RODILLA APOYADA más cerca del anclaje de la banda elástica. Después, con las manos a la altura del pecho, movelas lentamente hacia afuera por delante del cuerpo hasta que los codos queden extendidos. Asegurate de no dejar que el tronco rote durante el ejercicio. Volvé con los brazos a la posición original.', 525),
  ('BANDA ELÁSTICA - CHOP', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'En posición arrodillada con la RODILLA LEVANTADA más cerca del anclaje de la banda elástica, tirá de la banda hacia abajo y hacia el lado contrario. Asegurate de no dejar que el tronco se flexione ni se tuerza durante el ejercicio. Volvé a la posición original.', 527),
  ('PUENTE CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, sostené una banda elástica por encima de la cintura, como se muestra. Después, activá los músculos abdominales bajos, apretá los glúteos y elevá la cola del piso o de la cama.', 11802),
  ('CHOPS CON BANDA ELÁSTICA - DE ARRIBA HACIA ABAJO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sosteniendo una banda elástica con ambas manos por encima del hombro. Después, tirá hacia abajo y cruzando el cuerpo hacia el lado contrario. El tronco y las caderas tienen que rotar durante el movimiento.', 19045),
  ('CHOPS CON BANDA ELÁSTICA - DE ABAJO HACIA ARRIBA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sosteniendo una banda elástica con ambas manos por debajo de la cintura. Después, elevá y cruzá el cuerpo hacia el lado contrario. El tronco y las caderas tienen que rotar durante el movimiento.', 19046),
  ('ROTACIÓN DE TRONCO SENTADO CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentado, cruzá los brazos sobre el pecho y sostené una banda elástica con una mano, como se muestra. Girá hacia el costado mientras rotás el tronco. Los brazos quedan cruzados todo el tiempo.', 19050),
  ('ROTACIÓN DE TRONCO DE PIE CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'De pie, sostené una banda elástica con los brazos extendidos por delante tuyo. Girá hacia el costado mientras rotás el tronco y las caderas. Los brazos tienen que estar extendidos y por delante del pecho todo el tiempo. La banda elástica tiene que estar fijada hacia el costado del cuerpo.', 18689),
  ('PELOTA DE EJERCICIOS - PUENTE CON ESPALDA ALTA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado sobre una pelota de ejercicios. Después, caminá lentamente con los pies hacia adelante de modo que la pelota quede en la espalda alta. Después, elevá la cola y la pelvis despegándolas de la pelota, formando un puente con el cuerpo. Mantené esta posición y después volvé caminando con los pies hacia la pelota para regresar a la posición inicial. Repetí.', 292),
  ('PELOTA DE EJERCICIOS - BICHO MUERTO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba con una pelota de ejercicios apoyada sobre el abdomen. Después, hacé una báscula pélvica o activá los músculos abdominales en posición de columna neutra. Después, sostené la pelota con las rodillas y los brazos. Las piernas tienen que estar en posición 90-90, como en la imagen de arriba. Después, presioná la pelota con una rodilla y el brazo contrario mientras estirás la otra pierna y el otro brazo, como se muestra, en un movimiento alternado. Mantené la columna plana o en posición neutra.', 36382),
  ('PELOTA DE EJERCICIOS - MARCHA', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Sentado sobre una pelota de ejercicios, elevá lentamente un pie del piso. Volvé y después elevá el otro lado. Mantené la columna estable y erguida. Tratá de mover solamente las piernas.', 308)
INSERT INTO exercise_library (name, professional_id, is_active, exercise_type, catalog_region, catalog_subcategory, instructions, source_exercise_id)
VALUES
  ('PELOTA DE EJERCICIOS - BRAZO Y PIERNA ALTERNADOS SENTADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentado sobre una pelota de ejercicios, activá los músculos abdominales y después elevá una pierna y el brazo contrario. Bajá las extremidades y después elevá el lado contrario. Tratá de mantener la pelvis y la columna estables todo el tiempo.', 319),
  ('RODILLO DE ESPUMA - EXTENSIÓN 90/90 CON AMBAS PIERNAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate sobre un rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar y presionala contra el rodillo. Después, elevá una pierna por vez hasta una posición de 90 grados en caderas y rodillas, como se muestra. Después, empezá a estirar las piernas hacia adelante, como se muestra. Asegurate de no dejar que la zona lumbar se arquee hacia arriba. Achicá el rango si hace falta. Mantené el equilibrio y la espalda plana todo el tiempo.', 8974),
  ('RODILLO DE ESPUMA - BICICLETA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate sobre un rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar y presionala contra el rodillo. Después, flexioná las rodillas y empezá a estirar una pierna hacia adelante, como se muestra. Volvé con esa pierna y después extendé la otra. Asegurate de no dejar que la zona lumbar se arquee hacia arriba. Achicá el rango si hace falta. Mantené el equilibrio y la espalda plana todo el tiempo.', 9256),
  ('RODILLO DE ESPUMA 90/90', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate sobre un rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar y presionala contra el rodillo. Después, elevá una pierna por vez hasta una posición de 90 grados en caderas y rodillas, como se muestra. Mantené el equilibrio y la espalda plana todo el tiempo.', 9255),
  ('PUENTE SOBRE RODILLO DE ESPUMA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba y con los pies encima de un rodillo de espuma, activá los músculos abdominales bajos, apretá los glúteos y después elevá la cola del piso, como se muestra. Bajá y repetí. Mantené el equilibrio sobre el rodillo todo el tiempo.', 8977),
  ('MARCHA SOBRE RODILLO DE ESPUMA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate sobre un rodillo de espuma de modo que la cabeza y la cola queden en contacto. Aplaná la zona lumbar y presionala contra el rodillo. Después, alterná elevando una pierna por vez, como marchando en el lugar. Mantené el equilibrio y la espalda plana todo el tiempo.', 8988),
  ('CAMINATA EN PLANCHA CON RODILLO DE ESPUMA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Arrodillado, apoyá las manos sobre un rodillo de espuma y mantené la columna derecha, como se muestra. Después, empujá el rodillo hacia adelante con los brazos y volvé a la posición original. Mantené la columna derecha todo el tiempo.', 9254),
  ('PUENTE A UNA PIERNA SOBRE RODILLO DE ESPUMA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba y con un pie encima de un rodillo de espuma, activá los músculos abdominales bajos, apretá los glúteos y después elevá la cola del piso, como se muestra. Bajá y repetí. Mantené el equilibrio sobre el rodillo todo el tiempo.', 8978),
  ('PESO MUERTO CON PESO LIBRE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Parate sosteniendo una mancuerna con ambas manos, como se muestra. Inclinate hacia adelante y bajá la mancuerna hacia el piso. Hacé bisagra desde las caderas y no flexiones la columna. Las rodillas pueden flexionarse un poco. Enderezate hasta quedar de pie y repetí. Asegurate de mantener la espalda plana todo el tiempo.', 170797),
  ('PESO LIBRE - RDL - PESO MUERTO RUMANO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Parate sosteniendo mancuernas en cada mano. Inclinate hacia adelante manteniendo la espalda y las rodillas estiradas. Asegurate de hacer bisagra desde las caderas y no dejes que la espalda se redondee hacia adelante. Volvé a subir a la posición de pie y repetí.', 165019),
  ('PUENTE DE RANA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá acostado boca arriba con las plantas de los pies en contacto entre sí y los brazos al costado del cuerpo para apoyarte. Después, empujá con las piernas y elevá la cola del piso hasta la posición de puente, como se muestra. Mantené, después bajá la cola al piso volviendo a la posición inicial y repetí.', 79114),
  ('PLANCHA COMPLETA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Mantené una posición de plancha con los codos completamente extendidos y las piernas apenas separadas, como se muestra. No dejes que la espalda se arquee hacia abajo.', 40573),
  ('PLANCHA COMPLETA - BRAZOS ALTERNADOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Mantené una posición de plancha con los codos completamente extendidos y las piernas apenas separadas, como se muestra. No dejes que la espalda se arquee hacia abajo. Manteniendo esta posición, elevá un brazo y después volvé a apoyarlo. Después hacelo con el otro brazo y repetí.', 40571),
  ('PLANCHA COMPLETA - PIERNAS ALTERNADAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Mantené una posición de plancha con los codos completamente extendidos y las piernas apenas separadas, como se muestra. No dejes que la espalda se arquee hacia abajo. Manteniendo esta posición, elevá una pierna y después volvé a apoyarla. Después hacelo con la otra pierna y repetí.', 40572),
  ('PLANCHA COMPLETA CON ROTACIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Mantené una posición de plancha con los codos completamente extendidos y las piernas separadas, como se muestra. Después, elevá un brazo hacia arriba y atrás mientras rotás el tronco y la cabeza en la misma dirección. Volvé y repetí del otro lado.', 12911),
  ('DISCOS DESLIZANTES - BURPEE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de pie con discos deslizantes debajo de cada pie. Después, flexioná las rodillas y bajá hacia el piso. Apoyá las manos en el piso mientras deslizás y estirás las piernas hasta quedar en posición de plancha, con las puntas de los pies y las manos en contacto con el piso. Mantené la columna derecha y no dejes que la espalda se hunda. Después, invertí el movimiento, flexioná las rodillas y volvé a pararte. Repetí.', 43361),
  ('DISCOS DESLIZANTES - TIJERAS EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Colocá discos deslizantes debajo de cada pie y empezá en posición de plancha con ambas manos y pies en contacto con el piso, boca abajo. Después, deslizá un pie hacia el otro lado pasándolo por debajo de la pierna contraria, como se muestra. Volvé a la posición de plancha original y después repetí del otro lado.', 43360),
  ('MEDIO RODILLO DE ESPUMA - BICHO MUERTO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate sobre un medio rodillo de espuma de modo que la cabeza y la cola queden en contacto con el lado plano del rodillo. Aplaná la zona lumbar y presionala contra el rodillo. Después, elevá una pierna por vez hasta una posición de 90 grados en caderas y rodillas, como se muestra. Sostené las piernas y después elevá un brazo hacia el techo mientras estirás la pierna del lado contrario hacia adelante. Volvé y después alterná con el otro brazo y la otra pierna. Mantené el equilibrio y la espalda plana todo el tiempo.', 8985),
  ('MEDIO RODILLO DE ESPUMA 90/90 - BRAZOS ALTERNADOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate sobre un medio rodillo de espuma de modo que la cabeza y la cola queden en contacto con el lado plano del rodillo. Aplaná la zona lumbar y presionala contra el rodillo. Después, elevá una pierna por vez hasta una posición de 90 grados en caderas y rodillas, como se muestra. Sostené las piernas y después elevá un brazo hacia el techo, volvé y después alterná con el otro brazo. Mantené el equilibrio y la espalda plana todo el tiempo.', 8972),
  ('MANCUERNAS PESADAS - PESO MUERTO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Parate sosteniendo una mancuerna en cada mano por delante de las caderas y los muslos. Inclinate hacia adelante manteniendo la espalda derecha y sin dejar que se redondee hacia adelante. Hacé bisagra desde las caderas de modo que el peso baje cerca de las piernas hasta aproximadamente la mitad de la tibia. Después, enderezate hasta la posición de pie. Asegurate de mantener la espalda derecha y de hacer bisagra desde las caderas. Mantené la mancuerna cerca del cuerpo para evitar presión excesiva sobre la espalda.', 63497),
  ('PUENTE SOBRE TALONES', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, activá los músculos abdominales bajos, apretá los glúteos, levantá las puntas de los pies y después elevá la cola del piso o de la cama, formando un puente con el cuerpo. Tenés que empujar con los talones todo el tiempo.', 22418),
  ('ISOMÉTRICO DE FLEXIÓN DE CADERA - UNA PIERNA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, elevá una rodilla y presionala contra las manos.', 5093),
  ('ISOMÉTRICO BILATERAL DE FLEXIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, elevá las rodillas y presionalas contra las manos.', 547),
  ('BOSU INVERTIDO - PLANCHA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Apoyá los codos sobre un Bosu invertido y elevá el cuerpo apoyándote en las puntas de los pies. Tratá de mantener la columna derecha.', 8420),
  ('KETTLEBELL - RDL A UNA PIERNA - PESO MUERTO RUMANO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de pie sosteniendo una kettlebell o mancuerna al costado del cuerpo. Después, inclinate hacia adelante y dejá que la kettlebell baje hacia el piso mientras extendés y elevás la pierna contraria por detrás del cuerpo. Mantené la columna derecha y hacé bisagra desde la cadera, como se muestra. Volvé a la posición original y repetí.', 120511),
  ('PESO MUERTO CON KETTLEBELL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Agachate y levantá una kettlebell. Asegurate de mantener la espalda plana todo el tiempo. Hacé bisagra desde las caderas, no flexiones la columna.', 28611),
  ('REMO EN PLANCHA CON KETTLEBELL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de plancha completa sobre las manos y las puntas de los pies. Después, agarrá una kettlebell y tirá de ella hacia el techo mientras flexionás el codo. Dejá que la columna rote mientras elevás la kettlebell.', 28620),
  ('RODILLAS AL PECHO', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición sentada con las piernas estiradas y las manos apoyadas atrás para sostenerte. Elevá las piernas y llevalas hacia arriba y en diagonal hacia el hombro contrario. Estirá las piernas hasta la posición inicial, alterná los lados y repetí.', 169166),
  ('PLANCHA LATERAL MODIFICADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado de costado con las rodillas flexionadas, elevá el cuerpo apoyándote sobre el codo y las rodillas. Tratá de mantener la columna derecha.', 28009),
  ('PLANCHA LATERAL CON ALMEJA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado de costado con las rodillas flexionadas, elevá el cuerpo apoyándote sobre el codo y las rodillas. Después, elevá la rodilla de arriba. Repetí. Tratá de mantener la columna derecha.', 28006),
  ('PLANCHA LATERAL CON CRUNCH LATERAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Hacé una plancha lateral como se muestra: acostado de costado, elevá el cuerpo apoyándote sobre el codo y los pies. Tratá de mantener la columna derecha. Manteniendo esta posición, acercá el brazo y la pierna de arriba entre sí, de modo que el codo y la rodilla se toquen o queden cerca de tocarse. Dejá que el tronco se flexione también para involucrar los músculos abdominales.', 68973),
  ('ROTACIONES DEL TRONCO INFERIOR - SIN APOYO - LTR', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con las rodillas flexionadas, elevá ambos pies y balanceá lentamente la pelvis hacia un costado. Después balanceá lentamente hacia el otro costado. Mantené la columna derecha durante todo el ejercicio.', 274),
  ('PUENTE CON BALÓN MEDICINAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con las rodillas flexionadas, apretá una pelota entre las rodillas y elevá la cola del piso o de la cama.', 6236),
  ('PLANCHA LATERAL MODIFICADA - ALMEJAS - ABDUCCIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado de costado con las rodillas flexionadas, elevá el cuerpo apoyándote sobre el codo y las rodillas. Mantené esta posición de plancha lateral modificada y tratá de mantener la columna derecha. Manteniendo esa posición, elevá la pierna de arriba separando las rodillas, como se muestra. Bajá la rodilla y repetí el movimiento de subir y bajar la pierna.', 79117),
  ('PLANCHA MODIFICADA - ALCANCE CON ROTACIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado de costado con las rodillas flexionadas, elevá el cuerpo apoyándote sobre el codo y las rodillas. Después, elevá el brazo por encima de la cabeza siguiendo la mano con la mirada. Bajá la mano y el brazo, y repetí. Mantené la columna derecha mientras las caderas están despegadas del piso.', 139536),
  ('ENERGÍA MUSCULAR - UNA PIERNA - SI', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, elevá la rodilla y presionala contra la mano. Con la otra pierna, presioná el pie contra el piso. Hacé las dos cosas al mismo tiempo. Descansá y después repetí del mismo lado.', 331),
  ('ENERGÍA MUSCULAR EN DIAGONAL', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, elevá la rodilla y presionala contra la mano CONTRARIA. Con la otra pierna, presioná el pie contra el piso. Hacé las dos cosas al mismo tiempo.', 28003),
  ('PALLOF PRESS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sostené una banda elástica, cuerda o polea contra el pecho, fijada hacia el costado. Después, extendé lentamente los brazos hacia adelante y volvé. No dejes que el cuerpo rote en ningún momento.', 110006),
  ('CRUNCH PARCIAL DE OBLICUOS 1', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado en el piso con las rodillas flexionadas, elevate lentamente y hacia el costado de modo que el omóplato se despegue del piso. Alterná llevando el brazo hacia adelante y hacia el costado del cuerpo en cada repetición.', 259),
  ('CRUNCH PARCIAL DE OBLICUOS 2', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado en el piso con las rodillas flexionadas, elevate lentamente y hacia el costado de modo que el omóplato se despegue del piso. Mantené los brazos cruzados sobre el pecho todo el tiempo.', 398),
  ('CRUNCH PARCIAL DE OBLICUOS 3', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado en el piso con las rodillas flexionadas, elevate lentamente y hacia el costado de modo que el omóplato se despegue del piso. Mantené las manos entrelazadas detrás de la cabeza todo el tiempo.', 260),
  ('RELOJ PÉLVICO EN 12 - RETROVERSIÓN PÉLVICA', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba con las rodillas flexionadas y los pies bien apoyados en el piso, separados aproximadamente al ancho de la pelvis. Después, imaginate un reloj sobre la zona del abdomen y la pelvis. Inclina la pelvis de modo que el reloj se vuelque hacia las 12 (retroversión) y la zona lumbar se apoye firme contra el piso. Colocá los pulgares sobre la parte de adelante del hueso de la pelvis (EIAS) para sentir el movimiento. Durante el movimiento, la pelvis rota hacia atrás (retroversión) y después vuelve a una posición relajada. Repetí con movimientos suaves y controlados.', 67637),
  ('ELEVACIONES PÉLVICAS', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Apoyá el cuerpo sobre una silla, sostenido en el pecho y el abdomen. Después, elevá la cola hacia el techo.', 275),
  ('BÁSCULA PÉLVICA - SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Sentado, arqueá la zona lumbar y después aplanala, de manera repetida. La pelvis tiene que inclinarse hacia adelante y atrás durante el movimiento. Movete dentro de un rango cómodo.', 40933),
  ('BÁSCULA PÉLVICA - SENTADO - PELOTA DE EJERCICIOS', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Sentate sobre una pelota de ejercicios grande y apoyá las manos en las caderas. Después, arqueá la zona lumbar y después aplanala, de manera repetida. La pelvis tiene que inclinarse hacia adelante y atrás durante el movimiento. Movete dentro de un rango cómodo.', 309),
  ('BÁSCULA PÉLVICA CON EXTENSIÓN DE BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, tirá de las bandas elásticas hacia abajo, en dirección a los pies. Mantené la zona lumbar plana contra el piso todo el tiempo.', 394),
  ('PIKE - TOQUES ALTERNADOS DE PIE', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de pike (V invertida). Bajá la mano y tocá el pie contrario. Volvé a la posición inicial y alterná los brazos.', 161460),
  ('PIKE - ESCALADOR', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de pike. Bajá hasta la posición de flexión de brazos mientras llevás la rodilla hacia el pecho, como se muestra. Volvé a la posición inicial, cambiá de pierna y repetí.', 159612),
  ('PLANCHA - 1 RODILLA 1 PIE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de plancha bilateral sobre las rodillas, como se muestra. Las dos rodillas y los dos codos tienen que estar en contacto con el piso sosteniendo el cuerpo. Mantené la columna derecha. Después, estirá y elevá una rodilla, y mantené. Después bajala y hacelo con la otra pierna.', 39682),
  ('PLANCHA - BRAZOS ALTERNADOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo, elevá el cuerpo apoyándote sobre los codos y las puntas de los pies. Después, apoyate sobre un codo y elevá el otro brazo hacia adelante, como se muestra. Volvé a la posición inicial y después elevá el otro brazo hacia adelante y repetí. Tratá de mantener la columna derecha todo el tiempo. No dejes que la zona lumbar se hunda.', 40574),
  ('PLANCHA - PIERNAS ALTERNADAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo, elevá el cuerpo apoyándote sobre los codos y las puntas de los pies. Después, despegá una pierna del piso y volvé a apoyarla. Después repetí con la otra pierna. Tratá de mantener la columna derecha todo el tiempo. No dejes que la zona lumbar se hunda.', 40575),
  ('PLANCHA - ESCALADORES CRUZADOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de plancha completa (posición de flexión de brazos). Manteniendo la plancha completa, flexioná la cadera y la rodilla llevándolas hacia el hombro contrario. Volvé a la posición de plancha y después alterná elevando el otro lado. Repetí alternando los lados.', 168820),
  ('PLANCHA - RODILLAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo, elevá el cuerpo apoyándote sobre los codos y las rodillas. Tratá de mantener la columna derecha.', 39685),
  ('PLANCHA - LATERAL - 1 RODILLA 1 PIE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado de costado, elevá el cuerpo apoyándote sobre el codo y la rodilla de un lado y el pie del otro lado. Tratá de mantener la columna derecha.', 39683),
  ('PLANCHA CON BRAZO Y PIERNA ALTERNADOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo, elevá el cuerpo apoyándote sobre los codos y las puntas de los pies. Después, elevá un brazo y la pierna contraria. Volvé a la posición original y después hacelo con el otro brazo y la otra pierna. Tratá de mantener la columna derecha.', 498),
  ('PLANCHA LATERAL CON ABDUCCIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado de costado, elevá el cuerpo apoyándote sobre el codo y los pies. Después, elevá lentamente la pierna de arriba y volvé. Tratá de mantener la columna derecha todo el tiempo.', 556),
  ('REMOS EN PLANCHA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de plancha completa sobre las manos y las puntas de los pies. Después, apoyate sobre un brazo y despegá el otro brazo del piso mientras flexionás el codo, como se muestra. Dejá que la columna rote mientras elevás el brazo. Volvé a apoyar el brazo y después repetí del otro lado.', 110624),
  ('PLANCHA CON EXTENSIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca abajo y después hacé una plancha de modo que las puntas de los pies y los antebrazos sostengan el cuerpo por encima del piso. Mantené la columna derecha y estable todo el tiempo. Después, flexioná una rodilla a 90 grados y elevala hacia el techo. Bajá y repetí.', 46748),
  ('EMBARAZO - ELEVACIONES ALTERNADAS DE BRAZOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'En posición de gateo, elevá lentamente un brazo hacia adelante. Bajalo y repetí del lado contrario. Activá los músculos abdominales y tratá de mantener la columna derecha todo el tiempo. Mantené la zona lumbar nivelada.', 179627),
  ('EMBARAZO - OSO SUSPENDIDO', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de cuatro apoyos. Elevá la rodilla manteniendo la columna derecha. Mantené, bajá la pierna, volvé a la posición inicial y repetí del lado contrario.', 181343),
  ('EMBARAZO - PLANCHA LATERAL MODIFICADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado de costado con las rodillas flexionadas, elevá el cuerpo apoyándote sobre el codo y las rodillas. Mantené esta posición de plancha lateral modificada y tratá de mantener la columna derecha. Bajá y repetí.', 181348),
  ('DECÚBITO VENTRAL CON BRAZO Y PIERNA ALTERNADOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo y manteniendo los músculos abdominales bajos activados, elevá lentamente un brazo y la pierna contraria. Bajá lentamente y después elevá el lado contrario. No dejes que la columna se mueva en ningún momento.', 337),
  ('DECÚBITO VENTRAL CON PIERNA ALTERNADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo y manteniendo los músculos abdominales bajos activados, elevá lentamente una pierna. Bajá lentamente y después elevá el lado contrario. No dejes que la columna se mueva en ningún momento.', 338),
  ('EXTENSIÓN DE ESPALDA EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo, elevá lentamente el pecho despegándolo del piso. Después bajá lentamente hasta el piso.', 339),
  ('PELOTA EN DECÚBITO VENTRAL - BRAZO Y PIERNA ALTERNADOS', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo sobre una pelota, sostenete con los pies y las manos. Después, elevá lentamente un brazo y la pierna contraria. Volvé con el brazo y la pierna al piso y después elevá el brazo y la pierna del lado contrario.', 315),
  ('SUPERMAN EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca abajo, elevá lentamente los brazos y las piernas despegándolos del piso. Después bajá lentamente hasta el piso.', 340),
  ('FLEXIÓN DE BRAZOS A PLANCHA COMPLETA CON ROTACIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá haciendo una flexión de brazos con las piernas bien separadas. Mantené la posición de plancha arriba, con los codos completamente extendidos, y elevá un brazo hacia arriba y atrás mientras rotás el tronco y la cabeza en la misma dirección. Volvé con el brazo a la posición de plancha completa, hacé otra flexión de brazos y después repetí del otro lado.', 12912),
  ('CUATRO APOYOS CON BRAZO ALTERNADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'En posición de gateo, elevá lentamente un brazo hacia adelante. Bajalo y repetí del lado contrario. Activá los músculos abdominales y tratá de mantener la columna derecha todo el tiempo. Mantené la zona lumbar nivelada.', 341),
  ('CUATRO APOYOS CON BRAZO Y PIERNA ALTERNADOS CON BANDA ELÁSTICA - BIRD DOG', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de gateo. Sujetá una banda elástica a un pie y sostené la otra punta con el brazo contrario. Empezá a hacer la elevación alternada de brazo y pierna del lado donde está sujeta la banda elástica, como se muestra. Hacelo de un lado y después del otro.', 38391),
  ('CUATRO APOYOS CON BRAZO Y PIERNA ALTERNADOS Y TOQUE DE RODILLA CON CODO - BIRD DOG CON TOQUE DE CODO', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'En posición de gateo, elevá lentamente la pierna y el brazo contrario. Al volver con el brazo y la pierna hacia abajo, no toques el piso: en cambio, tocá la rodilla contraria con el codo y después volvé a elevarlos y estirarlos. Después apoyalos en el piso. Luego hacelo del otro lado y repetí.', 36152),
  ('CUATRO APOYOS CON PIERNA ALTERNADA - EXTENSIÓN DE CADERA', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'En posición de gateo, llevá lentamente la pierna hacia atrás mientras estirás la rodilla.', 343),
  ('CUATRO APOYOS - EXTENSIÓN DE CADERA Y DESPUÉS ABDUCCIÓN', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá en posición de gateo. Elevá la pierna que vas a trabajar hacia arriba y atrás mientras estirás la rodilla. Después, alejá la pierna de la línea media y mantené. Volvé a la posición inicial y repetí.', 161459),
  ('CUATRO APOYOS - ELEVACIONES DE MULTÍFIDOS', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'En posición de gateo y con una rodilla sobre una superficie elevada, despegá la otra rodilla del piso usando los músculos de la zona lumbar. Después, volvé a la posición original.', 12910),
  ('CRUNCH INVERTIDO - RODILLAS FLEXIONADAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba con las rodillas flexionadas. Elevá las piernas y la cola mientras llevás las rodillas hacia el pecho. Bajá y repetí. Asegurate de mantener la espalda alta y los omóplatos apoyados en el piso todo el tiempo.', 169170),
  ('CRUNCH INVERTIDO - RODILLAS ESTIRADAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba. Manteniendo las rodillas estiradas, los hombros apoyados en el piso y usando solamente los músculos abdominales, elevá las piernas y la cola del piso, como se muestra. Bajá las piernas y repetí.', 169167),
  ('EMPUJE EN CRUNCH INVERTIDO - RODILLA FLEXIONADA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate en el piso con las rodillas flexionadas a aproximadamente 90 grados. Empezá elevando la cola y las piernas del piso usando los músculos abdominales, como se muestra. Volvé a la posición inicial y repetí.', 165458),
  ('CRUNCHS DIAGONALES INVERTIDOS', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba con las rodillas flexionadas. Elevá las piernas y la cola hacia un hombro. Bajá y después llevá las rodillas hacia el hombro contrario. Repetí alternando los lados. Asegurate de mantener la espalda alta apoyada en el piso.', 169169),
  ('PLANCHA INVERTIDA - DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, elevá el cuerpo apoyándote sobre los codos y los talones. Tratá de mantener la columna derecha.', 279),
  ('PLANCHAS ROTATORIAS EN LA PARED - EJERCICIO DE CONCIENCIA DEL MOVIMIENTO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Apoyate contra una pared sobre los codos y después girá y rotá el cuerpo hacia el costado sin rotar la columna. Mantené los músculos abdominales contraídos. Pivoteá sobre los pies, como se muestra. Repetí del otro lado.', 39035),
  ('GIROS RUSOS - BALÓN MEDICINAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sostené un balón medicinal sentado en el piso con las piernas cruzadas. Despegá los pies del piso y rotá el tronco de lado a lado manteniendo la pelota por delante del pecho.', 168816),
  ('CRUNCH ABDOMINAL SENTADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentate en una silla y empezá elevando ambas rodillas, como se muestra. Después, extendé las piernas completamente estirando las rodillas. Luego, flexioná las caderas y las rodillas para volver con los pies a la posición inicial. Repetí.', 79099),
  ('PESO MUERTO SENTADO - LEVANTADAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentate en una silla con buena postura y una mancuerna sobre una superficie más baja, como un banquito, como se muestra. Después, inclinate hacia adelante manteniendo la espalda derecha y levantá la mancuerna. Mantené la mancuerna cerca del cuerpo mientras volvés a incorporarte. Para la repetición siguiente, inclinate hacia adelante manteniendo la espalda derecha y volvé a apoyar la mancuerna sobre el banquito. Volvé a la posición inicial sin la mancuerna, sentado erguido. Repetí alternando entre levantar y dejar la pesa en cada repetición.', 165028),
  ('CRUNCHS EN PLANCHA LATERAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado de costado, elevá el cuerpo apoyándote sobre el codo y los pies. Tratá de mantener la columna derecha. Mantené esta posición y apoyá la mano de arriba sobre la cabeza; después acercá el codo y la rodilla entre sí mientras bajás el codo y flexionás la cadera y la rodilla. Volvé con el brazo y la pierna a la posición inicial y repetí.', 67957),
  ('PUENTE A UNA PIERNA SOBRE ESCALÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba con las rodillas flexionadas y ambos pies sobre un escalón. Empezá despegando un pie del escalón y después presioná hacia abajo con el otro pie sobre el escalón y elevá la cola y la espalda del piso, como se muestra. Mantené la pelvis nivelada todo el tiempo. Mantené, volvé a la posición inicial y repetí.', 68192),
  ('PUENTE A UNA PIERNA SOBRE ESCALÓN - SÓLEO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba con las rodillas flexionadas y ambos pies sobre un escalón. Ubicá los pies de modo que solo los dedos y el antepié queden sobre el escalón y los talones queden por fuera del borde. Empezá despegando un pie del escalón y después presioná hacia abajo con los dedos del otro pie apoyado para elevar la cola y la espalda del piso, como se muestra. Mantené la pelvis nivelada todo el tiempo. Mantené, volvé a la posición inicial y repetí.', 68193),
  ('PARACAIDISTA', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostate boca abajo con los brazos al costado del cuerpo. Después, elevá al mismo tiempo el tronco, las piernas, los muslos y los brazos del piso, como se muestra. Podés colocar una almohada debajo del abdomen para mayor comodidad.', 5889),
  ('BRAZO Y PIERNA ALTERNADOS DE PIE - MESA', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Parate cerca de una mesa o mesada y apoyate sobre ella con los brazos. Después, elevá alternadamente un brazo y la pierna contraria manteniendo la columna estable y el core activado.', 46744),
  ('EMPUJE CON PIERNAS ESTIRADAS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, cruzá las piernas y elevalas derecho hacia arriba. Después, aplaná la zona lumbar de modo que impulse las piernas unos centímetros hacia el techo.', 550),
  ('EMPUJE CON PIERNAS ESTIRADAS - ROTACIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, cruzá las piernas y elevalas derecho hacia arriba. Después, aplaná la zona lumbar de modo que impulse las piernas unos centímetros hacia el techo. Manteniendo esta posición con la zona lumbar plana contra el piso, balanceá lentamente las piernas de lado a lado, como se muestra.', 551),
  ('DECÚBITO DORSAL 90/90 - ACTIVACIÓN PÉLVICA', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá aplanando la zona lumbar contra el piso. Mantené esta posición mientras elevás una pierna por vez hasta la posición de mesa, como se muestra. Las caderas y las rodillas deben quedar flexionadas a unos 90 grados. No dejes que la zona lumbar se arquee hacia arriba en ningún momento del ejercicio. Mantené, volvé a la posición original y repetí.', 76012),
  ('DECÚBITO DORSAL 90/90 CON DESCENSO BILATERAL DE PIERNAS - ACTIVACIÓN PÉLVICA', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá acostado boca arriba con las rodillas flexionadas y aplanando la pelvis y la zona lumbar contra el piso. Activá y mantené esta posición mientras elevás una pierna por vez hasta la posición de mesa, como se muestra. Las caderas y las rodillas deben quedar flexionadas a unos 90 grados. No dejes que la zona lumbar se arquee hacia arriba en ningún momento del ejercicio. Después, bajá ambas piernas hasta casi tocar el piso. Volvé con las piernas a la posición 90-90 y repetí.', 76049),
  ('MARCHA EN DECÚBITO DORSAL 90/90 - ACTIVACIÓN PÉLVICA', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá acostado boca arriba con las rodillas flexionadas y aplanando la pelvis y la zona lumbar contra el piso. Activá y mantené esta posición mientras elevás una pierna por vez hasta la posición de mesa, como se muestra. Las caderas y las rodillas deben quedar flexionadas a unos 90 grados. No dejes que la zona lumbar se arquee hacia arriba en ningún momento del ejercicio. Después, bajá una pierna hasta casi tocar el piso. Volvé esa pierna a la posición 90-90 y después repetí del otro lado.', 76013),
  ('ACTIVACIÓN EN DECÚBITO DORSAL - ELEVACIÓN DE AMBAS PIERNAS', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, colocá las manos debajo de la cola. Bascula la pelvis de modo que la zona lumbar se acerque al piso y mantené esta posición. Después, elevá las piernas en el aire de a una por vez y mantené la posición. Mantené la columna baja apoyada hacia el piso todo el tiempo. Si no podés controlar la columna hacia abajo, probá flexionando las rodillas mientras las elevás y mantené. Si perdés el control de la columna, el ejercicio es demasiado avanzado.', 34144),
  ('ABDUCCIÓN Y ADUCCIÓN DE CADERA CON PIERNAS ELEVADAS EN DECÚBITO DORSAL - ACTIVACIÓN PÉLVICA', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá acostado boca arriba con las rodillas flexionadas y aplanando la pelvis y la zona lumbar contra el piso. Activá y mantené esta posición mientras estirás las piernas hacia adelante y las despegás del piso. No dejes que la zona lumbar se arquee hacia arriba en ningún momento del ejercicio. Manteniendo las rodillas completamente extendidas (estiradas), abrí y cerrá las piernas sin tocar el piso, como se muestra.', 76051),
  ('PATADITAS EN DECÚBITO DORSAL - ACTIVACIÓN PÉLVICA', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá acostado boca arriba con las rodillas flexionadas y aplanando la pelvis y la zona lumbar contra el piso. Activá y mantené esta posición mientras estirás las piernas hacia adelante y las despegás del piso. No dejes que la zona lumbar se arquee hacia arriba en ningún momento del ejercicio. Manteniendo las rodillas completamente extendidas (estiradas), hacé patadas hacia arriba y abajo sin tocar el piso, como se muestra.', 76050),
  ('BÁSCULA PÉLVICA EN DECÚBITO DORSAL CON APRIETE DE PELOTA CHICA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostate boca arriba y hacé una báscula pélvica. Podés hacerlo usando los músculos abdominales para presionar la zona lumbar contra el piso o la colchoneta. Mantené esto mientras apretás una pelota chica de goma, una toalla enrollada o una almohada doblada entre las rodillas. Relajá las rodillas y los músculos abdominales y después repetí.', 106209),
  ('TIJERAS EN DECÚBITO DORSAL', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba, colocá las manos debajo de la cola. Bascula la pelvis de modo que la zona lumbar se acerque al piso y mantené esta posición. Después, elevá las piernas en el aire y movelas hacia arriba y abajo en un movimiento alternado de aleteo, como se muestra. Mantené la columna baja apoyada hacia el piso todo el tiempo. Si no podés controlar la columna hacia abajo, probá flexionando las rodillas mientras las subís y bajás para bajar la intensidad del ejercicio. Si perdés el control de la columna, el ejercicio es demasiado avanzado.', 34143),
  ('PLANCHA EN LA MESA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Parate frente a una mesa y después dá un paso hacia atrás con ambos pies mientras apoyás los codos sobre la mesa. Mantené la columna derecha mientras sostenés esta posición. Después dá pasos hacia adelante para volver a la posición de pie y repetí. Puede que necesites una almohada sobre la mesa si te resulta incómodo en los codos.', 83686),
  ('PLANCHA EN LA MESA - LATERAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Parate frente a una mesa y después dá un paso hacia atrás con ambos pies mientras apoyás los codos sobre la mesa. Mantené la columna derecha mientras sostenés esta posición. Después dá pasos hacia adelante para volver a la posición de pie y repetí. Puede que necesites una almohada sobre la mesa si te resulta incómodo en los codos.', 83687),
  ('ENTRENAMIENTO DE ACTIVACIÓN DEL TRANSVERSO ABDOMINAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Colocá 2 dedos a cada lado del abdomen, a la altura del ombligo, pero lo suficientemente separados como para NO estar sobre el recto abdominal (los músculos del six-pack). Hundí los dedos suavemente con el cuerpo relajado. Después, activá el músculo transverso abdominal haciendo una técnica de bracing (apretá la panza como si alguien te fuera a dar un golpe en el abdomen). Si lo hacés bien, los dedos van a ser empujados hacia afuera. Mantené, después relajá y repetí.', 66143),
  ('ENTRENAMIENTO DEL TRANSVERSO ABDOMINAL - ACTIVACIÓN SENTADO', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Esto se hace sentado. Presioná las puntas de los dedos sobre el abdomen relajado, al costado del ombligo. Después, activá y apretá el abdomen de modo que los músculos empujen las puntas de los dedos alejándolas del centro del cuerpo. Mantené, después relajá y repetí.', 86361),
  ('ENTRENAMIENTO DEL TRANSVERSO ABDOMINAL - ACTIVACIÓN DE PIE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Esto se puede hacer de pie o acostado. Presioná las puntas de los dedos sobre el abdomen relajado, al costado del ombligo. Después, activá y apretá el abdomen de modo que los músculos empujen las puntas de los dedos alejándolas del centro del cuerpo. Mantené, después relajá y repetí.', 47188),
  ('ENTRENAMIENTO DEL TRANSVERSO ABDOMINAL - ACTIVACIÓN EN DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Acostado boca arriba con las rodillas flexionadas, usá los pulgares o 2 dedos de cada mano para encontrar el hueso de la pelvis (espina ilíaca anterosuperior - EIAS). Una vez ubicada esa parte de la pelvis, movés los dedos 2 a 5 cm hacia arriba y hacia adentro desde ahí y presioná 2 dedos de cada lado suavemente hacia adentro en un ángulo de 45 grados. Después, apretá los músculos abdominales como si alguien te fuera a dar un golpe en la panza. Otra forma de pensar esta contracción es llevar el ombligo hacia abajo, hacia la camilla o la cama. Si lo hacés bien, los dedos deberían elevarse mientras el músculo los empuja hacia afuera. Mantené esta contracción y después relajá y repetí.', 81357),
  ('SUSPENSIÓN TRX - PIKE', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'De pie y de frente al anclaje del TRX, flexioná desde las caderas mientras te inclinás hacia atrás y después volvé a la posición de pie. Mantené la espalda y las rodillas derechas todo el tiempo.', 31410),
  ('SUSPENSIÓN TRX - PUENTE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentate en el piso de frente al anclaje del TRX y colocá las cintas en los talones. Una vez sujeto, acostate con las rodillas estiradas y elevá la cola del piso. Después, volvé a la posición inicial y repetí.', 32693),
  ('SUSPENSIÓN TRX - COMBO PUENTE CON CURL Y ABDUCCIÓN EN APERTURA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentate en el piso de frente al anclaje del TRX y colocá las cintas en los talones. Una vez sujeto, acostate con las rodillas estiradas y elevá la cola del piso. Mantené esta posición y después flexioná las rodillas para hacer un curl de isquiotibiales. Estirá las rodillas y después separá las piernas entre sí para hacer una apertura. Repetí todo esto manteniendo la cola despegada del piso. Mantené esta posición y después separá las piernas entre sí para hacer una apertura y después volvé a juntarlas.', 32689),
  ('SUSPENSIÓN TRX - PUENTE CON APERTURA - ABDUCCIÓN', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Sentate en el piso de frente al anclaje del TRX y colocá las cintas en los talones. Una vez sujeto, acostate con las rodillas estiradas y elevá la cola del piso. Mantené esta posición y después separá las piernas entre sí para hacer una apertura y después volvé a juntar las rodillas. Repetí todo esto manteniendo la cola despegada del piso.', 32692),
  ('SUSPENSIÓN TRX - INCLINACIÓN LATERAL DE TRONCO', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Sostené las manijas del TRX por encima de la cabeza con el anclaje hacia el costado del cuerpo. Después, inclinate lateralmente desde el tronco y volvé a la posición de pie erguida. Los brazos tienen que quedar quietos mientras el tronco es el responsable del movimiento.', 31427),
  ('SUSPENSIÓN TRX - BALANCEO EN CRUNCH EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado para colocar la cinta en los pies. Date vuelta para quedar de frente al piso y ponete en posición de flexión de brazos, como se muestra. Después, balanceate de lado a lado mientras llevás las rodillas hacia el costado, como se muestra. Si no llegás a la posición completa de balanceo que se ve en la foto, podés hacer balanceos parciales.', 31502),
  ('SUSPENSIÓN TRX - BALANCEO EN CRUNCH EN DECÚBITO VENTRAL SOBRE CODOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado para colocar la cinta en los pies. Date vuelta para acostarte en el piso y apoyate sobre los codos. Después, rotá la parte baja del cuerpo y las rodillas de lado a lado, como se muestra. Si no llegás a la posición completa de balanceo que se ve en la foto, podés hacer balanceos parciales.', 115038),
  ('SUSPENSIÓN TRX - RECOGIDA EN DECÚBITO VENTRAL SOBRE CODOS', NULL, true, 'activo', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado para colocar la cinta en los pies. Date vuelta para quedar de frente al piso, apoyate sobre los codos y suspendé el cuerpo. Después, llevá las rodillas hacia el pecho mientras enrollás la columna. Controlá el movimiento de vuelta a la posición inicial y repetí.', 31503),
  ('SUSPENSIÓN TRX - PIKE EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado para colocar la cinta en los pies. Date vuelta para quedar de frente al piso en posición de plancha completa de flexión de brazos. Mantené la posición de plancha con la columna neutra. Después, flexioná desde las caderas para elevar la cola hacia el techo. Mantené las rodillas estiradas todo el tiempo.', 31498),
  ('SUSPENSIÓN TRX - PLANCHA EN DECÚBITO VENTRAL - CODOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Colocá las cintas en los pies. Apoyate sobre los codos con la columna derecha. Mantené esta posición en columna neutra. Relajá y bajá la pelvis y el abdomen al piso, y después repetí.', 31501),
  ('SUSPENSIÓN TRX - PLANCHA EN DECÚBITO VENTRAL CON ABDUCCIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado para colocar la cinta en los pies. Date vuelta para quedar de frente al piso y apoyate sobre los codos con la columna derecha. Mantené esta posición en columna neutra. Después, separá las piernas y volvé a juntarlas, y repetí. Mantené las rodillas y la columna derechas todo el tiempo.', 31499),
  ('SUSPENSIÓN TRX - PLANCHA EN DECÚBITO VENTRAL CON BÁSCULA PÉLVICA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado para colocar la cinta en los pies. Date vuelta para quedar de frente al piso y apoyate sobre los codos con la columna derecha. Mantené esta posición en columna neutra y después redondeá la zona lumbar usando los músculos abdominales. Volvé a columna neutra y repetí. Mantené las rodillas estiradas todo el tiempo.', 31500),
  ('SOSTÉN EN V', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado con las piernas estiradas hacia adelante. Inclinate hacia atrás y elevá las piernas mientras apretás los músculos abdominales. Mantené, volvé a la posición inicial y repetí.', 161458),
  ('SOSTÉN EN V - ASISTIDO', NULL, true, 'activo_asistido; fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Empezá sentado con las piernas estiradas hacia adelante. Inclinate hacia atrás mientras elevás las piernas. Después, agarrate la parte de atrás de las rodillas para ayudarte a sostener las piernas arriba mientras apretás los músculos abdominales. Mantené, volvé a la posición inicial y repetí.', 161457),
  ('PUENTE EN LA PARED - EXTENSIÓN DE ESPALDA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Apoyate contra una pared. Activá y meté hacia adentro los músculos abdominales y después, de forma segmentaria, despegá de la pared la cola, después la zona lumbar y después la espalda alta. Mantené y después bajá de nuevo.', 39154),
  ('PLANCHA EN LA PARED - DE FRENTE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Parate de frente a una pared. Alejate un paso de la pared e inclinate contra ella apoyándote sobre los codos. Activá los músculos abdominales, los glúteos y los muslos, y mantené la columna derecha.', 39158),
  ('PLANCHA EN LA PARED - LATERAL', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Parate de costado a una pared, a medio metro de distancia. Alejate un paso de la pared e inclinate contra ella apoyándote sobre el codo. Activá los músculos abdominales, los glúteos y los muslos, y mantené la columna derecha.', 39160),
  ('SILLA DE RUEDAS - PUENTE', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Con los antebrazos o las manos sobre los apoyabrazos, activá los músculos abdominales bajos, apretá los glúteos y después elevá la cola de la silla formando un puente con el cuerpo. Mantené y después bajá y repetí.', 105311),
  ('SILLA DE RUEDAS - PUENTE - UNA PIERNA', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estabilización', 'Con los antebrazos o las manos sobre los apoyabrazos, activá los músculos abdominales bajos, apretá los glúteos y después elevá la cola de la silla formando un puente con el cuerpo. Mantené un pie en el piso para ayudarte a subir y bajar el cuerpo. Mantené y después bajá y repetí.', 105324),
  ('ESPALDA - ESTIRAMIENTO EN LA PILETA', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Parate cerca de una pileta u otro objeto firme que esté a la altura de la cintura. Agarrate del borde de adelante de la pileta e inclinate hacia atrás para estirar la espalda.', 77894),
  ('BOSU - ESTIRAMIENTO EN FLEXIÓN DE TRONCO SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Empezá sentado sobre un Bosu. Después, inclinate lentamente hacia adelante entre las piernas hasta sentir un estiramiento a lo largo de la espalda.', 5780),
  ('BOSU - EXTENSIÓN TORÁCICA Y ESTIRAMIENTO DE PECTORALES', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Empezá sentado con un Bosu detrás tuyo y los dedos tocando la parte de atrás de la cabeza. Después, acostate hacia atrás y extendé la espalda sobre el Bosu mientras abrís los codos hacia los costados, como se muestra.', 5787),
  ('ESTIRAMIENTO EN ROTACIÓN DE TRONCO CON PIERNAS CRUZADAS', NULL, true, 'pasivo', 'Lumbar y torácica', 'Estiramientos', 'Empezá sentado con las piernas cruzadas. Agarrá la rodilla contraria y rotá la columna hacia un lado siguiendo con la cabeza hasta sentir un estiramiento suave. Podés apoyar el otro brazo en el piso, detrás tuyo, para estabilizarte. Mantené, volvé a la posición inicial y repetí del otro lado.', 160177),
  ('GERIÁTRICO - ESTIRAMIENTO LATERAL DE TRONCO SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Sentado, elevá el brazo por encima de la cabeza e inclina el cuerpo hacia el costado para estirar la espalda y el brazo. Mantené, después volvé a la posición inicial y repetí.', 124517),
  ('GERIÁTRICO - ESTIRAMIENTO LUMBAR SENTADO - ESTIRAMIENTO EN FLEXIÓN DE TRONCO', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Sentado en una silla, empezá inclinándote lentamente hacia adelante y llevando las manos hacia el piso. Flexioná el tronco y la cabeza hacia el suelo. Mantené para estirar la espalda, después volvé a la posición inicial y repetí.', 124518),
  ('ESTIRAMIENTO DE DORSAL EN CAMILLA O CAMA', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Acostate de costado en una camilla o cama, como se muestra. Estirá el brazo por encima de la cabeza y agarrate del colchón, del respaldo o del borde de la camilla para estirar la espalda y el hombro.', 39438),
  ('ESTIRAMIENTO DE DORSAL EN CAMILLA O CAMA', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Acostate de costado con las piernas colgando por fuera de la camilla o cama, como se muestra. Estirá el brazo por encima de la cabeza y agarrate del colchón, del respaldo o del borde de la camilla para estirar la espalda y el hombro.', 39437),
  ('ESTIRAMIENTO LATERAL DE TRONCO - CUADRADO LUMBAR', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Parate con los pies en tándem, uno adelante del otro. Inclinate hacia una pared y sostenete con un brazo, como se muestra. Después, elevá el brazo contrario e inclinate hacia el costado, hacia la pared, para estirar el costado del cuerpo.', 75024),
  ('ESTIRAMIENTO LATERAL DE TRONCO CON CINTA MULTIANILLA', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'De pie, sostené una cinta de estiramiento por encima de la cabeza con los codos estirados, como se muestra. Después, inclinate hacia el costado mientras sostenés la cinta para estirar el costado del cuerpo.', 47193),
  ('ESTIRAMIENTO LUMBAR / ISQUIOTIBIALES - DE PIE - CON APOYO', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Empezá parado con los pies juntos y las manos apoyadas en el respaldo de una silla o en una mesada. Después, inclinate hacia adelante para un estiramiento suave de la zona lumbar y los isquiotibiales. Volvé a la posición inicial y repetí.', 79115),
  ('EMBARAZO - ESTIRAMIENTO DE PLEGARIA - POSTURA DEL NIÑO', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Empezá en posición de gateo y después bajá lentamente la cola hacia los talones hasta sentir un estiramiento a lo largo de la espalda o de los glúteos. Asegurate de separar bien las rodillas para dejar lugar a la panza. Subí a la posición inicial y repetí.', 179629),
  ('ESTIRAMIENTO DE CUADRADO LUMBAR Y TFL - CUATRO APOYOS', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Empezá en posición de gateo y deslizá la pierna hacia atrás hasta que la rodilla quede estirada. Dejá que la pelvis de ese lado caiga hacia el piso. Mantené los codos estirados mientras estirás la zona lumbar y la cadera. Mantené, volvé a la posición inicial y repetí.', 156244),
  ('ESTIRAMIENTO DE CUADRADO - SENTADO CON PIERNAS CRUZADAS', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Sentate con las piernas cruzadas, como se muestra. Después, elevá el brazo por encima de la cabeza y hacia el costado mientras inclinás el tronco lateralmente hasta sentir un estiramiento suave a lo largo del costado de la zona lumbar.', 61152),
  ('ESTIRAMIENTO DE DORSAL EN CUATRO APOYOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estiramientos', 'Empezá en posición de gateo. Bajá el pecho y la cabeza hacia el piso mientras colocás el brazo al costado de la cabeza. Podés sentir un estiramiento suave en el hombro o la espalda alta. El antebrazo y el codo tienen que quedar apoyados en el piso durante este estiramiento. Mantené, volvé a la posición inicial y repetí.', 39436),
  ('ESTIRAMIENTO LATERAL DE TRONCO EN CUATRO APOYOS', NULL, true, 'fortalecimiento', 'Lumbar y torácica', 'Estiramientos', 'En posición de gateo, sobre las manos y las rodillas, inclina el tronco y la cabeza hacia un costado hasta sentir un estiramiento.', 283),
  ('ESTIRAMIENTO DE CUADRADO LUMBAR EN REPOSO CONTRA LA PARED', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Parate con los pies juntos y alejado de la pared. Empezá inclinando la cadera y el tronco contra la pared y elevá el brazo por encima de la cabeza. Después, hacé un estiramiento en inclinación lateral alejándote de la pared mientras deslizás la otra mano por el costado de la pierna. No te inclines hacia adelante ni hacia atrás con el tronco. Mantené para un estiramiento suave, después volvé a la posición inicial y repetí.', 164805),
  ('ESTIRAMIENTO LATERAL DE TRONCO SENTADO I', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Sentado, elevá el brazo por encima de la cabeza e inclina el cuerpo hacia el lado contrario para estirar. Mantené, volvé a la posición inicial y repetí.', 24204),
  ('ESTIRAMIENTO EN ROTACIÓN DE TRONCO SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Sentado, rotá el cuerpo hacia el costado y mantené para estirar.', 24205),
  ('ESTIRAMIENTO DE TRONCO EN INCLINACIÓN Y FLEXIÓN - DE PIE', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Parate frente a una mesa e inclinate hacia adelante desde la cintura. Sostenete con las manos sobre la mesa, como se muestra. Después, caminá lentamente con las manos hacia el costado para un estiramiento suave.', 24217),
  ('ESTIRAMIENTO DE CUADRADO LUMBAR EN DECÚBITO LATERAL - ESTIRAMIENTO DE QL', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Empezá acostado de costado con las rodillas flexionadas. Después, bajá las piernas por el borde de adelante de la camilla o cama y dejá que la pelvis se incline para estirar la zona lumbar.', 11806),
  ('ESTIRAMIENTO DE CUADRADO LUMBAR EN DECÚBITO LATERAL - UNA PIERNA - QL SIMPLE', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Empezá acostado de costado con las rodillas flexionadas. Después, bajá la pierna de arriba por el borde de adelante de la camilla o cama y dejá que la pelvis se incline para estirar la zona lumbar.', 11807),
  ('POSTURA DEL GUERRERO CON ALCANCE LATERAL - SENTADO', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Empezá sentado en una silla con los brazos elevados hacia los costados y las piernas separadas. Extendé una pierna hacia adelante y elevá el brazo del mismo lado hacia el techo mientras te inclinás hacia el lado contrario para un estiramiento suave. Mantené esta posición con la postura erguida, relajá y repetí.', 177808),
  ('PIES EN TIJERA - ESTIRAMIENTO LATERAL DE TRONCO', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Dá un paso adelante con una pierna y mantené esta posición. Después, elevá el brazo por encima de la cabeza e inclinate hacia el costado hasta sentir un estiramiento a lo largo del costado del cuerpo.', 24200),
  ('ESTIRAMIENTO EN ROTACIÓN DE TRONCO BILATERAL', NULL, true, 'pasivo', 'Lumbar y torácica', 'Estiramientos', 'Empezá acostado boca arriba con las rodillas flexionadas. Después, dejá caer lentamente las rodillas hacia un costado mientras rotás desde la columna, para un estiramiento suave. Después rotá hacia el otro lado para un estiramiento suave. Repetí alternando los lados.', 83249),
  ('SUSPENSIÓN TRX - ESTIRAMIENTO LUMBAR', NULL, true, 'activo', 'Lumbar y torácica', 'Estiramientos', 'Sostené las manijas del TRX de frente al anclaje. Inclinate hacia adelante para estirar la zona lumbar.', 31414),
  ('SENTADILLA TRASERA - BARRA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parate y agarrá la barra un poco más abierto que el ancho de los hombros. Sacá la barra del soporte y dá un paso atrás. Apoyá la barra sobre la parte de atrás de los hombros. Colocá los pies aproximadamente al ancho de los hombros y después hacé una sentadilla. Empujá con los talones mientras empezás a subir a la posición de pie con las rodillas completamente estiradas. Mantené la columna derecha mientras flexionás desde las caderas y las rodillas. Volvé a la posición de pie y repetí.', 155493),
  ('APRIETE DE PELOTA EN ADUCCIÓN DE CADERA - SENTADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Sentado en una silla, colocá una pelota entre las rodillas. Apretá la pelota con las rodillas y mantené. Relajá y repetí.', 17390),
  ('BARRA - SENTADILLA FRONTAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parate y agarrá la barra un poco más abierto que el ancho de los hombros. Sacá la barra del soporte y dá un paso atrás. Apoyá la barra sobre la parte de adelante de los hombros. Colocá los pies aproximadamente al ancho de los hombros y después hacé una sentadilla. Empujá con los talones mientras empezás a subir a la posición de pie con las rodillas completamente estiradas.', 155330),
  ('BURPEE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá en posición de pie. Después, flexioná las rodillas y bajá hacia el piso. Apoyá las manos en el piso mientras estirás las piernas de modo que quedes en posición de plancha con los dedos de los pies y las manos tocando el piso. Mantené la columna derecha y no dejes que la espalda se hunda. Después, invertí el movimiento, volvé a flexionar las rodillas y pararte de nuevo.', 41808),
  ('PASO SOBRE CONOS - ADELANTE Y ATRÁS', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Colocá conos, vasos u otros objetos chicos en el piso, separados de forma pareja. Empezando con la pierna afectada, pasá por encima de cada cono con un paso de rodilla alta, como se muestra. Cuando llegues al final, volvé a la posición original pasando hacia atrás por encima de los conos, empezando con la pierna afectada.', 7343),
  ('PASO SOBRE CONOS - LATERAL', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Colocá conos, vasos u otros objetos chicos en el piso, separados de forma pareja. Pasá de costado por encima de cada cono con un paso de rodilla alta, como se muestra. Cuando llegues al final, volvé a la posición original pasando por encima de los conos en la dirección contraria.', 7344),
  ('SALTO CON DOS PIERNAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parate sobre ambas piernas y después saltá hacia adelante y caé sobre ambos pies. Aumentá la distancia o la altura del salto para progresar este ejercicio.', 76601),
  ('CARGADA CON MANCUERNA Y ESTOCADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parate con los pies un poco más separados que el ancho de los hombros. Inclinate y levantá una pesa hasta la altura del hombro, como se muestra. Sosteniendo la mancuerna, dá un paso adelante en posición de estocada. Después, dá un paso atrás y hacé sentadilla para volver a apoyar la mancuerna en el piso. Repetí.', 154816),
  ('BANDA ELÁSTICA - ALMEJAS SENTADO - ABDUCCIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Sentado en una silla, colocá una banda elástica circular alrededor de los muslos, cerca de las rodillas, como se muestra. Empezá llevando ambas rodillas hacia afuera para separar las piernas. Volvé a la posición inicial y repetí. Mantené los pies en contacto con el piso todo el tiempo.', 8095),
  ('VENDAJE ELÁSTICO - INESTABILIDAD DE LCA', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 74041),
  ('VENDAJE ELÁSTICO - SOPORTE DE ISQUIOTIBIALES', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 74049),
  ('VENDAJE ELÁSTICO - SOPORTE DE BANDA ILIOTIBIAL - ALIVIO DEL DOLOR', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73826),
  ('VENDAJE ELÁSTICO - DOLOR DE RODILLA - SOPORTE DE CUÁDRICEPS', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73839),
  ('VENDAJE ELÁSTICO - SOPORTE DE RENDIMIENTO DE RODILLA', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 74053),
  ('VENDAJE ELÁSTICO - SOPORTE DE RENDIMIENTO DE RODILLA', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 74052),
  ('VENDAJE ELÁSTICO - ESTABILIDAD DE LCM - SOPORTE DE RODILLA', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 74058),
  ('VENDAJE ELÁSTICO - CARA POSTERIOR DE LA RODILLA', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75008),
  ('PELOTA DE EJERCICIOS - SENTADILLAS EN LA PARED', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá de pie apoyando la zona lumbar contra una pelota de ejercicios sobre una pared. Mantené los pies separados al ancho de los hombros. Después, flexioná lentamente las rodillas y bajá la cola hacia el piso. Volvé a la posición de pie y repetí. Las rodillas tienen que flexionarse alineadas con el segundo dedo del pie y no pasar la punta del pie.', 522),
  ('RODILLO DE ESPUMA - PANTORRILLAS', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Empezá sentado con el rodillo debajo de la pantorrilla afectada y cruzá la otra pierna por encima. Después, elevá el cuerpo con los brazos y rodá hacia adelante y atrás por la zona de la pantorrilla.', 481),
  ('RODILLO DE ESPUMA - PANTORRILLAS BILATERAL', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Empezá sentado con el rodillo debajo de las pantorrillas. Después, elevá el cuerpo con los brazos y rodá hacia adelante y atrás por las pantorrillas.', 482),
  ('RODILLO DE ESPUMA - GLÚTEO - PIRAMIDAL', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Empezá sentado sobre un rodillo de espuma y cruzá la pierna afectada sobre la otra rodilla, como se muestra. Inclinate levemente hacia el lado afectado. Después, usando los brazos y la pierna sana, rodá hacia adelante y atrás por la zona del glúteo.', 483),
  ('RODILLO DE ESPUMA - ISQUIOTIBIALES BILATERAL', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Empezá sentado sobre un rodillo de espuma ubicado debajo de ambos muslos. Después, usando los brazos, rodá hacia adelante y atrás por esa zona.', 484),
  ('RODILLO DE ESPUMA - ISQUIOTIBIALES UNA PIERNA', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Empezá sentado sobre un rodillo de espuma ubicado debajo del muslo que querés trabajar. Después, usando los brazos, rodá hacia adelante y atrás por esa zona.', 485),
  ('RODILLO DE ESPUMA - ADUCTORES DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Acostate boca abajo con un rodillo de espuma en diagonal debajo de la cara interna del muslo afectado. Usá los brazos para rodar hacia arriba y abajo por la pierna.', 486),
  ('RODILLO DE ESPUMA - BANDA ILIOTIBIAL - ITB', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Empezá de costado con un rodillo de espuma debajo del muslo de abajo. Después, usando los brazos y la pierna sana, rodá hacia arriba y abajo sobre el rodillo a lo largo de la cara lateral del muslo.', 487),
  ('RODILLO DE ESPUMA - CUÁDRICEPS UNA PIERNA', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Empezá acostado boca abajo de modo que el rodillo de espuma quede debajo de la parte de arriba del muslo afectado. Cruzá la otra pierna por encima de la pierna afectada, como se muestra. Después, apoyándote sobre los codos con los brazos, rodá hacia adelante y atrás por esa zona.', 488),
  ('RODILLO DE ESPUMA - CUÁDRICEPS', NULL, true, 'sin_clasificar', 'Cadera y rodilla', NULL, 'Empezá acostado boca abajo de modo que el rodillo de espuma quede debajo de la parte de arriba de los muslos. Después, apoyándote sobre los codos con los brazos, rodá hacia adelante y atrás por esa zona.', 489),
  ('DESLIZAMIENTOS DE PIE - TOALLA - RI / RE DE CADERA ASISTIDA', NULL, true, 'activo_asistido', 'Cadera y rodilla', NULL, 'Sentate en una silla y apoyá el pie sobre una toalla de mano que esté en el piso. Deslizá el pie de lado a lado dejando que la cadera rote. Usá la mano para ayudarte empujando y tirando.', 162074),
  ('DESLIZAMIENTOS DE PIE - TOALLA - FLEXIÓN / EXTENSIÓN DE RODILLA ASISTIDA', NULL, true, 'activo_asistido', 'Cadera y rodilla', NULL, 'Sentate en una silla y apoyá el pie sobre una toalla de mano que esté en el piso. Deslizá el pie dejando que la rodilla se flexione y se estire. Usá la mano para ayudarte empujando y tirando.', 162073),
  ('GERIÁTRICO - APRIETE DE PELOTA EN ADUCCIÓN DE CADERA - SENTADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Sentate en una silla y sostené una pelota entre las rodillas. Apretá la pelota con las rodillas y mantené. Relajá y repetí.', 124249),
  ('GERIÁTRICO - DE SENTADO A DE PIE', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Sentate cerca del borde de adelante de una silla. Después, estirá los brazos hacia adelante e inclinate hacia adelante desde la cintura mientras empujás hacia abajo con las piernas y te levantás hasta quedar de pie. A medida que subís, bajá los brazos a los costados. Parate erguido. Después, volvé a sentarte en la silla inclinándote hacia adelante mientras elevás los brazos. Repetí. NOTA: si no podés pararte, probá empujando sobre los muslos con los brazos, o usá una silla con apoyabrazos para empujar hacia abajo, o agarrate de una pileta del baño o de la cocina para ayudarte a subir.', 124258),
  ('DISCO DESLIZANTE - ESTOCADA ALTERNADA ADELANTE Y ATRÁS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parate sobre un disco deslizante con ambas piernas. Después, deslizá un lado hacia atrás hasta la posición de estocada invertida y después deslizalo hacia adelante hasta la posición de estocada frontal. Repetí.', 43353),
  ('DISCO DESLIZANTE - SENTADILLAS DINÁMICAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parate con discos deslizantes debajo de cada pie y los pies juntos. Después, deslizá los discos hacia afuera, hacia los costados, mientras flexionás las rodillas y bajás la cola hacia el piso en posición de sentadilla, como se muestra. Volvé a la posición original de pie mientras deslizás los discos juntándolos de nuevo. Repetí.', 43359),
  ('DISCO DESLIZANTE - ESTOCADA HACIA ADELANTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parate con un disco deslizante debajo de cada pie y después deslizá un lado hacia adelante hasta quedar con la rodilla flexionada, como se muestra. Volvé a la posición original y repetí.', 43352),
  ('DISCO DESLIZANTE - PATADAS AL FRENTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Colocá discos deslizantes debajo de los pies y, en posición de pie, deslizá un pie hacia adelante mientras deslizás el otro hacia atrás; después invertí la dirección de cada pie. Hacelo rápido y con recorrido corto. Los brazos deben balancearse en dirección opuesta al pie que se desliza.', 43371),
  ('DISCO DESLIZANTE - CURLS DE ISQUIOTIBIALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Acostate boca arriba con un disco deslizante debajo de cada pie. Después, flexioná ambas rodillas y hacé un puente elevando la cola del piso. Después, estirá las piernas y mantené la cola despegada todo el tiempo. Después flexioná las rodillas de nuevo y repetí.', 43362),
  ('DISCO DESLIZANTE - ALMEJAS ARRODILLADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Colocá discos deslizantes debajo de las rodillas mientras te arrodillás sobre ellos. Empezando con las rodillas juntas, deslizá los discos y las rodillas hacia afuera y después volvé a juntarlas. Repetí.', 43364),
  ('DISCO DESLIZANTE - CAMINATA DE MONSTRUO LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parate con discos deslizantes debajo de ambos pies. Flexioná las rodillas para bajar la cola hacia el piso. Después, deslizá una pierna hacia el costado y desplazate lateralmente mientras acercás la otra pierna, y repetí. Después de unos pasos deslizados, movete en la dirección contraria.', 43365),
  ('DISCO DESLIZANTE - CAMINATA DE MONSTRUO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parate con discos deslizantes debajo de ambos pies. Flexioná las rodillas para bajar la cola hacia el piso. Empezá deslizando una pierna hacia adelante. Después deslizá la otra pierna hacia adelante y repetí mientras el cuerpo avanza. Después de unos pasos deslizados, deslizate hacia atrás para volver a la posición inicial.', 43367),
  ('DISCO DESLIZANTE - ESCALADOR', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Colocá discos deslizantes debajo de cada pie y empezá en posición de plancha con manos y pies en contacto con el piso, boca abajo. Después, flexioná la rodilla y la cadera de un lado hacia el pecho, como se muestra, y después estirala mientras flexionás la del otro lado. Mantené la columna derecha todo el tiempo. Repetí este movimiento alternando ambas piernas.', 43357),
  ('DISCO DESLIZANTE - ABDUCCIÓN EN PLANCHA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Colocá discos deslizantes debajo de cada pie y empezá en posición de plancha con manos y pies en contacto con el piso, boca abajo. Mantené la columna derecha mientras deslizás las piernas separándolas y después volvés a juntarlas. Repetí.', 43368),
  ('DISCO DESLIZANTE - ESCALADOR INVERTIDO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Sentate en el piso y colocá discos deslizantes debajo de cada talón. Elevá el cuerpo apoyándote sobre las manos y los talones, en posición de plancha invertida. Después, flexioná la rodilla de un lado y después estirá la otra, como si pedalearas. Alterná y repetí.', 43370),
  ('DISCO DESLIZANTE - PATINADOR', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parate con un disco deslizante debajo de cada pie. Después, deslizá una pierna hacia el costado mientras estirás el brazo del mismo lado hacia adelante, en dirección al pie contrario. Volvé a la posición de pie y repetí.', 43366),
  ('DISCO DESLIZANTE - ABDUCCIÓN Y ADUCCIÓN EN PLANCHA SUPINA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Colocá discos deslizantes debajo de cada talón, en posición sentada con las piernas estiradas. Después, elevá la cola de modo que solo las manos y los talones sostengan el peso del cuerpo. Mantené la columna derecha mientras deslizás las piernas separándolas y después volvés a juntarlas. Repetí.', 43372),
  ('ACTIVACIÓN DE GLÚTEOS - DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Acostado boca arriba, apretá los glúteos y mantené. Repetí.', 22421),
  ('ACTIVACIÓN DE GLÚTEOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Acostado boca abajo, apretá los glúteos.', 329),
  ('ESTIRAMIENTO DE FLEXORES DE CADERA EN MEDIA RODILLA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Arrodillado sobre una rodilla, inclinate hacia adelante y flexioná la rodilla de adelante hasta sentir un estiramiento en la parte anterior de la cadera del lado de la rodilla apoyada.', 112),
  ('ACTIVACIÓN DE ISQUIOTIBIALES', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Acostate boca arriba y después flexioná la rodilla. Después, presioná el talón contra el piso y mantené. Relajá y repetí.', 114),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES', NULL, true, 'pasivo', 'Cadera y rodilla', NULL, 'Acostado boca arriba, elevá la pierna y agarrá la parte de atrás de la rodilla. Tirá de la pierna hacia arriba hasta sentir un estiramiento. Mantené, relajá y repetí.', 4735),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES - MESA, CAMA O SILLÓN', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Sentate en una superficie plana elevada donde puedas apoyar la pierna afectada, como una camilla, un sillón o la cama. Manteniendo la rodilla estirada o apenas flexionada, inclinate lentamente hacia adelante y llevá las manos hacia el pie hasta sentir un estiramiento suave en la parte de atrás de la rodilla y el muslo. Mantené, volvé a la posición inicial y repetí.', 46072),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES CON CINTA MULTIANILLA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Acostate boca arriba y colocá una cinta de estiramiento en el pie. Tirá de la cinta para ayudarte a elevar la pierna y estirar la parte de atrás. Mantené la pierna que trabajás estirada o apenas flexionada todo el tiempo.', 38887),
  ('DESLIZAMIENTOS DE TALÓN - SENTADO CON TOALLA Y CINTO', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'En posición sentada, colocá una toalla chica debajo del talón. Después, pasá un cinto, una toalla o una sábana alrededor del pie y tirá para llevar la rodilla a flexión mientras el pie se desliza hacia la cola. Mantené un estiramiento suave y después volvé a la posición original.', 119),
  ('ABDUCCIÓN DE CADERA - DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Acostado boca arriba, llevá lentamente la pierna hacia el costado. Mantené la rodilla estirada todo el tiempo.', 123),
  ('ADUCCIÓN DE CADERA CON ALMOHADA - DECÚBITO DORSAL CON RODILLAS FLEXIONADAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Acostate boca arriba con las rodillas flexionadas. Colocá una almohada doblada entre las rodillas y apretá las rodillas para comprimirla con firmeza. Mantené, después soltá y repetí.', 69301),
  ('FLEXIÓN DE CADERA - DE PIE - ELEVACIÓN DE PIERNA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parado al lado de una silla o mesada para apoyarte, elevá una pierna hacia adelante despegándola del piso con la rodilla estirada. Volvé a la posición inicial y repetí.', 7001),
  ('PROM DE CADERA - ABDUCCIÓN Y ADUCCIÓN', NULL, true, 'pasivo', 'Cadera y rodilla', NULL, 'La persona debe estar completamente relajada mientras el cuidador hace todo el trabajo (rango de movimiento pasivo) para mover la pierna. Agarrá la pierna sosteniendo por debajo del muslo y del tobillo, después llevala suavemente hacia afuera y volvé a la posición original, y repetí.', 27177),
  ('PROM DE CADERA - FLEXIÓN Y EXTENSIÓN', NULL, true, 'pasivo', 'Cadera y rodilla', NULL, 'La persona debe estar completamente relajada mientras el cuidador hace todo el trabajo (rango de movimiento pasivo) para mover la pierna. Agarrá la pierna sosteniendo por debajo del muslo y del tobillo, después flexioná suavemente la rodilla y la cadera hacia arriba, como se muestra, y volvé a la posición original, y repetí.', 27181),
  ('PROM DE CADERA - ROTACIÓN', NULL, true, 'pasivo', 'Cadera y rodilla', NULL, 'La persona debe estar completamente relajada mientras el cuidador hace todo el trabajo (rango de movimiento pasivo) para mover la pierna. Agarrá la pierna sosteniendo por debajo del muslo y del tobillo, después flexioná suavemente la rodilla y rotá la cadera repetidamente, como se muestra.', 27182),
  ('TROTE EN EL LUGAR', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Trotá en el lugar moviendo los brazos y las piernas como si trotaras, pero sin avanzar.', 47189),
  ('SALTO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Saltá hacia arriba con ambas piernas. Caé al piso con ambas piernas. Repetí.', 82533),
  ('KETTLEBELL - PLIOMETRÍA 90 90', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Sosteniendo una kettlebell a la altura del pecho, saltá 90 grados hacia el costado y caé en sentadilla. Después, hacelo de nuevo en la otra dirección para volver a quedar mirando hacia adelante. Después, saltá en la dirección contraria y volvé a saltar hacia el frente. Alterná las direcciones y repetí.', 28612),
  ('DESCOMPRESIÓN DE RODILLA', NULL, true, 'pasivo', 'Cadera y rodilla', NULL, 'Ponete una tobillera con peso y dejá que la pierna cuelgue por el borde de una silla alta o una mesa firme, y relajate. Colocá una almohada debajo del muslo para aumentar el efecto de tracción. Dejá que el peso de la pierna y de la tobillera generen un estiramiento suave en la rodilla.', 66770),
  ('ESCALERA DE AGILIDAD - 2 PASOS', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá parado de frente a la escalera de agilidad. Flexioná las rodillas y los codos. Pisá con cada pie alternadamente dentro de cada cuadro mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45599),
  ('ESCALERA DE AGILIDAD - IDA Y VUELTA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá parado al costado de la escalera de agilidad, con el cuerpo mirando hacia ella. Flexioná las rodillas y los codos. Pisá el primer cuadro con un pie y después salí hacia afuera de la escalera con cada pie alternadamente. Después, retrocedé pisando el segundo cuadro con un pie y pasá al otro lado con ambos pies alternadamente. Repetí esta secuencia mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45600),
  ('ESCALERA DE AGILIDAD - CARIOCA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá parado al frente de la escalera de agilidad con el costado del cuerpo mirando hacia ella. Flexioná las rodillas y los codos. Cruzá la pierna de atrás por delante de la de adelante y metela en el primer cuadro. Después destrabá las piernas y llevá la otra pierna al segundo cuadro. Después, llevá la pierna de atrás por detrás de la de adelante y metela en el tercer cuadro. Destrabá llevando la otra pierna al cuarto cuadro. Repetí esta secuencia alternando la pierna de atrás por delante y por detrás mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45601),
  ('ESCALERA DE AGILIDAD - DOBLE SALTO HACIA ADELANTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado de frente al inicio de la escalera de agilidad. Flexioná las rodillas y los codos. Saltá con ambos pies dentro del primer cuadro y después saltá con ambos pies al segundo cuadro. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 46151),
  ('ESCALERA DE AGILIDAD - SALTOS EN SLALOM CON DOS PIERNAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado en la esquina superior de la escalera de agilidad mirando hacia adelante. Flexioná las rodillas y los codos. Saltá con ambos pies dentro del primer cuadro y después saltá hacia afuera, al otro lado, con ambos pies. Después, saltá con ambos pies dentro del segundo cuadro y después saltá con ambos pies hacia afuera, al otro lado. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45605),
  ('ESCALERA DE AGILIDAD - DOBLE PROBLEMA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá parado frente a la escalera de agilidad mirando hacia adelante. Flexioná las rodillas y flexioná los codos. Pisá con cada pie alternadamente dentro del primer cuadro y después pisá con cada pie afuera de la escalera, uno de cada lado. Repetí esta secuencia mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45606),
  ('ESCALERA DE AGILIDAD - RAYUELA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado al frente de la escalera de agilidad, mirando hacia ella con las piernas separadas. Flexioná las rodillas y flexioná los codos. Saltá con un pie dentro del primer cuadro. Después, saltá con ambos pies hacia afuera de la escalera. Después, saltá con un pie (el contrario al que cayó en el primer cuadro) dentro del segundo cuadro. Después, saltá de nuevo con ambos pies al costado de la escalera. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45607),
  ('ESCALERA DE AGILIDAD - ICKEY SHUFFLE', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá parado en la esquina superior de la escalera de agilidad mirando hacia adelante. Flexioná las rodillas y flexioná los codos. Pisá el primer cuadro con el pie más cercano a la escalera y después pisá el mismo cuadro con el otro pie. Después, salí de la escalera hacia el otro lado con el mismo pie con el que empezaste. Después, repetilo en la otra dirección: pisá el segundo cuadro con el pie más cercano a la escalera y después entrá con el otro pie. Después, salí de la escalera hacia el otro lado con un pie. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45626),
  ('ESCALERA DE AGILIDAD - ADENTRO Y AFUERA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá parado en la esquina superior de la escalera de agilidad con el cuerpo mirando hacia ella. Pisá el primer cuadro con el pie más cercano a la escalera y después con el otro pie, alternando. Después, retrocedé y salí de la escalera con el pie de adelante y después, alternando, con el otro pie. Repetí esta secuencia en el segundo cuadro y seguí avanzando por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45628),
  ('ESCALERA DE AGILIDAD - ESTOCADAS CON SALTO EN TIJERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado al costado de la escalera de agilidad, mirando hacia ella. Saltá a posición de estocada de modo que un pie caiga en el primer cuadro y la otra pierna caiga detrás tuyo, afuera de la escalera. En la posición de estocada, no dejes que la rodilla de adelante pase los dedos del pie y mantené la rodilla alineada con los dedos. Después, saltá y cambiá de pierna para que el pie contrario caiga adelante, en el mismo primer cuadro, y flexioná las rodillas en estocada otra vez. Repetí esta secuencia saltando a estocada en el segundo cuadro con el pie contrario, volvé a saltar cambiando en el mismo cuadro y después seguí y repetí mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45629),
  ('ESCALERA DE AGILIDAD - SALTOS EN TIJERA - ALI SHUFFLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado en la esquina superior de la escalera de agilidad con el cuerpo mirando en dirección a la escalera. Saltá de modo que un pie caiga en el primer cuadro y la otra pierna caiga detrás tuyo, afuera de la escalera. Después, saltá y cambiá de pierna para que el pie contrario caiga adelante, en el primer cuadro, y el otro pie caiga afuera del cuadro, detrás tuyo. Repetí esta secuencia saltando al segundo cuadro con el pie contrario. Repetilo mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45630),
  ('ESCALERA DE AGILIDAD - SALTO EN UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado de frente a la escalera de agilidad. Flexioná las rodillas y los codos. Parate en una pierna y saltá dentro del primer cuadro. Después saltá al segundo cuadro con el mismo pie. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45636),
  ('ESCALERA DE AGILIDAD - SALTO EN UNA PIERNA ADENTRO Y AFUERA - MEDIAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado cerca del frente de la escalera de agilidad, mirando hacia ella. Flexioná las rodillas y los codos. Equilibrate en una pierna (la más alejada de la escalera) y saltá dentro del primer cuadro. Después, saltá hacia atrás saliendo del cuadro y después saltá dentro del segundo cuadro con el mismo pie. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45637),
  ('ESCALERA DE AGILIDAD - SALTOS A HORCAJADAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado frente a la escalera de agilidad mirando hacia adelante y con las piernas separadas. Flexioná las rodillas y flexioná los codos. Saltá con ambos pies dentro del primer cuadro. Después, saltá afuera del cuadro con cada pie a un lado. Repetilo en el cuadro siguiente: saltá con ambos pies dentro del segundo cuadro y después saltá afuera del cuadro con cada pie a un lado. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45640),
  ('ESCALERA DE AGILIDAD - DESPLAZAMIENTO LATERAL DE DOS PASOS', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá parado de costado frente a la escalera de agilidad. Flexioná las rodillas y los codos. Pisá con cada pie alternadamente dentro de cada cuadro mientras te desplazás lateralmente por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45598),
  ('CAMINATA DE MONSTRUO LATERAL - BANDA ELÁSTICA EN LOS TOBILLOS - PASOS LATERALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Colocá una banda elástica circular alrededor de ambos tobillos. Después, flexioná las rodillas y dá pasos hacia el costado manteniendo la tensión de la banda todo el tiempo. Después de dar varios pasos laterales en una dirección, invertí la dirección dando pasos laterales hasta volver a la posición inicial. Repetí.', 448),
  ('CAMINATA DE MONSTRUO LATERAL - BANDA ELÁSTICA EN LOS MUSLOS - PASOS LATERALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Colocá una banda elástica circular alrededor de ambos muslos. Después, flexioná las rodillas y dá pasos hacia el costado manteniendo la tensión de la banda todo el tiempo. Después de dar varios pasos laterales en una dirección, invertí la dirección dando pasos laterales hasta volver a la posición inicial. Repetí.', 9460),
  ('ABDUCCIÓN DE CADERA CON BANDA ELÁSTICA CIRCULAR', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'De pie con una banda elástica circular alrededor de los tobillos, llevá la pierna que trabajás hacia el costado, como se muestra.', 8074),
  ('ESTOCADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado con los pies separados al ancho de los hombros. Después, dá un paso hacia adelante y apenas hacia afuera, y dejá que la rodilla de adelante se flexione. La rodilla de atrás también puede flexionarse. Después, volvé a la posición original y repetí con la misma pierna. Mantené la pelvis nivelada y derecha todo el tiempo. La rodilla de adelante tiene que flexionarse alineada con el segundo dedo del pie y no pasar la punta del pie.', 4668),
  ('BALÓN MEDICINAL - ESTOCADA CON ROTACIÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado sosteniendo un balón medicinal a la altura del pecho. Después, dá un paso adelante en estocada mientras extendés los brazos hacia adelante para estirar los codos. Después, rotá los brazos y el tronco hacia el lado de la pierna de adelante. Después volvé a la posición de estocada con la pelota y el tronco mirando hacia adelante. Por último, dá un paso atrás y volvé a la posición original.', 6042),
  ('CAMINATA DE MONSTRUO - BANDA ELÁSTICA EN LOS TOBILLOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Colocá una banda elástica circular alrededor de ambos tobillos. Después, flexioná las rodillas y dá pasos hacia adelante manteniendo la tensión de la banda todo el tiempo. Después de dar varios pasos hacia adelante, invertí la dirección dando pasos hacia atrás hasta volver a la posición inicial. Repetí.', 453),
  ('DESLIZAMIENTO INFERIOR DE RÓTULA - AUTOMOVILIZACIÓN', NULL, true, 'activo_asistido', 'Cadera y rodilla', NULL, 'Colocá los pulgares sobre el borde superior de la rótula y deslizala hacia abajo, en dirección a los pies.', 136),
  ('DESLIZAMIENTO LATERAL DE RÓTULA - AUTOMOVILIZACIÓN', NULL, true, 'activo_asistido', 'Cadera y rodilla', NULL, 'Colocá la mano sobre el borde interno de la rótula y deslizala hacia afuera, hacia el costado.', 137),
  ('DESLIZAMIENTO MEDIAL DE RÓTULA - AUTOMOVILIZACIÓN', NULL, true, 'activo_asistido', 'Cadera y rodilla', NULL, 'Colocá la mano sobre el borde externo de la rótula y deslizala hacia adentro, hacia la línea media.', 138),
  ('DESLIZAMIENTO SUPERIOR DE RÓTULA - AUTOMOVILIZACIÓN', NULL, true, 'activo_asistido', 'Cadera y rodilla', NULL, 'Colocá los pulgares sobre el borde inferior de la rótula y deslizala hacia arriba, en dirección al muslo.', 139),
  ('ESTIRAMIENTO DE PIRAMIDAL Y CADERA - FABER SENTADO', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Sentado en una silla, cruzá la pierna afectada por encima de la otra, como se muestra. Después, inclinate suavemente hacia adelante hasta sentir un estiramiento en la pierna cruzada.', 470),
  ('ESTIRAMIENTO DE PIRAMIDAL', NULL, true, 'pasivo', 'Cadera y rodilla', NULL, 'Acostado boca arriba con ambas rodillas flexionadas, cruzá la pierna afectada sobre la otra rodilla. Después, agarrá el muslo de la pierna sana y tiralo hacia el pecho hasta sentir un estiramiento en el glúteo.', 140),
  ('ESTIRAMIENTO DE PIRAMIDAL - MODIFICADO', NULL, true, 'pasivo', 'Cadera y rodilla', NULL, 'Acostado boca arriba, agarrá la rodilla con la mano contraria y llevá la rodilla hacia arriba y cruzando hacia el hombro contrario.', 142),
  ('ESTIRAMIENTO DE PIRAMIDAL MODIFICADO 3', NULL, true, 'pasivo', 'Cadera y rodilla', NULL, 'Acostado boca arriba y con la pierna cruzada por encima de la rodilla contraria, agarrá la rodilla con la mano contraria y llevá la rodilla hacia arriba y cruzando la línea media hacia el hombro contrario, hasta sentir un estiramiento en el glúteo.', 22425),
  ('EXTENSIÓN DE CADERA EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Acostado boca abajo con la rodilla estirada, elevá lentamente la pierna despegándola del piso. Mantené la rodilla estirada todo el tiempo.', 411),
  ('ACTIVACIÓN DE CUÁDRICEPS - TOALLA DEBAJO DE LA RODILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Apretá el músculo de la parte de arriba del muslo mientras intentás presionar la parte de atrás de la rodilla hacia abajo, contra la camilla.', 22532),
  ('ACTIVACIÓN DE CUÁDRICEPS - TOALLA DEBAJO DE LA RODILLA - CUÁDRICEPS ISOMÉTRICO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Colocá una toalla chica enrollada debajo de la rodilla y apretá el músculo de la parte de arriba del muslo para presionar la parte de atrás de la rodilla hacia abajo, contra la toalla.', 17392),
  ('ACTIVACIÓN DE CUÁDRICEPS CON TOALLA DEBAJO DEL TALÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Acostado o sentado con una toalla chica enrollada debajo del tobillo, apretá el músculo de la parte de arriba del muslo para presionar la parte de atrás de la rodilla hacia abajo, en dirección al piso.', 149),
  ('ACTIVACIÓN DE CUÁDRICEPS - CUÁDRICEPS ISOMÉTRICO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Sentate y estirá la pierna y la rodilla. Apretá el músculo de la parte de arriba del muslo para presionar la parte de atrás de la rodilla hacia abajo. Mantené, después relajá y repetí.', 82672),
  ('SUBIDAS AL ESCALÓN RÁPIDAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Hacé subidas al escalón de forma rápida. Caé sobre la parte anterior de los pies en el escalón mientras las hacés.', 12627),
  ('DESLIZAMIENTO DEL NERVIO CIÁTICO - SENTADO - 1', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá sentado derecho en una silla o en el borde de la cama, con las manos por detrás de la espalda. Después, extendé la rodilla y mantené esta posición. Después, flexioná el tobillo hacia adelante y hacia atrás.', 5985),
  ('DESLIZAMIENTO DEL NERVIO CIÁTICO - SENTADO - 2', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá sentado flexionado hacia adelante desde el tronco y la cabeza, como se muestra. Después, extendé la rodilla mientras extendés la columna y la cabeza hasta quedar sentado derecho. Después volvé a la posición inicial y repetí.', 5986),
  ('DESLIZAMIENTO DEL NERVIO CIÁTICO - SENTADO - 3', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá sentado con la cabeza flexionada, la rodilla flexionada y el pie bien apoyado en el piso, como se muestra. Después, extendé la cabeza como si miraras hacia arriba y elevá el pie. Volvé a la posición inicial y repetí.', 81658),
  ('DESLIZAMIENTO DEL NERVIO CIÁTICO - SENTADO - 4', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá sentado en el borde delantero de una silla con buena postura y una rodilla estirada. Extendé la cabeza, como si miraras hacia arriba, mientras llevás los dedos del pie hacia el techo. Después, flexioná la cabeza, como si miraras hacia el piso, mientras apuntás los dedos del pie hacia adelante. Volvé a la posición inicial y repetí.', 164284),
  ('DESLIZAMIENTO DEL NERVIO CIÁTICO - DECÚBITO DORSAL', NULL, true, 'pasivo', 'Cadera y rodilla', NULL, 'Empezá acostado boca arriba y agarrá la parte de atrás de la rodilla. Después, intentá estirar la rodilla. Por último, mantené esta posición y después flexioná el tobillo hacia adelante y hacia atrás, como se muestra.', 5987),
  ('SALTOS EN TIJERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá en posición de estocada y después saltá y cambiá de pierna para que el pie contrario caiga adelante mientras bajás a la posición de estocada. No dejes que la rodilla de adelante pase los dedos del pie. Seguí saltando y alternando las piernas.', 9673),
  ('MARCHA SENTADO - BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá sentado en una silla con una banda elástica alrededor de la parte baja de los muslos. Después, elevá una rodilla, volvé a apoyarla y después alterná al otro lado.', 11804),
  ('AUTOMASAJE CON PELOTA - GLÚTEO - PARED', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Colocá una pelota entre una pared y la cola. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Inclinate contra la pelota para aplicar presión suave sobre las zonas tensas. No pases la pelota sobre zonas óseas. Podés mantener la presión en una zona o mover el cuerpo para que la pelota ruede hacia arriba y abajo o de lado a lado.', 99626),
  ('AUTOMASAJE CON PELOTA - PIRAMIDAL - PARED', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parate al costado de una pared y colocá una pelota entre la pared y la cola. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Inclinate contra la pelota para aplicar presión suave sobre las zonas tensas. No pases la pelota sobre zonas óseas. Podés mantener la presión en una zona o mover el cuerpo para que la pelota ruede hacia arriba y abajo o de lado a lado.', 99628),
  ('ESTIRAMIENTO DE UNA RODILLA AL PECHO 2', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Acostado boca arriba, usá las manos para elevar suavemente una rodilla y tirarla hacia el pecho. Mantené para un estiramiento suave. Asegurate de mantener la otra rodilla estirada y apoyada en el piso.', 5104),
  ('ESTIRAMIENTO DE UNA RODILLA AL PECHO CON TOALLA', NULL, true, 'pasivo', 'Cadera y rodilla', NULL, 'Acostate boca arriba y colocá una toalla alrededor de la cara de abajo del muslo. Sostené las dos puntas de la toalla y usá los brazos para tirar de la pierna hacia la flexión de cadera, para un estiramiento suave. Volvé a la posición inicial y repetí.', 83137),
  ('SALTO EN UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Saltá hacia arriba usando una sola pierna. Caé al piso con la misma pierna. Repetí.', 82537),
  ('APOYO EN UNA PIERNA - RELOJ O ESTRELLA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá parado en una pierna y mantené el equilibrio. Imaginate un reloj en el piso donde la pierna de apoyo está en el centro. Manteniendo el equilibrio en una pierna, tocá suavemente hacia adelante con los dedos del pie libre sobre la cinta. Después, volvé con esa pierna a la posición inicial. Después, tocá hacia adelante y apenas hacia el costado sobre la cinta, y volvé. Seguí así todo alrededor hasta la sexta posición, que queda detrás tuyo y apenas cruzando hacia el otro lado del cuerpo. Mantené la rodilla de apoyo apenas flexionada todo el tiempo.', 22537),
  ('APOYO EN UNA PIERNA - ADELANTE', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parate en una pierna y mantené el equilibrio. Después, sostené la otra pierna extendida por delante del cuerpo. Después volvé a la posición original. Mantené la rodilla de apoyo apenas flexionada.', 21),
  ('APOYO EN UNA PIERNA - LATERAL', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parate en una pierna y mantené el equilibrio. Después, sostené la otra pierna extendida hacia el costado del cuerpo. Después volvé a la posición original. Mantené la rodilla de apoyo apenas flexionada.', 22),
  ('APOYO EN UNA PIERNA - HACIA ATRÁS', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parate en una pierna y mantené el equilibrio. Después, sostené la otra pierna extendida por detrás del cuerpo. Después volvé a la posición original. Mantené la rodilla de apoyo apenas flexionada.', 25),
  ('APOYO EN UNA PIERNA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parate en una pierna y mantené el equilibrio.', 20),
  ('SENTADO A DE PIE - ASISTIDO CON AMBAS MANOS', NULL, true, 'activo_asistido', 'Cadera y rodilla', NULL, 'Sentado en una silla, deslizate hacia adelante, hacia el borde de la silla. Después, agarrate del apoyabrazos con ambas manos para apoyarte y después incorporate hasta quedar de pie.', 27191),
  ('SENTADO A DE PIE - APOYO EN LOS MUSLOS', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Empezá deslizándote cerca del frente de la silla. Después inclinate hacia adelante y apoyá las manos sobre los muslos. Incorporate hasta quedar de pie usando las manos como apoyo. Volvé a sentarte usando las manos como apoyo sobre los muslos y después repetí.', 48536),
  ('SENTADILLAS - CON APOYO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'De pie con los pies separados al ancho de los hombros y frente a un apoyo estable por si necesitás ayuda para el equilibrio, flexioná las rodillas y bajá el cuerpo hacia el piso. El peso del cuerpo tiene que ir principalmente por los talones. Volvé a la posición de pie. Las rodillas tienen que flexionarse alineadas con el segundo dedo del pie y no pasar la punta del pie.', 26),
  ('CURLS DE ISQUIOTIBIALES DE PIE', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'De pie, flexioná la rodilla de modo que el talón se acerque a la cola. Bajá hasta el primer contacto con el piso y repetí. Mantené las rodillas alineadas entre sí.', 113),
  ('MARCHA DE PIE - FLEXIÓN DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parado al lado de una silla o mesada para apoyarte, marchá en el lugar elevando la rodilla y dejando que se flexione, y después hacelo del otro lado. Repetí este movimiento alternado.', 7002),
  ('BICICLETA FIJA - HACIA ADELANTE', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Pedaleá hacia adelante en una bicicleta fija de modo que los pies suban, vayan hacia adelante y después bajen.', 118261),
  ('BICICLETA FIJA - ARCOS PARCIALES', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Pedaleá hacia adelante y después hacia atrás en arcos parciales. Hacelo dentro del rango de movimiento disponible y mantené al final del recorrido para un estiramiento suave.', 118263),
  ('BICICLETA FIJA - HACIA ATRÁS', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Pedaleá hacia atrás en una bicicleta fija de modo que los pies suban, vayan hacia atrás y después bajen.', 118262),
  ('BAJADA DEL ESCALÓN - LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá con ambos pies arriba de un escalón o cajón. Después, bajá lentamente la pierna sana por el costado del escalón hasta tocar suavemente el piso con el talón. Después volvé a la posición original con ambos pies en el escalón. Mantené la alineación correcta de la rodilla: la rodilla alineada con el segundo dedo del pie y sin pasar por delante de los dedos.', 7394),
  ('SUBIDA AL ESCALÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado frente a un escalón o banquito con ambos pies en el piso. Subí al escalón con una pierna y después con la otra. Volvé a la posición inicial bajando un paso hacia el piso empezando con la misma pierna.', 456),
  ('SUBIR Y PASAR - LATERAL', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parado al lado de un cajón o superficie elevada, subí de costado a la superficie. Ambos pies tienen que tocar la superficie elevada. Después bajá al piso hacia el lado contrario al que empezaste. Repetí en la otra dirección.', 13120),
  ('SUBIR Y BAJAR DEL ESCALÓN - IPSILATERAL (MISMO LADO)', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá parado frente a un escalón o banquito con ambos pies en el piso. Subí al escalón con la pierna que trabajás y usá esa pierna para elevar el peso del cuerpo al escalón con la otra pierna. Una vez que los dos pies están en el escalón, bajá hacia atrás con la otra pierna primero, de modo que la pierna que trabajás haga el esfuerzo de bajar el cuerpo al piso. Después llevá la pierna que trabajás al piso, al lado de la otra. Puede que necesites algo de dónde agarrarte para el equilibrio. Repetí del mismo lado.', 95397),
  ('SUBIDA LATERAL AL ESCALÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Parado al lado de un cajón o superficie elevada, subí de costado a la superficie. Ambos pies tienen que tocar la superficie elevada. Después bajá al piso hacia el mismo lado desde donde empezaste.', 13121),
  ('DESLIZAMIENTOS DE TALÓN EN DECÚBITO DORSAL - AAROM', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Acostado boca arriba, colocá un cinto, toalla, cinta o sábana alrededor del pie y empezá tirando con los brazos para flexionar la rodilla. Después dejá que la rodilla se estire de nuevo hasta la posición inicial y repetí.', 66920),
  ('ABDUCCIÓN DE CADERA EN DECÚBITO DORSAL - ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Pasá un cinto o atá una sábana alrededor de las rodillas. Acostado boca arriba, intentá separar las rodillas y mantené.', 22423),
  ('EQUILIBRIO EN APOYO TÁNDEM', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parate y equilibrate en apoyo tándem. Mantené esta posición. Relajá y repetí.', 52536),
  ('APOYO TÁNDEM CON SOPORTE', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parate frente a una silla, mesa o mesada para apoyarte. Después, colocá el talón de un pie tocando los dedos del otro pie. Mantené el equilibrio en esta posición.', 22540),
  ('CAMINATA EN TÁNDEM', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Parate con un pie justo delante del otro, de modo que los dedos de un pie toquen el talón del otro, como se ve en la imagen. Progresá dando pasos con el talón tocando los dedos en cada paso, como se ve en el video. Mantené el equilibrio.', 542),
  ('SALTOS SOBRE LA CINTA - HACIA ADELANTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Saltá con ambos pies por encima de la cinta hacia adelante y después volvé a la posición original. Usá marcadores o cinta en el piso para trabajar el control de la caída y la ubicación de los pies. Aumentá la distancia o la velocidad para progresar.', 7659),
  ('SALTOS SOBRE LA CINTA - CICLO COMPLETO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Saltá con ambos pies por encima de la cinta hacia adelante, después saltá hacia el costado, después hacia atrás y después a la posición original. Después de hacerlo un par de veces, invertí la dirección y hacelo al revés. Usá marcadores o cinta en el piso para trabajar el control de la caída y la ubicación de los pies. Aumentá la distancia o la velocidad para progresar.', 7657),
  ('SALTOS SOBRE LA CINTA - LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Saltá con ambos pies por encima de la cinta hacia el costado y después volvé a la posición original. Usá marcadores o cinta en el piso para trabajar el control de la caída y la ubicación de los pies. Aumentá la distancia o la velocidad para progresar.', 7660),
  ('EXTENSIÓN TERMINAL DE RODILLA - TKE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', NULL, 'Empezá de pie con una banda elástica fijada por encima de la rodilla y la otra punta atada con un nudo y fijada detrás de una puerta cerrada u otro anclaje. La rodilla que trabajás tiene que estar parcialmente flexionada con los dedos del pie tocando el piso. Después, llevá la rodilla hacia atrás, hacia la posición estirada, de modo que el talón toque el piso mientras tirás contra la banda.', 464),
  ('CINTA - MARCHA HACIA ATRÁS', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Caminá hacia atrás en una cinta.', 137146),
  ('CINTA - CORRER', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Corré o trotá en una cinta.', 137147),
  ('CINTA - CAMINAR', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'Caminá hacia adelante en una cinta.', 137148),
  ('TRASLADO DE PESO - LATERAL', NULL, true, 'activo', 'Cadera y rodilla', NULL, 'En posición de pie y con las rodillas parcialmente flexionadas, trasladá lentamente el peso del cuerpo de lado a lado.', 7350),
  ('ABDUCCIÓN DE CADERA CON RODILLA AL PECHO - DECÚBITO LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo)', 'Acostate de costado con la rodilla y la cadera de arriba flexionadas, como se muestra. Empezá elevando la pierna hacia el techo hasta que la rodilla quede completamente estirada, los dedos del pie apunten hacia adelante y la pierna quede alineada con el cuerpo. Volvé con la pierna a la posición inicial y repetí.', 139313),
  ('EXTENSIÓN DE CADERA CON APOYO - DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo)', 'Parate y apoyá los brazos sobre una mesa. Mientras cargás el peso en una pierna, llevá la otra pierna hacia atrás, como se muestra. Hacé movimientos suaves y controlados. Mantené la rodilla estirada todo el tiempo. Mantené el tronco estable y sin arquearse durante el movimiento. Usá los brazos de apoyo si los necesitás para el equilibrio y la seguridad.', 86357),
  ('SENTADILLAS CON ANDADOR', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo)', 'Parate dentro de un andador con los pies separados al ancho de los hombros y con una silla atrás por seguridad. Empezá flexionando las rodillas y bajando el cuerpo en sentadilla, como si te fueras a sentar en la silla, pero sin sentarte. El peso del cuerpo tiene que ir principalmente por los talones. Sin tocar la silla con la cola, estirá las rodillas y volvé a la posición de pie completa, y repetí. La silla está ahí por seguridad y como guía para mejorar la técnica. Las rodillas tienen que flexionarse alineadas con el segundo dedo del pie y no pasar la punta del pie.', 452),
  ('SENTADILLA - CON APOYO Y SILLA POR SEGURIDAD', NULL, true, 'sin_clasificar', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo); Cadena cerrada', 'Colocá una silla detrás tuyo por seguridad. De pie con los pies separados al ancho de los hombros y frente a un apoyo estable por si necesitás ayuda para el equilibrio, flexioná las rodillas y bajá el cuerpo hacia el piso. El peso del cuerpo tiene que ir principalmente por los talones. Volvé a la posición de pie. Las rodillas tienen que flexionarse alineadas con el segundo dedo del pie y no pasar la punta del pie.', 48538),
  ('GERIÁTRICO - ABDUCCIÓN DE CADERA - DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo); Cadena abierta', 'Parado al lado de una silla o mesada para apoyarte, elevá la pierna hacia el costado. Mantené la rodilla estirada y los dedos del pie apuntando hacia adelante lo mejor que puedas. Después, bajá la pierna y repetí. Usá los brazos de apoyo si los necesitás para el equilibrio y la seguridad.', 124259),
  ('GERIÁTRICO - EXTENSIÓN DE CADERA - DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo); Cadena abierta', 'De pie, parate en una pierna y llevá la otra pierna hacia atrás. No balancees la pierna. Hacé movimientos suaves y controlados. Mantené el tronco estable y sin arquearse durante el movimiento. Usá los brazos de apoyo si los necesitás para el equilibrio y la seguridad.', 124260),
  ('GERIÁTRICO - FLEXIÓN DE CADERA - DE PIE - ELEVACIÓN DE PIERNA', NULL, true, 'activo', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo); Cadena abierta', 'Parado al lado de una silla o mesada para apoyarte, elevá una pierna hacia adelante despegándola del piso con la rodilla estirada. Volvé a la posición inicial y repetí.', 124261),
  ('GERIÁTRICO - ABDUCCIÓN DE CADERA CON ANDADOR', NULL, true, 'activo', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo); Cadena abierta', 'Parado dentro de un andador, elevá la pierna hacia el costado. Bajala de nuevo y después repetí con la misma pierna. Mantené la rodilla estirada y los dedos del pie apuntando hacia adelante lo mejor que puedas todo el tiempo. Usá los brazos de apoyo y para el equilibrio, y tené una silla atrás por seguridad.', 125301),
  ('ABDUCCIÓN DE CADERA EN DECÚBITO LATERAL 2', NULL, true, 'activo', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo); Cadena abierta', 'Acostado de costado con la pierna de arriba sobre 2 o 3 almohadas, elevá lentamente la pierna de arriba hacia el costado. Mantené la rodilla estirada y los dedos del pie apuntando hacia adelante todo el tiempo. Mantené la pierna alineada con el cuerpo. La pierna de abajo puede estar flexionada para estabilizar el cuerpo.', 560),
  ('EMBARAZO - MARCHA DE PIE - FLEXIÓN DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo); Cadena abierta', 'De pie, marchá en el lugar elevando la rodilla y dejando que se flexione. Bajala y después hacelo del otro lado. Repetí este movimiento alternado.', 179246),
  ('ABDUCCIÓN DE CADERA CON ANDADOR', NULL, true, 'activo', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo); Cadena abierta', 'Parado con un andador, elevá la pierna hacia el costado. Mantené la rodilla estirada y los dedos del pie apuntando hacia adelante todo el tiempo. Usá los brazos de apoyo y para el equilibrio, y tené una silla atrás por seguridad. Colocá una silla detrás tuyo y debajo de la cola por seguridad.', 538),
  ('EXTENSIÓN DE CADERA CON ANDADOR', NULL, true, 'activo', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo); Cadena abierta', 'Parado con un andador, extendé la pierna hacia atrás. No dejes que la espalda ni el pecho se muevan. Además, mantené la rodilla estirada todo el tiempo. Bajá la pierna de nuevo y repetí. Colocá una silla detrás tuyo y debajo de la cola por seguridad.', 539),
  ('MARCHA CON ANDADOR', NULL, true, 'activo_asistido', 'Cadera y rodilla', 'Cadera en 4 direcciones; AROM (activo); Cadena abierta', 'Parado con un andador, elevá una rodilla dejando que se flexione mientras despegás el pie del piso. Volvé a apoyar el pie en el piso y después hacelo del otro lado. Colocá una silla detrás tuyo y debajo de la cola por seguridad.', 451),
  ('SENTADILLA/ESTOCADA LATERAL CON ROTACIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Cadena cerrada', 'Parate con las piernas bien separadas. Después, dá un paso hacia el costado dejando que la rodilla se flexione mientras bajás la cola hacia atrás. Mientras bajás, rotá la otra pierna de modo que el pie apunte hacia arriba. Mantené las rodillas alineadas con los dedos de los pies. Podés elevar los brazos hacia adelante en cada flexión de rodilla como contrapeso. Volvé a la posición original y repetí del mismo lado.', 79100),
  ('SALTOS EN SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Cadena cerrada', 'Empezá con las piernas bien separadas y las manos en la cintura, como se muestra. Después hacé una sentadilla y saltá hacia arriba. Mientras volvés a bajar del salto, bajá de nuevo a la posición de sentadilla y repetí.', 79098),
  ('PIES EN TIJERA - SENTADO A DE PIE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Cadena cerrada', 'Empezá sentado en una silla con los pies separados en tijera, como se muestra. Después incorporate manteniendo los pies en la misma posición. Volvé a sentarte y repetí.', 79097),
  ('BANDA ELÁSTICA - FLEXIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Banda elástica; Cadena abierta', 'De pie con una banda elástica fijada al tobillo, llevá la pierna hacia adelante por delante del cuerpo. Mantené la rodilla estirada todo el tiempo. Usá los brazos de apoyo si los necesitás para el equilibrio y la seguridad.', 536),
  ('BANDA ELÁSTICA - EXTENSIÓN DE CADERA EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Banda elástica; Cadena abierta', 'Acostado boca abajo con una banda elástica circular alrededor de los tobillos, elevá la pierna que trabajás hacia arriba.', 8516),
  ('BANDA ELÁSTICA - ABDUCCIÓN EN DECÚBITO LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Banda elástica; Cadena abierta', 'Acostado de costado con una banda elástica circular alrededor de los tobillos, elevá la pierna de arriba hacia arriba.', 8513),
  ('BANDA ELÁSTICA - ELEVACIÓN DE PIERNA ESTIRADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Banda elástica; Cadena abierta', 'Acostado boca arriba con una banda elástica circular alrededor de los tobillos, elevá la pierna que trabajás hacia arriba.', 8519),
  ('ADUCCIÓN DE CADERA CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Banda elástica; Cadena abierta', 'Parate con una banda elástica fijada al tobillo de modo que la banda quede dirigida y anclada hacia el costado, alejándose del cuerpo, como se muestra. Después, llevá la pierna hacia el costado y después llevala de vuelta hacia el piso tirando contra la resistencia de la banda. Repetí. Usá los brazos de apoyo si los necesitás para el equilibrio y la seguridad.', 537),
  ('BANDA ELÁSTICA - EXTENSIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Cadena abierta', 'De pie con una banda elástica fijada al tobillo, llevá la pierna hacia atrás. Mantené la rodilla estirada todo el tiempo. Usá los brazos de apoyo si los necesitás para el equilibrio y la seguridad.', 4714),
  ('ABDUCCIÓN DE CADERA CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Cadena abierta', 'Parate con una banda elástica fijada al tobillo de modo que la banda quede dirigida y anclada hacia el costado, por delante de la otra pierna, como se muestra. Después, llevá la pierna hacia el costado tirando contra la resistencia de la banda y después llevala de vuelta hacia el piso. Repetí. Usá los brazos de apoyo si los necesitás para el equilibrio y la seguridad.', 108),
  ('FLEXIÓN DE CADERA CON BANDA ELÁSTICA CIRCULAR', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadera en 4 direcciones; Cadena abierta', 'De pie con una banda elástica circular alrededor de los tobillos, llevá la pierna que trabajás hacia adelante, como se muestra. Volvé a la posición original y después repetí.', 8076),
  ('ESTOCADA CON TOQUE AL CONO', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo)', 'Empezá parado con los pies separados en tijera y el talón de atrás despegado del piso, como se muestra. Flexioná las caderas y las rodillas mientras te inclinás hacia adelante para tocar el cono. Mantené la columna derecha y no dejes que la rodilla de adelante pase por delante de los dedos del pie. Volvé a la posición inicial y repetí.', 177481),
  ('PELOTA DE EJERCICIOS - RODADO DE CADERA Y RODILLA - AROM', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostado boca arriba, apoyá los talones sobre una pelota de ejercicios y rodala acercándola a la cola mientras las rodillas y las caderas se flexionan, como se muestra. Volvé a la posición original y repetí.', 8514),
  ('DESLIZAMIENTOS DEL PIE - TOALLA - RI / RE DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Sentate en una silla y apoyá el pie sobre una toalla de mano en el piso. Deslizá el pie de lado a lado dejando que la cadera rote.', 162075),
  ('DESLIZAMIENTOS DEL PIE - TOALLA - FLEXIÓN / EXTENSIÓN DE RODILLA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Sentate en una silla y apoyá el pie sobre una toalla de mano en el piso. Deslizá el pie dejando que la rodilla se flexione y se estire.', 162077),
  ('ABDUCCIÓN DE CADERA - BILATERAL - ALMEJAS SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Empezá sentado cerca del borde de una silla con las rodillas flexionadas y ambos pies en el piso. Después, llevá las rodillas hacia los costados, como se muestra, y después volvé al frente. Mantené el contacto de los pies con el piso todo el tiempo.', 7157),
  ('ABDUCCIÓN DE CADERA - UNILATERAL - SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Empezá sentado cerca del borde de una silla con las rodillas flexionadas y ambos pies en el piso. Después, llevá la rodilla que trabajás hacia el costado, como se muestra, y después volvé al frente. Mantené el contacto de los pies con el piso todo el tiempo.', 7158),
  ('ADUCCIÓN DE CADERA - DECÚBITO LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostado de costado, elevá lentamente la pierna de abajo hacia el techo. Mantené la rodilla estirada todo el tiempo. La pierna de arriba tiene que estar flexionada en la rodilla y con el pie apoyado en el piso sosteniendo el cuerpo.', 125),
  ('ROTACIÓN EXTERNA DE CADERA - RE EN DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Empezá acostado boca arriba con la pierna en posición neutra. Después, rotá la cadera y toda la pierna hacia afuera, alejándola de la línea media del cuerpo, como se muestra. Volvé a la posición inicial y repetí.', 165865),
  ('ROTACIÓN INTERNA / EXTERNA DE CADERA - RI / RE EN DECÚBITO DORSAL - BILATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostate boca arriba con las piernas en posición neutra. Después, rotá las caderas y las piernas enteras hacia adentro y después hacia afuera, como se muestra.', 165868),
  ('ROTACIÓN INTERNA / EXTERNA DE CADERA - RI / RE EN DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostate boca arriba con la pierna en posición neutra. Después, rotá la cadera y toda la pierna hacia adentro y después hacia afuera, como se muestra.', 165869),
  ('ROTACIÓN INTERNA Y EXTERNA DE CADERA - DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostado boca arriba con las rodillas estiradas, rodá la cadera hacia adentro y hacia afuera de modo que los dedos del pie apunten primero a la derecha y después a la izquierda. Asegurate de que la rótula también mire a la derecha y después a la izquierda.', 160),
  ('ROTACIÓN INTERNA DE CADERA - RI EN DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Empezá acostado boca arriba con la pierna en posición neutra. Después, rotá la cadera y toda la pierna hacia adentro, hacia la línea media del cuerpo, como se muestra. Volvé a la posición inicial y repetí.', 165863),
  ('RI DE CADERA - ROTACIÓN INTERNA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostate boca arriba con las rodillas extendidas y los dedos de los pies apuntando derecho hacia arriba. Empezá rotando lentamente la cadera hacia adentro, hacia la línea media, de modo que los dedos del pie apunten hacia adentro, como se muestra. Después volvé a la posición inicial con los dedos apuntando derecho hacia arriba y repetí.', 53522),
  ('ELEVACIONES DE PIERNA - APOYADO SOBRE LOS CODOS', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostate boca arriba apoyado sobre los codos, como se muestra. Flexioná una rodilla con el pie apoyado en el piso y dejá la otra pierna estirada. Elevá la pierna estirada despegándola del piso. Bajala a la posición inicial y repetí.', 177807),
  ('ARCO PARCIAL DE CUÁDRICEPS - ASIENTO BAJO - EXTENSIÓN DE RODILLA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Sentado con la rodilla flexionada y el talón tocando el piso, estirá lentamente la rodilla mientras elevás el pie hacia arriba, como se muestra. Bajá el pie hasta que el talón toque el piso y después repetí.', 393),
  ('EMBARAZO - ADUCCIÓN DE CADERA EN DECÚBITO LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostada de costado, elevá lentamente la pierna de abajo hacia el techo. Mantené la rodilla estirada todo el tiempo. La pierna de arriba tiene que estar flexionada en la rodilla y con el pie apoyado en el piso sosteniendo el cuerpo.', 181853),
  ('EMBARAZO - ABDUCCIÓN EN DECÚBITO LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostate de costado con la rodilla de abajo flexionada. Empezá elevando la pierna de arriba y llevala hacia adelante y después hacia atrás. Bajá la pierna, volvé a la posición inicial y repetí.', 181852),
  ('ALMEJA EN DECÚBITO LATERAL CON COMBINACIÓN INVERSA', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo)', 'Empezá acostado de costado con las rodillas flexionadas y en contacto entre sí. Después, elevá la rodilla de arriba manteniendo los pies en contacto. Bajá la rodilla a la posición inicial y después elevá el pie de arriba hacia el techo manteniendo las rodillas en contacto. Bajá y después repetí este movimiento alternado. Activá los músculos abdominales para estabilizar la pelvis, de modo que no rote hacia adelante ni hacia atrás durante el ejercicio.', 150392),
  ('ALMEJA INVERTIDA EN DECÚBITO LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostado de costado con las rodillas flexionadas, elevá el pie de arriba hacia el techo manteniendo las rodillas en contacto. Después, bajá a la posición original. No dejes que la pelvis rote hacia adelante durante el movimiento de elevación.', 7162),
  ('RDL A UNA PIERNA - PESO MUERTO RUMANO', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Parate y equilibrate sobre una pierna. Después, inclinate hacia adelante como si fueras a tocar el piso mientras extendés y elevás la otra pierna por detrás del cuerpo. Mantené la columna derecha y flexioná desde la cadera. Volvé a la posición original y repetí.', 24215),
  ('PATADAS DE BICICLETA DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Parate al lado de una silla o mesada para agarrarte y mantener el equilibrio. Parate en una pierna y elevá la otra mientras la movés en círculos, como pedaleando una bicicleta, como se muestra. Hacé algunas vueltas y después invertí la dirección y hacé algunas más. Seguí con este movimiento alternado.', 177252),
  ('ELEVACIÓN DE PIERNA ESTIRADA - SLR EN ROTACIÓN EXTERNA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostado o sentado, elevá la pierna con la rodilla estirada y los dedos del pie apuntando hacia afuera.', 159),
  ('CÍRCULOS CON PIERNA ELEVADA EN DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostate boca arriba con una rodilla flexionada y la otra pierna despegada del piso, como se muestra. Rotá la pierna elevada en un patrón circular durante varias vueltas y después repetí en la dirección contraria.', 177483),
  ('CÍRCULOS CON PIERNA ELEVADA EN DECÚBITO DORSAL I', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo)', 'Acostate boca arriba con una pierna apoyada en el piso y la otra despegada del piso, como se muestra. Rotá la pierna elevada en un patrón circular durante varias vueltas y después repetí en la dirección contraria. Mantené los músculos del core y del abdomen activados para estabilizar la columna todo el tiempo.', 177806),
  ('TOQUES EN EL ESCALÓN - ALTERNADOS', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo)', 'Parate frente a un escalón y despegá un pie del piso mientras te equilibrás sobre la otra pierna. Tocá la parte de arriba del escalón con los dedos del pie. Asegurate de elevar lo suficiente para no golpear el frente del escalón con la punta del pie. Después, apoyá el pie de nuevo y hacelo del otro lado. Si hace falta, apoyá la mano en una mesa para mantener el equilibrio.', 54265),
  ('SENTADILLAS EN LA PARED', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo)', 'De pie, apoyá la espalda contra una puerta o una pared de superficie lisa. Colocá los pies separados al ancho de los hombros. Después, flexioná las rodillas mientras deslizás el cuerpo hacia abajo y después volvé a la posición erguida. Repetí. Las rodillas tienen que flexionarse alineadas con el segundo dedo del pie y no pasar el frente del pie.', 354),
  ('VASO - TOCAR CON EL PIE Y MANTENER', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Equilibrio', 'Parate al lado de algo para ayudarte con el equilibrio si hace falta. Colocá un vaso de papel o de plástico en el piso. Parate frente al vaso y despegá del piso el pie que vas a trabajar mientras te equilibrás sobre la otra pierna. Tocá la parte de arriba del vaso con los dedos de ese pie. Mantené la posición sin aplastar el vaso. Después, apoyá el pie de nuevo y repetí del mismo lado. Si perdés el equilibrio, podés usar una o más estrategias para ayudarte: dar un paso, abrir los brazos hacia los costados o agarrarte de algo.', 54251),
  ('HOMBRE CORRIENDO', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Equilibrio; Cadena cerrada', 'Parate y equilibrate sobre una pierna. Después, inclinate hacia adelante mientras llevás la otra pierna hacia atrás para tocar el piso. Llevá el brazo del mismo lado hacia adelante durante el movimiento, como se muestra. Volvé a la posición inicial y repetí.', 24201),
  ('PELOTA DE EJERCICIOS - SENTADILLAS SENTADO', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Pelota', 'Sentado sobre una pelota de ejercicios, rodá hacia adelante de modo que la espalda quede apoyada contra la pelota. Después, flexioná las rodillas de modo que la cola ruede hacia adelante sobre la pelota, en dirección al piso. Después, empujá con las piernas para estirar las rodillas de modo que la cola ruede hacia atrás y hacia arriba, alejándose del piso. Repetí.', 322),
  ('LIBERACIÓN DE PUNTO GATILLO DE ISQUIOTIBIALES CON PELOTA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Pelota', 'Sentate en una superficie firme, como una mesa o una silla, y colocá una pelota de tenis debajo del muslo, donde está el punto gatillo. Después, flexioná y estirá la rodilla de ese lado repetidamente.', 46749),
  ('PELOTA MANÍ - AROM DE RODILLA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Pelota', 'Acostado boca arriba, apoyá el talón sobre una pelota maní y rodala acercándola a la cola mientras flexionás la rodilla y la cadera, como se muestra. Después volvé a la posición original y repetí.', 61513),
  ('EMBARAZO - PELOTA DE EJERCICIOS - BALANCEO EN DECÚBITO VENTRAL', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Pelota; Cadena cerrada', 'Arrodillate frente a una pelota de ejercicios con las rodillas bien separadas. Rodá hacia adelante sobre la pelota de modo que quede debajo del pecho. Balanceate suavemente hacia adelante y atrás. Tené cuidado de no hacer demasiada presión sobre la panza.', 180450),
  ('ELEVACIONES DE CADERA - KETTLEBELL - PESO LIBRE', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cajones y escalones; Cadena cerrada', 'Parate sobre un escalón sosteniendo una kettlebell o un peso libre a la altura del hombro. Después, bajá una pierna hacia el piso inclinando la pelvis hacia el costado. Volvé a la posición inicial y repetí.', 149061),
  ('GERIÁTRICO - ALMEJAS SENTADO - ABDUCCIÓN Y ADUCCIÓN DE CADERA', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena cerrada', 'Empezá sentado cerca del borde de una silla con las rodillas flexionadas y ambos pies en el piso. Después, llevá las rodillas hacia afuera, como se muestra, y después volvé a la posición inicial mirando al frente. Mantené los pies en contacto con el piso todo el tiempo.', 124251),
  ('GERIÁTRICO - SENTADILLAS CON ANDADOR', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena cerrada', 'Parate dentro de un andador con los pies separados al ancho de los hombros y una silla atrás tuyo por seguridad. Empezá flexionando las rodillas y bajando el cuerpo en sentadilla, como si te fueras a sentar en la silla, pero sin sentarte. El peso del cuerpo tiene que ir principalmente por los talones. Sin tocar la silla con la cola, estirá las rodillas y volvé a la posición de pie completa, y repetí. La silla está por seguridad y como guía para mejorar la técnica.', 125304),
  ('EMBARAZO - DE SENTADO A DE PIE', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena cerrada', 'Sentada en una silla, deslizate hacia adelante, hacia el borde de la silla. Después, incorporate hasta quedar de pie. Si hace falta, apoyá las manos en los muslos para ayudarte. Volvé a sentarte y repetí.', 181349),
  ('EMBARAZO - EXTENSIÓN DE CADERA DE RODILLAS', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena cerrada', 'Empezá arrodillada en el piso, sentada sobre los pies, como se muestra. Después, elevá los brazos e incorporate hasta quedar arrodillada en posición erguida. Volvé a bajar y repetí.', 179625),
  ('ROTACIONES DE CADERA EN CADENA CERRADA SENTADO', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena cerrada', 'Sentate erguido con buena postura en una silla, con las manos sobre los muslos. Rotá desde las caderas para mover las rodillas de lado a lado. Repetí este movimiento hacia los dos lados.', 177019),
  ('SENTADILLAS - BANDA ELÁSTICA', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena cerrada; Banda elástica', 'De pie en posición de sentadilla y sosteniendo una banda elástica, estirá las rodillas hasta quedar parado. Bajá de nuevo y repetí.', 289),
  ('ELEVACIÓN DE CADERA - MEDIA RODILLA', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena cerrada; Varios', 'Arrodillate sobre una rodilla y después elevá y bajá el costado de la pelvis del lado de la rodilla que está arriba, como se muestra.', 39430),
  ('EXTENSIONES DE CADERA EN LA MESADA - PUNTA DEL PIE FIJA', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena cerrada; Estiramientos', 'Parate con las manos apoyadas en la mesada para mantener el equilibrio. Apoyá la punta del pie que vas a trabajar en el piso, por detrás tuyo, con la rodilla flexionada. Después, estirá la rodilla y mantené. Volvé a la posición inicial y repetí.', 165460),
  ('BANDA ELÁSTICA - ROTACIÓN DE CADERA SENTADO CON PELOTA', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Banda elástica', 'Empezá sentado con una pelota entre las rodillas y una banda elástica alrededor de los tobillos. Apretá la pelota y sostené la contracción. Después, tirá de la banda mientras separás los pies uno del otro.', 11202),
  ('ALMEJA INVERTIDA EN DECÚBITO LATERAL - BANDA ELÁSTICA', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Banda elástica', 'Acostado de costado con las rodillas flexionadas y una banda elástica alrededor de los tobillos, elevá el pie de arriba hacia el techo manteniendo las rodillas en contacto. Después, bajá a la posición original. No dejes que la pelvis rote hacia adelante durante el movimiento de elevación.', 49614),
  ('ELEVACIÓN DE CADERA - DE RODILLAS', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Varios; Cadena abierta', 'Arrodillate sobre las dos rodillas con una de ellas sobre una toalla doblada. Elevá y bajá el costado de la pelvis del lado que no está sobre la toalla.', 39431),
  ('ELEVACIÓN DE CADERA SENTADO - BÁSCULA PÉLVICA LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Varios; Cadena abierta', 'Sentate de costado en una silla con una nalga fuera del asiento, como se muestra. Después, elevá y bajá el costado de la pelvis que queda colgando del borde de la silla.', 39429),
  ('SENTADO - POSTURA DEL GUERRERO', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Varios; Estiramientos', 'Empezá sentado de costado en una silla, como se muestra, de modo que una pierna no quede apoyada en la silla. Después, extendé esa pierna hacia atrás mientras elevás el brazo del mismo lado hacia el techo. Mantené esta posición con la postura erguida, relajá y repetí.', 171052),
  ('MOVILIDAD DE CADERA DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Movilización; Cadena abierta; Estiramientos', 'Empezá agarrándote de una silla o mesada con una mano para ayudarte con el equilibrio. Después, elevá la pierna que vas a trabajar hacia adelante y arriba con la rodilla flexionada. Después, llevá la pierna hacia el costado. Desde ahí, rotá la pierna de modo que el pie se mueva hacia atrás. Después, bajá la pierna para juntar las rodillas. Invertí los movimientos y repetí.', 159902),
  ('MOVILIDAD DE CADERA EN SENTADO EN Z - NIVEL 1', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Movilización; Estiramientos', 'Empezá sentado en el piso, inclinado hacia atrás y apoyándote con las manos, como se muestra. Sentate con ambas rodillas flexionadas y las caderas rotadas hacia un lado. Después, rotá las caderas hacia el otro lado. Repetí este movimiento alternando de lado a lado.', 159628),
  ('MOVILIDAD DE CADERA EN SENTADO EN Z - NIVEL 2', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Movilización; Estiramientos', 'Empezá sentado erguido en el piso. Apoyá las manos en el piso por detrás tuyo y cerca del cuerpo. Sentate con ambas rodillas flexionadas y las caderas rotadas hacia un lado. Después, rotá las caderas hacia el otro lado. Repetí este movimiento alternando de lado a lado.', 159627),
  ('MOVILIDAD DE CADERA EN SENTADO EN Z - NIVEL 3', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Movilización; Estiramientos', 'Empezá sentado erguido en el piso. No toques el piso con las manos. Sentate con ambas rodillas flexionadas y las caderas rotadas hacia un lado. Después, rotá las caderas hacia el otro lado. Repetí este movimiento alternando de lado a lado.', 159626),
  ('MOVILIDAD DE CADERA EN SENTADO EN Z - NIVEL 4', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Movilización; Estiramientos', 'Empezá sentado erguido en el piso. No toques el piso con las manos. Sentate con ambas rodillas flexionadas y las caderas rotadas hacia un lado y después incorporate hasta quedar arrodillado, como se muestra. Volvé a bajar a la posición sentada y hacelo del otro lado. Repetí este movimiento alternando de lado a lado.', 160175),
  ('HIDRANTE - ABDUCCIÓN DE CADERA EN CUATRO APOYOS', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Empezá en posición de gateo y elevá la pierna hacia el costado, como se muestra. Mantené la espalda alta y media derecha.', 10685),
  ('GERIÁTRICO - EXTENSIÓN DE RODILLA - ARCO LARGO DE CUÁDRICEPS (LAQ)', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Sentado con la rodilla flexionada y el talón tocando el piso, estirá lentamente la rodilla mientras elevás el pie hacia arriba, como se muestra. Bajá el pie hasta que el talón toque el piso y después repetí.', 124254),
  ('GERIÁTRICO - MARCHA SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Sentado en una silla, despegá el pie del piso mientras flexionás la cadera y elevás la pierna. Bajá de nuevo y repetí con la otra pierna. Repetí este movimiento alternado.', 124255),
  ('GERIÁTRICO - CURL DE ISQUIOTIBIALES DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Parado al lado de una silla o mesada para apoyarte, flexioná la rodilla de modo que el talón se acerque a la cola. Bajá de nuevo y después repetí con la otra pierna.', 124575),
  ('GERIÁTRICO - MARCHA DE PIE - FLEXIÓN DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Parado al lado de una silla o mesada para apoyarte, marchá en el lugar elevando la rodilla mientras dejás que se flexione. Bajá de nuevo y después hacelo del otro lado. Repetí este movimiento alternado.', 124576),
  ('GERIÁTRICO - ABDUCCIÓN DE CADERA ALTERNADA CON ANDADOR', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Parado dentro de un andador, elevá la pierna hacia el costado. Bajá de nuevo y después repetí con la otra pierna. Mantené la rodilla estirada y los dedos del pie apuntando hacia adelante lo mejor que puedas todo el tiempo. Usá los brazos para apoyarte y mantener el equilibrio, y poné una silla atrás tuyo por seguridad.', 125300),
  ('FLEXIÓN DE CADERA EN DECÚBITO DORSAL CON PIERNA COLGANDO', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Acostate y dejá que la pierna cuelgue por el costado, como se muestra. Manteniendo la rodilla flexionada, elevá la pierna hacia arriba y después bajala de nuevo y repetí.', 139357),
  ('ABDUCCIÓN DE CADERA - UNILATERAL - SENTADO - PIERNA ESTIRADA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Empezá sentado cerca del borde de una silla con la pierna que vas a trabajar estirada en la rodilla. Después, deslizá esa pierna hacia el costado. Podés deslizar el talón por el piso mientras lo hacés. Después volvé al centro. Mantené los dedos del pie apuntando hacia arriba todo el tiempo.', 7163),
  ('ABDUCCIÓN Y EXTENSIÓN DE CADERA - DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Empezá parado con los pies juntos. Después, llevá la pierna hacia atrás y hacia el costado en un ángulo de aproximadamente 45 grados. Mantené la rodilla estirada y usá los brazos para apoyarte si hace falta, por equilibrio y seguridad. Volvé a la posición inicial y repetí.', 66126),
  ('ADUCCIÓN DE CADERA - APRETAR ALMOHADA SENTADO', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Sentate en una silla y colocá una almohada entre los muslos y las rodillas. Apretá la almohada con las piernas. Mantené, relajá y repetí.', 70021),
  ('CÍRCULOS DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Parate en una pierna y estirá la punta del otro pie mientras movés la pierna en círculo, como se muestra. Hacé algunos círculos en sentido horario y después invertí la dirección y hacelo en sentido antihorario. Las rodillas tienen que estar estiradas todo el tiempo. Repetí.', 79113),
  ('ROTACIÓN EXTERNA DE CADERA - DECÚBITO LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Acostado de costado, dejá que la pierna de abajo cuelgue por fuera de la camilla. El muslo tiene que quedar apoyado sobre la cama o camilla y la parte de la pierna por debajo de la rodilla queda colgando. Después, elevá lentamente la pierna y el pie de abajo, como se muestra.', 467),
  ('ELEVACIÓN DE CADERA - DE PIE - TOALLA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Parado sobre una toalla doblada, elevá y bajá la pelvis del lado que no está apoyado sobre la toalla.', 39432),
  ('ROTACIONES DE CADERA - BILATERAL EN DECÚBITO LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Acostado de costado en posición fetal, con las rodillas y las caderas flexionadas, elevá lentamente ambas piernas y pies, como se muestra. Los pies y las rodillas tienen que estar en contacto todo el tiempo.', 468),
  ('ARCO LARGO DE CUÁDRICEPS - LAQ - EXTENSIÓN PARCIAL DE RODILLA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Sentado, extendé la rodilla desde una posición flexionada a 90 grados hasta los 45 grados, como se muestra. Bajá la pierna de nuevo y repetí. Conviene hacerlo desde un asiento alto, una cama o una mesa.', 103732),
  ('PELOTA MANÍ - ARCO CORTO DE CUÁDRICEPS - SAQ', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Empezá colocando una pelota maní debajo de la rodilla. Después, elevá lentamente la pierna y el pie mientras estirás la rodilla. Volvé a la posición inicial y repetí.', 61514),
  ('CURL DE ISQUIOTIBIALES EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Acostado boca abajo, flexioná lentamente la rodilla mientras llevás el pie hacia la cola.', 143),
  ('EXTENSIÓN DE CADERA EN DECÚBITO VENTRAL - RODILLA FLEXIONADA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Acostado boca abajo con la rodilla flexionada, elevá lentamente la rodilla despegándola del piso.', 146),
  ('EXTENSIÓN DE CADERA EN CUATRO APOYOS', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Empezá en posición de gateo y después extendé la pierna hacia arriba desde la cadera, como se muestra. Mantené la rodilla flexionada a 90 grados todo el tiempo. Bajá de nuevo y repetí.', 24198),
  ('SENTADO - ALCANCES CON INCLINACIÓN', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Empezá sentado en una silla con los brazos a la altura del pecho. Después, llevá un brazo hacia el lado opuesto del cuerpo mientras estirás la pierna del mismo lado hacia el otro costado, como se muestra. Volvé a la posición inicial y repetí del lado contrario.', 171428),
  ('SENTADO - ABRIR LA PUERTA Y RETRACCIÓN DE HOMBROS', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Sentate en una silla con las piernas y las manos juntas, como se muestra. Separá los brazos y las piernas. Volvé a la posición inicial y repetí.', 171426),
  ('MARCHA SENTADO - ELEVACIONES DE BRAZO ALTERNADAS', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Sentado en una silla, despegá el pie del piso y elevá el brazo contrario hacia arriba. Bajá de nuevo y hacelo del lado contrario. Repetí este movimiento alternado.', 170798),
  ('ELEVACIÓN DE PIERNA ESTIRADA SENTADO - SLR', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Empezá sentado con las manos por detrás tuyo y ubicado hacia el borde delantero de la silla. La pierna afectada tiene que estar estirada en la rodilla, con el talón apoyado en el piso. Después, elevá la pierna manteniendo la rodilla estirada. Después bajá de nuevo y repetí.', 7127),
  ('ELEVACIÓN DE PIERNA ESTIRADA SENTADO - SLR', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Empezá sentado hacia el borde delantero de la silla con las manos apoyadas en el frente de la silla. La pierna afectada tiene que estar estirada en la rodilla, con el talón apoyado en el piso. Después, elevá la pierna manteniendo la rodilla estirada. Después bajá de nuevo y repetí.', 135768),
  ('ARCO CORTO DE CUÁDRICEPS - SILLA - SAQ', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Sentate en una mesa con una silla adelante tuyo O sentate en una silla con un banquito adelante. Apoyá el talón del pie sobre la superficie más baja con la rodilla flexionada a unos 20-45 grados. Después, estirá la rodilla de modo que el pie se despegue de la superficie y quede en el aire, como se muestra. Bajá de nuevo y repetí.', 83688),
  ('ARCO CORTO DE CUÁDRICEPS - VASTO INTERNO - SAQ - VMO', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Colocá una toalla enrollada u otro objeto debajo de la rodilla. Ubicá la pierna rotada hacia afuera. El pie tiene que apuntar hacia el costado, a unos 45 grados. Empezá estirando lentamente la rodilla mientras elevás el pie. Bajá de nuevo y repetí.', 81662),
  ('SKATE - FLEXIÓN Y EXTENSIÓN DE RODILLA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Sentate en una silla y apoyá el pie sobre un skate. De forma lenta y controlada, empujá el skate hacia adelante y después traelo hacia atrás, y repetí.', 78539),
  ('ABDUCCIÓN DE CADERA DE PIE - MESADA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Parado al lado de una mesada para apoyarte, elevá la pierna hacia el costado. Mantené la rodilla estirada y los dedos del pie apuntando hacia adelante lo mejor que puedas. Después, bajá la pierna de nuevo y repetí. Usá los brazos para ayudarte con el equilibrio si hace falta, por equilibrio y seguridad.', 165456),
  ('FLEXIÓN DE CADERA DE PIE - MESADA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Parado al lado de una mesada para apoyarte, elevá una pierna hacia adelante y despegala del piso con la rodilla estirada. Volvé a la posición inicial y repetí.', 165457),
  ('MARCHA DE PIE - FLEXIÓN DE CADERA - BILATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Parado al lado de una mesada para apoyarte, marchá en el lugar elevando la rodilla mientras dejás que se flexione. Bajá de nuevo y después hacelo del otro lado. Repetí este movimiento alternado.', 164803),
  ('MARCHA DE PIE - UNA PIERNA - FLEXIÓN DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Parado al lado de una silla o mesada para apoyarte, marchá en el lugar elevando la rodilla mientras dejás que se flexione. Bajá de nuevo y después hacelo del otro lado. Repetí este movimiento alternado.', 7003),
  ('HIDRANTE CON PIERNA ESTIRADA - ABDUCCIÓN HORIZONTAL DE CADERA EN CUATRO APOYOS', NULL, true, 'activo; fortalecimiento', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Empezá en posición de gateo y después estirá la pierna hacia el costado, como se muestra. Después, elevá la pierna despegándola del piso. Bajá de nuevo y repetí. Mantené la espalda alta y media derecha todo el tiempo.', 83154),
  ('ELEVACIÓN DE PIERNA ESTIRADA - SLR SENTADO CON PIERNAS EXTENDIDAS', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Sentate en el piso con una rodilla flexionada y la otra estirada. Apoyate colocando las manos en el piso por detrás tuyo. Después, elevá la pierna estirada despegándola del piso. Bajá de nuevo y repetí.', 130991),
  ('ELEVACIÓN DE PIERNA ESTIRADA 2 - SLR', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Acostado o sentado, elevá la pierna con la rodilla estirada. Mantené ambas rodillas estiradas todo el tiempo.', 544),
  ('LAQ EN DECÚBITO DORSAL - ARCO LARGO DE CUÁDRICEPS - EXTENSIÓN DE RODILLA COLGANDO', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Acostate y dejá que la pierna cuelgue por el costado, como se muestra, de modo que la rodilla se flexione hacia el piso. Extendé la rodilla para elevar el pie y la pierna hasta la posición de rodilla estirada. Después, bajá de nuevo y repetí.', 139358),
  ('MARCHA CON ANDADOR', NULL, true, 'activo_asistido', 'Cadera y rodilla', 'AROM (activo); Cadena abierta', 'Parado con un andador, elevá una rodilla dejando que se flexione mientras despegás el pie del piso. Volvé a apoyar el pie en el piso y después hacelo del otro lado y repetí. Colocá una silla atrás tuyo y debajo de la cola por seguridad.', 125302),
  ('EMBARAZO - COMBINACIÓN DE ESTIRAMIENTO DE PLEGARIA CON ESTIRAMIENTO EN ABDUCCIÓN DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Estiramientos', 'Empezá en posición de gateo y después estirá una pierna hacia el costado, como se muestra. Sentate hacia atrás mientras bajás la cola en dirección al talón del pie y apoyás los codos en el piso. Mantené este estiramiento, volvé a la posición inicial y repetí.', 180895),
  ('DESLIZAMIENTOS DE TALÓN SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Estiramientos', 'Sentado con el pie hacia adelante y apoyado en el piso, deslizá lentamente el pie acercándolo hacia vos. Mantené un estiramiento suave y después llevá el pie de nuevo hacia adelante, a la posición original.', 151),
  ('DESLIZAMIENTOS DE TALÓN SENTADO CON TOALLA', NULL, true, 'activo', 'Cadera y rodilla', 'AROM (activo); Estiramientos', 'Sentado, apoyá el pie sobre una toalla chica. Después, deslizá lentamente el pie acercándolo hacia vos. Mantené un estiramiento suave y después llevá el pie de nuevo hacia adelante, a la posición original.', 13125),
  ('BOSU - EQUILIBRIO EN UNA PIERNA HACIA ADELANTE', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Parate sobre una pelota Bosu con una pierna y mantené el equilibrio. Después, sostené la otra pierna estirada por delante del cuerpo. Después volvé a la posición original. Mantené la rodilla de apoyo levemente flexionada.', 5595),
  ('BOSU - EQUILIBRIO EN UNA PIERNA HACIA EL COSTADO', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Parate sobre una pelota Bosu con una pierna y mantené el equilibrio. Después, sostené la otra pierna hacia el costado del cuerpo. Después volvé a la posición original. Mantené la rodilla de apoyo levemente flexionada.', 5596),
  ('BOSU - EQUILIBRIO EN UNA PIERNA HACIA ATRÁS', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Parate sobre una pelota Bosu con una pierna y mantené el equilibrio. Después, sostené la otra pierna por detrás del cuerpo. Después volvé a la posición original. Mantené la rodilla de apoyo levemente flexionada.', 5597),
  ('BOSU - APOYO EN UNA PIERNA', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Parate sobre una pelota Bosu con una pierna y mantené el equilibrio. Mantené la rodilla de apoyo levemente flexionada.', 5594),
  ('CAMINATA CRUZADA - CARIOCA', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Dá pasos hacia el costado cruzando una pierna sobre la otra. Alterná cruzando la pierna por delante y después por detrás de la otra. Enfocate en movimientos lentos y controlados. NOTA: al hacerlo, tenés que desplazarte en una sola dirección durante varios metros y después hacerlo en la dirección contraria durante varios metros.', 555),
  ('VASOS - TOQUES ALTERNADOS', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Parate al lado de algo para ayudarte con el equilibrio si hace falta. Colocá un vaso de papel o de plástico en el piso. Parate frente al vaso y despegá un pie del piso mientras te equilibrás sobre la otra pierna. Tocá la parte de arriba del vaso con los dedos del pie. Después, apoyá el pie de nuevo y hacelo del otro lado. Si hace falta, apoyá la mano en una mesa para mantener el equilibrio. Si perdés el equilibrio, podés usar una o más estrategias para ayudarte: dar un paso, abrir los brazos hacia los costados o agarrarte de algo.', 54249),
  ('GERIÁTRICO - APOYO TÁNDEM CON SOPORTE', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Parate al lado de una silla, mesa o mesada y agarrate para apoyarte y por seguridad. Colocá el talón de uno de los pies de modo que toque los dedos del otro pie. Mantené el equilibrio en esta posición.', 124577),
  ('SALTO Y FRENO - HACIA ADELANTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio', 'Parate en una pierna y después saltá hacia adelante cayendo sobre la otra pierna. Mantené el equilibrio todo el tiempo. Aumentá la dificultad saltando más lejos o más alto.', 39675),
  ('SALTO Y FRENO - LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio', 'Parate en una pierna y después saltá hacia el costado cayendo sobre la otra pierna. Mantené el equilibrio todo el tiempo. Aumentá la dificultad saltando más lejos y más alto hacia el costado.', 39676),
  ('BOSU INVERTIDO - EQUILIBRIO EN DOS PIERNAS', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Mantené el equilibrio parado sobre una pelota Bosu invertida con las dos piernas.', 5577),
  ('BOSU INVERTIDO - INCLINACIÓN LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Mantené el equilibrio parado sobre una pelota Bosu invertida con las dos piernas. Después, inclina el Bosu de lado a lado manteniendo el equilibrio.', 5583),
  ('KETTLEBELL - HALO EN APOYO SOBRE UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio', 'Sostené una kettlebell invertida y equilibrate sobre una pierna. Después, movés la kettlebell alrededor de la cabeza manteniendo el equilibrio.', 28623),
  ('PASOS LATERALES', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Dá pasos laterales en una dirección durante varios pasos. Después, invertí la dirección y dá pasos laterales hasta volver al mismo lugar. Mantené el equilibrio y dá pasos controlados.', 123486),
  ('PASOS LATERALES CON APOYO - MESA - MESADA', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Parate frente a una mesa firme o una mesada. Dá pasos laterales y usá la mesa o la mesada para apoyarte.', 114186),
  ('MARCHA EN EL LUGAR - SUPERFICIE ESTABLE', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Marchá en el lugar y mantené el equilibrio. Mantené la cabeza mirando hacia adelante.', 120516),
  ('MARCHA EN EL LUGAR - SUPERFICIE INESTABLE', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Marchá en el lugar sobre una almohadilla de equilibrio o una toalla doblada. Mantené el equilibrio. Mantené la cabeza mirando hacia adelante.', 120518),
  ('MARCHA EN EL LUGAR CON MOVIMIENTOS DE CABEZA - SUPERFICIE ESTABLE', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Marchá en el lugar mientras girás la cabeza de lado a lado y hacia arriba y abajo. Mantené el equilibrio. Reducí el rango de movimiento de la cabeza si te resulta muy difícil.', 120517),
  ('MARCHA EN EL LUGAR CON MOVIMIENTOS DE CABEZA - SUPERFICIE INESTABLE', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Marchá en el lugar sobre una almohadilla de equilibrio o una toalla doblada mientras girás la cabeza de lado a lado y hacia arriba y abajo. Mantené el equilibrio. Reducí el rango de movimiento de la cabeza si te resulta muy difícil.', 120519),
  ('BALÓN MEDICINAL - LANZAMIENTO EN APOYO SOBRE UNA PIERNA - SLS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio', 'Lanzá un balón medicinal al aire y atajalo mientras mantenés el equilibrio sobre una pierna.', 6247),
  ('EQUILIBRIO EN TÁNDEM PARCIAL', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Colocá el talón de un pie de modo que toque el medio del otro pie, como se muestra. Mantené el equilibrio en esta posición.', 164278),
  ('EQUILIBRIO EN TÁNDEM PARCIAL CON APOYO', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Parate frente a una silla, mesa o mesada para apoyarte. Después, colocá el talón de un pie de modo que toque el medio del otro pie. Mantené el equilibrio en esta posición.', 164279),
  ('SALTO Y FRENO EN UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio', 'Parate en una pierna y después saltá hacia adelante cayendo sobre el pie de la misma pierna. Hacé 3 saltos hacia adelante y, en la última caída, equilibrate y frená la caída (mantené la posición sobre un pie). Aumentá la distancia o la altura del salto para progresar en este ejercicio.', 76598),
  ('APOYO EN UNA PIERNA - ALCANCE HACIA ADELANTE SLS', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Parate en una pierna y mantené el equilibrio. Después, estirá el brazo contrario hacia adelante todo lo que puedas sin perder el equilibrio. Después volvé a la posición original. Mantené la rodilla de apoyo levemente flexionada.', 23),
  ('APOYO EN UNA PIERNA - ALCANCE CON GIRO SLS', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio', 'Parate en una pierna y mantené el equilibrio. Después, estirá el brazo contrario hacia adelante y cruzando el cuerpo todo lo que puedas sin perder el equilibrio. Después volvé a la posición original. Mantené la rodilla de apoyo levemente flexionada.', 24),
  ('CAÍDAS CONTRA LA PARED - HACIA ADELANTE - EJERCICIO DE EQUILIBRIO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio', 'Parate frente a una pared, a medio metro de distancia. Después, de forma lenta y controlada, inclinate hacia adelante en dirección a la pared. Tratá de controlar el equilibrio para no caerte hacia adelante, pero seguí inclinándote cada vez más hasta que finalmente perdés el equilibrio y caés hacia la pared. Usá los brazos para frenar la caída y después empujate para volver a la posición erguida y repetí. Mantené activados los músculos abdominales, los glúteos y los muslos (cuádriceps) durante el ejercicio.', 39157),
  ('CAÍDAS CONTRA LA PARED - LATERAL - EJERCICIO DE EQUILIBRIO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio', 'Parate de costado al lado de una pared, a medio metro de distancia. Después, de forma lenta y controlada, inclinate hacia el costado en dirección a la pared. Tratá de controlar el equilibrio para no caerte de costado, pero seguí inclinándote cada vez más hasta que finalmente perdés el equilibrio y caés hacia la pared. Usá el brazo para frenar la caída y después empujate para volver a la posición erguida y repetí. Mantené activados los músculos abdominales, los glúteos y los muslos (cuádriceps) durante el ejercicio.', 39159),
  ('CAÍDAS CONTRA LA PARED - HACIA ATRÁS - EJERCICIO DE EQUILIBRIO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio', 'Parate de espaldas a una pared, a medio metro de distancia. Después, de forma lenta y controlada, inclinate hacia atrás en dirección a la pared. Tratá de controlar el equilibrio para no caerte hacia atrás, pero seguí inclinándote cada vez más hasta que finalmente perdés el equilibrio y caés. Usá la espalda alta para frenar la caída y después empujate para volver a la posición erguida y repetí. Mantené activados los músculos abdominales, los glúteos y los muslos (cuádriceps) durante el ejercicio.', 39161),
  ('RODADOS CON PELOTA - TALÓN Y PUNTA', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio; Pelota', 'En posición de pie, apoyá un pie sobre una pelota y rodala hacia adelante y atrás con un movimiento controlado, del talón a la punta, mientras mantenés el equilibrio.', 12624),
  ('RODADOS CON PELOTA - LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio; Pelota', 'En posición de pie, apoyá un pie sobre una pelota y rodala de lado a lado con un movimiento controlado, del borde interno al borde externo del pie, mientras mantenés el equilibrio.', 12625),
  ('PELOTA DE EJERCICIOS - EQUILIBRIO EN UNA PIERNA', NULL, true, 'activo', 'Cadera y rodilla', 'Equilibrio; Pelota', 'Sentado sobre una pelota de ejercicios, elevá una pierna despegándola del piso y equilibrate sobre la otra. Si hace falta, agarrate de la pelota con las manos para apoyarte.', 321),
  ('APOYO EN UNA PIERNA - SLS RODANDO PELOTA EN SUPERFICIE INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota', 'Parate sobre una superficie inestable, como una almohadilla de equilibrio o una toalla doblada. Usá el otro pie para rodar un balón medicinal chico alrededor de la pierna de apoyo.', 139356),
  ('LANZAMIENTO DE PELOTA - BOSU INVERTIDO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Bosu; Cadena cerrada', 'Parado con los pies sobre un Bosu invertido, lanzá y atajá una pelota manteniendo el equilibrio. Podés lanzarla a un compañero o contra una pared. Mantené las rodillas levemente flexionadas, a unos 30 grados, mientras hacés este ejercicio.', 7371),
  ('LANZAMIENTO DE PELOTA - UNA PIERNA - BOSU INVERTIDO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Bosu; Cadena cerrada', 'Parado con un pie sobre un Bosu invertido, lanzá y atajá una pelota manteniendo el equilibrio. Mantené las rodillas levemente flexionadas, a unos 30 grados, mientras hacés este ejercicio.', 7372),
  ('PIE SOBRE EL ESCALÓN CON ROTACIONES - CON PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Cajones y escalones', 'Parate con un pie arriba de un escalón. Después, sosteniendo una pelota por delante del cuerpo, rotá el tronco de lado a lado.', 11808),
  ('LANZAMIENTO DE PELOTA - TABLA BASCULANTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Cadena cerrada', 'Parado sobre una superficie inestable, como una tabla basculante, lanzá y atajá una pelota manteniendo el equilibrio. La tabla tiene que estar en posición de balanceo lateral. Podés lanzarla a un compañero o contra una pared. Si no tenés tabla basculante, podés usar una almohada. Mantené las rodillas levemente flexionadas, a unos 30 grados, mientras hacés este ejercicio.', 7373),
  ('LANZAMIENTO DE PELOTA EN LA PARED - BASE DE APOYO ANGOSTA - APOYO BIPODAL - SUPERFICIE INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Cadena cerrada', 'Parate arriba de una almohadilla de equilibrio, almohada, almohadón u otra superficie inestable. Equilibrate sobre ambas piernas con los pies juntos. Lanzá una pelota contra la pared y atajala mientras mantenés el equilibrio. Si perdés el equilibrio, podés dar un paso si hace falta o tener cerca algo firme para agarrarte.', 121798),
  ('LANZAMIENTO DE PELOTA EN LA PARED - BASE DE APOYO AMPLIA - APOYO BIPODAL - SUPERFICIE INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Cadena cerrada', 'Parate arriba de una almohadilla de equilibrio, almohada, almohadón u otra superficie inestable. Equilibrate sobre ambas piernas con los pies separados al ancho de la cadera. Lanzá una pelota contra la pared y atajala mientras mantenés el equilibrio. Si perdés el equilibrio, podés dar un paso si hace falta o tener cerca algo firme para agarrarte.', 121799),
  ('PELOTA DE EJERCICIOS - SENTADILLA A UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Cadena cerrada', 'Parate en una pierna y apoyá el otro pie sobre una pelota de ejercicios, como se muestra. Hacé una sentadilla a una pierna manteniendo la espalda derecha y flexionando desde la cadera. Asegurate de que la rodilla no pase el frente de los dedos del pie. Empujá con el talón para volver a subir a la posición inicial y repetí.', 174646),
  ('EQUILIBRIO EN ALMOHADILLA DE ESPUMA - LANZAMIENTO DE PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Cadena cerrada', 'Parado sobre una superficie inestable, como una almohadilla de espuma, lanzá y atajá una pelota manteniendo el equilibrio. Podés lanzarla a un compañero o contra una pared. Si no tenés almohadilla de espuma, podés usar una almohada. Mantené las rodillas levemente flexionadas, a unos 30 grados, mientras hacés este ejercicio.', 7370),
  ('EQUILIBRIO EN UNA PIERNA - SUPERFICIE INESTABLE - LANZAMIENTO DE PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Cadena cerrada', 'Parate arriba de una almohadilla de equilibrio, almohada, almohadón u otra superficie inestable. Equilibrate sobre una pierna y ubicate de modo que la pared quede adelante tuyo. Lanzá una pelota contra la pared y atajala mientras mantenés el equilibrio. Si perdés el equilibrio, podés apoyar la punta del otro pie o dar un paso si hace falta.', 75023),
  ('EQUILIBRIO EN UNA PIERNA - SUPERFICIE INESTABLE - LANZAMIENTO LATERAL DE PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Cadena cerrada', 'Parate arriba de una almohadilla de equilibrio, almohada, almohadón u otra superficie inestable. Equilibrate sobre una pierna y ubicate de modo que la pared quede del lado de la pierna de apoyo. Lanzá una pelota contra la pared y atajala mientras mantenés el equilibrio. Si perdés el equilibrio, podés apoyar la punta del otro pie o dar un paso si hace falta.', 75020),
  ('EQUILIBRIO EN UNA PIERNA - SUPERFICIE INESTABLE - LANZAMIENTO MEDIAL DE PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pelota; Cadena cerrada', 'Parate arriba de una almohadilla de equilibrio, almohada, almohadón u otra superficie inestable. Equilibrate sobre una pierna y ubicate de modo que la pared quede del lado contrario a la pierna de apoyo. Lanzá una pelota contra la pared y atajala mientras mantenés el equilibrio. Si perdés el equilibrio, podés apoyar la punta del otro pie o dar un paso si hace falta.', 75022),
  ('BOSU - EQUILIBRIO SOBRE UNA RODILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Bosu', 'Mantené el equilibrio arrodillado sobre una rodilla encima de una pelota Bosu.', 5591),
  ('BOSU - APOYO EN UNA PIERNA HACIA ATRÁS Y AFUERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Bosu', 'Parate sobre una pelota Bosu con una pierna y mantené el equilibrio. Después, sostené la otra pierna por detrás y cruzando el cuerpo. Después volvé a la posición original. Mantené la rodilla de apoyo levemente flexionada.', 5598),
  ('BOSU - ESTOCADA INVERTIDA - PIE FIJO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Bosu; Cadena cerrada', 'Parado en el piso con una pelota Bosu por detrás tuyo, dá un paso hacia atrás apoyando el pie sobre el Bosu. Dejá que la rodilla de adelante y la de atrás se flexionen mientras bajás hacia el piso. No dejes que la rodilla de adelante pase los dedos del pie. Después, estirá la rodilla de adelante y volvé a subir, pero dejá el pie de atrás sobre el Bosu. Después, volvé a bajar flexionando ambas rodillas y subí de nuevo. Repetí.', 78218),
  ('BOSU INVERTIDO - GIRO CON PELOTA ABAJO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Bosu; Cadena cerrada', 'Mantené el equilibrio parado sobre una pelota Bosu invertida con las dos piernas. Después, sosteniendo una pelota, bajá los brazos y llevá la pelota al costado de la rodilla. Volvé a la posición de pie mientras llevás la pelota al pecho y después repetí del otro lado.', 5581),
  ('BOSU - SWING DE GOLF', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Bosu; Cadena cerrada; Varios', 'Parate sobre un Bosu sosteniendo un palo de golf y practicá swings con esfuerzo parcial. Mantené el equilibrio y una buena técnica de golf.', 18688),
  ('APOYO EN UNA PIERNA SOBRE ESCALÓN - ALCANCE EN RELOJ SLS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cajones y escalones', 'Empezá parado sobre un escalón con ambos pies. Después, parate en una pierna y equilibrate. Después, llevá la otra pierna hacia atrás y cruzando por detrás de la pierna de apoyo, como se muestra, tocando el piso con la punta del pie, y después volvé a la posición original.', 12915),
  ('ESTOCADA HACIA ADELANTE - CAJÓN - INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cajones y escalones; Cadena cerrada', 'Parado en el piso con un escalón adelante tuyo, colocá el pie hacia adelante sobre un escalón inestable, como se muestra. Podés poner una almohadilla de espuma arriba del escalón, como se ve. Dejá que la rodilla de adelante y la de atrás se flexionen mientras bajás la rodilla de atrás hacia el piso en posición de estocada. No dejes que la rodilla de adelante pase los dedos del pie. Volvé a la posición original y después hacelo con la otra pierna. Progresá sosteniendo pesas.', 7381),
  ('SUBIDA A SUPERFICIE INESTABLE - DIAGONAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cajones y escalones; Cadena cerrada', 'Subí hacia adelante y en diagonal a un escalón inestable. Podés poner una almohadilla de espuma arriba del escalón, como se muestra. Caé sobre una pierna con unos 30 grados de flexión de rodilla. Después volvé a la posición original.', 7374),
  ('APOYO DEL PIE HACIA ADELANTE SOBRE EL ESCALÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cajones y escalones; Cadena abierta', 'Parado con ambos pies en el piso, apoyá un pie arriba del escalón. Después, volvé con el pie al piso y repetí con la misma pierna. Mantené el equilibrio y asegurate de apoyar bien el talón en el escalón. Puede que necesites agarrarte de algo para mantener el equilibrio.', 95395),
  ('APOYO LATERAL DEL PIE SOBRE EL ESCALÓN - NIVEL 1', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cajones y escalones; Cadena abierta', 'Parado con ambos pies en el piso y un banquito o escalón a tu costado, apoyá un pie arriba del escalón. Después, volvé con el pie al piso y repetí con la misma pierna. Mantené el equilibrio y asegurate de apoyar bien el talón en el escalón. Puede que necesites agarrarte de algo para mantener el equilibrio.', 95399),
  ('APOYO LATERAL DEL PIE SOBRE EL ESCALÓN - NIVEL 2', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cajones y escalones; Cadena abierta', 'Parado con ambos pies en el piso y un banquito o escalón a tu costado, apoyá un pie arriba del escalón. Colocá el pie lo suficientemente lejos como para que quede lugar para el otro pie en un ejercicio posterior. Después, volvé con el pie al piso y repetí con la misma pierna. Mantené el equilibrio y asegurate de apoyar bien el talón en el escalón. Puede que necesites agarrarte de algo para mantener el equilibrio.', 95400),
  ('ESTOCADA CON SALTO EN TIJERA - CAJÓN - INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cajones y escalones; Pliometría', 'Empezá en posición de estocada, como se muestra, con el pie de adelante arriba de un escalón o cajón que tenga una superficie inestable, como una almohadilla de espuma en la parte de arriba. Después, saltá y cambiá de pierna de modo que el pie contrario caiga sobre la almohadilla o el escalón mientras bajás a la posición de estocada. No dejes que la rodilla de adelante pase los dedos del pie. Seguí saltando y alternando las piernas.', 7391),
  ('BOSU - ESTOCADA HACIA ADELANTE - UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parado en el piso frente a una pelota Bosu, dá un paso hacia adelante apoyando el pie sobre el Bosu. Dejá que la rodilla de adelante y la de atrás se flexionen mientras bajás hacia el piso. No dejes que la rodilla de adelante pase los dedos del pie. Volvé a la posición original y después hacelo del mismo lado y repetí.', 78216),
  ('BOSU - ESTOCADA HACIA ADELANTE ALTERNADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parado en el piso frente a una pelota Bosu, dá un paso hacia adelante apoyando el pie sobre el Bosu. Dejá que la rodilla de adelante y la de atrás se flexionen mientras bajás hacia el piso. No dejes que la rodilla de adelante pase los dedos del pie. Volvé a la posición original y después hacelo con la otra pierna.', 5584),
  ('BOSU - SUBIDA LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Con la pelota Bosu a tu costado, subí de costado arriba de la pelota. Después bajá del otro lado y repetí en la dirección contraria.', 5582),
  ('BOSU - ESTOCADA - PIE FIJO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parado en el piso frente a una pelota Bosu, dá un paso hacia adelante apoyando el pie sobre el Bosu. Dejá que la rodilla de adelante y la de atrás se flexionen mientras bajás hacia el piso. No dejes que la rodilla de adelante pase los dedos del pie. Después, estirá la rodilla de adelante y volvé a subir, pero dejá el pie de adelante sobre el Bosu. Después, volvé a bajar flexionando ambas rodillas y subí de nuevo. Repetí.', 78214),
  ('BOSU - ESTOCADA CON GIRO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parado en el piso frente a una pelota Bosu, dá un paso hacia adelante apoyando el pie sobre el Bosu. Dejá que la rodilla de adelante y la de atrás se flexionen mientras bajás hacia el piso en posición de estocada. Una vez en la estocada, rotá el tronco hacia el costado. La rodilla de adelante tiene que flexionarse alineada con el segundo dedo del pie y no pasar el frente del pie. Mantené la columna derecha. Volvé a la posición original y después hacelo del otro lado.', 5585),
  ('BOSU - SENTADILLA A UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parado y en equilibrio sobre una pelota Bosu con una pierna, flexioná la rodilla y bajá el cuerpo hacia el piso. Volvé a la posición de pie. La rodilla de apoyo debe flexionarse alineada con el segundo dedo del pie y no pasar la punta del pie.', 5592),
  ('BOSU - SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parado y manteniendo el equilibrio sobre una pelota Bosu, hacé una sentadilla y volvé a la posición de pie. Las rodillas deben flexionarse alineadas con el segundo dedo del pie y no pasar la punta del pie.', 5599),
  ('BOSU - SUBIDA AL ESCALÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parado frente a una pelota Bosu con ambos pies en el piso, subí a la Bosu con los dos pies. Bajá hacia atrás al piso empezando con la misma pierna.', 5593),
  ('SENTADO A DE PIE EN SILLA - SENTADILLA A UNA PIERNA - SIN MANOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Empezá sentado en una silla. Con un pie en el piso, presioná el talón contra el piso y parate. Llevá los brazos hacia adelante como contrapeso. Mantené la espalda derecha y flexioná desde la cadera. Asegurate de que la rodilla no pase la punta de los dedos del pie. Empujá con el talón para volver a subir a la posición inicial y repetí.', 174645),
  ('TOQUES DE CONO - PIE ALTERNADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá un cono adelante tuyo, como se muestra. Mantené el equilibrio con la rodilla levemente flexionada mientras elevás un pie y lo apoyás sobre la punta del cono. Bajá el pie y repetí con el otro pie. Repetí.', 80399),
  ('TOQUES DE CONO - MANO ALTERNADA - UNA PIERNA', NULL, true, 'pasivo', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá un cono adelante tuyo, como se muestra. Mantené el equilibrio con la rodilla levemente flexionada y bajá el cuerpo para tocar la punta del cono. Volvé a la posición original, tocá el mismo cono con la otra mano y volvé a la posición original. Repetí.', 80396),
  ('TOQUES DE CONO - MANO - UNA PIERNA - MULTIDIRECCIONAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá 5 conos o vasos alrededor tuyo, como se muestra. Mantené el equilibrio con la rodilla levemente flexionada y bajá el cuerpo para tocar la punta de un cono. Volvé a la posición original y repetí tocando un cono distinto hasta tocar los 5. Después repetí. Usá el brazo y la pierna contrarios para equilibrarte.', 80394),
  ('TOQUES DE CONO - UNA PIERNA - ADELANTE Y ATRÁS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá 1 cono adelante tuyo y 1 atrás, como se muestra. Mantené el equilibrio con la rodilla levemente flexionada mientras elevás un pie y lo apoyás sobre la punta del cono de adelante. Después, tocá el cono de atrás con el mismo pie. Repetí alternando los toques en cada cono.', 80407),
  ('TOQUES DE CONO - APOYO EN UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá 5 conos o vasos alrededor tuyo, como se muestra. Mantené el equilibrio con la rodilla levemente flexionada. Sosteniendo una pelota, bajá el cuerpo para tocar la punta de un cono con la pelota. Volvé a la posición original y repetí tocando un cono distinto. Mantené las dos manos en la pelota todo el tiempo. Podés progresar usando conos o vasos más chicos y/o más velocidad.', 7382),
  ('TOQUES DE CONO - APOYO EN UNA PIERNA - LANZAMIENTO DE PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá 5 conos o vasos alrededor tuyo, como se muestra. Mantené el equilibrio con la rodilla levemente flexionada. Atajá una pelota, bajá el cuerpo para tocar la punta de un cono con la pelota y devolvé la pelota. Repetí tocando un cono distinto. Mantené las dos manos en la pelota mientras tocás el cono. Si no tenés compañero, lanzá la pelota contra una pared. Podés progresar usando conos o vasos más chicos y/o más velocidad.', 7384),
  ('TOQUES DE CONO - APOYO EN UNA PIERNA - INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá 5 conos o vasos alrededor tuyo, como se muestra. Mantené el equilibrio sobre una superficie inestable, como una almohadilla de espuma, con la rodilla levemente flexionada. Sosteniendo una pelota, bajá el cuerpo para tocar la punta de un cono con la pelota. Volvé a la posición original y repetí tocando un cono distinto. Mantené las dos manos en la pelota todo el tiempo. Podés progresar usando conos o vasos más chicos y/o más velocidad.', 7383),
  ('TOQUES DE CONO - APOYO EN UNA PIERNA - INESTABLE - LANZAMIENTO DE PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá 5 conos o vasos alrededor tuyo, como se muestra. Mantené el equilibrio con la rodilla levemente flexionada y sobre una superficie inestable, como una almohadilla de espuma. Atajá una pelota, bajá el cuerpo para tocar la punta de un cono con la pelota y devolvé la pelota. Repetí tocando un cono distinto. Mantené las dos manos en la pelota mientras tocás el cono. Si no tenés compañero, lanzá la pelota contra una pared. Podés progresar usando conos o vasos más chicos y/o más velocidad.', 7385),
  ('CAÍDA HACIA ATRÁS - RECUPERACIÓN CON PASO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Empezá en posición de pie con los pies separados. Después, inclinate lentamente hacia atrás y tratá de no perder el equilibrio. Seguí inclinándote hacia atrás hasta que finalmente pierdas el equilibrio y tengas que dar un paso para no caerte.', 39674),
  ('CAÍDA HACIA ADELANTE - RECUPERACIÓN CON PASO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Empezá en posición de pie con los pies separados. Después, inclinate lentamente hacia adelante y tratá de no perder el equilibrio. Seguí inclinándote hacia adelante hasta que finalmente pierdas el equilibrio y tengas que dar un paso para no caerte.', 39672),
  ('CAÍDA LATERAL - RECUPERACIÓN CON PASO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Empezá en posición de pie con los pies separados. Después, inclinate lentamente hacia el costado y tratá de no perder el equilibrio. Seguí inclinándote hacia el costado hasta que finalmente pierdas el equilibrio y tengas que dar un paso para no caerte.', 39673),
  ('TOQUE AL PISO - PIE SOBRE EL CONO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá un cono adelante tuyo, como se muestra. Mantené el equilibrio con la rodilla levemente flexionada mientras elevás un pie y tocás el piso de un lado del cono. Después, pasá el pie por encima del cono para tocar el piso del otro lado. Repetí y seguí con este movimiento alternando los lados.', 80400),
  ('TOQUE AL PISO - PIE SOBRE EL CONO - SUPERFICIE INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá un cono adelante tuyo, como se muestra. Mantené el equilibrio sobre una almohadilla de espuma con la rodilla levemente flexionada mientras elevás un pie y tocás el piso de un lado del cono. Después, pasá el pie por encima del cono para tocar el piso del otro lado. Repetí y seguí con este movimiento alternando los lados.', 80404),
  ('RODILLO DE ESPUMA - EQUILIBRIO EN APOYO BIPODAL AMPLIO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá medio rodillo de espuma en el piso en dirección lateral, con el lado plano hacia arriba. Parate sobre el rodillo con los pies separados y mantené el equilibrio.', 8984),
  ('RODILLO DE ESPUMA - CAMINATA EN TÁNDEM', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá medio rodillo de espuma en el piso en dirección adelante-atrás, con el lado redondeado hacia arriba. Parate sobre el rodillo y empezá a caminar en tándem (talón-punta, como se muestra). Cuando llegues al final del rodillo, caminá en tándem hacia atrás. Tratá de mantener el equilibrio sin bajarte del rodillo.', 8995),
  ('ESTOCADA EN RODILLO DE ESPUMA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá medio rodillo de espuma en el piso en dirección adelante-atrás, con el lado redondeado hacia arriba. Hacé una estocada manteniendo el equilibrio.', 8986),
  ('APOYO EN TÁNDEM SOBRE RODILLO DE ESPUMA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá medio rodillo de espuma en el piso en dirección adelante-atrás, con el lado plano hacia arriba. Parate sobre el rodillo en apoyo tándem (con el talón y la punta en contacto, como se muestra) y mantené el equilibrio.', 8994),
  ('MEDIO RODILLO DE ESPUMA - EQUILIBRIO EN APOYO BIPODAL ANGOSTO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Colocá medio rodillo de espuma en el piso en dirección lateral, con el lado plano hacia arriba. Parate sobre el rodillo con los pies juntos y mantené el equilibrio.', 8983),
  ('BOSU INVERTIDO - SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parado y manteniendo el equilibrio sobre una pelota Bosu invertida, hacé una sentadilla y volvé a la posición de pie. Las rodillas deben flexionarse alineadas con el segundo dedo del pie y no pasar la punta del pie.', 5580),
  ('MINI ESTOCADA LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Dá un paso hacia el costado y equilibrate sobre esa pierna. Después volvé a la posición original. Las rodillas deben estar flexionadas unos 30 grados durante el ejercicio. Si necesitás, parate frente a un objeto para equilibrarte.', 10043),
  ('MINI SENTADILLA - APOYO INESTABLE - TABLA BASCULANTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Empezá con los pies separados al ancho de los hombros, las puntas de los pies hacia adelante y parado sobre una tabla basculante. Después, flexioná las rodillas hasta unos 30 grados para hacer una mini sentadilla, como se muestra. Después volvé a la posición original. Tratá de mantener la tabla nivelada durante el ejercicio. Las rodillas deben flexionarse alineadas con el segundo dedo del pie y no pasar la punta del pie.', 7348),
  ('APOYO DE ROMBERG', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parate erguido y con los pies juntos, al lado de una mesa u otro objeto firme. Con los pies juntos y los brazos cruzados sobre el pecho, mantené el equilibrio en esta posición. Tratá de sostener la posición lo mejor que puedas. Si perdés el equilibrio, podés usar una o más estrategias para ayudarte: dar un paso, descruzar los brazos y elevarlos hacia los costados, o agarrarte de algo para apoyarte.', 54262),
  ('APOYO DE ROMBERG - OJOS CERRADOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parate erguido y con los pies juntos, al lado de una mesa u otro objeto firme. Con los pies juntos y los brazos cruzados sobre el pecho, mantené el equilibrio en esta posición... después, cerrá los ojos. Tratá de sostener la posición con los ojos cerrados lo mejor que puedas. Si perdés el equilibrio, podés usar una o más estrategias para ayudarte: abrir los ojos, dar un paso, descruzar los brazos y elevarlos hacia los costados, o agarrarte de algo para apoyarte.', 54255),
  ('APOYO DE ROMBERG - UNA PIERNA - OJOS CERRADOS - SLS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Cruzá los brazos sobre el pecho y después parate sobre una pierna. Hacelo al lado de una mesa u otro objeto firme. Mantené el equilibrio en esta posición... después, cerrá los ojos. Tratá de sostener la posición con los ojos cerrados lo mejor que puedas. Si perdés el equilibrio, podés usar una o más estrategias para ayudarte: abrir los ojos, apoyar la punta del pie, dar un paso, descruzar los brazos y elevarlos hacia los costados, o agarrarte de algo para apoyarte.', 54256),
  ('APOYO DE ROMBERG - INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parate sobre una almohadilla de equilibrio, almohada, almohadón u otra superficie inestable. Parate erguido con los pies juntos y al lado de una mesa u otro objeto firme. Con los pies juntos y los brazos cruzados sobre el pecho, mantené el equilibrio en esta posición... después, cerrá los ojos. Tratá de sostener la posición con los ojos cerrados lo mejor que puedas. Si perdés el equilibrio, podés usar una o más estrategias para ayudarte: dar un paso, descruzar los brazos y elevarlos hacia los costados, o agarrarte de algo para apoyarte.', 54263),
  ('APOYO DE ROMBERG - INESTABLE - OJOS CERRADOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parate sobre una almohadilla de equilibrio, almohada, almohadón u otra superficie inestable. Parate erguido con los pies juntos y al lado de una mesa u otro objeto firme. Con los pies juntos y los brazos cruzados sobre el pecho, mantené el equilibrio en esta posición... después, cerrá los ojos. Tratá de sostener la posición con los ojos cerrados lo mejor que puedas. Si perdés el equilibrio, podés usar una o más estrategias para ayudarte: abrir los ojos, dar un paso, descruzar los brazos y elevarlos hacia los costados, o agarrarte de algo para apoyarte.', 54259),
  ('APOYO DE ROMBERG - INESTABLE - UNA PIERNA - OJOS CERRADOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parate sobre una almohadilla de equilibrio, almohada, almohadón u otra superficie inestable. Equilibrate sobre una pierna y cruzá los brazos sobre el pecho. Hacelo al lado de una mesa u otro objeto firme. Mantené el equilibrio en esta posición... después, cerrá los ojos. Si perdés el equilibrio, podés usar una o más estrategias para ayudarte: abrir los ojos, apoyar la punta del pie, dar un paso, descruzar los brazos y elevarlos hacia los costados, o agarrarte de algo para apoyarte.', 54264),
  ('BAJADA DEL ESCALÓN - ADELANTE - INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Empezá con ambos pies sobre un escalón o cajón y sobre una superficie inestable, como una almohadilla de espuma. Después, bajá lentamente la pierna sana hacia adelante, fuera del escalón, para tocar suavemente el piso con el talón. Después volvé a la posición original con ambos pies sobre el escalón. Mantené la alineación correcta de la rodilla: alineada con el segundo dedo del pie y sin pasar la punta de los dedos.', 7393),
  ('BAJADA DEL ESCALÓN - LATERAL - INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Empezá con ambos pies sobre un escalón o cajón y sobre una superficie inestable, como una almohadilla de espuma. Después, bajá lentamente la pierna sana por el costado del escalón para tocar suavemente el piso con el talón. Después volvé a la posición original con ambos pies sobre el escalón. Mantené la alineación correcta de la rodilla: alineada con el segundo dedo del pie y sin pasar la punta de los dedos.', 7395),
  ('SUBIDA A SUPERFICIE INESTABLE - ADELANTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Subí hacia adelante a un escalón inestable. Podés colocar una almohadilla de espuma sobre un escalón, como se muestra. Caé sobre una pierna con unos 30 grados de flexión de rodilla. Después volvé a la posición original.', 7375),
  ('SUBIDA A SUPERFICIE INESTABLE - LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Subí de costado a un escalón inestable. Podés colocar una almohadilla de espuma sobre un escalón, como se muestra. Caé sobre una pierna con unos 30 grados de flexión de rodilla. Después volvé a la posición original.', 7379),
  ('TOQUE CON LA PUNTA DEL PIE Y MANTENER EN EL ESCALÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parate frente a un escalón y elevá el pie que vas a trabajar mientras te equilibrás sobre la otra pierna. Tocá la parte de arriba del escalón con la punta de los dedos del pie a trabajar. Mantené esta posición mientras conservás el equilibrio. Después, volvé a apoyar el pie y repetí del mismo lado.', 54266),
  ('TRX - ESTOCADA CRUZADA DE EQUILIBRIO PLIOMÉTRICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Sostené las manijas del TRX de frente al anclaje. Parate sobre una pierna y llevá la otra hacia atrás y cruzando la línea media mientras flexionás la rodilla de apoyo, como se muestra. Al volver a la posición erguida, estirá la rodilla de apoyo e impulsate en un salto chico mientras la otra rodilla sube hasta la altura de la cintura o más. No dejes que la rodilla de apoyo pase la punta de los dedos del pie. Mantené la rodilla de apoyo alineada con el pie.', 31459),
  ('TRX - ESTOCADA CRUZADA DE EQUILIBRIO CON POTENCIA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Sostené las manijas del TRX de frente al anclaje. Parate sobre una pierna y llevá la otra hacia atrás y cruzando la línea media mientras flexionás la rodilla de apoyo, como se muestra. Al volver a la posición erguida, estirá la rodilla de apoyo mientras la otra rodilla sube hasta la altura de la cintura o más. No dejes que la rodilla de apoyo pase la punta de los dedos del pie. Mantené la rodilla de apoyo alineada con el pie.', 31490),
  ('TRX - ESTOCADA INVERSA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Sostené las manijas del TRX de frente al anclaje. Parate sobre una pierna y llevá la otra hacia atrás mientras flexionás la rodilla del lado de apoyo, como se muestra. Después, volvé a la posición erguida estirando la rodilla de apoyo. No dejes que la rodilla de apoyo pase la punta de los dedos del pie. Mantené la rodilla de apoyo alineada con el pie.', 31421)
INSERT INTO exercise_library (name, professional_id, is_active, exercise_type, catalog_region, catalog_subcategory, instructions, source_exercise_id)
VALUES
  ('TRX - ESTOCADA INVERSA CON POTENCIA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Sostené las manijas del TRX de frente al anclaje. Parate sobre una pierna y llevá la otra hacia atrás mientras flexionás la rodilla del lado de apoyo, como se muestra. Al volver a la posición erguida, estirá la rodilla de apoyo e impulsá la otra rodilla hacia arriba hasta 90 grados o más, como se muestra. No dejes que la rodilla de apoyo pase la punta de los dedos del pie. Mantené la rodilla de apoyo alineada con el pie.', 31415),
  ('CAÍDAS CONTRA LA PARED - UNA PIERNA - ADELANTE - EJERCICIO DE EQUILIBRIO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parate sobre una pierna de frente a una pared, a medio metro de distancia. Después, lenta y controladamente, inclinate hacia adelante en dirección a la pared. Tratá de controlar el equilibrio para no caerte hacia adelante, pero seguí inclinándote cada vez más hasta que finalmente pierdas el equilibrio y caigas. Usá los brazos para frenar la caída y después empujate para volver a la posición erguida y repetí. Mantené activados los músculos abdominales, los glúteos y los cuádriceps durante el ejercicio.', 39446),
  ('CAÍDAS CONTRA LA PARED - UNA PIERNA - LATERAL - EJERCICIO DE EQUILIBRIO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parate sobre una pierna con una pared a medio metro hacia ese mismo costado. Después, lenta y controladamente, inclinate hacia el costado en dirección a la pared. Tratá de controlar el equilibrio para no caerte, pero seguí inclinándote cada vez más hacia la pared hasta que finalmente pierdas el equilibrio y caigas. Usá el brazo para frenar la caída y después empujate para volver a la posición erguida y repetí. Mantené activados los músculos abdominales, los glúteos y los cuádriceps durante el ejercicio.', 39447),
  ('CAÍDAS CONTRA LA PARED - UNA PIERNA - MEDIAL - EJERCICIO DE EQUILIBRIO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parate sobre una pierna con una pared a medio metro hacia el costado contrario a esa pierna, como se muestra. Después, lenta y controladamente, inclinate de costado en dirección a la pared. Tratá de controlar el equilibrio para no caerte, pero seguí inclinándote cada vez más hacia la pared hasta que finalmente pierdas el equilibrio y caigas. Usá el brazo para frenar la caída y después empujate para volver a la posición erguida y repetí. Mantené activados los músculos abdominales, los glúteos y los cuádriceps durante el ejercicio.', 39450),
  ('CAÍDAS CONTRA LA PARED - UNA PIERNA - HACIA ATRÁS - EJERCICIO DE EQUILIBRIO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada', 'Parate sobre una pierna con una pared a unos 15-30 cm por detrás tuyo. Después, lenta y controladamente, inclinate hacia atrás en dirección a la pared. Tratá de controlar el equilibrio para no caerte hacia atrás, pero seguí inclinándote cada vez más hasta que finalmente pierdas el equilibrio y caigas hacia la pared. Usá la espalda alta para frenar la caída y después empujate para volver a la posición erguida y repetí. Mantené activados los músculos abdominales, los glúteos y los cuádriceps durante el ejercicio.', 39451),
  ('ESTOCADA LATERAL CON RESISTENCIA - SUPERFICIE INESTABLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada; Banda elástica; Máquinas y poleas', 'Usá una cuerda deportiva, banda elástica o cable de polea fijado a un cinto hacia un costado. Después, hacé una estocada hacia el costado y sobre una superficie inestable, como una almohadilla de espuma, y volvé a la posición original. Mantené las puntas de los pies apuntando hacia adelante. Usá marcadores o cinta en el piso para enfocarte en el control de la caída y la posición de los pies. Aumentá la distancia o la velocidad para progresar.', 7655),
  ('ESTOCADA EN RODILLO DE ESPUMA - B', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada; Rodillo de espuma', 'Colocá medio rodillo de espuma en el piso en dirección adelante-atrás, con el lado plano hacia arriba. Hacé una estocada manteniendo el equilibrio.', 9317),
  ('MEDIO RODILLO DE ESPUMA - APOYO EN UNA PIERNA - A', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada; Rodillo de espuma', 'Colocá medio rodillo de espuma en el piso en dirección adelante-atrás, con el lado plano hacia arriba. Equilibrate sobre una pierna.', 8990),
  ('MEDIO RODILLO DE ESPUMA - APOYO EN UNA PIERNA - B', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada; Rodillo de espuma', 'Colocá medio rodillo de espuma en el piso en dirección adelante-atrás, con el lado redondeado hacia arriba. Equilibrate sobre una pierna.', 8992),
  ('MEDIO RODILLO DE ESPUMA - APOYO EN UNA PIERNA - C', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena cerrada; Rodillo de espuma', 'Colocá medio rodillo de espuma en el piso en dirección lateral, con el lado plano hacia arriba. Equilibrate sobre una pierna.', 8993),
  ('KETTLEBELL - FLEXIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena abierta', 'Pasá el pie por la manija de una kettlebell con la punta del pie hacia arriba. Elevá la kettlebell con la pierna dejando que la rodilla se flexione, como se muestra. Bajá y repetí. Agarrate de una silla o una mesa para apoyarte y mantener el equilibrio.', 168817),
  ('COLOCACIÓN DEL PIE EN EL ESCALÓN - ALTERNADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Cadena abierta', 'Parado con ambos pies en el piso, apoyá un pie sobre un escalón o banquito. Después, volvé con el pie al piso y repetí con la otra pierna. Mantené el equilibrio y asegurate de apoyar bien el talón en el escalón. Puede que necesites agarrarte de algo para mantener el equilibrio.', 4672),
  ('SALTO Y FRENO - HACIA ATRÁS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Equilibrio; Pliometría', 'Parate sobre una pierna y después saltá hacia atrás cayendo sobre la otra pierna. Mantené el equilibrio todo el tiempo. Aumentá la dificultad saltando más lejos o más alto.', 39677),
  ('ALCANCE HACIA ATRÁS', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota', 'Parate de espaldas a una pared, a unos 15-20 cm de distancia. Después, estirate por encima de la cabeza y hacia atrás para tocar la pared por arriba. Mantené el equilibrio.', 39155),
  ('PELOTA DE EJERCICIOS - EXTENSIÓN DE RODILLA SIN APOYO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota', 'Sentate sobre una pelota de ejercicios y activá los músculos abdominales para estabilizar la columna. Elevá y bajá lentamente el pie mientras flexionás la rodilla, como se muestra. Después, hacelo del otro lado y repetí. Tratá de mantener la columna estable y derecha todo el tiempo. Si necesitás, apoyá las manos en la pelota para equilibrarte, pero tratá de hacerlo sin tocarla.', 166989),
  ('BALANCEO DE GLÚTEO CON PELOTA - AUTOMASAJE', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota', 'Acostate boca arriba y colocá una pelota chica, como una de tenis o de golf, debajo del glúteo. Después, balanceá la pelvis de lado a lado sobre la pelota para un masaje profundo.', 11042),
  ('BALÓN MEDICINAL - SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota', 'Empezá parado sosteniendo un balón medicinal a la altura del pecho. Después, hacé una sentadilla mientras extendés los brazos hacia adelante hasta estirar los codos. Volvé a la posición original.', 6047),
  ('BALÓN MEDICINAL - SENTADILLA - GOLPE - ATAJADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota', 'Empezá en posición de sentadilla sosteniendo un balón medicinal por encima de la cabeza. Después, tirá la pelota contra el piso mientras extendés las rodillas y te parás. Por último, atajá la pelota con las manos cuando rebote hacia arriba.', 6046),
  ('BALÓN MEDICINAL - ELEVACIONES EN SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota', 'Empezá en posición de sentadilla sosteniendo un balón medicinal cerca del piso. Después, parate desde la posición de sentadilla mientras elevás la pelota por encima de la cabeza.', 6048),
  ('ESTOCADA CON BALÓN MEDICINAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota', 'Empezá parado sosteniendo un balón medicinal a la altura del pecho. Después, dá un paso adelante en estocada mientras extendés los brazos hacia adelante hasta estirar los codos. Después volvé a la posición original. Mantené la cabeza mirando hacia adelante todo el tiempo.', 6570),
  ('AUTOMASAJE CON PELOTA - CADERA LATERAL - BANDA ILIOTIBIAL - PARED', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota', 'Colocá una pelota entre una pared y el costado del muslo, como se muestra. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Inclinate contra la pelota para aplicar presión suave sobre las zonas tensas. No pases la pelota sobre zonas óseas. Podés mantener la presión en una zona o mover el cuerpo para que la pelota ruede hacia arriba y abajo o de lado a lado.', 99547),
  ('AUTOMASAJE CON PELOTA - PIRAMIDAL - DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota', 'Acostate boca arriba y flexioná las rodillas. Apoyá la pierna del lado afectado sobre el otro muslo. Después colocá una pelota chica debajo del glúteo y bajá suavemente la rodilla de arriba para aumentar la presión. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. No pases la pelota sobre zonas óseas.', 99648),
  ('AUTOMASAJE CON PELOTA - PIRAMIDAL 2 - DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota', 'Acostate boca arriba, cruzá la pierna afectada por encima de la otra y apoyá el pie en el piso. Después colocá una pelota chica debajo del glúteo del lado afectado. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Después, dejá que la rodilla de arriba baje hacia el piso para aumentar la presión sobre la pelota. No pases la pelota sobre zonas óseas.', 99650),
  ('AUTOMASAJE CON PELOTA - BANDA ILIOTIBIAL SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota', 'Sentado, usá una pelota de lacrosse o de tenis/paleta y rodala por el costado del muslo para un masaje suave. No pases la pelota sobre zonas óseas.', 99583),
  ('AUTOMASAJE CON PELOTA - TIBIAL ANTERIOR - SILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota', 'Parate frente a una silla y apoyá la rodilla sobre el asiento. Si necesitás, usá una toalla doblada o una almohada para estar más cómodo. Colocá una pelota chica debajo de la cara externa de la pierna, como se muestra. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Podés mantener la presión en una zona o mover el cuerpo para que la pelota ruede hacia arriba y abajo por la pierna. No pases la pelota sobre zonas óseas.', 101774),
  ('PELOTA DE EJERCICIOS - CURLS DE ISQUIOTIBIALES - UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Cadena cerrada', 'Acostado en el piso, apoyá el talón sobre una pelota de ejercicios. Después, elevá la cola y flexioná la rodilla para traer la pelota hacia los glúteos. Mantené la cola despegada del piso todo el tiempo.', 8515),
  ('PELOTA DE EJERCICIOS - SENTADILLAS PARCIALES EN LA PARED - APRETANDO PELOTA - VMO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Cadena cerrada', 'Empezá parado y apoyá la zona lumbar contra una pelota de ejercicios que está contra la pared. Colocá una pelota chica entre las rodillas, apretá las rodillas y mantené. Después, flexioná lentamente las rodillas hasta unos 45 grados para una sentadilla parcial. Después, estirá las rodillas para volver a subir a la posición inicial. Las rodillas deben flexionarse alineadas con el segundo dedo del pie y no pasar la punta del pie.', 66793),
  ('PELOTA DE EJERCICIOS - SENTADILLAS EN LA PARED - APRETANDO PELOTA - VMO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Cadena cerrada', 'Empezá parado y apoyá la zona lumbar contra una pelota de ejercicios que está contra la pared. Colocá una pelota chica entre las rodillas, apretá las rodillas y mantené. Después, flexioná lentamente las rodillas en posición de sentadilla hasta que los muslos queden paralelos o casi paralelos al piso. Después, estirá las rodillas para volver a subir a la posición inicial. Las rodillas deben flexionarse alineadas con el segundo dedo del pie y no pasar la punta del pie.', 66799),
  ('SENTADILLA CON PELOTA POR ENCIMA DE LA CABEZA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Cadena cerrada', 'Parate con los pies separados al ancho de los hombros y colocá una pelota de ejercicios adelante de los pies. Empezá haciendo una sentadilla con buena técnica, usando la bisagra de cadera, y agarrá la pelota. Después, incorporate hasta quedar de pie mientras elevás la pelota por encima de la cabeza. Volvé a bajar en sentadilla, tocá el piso con la pelota y repetí.', 67954),
  ('SENTADILLA - APRETANDO PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Cadena cerrada', 'Parate con una pelota apretada entre los muslos y los brazos cerca del cuerpo, como se muestra. Después, bajá a la posición de sentadilla. Mantené la espalda derecha mientras flexionás desde las caderas y no dejes que las rodillas pasen la punta de los dedos del pie. Elevá los brazos hacia adelante como contrapeso mientras bajás. Volvé a la posición inicial y repetí.', 174648),
  ('PELOTA DE EJERCICIOS - SENTADILLAS EN LA PARED CON ABDUCCIÓN CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Cadena cerrada; Banda elástica', 'Empezá parado y apoyá la zona lumbar contra una pelota de ejercicios que está contra la pared. Colocá una banda elástica alrededor de las rodillas y después separá las rodillas de modo que las rótulas apunten hacia adelante. Después, flexioná lentamente las rodillas en posición de sentadilla hasta que los muslos queden paralelos o casi paralelos al piso. Asegurate de mantener la presión contra la banda elástica y las rótulas apuntando hacia adelante mientras flexionás. Después, estirá las rodillas para volver a subir a la posición inicial. Las rodillas deben flexionarse alineadas con el segundo dedo del pie y no pasar la punta del pie.', 75019),
  ('ESTOCADA LATERAL CON RESISTENCIA - DIAGONAL - LANZAMIENTO DE PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Cadena cerrada; Banda elástica; Máquinas y poleas', 'Usá una cuerda deportiva, banda elástica o cable de polea fijado a un cinto hacia un costado. Después, hacé una estocada en diagonal y HACIA ATRÁS, al costado. Después, volvé a la posición original. Luego hacé una estocada en diagonal HACIA ADELANTE y volvé a la posición original. Tenés que caer con las puntas de los pies apuntando hacia adelante todo el tiempo. Durante estas estocadas, alguien te puede tirar una pelota para que la atajes y la devuelvas. Si no hay nadie disponible, tirá la pelota contra una pared y atajala. Usá marcadores o cinta en el piso para enfocarte en el control de la caída y la posición de los pies. Aumentá la distancia o la velocidad para progresar.', 9645),
  ('ESTOCADA LATERAL CON RESISTENCIA - ROTACIÓN DIAGONAL - LANZAMIENTO DE PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Cadena cerrada; Banda elástica; Máquinas y poleas', 'Usá una cuerda deportiva, banda elástica o cable de polea fijado a un cinto hacia un costado. Después, hacé una estocada en diagonal y HACIA ATRÁS, al costado. Tenés que caer con las puntas de los pies apuntando hacia el costado y alineadas con la dirección del movimiento. Después, volvé a la posición original. Luego hacé una estocada en diagonal HACIA ADELANTE y volvé a la posición original. Durante estas estocadas, alguien te puede tirar una pelota para que la atajes y la devuelvas. Si no hay nadie disponible, tirá la pelota contra una pared y atajala. Asegurate de mantener la rodilla alineada con los dedos del pie. Sin torsión en la rodilla. Además, mirado desde arriba, no dejes que las rodillas pasen la punta de los dedos. Usá marcadores o cinta en el piso para enfocarte en el control de la caída y la posición de los pies. Aumentá la distancia o la velocidad para progresar.', 7654),
  ('ESTOCADA LATERAL CON RESISTENCIA - SUPERFICIE INESTABLE - LANZAMIENTO DE PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Cadena cerrada; Banda elástica; Máquinas y poleas', 'Usá una cuerda deportiva, banda elástica o cable de polea fijado a un cinto hacia un costado. Después, hacé una estocada hacia el costado y sobre una superficie inestable, como una almohadilla de espuma, y volvé a la posición original. Mantené las puntas de los pies apuntando hacia adelante. Durante estas estocadas, alguien te puede tirar una pelota para que la atajes y la devuelvas. Si no hay nadie disponible, tirá la pelota contra una pared y atajala. Usá marcadores o cinta en el piso para enfocarte en el control de la caída y la posición de los pies. Aumentá la distancia o la velocidad para progresar.', 7656),
  ('ADUCCIÓN DE CADERA APRETANDO PELOTA - DE PIE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Cadena cerrada; Isométrico', 'Parado, colocá una pelota entre las rodillas. Apretá la pelota con las rodillas y mantené. Relajá y después repetí.', 75018),
  ('ISOMÉTRICO DE ISQUIOTIBIALES CON PELOTA - SENTADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Isométrico', 'Sentate en una silla y colocá una pelota entre el talón y una pata de la silla. Flexioná la rodilla de modo que el talón presione contra la pelota. Mantené, después relajá y repetí.', 97619),
  ('ADUCCIÓN DE CADERA - APRETANDO PELOTA GRANDE - DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Isométrico', 'Acostado en el piso, colocá una pelota de ejercicios entre las rodillas y apretala. Mantené, relajá y repetí.', 302),
  ('ADUCCIÓN DE CADERA - APRETANDO PELOTA MEDIANA - DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Isométrico', 'Acostado en el piso, colocá una pelota de ejercicios entre las rodillas y apretala. Mantené, relajá y repetí.', 129398),
  ('ISOMÉTRICO DE ROTACIÓN EXTERNA DE CADERA - DECÚBITO VENTRAL - APRETANDO PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Isométrico', 'Acostado boca abajo, colocá una pelota entre los tobillos y presioná los pies uno contra el otro. Mantené, relajá y repetí.', 129051),
  ('SILLA DE RUEDAS - ADUCCIÓN DE CADERA APRETANDO PELOTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pelota; Isométrico', 'Sentado, colocá una pelota entre las rodillas. Apretá la pelota con las rodillas y mantené. Relajá y repetí.', 105287),
  ('AUTOMASAJE CON PELOTA - BANDA ILIOTIBIAL', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota; Movilización', 'Acostate de costado y colocá una doble pelota de lacrosse (pelota maní) o 2 pelotas de tenis/paleta pegadas debajo del costado de la pierna, como se muestra. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Después, usá la otra pierna o el pie para ayudarte a mover el cuerpo hacia arriba y abajo, de modo que la pelota ruede a lo largo del costado de la pierna. No pases la pelota sobre zonas óseas.', 101771),
  ('AUTOMASAJE CON PELOTA - TIBIAL ANTERIOR', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota; Movilización', 'Empezá en posición de gateo y colocá una pelota chica debajo de la cara externa de la pierna, como se muestra. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Podés mantener la presión en una zona o, sosteniéndote con los brazos y la otra pierna, mover el cuerpo para que la pelota ruede hacia arriba y abajo por la pierna. No pases la pelota sobre zonas óseas.', 101773),
  ('AUTOMASAJE CON PELOTA - TIBIAL ANTERIOR - DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota; Movilización', 'Acostate boca arriba y colocá una pelota chica debajo de la cara externa de la pierna, como se muestra. Podés usar una pelota de tenis, de lacrosse (como se muestra) o de paleta. Podés mantener la presión en una zona o mover la pierna para que la pelota ruede hacia arriba y abajo. No pases la pelota sobre zonas óseas.', 101772),
  ('PELOTA DE EJERCICIOS - ESTIRAMIENTO DEL PIRAMIDAL', NULL, true, 'activo', 'Cadera y rodilla', 'Pelota; Estiramientos', 'Empezá acostado boca arriba con un pie apoyado sobre la pelota. Después, cruzá la otra pierna por encima de la rodilla de la pierna que está sobre la pelota. Después, rodá suavemente la pelota hacia los glúteos hasta sentir un estiramiento en la zona del glúteo.', 311),
  ('BOSU INVERTIDO - SENTADO CON PIERNA ALTERNADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Bosu', 'Sentado sobre un Bosu invertido, elevá alternadamente un pie del piso. No dejes que la pelvis ni la columna se muevan durante el ejercicio.', 10247),
  ('BOSU - SENTADILLA - PASOS POR ENCIMA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Bosu; Cadena cerrada; Pliometría', 'Parate al costado de una pelota Bosu. Apoyá un pie sobre la Bosu y hacé una sentadilla. Un pie debe estar elevado sobre la Bosu y el otro en el piso. Pasá por encima de la Bosu para caer del lado contrario y después hacé otra sentadilla. Seguí así alternando los lados y repetí.', 168277),
  ('BOSU - PASOS LATERALES POR ENCIMA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Bosu; Pliometría', 'Apoyá un pie sobre una pelota Bosu y el otro pie en el piso, hacia el costado. Saltá de costado por encima de la Bosu alternando los pies, como se muestra. Repetí.', 169165),
  ('BOSU - ESTIRAMIENTO DEL PIRAMIDAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Bosu; Estiramientos', 'Sentado sobre una Bosu, cruzá la pierna afectada por encima de la otra, como se muestra. Después, inclinate suavemente hacia adelante hasta sentir un estiramiento a lo largo de la pierna cruzada.', 5771),
  ('BOSU INVERTIDO - ESTIRAMIENTO DE ADUCTORES DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Bosu; Estiramientos', 'Sentado sobre un Bosu invertido, separá las piernas e inclinate hacia adelante hasta sentir un estiramiento en la parte de atrás e interna de los muslos.', 5762),
  ('BOSU INVERTIDO - ESTIRAMIENTO DE ISQUIOTIBIALES SENTADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Bosu; Estiramientos', 'Sentado sobre un Bosu invertido, colocá ambas piernas estiradas adelante tuyo, de modo que los talones toquen el piso y las rodillas queden derechas. Después, inclinate suavemente hacia adelante hasta sentir un estiramiento detrás de las rodillas.', 5769),
  ('SALTO AL CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones', 'Parate frente a un cajón y, usando ambas piernas, saltá arriba de él. Bajá con un paso y repetí.', 82644),
  ('SALTOS AL CAJÓN - SUBIDAS RÁPIDAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones', 'Parate frente a un cajón y apoyá un pie sobre él. Después, usá la pierna de arriba para impulsarte en el aire mientras cambiás de pie, de modo que el otro pie toque el cajón y el primero toque el piso. Repetí este proceso alternando los lados.', 82638),
  ('PLIOMETRÍA - SALTOS ROTACIONALES - DOS CAJONES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones', 'Saltá y rotá hacia el costado para subir a un cajón y después bajá al piso cerca de la posición inicial. Después hacelo del otro lado sobre otro cajón. Seguí alternando de lado a lado. Este ejercicio pliométrico se puede modificar cambiando la altura del cajón y/o la velocidad.', 7378),
  ('CAMBIOS DE PASO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones', 'Saltá y tocá el escalón con la planta del pie y después saltá rápido cambiando al otro lado. Seguí cambiando rápido y alternando las piernas.', 12634),
  ('SENTADILLA CON LEVANTAMIENTO - PESO LIBRE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Cadena cerrada', 'Parate con los pies separados al ancho de los hombros y una mancuerna adelante tuyo sobre un banquito. Flexioná las rodillas y bajá el cuerpo hacia el piso. El peso del cuerpo debe ir a través de los talones y las rodillas no deben pasar la punta del segundo dedo del pie. Después, levantá la mancuerna manteniendo la espalda plana y volvé a la posición de pie. Después, volvé a bajar en sentadilla y apoyá la mancuerna sobre el banquito. Esta vez, volvé a la posición de pie sin la mancuerna. Repetí alternando entre sostener y no sostener la mancuerna en cada repetición.', 165249),
  ('CAJÓN - SENTADILLA EN PROFUNDIDAD', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Cadena cerrada; Pliometría', 'Parate sobre un cajón chico, después bajá y caé con ambos pies mientras bajás a posición de sentadilla y mantené. Volvé a la posición de pie y repetí.', 83689),
  ('CAJÓN - SALTO LARGO EN PROFUNDIDAD', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate sobre un cajón. Bajá cayendo con ambas piernas en el piso y después saltá inmediatamente hacia adelante buscando distancia.', 82637),
  ('CAJÓN - SALTOS RÁPIDOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate frente a un cajón y saltá rápido arriba y abajo de él, como se muestra.', 82643),
  ('CAJÓN - SALTOS COHETE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Empezá apoyando un pie sobre un cajón adelante tuyo. Después, empujá con esa pierna para impulsarte en el aire y caé en la misma posición en la que empezaste. Repetí del mismo lado.', 82639),
  ('SALTO EN PROFUNDIDAD DESDE CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate sobre un cajón chico y después bajá del cajón para caer en el piso con ambas piernas. Después de caer, saltá inmediata y rápidamente hacia arriba y caé con ambas piernas.', 82843),
  ('SALTO AL CAJÓN - DESPLAZAMIENTO LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate al costado de un cajón chico. Después, subí al cajón con ambas piernas y bajá rápido del otro lado. Seguí con este patrón alternando los lados.', 82564),
  ('SALTO AL CAJÓN - DESPLAZAMIENTO LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate al costado de un cajón. Apoyá un pie sobre el cajón y después saltá rápido para apoyar el otro pie sobre el cajón mientras sacás el primer pie hacia el otro lado del cajón y lo apoyás en el piso. Seguí con este patrón alternando los lados.', 82628),
  ('SALTO AL CAJÓN - UNILATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate con un cajón a tu costado. Saltá arriba del cajón usando ambas piernas desde un lado. Bajá con un paso hacia el mismo lado y repetí.', 82840),
  ('SALTOS AL CAJÓN - SALTO CON GIRO DE 90 GRADOS AL CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate en el piso con un cajón por detrás y hacia un costado, como se muestra. Después, dá un paso saltado hacia atrás mientras girás para quedar de frente al cajón y después saltá arriba del cajón usando ambas piernas.', 82532),
  ('SALTOS AL CAJÓN - GIROS DE 90 GRADOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate con un cajón a tu costado. Saltá girando 90 grados para quedar de frente al cajón. Bajá con un paso de modo que el cajón quede del otro costado. Después saltá girando 90 grados para quedar de frente al cajón otra vez. Repetí alternando los lados.', 82627),
  ('SALTOS AL CAJÓN - BURPEE CON FLEXIÓN DE BRAZOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parado frente a un cajón, hacé un burpee: flexioná las rodillas y bajá el cuerpo hacia el piso. Apoyá las manos en el piso mientras estirás las piernas hasta quedar en posición de plancha o flexión de brazos, con las puntas de los pies y las manos en el piso. Mantené la columna derecha y no dejes que la espalda se hunda. Hacé una flexión de brazos y después saltá arriba del cajón que tenés adelante.', 82531),
  ('SALTOS AL CAJÓN - PASO LATERAL CON SALTO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate en el piso con un cajón a tu costado, como se muestra. Después, dá un paso lateral saltando para quedar de frente al cajón y después saltá arriba del cajón con las dos piernas.', 82534),
  ('SALTOS AL CAJÓN - NORTE, ESTE, OESTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate con un cajón adelante tuyo. Saltá arriba del cajón con las dos piernas. Bajá con un paso hacia el costado y después saltá arriba del cajón desde ese lado. Bajá hacia el lado opuesto y después saltá arriba del cajón desde ese lado. Volvé a la posición inicial y repetí.', 82642),
  ('SALTOS AL CAJÓN - SALTO EN PROFUNDIDAD A UNA PIERNA AL CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate arriba de un cajón y después bajá con un paso para caer en el piso con una pierna. Después de caer, saltá inmediatamente y rápido hacia adelante a un cajón más alto cayendo con las dos piernas.', 82555),
  ('SALTO EN PROFUNDIDAD A CARRERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate arriba de un cajón. Dejate caer para aterrizar con las dos piernas en el piso y después salí inmediatamente a correr hacia adelante en sprint.', 82630),
  ('SALTO EN PROFUNDIDAD AL CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate arriba de un cajón y después bajá con un paso para caer en el piso con las dos piernas. Después de caer, saltá inmediatamente y rápido hacia adelante a un cajón más alto cayendo con las dos piernas.', 82529),
  ('SALTO LATERAL AL CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate con un cajón a tu costado. Saltá arriba del cajón con las dos piernas desde un lado. Bajá con un paso hacia el otro lado y después saltá arriba del cajón desde ese lado. Repetí alternando los lados.', 82626),
  ('PLIOMETRÍA - SALTOS LATERALES - UN CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Saltá hacia el costado arriba de un cajón y después volvé al piso cerca de la posición inicial. Este ejercicio pliométrico se puede modificar cambiando la altura del cajón o la velocidad.', 7376),
  ('PLIOMETRÍA - SALTOS LATERALES - DOS CAJONES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Saltá hacia el costado arriba de un cajón y después volvé al piso cerca de la posición inicial. Después hacelo del otro lado sobre otro cajón. Seguí alternando de lado a lado. Este ejercicio pliométrico se puede modificar cambiando la altura del cajón o la velocidad.', 7377),
  ('SALTOS EN TIJERA - CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Empezá en posición de estocada, como se muestra, con el pie de adelante arriba de un escalón o cajón. Después, saltá y cambiá de pierna para que el pie contrario caiga sobre el escalón mientras bajás a la posición de estocada. No dejes que la rodilla de adelante pase los dedos del pie. Seguí saltando y alternando las piernas.', 7390),
  ('SALTO AL CAJÓN A UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate frente a un cajón y, usando una pierna, saltá arriba de él. Bajá con un paso y repetí.', 82645),
  ('SALTO AL CAJÓN A UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate en una pierna frente a un cajón chico y saltá arriba del cajón cayendo con las dos piernas. Después, bajá del cajón con un paso hacia atrás y repetí.', 82561),
  ('SALTO EN PROFUNDIDAD DESDE CAJÓN CHICO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate arriba de un cajón chico y después bajá con un paso para caer en el piso con las dos piernas. Después de caer, saltá inmediatamente y rápido hacia arriba y caé con las dos piernas.', 82562),
  ('SALTO AL CAJÓN CHICO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Saltá arriba del cajón con las dos piernas. Bajá con un paso hacia atrás y repetí.', 82554),
  ('SALTO AL CAJÓN CHICO - BILATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate al costado de un cajón chico y después saltá de costado arriba del cajón. Después, bajá del cajón con un paso hacia el otro lado y seguí con este patrón alternando los lados.', 82557),
  ('SALTO AL CAJÓN CHICO - LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate al costado de un cajón chico y después saltá de costado arriba del cajón. Después, bajá del cajón con un paso hacia el mismo lado y repetí el salto.', 82559),
  ('SALTOS AL CAJÓN CHICO - MULTIDIRECCIONALES - NORTE OESTE ESTE - NOE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Empezá parado frente a un cajón chico y, con las dos piernas, saltá arriba del cajón. Después, bajá con un paso hacia el costado y después saltá de costado arriba del cajón. Después, bajá del cajón hacia el otro lado y repetí el salto al cajón desde la dirección opuesta. Bajá a la posición inicial y repetí.', 82560),
  ('SALTOS AL CAJÓN CHICO - CAMBIO DE PASOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate frente a un cajón chico y tocá el escalón con la punta de un pie mientras el otro pie queda en el piso. Después, saltá rápido y cambiá los pies de modo que el otro pie toque el escalón y el pie contrario toque el piso. Repetí este proceso alternando los lados.', 82566),
  ('SALTO EN PROFUNDIDAD A UNA PIERNA DESDE CAJÓN CHICO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cajones y escalones; Pliometría', 'Parate arriba de un cajón chico y después bajá con un paso para caer en el piso con una pierna. Después de caer, saltá inmediatamente y rápido hacia arriba y caé con las dos piernas.', 82563),
  ('ESTOCADA ADELANTE ALTERNADA CON MANCUERNAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con los pies separados al ancho de los hombros. Después, dá un paso adelante y un poco hacia el costado, y dejá que la rodilla de adelante se flexione hasta la posición de estocada. La rodilla de atrás también se puede flexionar. Después, empujá con la rodilla de adelante y volvé a la posición inicial. Después hacelo con la otra pierna. Mantené la pelvis nivelada y derecha todo el tiempo. La rodilla de adelante debe flexionarse alineada con el segundo dedo y no pasar la punta del pie. Las mancuernas deben quedar a los costados de la rodilla de adelante.', 65362),
  ('ESTOCADA INVERSA ALTERNADA CON MANCUERNAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con los pies separados al ancho de los hombros y una mancuerna en cada mano. Después, dá un paso hacia atrás y dejá que la rodilla de adelante se flexione hasta la posición de estocada. La rodilla de atrás también se puede flexionar. Después, empujá principalmente con la rodilla de adelante dirigiendo la presión por el talón y volvé a la posición inicial. Después hacelo con la otra pierna. Mantené la pelvis nivelada y derecha todo el tiempo. La rodilla de adelante debe flexionarse alineada con el segundo dedo y no pasar la punta del pie. Las mancuernas deben quedar a los costados de la pierna de adelante, como se muestra.', 65364),
  ('TKE CON PELOTA - EXTENSIÓN TERMINAL DE RODILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá en posición de pie con una pelota detrás de la rodilla y contra una pared. La rodilla debe estar parcialmente flexionada. Después, presioná la parte de atrás de la rodilla contra la pelota mientras tratás de estirar la rodilla.', 15324),
  ('SENTADILLA TRASERA AL CAJÓN - BARRA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate y agarrá la barra un poco más abierto que el ancho de los hombros. Sacá la barra del soporte y dá un paso atrás. Apoyá la barra sobre la parte de atrás de los hombros. Colocá los pies separados aproximadamente al ancho de los hombros y después hacé una sentadilla como si te fueras a sentar en un banco o silla. Empujá con los talones mientras empezás a subir a la posición de pie con las rodillas completamente estiradas. Mantené la columna derecha mientras flexionás desde las caderas y las rodillas. Volvé a la posición de pie y repetí.', 154607),
  ('SENTADILLA FRONTAL AL CAJÓN - BARRA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate y agarrá la barra un poco más abierto que el ancho de los hombros. Sacá la barra del soporte y dá un paso atrás. Apoyá la barra sobre la parte de adelante de los hombros. Colocá los pies separados aproximadamente al ancho de los hombros y después hacé una sentadilla como si te fueras a sentar en un banco o silla. Empujá con los talones mientras empezás a subir a la posición de pie con las rodillas completamente estiradas. Mantené la columna derecha mientras flexionás desde las caderas y las rodillas. Volvé a la posición de pie y repetí.', 154606),
  ('MESADA - SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parado al lado de una bacha, agarrate de la mesada con los pies separados al ancho de los hombros. Flexioná las rodillas y bajá el cuerpo hacia el piso. El peso del cuerpo debe estar dirigido por los talones. Volvé a la posición de pie. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta del pie.', 15321),
  ('SENTADILLA EN MESADA - INVERSA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con una mesada detrás tuyo y colocá los pies separados al ancho de los hombros. Estirá los brazos hacia atrás y agarrá el borde de la mesada con las dos manos. Flexioná los codos y las rodillas para bajar el cuerpo hacia el piso. El peso del cuerpo debe estar dirigido por los talones. Volvé a la posición de pie y repetí. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta del pie.', 164804),
  ('ESTOCADA PROFUNDA ADELANTE - ALTERNADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con los pies separados al ancho de los hombros. Después, dá un paso largo hacia adelante y dejá que la rodilla de adelante se flexione. Dejá que la rodilla de atrás también se flexione hasta tocar el piso o quedar cerca de tocarlo. Después, empujá con la pierna de adelante y volvé a la posición original. Después hacelo del otro lado. Repetí alternando los lados. Mantené la pelvis nivelada y derecha todo el tiempo. La rodilla de adelante debe flexionarse alineada con el segundo dedo y no pasar la punta del pie.', 75824),
  ('ESTOCADA PROFUNDA ADELANTE - CAMINANDO - ALTERNADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con los pies separados al ancho de los hombros. Después, dá un paso adelante y dejá que la rodilla de adelante se flexione. Dejá que la rodilla de atrás también se flexione hasta tocar el piso o quedar cerca de tocarlo. Después, seguí avanzando mientras llevás la pierna de atrás hacia adelante para volver a quedar parado con los dos pies juntos. Repetí del otro lado y seguí alternando los lados. Mantené la pelvis nivelada y derecha todo el tiempo. La rodilla de adelante debe flexionarse alineada con el segundo dedo y no pasar la punta del pie.', 75828),
  ('MANCUERNA - CARGADAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá en posición de sentadilla sosteniendo los pesos libres. Movete rápido a la posición erguida mientras elevás las mancuernas a la altura de los hombros. Al subir, asegurate de levantar el pecho y arquear la espalda para mantener la columna derecha. Recibí las mancuernas con las rodillas flexionadas para reducir el impacto en el cuerpo. Terminá en posición erguida con las rodillas estiradas.', 154788),
  ('PELOTA DE EJERCICIOS - CURLS DE ISQUIOTIBIALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Acostado en el piso, colocá una pelota de ejercicios debajo de los talones. Después, elevá la cola y después flexioná las rodillas para llevar la pelota hacia la cola. Mantené la cola despegada del piso durante la repetición. Bajá cuando lo necesites y repetí.', 301),
  ('ESTOCADA ADELANTE CON MANCUERNAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con los pies separados al ancho de los hombros. Después, dá un paso adelante y un poco hacia el costado, y dejá que la rodilla de adelante se flexione hasta la posición de estocada. La rodilla de atrás también se puede flexionar. Después, empujá con la rodilla de adelante y volvé a la posición inicial. Después repetí con la misma pierna. Mantené la pelvis nivelada y derecha todo el tiempo. La rodilla de adelante debe flexionarse alineada con el segundo dedo y no pasar la punta del pie. Las mancuernas deben quedar a los costados de la rodilla de adelante.', 65363),
  ('GERIÁTRICO - APOYO EN UNA PIERNA - SLS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate en una pierna y mantené el equilibrio. Tené cerca una silla u otro objeto más firme, como una mesada o una bacha, por si necesitás apoyo para el equilibrio y la seguridad.', 124570),
  ('ESTOCADA LATERAL EN COPA - PESO LIBRE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies separados al ancho de los hombros. Sostené la punta de una mancuerna contra la parte alta del pecho, como se muestra. Después, dá un paso hacia el costado y flexioná la rodilla hasta la posición de estocada. Mientras la rodilla se flexiona, bajá la cola hacia el piso. Mantené las rodillas alineadas con los dedos de los pies y no dejes que la rodilla pase por delante de la punta del pie. Volvé a la posición de pie empujando con el talón y repetí del mismo lado.', 120510),
  ('SENTADILLA EN COPA - SILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies separados al ancho de los hombros. Sostené la punta de una mancuerna contra la parte alta del pecho, como se muestra. Flexioná las rodillas y bajá la cola para sentarte en la silla. Mantené la espalda derecha y flexioná desde las caderas. El peso del cuerpo debe estar dirigido principalmente por los talones. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta de los pies. Volvé a la posición de pie empujando con los talones. Repetí.', 109436),
  ('MANCUERNA PESADA - SENTADILLA CON AGARRE APRETADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá con los pies un poco más separados que el ancho de los hombros mientras sostenés un peso libre con las dos manos a la altura del pecho. Después, bajá en sentadilla manteniendo la mancuerna en el pecho todo el tiempo. La distribución del peso debe ir principalmente por los talones. Mientras flexionás las rodillas y bajás el cuerpo, no dejes que las rodillas pasen los dedos de los pies y mantené la espalda derecha flexionando desde las caderas. Empujá con los talones, estirá las rodillas y volvé a pararte. Repetí.', 63481),
  ('MANCUERNAS PESADAS - SENTADILLA EN COPA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies separados al ancho de los hombros. Sostené la punta de un peso libre contra la parte alta del pecho, como se muestra. Flexioná las rodillas y bajá el cuerpo hacia el piso para hacer una sentadilla. Mantené la espalda derecha y flexioná desde las caderas. El peso del cuerpo debe estar dirigido principalmente por los talones. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta de los pies. Volvé a la posición de pie empujando con los talones. Repetí.', 63515),
  ('MANCUERNAS PESADAS - SENTADILLA A UNA PIERNA - PIE APOYADO ATRÁS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'SENTADILLA A UNA PIERNA - PIE APOYADO ATRÁS. Parate sosteniendo pesos libres en cada mano y apoyado en una pierna, como se muestra, con el otro pie apoyado sobre un banco, silla o sillón detrás tuyo, como se muestra. Después, flexioná la rodilla de adelante y bajá el cuerpo hacia el piso. Volvé a la posición de pie y repetí. La rodilla que trabajás debe flexionarse alineada con el segundo dedo y no pasar la punta del pie.', 63470),
  ('MANCUERNAS PESADAS - SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies un poco más separados que el ancho de los hombros. Sostené un peso libre en cada mano y flexioná los codos para mantener las pesas cerca de los hombros. Flexioná las rodillas y bajá el cuerpo hacia el piso para hacer una sentadilla. Mantené la espalda derecha y flexioná desde las caderas. El peso del cuerpo debe estar dirigido principalmente por los talones. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta de los pies. Volvé a la posición de pie empujando con los talones. Repetí.', 63513),
  ('MANCUERNAS PESADAS - SENTADILLA SUMO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies un poco más separados que el ancho de los hombros. Sostené la punta de un peso libre con las dos manos, como se muestra. Flexioná las rodillas y bajá el cuerpo hacia el piso para hacer una sentadilla. Mantené la espalda derecha y flexioná desde las caderas. El peso del cuerpo debe estar dirigido principalmente por los talones. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta de los pies. Volvé a la posición de pie empujando con los talones. Repetí.', 63514),
  ('ELEVACIONES DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate arriba de un escalón y después bajá una pierna hacia el piso inclinando la pelvis hacia el costado. Volvé a la posición inicial y repetí.', 128),
  ('KETTLEBELL - ESTOCADA CON PRESS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá sosteniendo una kettlebell en posición acunada y con los pies juntos. Después, dá un paso adelante a la posición de estocada con la pierna contraria y elevá la kettlebell hacia el techo mientras hacés la estocada. Las rodillas siguen la línea de los dedos de los pies.', 28618),
  ('KETTLEBELL - ESTOCADA CON REMO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá en la posición final de estocada. Después, agarrá una kettlebell y tirá de ella hacia el techo mientras subís a la posición de estocada. Bajá de nuevo y repetí.', 28622),
  ('KETTLEBELL - ARRANQUE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá con la kettlebell entre las piernas en posición de sentadilla. Después, subí la kettlebell hasta tener el codo levemente flexionado mientras hacés una sentadilla, y por último empujá el peso por encima de la cabeza mientras hacés otra sentadilla. Durante este ejercicio tenés que hacer 2 sentadillas cortas.', 28617),
  ('KETTLEBELL - SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá con los pies separados al ancho de los hombros y sosteniendo una kettlebell a la altura del pecho. Después, bajá en sentadilla manteniendo la kettlebell en el pecho todo el tiempo. No dejes que las rodillas pasen los dedos de los pies. Mantené la espalda derecha.', 28624),
  ('KETTLEBELL - SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá elevando la kettlebell al hombro con los pies separados al ancho de los hombros. Después, flexioná las rodillas y bajá el cuerpo hacia el piso. Mientras bajás, elevá el otro brazo como contrapeso. El peso del cuerpo debe estar dirigido principalmente por los talones. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta de los pies. Después, pararte y volver a la posición inicial. Repetí.', 79195),
  ('KETTLEBELL - PASO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Hacé un swing de kettlebell y después dá un paso adelante. Después, hacé un swing de kettlebell y dá un paso atrás. Swing de kettlebell: empezá balanceando la kettlebell hacia adelante y atrás mientras flexionás y estirás las rodillas. Cuando la kettlebell baja, dejá que las rodillas se flexionen. Cuando la kettlebell sube, estirá las rodillas.', 28626),
  ('KETTLEBELL - SWING', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies separados y sosteniendo una kettlebell. Empezá balanceando la kettlebell hacia adelante y atrás mientras flexionás y estirás las rodillas. Cuando la kettlebell baja, dejá que las rodillas se flexionen. Cuando la kettlebell sube, estirá las rodillas. Las caderas y la pelvis deben empujar hacia adelante para generar un estiramiento (extensión) rápido de las rodillas. Mantené la espalda derecha todo el tiempo.', 28625),
  ('KETTLEBELL - SWING ALTO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies separados y sosteniendo una kettlebell. Empezá balanceando la kettlebell hacia adelante y atrás mientras flexionás y estirás las rodillas. Cuando la kettlebell baja, dejá que las rodillas se flexionen. Cuando la kettlebell sube por encima de la cabeza, estirá las rodillas. Las caderas y la pelvis deben empujar hacia adelante para generar un estiramiento (extensión) rápido de las rodillas. Mantené la espalda derecha todo el tiempo.', 75816),
  ('KETTLEBELL - SWING CON CAMBIO DE MANO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Balanceá una kettlebell con un brazo desde entre las piernas hasta la altura del pecho y después cambiala a la mano contraria y repetí.', 28610),
  ('ESTOCADA LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies levemente separados. Después, dá un paso hacia el costado y flexioná la rodilla hasta la posición de estocada. Mientras la rodilla se flexiona, bajá la cola hacia el piso. Mantené las rodillas alineadas con los dedos de los pies. Podés elevar los brazos hacia adelante con cada flexión de rodilla como contrapeso. Volvé a la posición original y repetí del mismo lado.', 60381),
  ('ESTOCADA LATERAL - ALTERNADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies levemente separados. Después, dá un paso hacia el costado y flexioná esa rodilla hasta la posición de estocada. Mientras la rodilla se flexiona, bajá la cola hacia el piso. Mantené las rodillas alineadas con los dedos de los pies. Podés elevar los brazos hacia adelante con cada flexión de rodilla como contrapeso. Volvé a la posición original y repetí del otro lado.', 60374),
  ('ESTOCADA LATERAL CON MANCUERNAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado sosteniendo una mancuerna en cada mano. Después, dá un paso hacia el costado, flexioná esa rodilla y bajá la cola mientras flexionás desde las caderas. No dejes que la rodilla pase por delante de los dedos del pie y mantenela alineada con el pie. Las manos deben quedar a los costados de la rodilla, una de cada lado de la rodilla flexionada. Empujá para volver a la posición inicial y después repetí del mismo lado.', 65360),
  ('ESTOCADA LATERAL CON MANCUERNAS ALTERNADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado sosteniendo una mancuerna en cada mano. Después, dá un paso hacia el costado, flexioná esa rodilla y bajá la cola mientras flexionás desde las caderas. No dejes que la rodilla pase por delante de los dedos del pie y mantenela alineada con el pie. Las manos deben quedar a los costados de la rodilla, una de cada lado de la rodilla flexionada. Empujá para volver a la posición inicial y después repetí del otro lado.', 65359),
  ('ESTOCADA - ALTERNADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con los pies separados al ancho de los hombros. Después, dá un paso adelante y un poco hacia el costado, y dejá que la rodilla de adelante se flexione. La rodilla de atrás también se puede flexionar. Después, volvé a la posición original y repetí con la pierna contraria. Seguí así alternando de la pierna derecha a la izquierda. Mantené la pelvis nivelada y derecha todo el tiempo. La rodilla de adelante debe flexionarse alineada con el segundo dedo y no pasar la punta del pie.', 111999),
  ('ESTOCADAS EN RELOJ', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con las dos rodillas estiradas. Empezá dando un paso hacia adelante y un poco hacia el costado mientras dejás que la rodilla de adelante se flexione. La rodilla de atrás también se puede flexionar. Después, volvé a la posición inicial. Después, hacé lo mismo dando un paso a unos 45 grados hacia el costado. Después, volvé a la posición inicial. Por último, hacelo dando un paso derecho hacia el costado. Después, volvé a la posición inicial. Mantené la pelvis nivelada y derecha todo el tiempo. La rodilla de adelante debe flexionarse alineada con el segundo dedo y no pasar la punta del pie.', 83690),
  ('ESTOCADA ADELANTE - CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parado en el piso con un escalón adelante tuyo, apoyá el pie hacia adelante sobre el escalón, como se muestra. Dejá que la rodilla de adelante y la de atrás se flexionen mientras bajás la rodilla de atrás hacia el piso en posición de estocada. No dejes que la rodilla de adelante pase los dedos del pie. Volvé a la posición original y después hacelo con la otra pierna.', 7380),
  ('ESTOCADAS - ALMOHADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con los pies separados al ancho de los hombros. Después, dá un paso largo hacia adelante y dejá que la rodilla de adelante se flexione. Dejá que la rodilla de atrás también se flexione y apoyala sobre una almohada, una toalla doblada o una almohadilla de equilibrio. Después, empujá con la pierna de adelante y volvé a la posición original. Repetí del mismo lado.', 156627),
  ('ESTOCADAS - ALMOHADILLA - BILATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con los pies separados al ancho de los hombros. Después, dá un paso largo hacia adelante y dejá que la rodilla de adelante se flexione. Dejá que la rodilla de atrás también se flexione y apoyala sobre una almohada, una toalla doblada o una almohadilla de equilibrio. Después, empujá con la pierna de adelante y volvé a la posición original. Después hacelo del otro lado. Repetí alternando los lados.', 156628),
  ('SENTADILLA CORTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá con los pies separados al ancho de los hombros y los dedos apuntando derecho hacia adelante. Después, flexioná las rodillas hasta unos 30 grados de flexión para hacer una sentadilla corta, como se muestra. Después, volvé a la posición original. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta del pie.', 7345),
  ('SENTADILLA CORTA - APOYO INESTABLE - ALMOHADILLA DE ESPUMA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá con los pies separados al ancho de los hombros, los dedos apuntando derecho hacia adelante y parado sobre una almohadilla de equilibrio de espuma. Después, flexioná las rodillas hasta unos 30 grados de flexión para hacer una sentadilla corta, como se muestra. Después, volvé a la posición original. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta del pie.', 7346),
  ('SENTADILLA CORTA - APOYO INESTABLE - TOALLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá con los pies separados al ancho de los hombros, los dedos apuntando derecho hacia adelante y parado sobre 2 toallas dobladas o una almohada. Después, flexioná las rodillas hasta unos 30 grados de flexión para hacer una sentadilla corta, como se muestra. Después, volvé a la posición original. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta del pie.', 7347),
  ('EMBARAZO - SENTADILLA CORTA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá con los pies bien separados para dejar espacio a la panza durante la sentadilla. Después, flexioná las rodillas (menos de 90 grados) para hacer una sentadilla corta, como se muestra. Después, volvé a la posición de pie. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar la punta del pie.', 179247),
  ('ROTACIÓN EXTERNA DE CADERA EN DECÚBITO VENTRAL - FIGURA 4', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá acostado boca abajo con las manos debajo de la frente. Flexioná una pierna hacia adentro y apoyá el tobillo sobre la parte de atrás de la rodilla contraria. Elevá del piso la rodilla que está flexionada. Mantené, volvé a la posición inicial y repetí.', 160562),
  ('ESTOCADA INVERSA CON MANCUERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con los pies separados al ancho de los hombros y sosteniendo una mancuerna en una mano. Después, dá un paso hacia atrás y dejá que la rodilla de adelante se flexione hasta la posición de estocada. La rodilla de atrás también se puede flexionar. Después, empujá principalmente con la rodilla de adelante dirigiendo la presión por el talón y volvé a la posición inicial. Después repetí con la misma pierna. Mantené la pelvis nivelada y derecha todo el tiempo. La rodilla de adelante debe flexionarse alineada con el segundo dedo y no pasar la punta del pie.', 65366),
  ('ESTOCADA INVERSA CON MANCUERNA DESCOMPENSADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá parado con los pies separados al ancho de los hombros y sosteniendo una mancuerna en una mano. Subí la mancuerna a la altura del hombro, como se muestra. Después, dá un paso hacia atrás y dejá que la rodilla de adelante se flexione hasta la posición de estocada. La rodilla de atrás también se puede flexionar. Después, empujá principalmente con la rodilla de adelante dirigiendo la presión por el talón y volvé a la posición inicial. Después repetí con la misma pierna. Mantené la pelvis nivelada y derecha todo el tiempo. La rodilla de adelante debe flexionarse alineada con el segundo dedo y no pasar la punta del pie.', 65365),
  ('POSICIÓN DE ROMBERG - UNA PIERNA - SLS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Cruzá los brazos sobre el pecho y después parate en una pierna. Hacé esto al lado de una mesa u otro objeto firme. Mantené el equilibrio en esta posición. Si perdés el equilibrio, podés usar una o más estrategias para ayudarte: apoyar los dedos del pie, dar un paso, descruzar los brazos y elevarlos hacia los costados, agarrarte de algo para apoyarte.', 54258),
  ('POSICIÓN DE ROMBERG - INESTABLE - UNA PIERNA - SLS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate arriba de una almohadilla de equilibrio, una almohada, un almohadón u otra superficie inestable. Equilibrate en una pierna y cruzá los brazos sobre el pecho. Hacé esto al lado de una mesa u otro objeto firme. Mantené el equilibrio en esta posición. Si perdés el equilibrio, podés usar una o más estrategias para ayudarte: apoyar los dedos del pie, dar un paso, descruzar los brazos y elevarlos hacia los costados, agarrarte de algo para apoyarte.', 54260),
  ('SENTADILLA BÚLGARA A UNA PIERNA - SENTADILLA BÚLGARA / ESTOCADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate sobre la pierna que querés trabajar y apoyá el otro pie sobre una silla u otro objeto bajo detrás tuyo, como se muestra. Después, flexioná la rodilla y bajá el cuerpo hacia el piso. Volvé a la posición de pie. La rodilla que trabajás debe flexionarse alineada con el segundo dedo y no pasar la punta del pie.', 16049),
  ('SENTARSE Y PARARSE - CON AYUDA DE UNA MANO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Sentado en una silla, deslizate hacia adelante, hacia el borde de la silla. Después, agarrate del apoyabrazos con una mano para apoyarte y después incorporate hasta quedar parado.', 27190),
  ('DE SENTADO A DE PIE - SENTADILLA A UNA PIERNA - SIN MANOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá sentado en una silla. Después, usando solo una pierna, incorporate hasta quedar parado sin usar las manos como apoyo.', 28007),
  ('SENTADILLA BÚLGARA - BARRA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con la barra apoyada sobre los hombros, detrás de la cabeza. Colocá los pies separados aproximadamente al ancho de los hombros. Después, agarrá la barra un poco más abierto que el ancho de los hombros. Sacá la barra del soporte y dá un paso atrás quedando en posición de tijera. Después, flexioná las dos rodillas para bajar el cuerpo y frená antes de que la rodilla toque el piso. Empujá con el talón de adelante para estirar las rodillas mientras subís, manteniendo la columna derecha. Repetí.', 154675),
  ('SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies separados al ancho de los hombros y las puntas de los pies hacia adelante o levemente hacia afuera. Flexioná las rodillas y bajá la cola hacia el piso manteniendo la espalda derecha y flexionando desde las caderas. Dejá que los brazos suban hacia adelante mientras bajás y volvé a llevarlos al costado al subir. La cola tiene que bajar por detrás de los pies, como si te fueras a sentar en una silla. Enfocá el peso a través de los talones. Para una buena alineación de rodilla, no dejes que las rodillas pasen por delante de los dedos del pie y mantené la rodilla alineada con el segundo dedo (el que está al lado del dedo gordo) al flexionar.', 75809),
  ('SENTADILLA - CON SILLA COMO GUÍA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parado con los pies separados al ancho de los hombros y frente a una silla que te mira, flexioná las rodillas y bajá el cuerpo hacia el piso. El asiento de la silla es una guía para que las rodillas no pasen por encima de los dedos del pie. El peso del cuerpo tiene que ir principalmente a través de los talones. Volvé a la posición de pie. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar más allá de los dedos.', 18213),
  ('SENTADILLA - BASE AMPLIA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá con una base amplia, las rodillas estiradas y las manos en las caderas. Después, flexioná las rodillas y bajá la cola hacia el piso. Después estirá las rodillas, volvé a la posición inicial y repetí.', 119354),
  ('SENTADILLA CON PRESS POR ENCIMA DE LA CABEZA - MANCUERNAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parate con los pies un poco más separados que el ancho de los hombros. Sostené las mancuernas a la altura de los hombros, como se muestra. Después, flexioná las rodillas y bajá la cola hacia el piso. Mantené la espalda derecha y flexioná desde las caderas. El peso del cuerpo tiene que ir principalmente a través de los talones. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar más allá de los dedos. Volvé a la posición de pie empujando con los talones mientras subís las pesas por encima de la cabeza extendiendo los codos. Bajá los pesos libres hasta cerca de la parte alta de los hombros y repetí.', 109437),
  ('SENTADILLA CON PELOTA - CON SILLA COMO GUÍA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Sosteniendo una pelota y parado con los pies separados al ancho de los hombros y frente a una silla que te mira, flexioná las rodillas y bajá el cuerpo hacia el piso. El asiento de la silla es una guía para que las rodillas no pasen por encima de los dedos del pie. El peso del cuerpo tiene que ir principalmente a través de los talones. Volvé a la posición de pie. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar más allá de los dedos.', 18214),
  ('SENTADILLAS - A UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parado sobre una pierna frente a un apoyo estable para asistir el equilibrio, flexioná la rodilla y bajá el cuerpo hacia el piso. Volvé a la posición de pie. La rodilla debe flexionarse alineada con el segundo dedo y no pasar el frente del pie.', 4671),
  ('BAJADA DEL ESCALÓN - HACIA ADELANTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Empezá con ambos pies arriba de un escalón o cajón. Después, bajá lentamente la pierna sana hacia adelante, fuera del escalón, para tocar suavemente el piso con el talón. Después volvé a la posición original con ambos pies sobre el escalón. Si hace falta, podés usar el mango de una escoba para el equilibrio. Mantené la alineación correcta de rodilla: alineada con el segundo dedo y sin pasar por delante de los dedos.', 7392),
  ('DESPLAZAMIENTOS EN BANQUETA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Sentate en una silla o banqueta con buena postura. Presioná el pie de adelante contra el piso y tirá de vos hacia adelante flexionando la rodilla. Después, hacelo del otro lado y alterná.', 72287),
  ('TRX - ESTOCADA DE EQUILIBRIO PLIOMÉTRICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Sostené las manijas del TRX mirando hacia el anclaje. Parate en una pierna y llevá la otra pierna hacia atrás mientras flexionás la rodilla de apoyo, como se muestra. Al volver a la posición erguida, estirá la rodilla del lado de apoyo e impulsate en un salto corto mientras la otra rodilla sube hasta la altura de la cintura o más. No dejes que la rodilla del lado de apoyo pase los dedos del pie. Mantené la rodilla de apoyo alineada con el pie.', 31504),
  ('TRX - BURPEE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Meté un pie en la cinta de una manija del TRX y después ponete de espaldas al anclaje. Equilibrate sobre el otro pie y después bajá el cuerpo a posición de plancha de flexión de brazos y hacé una flexión. Después, al volver a la posición de pie, saltá y aplaudí por encima de la cabeza.', 32695),
  ('TRX - ESTOCADA CRUZADA DE EQUILIBRIO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Sostené las manijas del TRX mirando hacia el anclaje. Parate en una pierna y llevá la otra pierna hacia atrás y cruzando la línea media mientras flexionás la rodilla de apoyo, como se muestra. Al volver a la posición erguida, estirá la rodilla del lado de apoyo mientras la otra rodilla vuelve a la posición original. No dejes que la rodilla del lado de apoyo pase los dedos del pie. Mantené la rodilla de apoyo alineada con el pie.', 31505),
  ('TRX - SENTADILLA A UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Sostené las manijas del TRX mirando hacia el anclaje. Parate en una pierna y llevá la otra pierna hacia adelante mientras flexionás la rodilla del lado de apoyo, como se muestra. Después, volvé a la posición erguida estirando la rodilla del lado de apoyo. No dejes que la rodilla del lado de apoyo pase los dedos del pie. Mantené la rodilla de apoyo alineada con el pie.', 31422),
  ('TRX - SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Sostené las manijas del TRX mirando hacia el anclaje. Los pies separados al ancho de los hombros. Flexioná las rodillas y volvé a la posición de pie. Las rodillas no deben pasar los dedos del pie y deben quedar alineadas con ellos.', 31425),
  ('TRX - COMBINACIÓN DE SENTADILLA Y REMO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Sostené las manijas del TRX mirando hacia el anclaje. Hacé una sentadilla y después un remo al acercarte a la posición de pie. Los pies deben estar separados al ancho de los hombros y las rodillas alineadas con los pies. Las rodillas NO deben pasar por delante de los dedos del pie.', 31424),
  ('TRASLADO DE PESO - DIAGONAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parado con las rodillas parcialmente flexionadas, colocá un pie adelante y el otro atrás en posición de tijera. Después, trasladá lentamente el peso del cuerpo en diagonal hacia el pie de adelante y después hacia el pie de atrás.', 7351),
  ('TRASLADO DE PESO - ADELANTE Y ATRÁS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada', 'Parado con las rodillas parcialmente flexionadas, trasladá lentamente el peso del cuerpo hacia adelante y después hacia atrás.', 7349),
  ('CAMINATAS LATERALES CON BANDA ELÁSTICA - MODIFICADA - PASOS LATERALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Banda elástica', 'Con una banda elástica en ambas manos y por debajo de los pies, dá pasos hacia el costado. Las rodillas deben estar levemente flexionadas todo el tiempo.', 5880),
  ('ESTOCADA LATERAL CON RESISTENCIA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Banda elástica', 'Usá una cuerda deportiva, banda elástica o cable de polea fijado a un cinto hacia tu costado. Después, hacé una estocada hacia el costado y volvé a la posición original. Mantené las puntas de los pies apuntando derecho hacia adelante. Usá marcas o cinta en el piso para enfocarte en el control de la caída y la posición de los pies. Aumentá la distancia o la velocidad para progresar.', 7651),
  ('ESTOCADA LATERAL CON RESISTENCIA - DIAGONAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Banda elástica', 'Usá una cuerda deportiva, banda elástica o cable de polea fijado a un cinto hacia tu costado. Después, hacé una estocada en diagonal y HACIA ATRÁS al costado. Tenés que caer de modo que las puntas de los pies sigan apuntando hacia adelante. Después, hacé una estocada lateral hacia la posición original. En la repetición siguiente, hacé la estocada en diagonal HACIA ADELANTE y después volvé a la posición original. Usá marcas o cinta en el piso para enfocarte en el control de la caída y la posición de los pies. Aumentá la distancia o la velocidad para progresar.', 7653),
  ('TKE CON BANDA ELÁSTICA LATERAL - EXTENSIÓN TERMINAL DE RODILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Banda elástica', 'Envolvé una banda elástica alrededor de la pierna de apoyo, como se muestra, de modo que traccione la rodilla cruzando por delante del cuerpo. Después, flexioná la rodilla de apoyo y bajá el cuerpo hacia el piso. Volvé a la posición de pie. La rodilla de apoyo debe flexionarse alineada con el segundo dedo y no pasar el frente del pie. Usá los brazos como apoyo si hace falta, por equilibrio y seguridad.', 5881),
  ('TKE - ESTOCADAS INVERSAS - BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Banda elástica', 'Empezá en posición de pie con una banda elástica fijada por encima de la rodilla y la otra punta atada con un nudo y fijada detrás de una puerta cerrada u otro anclaje. Dá un paso hacia atrás con la pierna contraria y hacé una estocada. Empujá desde el talón del pie de adelante y volvé a la posición inicial mientras estirás las rodillas. Repetí.', 159901),
  ('SENTADILLA CON PRESS DE KETTLEBELL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Banda elástica; Isométrico', 'Sostené una kettlebell a la altura del pecho y hacé una sentadilla. Al subir, elevá la kettlebell hacia arriba, por encima de la cabeza.', 28609),
  ('ESTOCADA LATERAL CON RESISTENCIA - ROTACIÓN DIAGONAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Banda elástica; Máquinas y poleas', 'Usá una cuerda deportiva, banda elástica o cable de polea fijado a un cinto hacia tu costado. Después, hacé una estocada en diagonal y HACIA ATRÁS al costado. Tenés que caer de modo que las puntas de los pies apunten hacia el costado y alineadas con la dirección del movimiento. Después, hacé una estocada lateral hacia la posición original. En la repetición siguiente, hacé la estocada en diagonal HACIA ADELANTE y después volvé a la posición original. Usá marcas o cinta en el piso para enfocarte en el control de la caída y la posición de los pies. Aumentá la distancia o la velocidad para progresar.', 7652),
  ('ALMEJA EN DECÚBITO LATERAL ELEVADA - CLAM SHELL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Cadena abierta', 'Acostado de costado con las rodillas flexionadas, elevá el cuerpo apoyándote sobre el codo y el antebrazo y la rodilla de abajo, hasta lograr una columna derecha. Al mismo tiempo, elevá la rodilla de arriba más alto, como se muestra. Bajá y repetí. No dejes que la pelvis rote hacia atrás durante el movimiento de elevación.', 157231),
  ('ESTIRAMIENTO EN FLEXIÓN DE RODILLA - ESTOCADA EN SILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Estiramientos', 'Empezá parado frente a una silla. Apoyá el pie de la rodilla afectada sobre el asiento y después flexioná esa rodilla hasta sentir un estiramiento. Mantené, volvé a la posición inicial y repetí.', 135807),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES DE PIE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Estiramientos', 'Empezá parado con un pie adelante y el talón apoyado en el piso. Después, inclinate lentamente hacia adelante hasta sentir un estiramiento detrás de la rodilla y el muslo. Flexioná desde las caderas y no desde la columna. Mantené, después volvé a la posición inicial y repetí.', 130990),
  ('ESTIRAMIENTO DE FLEXORES DE CADERA DE PIE - ESTOCADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena cerrada; Estiramientos', 'Parado en posición de paso, con una pierna adelante de la otra, inclinate hacia adelante y flexioná la rodilla de adelante hasta sentir un estiramiento en la zona de la cadera anterior de la pierna de atrás.', 149054),
  ('CLX - ABDUCCIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Parado con un CLX enlazado alrededor de cada pie, elevá la pierna hacia el costado, como se muestra. Volvé a la posición inicial y repetí. Si hace falta, sostenete de una silla, pared o mesa para el equilibrio.', 40136),
  ('CLX - CAMINATAS LATERALES - PASOS LATERALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Colocá los 2 anillos centrales consecutivos del CLX alrededor de los muslos. Después sostené las puntas y dá pasos hacia el costado manteniendo los pies separados. Mantené las rodillas flexionadas todo el tiempo.', 40106),
  ('CLX - SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Colocá los pies en los anillos del CLX cerca del centro, dejando un anillo en el medio. Sujetá los anillos de las puntas a cada mano. Después, cruzá los brazos y hacé una sentadilla. El peso del cuerpo tiene que ir principalmente a través de los talones. Volvé a la posición de pie. Las rodillas deben flexionarse alineadas con el segundo dedo y no pasar más allá de los dedos.', 40132),
  ('BANDA ELÁSTICA - ROTACIÓN INTERNA DE CADERA - SENTADO CON PIERNAS EXTENDIDAS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Sentate en el piso con las rodillas flexionadas, como se muestra. Enlazá una banda elástica alrededor de la pierna, justo por encima de la rodilla. Llevá la rodilla hacia adentro, en dirección al piso, después volvé a la posición inicial y repetí.', 159900),
  ('BANDA ELÁSTICA - ALMEJAS SENTADO - ABDUCCIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Sentado en una silla de ruedas, colocá una banda elástica circular alrededor de los muslos, cerca de las rodillas, como se muestra. Empezá separando ambas rodillas hacia los costados. Volvé a la posición inicial y repetí. Mantené los pies en contacto con el piso todo el tiempo.', 104773),
  ('BANDA ELÁSTICA EN 8 - ALMEJAS SENTADO - ABDUCCIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Sentado en una silla, colocá una banda elástica en forma de 8 alrededor de los muslos, cerca de las rodillas, como se muestra. Empezá separando ambas rodillas hacia los costados. Volvé a la posición inicial y repetí. Mantené los pies en contacto con el piso todo el tiempo.', 163275),
  ('GERIÁTRICO - BANDA ELÁSTICA - ABDUCCIÓN DE CADERA - ALMEJAS SENTADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Sentado en una silla, colocá una banda elástica circular alrededor de los muslos, cerca de las rodillas, como se muestra. Empezá separando ambas rodillas hacia los costados. Volvé a la posición inicial y repetí. Mantené los pies en contacto con el piso todo el tiempo.', 124433),
  ('CAMINATAS LATERALES - BANDA EN 8 - PASOS LATERALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Envolvé una banda elástica alrededor de las piernas, como se muestra. Empezá pisando la banda con los pies separados aproximadamente al ancho de los hombros. Después, pasá la banda por delante de los tobillos, cruzala hacia el otro lado, envolvela por detrás de las rodillas y los muslos y sostenela con las manos cruzadas. Una vez armada la banda, dá pasos hacia el costado manteniendo los pies separados y las rodillas flexionadas. Hacé pasos laterales en una dirección y después en la otra.', 66773),
  ('CAMINATA DE MONSTRUO - BANDA ELÁSTICA EN LOS MUSLOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Colocá una banda elástica circular alrededor de ambos muslos. Después, flexioná las rodillas y dá pasos hacia adelante manteniendo la tensión de la banda todo el tiempo. Después de varios pasos hacia adelante, invertí la dirección y caminá hacia atrás hasta volver a la posición inicial. Repetí.', 135808),
  ('MARCHA SENTADO - BANDA ELÁSTICA EN 8', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Empezá sentado en una silla con una banda elástica en 8 alrededor de la parte baja de los muslos. Después, subí una rodilla, bajala y alterná con el otro lado.', 163274),
  ('PATADAS CON BANDA ELÁSTICA A UNA PIERNA - APOYO UNIPODAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica', 'Empezá con una banda elástica circular alrededor de los tobillos, parado sobre la pierna que querés trabajar. Después, movés la otra pierna estirando la banda hacia adelante, hacia el costado y hacia atrás, unas cuantas repeticiones en cada dirección. Mantené el equilibrio sobre la pierna de apoyo todo el tiempo. Para progresar, aumentá la velocidad o la resistencia.', 8073),
  ('BICICLETA CON BANDA ELÁSTICA - EXTENSIÓN DE CADERA EN DECÚBITO DORSAL SIN APOYO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Acostate boca arriba con las rodillas flexionadas. Pasá una banda elástica alrededor de ambos pies. Elevá los dos pies de modo que las caderas queden a 90 grados y las rodillas a 90 grados. Usá los músculos abdominales para que la columna no se mueva durante el ejercicio. Empezá estirando una pierna alejándola de vos. Después, volvé con la pierna a la posición inicial y repetí del otro lado. Repetí.', 79205),
  ('CLX - EXTENSIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Colocá las anillas del CLX alrededor de los tobillos. Con las rodillas estiradas, llevá la pierna que trabajás hacia atrás, después volvé y repetí.', 40107),
  ('BANDA ELÁSTICA - CURLS DE ISQUIOTIBIALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Fijá una banda elástica circular a tu tobillo y al pie contrario, con una pierna apoyada sobre una silla u otro objeto elevado. Después, llevá la pierna hacia abajo flexionando la rodilla, mientras el otro tobillo fija la banda en la silla.', 107),
  ('BANDA ELÁSTICA - DIAGONAL DE CADERA - EXTENSIÓN Y ABDUCCIÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Fijá una banda elástica a tu tobillo. Empezá en posición de pie con la pierna adelante y hacia adentro del cuerpo. Después, llevá la pierna hacia atrás y afuera, como se muestra. Usá los brazos como apoyo si necesitás equilibrio y seguridad.', 105),
  ('BANDA ELÁSTICA - DIAGONAL DE CADERA - EXTENSIÓN Y ADUCCIÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Fijá una banda elástica a tu tobillo. Empezá en posición de pie con la pierna adelante y hacia afuera del cuerpo. Después, llevá la pierna hacia atrás y adentro, como se muestra. Usá los brazos como apoyo si necesitás equilibrio y seguridad.', 104),
  ('BANDA ELÁSTICA - ROTACIÓN EXTERNA DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Empezá con una banda elástica fijada al tobillo desde el costado. Después, tirá hacia la otra pierna evitando que el muslo se desplace sobre la camilla.', 417),
  ('BANDA ELÁSTICA - ROTACIÓN INTERNA DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Empezá con una banda elástica fijada al tobillo desde el costado. Después, tirá alejándote de la otra pierna evitando que el muslo se desplace sobre la camilla.', 418),
  ('BANDA ELÁSTICA - EXTENSIÓN DE RODILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Fijá una punta de una banda elástica al tobillo y anclala por detrás tuyo. Sentate en una silla. Empezá con el talón en el piso y después estirá la rodilla para elevar el pie, como se muestra. Tratá de estirar completamente la rodilla contra la resistencia de la banda. Después, bajá el pie flexionando la rodilla y tocá el piso con el talón. Repetí.', 111),
  ('BANDA ELÁSTICA EN 8 - EXTENSIÓN DE RODILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Sentate en una silla con una banda elástica en 8 en los tobillos. Empezá con el talón en el piso y después estirá la rodilla para elevar el pie, como se muestra. Tratá de estirar completamente la rodilla contra la resistencia de la banda mientras el otro pie queda fijo en el piso. Después, bajá el pie flexionando la rodilla y tocá el piso con el talón. Repetí.', 163284),
  ('BANDA ELÁSTICA EN 8 - EXTENSIÓN DE RODILLA - ALTERNADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Sentate en una silla con una banda elástica en 8 en los tobillos. Empezá con el talón en el piso y después estirá la rodilla para elevar el pie, como se muestra. Tratá de estirar completamente la rodilla contra la resistencia de la banda mientras el otro pie queda fijo en el piso. Después, bajá el pie flexionando la rodilla y tocá el piso con el talón. Repetí alternando de lado a lado.', 163285),
  ('BANDA ELÁSTICA EN 8 - FLEXIÓN DE RODILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Sentate con una banda elástica en 8 fijada a los tobillos. Flexioná la rodilla mientras deslizás el pie hacia la silla, mientras el otro pie queda fijo en el piso. Mantené, volvé a la posición inicial y repetí.', 163286),
  ('BANDA ELÁSTICA EN 8 - FLEXIÓN DE RODILLA - ALTERNADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Sentate con una banda elástica en 8 fijada a los tobillos. Flexioná la rodilla mientras deslizás el pie hacia la silla, mientras el otro pie queda fijo en el piso. Mantené, volvé a la posición inicial y repetí alternando de lado a lado.', 163287),
  ('HIDRANTE - ABDUCCIÓN DE CADERA EN CUATRO APOYOS CON BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Empezá en posición de gateo con una banda elástica alrededor de los muslos. Después, elevá la pierna hacia el costado, como se muestra. Mantené la espalda alta y media derecha.', 36149),
  ('GERIÁTRICO - MARCHA SENTADO - BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Empezá sentado en una silla con una banda elástica alrededor de la parte baja de los muslos. Después, flexioná desde la cadera para elevar una pierna del piso y volvé a bajarla. Después elevá la otra pierna y bajala. Repetí alternando los lados.', 124435),
  ('FLEXIÓN DE CADERA - BANDA ELÁSTICA CIRCULAR', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Colocá una banda circular alrededor de ambos pies, a la altura del medio del pie. Parado, elevá una cadera dejando que la rodilla se flexione. Bajá y repetí con la misma pierna.', 153688),
  ('FLEXIÓN DE CADERA - BANDA ELÁSTICA CIRCULAR - BILATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Colocá una banda circular alrededor de ambos pies, a la altura del medio del pie. Parado, elevá una cadera dejando que la rodilla se flexione. Bajá y repetí con la pierna contraria. Repetí alternando el movimiento.', 153693),
  ('CAMINATA DE MONSTRUO LATERAL - BANDA ELÁSTICA EN LOS PIES - PASOS LATERALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Colocá una banda elástica alrededor de ambos pies. Después, flexioná las rodillas y dá pasos hacia el costado manteniendo la tensión de la banda todo el tiempo. Después de varios pasos laterales en una dirección, invertí la dirección hasta volver a la posición inicial. Repetí.', 83356),
  ('BANDA ELÁSTICA CIRCULAR - FLEXIÓN Y EXTENSIÓN DE CADERA - MARCHA EN DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Acostate boca arriba con una banda elástica circular alrededor de los pies, como se muestra. Después, llevá una rodilla y cadera hacia el pecho tirando contra la resistencia de la banda. Bajá y después hacelo del otro lado. Repetí alternando las piernas.', 78540),
  ('ABDUCCIÓN DE CADERA CON BANDA ELÁSTICA CIRCULAR', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Parate con una banda elástica circular alrededor de los muslos, justo por encima de las rodillas. Después, llevá la pierna que trabajás hacia el costado, como se muestra. Bajá y repetí.', 153691),
  ('CURLS DE ISQUIOTIBIALES CON BANDA ELÁSTICA EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Fijá una banda elástica alrededor de tu pie y del tobillo contrario, como se muestra. Después, acostado boca abajo, flexioná lentamente la rodilla que trabajás llevando el pie hacia la cola. Mantené el otro pie en el piso para fijar la banda.', 12914),
  ('MARCHA SENTADO - BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Empezá sentado en una silla con una banda elástica alrededor de la parte baja de los muslos. Después, subí una rodilla, bajala y alterná con el otro lado.', 104777),
  ('PRENSA A UNA PIERNA - BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Banda elástica; Cadena abierta', 'Sentate en una silla y sostené una banda elástica con ambas manos. Pasá la banda alrededor del pie que trabajás y después tirá de la banda y del pie hacia arriba flexionando la rodilla. Después empujá la rodilla y la cadera hacia la extensión mientras estirás la pierna contra la resistencia de la banda. Repetí.', 69880),
  ('RODILLO DE ESPUMA - TIBIAL ANTERIOR', NULL, true, 'sin_clasificar', 'Cadera y rodilla', 'Rodillo de espuma', 'Empezá en posición de gateo y colocá el rodillo de espuma sobre la parte de adelante de la pierna, como se muestra, con el pie girado hacia adentro. Usando los brazos, rodá hacia adelante y atrás sobre esa zona.', 157239),
  ('ACTIVACIÓN DE ISQUIOTIBIALES - ÉNFASIS LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Acostado boca arriba, flexioná levemente la rodilla con la pierna rotada hacia afuera y después presioná el talón contra el piso.', 9463),
  ('ACTIVACIÓN DE ISQUIOTIBIALES - ÉNFASIS MEDIAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Acostado boca arriba, flexioná levemente la rodilla con la pierna rotada hacia adentro y después presioná el talón contra el piso.', 9464),
  ('ABDUCCIÓN DE CADERA - ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Sentado al lado de una pared, presioná la parte de afuera de la rodilla contra la pared. Si necesitás, colocá una toalla entre la rodilla y la pared para mayor comodidad.', 122),
  ('ABDUCCIÓN DE CADERA ISOMÉTRICA - CON LAS MANOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Sentate en una silla y colocá las manos en la parte de afuera de los muslos, cerca de las rodillas. Intentá separar las rodillas hacia afuera mientras resistís el movimiento con las manos. Mantené, relajá y repetí.', 76010),
  ('ADUCCIÓN DE CADERA APRETANDO UNA PELOTA - DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Acostado boca arriba, colocá una pelota entre las rodillas. Apretá la pelota con las rodillas y mantené.', 17391),
  ('ADUCCIÓN DE CADERA ISOMÉTRICA - CON LAS MANOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Sentate en una silla y colocá las manos en la parte de adentro de los muslos o de las rodillas. Intentá juntar las rodillas mientras resistís el movimiento con las manos. Mantené, relajá y repetí.', 70020),
  ('FLEXIÓN DE CADERA - ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Parado frente a una pared, llevá la rodilla hacia adelante y presionala contra la pared. Si necesitás, colocá una toalla doblada entre la rodilla y la pared para mayor comodidad. Mantené, relajá y repetí.', 127),
  ('FLEXIÓN DE CADERA ISOMÉTRICA - ALTERNADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Acostado boca arriba, elevá la rodilla y presionala contra tu mano. Después, volvé a la posición original y repetí del otro lado.', 6839),
  ('FLEXIÓN DE CADERA ISOMÉTRICA - CON LAS MANOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Sentate en una silla y colocá las manos sobre el muslo, cerca de la rodilla. Intentá subir la rodilla contra las manos mientras resistís el movimiento con ellas. Mantené, relajá y repetí.', 76011),
  ('ISOMÉTRICO DE FLEXIÓN DE CADERA BILATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Acostado boca arriba, elevá las rodillas y presionalas contra las manos.', 332),
  ('ISOMÉTRICO DE ROTACIÓN EXTERNA DE CADERA - APRETAR TALONES - RE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Acostado boca abajo, separá las rodillas y apretá los talones entre sí. Mantené, relajá y repetí.', 330),
  ('ACTIVACIÓN DE CUÁDRICEPS EN DECÚBITO VENTRAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Isométrico', 'Acostado boca abajo, apoyá los dedos de los pies en el piso o la camilla. Después, estirá la rodilla de modo que la parte de atrás de la rodilla se eleve, y mantené esta posición.', 16047),
  ('ESCALERA DE AGILIDAD - ICKEY SHUFFLE HACIA ATRÁS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado en la esquina superior de la escalera de agilidad, de espaldas a la escalera. Flexioná las rodillas y los codos. Pisá hacia atrás dentro del primer cuadrado con el pie más cercano a la escalera y después entrá al mismo cuadrado con el otro pie. Después, salí de la escalera hacia el otro lado con el mismo pie con el que empezaste. Después repetí en la otra dirección, entrando hacia atrás al segundo cuadrado con el pie más cercano a la escalera y después con el otro pie. Después, salí de la escalera hacia el otro lado con un pie. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45627),
  ('ESCALERA DE AGILIDAD - SALTOS ABIERTOS HACIA ATRÁS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado delante de la escalera de agilidad, de espaldas a la escalera y con las piernas separadas. Flexioná las rodillas y los codos. Saltá hacia atrás con cada pie por fuera de la escalera, en lados opuestos. Después, saltá con ambos pies dentro del primer cuadrado. Repetí esto saltando con cada pie por fuera de la escalera en lados opuestos y después con ambos pies hacia atrás dentro del segundo cuadrado. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45641),
  ('ESCALERA DE AGILIDAD - CIEMPIÉS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado en la esquina superior de la escalera de agilidad, con el cuerpo de costado hacia la escalera. Flexioná las rodillas y los codos. Entrá al primer cuadrado con un pie y después con el otro, alternando. Después, pasá lateralmente al segundo cuadrado con el pie de adelante y después con el otro pie. Después, pisá hacia atrás y fuera de la escalera con el pie de adelante y después con el otro. Repetí esta secuencia mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45602),
  ('ESCALERA DE AGILIDAD - CRUCE POR DETRÁS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado al costado de la escalera de agilidad, mirando hacia adelante. Flexioná las rodillas y los codos. Cruzá la pierna de afuera por detrás de la otra y entrá al primer cuadrado. Después, salí alternando cada pie por fuera de la escalera hacia el otro lado. Repetí esto en el segundo cuadrado, cruzando la pierna de afuera por detrás de la otra y entrando al segundo cuadrado. Después salí hacia afuera de la escalera con cada pie. Repetí esta secuencia mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45603),
  ('ESCALERA DE AGILIDAD - CRUCE POR DELANTE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado al frente de la escalera de agilidad, con el costado del cuerpo hacia la escalera. Flexioná las rodillas y los codos. Cruzá la pierna de atrás por delante de la otra y entrá al primer cuadrado. Después desenredá las piernas y llevá la otra pierna al segundo cuadrado. Repetí esta secuencia mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45604),
  ('ESCALERA DE AGILIDAD - DOBLE SALTO ADENTRO Y AFUERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado de costado en la escalera de agilidad. Flexioná las rodillas y los codos. Saltá con ambos pies dentro del primer cuadrado y después saltá hacia atrás y afuera, quedando del mismo lado en el que empezaste. Después, saltá con ambos pies dentro del segundo cuadrado y después saltá hacia atrás y afuera. Repetí esta secuencia mientras te movés de costado a lo largo de la escalera. Aumentá la velocidad a medida que mejorás.', 46149),
  ('ESCALERA DE AGILIDAD - DOBLE SALTO LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado de costado al frente de la escalera de agilidad. Flexioná las rodillas y los codos. Saltá con ambos pies dentro del primer cuadrado y después saltá con ambos pies dentro del segundo cuadrado. Repetí esta secuencia mientras te movés de costado a lo largo de la escalera. Aumentá la velocidad a medida que mejorás.', 46150),
  ('ESCALERA DE AGILIDAD - RODILLA ALTA CON 2 PASOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado mirando hacia adelante, delante de la escalera de agilidad. Flexioná las rodillas y los codos. Hacé pasos con rodilla alta (elevando bien la rodilla) mientras cada pie aterriza alternadamente en cada cuadrado a medida que avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 46146),
  ('ESCALERA DE AGILIDAD - RODILLA ALTA CON UN PASO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado mirando hacia adelante, delante de la escalera de agilidad. Flexioná las rodillas y los codos. Hacé pasos con rodilla alta (elevando bien la rodilla) apoyando un pie en el primer cuadrado y después el otro pie en el segundo cuadrado. Repetí esta secuencia mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 46147),
  ('ESCALERA DE AGILIDAD - RODILLA ALTA DE COSTADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado de costado delante de la escalera de agilidad. Flexioná las rodillas y los codos. Hacé pasos con rodilla alta (elevando bien la rodilla) apoyando cada pie alternadamente en cada cuadrado mientras te movés de costado a lo largo de la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 46148),
  ('ESCALERA DE AGILIDAD - UN PASO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado mirando hacia adelante, delante de la escalera de agilidad. Flexioná las rodillas y los codos. Apoyá un pie en el primer cuadrado y después el otro pie en el segundo cuadrado. Repetí esta secuencia mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45634),
  ('ESCALERA DE AGILIDAD - UN PASO CON SHUFFLE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado en la esquina superior de la escalera de agilidad, mirando hacia adelante. Flexioná las rodillas y los codos. Entrá al primer cuadrado con el pie más cercano a la escalera. Después dá 3 pasos rápidos alternados por fuera de la escalera. Quedate del mismo lado de la escalera y repetí esta secuencia en el segundo cuadrado, entrando con el pie más cercano a la escalera. Después dá 3 pasos rápidos alternados por fuera de la escalera. Repetí esta secuencia mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45638),
  ('ESCALERA DE AGILIDAD - RIVER DANCE', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado en la esquina superior de la escalera de agilidad, mirando hacia adelante. Flexioná las rodillas y los codos. Entrá al primer cuadrado con el pie más cercano a la escalera y después cruzá la otra pierna por detrás del pie apoyado y pasá al otro lado de la escalera. Después, llevá el pie que estaba en el primer cuadrado al lado del otro pie, por fuera de la escalera. Repetí esta secuencia en el segundo cuadrado y mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45635),
  ('ESCALERA DE AGILIDAD - SALTO A UNA PIERNA ADENTRO Y AFUERA - LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado al frente de la escalera de agilidad, con el costado del cuerpo hacia la dirección de la escalera. Flexioná las rodillas y los codos. Equilibrate sobre una pierna (la más cercana a la escalera) y después saltá al primer cuadrado con esa pierna. Después, saltá fuera del cuadrado y después saltá al segundo cuadrado con la misma pierna. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 46153),
  ('ESCALERA DE AGILIDAD - SALTO A UNA PIERNA LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado al frente de la escalera de agilidad, con el costado del cuerpo hacia la dirección de la escalera. Flexioná las rodillas y los codos. Equilibrate sobre una pierna (la más cercana a la escalera) y después saltá al primer cuadrado con esa pierna. Después, saltá al segundo cuadrado con la misma pierna. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 46155),
  ('ESCALERA DE AGILIDAD - SALTO A UNA PIERNA MEDIAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado al frente de la escalera de agilidad, con el costado del cuerpo hacia la dirección de la escalera. Flexioná las rodillas y los codos. Equilibrate sobre una pierna (la más alejada de la escalera) y después saltá al primer cuadrado con esa pierna. Después, saltá al segundo cuadrado con la misma pierna. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 46156),
  ('ESCALERA DE AGILIDAD - SALTOS EN SLALOM', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado en la esquina superior de la escalera de agilidad, mirando hacia adelante. Flexioná las rodillas y los codos. Saltá con ambos pies al mismo tiempo, con un pie dentro del primer cuadrado y el otro al costado y por detrás del primer cuadrado. Después, saltá hacia adelante con ambas piernas de modo que el pie que estaba fuera de la escalera pase al segundo cuadrado y el otro pie salga de la escalera del lado opuesto. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 45639),
  ('ESCALERA DE AGILIDAD - SALTOS EN SLALOM CON SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado mirando hacia adelante, cerca de la escalera de agilidad. Flexioná las rodillas y los codos. Saltá con ambos pies al mismo tiempo, con un pie dentro del primer cuadrado y el otro al costado del primer cuadrado. Al aterrizar, flexioná las rodillas en posición de sentadilla. Después, saltá hacia adelante con ambas piernas de modo que el pie que estaba fuera de la escalera pase al segundo cuadrado y el otro pie salga de la escalera del lado opuesto. Asegurate de hacer una sentadilla en cada aterrizaje. Repetí esta secuencia mientras avanzás por la escalera. Aumentá la velocidad a medida que mejorás.', 46152),
  ('ESCALERA DE AGILIDAD - PIES DE LINEBACKER', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Escalera de agilidad', 'Empezá parado al frente de la escalera de agilidad, con el costado del cuerpo hacia la escalera. Flexioná las rodillas y los codos. Entrá al primer cuadrado con el pie más cercano a la escalera y alterná rápidamente levantando cada pie y volviéndolo a apoyar. Hacé 2 pasos con cada pie y después pasá al cuadrado siguiente. Repetí esta secuencia mientras avanzás por la escalera. Mantenete en las puntas de los pies. Vibrá con los brazos. Aumentá la velocidad a medida que mejorás.', 45633),
  ('POLEA - EXTENSIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Máquinas y poleas', 'Colocá la polea en posición baja y parate de frente a la polea, con la cinta sujeta al tobillo de la pierna que vas a trabajar. Trasladá el peso a la otra pierna y llevá el tobillo hacia atrás, por detrás del cuerpo. Volvé a la posición inicial y repetí.', 155902),
  ('CINTA - DESPLAZAMIENTO LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Máquinas y poleas', 'Empezá caminando hacia adelante en la cinta y después girá de costado y hacé pasos de desplazamiento lateral. Después girá para caminar hacia adelante otra vez y después girá hacia la otra dirección y hacé desplazamientos laterales del otro lado.', 137145),
  ('CINTA - CAMINATA LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Máquinas y poleas', 'Empezá caminando despacio hacia adelante en la cinta. Después, girá de costado y hacé pasos laterales. Después, caminá hacia adelante otra vez. Después, girá hacia el lado opuesto y hacé pasos laterales. Volvé a caminar hacia adelante y repetí.', 137166),
  ('CINTA - DESPLAZAMIENTO UNILATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Máquinas y poleas', 'Empezá caminando hacia adelante en la cinta y después girá de costado y hacé pasos de desplazamiento lateral, como se muestra.', 137143),
  ('CINTA - CAMINATA UNILATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Máquinas y poleas', 'Empezá caminando despacio hacia adelante en la cinta. Después, girá de costado y hacé pasos laterales en una sola dirección.', 137142),
  ('POLEA - ROTACIÓN EXTERNA DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Máquinas y poleas; Cadena abierta', 'Colocá la polea en posición baja, sentate en una silla o banco con la polea del lado del cuerpo más cercano a la pierna que vas a trabajar y sujetá la cinta al tobillo. Llevá el tobillo hacia adentro, cruzando por delante del cuerpo. Volvé a la posición inicial y repetí.', 155167),
  ('POLEA - FLEXIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Máquinas y poleas; Cadena abierta', 'Colocá la polea en posición baja y parate de espaldas a la polea, con la cinta sujeta al tobillo de la pierna que vas a trabajar. Trasladá el peso a la otra pierna y llevá el tobillo hacia adelante, por delante del cuerpo. Volvé a la posición inicial y repetí.', 155165),
  ('POLEA - FLEXIÓN DE CADERA - RODILLA FLEXIONADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Máquinas y poleas; Cadena abierta', 'Colocá la polea en posición baja y parate de espaldas a la polea, con la cinta sujeta al tobillo de la pierna que vas a trabajar. Trasladá el peso a la otra pierna y elevá la pierna hacia adelante flexionando la rodilla, como en una marcha. Volvé a la posición inicial y repetí.', 155183),
  ('POLEA - ROTACIÓN INTERNA DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Máquinas y poleas; Cadena abierta', 'Colocá la polea en posición baja, sentate en una silla o banco con la polea del lado del cuerpo más alejado de la pierna que vas a trabajar y sujetá la cinta al tobillo. Llevá el tobillo hacia afuera, alejándolo del cuerpo. Volvé a la posición inicial y repetí.', 155168),
  ('MOVILIZACIÓN DE RODILLA - TOALLA', NULL, true, 'activo', 'Cadera y rodilla', 'Varios; Movilización', 'Colocá una toalla chica enrollada debajo de la rodilla con el pie apoyado en una silla. Flexioná lentamente la rodilla y dejá que la toalla haga una presión suave debajo de la rodilla. Mantené, relajá y repetí.', 66922),
  ('SALTOS AGRUPADOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Varios; Pliometría', 'Hacé una sentadilla y después usá ambas piernas para saltar hacia arriba. En el aire, flexioná las rodillas y las caderas hasta la posición agrupada, como se muestra. Caé de nuevo en el piso con ambos pies y después repetí.', 76593),
  ('ELEVACIÓN DE CADERA - ARRODILLADO', NULL, true, 'activo', 'Cadera y rodilla', 'Movilización', 'Arrodillate en el piso con una toalla doblada debajo de la rodilla del lado que vas a trabajar, como se muestra. Después, elevá la pelvis del lado opuesto, como se muestra. Bajá y repetí.', 167434),
  ('POLEA - ABDUCCIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'Colocá la polea en posición baja y parate con la polea del lado del cuerpo más cercano a la pierna que no trabaja, y sujetá la cinta al tobillo. Trasladá el peso a la otra pierna y llevá el tobillo hacia afuera, alejándolo del costado del cuerpo. Volvé a la posición inicial y repetí.', 155162),
  ('POLEA - ADUCCIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'Colocá la polea en posición baja, parate con la polea del lado del cuerpo más cercano a la pierna que vas a trabajar y sujetá la cinta al tobillo. Trasladá el peso a la otra pierna y llevá el tobillo hacia adentro, cruzando por delante del cuerpo. Volvé a la posición inicial y repetí.', 155163),
  ('POLEA - EXTENSIÓN DE CADERA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'Colocá la polea en posición baja, parate de frente a la polea con la cinta sujeta al tobillo de la pierna que vas a trabajar. Trasladá el peso a la otra pierna y llevá el tobillo hacia atrás, por detrás del cuerpo. Volvé a la posición inicial y repetí.', 155164),
  ('BANDA ELÁSTICA - CURL DE ISQUIOTIBIALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'Sentado y con una banda elástica sujeta al tobillo, flexioná la rodilla y llevá el pie hacia atrás.', 106),
  ('BANDA ELÁSTICA - EXTENSIÓN DE RODILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'Sujetá una banda elástica circular a tu tobillo y al pie contrario. Después, llevá la pierna hacia arriba hasta estirar la rodilla mientras el otro pie hace de anclaje de la banda.', 419),
  ('CURL DE ISQUIOTIBIALES - BILATERAL - MÁQUINA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'Acostate boca abajo en la máquina o el banco de curl de piernas y colocá los tobillos debajo de los apoyos. Flexioná las rodillas para levantar el peso. Volvé a la posición inicial y repetí. No apuntes los dedos de los pies hacia adelante.', 62937),
  ('CURL DE ISQUIOTIBIALES - UNA PIERNA - MÁQUINA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'Acostate boca abajo en la máquina o el banco de curl de piernas y colocá el tobillo debajo del apoyo. Flexioná la rodilla para levantar el peso. Volvé a la posición inicial y repetí. No apuntes los dedos del pie hacia adelante.', 62942),
  ('EXTENSIÓN DE RODILLA - BILATERAL - MÁQUINA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'Sentate en la máquina o el banco de extensión de rodilla y colocá los tobillos debajo de los apoyos. Extendé las rodillas para levantar el peso. Volvé a la posición inicial y repetí.', 62945),
  ('EXTENSIÓN DE RODILLA - AUTOASISTIDA', NULL, true, 'activo', 'Cadera y rodilla', 'Cadena abierta', 'Colocá la pierna sana debajo de la afectada. Usá la pierna sana para ayudar a la afectada a llegar a la posición de rodilla estirada.', 4717),
  ('EXTENSIÓN DE RODILLA - UNA PIERNA - MÁQUINA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'Sentate en la máquina o el banco de extensión de rodilla y colocá el tobillo debajo del apoyo. Extendé la rodilla para levantar el peso. Volvé a la posición inicial y repetí.', 62946),
  ('EXTENSIÓN DE CADERA CON BANDA ELÁSTICA CIRCULAR', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'De pie con una banda elástica circular alrededor de los tobillos, llevá la pierna que trabajás hacia atrás, como se muestra. Mantené las rodillas estiradas todo el tiempo.', 8075),
  ('CURLS DE ISQUIOTIBIALES EN DECÚBITO VENTRAL - ASISTIDOS', NULL, true, 'activo_asistido', 'Cadera y rodilla', 'Cadena abierta', 'Acostado boca abajo, flexioná la rodilla afectada con la ayuda de la pierna sana.', 144),
  ('EJERCICIO DEL PATINADOR DE VELOCIDAD', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Cadena abierta', 'Saltá de lado a lado cayendo sobre un pie. Balanceá los brazos de forma alternada para ayudarte con el impulso. Aumentá la altura y/o la velocidad como progresión.', 76592),
  ('SILLA DE RUEDAS - MARCHA', NULL, true, 'activo', 'Cadera y rodilla', 'Cadena abierta', 'Despegá el pie del piso mientras flexionás la rodilla. Bajá de nuevo y repetí con la otra pierna. Repetí este movimiento alternando.', 105320),
  ('SALTOS CON PIES EN TIJERA - PLIOMÉTRICO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Parate con una pierna adelante de la otra (posición en tijera). Empezá saltando y cayendo en la misma posición. Mantené el equilibrio todo el tiempo. Repetí. Aumentá la dificultad saltando más alto.', 170248),
  ('SALTOS AL CAJÓN 180 GRADOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Empezá parado frente a un cajón o escalón. Saltá hacia adelante sobre el cajón y después volvé a saltar rotando el cuerpo 180 grados mientras bajás del cajón. Seguí con este patrón alternando los lados.', 154814),
  ('SALTO ADELANTE Y ATRÁS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Saltá hacia adelante con las dos piernas. Caé en el piso con las dos piernas. Saltá hacia atrás con las dos piernas. Caé en el piso con las dos piernas. Repetí.', 82558),
  ('SALTO LATERAL', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Parado derecho, flexioná levemente las rodillas y saltá lateralmente hacia un costado.', 82552),
  ('SALTOS PLIOMÉTRICOS AL CAJÓN DE 90 GRADOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Empezá parado frente a un cajón o escalón. Saltá hacia adelante sobre el cajón mientras rotás el cuerpo 90 grados. Recuperá el equilibrio y después saltá al piso del otro lado del cajón rotando otros 90 grados, como se muestra. Seguí con este patrón alternando los lados.', 154817),
  ('SALTOS PLIOMÉTRICOS SOBRE BANCO - NIVEL 1', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Sosteniéndote de la punta de un banco de ejercicios o una silla, saltá de lado a lado.', 154786),
  ('SALTOS PLIOMÉTRICOS SOBRE BANCO - NIVEL 2', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Sosteniéndote del medio de un banco de ejercicios, saltá de lado a lado por encima del banco.', 154787),
  ('SALTOS PLIOMÉTRICOS ADELANTE AL CAJÓN - RÁPIDOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Empezá parado unos centímetros delante de un cajón o escalón. Saltá rápido hacia adelante sobre el cajón y después saltá rápido hacia atrás a la posición inicial y repetí.', 154812),
  ('SALTOS PLIOMÉTRICOS ADELANTE AL CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Empezá parado frente a un cajón o escalón. Saltá hacia adelante sobre el cajón, recuperá el equilibrio y después saltá hacia atrás bajando del cajón a la posición inicial. Repetí.', 154813),
  ('SALTOS PLIOMÉTRICOS LATERALES AL CAJÓN - RÁPIDOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Empezá parado al costado de un cajón o escalón. Saltá rápido de costado sobre el cajón y después saltá al piso del mismo lado. Repetí.', 154877),
  ('SALTOS PLIOMÉTRICOS LATERALES AL CAJÓN - RÁPIDOS - ALTERNADOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Empezá parado al costado de un cajón o escalón. Saltá de costado sobre el cajón. Después, saltá rápido al piso del lado opuesto del cajón, como se muestra. Seguí con este patrón alternando los lados.', 154878),
  ('SALTOS PLIOMÉTRICOS LATERALES AL CAJÓN', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Empezá parado al costado de un cajón o escalón. Saltá de costado sobre el cajón, recuperá el equilibrio y después saltá al piso del mismo lado. Repetí.', 154876),
  ('SALTOS PLIOMÉTRICOS LATERALES AL CAJÓN - ALTERNADOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Empezá parado al costado de un cajón o escalón. Saltá de costado sobre el cajón. Recuperá el equilibrio y después saltá al piso del lado opuesto del cajón, como se muestra. Seguí con este patrón alternando los lados.', 154875),
  ('SALTO LATERAL A UNA PIERNA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Pliometría', 'Saltá en dirección lateral usando una sola pierna. Caé en el piso con la misma pierna. Repetí.', 82556),
  ('ESTIRAMIENTO DE ADUCTORES CON CINTA MULTIANILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba y colocá una cinta de estiramiento en el pie. Tirá de la cinta para ayudarte a elevar la pierna hacia arriba y hacia el costado, buscando un estiramiento en los músculos de la cara interna del muslo.', 38881),
  ('ESTIRAMIENTO DE ADUCTORES CON CINTA MULTIANILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba y colocá una cinta de estiramiento en el pie. Envolvela alrededor del tobillo hacia la cara interna de la rodilla. Después, tirá de la cinta para sostener la pierna despegada del piso y dejá que se mueva hacia el costado, buscando un estiramiento en la cara interna del muslo. Mantené la pierna que trabajás estirada o apenas flexionada todo el tiempo.', 47190),
  ('ESTIRAMIENTO ASISTIDO CON DESLIZAMIENTO DE TALÓN - PARED', NULL, true, 'activo_asistido', 'Cadera y rodilla', 'Estiramientos', 'Acostate en el piso y apoyá los talones contra una pared. Cruzá las piernas con la pierna afectada abajo. Empezá deslizando el pie hacia abajo por la pared para estirar la rodilla que trabajás. Usá la pierna sana para ayudar con el estiramiento. Mantené, volvé a la posición inicial y repetí.', 165248),
  ('ESTIRAMIENTO DE MARIPOSA', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Sentado, flexioná las rodillas y juntá las plantas de los pies. Después, dejá caer lentamente las rodillas hacia el piso hasta sentir un estiramiento en la cara interna de los muslos.', 101),
  ('ESTIRAMIENTO DE MARIPOSA - DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba con las rodillas flexionadas y juntá las plantas de los pies. Después, bajá las rodillas hacia los costados buscando un estiramiento en la cara interna de los muslos.', 22539),
  ('ESTIRAMIENTO CRUZADO DE ISQUIOTIBIALES - SENTADO LARGO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá sentado con las piernas extendidas, con una rodilla flexionada y la otra pierna estirada, como se muestra. Después, inclinate y llevá la mano hacia adelante por fuera de la pierna estirada hasta sentir un estiramiento suave en los isquiotibiales. Mantené, volvé a la posición inicial y repetí.', 160557),
  ('ESTIRAMIENTO DINÁMICO DE GLÚTEOS', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Mientras caminás, elevá una rodilla flexionándola y agarrala con ambos brazos mientras la llevás hacia el pecho, buscando un estiramiento en la cola. Alterná al otro lado mientras seguís con el patrón de marcha.', 46746),
  ('ESTIRAMIENTO DINÁMICO DE ISQUIOTIBIALES', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Mientras caminás con los brazos extendidos hacia adelante, elevá una pierna manteniendo la rodilla estirada. Alterná al otro lado mientras seguís con el patrón de marcha.', 46747),
  ('ESTIRAMIENTO FABER - ESTIRAMIENTO EN 4', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba y cruzá las piernas flexionando la rodilla de modo que el tobillo quede apoyado sobre la otra pierna, por encima de la rótula. Relajá la pierna de arriba y dejá que la gravedad estire la cadera. Si hace falta, podés aplicar un poco de sobrepresión con la mano para lograr un estiramiento más profundo.', 81674),
  ('GERIÁTRICO - ESTIRAMIENTO SENTADO CON PIERNA CRUZADA - ESTIRAMIENTO DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentado en una silla, cruzá la pierna afectada de modo que el tobillo quede apoyado sobre la rodilla contraria, como se muestra. Puede que con eso ya sientas un estiramiento en la cadera. Si no, inclinate suavemente hacia adelante hasta sentir el estiramiento en la pierna de arriba. Mantené, después apoyá la pierna de nuevo en el piso y repetí.', 124250),
  ('GERIÁTRICO - ESTIRAMIENTO DE ISQUIOTIBIALES SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentate cerca del borde delantero de una silla. Apoyá el talón en el piso con la rodilla estirada e inclinate suavemente hacia adelante hasta sentir un estiramiento detrás de la rodilla y el muslo. Mantené la columna derecha todo el tiempo. Flexioná desde las caderas.', 124252),
  ('GERIÁTRICO - ESTIRAMIENTO DE ISQUIOTIBIALES SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentado, estirá la pierna que querés trabajar y después inclinate hacia adelante hasta sentir un estiramiento suave en la parte de atrás de la pierna. Enderezate para volver a la posición inicial y repetí.', 172278),
  ('ESTIRAMIENTO DE GLÚTEOS CON CINTA MULTIANILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba y colocá una cinta de estiramiento por detrás de la rodilla. Tirá de la cinta mientras elevás la rodilla para estirar los músculos del glúteo.', 38885),
  ('MEDIA RODILLA + COMBO DE ESTIRAMIENTO DE ISQUIOTIBIALES / ADUCTORES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición de estocada profunda con la rodilla de adelante flexionada y hacia el costado. En esa posición tenés que sentir un estiramiento en la cara interna del muslo de la pierna de atrás. Después, estirá la rodilla de adelante para estirar los isquiotibiales y la cara interna del muslo. Mantené, volvé a la posición inicial y repetí.', 161462),
  ('MEDIA RODILLA - COMBO DE ESTIRAMIENTO DE FLEXOR DE CADERA E ISQUIOTIBIALES', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición de estocada profunda estirando el flexor de cadera y mantené. Después, trasladá el peso del cuerpo hacia atrás y llevá los brazos hacia adelante mientras estirás la pierna de adelante hasta sentir un estiramiento en los isquiotibiales. Mantené, volvé a la posición inicial y repetí.', 160565),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES Y COLUMNA - SENTADO CON PIERNAS EXTENDIDAS', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá sentado en el piso con las rodillas estiradas. Después, llevá las manos hacia adelante y tratá de agarrarte los dedos de los pies para estirar los isquiotibiales y la espalda. Si no llegás a los dedos, agarrate de las piernas. Mantené, volvé a la posición inicial y repetí.', 160179),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES - SENTADO CON PIERNAS EXTENDIDAS', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentado con la pierna extendida, llevá las manos hacia adelante tratando de tocarte los dedos del pie.', 271),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES - DECÚBITO DORSAL', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Acostado en el piso, agarrá la parte de atrás de la rodilla y el muslo y estirá la rodilla hasta sentir un estiramiento en la parte de atrás de la pierna.', 5099),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES - PARED', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba y apoyá la pierna sobre una pared. La otra pierna debe quedar estirada en la rodilla y apoyada en el piso, atravesando el vano de la puerta o el pasillo. Mantené, después bajá al piso la pierna que estaba en la pared, relajá y repetí.', 117),
  ('ESTIRAMIENTO CON DESLIZAMIENTO DE TALÓN - PARED', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostado boca arriba con las dos piernas apoyadas sobre una pared o una puerta cerrada, flexioná lentamente la rodilla afectada de modo que el talón se deslice hacia abajo, para un estiramiento suave. Después volvé activamente a la posición original. Para reducir el roce contra la puerta, podés usar medias.', 121),
  ('DESLIZAMIENTOS DE TALÓN - AUTOASISTIDOS', NULL, true, 'activo_asistido', 'Cadera y rodilla', 'Estiramientos', 'Sentado, deslizá el talón hacia la cola con la ayuda de la pierna sana.', 120),
  ('DESLIZAMIENTOS DE TALÓN - MUSLO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición sentada con medias puestas o colocando una toalla chica debajo del talón. Después, pasá un cinto, una toalla o una sábana alrededor del muslo y tirá para flexionar la rodilla mientras el pie se desliza hacia la cola. Mantené un estiramiento suave y después volvé con la pierna a la posición original.', 82666),
  ('DESLIZAMIENTOS DE TALÓN - TOALLA EN EL MUSLO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá acostado boca arriba con las rodillas estiradas y una toalla enrollada por detrás de la rodilla afectada. Deslizá el talón afectado hacia la cola mientras flexionás la rodilla. Después, volvé a la posición inicial y repetí.', 164280),
  ('ESTIRAMIENTO DE ADUCTORES Y ROTACIÓN INTERNA DE CADERA - CUATRO APOYOS', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá sobre los codos y las rodillas en posición de gateo, con las rodillas bien separadas y los pies girados hacia afuera, como se muestra. Después, bajá la cola hacia atrás y abajo manteniendo la columna lumbar plana, hasta sentir un estiramiento suave en los rotadores internos de cadera y los aductores. Mantené, volvé a la posición inicial y repetí.', 156231),
  ('ESTIRAMIENTO DE ADUCTORES DE CADERA - DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición de pie con los pies bien separados. Después, flexioná lentamente la rodilla para permitir un estiramiento suave de la pierna contraria. Mantené la rodilla de la pierna que trabajás estirada todo el tiempo. Tenés que sentir un estiramiento en la cara interna del muslo.', 7154),
  ('ESTIRAMIENTO DE ROTACIÓN EXTERNA DE CADERA - CUATRO APOYOS', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición arrodillada con las rodillas bien separadas y los pies juntos. Apoyá las manos adelante tuyo y empujá hacia atrás mientras te sentás sobre los talones. Volvé a la posición inicial y repetí.', 159166),
  ('ESTIRAMIENTO DE ROTACIÓN EXTERNA DE CADERA - SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentado en una silla, cruzá la pierna con el tobillo de un pie sobre la rodilla del otro. Después, empujá la rodilla de arriba hacia abajo para estirar.', 23250),
  ('ESTIRAMIENTO DE FLEXOR DE CADERA / ADUCTORES - MEDIA RODILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá arrodillado sobre una rodilla (la pierna que querés trabajar). Inclinate hacia adelante y flexioná la rodilla de adelante hasta sentir un estiramiento en la parte de adelante de la cadera de esa pierna. Volvé a la posición inicial y después llevá la pierna contraria hacia el costado. Inclinate hacia ese lado mientras flexionás la rodilla de arriba para estirar la cara interna del muslo de la pierna que trabajás. Volvé a la posición inicial y repetí.', 159614),
  ('ESTIRAMIENTO DE FLEXOR DE CADERA / CUÁDRICEPS CON CINTA - ESTIRAMIENTO DE THOMAS', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Colocá una cinta o un cinto alrededor del pie, como se muestra. Pasá la otra punta del cinto por encima del hombro. Si usás un cinto, quizás necesites unir 2 para tener más largo. Acostado sobre una camilla o una cama alta, dejá que la pierna afectada baje hacia el piso. Después, tirá suavemente de la cinta para flexionar la rodilla hasta sentir un estiramiento en la parte de arriba del muslo.', 21671),
  ('ESTIRAMIENTO DE FLEXOR DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostado sobre una camilla o una cama alta, dejá que la pierna afectada baje hacia el piso hasta sentir un estiramiento en la parte de adelante del muslo.', 402),
  ('ESTIRAMIENTO DE FLEXOR DE CADERA - RECTO ANTERIOR', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá arrodillado sobre una rodilla y con el otro pie apoyado en el piso. Apoyá el pie de atrás sobre una silla, un sillón o un cajón, como se muestra. La rodilla de abajo puede apoyarse sobre una toalla doblada o una almohadilla blanda para mayor comodidad. Después, trasladá el cuerpo hacia adelante manteniendo la espalda derecha, hasta sentir un estiramiento suave en la parte de adelante de la cadera. Volvé a la posición inicial y repetí.', 165026),
  ('ESTIRAMIENTO DE FLEXOR DE CADERA - PIE SOBRE SILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'De pie, apoyá el pie sobre una silla, como se muestra. Después, flexioná la rodilla para estirar la parte de adelante del muslo de la pierna que está en el piso.', 23249),
  ('ESTIRAMIENTO DE FLEXOR DE CADERA 2', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Acostado sobre una camilla o una cama alta, dejá que la pierna afectada baje hacia el piso hasta sentir un estiramiento en la parte de adelante del muslo. Al mismo tiempo, agarrá la rodilla contraria y llevala hacia el pecho.', 404),
  ('ESTIRAMIENTO DE FLEXOR DE CADERA 3', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostado sobre una camilla o una cama alta, dejá que la pierna afectada baje hacia el piso hasta sentir un estiramiento en la parte de adelante del muslo. Flexioná lentamente la rodilla del lado afectado para aumentar el estiramiento.', 405),
  ('ESTIRAMIENTO DE FLEXOR DE CADERA 4', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Acostado sobre una camilla o una cama alta, dejá que la pierna afectada baje hacia el piso hasta sentir un estiramiento en la parte de adelante del muslo. Flexioná lentamente la rodilla afectada y agarrá la rodilla contraria para llevarla hacia el pecho y aumentar el estiramiento.', 406),
  ('ESTIRAMIENTO DE FLEXOR DE CADERA CON CINTA MULTIANILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Ponete en posición de media rodilla y colocá una cinta en el pie de atrás. Tirá de la cinta de modo que eleve la pierna de atrás para estirar la parte de adelante del muslo. Si te duele la rodilla de abajo con este ejercicio, colocá una almohada o un almohadón debajo como apoyo.', 38891),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA DE CADERA - SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá sentado en una silla con las piernas separadas y los pies apoyados en el piso. Después, usá la mano para llevar la rodilla hacia adentro, como se muestra.', 5883),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA DE CADERA - CUATRO APOYOS', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Estiramientos', 'Empezá en cuatro apoyos, sobre las manos y las rodillas, con los pies bien separados, como se muestra. Después, bajá la cola hacia atrás y abajo hasta sentir un estiramiento suave en los rotadores internos de cadera. Mantené, volvé a la posición inicial y repetí.', 152517),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA DE CADERA - SENTADO NIVEL 1', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentado, colocá una pierna rotada en una dirección y la otra rotada en la dirección contraria, como se muestra. Esto ayuda a estirar los rotadores internos de la cadera de la pierna que tiene el pie ubicado al costado del cuerpo. Apoyá las manos por detrás para sostener el cuerpo en la versión más suave (nivel 1) de esta serie de estiramientos.', 152512),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA DE CADERA - SENTADO NIVEL 2', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentate en el piso y colocá una pierna rotada en una dirección y la otra rotada en la dirección contraria, como se muestra. Esto ayuda a estirar los rotadores internos de la cadera de la pierna que tiene el pie ubicado al costado o por detrás del cuerpo. Sentate erguido y apoyá una mano por delante de la zona de la ingle y la otra al lado de la cadera para sostener el cuerpo y sumar un estiramiento profundo (nivel 2).', 152514),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA DE CADERA - SENTADO NIVEL 3', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentate en el piso y colocá una pierna rotada en una dirección y la otra rotada en la dirección contraria, como se muestra. Esto ayuda a estirar los rotadores internos de la cadera de la pierna que tiene el pie ubicado al costado o por detrás del cuerpo. Apoyá las manos por delante de la rodilla que tiene la cadera en rotación externa (la rodilla cuyo pie queda adelante tuyo) para sostener el cuerpo y sumar la máxima fuerza de estiramiento (nivel 3).', 152513),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA DE CADERA - DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'En posición de pie, apoyá la pierna que querés trabajar sobre una silla, como se muestra. Después, girá el tronco y la pelvis hacia el lado de esa pierna hasta sentir un estiramiento suave en la cadera.', 5882),
  ('ESTIRAMIENTO DE ROTACIÓN INTERNA DE CADERA - DE PIE CON SILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Parate sobre una pierna frente a una silla con apoyabrazos. Apoyá el otro pie y la pierna sobre el asiento, con el pie contra el apoyabrazos, como se muestra. Con las manos en las caderas, rotá el cuerpo hacia el lado contrario para un estiramiento suave de los rotadores internos de cadera. Mantené, desrotá y repetí.', 152515),
  ('ESTIRAMIENTO EN ROTACIÓN INTERNA DE CADERA - ADUCCIÓN EN DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba con las rodillas flexionadas y los pies bien separados. Después, dejá que las rodillas se junten hacia adentro para un estiramiento suave de los músculos rotadores internos de la cadera. Mantené, relajá y repetí.', 152516),
  ('ESTIRAMIENTO EN ROTACIÓN INTERNA DE CADERA - BALANCEO EN DECÚBITO DORSAL', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá acostado boca arriba con las rodillas flexionadas y los pies bien apoyados en el piso. Después, apoyá el pie/tobillo sobre la rodilla de la pierna que querés trabajar. Luego, rotá las rodillas y la pelvis hacia el lado contrario a esa pierna, como se muestra, hasta sentir un estiramiento suave en la cadera de la pierna que tiene el pie en contacto con el piso. Mantené, volvé a la posición inicial y repetí.', 152518),
  ('ESTIRAMIENTO EN ROTACIÓN INTERNA DE CADERA CON CINTA MULTIANILLA - RI CON CINTA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba y colocá una cinta de estiramiento en el pie. Elevá la pierna hasta 90 grados de flexión de rodilla y cadera. Tirá de la cinta con una mano para ayudar a rotar la pierna hacia afuera, como se muestra. Apoyá la otra mano sobre la rodilla para ayudar a estabilizarla en el lugar.', 47191),
  ('ESTIRAMIENTO DE CADERA - RI, FLEXIÓN Y ADUCCIÓN - SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá sentado en una silla con una pierna cruzada, de modo que el tobillo de una pierna quede sobre el muslo de la otra. Después, tirá de la rodilla de arriba hacia arriba y hacia la línea media para un estiramiento suave de la cola y la cadera. Mantené, después volvé a la posición inicial y repetí.', 52889),
  ('ESTIRAMIENTO EN ROTACIÓN INTERNA DE CADERA CON RODILLAS FLEXIONADAS - RI', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba con las rodillas flexionadas y los pies apoyados en el piso. Colocá una mano por encima de la cabeza y rotá la rodilla del mismo lado hacia adentro, como se muestra. Mantené para un estiramiento suave, volvé a la posición inicial y repetí.', 165481),
  ('ESTIRAMIENTO DE LA BANDA ILIOTIBIAL - DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'En posición de pie, cruzá la pierna afectada por detrás de la pierna sana. Después, inclinate hacia adelante y hacia el lado sano mientras usás el brazo como apoyo para el equilibrio.', 4716),
  ('ESTIRAMIENTO DE LA BANDA ILIOTIBIAL CON CINTO', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Pasá un cinto alrededor del pie. Acostado boca arriba y con la pierna elevada por delante tuyo y la rodilla estirada, llevá la pierna cruzando la línea media para sentir un estiramiento suave en la cara externa del muslo.', 22424),
  ('ESTIRAMIENTO DE LA BANDA ILIOTIBIAL CON CINTA MULTIANILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Colocá una cinta alrededor del pie. Acostado boca arriba y con la pierna elevada por delante tuyo y la rodilla estirada, llevá la pierna cruzando la línea media para sentir un estiramiento suave en la cara externa del muslo.', 38900),
  ('ESTIRAMIENTO PRETZEL DE BANDA ILIOTIBIAL / GLÚTEO / PIRAMIDAL - SENTADO CON PIERNAS EXTENDIDAS', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentate con una rodilla estirada y la otra flexionada. Después, girá suavemente el cuerpo hacia el lado de la rodilla flexionada.', 141),
  ('ESTIRAMIENTO DE BANDA ILIOTIBIAL - PLANCHA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición de flexión de brazos. Después deslizá y extendé la pierna hacia arriba y cruzando por encima de la pierna contraria. Trasladá el cuerpo hacia el lado de la pierna extendida. Mantené, volvé a la posición inicial y repetí.', 159165),
  ('KETTLEBELL - ESTIRAMIENTO DE GLÚTEO/ADUCTOR ARRODILLADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Estiramientos', 'Arrodillate con una rodilla en el piso y el pie contrario apuntando hacia afuera del cuerpo. Mientras sostenés una kettlebell, inclinate hacia la rodilla de adelante hasta sentir un estiramiento suave en las piernas. Volvé a la posición inicial y repetí.', 168818),
  ('ESTIRAMIENTO DE EXTENSIÓN DE RODILLA POR GRAVEDAD - PIE ELEVADO', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Acostado o sentado con una toalla chica enrollada debajo del tobillo, relajá completamente la pierna. La rodilla tiene que ir bajando mientras dejás que la gravedad estire la rodilla hacia una posición más estirada.', 65125),
  ('ESTIRAMIENTO DE EXTENSIÓN DE RODILLA - ELEVADO', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Sentado, apoyá el pie sobre otra silla y dejá que la gravedad estire la rodilla hacia una posición más estirada.', 11205),
  ('ESTIRAMIENTO DE EXTENSIÓN DE RODILLA - ELEVADO Y CON PESO', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Sentado, apoyá el pie sobre otra silla y dejá que la gravedad estire la rodilla hacia una posición más estirada. Colocá un peso sobre la rodilla, como una mochila, una tobillera con peso u otro objeto, para aumentar el estiramiento.', 11204),
  ('ESTIRAMIENTO CON PESO EN EXTENSIÓN DE RODILLA - PIE ELEVADO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Estiramientos', 'Acostado o sentado con una toalla chica enrollada debajo del tobillo, relajá completamente la pierna. Colocá una tobillera con peso sobre la rodilla. La rodilla tiene que ir bajando mientras dejás que el peso estire la rodilla hacia una posición más estirada.', 149051),
  ('ESTIRAMIENTO CON CAÍDA DE RODILLA - FABER MODIFICADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostado boca arriba con una rodilla flexionada, bajá lentamente la rodilla hacia el costado mientras estirás la zona interna del muslo y la cadera.', 133),
  ('FLEXIÓN DE RODILLA - AUTOASISTIDA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostado boca arriba con las rodillas estiradas, deslizá el talón afectado hacia la cola mientras flexionás la rodilla. Usá la pierna sana para ayudar en la flexión. Mantené un estiramiento suave en esta posición y después volvé a la posición original.', 132),
  ('ESTIRAMIENTO DE ADUCTORES DE CADERA ARRODILLADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Arrodillate sobre la rodilla del lado que querés trabajar. Colocá la otra pierna derecho hacia el costado. Después, inclinate hacia ese lado mientras flexionás la rodilla de arriba, para un estiramiento de la cara interna del muslo de la pierna que trabajás.', 11055),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES EN ESTOCADA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición de media rodilla, como se muestra. Después, apoyá las yemas de los dedos en el piso cerca del pie de adelante. Luego, estirá ambas rodillas para un estiramiento suave del isquiotibial de la pierna de adelante.', 119353),
  ('ESTIRAMIENTO DE PIRAMIDAL MODIFICADO - CON AYUDA DE SILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá sentado erguido con un pie sobre una superficie elevada, como un banquito o una silla. Dejá que la rodilla se flexione y caiga hacia el costado, como se muestra. Después, inclinate hacia adelante y llevá la mano más allá de la pierna elevada, y mantené para un estiramiento profundo de la cadera y la cola.', 177014),
  ('ESTIRAMIENTO DE LA PALOMA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición de flexión de brazos. Después deslizá la pierna hacia arriba y por debajo de la pierna contraria, como se muestra. Sostenete erguido con los brazos manteniendo la espalda derecha hasta sentir un estiramiento suave en la cadera. Mantené y repetí.', 159164),
  ('ESTIRAMIENTO DE LA PALOMA - CON BRAZO ARRIBA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición de flexión de brazos. Después deslizá la pierna hacia arriba y por debajo de la pierna contraria, como se muestra. Sostenete erguido con un brazo mientras elevás el otro por encima de la cabeza, manteniendo la espalda derecha hasta sentir un estiramiento suave en la cadera. Mantené y repetí.', 159163),
  ('ESTIRAMIENTO DE PIRAMIDAL - MODIFICADO 2', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostado boca arriba, agarrate la rodilla con una mano y el tobillo con la otra. Tirá de la pierna hacia arriba y cruzando hacia el hombro contrario, como se muestra.', 22420),
  ('ESTIRAMIENTO DE PIRAMIDAL CON CINTA MULTIANILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba y colocá una cinta de estiramiento en el pie. Tirá de la cinta para ayudar a elevar la pierna, para un estiramiento de la zona profunda de la cola. La rodilla y la cadera tienen que estar flexionadas, con rotación externa de cadera, como se muestra. Mantené la pierna que trabajás estirada o apenas flexionada todo el tiempo.', 47192),
  ('EMBARAZO - ESTIRAMIENTO DE LA PALOMA HACIA ATRÁS', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición de estiramiento de la paloma. Inclinate hacia atrás para sostenerte erguido con los brazos, manteniendo la espalda derecha hasta sentir un estiramiento suave en la cadera. Mantené y repetí.', 180899),
  ('EMBARAZO - ESTIRAMIENTO DE LA PALOMA HACIA ADELANTE', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición de estiramiento de la paloma. Inclinate hacia adelante usando los brazos para mantener la espalda derecha hasta sentir un estiramiento suave en la cadera. Asegurate de separar bien las rodillas para hacer lugar a la panza. Mantené, volvé a la posición inicial y repetí.', 180900),
  ('EMBARAZO - ESTIRAMIENTO DE CADERA EN SENTADILLA', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Estiramientos', 'Parate con los pies separados y frente a algo que te sirva de apoyo, como una silla o una mesa. Hacé sentadilla y flexioná las rodillas para bajar la cola hacia el piso. El peso del cuerpo tiene que permitir un estiramiento profundo de las caderas y la pelvis. Mantené, volvé a pararte y repetí. Asegurate de tener los pies bien separados para dejar lugar a la panza durante la sentadilla.', 181346),
  ('EMBARAZO - SENTADO EN V - ESTIRAMIENTO COMBINADO DE TRONCO LATERAL, DORSAL E ISQUIOTIBIALES/ADUCTORES', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentate en el piso con las piernas estiradas y separadas, como se muestra. Elevá un brazo por encima de la cabeza mientras te inclinás hacia el costado y deslizás la otra mano por la pierna hacia la que te inclinás. Mantené para un estiramiento suave de los isquiotibiales, aductores, espalda y músculo dorsal ancho. Mantené, relajá y hacelo del otro lado.', 181342),
  ('ESTIRAMIENTO PRETZEL', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentate en el piso con ambas rodillas flexionadas y después apoyá un pie por encima de la rodilla contraria, como se muestra. Después, girá suavemente el cuerpo hacia el otro lado.', 161461),
  ('ESTIRAMIENTO FABER EN DECÚBITO VENTRAL - FIGURA 4', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca abajo y flexioná la rodilla de modo que el pie de esa pierna quede apoyado sobre la cara interna de la otra rodilla, como se muestra.', 81660),
  ('ESTIRAMIENTO DE FLEXORES DE CADERA EN DECÚBITO VENTRAL - CODOS', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate en una camilla o cama con una pierna colgando por el costado. Después, sostenete sobre los codos. Tenés que sentir un estiramiento en la parte de adelante de la cadera y el muslo de la pierna que está sobre la camilla o la cama.', 39427),
  ('ESTIRAMIENTO DE FLEXORES DE CADERA EN DECÚBITO VENTRAL - MANOS', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate en una camilla o cama con una pierna colgando por el costado. Después, sostenete sobre las manos. Tenés que sentir un estiramiento en la parte de adelante de la cadera y el muslo de la pierna que está sobre la camilla o la cama.', 39426),
  ('ESTIRAMIENTO EN FLEXIÓN DE RODILLA EN DECÚBITO VENTRAL CON CINTA/CINTO - PIE FIJADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá acostado boca abajo con una cinta o 2 cintos unidos pasados alrededor del pie del lado afectado. Después, usá el cinto para llevar la rodilla a la posición flexionada permitiendo un estiramiento, como se muestra.', 34151),
  ('RODILLA COLGANDO EN DECÚBITO VENTRAL', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Acostado boca abajo, dejá que la pierna cuelgue por el borde de una camilla o cama. Ubicate de modo que la rótula quede justo por fuera del borde de la camilla o cama. Simplemente relajá el cuerpo y dejá que la gravedad estire la rodilla hacia una posición más estirada. Agregá una tobillera con peso para aumentar el estiramiento.', 147),
  ('RODILLA COLGANDO EN DECÚBITO VENTRAL APOYADA SOBRE TOALLA', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca abajo y dejá que la pierna cuelgue por el borde de una camilla o cama. Ubicate de modo que la rótula quede sobre una toalla doblada, justo por fuera del borde de la camilla o cama. Simplemente relajá el cuerpo y dejá que la gravedad estire la rodilla hacia una posición más estirada. Agregá una tobillera con peso para aumentar el estiramiento.', 86360),
  ('ESTIRAMIENTO DE CUÁDRICEPS EN DECÚBITO VENTRAL CON CINTO O CINTA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá acostado boca abajo con una cinta o 2 cintos unidos pasados alrededor del tobillo del lado afectado. Después, usá el cinto para llevar la rodilla a una posición flexionada, permitiendo el estiramiento, como se muestra.', 7161),
  ('ESTIRAMIENTO DE CUÁDRICEPS EN DECÚBITO VENTRAL CON CINTA MULTIANILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá acostado boca abajo con una cinta de estiramiento pasada alrededor del pie del lado afectado. Después, usá la cinta para llevar la rodilla a una posición flexionada, permitiendo el estiramiento, como se muestra.', 38947),
  ('ACTIVACIÓN DE CUÁDRICEPS - ESTIRAMIENTO EN EXTENSIÓN DE RODILLA - SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentado, contraé el músculo del muslo para presionar la parte de atrás de la rodilla hacia abajo, contra el piso. Tenés que sentir un estiramiento suave detrás de la rodilla.', 4670),
  ('ESTIRAMIENTO DE CUÁDRICEPS - DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'En posición de pie, flexioná la rodilla hacia atrás y agarrate el tobillo o el pie. Después, tirá suavemente de la rodilla hacia una posición más flexionada hasta sentir un estiramiento en la parte de adelante del muslo.', 150),
  ('ESTIRAMIENTO DE CUÁDRICEPS 2 - DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'En posición de pie, flexioná la rodilla hacia atrás y agarrate el empeine del pie. Después, tirá suavemente de la rodilla hacia una posición más flexionada hasta sentir un estiramiento en la parte de adelante del muslo.', 104665),
  ('ESTIRAMIENTO DE CUÁDRICEPS - DECÚBITO LATERAL', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Acostate de costado con la pierna que querés trabajar arriba. Después, agarrá esa pierna por debajo de la rodilla y tirá de la rodilla hacia una posición más flexionada hasta sentir un estiramiento a lo largo de la parte de adelante del muslo.', 286),
  ('ESTIRAMIENTO EN FLEXIÓN DE RODILLA Y CADERA - CUATRO APOYOS', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'En posición de gateo, flexioná suavemente las rodillas y llevá la cola hacia los pies. Mantené, volvé a la posición inicial y repetí.', 5103),
  ('ESTIRAMIENTO DE PIRAMIDAL CON BALANCEO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba con ambas rodillas flexionadas. Después, apoyá el tobillo de una pierna sobre el muslo de la otra. Después, dejá que la pierna se mueva lentamente hacia el costado hasta sentir un estiramiento suave en la pierna de arriba. El estiramiento se puede sentir en la parte de atrás de las piernas, en los glúteos o en la espalda.', 53528),
  ('ESTIRAMIENTO EN FLEXIÓN DE RODILLA SENTADO CON DESPLAZAMIENTO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'En posición sentada, deslizá el pie hacia atrás hasta flexionar la rodilla. Mantené el pie apoyado en el piso y desplazate hacia adelante hasta sentir un estiramiento en la rodilla.', 465),
  ('ESTIRAMIENTO DE PIRAMIDAL SENTADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sentado en una silla, cruzá la pierna y apoyá el tobillo de un pie sobre la rodilla de la otra pierna. Después, tirá de la rodilla de arriba hacia el hombro contrario para un estiramiento suave.', 23251),
  ('DECÚBITO LATERAL - ESTIRAMIENTO - BANDA ILIOTIBIAL', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá acostado de costado con la espalda cerca del borde de la cama o la camilla. La pierna afectada tiene que estar arriba. Después, dejá que la pierna de arriba baje hacia atrás manteniendo la rodilla extendida, como se muestra. Tenés que sentir un estiramiento suave a lo largo del costado de la pierna.', 7159),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES EN DECÚBITO LATERAL CON CINTA MULTIANILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate de costado y colocá una cinta de estiramiento en el pie. Tirá de la cinta para ayudarte a elevar la pierna, para un estiramiento en la parte de atrás del muslo y la rodilla. Mantené la pierna que trabajás estirada o apenas flexionada todo el tiempo.', 47194),
  ('PRETZEL LATERAL', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá acostado de costado y agarrate el empeine del pie de la pierna de abajo. Después, agarrá por detrás de la rodilla de la pierna de arriba y tirá de ella hacia arriba y cruzando el cuerpo. Mantené esta posición mientras rotás la columna tratando de tocar el piso con el omóplato. Mantené, volvé a la posición inicial y repetí.', 156232),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES DE PIE - 2', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá parado con un pie adelante y el talón apoyado en el piso. Después, inclinate lentamente hacia adelante y llevá las manos hacia el pie de adelante hasta sentir un estiramiento en los isquiotibiales. Flexioná desde las caderas y no desde la columna. Mantené, después volvé a la posición inicial y repetí.', 160558),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES DE PIE - MESADA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Parate frente a una mesada con puertas de alacena bajas. Apoyá el talón del pie dentro de una alacena abierta. Después, inclinate lentamente hacia adelante hasta sentir un estiramiento detrás de la rodilla y el muslo. Flexioná desde las caderas y no desde la columna. Mantené, después volvé a la posición inicial y repetí.', 164836),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES DE PIE - CON APOYO', NULL, true, 'fortalecimiento', 'Cadera y rodilla', 'Estiramientos', 'Empezá parado y apoyá el pie de la pierna afectada sobre una silla o un escalón. Después, inclinate lentamente hacia adelante hasta sentir un estiramiento detrás de la rodilla y el muslo. Flexioná desde las caderas y no desde la columna. Mantené, después volvé a la posición inicial y repetí.', 46071),
  ('ESTIRAMIENTO DE FLEXOR DE CADERA DE PIE - RODILLA EN LA SILLA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'De pie, apoyá la rodilla sobre una silla, como se muestra. Después, flexioná la rodilla de la pierna de apoyo para estirar la parte de adelante del muslo de la pierna que está sobre la silla.', 23248),
  ('ESTIRAMIENTO DE BANDA ILIOTIBIAL DE PIE CON INCLINACIÓN LATERAL DE TRONCO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'En posición de pie, cruzá la pierna afectada por detrás de la pierna sana. Después, con el brazo por encima de la cabeza, inclinate hacia el costado, en dirección a la pierna sana.', 24199),
  ('ESTIRAMIENTO DE PIRAMIDAL DE PIE', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Apoyá la pierna sobre una mesa, como se muestra. Si no sentís el estiramiento en el glúteo, podés inclinarte hacia adelante para aumentarlo.', 22427),
  ('ESTIRAMIENTO DE GLÚTEO EN DECÚBITO DORSAL CON CINTO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostate boca arriba y usá una cinta o dos cintos unidos. Sostené las puntas de la cinta o el cinto pasándolos alrededor del pie. Usá la cinta para ayudarte a elevar la pierna mientras dejás que la rodilla se flexione. Llevá la rodilla hacia el pecho y mantené para un estiramiento en el glúteo. Mantené esta posición y después volvé a la posición inicial. Repetí.', 34149),
  ('DESLIZAMIENTOS DE TALÓN EN DECÚBITO DORSAL - ESTIRAMIENTO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostado boca arriba, colocá un cinto, una toalla, una cinta o una sábana alrededor del pie y empezá tirando con los brazos para flexionar la rodilla hasta sentir un estiramiento suave, y mantené esta posición. Después dejá que la rodilla se estire de nuevo hasta la posición inicial y repetí.', 66921),
  ('ESTIRAMIENTO EN ROTACIÓN EXTERNA DE CADERA EN DECÚBITO DORSAL - FABER O FIGURA 4 MODIFICADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Acostado boca arriba con la pierna cruzada sobre la rodilla, usá la mano y empujá la rodilla cruzada alejándola de vos, como se muestra.', 22422),
  ('ESTIRAMIENTO DE TKE - CINTO', NULL, true, 'pasivo', 'Cadera y rodilla', 'Estiramientos', 'Empezá sentado con las piernas estiradas y un cinto o una sábana pasados alrededor del pie. Estabilizá el muslo con una mano y, con la otra, tirá del cinto o la sábana para llevar la rodilla a una posición más estirada. Tenés que sentir un estiramiento detrás de la rodilla.', 22538),
  ('SUSPENSIÓN TRX - ESTIRAMIENTO DE BANDA ILIOTIBIAL', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Parate de modo que el anclaje del TRX quede del lado contrario a la pierna que querés estirar. Colocá un pie adelante del otro mientras te inclinás lateralmente hasta sentir un estiramiento a lo largo del costado de la pierna (la pierna de atrás es la que trabajás).', 32698),
  ('SUSPENSIÓN TRX - ESTIRAMIENTO DE DORSAL - ESTIRAMIENTO DE FLEXOR DE CADERA', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Sostené las manijas del TRX de espaldas al anclaje. Empezá en posición arrodillada de modo que la cadera que querés estirar sea la de la rodilla que está abajo. Elevá el brazo del lado de la rodilla de abajo. Inclinate hacia el lado contrario a esa rodilla para estirar el dorsal. Inclinate hacia adelante flexionando la rodilla de adelante para conseguir un estiramiento del flexor de cadera del lado de la rodilla de abajo.', 31495),
  ('EL MEJOR ESTIRAMIENTO DEL MUNDO (WGS) - CODO - MODIFICADO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición arrodillada y después dá un paso adelante con una pierna. Apoyá la mano contraria en el piso y estirá la pierna de atrás de modo que la rodilla ya no toque el piso. Bajá con el otro brazo (el del mismo lado que la pierna de adelante) y tratá de llevar el codo al piso. Si no llegás al piso, acercate todo lo que toleres. Después, rotá el tronco hacia el costado y elevá el brazo hacia el techo. Girá la cabeza siguiendo la mano. Volvé a llevar el codo hacia el piso y repetí.', 129119),
  ('EL MEJOR ESTIRAMIENTO DEL MUNDO (WGS) - ANTEBRAZO', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición arrodillada y después dá un paso adelante con una pierna. Apoyá la mano contraria en el piso y estirá la pierna de atrás de modo que la rodilla ya no toque el piso. Apoyá el antebrazo del otro lado (el del mismo lado que la pierna de adelante) en el piso. Después, rotá el tronco hacia el costado y elevá el brazo hacia el techo. Girá la cabeza siguiendo la mano. Volvé a apoyar el antebrazo en el piso y repetí.', 129120),
  ('EL MEJOR ESTIRAMIENTO DEL MUNDO (WGS) - ALCANCE', NULL, true, 'activo', 'Cadera y rodilla', 'Estiramientos', 'Empezá en posición arrodillada y después dá un paso adelante con una pierna. Apoyá la mano contraria en el piso y estirá la pierna de atrás de modo que la rodilla ya no toque el piso. Deslizá el otro brazo (el del mismo lado que la pierna de adelante) por debajo y cruzando el cuerpo, como se muestra. Después, rotá el tronco hacia el costado y elevá el brazo hacia el techo. Girá la cabeza siguiendo la mano. Volvé a pasar el brazo por debajo y cruzando el cuerpo, y repetí.', 129121),
  ('ROM DEL 2DO AL 5TO DEDO DEL PIE', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Colocá un dedo de la mano sobre cada dedo del pie (del 2do al 5to). Usá los dedos de la mano para flexionar y estirar los dedos del pie repetidamente.', 175091),
  ('ROM EN FLEXIÓN DEL 2DO DEDO DEL PIE', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Empezá agarrando el segundo dedo del pie y usá los dedos de la mano para flexionarlo en cada una de sus articulaciones. Volvé a la posición inicial y repetí.', 175268),
  ('FLEXIÓN DEL 3ER DEDO DEL PIE - PROM', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Empezá agarrando la punta del tercer dedo del pie (el dedo del medio) y usá los dedos de la mano para flexionarlo. Después, estiralo y repetí.', 175798),
  ('ROM EN FLEXIÓN DEL 4TO DEDO DEL PIE', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Empezá agarrando el cuarto dedo del pie y usá los dedos de la mano para flexionarlo en cada una de sus articulaciones. Volvé a la posición inicial y repetí.', 175272),
  ('ROM EN FLEXIÓN DEL 5TO DEDO DEL PIE', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Empezá agarrando el cuarto dedo del pie y usá los dedos de la mano para flexionarlo en cada una de sus articulaciones. Volvé a la posición inicial y repetí.', 175725),
  ('ISOMÉTRICO DE INVERSIÓN DE TOBILLO BILATERAL', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado con ambos talones en el piso, presioná el antepié y los dedos de los dos pies uno contra el otro. Presioná, mantené, relajá y repetí.', 59378),
  ('BOMBEOS DE TOBILLO - SENTADO', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentado con los pies en el piso, presioná los dedos contra el piso de modo que los talones se despeguen. Después, relajá para que los talones bajen y luego despegá los dedos del piso mientras presionás los talones contra el piso. Alterná y repetí.', 93281),
  ('ELEVACIÓN DEL ARCO PLANTAR', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Empezá con el pie apoyado en el piso. Elevá el arco del pie manteniendo el dedo gordo, la base de los dedos y el talón en contacto con el piso todo el tiempo.', 11041),
  ('CÍRCULOS ASISTIDOS DE TOBILLO - SENTADO', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentado, apoyá un pie sobre el muslo contrario. Usá la mano para ayudar suavemente al pie a rotar en círculo. Hacé varias vueltas y después hacelo en la dirección contraria. Repetí alternando las rotaciones.', 177248),
  ('DORSIFLEXIÓN ASISTIDA', NULL, true, 'activo_asistido', 'Tobillo y pie', NULL, 'Sentate en una silla con los pies cerca uno del otro. Flexioná el tobillo hacia arriba y abajo manteniendo el talón en el piso. Usá el pie sano para ayudar a levantar.', 162071),
  ('AUTOMASAJE CON PELOTA - FASCIA PLANTAR', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado, colocá una pelota chica debajo del arco del pie y presioná contra ella mientras la hacés rodar. Usá esta técnica de automasaje de tejidos blandos para el arco del pie.', 3),
  ('ADUCCIÓN DEL DEDO GORDO - PROM', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Empezá agarrando el dedo gordo y usá los dedos de la mano para alejarlo de los otros dedos; después volvé a la posición inicial y repetí.', 176555),
  ('ESTIRAMIENTO DEL DEDO GORDO Y LA FASCIA PLANTAR', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentado, apoyá el tobillo afectado sobre la otra pierna. Después agarrá los dedos del pie y llevalos hacia atrás, en extensión, como se muestra. Mantené para un estiramiento suave de los dedos y la planta del pie (fascia plantar).', 94329),
  ('FLEXIÓN DEL DEDO GORDO - PROM', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Agarrá la punta del dedo gordo y flexionalo, después estiralo. Repetí.', 176556),
  ('BOMBEO DE PANTORRILLA CON PELOTA - AUTOMASAJE', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en el piso y colocá una pelota chica, como una de tenis o de golf, debajo de la pantorrilla. Después, flexioná el tobillo hacia arriba y abajo.', 11044),
  ('RODADO DE PANTORRILLA CON PELOTA - AUTOMASAJE', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en el piso y colocá una pelota chica, como una de tenis o de golf, debajo de la pantorrilla. Después, movés el cuerpo sobre la pelota para que ruede hacia arriba y abajo por la pantorrilla, logrando un masaje profundo de tejidos.', 11043),
  ('ESTIRAMIENTO DE PANTORRILLA / PROM', NULL, true, 'pasivo', 'Tobillo y pie', NULL, 'La persona tiene que estar completamente relajada mientras el cuidador hace todo el trabajo (rango de movimiento pasivo) para mover la pierna y el pie. Sostené el talón de la persona y flexioná el tobillo hacia atrás. Tu antebrazo tiene que estar alineado con el pie del paciente para hacer mejor palanca. Volvé el tobillo a la posición inicial y repetí.', 27173),
  ('ESTIRAMIENTO DE PANTORRILLA EN EL ESCALÓN - GEMELOS', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Empezá parado en un escalón con el talón que querés trabajar fuera del borde. Después, bajá el talón hacia el piso hasta sentir un estiramiento suave en la parte de atrás de la pierna. Los dedos de ambos pies deben apuntar derecho hacia adelante. Mantené la rodilla estirada durante el estiramiento.', 66924),
  ('ESTIRAMIENTO DE PANTORRILLA CON TOALLA', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Colocá una toalla doblada en el piso y pisala con la parte de adelante del pie que querés trabajar. Mantené el talón en el piso. Dá un paso adelante con el otro pie manteniendo los dedos de ambos pies hacia adelante, hasta sentir un estiramiento suave en la parte de atrás de la pierna. Mantené la rodilla estirada durante el estiramiento. Controlá la intensidad flexionando la rodilla de adelante o ajustando el largo del paso.', 60879),
  ('ESTIRAMIENTO DE PANTORRILLA CON TOALLA - SÓLEO', NULL, true, 'pasivo', 'Tobillo y pie', NULL, 'Sentado, colocá una toalla alrededor de la base de los dedos del pie y tirá del tobillo hacia atrás hasta sentir un estiramiento en la zona de la pantorrilla. Mantené la rodilla flexionada durante el estiramiento.', 94333),
  ('CLX - EVERSIÓN - TOBILLO ARRIBA Y AFUERA', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado, colocá los pies en dos anillas consecutivas de la CLX. Después, elevá un pie y llevalo hacia el costado. Repetí moviéndolo de lado a lado mientras lo mantenés despegado del piso. Minimizá el movimiento de rodilla y cadera apoyando una mano sobre la rodilla como referencia.', 40093),
  ('CLX - INVERSIÓN', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado, colocá una anilla en el pie y después cruzá las piernas, como se muestra. Con la otra pierna, pisá la banda CLX y sostené la otra punta. Movés el pie hacia arriba y abajo.', 40589),
  ('CLX - FLEXIÓN PLANTAR', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado, sujetá una anilla de la CLX al pie y sostené la otra punta. Movés el pie hacia adelante y atrás desde el tobillo, como se muestra. Asegurate de mantener el talón en contacto con el piso todo el tiempo.', 40590),
  ('ISOMÉTRICO DE DORSIFLEXIÓN', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Apoyá la mano sobre la parte de arriba del pie y mantené mientras intentás levantar el pie contra la mano.', 9469),
  ('ISOMÉTRICO DE DORSIFLEXIÓN - PIE CONTRARIO', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado con el talón del pie que trabajás en el piso, elevá el antepié y los dedos y presioná la parte de arriba de ese pie contra la planta del otro pie, y mantené esta posición. El pie de abajo tiene que intentar subir mientras el de arriba frena el movimiento. Si hace falta, poné una toalla chica doblada entre los pies para mayor comodidad. Presioná, mantené, relajá y repetí.', 59340),
  ('DORSIFLEXIÓN CON BANDA ELÁSTICA - SENTADO', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado, usá una banda elástica sujeta al pie y tirá del pie hacia arriba. Asegurate de mantener el talón en contacto con el piso todo el tiempo.', 7),
  ('DORSIFLEXIÓN CON BANDA ELÁSTICA - DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Podés hacer esto acostado boca arriba en el piso. Fijá una punta de la banda elástica en una puerta (hacé un nudo en la banda y cerrá la puerta de modo que el nudo quede del otro lado). Correte hacia atrás hasta que la banda tenga tensión. Cuando haya tensión, movés el tobillo de modo que los dedos y el pie se tiren hacia atrás y arriba, apuntando al techo. Volvé a la posición inicial y repetí.', 51109),
  ('DORSIFLEXIÓN CON BANDA ELÁSTICA 2 - SENTADO', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Con una banda elástica sujeta al pie que trabajás, pasala por debajo del otro pie y hacia arriba, hasta la mano. Después, tirá de la banda hacia arriba con el pie que trabajás, como se muestra. Asegurate de mantener el talón en contacto con el piso todo el tiempo.', 9459),
  ('EVERSIÓN CON BANDA ELÁSTICA - DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Empezá acostado boca arriba y colocá una anilla de la banda elástica alrededor del pie que trabajás. Sujetá la banda con el otro pie y sostené la otra punta con la mano. Después, movés el tobillo de modo que los dedos y el pie vayan hacia el costado, alejándose de la línea media. Volvé a la posición inicial y repetí.', 51108),
  ('INVERSIÓN CON BANDA ELÁSTICA - SENTADO', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado, cruzá las piernas y, con una banda elástica sujeta al pie, pasala por debajo del otro pie y hacia arriba, hasta la mano. Después, llevá el pie hacia adentro. Asegurate de mantener el talón en contacto con el piso todo el tiempo.', 10),
  ('INVERSIÓN CON BANDA ELÁSTICA - SENTADO', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado, usá una banda elástica sujeta al pie y llevá el pie hacia adentro. Asegurate de mantener el talón en contacto con el piso todo el tiempo.', 11),
  ('INVERSIÓN CON BANDA ELÁSTICA - DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Empezá acostado boca arriba y colocá una anilla de la banda elástica alrededor del pie que trabajás. Después, cruzá las piernas de modo que la pierna que trabajás quede abajo y parte de la banda quede sujeta por el pie de arriba. Sostené la otra punta con la mano. Después, movés el tobillo de modo que los dedos y el pie vayan hacia adentro, hacia la línea media. Volvé a la posición inicial y repetí.', 51110),
  ('FLEXIÓN PLANTAR CON BANDA ELÁSTICA - DECÚBITO DORSAL', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Podés hacer esto acostado boca arriba en el piso. Sostené una punta de la banda elástica con la mano y colocá la anilla alrededor del pie que trabajás. Después, sostené la banda y tirá para generar algo de tensión. Luego movés el tobillo y el pie hacia adelante, en flexión plantar. Es el mismo movimiento que hacés al pisar el acelerador de un auto. Volvé a la posición inicial y repetí.', 51111),
  ('VENDAJE ELÁSTICO - TENDINITIS AQUILEANA', NULL, true, 'sin_clasificar', 'Tobillo y pie', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75013),
  ('VENDAJE ELÁSTICO - ESGUINCE DE TOBILLO', NULL, true, 'sin_clasificar', 'Tobillo y pie', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73837),
  ('VENDAJE ELÁSTICO - SOPORTE DE TOBILLO', NULL, true, 'sin_clasificar', 'Tobillo y pie', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 74043),
  ('VENDAJE ELÁSTICO - PERIOSTITIS TIBIAL ANTERIOR', NULL, true, 'sin_clasificar', 'Tobillo y pie', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 73827),
  ('VENDAJE ELÁSTICO - APLICACIÓN EN PANTORRILLA', NULL, true, 'sin_clasificar', 'Tobillo y pie', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75005),
  ('VENDAJE ELÁSTICO - FASCITIS PLANTAR', NULL, true, 'sin_clasificar', 'Tobillo y pie', NULL, 'Aplicá la cinta según las indicaciones de tu profesional de rehabilitación.', 75014),
  ('AAROM DE EVERSIÓN', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentado, cruzá las piernas de modo que la pierna afectada quede arriba. Después, usá la mano para ayudar al tobillo a moverse hacia abajo (eversión) y a volver a subir de forma controlada. Repetí.', 166984),
  ('ISOMÉTRICO DE EVERSIÓN', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Apoyá la mano sobre la cara externa del pie y mantené mientras intentás presionar el pie contra la mano.', 9468),
  ('ISOMÉTRICO DE EVERSIÓN - PARED - PATA DE MESA', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado con el talón del pie que trabajás en el piso, movés el tobillo hacia el costado y presionalo contra la pata de una mesa o contra una pared. Mantené la presión con el pie. Presioná, mantené, relajá y repetí.', 59341),
  ('ESTIRAMIENTO EN EVERSIÓN', NULL, true, 'pasivo', 'Tobillo y pie', NULL, 'Sentado, cruzá las piernas de modo que la pierna afectada quede arriba. Después, agarrá el pie y empujalo hacia abajo hasta sentir un estiramiento en la cara interna del tobillo.', 161),
  ('PELOTA DE EJERCICIOS - ELEVACIÓN DE TALONES - PESO LIBRE', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentate sobre una pelota de ejercicios con pesos libres apoyados sobre los muslos, como se muestra. Manteniendo el equilibrio y una buena postura sobre la pelota, presioná los dedos del pie contra el piso mientras despegás los talones. Bajá los talones y repetí.', 174647),
  ('PROM DE PIE - PRONACIÓN Y SUPINACIÓN', NULL, true, 'pasivo', 'Tobillo y pie', NULL, 'La persona tiene que estar completamente relajada mientras el cuidador hace todo el trabajo (rango de movimiento pasivo) para mover el pie. Agarrá el pie de la persona. Estabilizá la mitad de abajo y rotá la porción de arriba pivoteando sobre el arco del pie, como se muestra. Rotá en cada dirección y repetí.', 27185),
  ('RODADO CON BOTELLA CONGELADA - FASCIA PLANTAR', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Apoyá el pie sobre una botella de agua congelada de plástico. Rodá la botella desde la parte de adelante de la planta hasta el talón, siguiendo el arco.', 72304),
  ('ESTIRAMIENTO EN EXTENSIÓN DEL DEDO GORDO', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentado, cruzá las piernas de modo que la pierna afectada quede arriba. Después, llevá el dedo gordo hacia atrás con los dedos de la mano hasta sentir un estiramiento en el dedo o en la planta del pie.', 13),
  ('ESTIRAMIENTO EN FLEXIÓN DEL DEDO GORDO', NULL, true, 'pasivo', 'Tobillo y pie', NULL, 'Agarrá la punta del dedo gordo y flexionalo para estirarlo, como se muestra. Estabilizá el pie con la otra mano.', 11054),
  ('ELEVACIÓN DE TALONES Y PUNTAS - DE PIE', NULL, true, 'activo', 'Tobillo y pie', NULL, 'De pie, elevate sobre las puntas de los pies despegando los talones del piso, bajá y después elevá los dedos y la parte de adelante del pie. Bajá y repetí.', 107669),
  ('ELEVACIÓN DE TALONES - GEMELOS - ESCALÓN - BILATERAL', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Parado en el borde de un escalón con los talones fuera del borde de atrás, elevate sobre las puntas de los pies mientras subís los talones y el cuerpo, como se muestra.', 23243),
  ('AAROM DE INVERSIÓN', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentado, cruzá las piernas de modo que la pierna afectada quede arriba. Después, usá la mano para ayudar al tobillo a moverse hacia arriba (inversión) y a bajar de nuevo con un movimiento controlado. Repetí.', 166985),
  ('ISOMÉTRICO DE INVERSIÓN', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Apoyá la mano sobre la cara interna del pie y mantené mientras intentás llevar el pie contra la mano.', 9467),
  ('ISOMÉTRICO BILATERAL DE INVERSIÓN - PELOTA', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Colocá una pelota entre los pies, como se muestra. Después, aplicá presión sobre la pelota con la parte de adelante e interna de los pies y mantené.', 8517),
  ('ISOMÉTRICO BILATERAL DE INVERSIÓN - TOALLA', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sentado con ambos talones en el piso, presioná entre sí la parte de adelante y los dedos de los dos pies. Si te resulta más cómodo, usá una toalla entre los pies. Presioná, mantené, relajá y repetí.', 59397),
  ('ESTIRAMIENTO EN INVERSIÓN', NULL, true, 'pasivo', 'Tobillo y pie', NULL, 'Sentado, cruzá las piernas de modo que la pierna afectada quede arriba. Después, agarrá el pie y tirá hacia arriba hasta sentir un estiramiento en el costado del tobillo.', 16),
  ('ISOMÉTRICO BILATERAL DE INVERSIÓN - PELOTA', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Colocá una pelota entre los dos pies, como se muestra. Presioná los pies uno contra otro contra la pelota. Mantené, relajá y repetí.', 67060),
  ('ISOMÉTRICO DE DORSIFLEXIÓN - PELOTA', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Colocá una pelota sobre el pie que vas a trabajar y sostenela en su lugar con la planta del otro pie, como se muestra. Tirá del pie que trabajás hacia arriba flexionando el tobillo y presionalo contra la pelota mientras el otro pie la mantiene en su lugar. Mantené, relajá y repetí.', 67057),
  ('ISOMÉTRICO DE EVERSIÓN - PELOTA', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Colocá una pelota contra una pared y sostenela ahí con la cara externa del pie. Mantenela en su lugar con el pie mientras la presionás contra la pared. Mantené, relajá y repetí.', 67059),
  ('ISOMÉTRICO DE FLEXIÓN PLANTAR - PELOTA', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Colocá una pelota contra una pared y sostenela ahí con la parte de adelante de la planta del pie. Presioná la pelota contra la pared. Mantené, relajá y repetí.', 67062),
  ('LEVANTAR BOLITAS', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Colocá varias bolitas, dados u otros objetos chicos en el piso y levantalos con los dedos del pie, como se muestra. Ponelos en un vaso o bol y repetí.', 8518),
  ('FASCIA PLANTAR - MASAJE TRANSVERSO', NULL, true, 'sin_clasificar', 'Tobillo y pie', NULL, 'Aplicá presión con el pulgar y deslizalo de lado a lado por la planta del pie, como se muestra.', 94035),
  ('ESTIRAMIENTO DE FASCIA PLANTAR', NULL, true, 'pasivo', 'Tobillo y pie', NULL, 'Sentado, colocá una toalla debajo de la pierna, el pie y los dedos, como se muestra. Agarrá la otra punta de la toalla. Tirá suavemente de la toalla hasta sentir un estiramiento.', 94792),
  ('FLEXIÓN PLANTAR - AAROM', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Usá los músculos del tobillo para flexionarlo hacia adelante mientras los dedos de la mano ayudan el movimiento. Relajá, dejá que el tobillo vuelva a la posición de descanso y repetí.', 176558),
  ('ISOMÉTRICO DE FLEXIÓN PLANTAR', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Apoyá la mano sobre la planta del pie y mantené mientras intentás presionar el pie contra la mano.', 9470),
  ('MARCHA HACIA ATRÁS', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Caminá para atrás. Al dar los pasos hacia atrás, apoyá primero la punta del pie y después rodá hasta apoyar el pie plano, como se muestra.', 27188),
  ('MARCHA TÁNDEM HACIA ATRÁS', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Parate con un pie justo delante del otro, de modo que los dedos de un pie toquen el talón del otro. Después, rodá el pie desde la posición de punta hasta apoyarlo plano. Mantené el equilibrio mientras seguís dando pasos hacia atrás.', 27189),
  ('ESTIRAMIENTO DE PANTORRILLA SENTADO - SÓLEO', NULL, true, 'pasivo', 'Tobillo y pie', NULL, 'Sentado, usá una toalla u otra cinta enlazada alrededor del pie. Tirá suavemente del tobillo hacia atrás hasta sentir un estiramiento en la parte de atrás de la pierna. La rodilla tiene que estar levemente flexionada todo el tiempo.', 4674),
  ('AUTOMASAJE CON PELOTA - TIBIAL POSTERIOR', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentado, cruzá la pierna afectada sobre la otra pierna. Usá una pelota de lacrosse o de tenis/paleta y rodala por la cara interna de la pierna, por detrás del hueso (tibia). No pases la pelota sobre zonas óseas.', 99586),
  ('ESTIRAMIENTO DE PANTORRILLA CON CINTA MULTIANILLA', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentate en el piso con una rodilla flexionada y la pierna que vas a trabajar estirada. Después, colocá una cinta de estiramiento alrededor de ese pie, como se muestra. Después, tirá de la cinta para estirar el músculo de la pantorrilla.', 38948),
  ('ELEVACIÓN DE TALONES DE PIE - GEMELOS - BILATERAL', NULL, true, 'activo', 'Tobillo y pie', NULL, 'De pie, elevate sobre las puntas de los pies despegando los talones del piso.', 23244),
  ('FLEXIÓN DE DEDOS - BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Tobillo y pie', NULL, 'Sostené las dos puntas de una banda elástica y envolvela alrededor de la planta del pie y los dedos. Flexioná los dedos contra la resistencia de la banda. Relajá y repetí.', 69881),
  ('PROM DE DEDOS DEL PIE - FLEXIÓN Y EXTENSIÓN', NULL, true, 'pasivo', 'Tobillo y pie', NULL, 'La persona tiene que estar completamente relajada mientras el cuidador hace todo el trabajo (rango de movimiento pasivo) para mover los dedos del pie. Agarrá los dedos de la persona. Después, flexionalos y estiralos. Repetí.', 27187),
  ('DESLIZAMIENTOS CON TOALLA - EVERSIÓN', NULL, true, 'activo', 'Tobillo y pie', NULL, 'Sentado, usá una toalla y deslizala con el pie por el piso hacia afuera. Asegurate de mantener el talón en contacto con el piso todo el tiempo.', 2),
  ('EXTENSIÓN DEL 1ER RADIO - EXTENSIÓN DEL DEDO GORDO', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Con el pie completamente apoyado en el piso, elevá el 1er dedo (el dedo gordo) sin levantar ningún otro dedo. El talón, los dedos 2do al 5to y la base del dedo gordo tienen que mantener contacto con el piso todo el tiempo.', 48494),
  ('EXTENSIÓN DEL 2DO AL 5TO DEDO - EXTENSIÓN DE LOS DEDOS CHICOS', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Con el pie completamente apoyado en el piso, elevá los dedos del 2do al 5to sin levantar el 1ero (el dedo gordo). El talón y el dedo gordo tienen que mantener contacto con el piso todo el tiempo.', 48495),
  ('CÍRCULOS DE TOBILLO - CADENA CERRADA', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentate en una silla con ambos pies en el piso. Levantá el talón y rotá suavemente el tobillo en círculos manteniendo los dedos en el piso. Hacé algunas vueltas en una dirección y después en la dirección contraria. Repetí alternando las rotaciones.', 177273),
  ('CÍRCULOS DE TOBILLO - SENTADO', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentado, apoyá un pie sobre el muslo contrario. Rotá suavemente el pie en círculos. Hacé algunas vueltas en una dirección y después en la dirección contraria. Repetí alternando las rotaciones.', 177250),
  ('CÍRCULOS DE TOBILLO - SENTADO Y ELEVADO', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentate en una silla y usá los brazos para sostener el muslo y el tobillo despegados del piso. Manteniendo el pie elevado, rotá lentamente el tobillo en dirección circular. Hacé algunas vueltas y después hacelo en la dirección contraria. Repetí estas rotaciones alternadas.', 177249),
  ('BOMBEOS DE TOBILLO - ELEVADO', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Acostate y elevá la pierna apoyándola sobre 2 a 4 almohadas. Después, flexioná el pie hacia arriba y hacia abajo desde la articulación del tobillo, como se muestra.', 94788),
  ('ELEVACIONES DEL ARCO', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentate en una silla y apoyá el pie plano en el piso. Después, usá los músculos del pie y el tobillo para subir y bajar el arco. Puede costar bastante. Pensá en tratar de llevar el dedo gordo hacia el talón y después deslizarlo hacia adelante.', 94036),
  ('INVERSIÓN BILATERAL DE TOBILLO - ALMOHADA', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Colocá una almohada doblada entre los pies, como se muestra. Después, aplicá presión contra la almohada con la parte de adelante e interna de los pies y mantené. Relajá y repetí.', 48535),
  ('BOSU - CÍRCULOS DE TOBILLO', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'En posición de pie, apoyá el pie sobre un Bosu invertido y movés el tobillo en un patrón circular. Hacelo en sentido horario varias veces y después invertí a sentido antihorario y repetí.', 5576),
  ('BOSU - BOMBEOS DE TOBILLO', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'En posición de pie, apoyá el pie sobre una pelota Bosu invertida y flexioná el tobillo hacia adelante y atrás.', 5575),
  ('DORSIFLEXIÓN - DECÚBITO DORSAL', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Acostado boca arriba, flexioná el tobillo para mover el pie hacia arriba, en dirección a la rodilla, como se muestra. Relajá y repetí.', 48394),
  ('ELEVACIONES EXCÉNTRICAS DE TALÓN - ELEVACIÓN DE PANTORRILLAS', NULL, true, 'activo; fortalecimiento', 'Tobillo y pie', 'AROM (activo)', '(1) De pie, subí en puntas de pie (2) despegando los talones del piso. (3) Después, flexioná la pierna que no trabaja. Luego, (4) bajá el talón de nuevo.', 23246),
  ('EVERSIÓN', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentado, movés el pie hacia afuera, como se muestra. Mantené el talón en contacto con el piso todo el tiempo.', 6998),
  ('EVERSIÓN - DECÚBITO DORSAL', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Acostado boca arriba, flexioná el tobillo para mover el pie hacia afuera, alejándolo de la línea media, como se muestra. Relajá y repetí.', 48395),
  ('RODILLO DE ESPUMA - INVERSIÓN Y EVERSIÓN DE TOBILLO', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentado, apoyá el pie sobre medio rodillo de espuma y la mano sobre la rodilla, como se muestra. Flexioná el tobillo de lado a lado mientras hacés bascular el rodillo. No dejes que la rodilla se mueva de lado a lado. Solo el tobillo y el pie deben moverse.', 95130),
  ('RODILLO DE ESPUMA - FLEXIÓN PLANTAR Y DORSIFLEXIÓN DE TOBILLO', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentado, apoyá el pie sobre medio rodillo de espuma, como se muestra. Flexioná el tobillo hacia adelante y después hacia atrás mientras hacés bascular el rodillo.', 95132),
  ('GERIÁTRICO - ELEVACIÓN DE TALONES - PANTORRILLAS - BILATERAL', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentado en una silla, apoyá los pies en el piso. Después, presioná hacia abajo con el antepié y los dedos para despegar los talones del piso. Bajá los talones de nuevo y repetí. Mantené los dedos en el piso todo el tiempo.', 124253),
  ('GERIÁTRICO - ELEVACIÓN DE DEDOS - DORSIFLEXIÓN - BILATERAL', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentate en una silla con los pies apoyados en el piso. Después, elevá los dedos y el antepié de ambos lados mientras flexionás los tobillos. Mantené los talones en el piso todo el tiempo. Si te cuesta, deslizá los pies hacia adelante y probá de nuevo.', 124256),
  ('ELEVACIÓN DE TALÓN - PANTORRILLA - UNILATERAL', NULL, true, 'activo; fortalecimiento', 'Tobillo y pie', 'AROM (activo)', 'Empezá con todo el pie apoyado en el piso. Después, elevá el talón mientras presionás los dedos hacia abajo. Mantené los dedos en el piso todo el tiempo.', 11057),
  ('ELEVACIONES DE TALONES', NULL, true, 'activo; fortalecimiento', 'Tobillo y pie', 'AROM (activo)', 'Parate con los dedos apuntando derecho hacia adelante. Después, subí en puntas de pie despegando los talones del piso. Bajá lentamente y repetí.', 68188),
  ('INVERSIÓN', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentado, movés el pie hacia adentro. Mantené el talón en contacto con el piso todo el tiempo.', 6997),
  ('INVERSIÓN - DECÚBITO DORSAL', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Acostado boca arriba, flexioná el tobillo para mover el pie hacia adentro, en dirección a la línea media del cuerpo, como se muestra. Relajá y repetí.', 48396),
  ('FLEXIÓN PLANTAR - DECÚBITO DORSAL', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Acostado boca arriba, flexioná el tobillo para apuntar el pie hacia adelante, como se muestra. Relajá y repetí.', 48397),
  ('INVERSIÓN DE TOBILLO SENTADO', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentado con ambos pies en el piso, flexioná los tobillos para elevar la parte interna de los pies manteniendo el borde externo en el piso. Las rodillas deben quedar fijas en el lugar todo el tiempo.', 94794),
  ('EVERSIÓN EN DECÚBITO LATERAL', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Empezá acostado de costado con el tobillo que trabaja arriba. Tenés que estar acostado de modo que el pie y el tobillo queden fuera del borde de la cama o la camilla. Después, movés el tobillo y el pie hacia arriba, en dirección al techo, como se muestra.', 7164),
  ('INVERSIÓN EN DECÚBITO LATERAL', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Empezá acostado de costado con el tobillo que trabaja abajo. Tenés que estar acostado de modo que el pie y el tobillo queden fuera del borde de la cama o la camilla. Después, movés el tobillo y el pie hacia arriba, en dirección al techo, como se muestra.', 7169),
  ('SEPARACIÓN DE DEDOS - ABDUCCIÓN', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'En posición sentada, separá los dedos del pie hacia los costados, como se muestra. Relajá y repetí.', 94328),
  ('ELEVACIÓN DE DEDOS - DORSIFLEXIÓN ALTERNADA', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Empezá con el pie apoyado plano en el piso. Después, elevá el antepié y los dedos mientras flexionás el tobillo. Mantené los talones en el piso todo el tiempo. Volvé a la posición inicial, alterná los lados y repetí.', 165025),
  ('ELEVACIÓN DE DEDOS - DORSIFLEXIÓN - UNILATERAL', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Empezá con el pie apoyado plano en el piso. Después, elevá el antepié y los dedos mientras flexionás el tobillo. Mantené los talones en el piso todo el tiempo.', 11259),
  ('DESLIZAMIENTOS CON TOALLA - INVERSIÓN', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo)', 'Sentado, usá una toalla y deslizala con el pie por el piso hacia adentro. Mantené el talón en contacto con el piso todo el tiempo.', 28),
  ('ELEVACIÓN DEL ARCO - MONEDA Y LAPICERA - PALLOF PRESS - APOYO EN UNA PIERNA', NULL, true, 'activo; fortalecimiento', 'Tobillo y pie', 'AROM (activo); Banda elástica; Estabilización', 'Colocá una moneda debajo de la base del dedo gordo y apoyá la punta de una lapicera debajo del arco del pie. Sostené una banda elástica, cuerda o polea contra el pecho, fijada hacia el costado del cuerpo. Elevá el arco del pie de modo que la base del dedo gordo mantenga la presión sobre la moneda y el arco se despegue de la lapicera. Después, parate en una pierna con la rodilla levemente flexionada y extendé lentamente los brazos hacia adelante y después de vuelta al pecho. Repetí manteniendo el arco elevado por encima de la lapicera y la base del dedo gordo sobre la moneda.', 129630),
  ('ELEVACIÓN DEL ARCO - PELOTA EN LA PARED PARA GLÚTEO - APOYO EN UNA PIERNA', NULL, true, 'activo; fortalecimiento', 'Tobillo y pie', 'AROM (activo); Isométrico', 'Parate con el costado del cuerpo cerca de una pared. Parate en una pierna y colocá una pelota de ejercicios contra la pared, sosteniéndola con la rodilla del otro lado. Elevá el arco del pie de apoyo manteniendo la presión de la base del dedo gordo contra el piso.', 129632),
  ('FNP DE TOBILLO - DIAGONAL 1', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Varios', 'D1: Flexioná el tobillo llevando el pie hacia arriba y adentro mientras estirás los dedos. Después, flexioná el tobillo moviendo el pie en la dirección contraria, hacia abajo y afuera, mientras enroscás los dedos. Repetí este patrón de movimiento.', 123483),
  ('FNP DE TOBILLO - COMBINADO DIAGONAL 1 Y DIAGONAL 2', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Varios', 'D1: Flexioná el tobillo llevando el pie hacia arriba y adentro mientras estirás los dedos, después movelo en la dirección contraria, hacia abajo y afuera, mientras enroscás los dedos, como se ve en las imágenes de arriba. Hacelo unas cuantas veces y después hacé el ejercicio de abajo. D2: Flexioná el tobillo llevando el pie hacia arriba y afuera mientras estirás los dedos, después movelo en la dirección contraria, hacia abajo y adentro, mientras enroscás los dedos, como se ve en las imágenes de abajo.', 123481),
  ('FNP DE TOBILLO - DIAGONAL 2', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Varios', 'D2: Flexioná el tobillo llevando el pie hacia arriba y afuera mientras estirás los dedos. Después, flexioná el tobillo moviendo el pie en la dirección contraria, hacia abajo y adentro, mientras enroscás los dedos. Repetí este patrón de movimiento.', 123484),
  ('ELEVACIÓN DEL ARCO - MONEDA Y LAPICERA', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Varios; Estabilización', 'Colocá una moneda debajo de la base del dedo gordo y apoyá la punta de una lapicera debajo del arco del pie. Parate en tu posición normal y después elevá el arco de modo que la base del dedo gordo mantenga la presión sobre la moneda y el arco se despegue de la lapicera. Mantené, bajá y repetí.', 129629),
  ('ELEVACIÓN DEL ARCO - PIVOTES', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Varios; Estabilización', 'Sentate en una silla con ambos pies en el piso. Pivoteá los pies hacia adentro y hacia afuera sobre los talones, como se muestra. Al pivotear hacia adentro, asegurate de elevar el arco de los pies y mantené esa posición. Volvé a la posición inicial pivoteando los talones hacia afuera y repetí. Mantené la base del dedo gordo en el piso todo el tiempo: tiene que deslizarse por el piso mientras pivoteás.', 129631),
  ('ELEVACIONES EXCÉNTRICAS DE TALÓN - PANTORRILLAS - ESCALÓN - UNILATERAL', NULL, true, 'activo; fortalecimiento', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Parate con ambos pies en el borde de un escalón, de modo que los talones queden por fuera del borde, como se muestra. Presioná hacia abajo con los dedos mientras elevás los talones. Después, despegá del escalón el pie que no trabaja para quedar parado en una pierna. Luego, bajá el talón del pie que quedó en el escalón. Volvé a apoyar ambos pies en el borde del escalón y repetí.', 23247),
  ('ANDADOR - ELEVACIONES DE TALONES', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Parado con un andador, presioná hacia abajo con los dedos mientras elevás los talones y el cuerpo. Bajá y repetí.', 125296),
  ('ELEVACIÓN DE TALONES - PANTORRILLA - ESCALÓN - A UNA PIERNA', NULL, true, 'activo; fortalecimiento', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Parate en un escalón con una pierna, con el talón por fuera del borde de atrás del escalón. Después, elevate en puntas de pie mientras subís el talón y el cuerpo, como se muestra. Bajá y repetí.', 23245),
  ('ELEVACIÓN DE TALONES - ROTACIÓN EXTERNA', NULL, true, 'activo; fortalecimiento', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Parate con las puntas de los pies hacia afuera (caderas en rotación externa). Después, elevate en puntas de pie despegando los talones del piso. Bajá lentamente y repetí.', 68186),
  ('ELEVACIÓN DE TALONES - ROTACIÓN INTERNA', NULL, true, 'activo; fortalecimiento', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Parate con las puntas de los pies hacia adentro (caderas en rotación interna). Después, elevate en puntas de pie despegando los talones del piso. Bajá lentamente y repetí.', 68187),
  ('INVERSIÓN Y EVERSIÓN - DESLIZAMIENTOS CON FUNDA O TOALLA', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Parate con ambos pies sobre una toalla o una funda de almohada y después girá el pie hacia adentro y hacia afuera. Minimizá el movimiento de la rodilla y la cadera para que solo se muevan los tobillos. Parate cerca de algo de donde agarrarte para tener apoyo.', 94331),
  ('INVERSIÓN Y EVERSIÓN - DESLIZAMIENTOS CON FUNDA O TOALLA - DE PIE A UNA PIERNA', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Parate sobre una toalla o funda de almohada apoyado en una pierna y después girá el pie hacia adentro y hacia afuera. Minimizá el movimiento de la rodilla y la cadera para que solo se mueva el tobillo. Parate cerca de algo de donde agarrarte para tener apoyo.', 94330),
  ('ELEVACIÓN DE TALONES DE PIE - PANTORRILLA - UNILATERAL', NULL, true, 'activo; fortalecimiento', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Parado en una pierna, elevate en puntas de pie despegando el talón del piso.', 23252),
  ('FLEXIÓN Y EXTENSIÓN DE DEDOS DEL PIE', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Enrollá los dedos del pie hacia abajo y después hacia arriba, y repetí. Usá movimientos controlados.', 7007),
  ('SILLA DE RUEDAS - ELEVACIÓN DE TALONES', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Sentado en una silla de ruedas con los pies bien apoyados en el piso, empezá elevando los talones del piso mientras presionás los dedos contra el piso. Bajá los talones a la posición inicial y repetí. Mantené los dedos en el piso todo el tiempo.', 104774),
  ('SILLA DE RUEDAS - ELEVACIÓN DE TALONES Y PUNTAS', NULL, true, 'activo', 'Tobillo y pie', 'AROM (activo); Estabilización', 'Sentado en una silla de ruedas con los pies bien apoyados en el piso, empezá elevando los talones del piso mientras presionás los dedos contra el piso. Bajá los talones a la posición inicial y después elevá los dedos y el antepié. Alterná estos movimientos.', 104775),
  ('CLX - DORSIFLEXIÓN', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Banda elástica', 'Fijá una punta del CLX al pie que vas a trabajar, pasalo por debajo del otro pie y llevalo hasta la mano. Después, elevá el pie hacia arriba manteniendo el talón en el piso. Asegurate de mantener el talón en contacto con el piso todo el tiempo.', 40586),
  ('ELEVACIÓN DEL ARCO - BANDA ELÁSTICA', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Banda elástica; Estabilización', 'Pasá una banda elástica alrededor del pie, como se muestra, y fijala pisándola con el otro pie. Parate en tu postura normal y después elevá el arco manteniendo la planta del antepié en el piso. Bajá el arco del pie y repetí.', 129627),
  ('BANDA ELÁSTICA - FLEXIONES DE TOBILLO', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Banda elástica; Estabilización', 'Sentado, cruzá las piernas y apoyá un pie sobre el otro muslo. Colocá una banda elástica sobre cada pie, como se muestra. Empezá moviendo el tobillo de arriba hacia arriba. Bajá y repetí.', 169164),
  ('BANDA ELÁSTICA - CAMINATAS LATERALES EN EVERSIÓN', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Banda elástica; Estabilización', 'Colocá una banda elástica circular alrededor de la planta del antepié, como se muestra. Después, dá pasos hacia el costado manteniendo la tensión de la banda todo el tiempo, con los pies apuntando derecho hacia adelante. Después de dar pasos laterales en una dirección, invertí la dirección hasta volver a la posición inicial. Repetí.', 147447),
  ('BANDA ELÁSTICA - EVERSIÓN - SENTADO CON PIERNAS EXTENDIDAS', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Banda elástica; Estabilización', 'Sentate en el piso con las piernas extendidas, como se muestra. Colocá la punta con anilla de una banda elástica alrededor del pie que vas a trabajar. Sostené la otra punta con la mano contraria. Después, movés el tobillo de modo que los dedos y el pie vayan hacia afuera, alejándose de la línea media. Volvé a la posición inicial y repetí.', 147449)
INSERT INTO exercise_library (name, professional_id, is_active, exercise_type, catalog_region, catalog_subcategory, instructions, source_exercise_id)
VALUES
  ('ELEVACIÓN DE TALÓN - BANDA ELÁSTICA CON ÉNFASIS EN EL PRIMER RADIO', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Banda elástica; Estabilización', 'Colocá la punta de una banda elástica debajo de la base del dedo gordo. Sostené la otra punta con la mano. Equilibrate en una pierna y después elevate en puntas de pie despegando el talón del piso. Asegurate de distribuir suficiente peso sobre el primer dedo para que la banda quede fija debajo del pie. Agarrate de una silla o algo firme con la otra mano para tener apoyo. Bajá y repetí.', 147450),
  ('FLEXIÓN DE DEDOS - BANDA ELÁSTICA CIRCULAR', NULL, true, 'activo_asistido; fortalecimiento', 'Tobillo y pie', 'Banda elástica; Estabilización', 'Sentate en una silla y envolvé una banda elástica alrededor de la planta del pie sosteniendo ambas puntas, como se muestra. La banda tiene que mantener los dedos levantados del piso mientras el resto del pie queda en contacto con el piso. Después, enrollá los dedos hacia abajo contra la resistencia de la banda hasta que toquen el piso. Relajá y dejá que los dedos vuelvan a subir con la ayuda de la banda, y después repetí.', 123485),
  ('2DO AL 5TO DEDO DEL PIE - FLEXIÓN ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Isométrico', 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Usá los músculos del pie para flexionar los dedos y mantené esa posición. Después, colocá un dedo de la mano sobre cada dedo del pie (del 2do al 5to). Presioná suavemente con los dedos de la mano contra los dedos del pie. Usá los músculos de los dedos del pie para evitar cualquier movimiento. Mantené, relajá y repetí.', 175092),
  ('TOBILLO - DORSIFLEXIÓN ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Isométrico', 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Usá los músculos del tobillo para mover el pie hacia arriba, como se muestra. Presioná suavemente con los dedos de la mano contra el dorso del pie. Usá los músculos del tobillo para evitar cualquier movimiento. Mantené, relajá y repetí.', 175646),
  ('DEDO GORDO - ISOMÉTRICO', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Isométrico', 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Extendé el dedo gordo hacia arriba, como se muestra. Presioná suavemente con el dedo de la mano contra el dedo gordo mientras usás el músculo del dedo para evitar cualquier movimiento. Mantené, relajá y repetí.', 176788),
  ('EVERSIÓN ISOMÉTRICA BILATERAL - PIERNAS CRUZADAS', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Isométrico', 'Sentado con las piernas cruzadas, presioná los costados de los pies uno contra el otro y mantené, como se muestra. Presioná, mantené la contracción, relajá y repetí. Si te resulta más cómodo, usá una toalla entre los pies.', 59396),
  ('INVERSIÓN - ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Isométrico', 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Usá los músculos del tobillo para mover el pie hacia arriba, como se muestra. Presioná suavemente con los dedos de la mano contra el costado del pie. Usá los músculos del tobillo para evitar cualquier movimiento. Mantené, relajá y repetí.', 176554),
  ('FLEXIÓN PLANTAR - ISOMÉTRICA', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Isométrico', 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Presioná suavemente con los dedos de la mano contra la planta del pie. Usá los músculos del tobillo para evitar cualquier movimiento. Mantené, relajá y repetí.', 176557),
  ('RODADO DE FASCIA PLANTAR - RESALTADOR', NULL, true, 'activo', 'Tobillo y pie', 'Varios', 'Sentate en una silla o al borde de la cama y apoyá el pie sobre un marcador o resaltador grueso. La lapicera tiene que quedar alineada en forma horizontal, como se muestra. Deslizá el pie hacia adelante y atrás sobre el piso para que el marcador ruede contra la planta del pie y te haga un masaje suave. Si la lapicera no es lo bastante gruesa, podés enrollarle un repasador chico alrededor y sujetarlo con cinta o atarlo.', 94332),
  ('ELEVACIÓN DE PANTORRILLAS - BARRA', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Varios; Estabilización', 'Parate con la barra apoyada sobre los hombros por detrás de la cabeza. Colocá los pies separados aproximadamente al ancho de los hombros. Agarrá la barra un poco más abierto que el ancho de los hombros. Después, sacá la barra del soporte, dá un paso atrás y elevate en puntas de pie despegando los talones del piso. Bajá los talones al piso y repetí.', 154636),
  ('DORSIFLEXIÓN - KETTLEBELL', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Varios; Estabilización', 'Sentate en una superficie alta. Apoyá la kettlebell en el piso. Enganchá el pie en la manija de la kettlebell y levantala usando el pie y el tobillo, como se muestra. Bajá y repetí.', 95129),
  ('ELEVACIÓN DE PANTORRILLAS EN ELEVACIÓN - BARRA', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Varios; Estabilización', 'Parate con la barra apoyada sobre los hombros por detrás de la cabeza. Colocá los pies separados aproximadamente al ancho de los hombros. Agarrá la barra un poco más abierto que el ancho de los hombros. Después, sacá la barra del soporte, dá un paso atrás y apoyá el arco de los pies en el borde de una superficie elevada, con los talones sobresaliendo hacia el piso. Después, elevate en puntas de pie despegando los talones. Bajá los talones al piso y repetí.', 154658),
  ('DISCO DESLIZANTE - INVERSIÓN Y EVERSIÓN', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Varios; Estabilización', 'Sentate en una silla con el pie sobre un disco deslizante. Rotá el pie hacia adentro y después hacia afuera, como se muestra. Repetí. Mantené los dedos sobre el disco deslizante todo el tiempo.', 169519),
  ('PUENTE CON ELEVACIÓN DE TALONES', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estabilización', 'Acostado boca arriba con las rodillas flexionadas, activá los músculos abdominales bajos, apretá los glúteos y después elevá la cola del piso o la cama, formando un puente con el cuerpo. Después, elevate en puntas de pie haciendo una elevación de pantorrillas. Mantené, después bajá y repetí.', 157230),
  ('BANDA ELÁSTICA - EVERSIÓN 2 - SENTADO', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estabilización', 'Sentado, usá una banda elástica fijada al pie y llevá el pie hacia afuera, hacia el costado. Asegurate de mantener el talón en contacto con el piso todo el tiempo.', 9),
  ('GERIÁTRICO - ELEVACIÓN DE TALONES - DE PIE', NULL, true, 'activo', 'Tobillo y pie', 'Estabilización', 'Parado al lado de una silla o mesada para apoyarte, presioná con los dedos hacia abajo mientras elevás los talones y el cuerpo. Bajá y repetí.', 124571),
  ('GERIÁTRICO - ELEVACIÓN DE PUNTAS - DE PIE', NULL, true, 'activo', 'Tobillo y pie', 'Estabilización', 'Parado al lado de una silla o mesada para apoyarte, elevá los dedos y el antepié flexionando el tobillo. Bajá y repetí.', 124574),
  ('ELEVACIÓN DE TALÓN - PANTORRILLA - CON DESCARGA REDUCIDA', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estabilización', 'De pie, inclinate hacia la pierna sana y después elevate en puntas de pie despegando los talones del piso. Tiene que haber menos peso corporal del lado afectado mientras subís y bajás los talones.', 94034),
  ('ELEVACIÓN DE TALÓN - PANTORRILLA - APRETANDO UNA PELOTA SENTADO', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estabilización', 'Sentate en una silla y colocá una pelota entre los tobillos y las piernas, como se muestra. Sostené la pelota ahí con las piernas y después elevate en puntas de pie despegando los talones del piso. Bajá y repetí.', 94039),
  ('ELEVACIÓN DE TALÓN - PANTORRILLA - APRETANDO UNA PELOTA DE PIE', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estabilización', 'Colocá una pelota de tenis u otra pelota chica entre los tobillos y las piernas, como se muestra. Sostenela ahí con las piernas y después elevate en puntas de pie despegando los talones del piso. Bajá y repetí.', 94038),
  ('ELEVACIÓN DE TALONES - BARRA', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estabilización', 'Parate con la barra apoyada sobre los hombros por detrás de la cabeza. Colocá los pies separados aproximadamente al ancho de los hombros. Agarrá la barra un poco más abierto que el ancho de los hombros. Después, sacá la barra del soporte y dá un paso atrás. Después, elevate en puntas de pie despegando los talones del piso. Bajá los talones al piso y repetí.', 155500),
  ('CAMINATA SOBRE TALONES', NULL, true, 'activo', 'Tobillo y pie', 'Estabilización', 'Levantá los dedos de los pies y caminá sobre los talones. Dá unos pasos hacia adelante y después unos pasos hacia atrás.', 9465),
  ('ELEVACIONES DE TALONES DE PIE CON PESOS LIBRES - ELEVACIONES DE PANTORRILLA - BILATERAL', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estabilización', 'De pie y sosteniendo pesos libres, elevate en puntas de pie despegando los talones del piso. Bajá y repetí.', 95133),
  ('ELEVACIONES DE TALONES DE PIE CON PESOS LIBRES - ELEVACIONES DE PANTORRILLA - A UNA PIERNA', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estabilización', 'De pie y sosteniendo pesos libres, equilibrate sobre una pierna. Después, elevate en puntas de pie despegando el talón del piso. Bajá y repetí.', 95185),
  ('CAMINATA EN PUNTAS DE PIE', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estabilización', 'Levantá los talones y caminá en puntas de pie. Dá unos pasos hacia adelante y después unos pasos hacia atrás.', 9466),
  ('ESTIRAMIENTO DEL 2DO AL 5TO DEDO DEL PIE', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Colocá un dedo de la mano sobre cada dedo del pie (del 2do al 5to). Usá los dedos de la mano para flexionar los dedos del pie hacia abajo, para un estiramiento suave, como se muestra. Mantené, volvé a la posición inicial y repetí.', 175090),
  ('ESTIRAMIENTO EN FLEXIÓN DEL 2DO DEDO DEL PIE', NULL, true, 'pasivo', 'Tobillo y pie', 'Estiramientos', 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Empezá agarrando el segundo dedo del pie y usá los dedos de la mano para flexionarlo en cada una de sus articulaciones, manteniendo para un estiramiento suave. Mantené y después volvé a la posición inicial.', 175267),
  ('ESTIRAMIENTO EN FLEXIÓN DEL 3ER DEDO DEL PIE', NULL, true, 'pasivo', 'Tobillo y pie', 'Estiramientos', 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Empezá agarrando el tercer dedo del pie y usá los dedos de la mano para flexionarlo en cada una de sus articulaciones, manteniendo para un estiramiento suave. Mantené y después volvé a la posición inicial.', 175269),
  ('ESTIRAMIENTO EN FLEXIÓN DEL 4TO DEDO DEL PIE', NULL, true, 'pasivo', 'Tobillo y pie', 'Estiramientos', 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Empezá agarrando el cuarto dedo del pie y usá los dedos de la mano para flexionarlo en cada una de sus articulaciones, manteniendo para un estiramiento suave. Mantené y después volvé a la posición inicial.', 175271),
  ('ESTIRAMIENTO EN FLEXIÓN DEL 5TO DEDO DEL PIE', NULL, true, 'pasivo', 'Tobillo y pie', 'Estiramientos', 'Sentate en una silla y apoyá el tobillo sobre la rodilla contraria. Empezá agarrando el quinto dedo del pie y usá los dedos de la mano para flexionarlo en cada una de sus articulaciones, manteniendo para un estiramiento suave. Mantené y después volvé a la posición inicial.', 175724),
  ('ESTIRAMIENTO ACTIVO DE PANTORRILLA - SENTADO', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Sentado, mantené la rodilla estirada mientras llevás suavemente el tobillo hacia atrás hasta sentir un estiramiento a lo largo de la pantorrilla. Bajá el tobillo y repetí.', 170800),
  ('ELEVACIÓN DE TALÓN ASISTIDA - AAROM DE FLEXIÓN PLANTAR', NULL, true, 'activo_asistido; fortalecimiento', 'Tobillo y pie', 'Estiramientos', 'Empezá sentado con el pie bien apoyado en el piso. Después, usá los músculos de la pantorrilla y presioná los dedos contra el piso para elevar el talón. Usá la mano agarrando la pantorrilla o la pierna para ayudar en el movimiento de elevación. Bajá el pie y repetí. Mantené los dedos en el piso todo el tiempo.', 166250),
  ('ELEVACIÓN DE DEDOS ASISTIDA - AAROM DE DORSIFLEXIÓN', NULL, true, 'activo_asistido', 'Tobillo y pie', 'Estiramientos', 'Empezá sentado con el pie bien apoyado en el piso. Después, usá los músculos del tobillo y elevá los dedos despegándolos del piso. Usá la mano agarrando los dedos para ayudar en el movimiento de elevación. Bajá el pie y repetí. Mantené el talón en el piso todo el tiempo.', 166249),
  ('ESTIRAMIENTO BILATERAL DE PANTORRILLA CON CINTA MULTIANILLA', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Sentate en el piso y colocá una cinta de estiramiento alrededor de ambos pies, como se muestra. Después, tirá de la cinta hacia atrás para estirar los músculos de la pantorrilla.', 38883),
  ('ESTIRAMIENTO DE PANTORRILLA EN EL ESCALÓN - SÓLEO', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estiramientos', 'Empezá parado en un escalón con el talón que vas a trabajar por fuera del borde. Después, bajá el talón hacia el piso hasta sentir un estiramiento suave en la parte de atrás de la pierna. Los dedos de los dos pies deben apuntar derecho hacia adelante. Mantené la rodilla que trabajás flexionada durante este estiramiento.', 66925),
  ('ESTIRAMIENTO DE PANTORRILLA CON TOALLA - SÓLEO', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Colocá una toalla doblada en el piso y pisala con la parte de adelante del pie que vas a trabajar. Mantené el talón en el piso. Dá un paso adelante con el otro pie, con los dedos de ambos pies apuntando hacia adelante, hasta sentir un estiramiento suave en la parte de atrás de la pierna que trabajás. Mantené esa rodilla flexionada durante el estiramiento. Controlá la intensidad flexionando la rodilla de adelante o ajustando el tamaño del paso.', 60875),
  ('ESTIRAMIENTO EN DORSIFLEXIÓN - MEDIA RODILLA', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Arrodillado sobre una rodilla y con el otro pie apoyado en el piso, inclinate hacia adelante y flexioná la rodilla de adelante hasta sentir un estiramiento en la parte de adelante del tobillo del lado del pie apoyado.', 85291),
  ('ESTIRAMIENTO EN EVERSIÓN CON TOALLA', NULL, true, 'pasivo', 'Tobillo y pie', 'Estiramientos', 'Sentado, colocá una toalla alrededor de la planta del pie y sostené las puntas con las manos, como se muestra. Empezá tirando suavemente del lado que baja hacia los dedos chicos. Esto debe mover el pie hacia arriba de modo que los dedos chicos queden más altos que los dedos grandes. Mantené, volvé a la posición inicial y repetí.', 123477),
  ('ESTIRAMIENTO EN EVERSIÓN CON RODILLO DE ESPUMA', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Apoyá el pie sobre un medio rodillo de espuma, como se muestra, e inclina el rodillo hacia adentro hasta sentir un estiramiento en la parte interna del tobillo.', 9461),
  ('ESTIRAMIENTO EN INVERSIÓN CON RODILLO DE ESPUMA', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Apoyá el pie sobre un medio rodillo de espuma, como se muestra, e inclina el rodillo hacia afuera hasta sentir un estiramiento en la parte externa del tobillo.', 9462),
  ('DESLIZAMIENTO DEL PIE - ESTIRAMIENTO EN DORSIFLEXIÓN', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Sentado y con el pie adelante apoyado en el piso, deslizá lentamente el pie acercándolo hacia vos. Mantené hasta sentir un estiramiento suave en el tobillo y después llevá el pie de vuelta hacia adelante, a la posición original. Repetí.', 70017),
  ('ESTIRAMIENTO EN ABDUCCIÓN DEL DEDO GORDO', NULL, true, 'pasivo', 'Tobillo y pie', 'Estiramientos', 'Agarrá el dedo gordo del pie y tiralo hacia el costado para un estiramiento. Estabilizá el pie con la otra mano.', 11053),
  ('ESTIRAMIENTO EN EXTENSIÓN DEL DEDO GORDO', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Sentado, envolvé el dedo gordo del pie con una sábana, una funda de almohada o una toalla y sostené las puntas con las manos. Después, tirá hacia abajo y hacia vos hasta sentir un estiramiento en el dedo o en la planta del pie.', 94787),
  ('ESTIRAMIENTO EN INVERSIÓN CON TOALLA', NULL, true, 'pasivo', 'Tobillo y pie', 'Estiramientos', 'Sentado, colocá una toalla alrededor de la planta del pie y sostené las puntas con las manos, como se muestra. Empezá tirando suavemente del lado que baja hacia el dedo gordo. Esto debe mover el pie hacia arriba de modo que el dedo gordo quede más alto que los dedos chicos. Mantené, volvé a la posición inicial y repetí.', 123478),
  ('ESTIRAMIENTO EN EXTENSIÓN MTF - EN EL PISO', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'De pie, apoyá los dedos del pie en el piso de modo que queden flexionados hacia arriba. Después, presioná hacia abajo hasta sentir un estiramiento en los dedos o en la planta del pie.', 17),
  ('ESTIRAMIENTO EN EXTENSIÓN MTF - EN LA PARED', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'De pie, apoyá los dedos del pie contra una pared de modo que queden llevados hacia atrás, para un estiramiento suave. Mantené el talón en el piso durante el estiramiento.', 164835),
  ('ESTIRAMIENTO EN FLEXIÓN PLANTAR - SENTADO SOBRE LOS TALONES', NULL, true, 'fortalecimiento', 'Tobillo y pie', 'Estiramientos', 'Empezá en posición arrodillada y después bajá la cola para sentarte sobre los talones. Dejá que esta posición estire los tobillos en posición de punta de pie.', 95131),
  ('ESTIRAMIENTO EN FLEXIÓN PLANTAR', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Sentate y apoyá el pie afectado sobre una superficie firme. Usá una mano para flexionar el tobillo hacia abajo, como se muestra, para un estiramiento suave en la parte de adelante del tobillo.', 48534),
  ('ESTIRAMIENTO DE PANTORRILLA SENTADO - SÓLEO - CINTA MULTIANILLA', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Sentado, usá una cinta de estiramiento pasada alrededor del pie. Tirá suavemente del tobillo hacia atrás hasta sentir un estiramiento en la parte de atrás de la pierna. La rodilla debe estar levemente flexionada todo el tiempo.', 149057),
  ('ESTIRAMIENTO SENTADO EN EXTENSIÓN MTF', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Sentado, apoyá el pie en el piso y presioná con la parte anterior del pie para elevar el talón del piso, dejando que los dedos se estiren.', 94793),
  ('ESTIRAMIENTO DE PANTORRILLA DE PIE - GEMELO EXTERNO', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Empezá parado frente a una pared u otro objeto firme. Dá un paso adelante con un pie manteniendo los dedos de la pierna de adelante apuntando derecho hacia adelante. Apuntá los dedos de la pierna de atrás hacia afuera, alejándolos de la línea media. Mantené la pierna de atrás con la rodilla estirada durante el estiramiento. Inclinate hacia la pared y sostenete con los brazos mientras dejás que la rodilla de adelante se flexione, hasta sentir un estiramiento suave en la parte de atrás de la pierna que quedó más atrás. Acercate o alejate de la pared para controlar el estiramiento. También podés ajustar la flexión de la rodilla de adelante para regularlo.', 48392),
  ('ESTIRAMIENTO DE PANTORRILLA DE PIE - GEMELO INTERNO', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'Empezá parado frente a una pared u otro objeto firme. Dá un paso adelante con un pie manteniendo los dedos de la pierna de adelante apuntando derecho hacia adelante. Apuntá los dedos de la pierna de atrás hacia adentro, hacia la línea media. Mantené la pierna de atrás con la rodilla estirada durante el estiramiento. Inclinate hacia la pared y sostenete con los brazos mientras dejás que la rodilla de adelante se flexione, hasta sentir un estiramiento suave en la parte de atrás de la pierna que quedó más atrás. Acercate o alejate de la pared para controlar el estiramiento. También podés ajustar la flexión de la rodilla de adelante para regularlo.', 48393),
  ('ESTIRAMIENTO DE FLEXIÓN PLANTAR DE PIE', NULL, true, 'activo', 'Tobillo y pie', 'Estiramientos', 'De pie, colocá uno de los pies por detrás tuyo de modo que la parte de arriba de los dedos quede apoyada en el piso. Después, flexioná la pierna de apoyo hasta sentir un estiramiento en la parte de arriba del pie afectado. Agarrate de algo estable para sostenerte.', 94795),
  ('GIRO DE CABEZA Y DEGLUCIÓN', NULL, true, 'activo', 'Motricidad oral', NULL, 'Girá la cabeza hacia un lado y tragá. Después, repetí del otro lado.', 145405),
  ('APERTURA MANDIBULAR CONTRA RESISTENCIA - TOALLA', NULL, true, 'fortalecimiento', 'Motricidad oral', NULL, 'Colocá una toalla chica enrollada debajo del mentón. Abrí la mandíbula contra la resistencia de la toalla. Mantené, relajá y repetí.', 145859),
  ('BESO SONORO', NULL, true, 'activo', 'Motricidad oral', NULL, 'Juntá los labios, frunciendo la boca, y dá un beso. Hacé el sonido del beso y abrí un poco la boca al final.', 145277),
  ('LAMER LA CARA INTERNA DE LOS DIENTES', NULL, true, 'activo', 'Motricidad oral', NULL, 'Usá la lengua para lamer la cara interna de los dientes de arriba y de abajo.', 145278),
  ('LAMER LA CARA EXTERNA DE LOS DIENTES', NULL, true, 'activo', 'Motricidad oral', NULL, 'Usá la lengua para lamer la cara externa de los dientes de arriba y de abajo.', 145280),
  ('CÍRCULO CON LA BOCA', NULL, true, 'activo', 'Motricidad oral', NULL, 'Abrí la boca y formá un círculo con los labios. Mantené, relajá y repetí.', 145281),
  ('PRONUNCIAR "AHHH"', NULL, true, 'activo', 'Motricidad oral', NULL, 'Tomá aire profundo, después abrí un poco la boca y hacé el sonido "Ahhh". Repetí.', 145396),
  ('DESVIACIÓN LATERAL CON LABIOS FRUNCIDOS', NULL, true, 'activo', 'Motricidad oral', NULL, 'Fruncí los labios y después movelos hacia el costado. Volvé a la posición inicial y repetí.', 145282),
  ('LABIOS FRUNCIDOS Y SONRISA - SIN DIENTES', NULL, true, 'activo', 'Motricidad oral', NULL, 'Fruncí los labios como para dar un beso y después sonreí sin mostrar los dientes. Repetí.', 145289),
  ('LABIOS FRUNCIDOS Y SONRISA CON DIENTES', NULL, true, 'activo', 'Motricidad oral', NULL, 'Fruncí los labios como para dar un beso y después sonreí mostrando los dientes. Repetí.', 145286),
  ('ELEVAR EL PALADAR BLANDO', NULL, true, 'activo', 'Motricidad oral', NULL, 'Abrí la boca y elevá el paladar blando. Es el movimiento que ocurre al bostezar.', 145275),
  ('APERTURA MANDIBULAR RESISTIDA - TOALLA ENROLLADA', NULL, true, 'fortalecimiento', 'Motricidad oral', NULL, 'Colocá una toalla enrollada debajo del mentón. Abrí la boca contra la resistencia de la toalla enrollada y después cerrá la boca. Repetí.', 145408),
  ('HABLA - M, P, B', NULL, true, 'activo', 'Motricidad oral', NULL, 'Pronunciá la letra "M". Después la letra "P". Después la letra "B". Después decí "Ma", "Pa", "Ba". Repetí.', 145872),
  ('DEGLUCIÓN SUPRAGLÓTICA', NULL, true, 'activo', 'Motricidad oral', NULL, 'Tragá un poco de saliva y tosé inmediatamente al final de la deglución. Esto ayuda a limpiar la garganta después de tragar, para evitar que los líquidos entren en la tráquea y los pulmones.', 145409),
  ('BAJALENGUAS - HACIA ADELANTE', NULL, true, 'fortalecimiento', 'Motricidad oral', NULL, 'Sacá la lengua y colocá un bajalenguas debajo de ella. Usá la lengua para presionar hacia abajo contra la resistencia del bajalenguas mientras lo sostenés en una posición fija.', 145873),
  ('BARRIDO DE LA LENGUA POR LA MEJILLA', NULL, true, 'activo', 'Motricidad oral', NULL, 'Empujá la lengua contra la cara interna de la mejilla y deslizala hacia arriba y abajo. Hacelo de los dos lados.', 145295),
  ('ISOMÉTRICO DE LENGUA - DESVIACIÓN LATERAL', NULL, true, 'fortalecimiento', 'Motricidad oral', NULL, 'Presioná la lengua contra el costado de la boca (cara interna de la mejilla) mientras aplicás un poco de fuerza externa con el dedo sobre la mejilla, del otro lado. Mantené esta contracción de la lengua, relajá y repetí.', 145264),
  ('ESTIRAMIENTO DE LENGUA - BILATERAL', NULL, true, 'activo', 'Motricidad oral', NULL, 'Sacá la lengua hacia un costado de la boca. Mantené un estiramiento suave y después volvé con la lengua adentro de la boca y repetí del lado contrario.', 145393),
  ('ESTIRAMIENTO DE LENGUA - HACIA ADELANTE', NULL, true, 'activo', 'Motricidad oral', NULL, 'Sacá la lengua hacia adelante todo lo que puedas. Mantené un estiramiento suave, después volvé con la lengua adentro de la boca y repetí.', 145391),
  ('ESTIRAMIENTO DE LENGUA - LATERAL', NULL, true, 'activo', 'Motricidad oral', NULL, 'Sacá la lengua hacia un costado de la boca. Mantené un estiramiento suave y después volvé con la lengua adentro de la boca y repetí del mismo lado.', 145394),
  ('ESTIRAMIENTO DE LENGUA - HACIA ARRIBA', NULL, true, 'activo', 'Motricidad oral', NULL, 'Sacá la lengua hacia arriba, en dirección a la nariz. Mantené un estiramiento suave y después volvé con la lengua adentro de la boca y repetí.', 145395),
  ('ESTIRAMIENTO DE LENGUA HACIA ABAJO', NULL, true, 'activo', 'Motricidad oral', NULL, 'Sacá la lengua hacia abajo, en dirección al mentón. Mantené un estiramiento suave y después volvé con la lengua adentro de la boca y repetí.', 145390),
  ('BOSTEZO Y SUSPIRO', NULL, true, 'activo', 'Motricidad oral', NULL, 'Hacé los movimientos del bostezo: bajá la mandíbula mientras tomás aire profundo. Después, soltá el aire de los pulmones y de la boca.', 145411),
  ('DEGLUCIÓN FORZADA', NULL, true, 'activo', 'Motricidad oral', 'Labios', 'Tragá un poco de saliva con una contracción fuerte de la lengua y los músculos de la garganta. Al final de la deglución, abrí bien la boca y mostrá los dientes. Repetí.', 145403),
  ('LAMER LOS LABIOS', NULL, true, 'activo', 'Motricidad oral', 'Labios', 'Usá la lengua para lamer el labio de arriba y el de abajo.', 145279),
  ('MANIOBRA DE MASAKO', NULL, true, 'activo', 'Motricidad oral', 'Lengua', 'Colocá la punta de la lengua entre los dientes y después tragá. Relajá la boca y después repetí.', 145406),
  ('MANIOBRA DE MENDELSOHN', NULL, true, 'activo', 'Motricidad oral', 'Lengua', 'Al tragar, la "nuez de Adán" o prominencia laríngea sube y después baja. Hacé una deglución y usá los músculos de la garganta para sostener la nuez de Adán en la posición alta. El objetivo es mantener 3 segundos. Relajá y repetí.', 145407),
  ('BAJALENGUAS - DESVIACIÓN BILATERAL', NULL, true, 'fortalecimiento', 'Motricidad oral', 'Lengua', 'Sacá la lengua y colocá un bajalenguas contra el costado de la lengua. Usá la lengua para presionar hacia el costado contra la resistencia del bajalenguas mientras lo sostenés en una posición fija. Después, hacelo del lado contrario. Repetí.', 145864),
  ('BAJALENGUAS - HACIA ABAJO', NULL, true, 'fortalecimiento', 'Motricidad oral', 'Lengua', 'Sacá la lengua y colocá un bajalenguas debajo de ella. Usá la lengua para presionar hacia abajo contra la resistencia del bajalenguas mientras lo sostenés en una posición fija.', 145861),
  ('BAJALENGUAS - DESVIACIÓN LATERAL', NULL, true, 'activo', 'Motricidad oral', 'Lengua', 'Sacá la lengua y colocá un bajalenguas contra el costado de la lengua. Usá la lengua para presionar hacia el costado contra el bajalenguas mientras lo sostenés en una posición fija.', 145862),
  ('BAJALENGUAS - HACIA ARRIBA', NULL, true, 'fortalecimiento', 'Motricidad oral', 'Lengua', 'Sacá la lengua y colocá un bajalenguas sobre la punta de la lengua. Usá la lengua para presionar hacia arriba contra la resistencia del bajalenguas mientras lo sostenés en una posición fija.', 145860),
  ('AAROM DE FLEXIÓN DE CODO - MANOS ENTRELAZADAS', NULL, true, 'activo', 'Especiales', NULL, 'Empezá con las manos apoyadas en la falda y los dedos entrelazados. Después, usá un brazo para ayudar a flexionar los codos hasta que las manos queden cerca de un costado del pecho. Volvé a la posición inicial y repetí del otro lado.', 163677),
  ('TOQUES ALTERNADOS A LA PUNTA DEL PIE', NULL, true, 'activo', 'Especiales', NULL, 'Parate con los pies bien separados. Empezá con los brazos extendidos hacia los costados. Bajá una mano y tratá de tocar los dedos del pie contrario. Volvé a la posición inicial y repetí del otro lado. Seguí alternando los lados.', 130989),
  ('CARA DE ENOJO', NULL, true, 'activo', 'Especiales', NULL, 'Juntá las cejas como si pusieras cara de enojo.', 379),
  ('POSTURA DEL BOTE - YOGA - NAVASANA', NULL, true, 'activo', 'Especiales', NULL, 'Empezá sentado con las rodillas flexionadas. Después, inclinate hacia atrás y elevá las piernas manteniendo las rodillas flexionadas. Sostenete en esta posición semirreclinada con los brazos estirados hacia adelante. Mantené la posición.', 65096),
  ('PUENTE - AMPUTADOS - INFRARROTULIANA O SUPRARROTULIANA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Acostate boca arriba con una toalla enrollada debajo del muñón. La pierna sana debe tener la rodilla flexionada y el pie apoyado en el piso. Después, presioná el muñón hacia abajo contra la toalla mientras elevás la pelvis del piso. Mantené, bajá y repetí.', 70659),
  ('CARDIOPULMONAR - CAMINAR EN EL LUGAR', NULL, true, 'activo', 'Especiales', NULL, 'Caminá en el lugar. Seguí con esto para ganar resistencia.', 75831),
  ('CARDIOPULMONAR - CAMINAR EN EL LUGAR CON BALANCEO DE BRAZOS', NULL, true, 'activo', 'Especiales', NULL, 'Marchá en el lugar mientras balanceás los brazos a los costados. Seguí con esto para ganar resistencia.', 75825),
  ('CARDIOPULMONAR - CAMINATA EN EL LUGAR CON CURLS DE BÍCEPS', NULL, true, 'activo', 'Especiales', NULL, 'Marchá en el lugar mientras hacés curls de bíceps con ambos brazos. Seguí con esto para ganar resistencia.', 75827),
  ('CARDIOPULMONAR - CAMINATA EN EL LUGAR CON ABDUCCIONES DE HOMBRO', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Marchá en el lugar mientras elevás los brazos hacia los costados. Si lo tolerás, sostené pesas chicas. Seguí con esto para ganar resistencia.', 75812),
  ('CARDIOPULMONAR - CAMINATA EN EL LUGAR CON CÍRCULOS DE HOMBROS', NULL, true, 'activo', 'Especiales', NULL, 'Caminá en el lugar mientras movés los hombros en un patrón circular, como se muestra, de modo que vayan hacia arriba, atrás y abajo. Seguí con esto para ganar resistencia.', 75832),
  ('EQUIPO DE TRACCIÓN CERVICAL', NULL, true, 'activo', 'Especiales', NULL, 'Usá el equipo de tracción cervical según las indicaciones de tu profesional.', 7150),
  ('FONDOS EN LA SILLA - AUTOASISTIDOS - AMPUTADOS - SUPRA O INFRARROTULIANA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Sentado en una silla con apoyabrazos, agarrá los apoyabrazos y empujá el cuerpo hacia arriba de modo que la cola se despegue del asiento. Mantené el pie sano en el piso para ayudarte a subir y bajar el cuerpo. Bajá y repetí.', 70651),
  ('POSTURA DE LA SILLA - YOGA - UTKATASANA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Empezá en posición de pie. Elevá los brazos bien alto mientras flexionás las rodillas en posición de sentadilla. Mantené las rodillas por detrás de los dedos de los pies. Flexioná desde las caderas y mantené la espalda derecha. Activá los músculos abdominales llevando el ombligo hacia la columna. Mantené esta posición. Respiración diafragmática lenta y profunda todo el tiempo.', 65003),
  ('COMPRESA FRÍA', NULL, true, 'sin_clasificar', 'Especiales', NULL, 'Aplicá una compresa fría sobre la zona afectada.', 7133),
  ('BAÑO DE CONTRASTE - PIE', NULL, true, 'activo', 'Especiales', NULL, 'Conseguí 2 baldes o palanganas lo suficientemente grandes como para que entre el pie cómodamente. Llená uno con agua tibia y el otro con agua fría. Meté el pie en el balde de agua tibia y dejalo ahí ___ minutos. Después, sacalo y metelo en el balde de agua fría ___ minutos. Alterná entre los baldes ___ veces y terminá en el de agua fría.', 73660),
  ('BAÑO DE CONTRASTE - MANO', NULL, true, 'activo', 'Especiales', NULL, 'Conseguí 2 baldes o palanganas lo suficientemente grandes como para que entre la mano cómodamente. Llená uno con agua tibia y el otro con agua fría. Meté la mano en el balde de agua tibia y dejala ahí ___ minutos. Después, sacala y metela en el balde de agua fría ___ minutos. Alterná entre los baldes ___ veces y terminá en el de agua fría.', 73662),
  ('POSTURA DEL CADÁVER - YOGA - SAVASANA', NULL, true, 'activo', 'Especiales', NULL, 'Empezá acostado boca arriba con las rodillas flexionadas y después estirá las piernas de a una hasta quedar acostado completamente plano. Las piernas tienen que quedar separadas y rotadas hacia afuera. Colocá los brazos hacia los costados con las palmas hacia arriba. Concentrate en relajar todos los músculos y en la respiración diafragmática profunda (la panza sube al inhalar y baja al exhalar).', 65065),
  ('POSTURA DE LA MEDIA LUNA EN ESTOCADA - YOGA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Empezá en posición de estocada de pie (un paso grande adelante con un pie). Ubicá los pies de modo que ambos apunten derecho hacia adelante. Activá los músculos abdominales llevando el ombligo hacia la columna. Flexioná la rodilla de adelante manteniéndola por detrás de los dedos del pie. Podés dejar que la rodilla de atrás se flexione más para progresar en esta postura. Mantené la espalda derecha y en posición neutra. Achicá el largo del paso si la espalda se arquea demasiado. Elevá los brazos por encima de la cabeza. Mantené esta posición. Respiración diafragmática lenta y profunda todo el tiempo.', 65005),
  ('POSTURA DEL ÁNGULO LATERAL EXTENDIDO - YOGA - CODO SOBRE EL MUSLO - PARSVAKONASANA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Empezá parado en posición de estocada, con los dedos del pie de adelante apuntando hacia adelante y los del pie de atrás apuntando hacia el costado (posición de pies del guerrero 2 de yoga). Después, inclinate hacia adelante, apoyá el antebrazo sobre el muslo de adelante y estirá el otro brazo hacia arriba y por encima de la cabeza, como se muestra. Girá la cabeza para mirar la mano que está arriba. Mantené esta posición. Respiración diafragmática lenta y profunda todo el tiempo.', 65013),
  ('CAMINATA DEL GRANJERO - KETTLEBELL - ACUNADA EN EL HOMBRO', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Acuná una kettlebell contra el hombro y después caminá 6 metros, girá y volvé caminando 6 metros hasta el punto de partida. Mantené la columna erguida y derecha. Además, mantené el tono en el hombro para sostener el peso. Después, hacelo con el otro brazo.', 53539),
  ('ESTABILIZACIÓN DE LA MIRADA - DIAGONAL', NULL, true, 'activo', 'Especiales', NULL, 'Escribí una letra del alfabeto en dos papelitos autoadhesivos y pegalos en una pared, aproximadamente a la altura de los ojos, a unos 60-90 cm adelante tuyo y separados entre sí unos 60-90 cm en diagonal. Mantené la cabeza quieta, sin moverla, y movés solo los ojos. Mirá la letra de la izquierda y después mirá la letra de la derecha. Repetí moviendo solo los ojos y no la cabeza. Mantené el foco nítido sobre la letra todo el tiempo.', 112005),
  ('ESTABILIZACIÓN DE LA MIRADA - HORIZONTAL', NULL, true, 'activo', 'Especiales', NULL, 'Escribí una letra del alfabeto en dos papelitos autoadhesivos y pegalos en una pared, aproximadamente a la altura de los ojos, a unos 60-90 cm adelante tuyo y separados entre sí unos 60-90 cm en horizontal. Mantené la cabeza quieta, sin moverla, y movés solo los ojos. Mirá la letra de la izquierda y después mirá la letra de la derecha. Repetí moviendo solo los ojos y no la cabeza. Mantené el foco nítido sobre la letra todo el tiempo.', 112002),
  ('ESTABILIZACIÓN DE LA MIRADA - VERTICAL', NULL, true, 'activo', 'Especiales', NULL, 'Escribí una letra del alfabeto en dos papelitos autoadhesivos y pegalos en una pared, aproximadamente a la altura de los ojos, a unos 60-90 cm adelante tuyo y separados entre sí unos 60-90 cm en vertical. Mantené la cabeza quieta, sin moverla, y movés solo los ojos. Usá los ojos para mirar la letra de arriba y después la letra de abajo. Repetí moviendo solo los ojos y no la cabeza. Mantené el foco nítido sobre la letra todo el tiempo.', 112003),
  ('DISCOS DESLIZANTES - SALTOS DE TIJERA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Empezá en posición de pie con las manos al costado del cuerpo y los pies juntos, parado sobre discos deslizantes. Después, deslizá los pies separándolos mientras elevás los brazos hacia el costado y por encima de la cabeza. Después, deslizá las piernas juntándolas otra vez mientras los brazos vuelven al costado del cuerpo. Repetí.', 43363),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES - DECÚBITO DORSAL - AMPUTADOS - SUPRA O INFRARROTULIANA', NULL, true, 'activo', 'Especiales', NULL, 'Acostado boca arriba, elevá el muñón y sostenelo por detrás. Tirá de la pierna hacia arriba hasta sentir un estiramiento. Mantené, relajá y repetí.', 70799),
  ('ESTIRAMIENTO DE ESPASTICIDAD DE MANO, ANTEBRAZO Y DEDOS', NULL, true, 'activo', 'Especiales', NULL, 'Apoyá el brazo afectado (antebrazo, mano y codo) sobre una mesa. Usá el otro brazo para acariciar el antebrazo. Esto puede ayudar a relajar los músculos. Con la mano y el brazo del otro lado, girá el antebrazo de modo que la palma quede hacia abajo. Presioná la muñeca hacia abajo para aplanarla y sacarla de su posición flexionada. Después, estirá el pulgar hacia afuera, alejándolo de la mano. Por último, usá los dedos de la mano sana para estirar los dedos del lado afectado y extenderlos sobre la mesa. Mantené esta posición. Relajá y repetí.', 140971),
  ('MANCUERNAS PESADAS - CAMINATA DEL GRANJERO - ASIMÉTRICA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Hacé una sentadilla y agarrá un peso libre en cada mano. Llevá una mancuerna hacia arriba con un curl y sostenela a la altura del hombro, como se muestra. Mantené la columna erguida y derecha. Mantené el tono en los hombros para sostener las pesas y después caminá hacia adelante. Mantené la columna erguida sin inclinarte.', 65350),
  ('MANCUERNAS PESADAS - CAMINATA DEL GRANJERO - DESBALANCEADA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Hacé una sentadilla y agarrá un peso libre con una mano. Llevá la mancuerna hacia arriba con un curl y sostenela a la altura del hombro, como se muestra. Mantené la columna erguida y derecha. Mantené el tono en el hombro para sostener el peso y después caminá hacia adelante. Mantené la columna erguida sin inclinarte hacia el costado.', 65351),
  ('MANCUERNAS PESADAS - CAMINATA DEL GRANJERO', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Hacé una sentadilla y agarrá un peso libre en cada mano. Mantené el tono en los hombros para sostener el peso y después caminá hacia adelante. Además, mantené la columna erguida y derecha, sin inclinarte, todo el tiempo.', 63498),
  ('ABDUCCIÓN Y ADUCCIÓN DE CADERA - AMPUTADOS - SUPRA O INFRARROTULIANA', NULL, true, 'activo', 'Especiales', NULL, 'Acostado boca arriba y con las piernas estiradas, movés lentamente el muñón hacia el costado y después volvé a la posición inicial. Repetí.', 71322),
  ('ADUCCIÓN DE CADERA - APRETAR ALMOHADA O TOALLA - DECÚBITO DORSAL - AMPUTADOS - INFRA O SUPRARROTULIANA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Acostate boca arriba. Colocá una almohada doblada o una toalla enrollada entre los muslos y apretá con firmeza. Mantené, soltá y repetí.', 71333),
  ('AROM DE CADERA Y RODILLA - DECÚBITO LATERAL - AMPUTADOS - INFRARROTULIANA', NULL, true, 'activo', 'Especiales', NULL, 'Acostate de costado con el muñón arriba. Después, flexioná la rodilla y la cadera llevando la pierna hacia el pecho; luego invertí la dirección y llevá la pierna hacia la línea del tronco mientras estirás la rodilla y extendés la cadera. Volvé a llevar la pierna hacia el pecho y repetí.', 70657),
  ('EXTENSIÓN DE CADERA - DECÚBITO VENTRAL - AMPUTADOS - SUPRA O INFRARROTULIANA', NULL, true, 'activo', 'Especiales', NULL, 'Acostate boca abajo y después elevá el muñón hacia el techo. Bajá y repetí.', 70660),
  ('ESTIRAMIENTO DE FLEXORES DE CADERA SOBRE LOS CODOS - DECÚBITO VENTRAL - AMPUTADOS - INFRA O SUPRARROTULIANA', NULL, true, 'activo', 'Especiales', NULL, 'Acostate boca abajo y apoyate sobre los codos para permitir un estiramiento en la parte de adelante de las caderas.', 70667),
  ('COMPRESA CALIENTE', NULL, true, 'sin_clasificar', 'Especiales', NULL, 'Aplicá una compresa caliente sobre la zona afectada.', 7136),
  ('BAÑO DE HIELO - PIE', NULL, true, 'activo', 'Especiales', NULL, 'Conseguí un balde o palangana lo suficientemente grande como para que entre el pie y el tobillo cómodamente. Llenalo con agua y hielo (proporción 3:1 de agua y hielo). Dejá el pie en el agua helada 5 minutos.', 73670),
  ('BAÑO DE HIELO - MANO', NULL, true, 'activo', 'Especiales', NULL, 'Conseguí un balde o palangana lo suficientemente grande como para que entre la mano y la muñeca cómodamente. Llenalo con agua y hielo (proporción 3:1 de agua y hielo). Dejá la mano en el agua helada 5 minutos.', 73672),
  ('SALTAR A LA SOGA', NULL, true, 'activo', 'Especiales', NULL, 'Hacé girar la soga hacia adelante saltando por encima con los dos pies. Repetí.', 61151),
  ('SALTAR A LA SOGA - DOBLE SALTO', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Hacé girar la soga hacia adelante saltando por encima dos veces con un pie y después alterná saltando dos veces con el otro pie. Repetí alternando los lados.', 61149),
  ('SALTOS DE TIJERA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Empezá en posición de pie con las manos al costado del cuerpo y los pies juntos. Después, hacé un salto chico separando las piernas hacia los costados. Al mismo tiempo, elevá los brazos hacia el costado y después por encima de la cabeza. Después saltá de nuevo y volvé con las manos y los pies a la posición original. Repetí.', 41809),
  ('KETTLEBELL - LEVANTADA TURCA', NULL, true, 'fortalecimiento', 'Especiales', NULL, '1. Acostate de costado sosteniendo una kettlebell con el brazo de abajo. 2. Rodá boca arriba, estirá una pierna y flexioná la rodilla del mismo lado que la pesa. 3. Elevá la kettlebell hacia el techo y estirá el codo. La kettlebell tiene que quedar sostenida así durante todos los pasos siguientes. 4. Apoyate sobre el codo contrario. 5. Apoyate sobre la mano y elevá la pelvis en puente. 6-7. Pasá la pierna de adelante por debajo tuyo y hacia atrás hasta quedar arrodillado. 8. Estirá la cadera. 9. Pararte. Después, invertí todos los pasos y volvé a la posición original.', 28619),
  ('EQUIPO DE TRACCIÓN LUMBAR', NULL, true, 'activo', 'Especiales', NULL, 'Usá el equipo de tracción lumbar en tu casa según las indicaciones de tu profesional.', 7151),
  ('POSTURA DE LA MONTAÑA - YOGA - TADASANA', NULL, true, 'activo', 'Especiales', NULL, 'Parate con los pies juntos o separados al ancho de las caderas. Los pies deben estar bien apoyados: hacé contacto con el piso en 3 puntos, es decir, el talón, la parte externa del metatarso (del lado del dedo gordo) y la parte externa del metatarso (del lado del dedo chico), con buen contacto y peso repartido parejo. Activá los muslos (cuádriceps). Las rótulas tienen que apuntar hacia adelante y no hiperextiendas las rodillas. Activá el core con estabilización pélvica (activando los músculos del abdomen y llevando el ombligo hacia la columna). Parate con buena postura, con las orejas alineadas sobre los hombros. Mantené los hombros bajos y lejos de las orejas. Los hombros sobre las caderas y las caderas sobre los tobillos. Juntá las palmas por delante del pecho o elevá los brazos por encima de la cabeza, como se muestra. Mantené esta posición. Respiración diafragmática lenta y profunda todo el tiempo.', 65021),
  ('SENTADO A DE PIE PARCIAL', NULL, true, 'activo', 'Especiales', NULL, 'Sentate en una silla y después elevate hasta una posición de pie parcial, sin pararte del todo, y volvé a sentarte. Repetí. Si te hace falta, podés empujar la rodilla hacia atrás con las manos mientras intentás pararte.', 139316),
  ('PEDIÁTRICO - DESPLAZAMIENTO LATERAL ASISTIDO EN EL SILLÓN', NULL, true, 'activo_asistido', 'Especiales', NULL, 'Poné al niño parado frente a un sillón para apoyarse. Dejá que el niño dé pasos laterales a lo largo del sillón y camine hasta el otro extremo. Asistilo con apoyo para el equilibrio según sea necesario.', 118361),
  ('PEDIÁTRICO - APOYO ASISTIDO EN UNA PIERNA', NULL, true, 'activo_asistido', 'Especiales', NULL, 'Poné al niño parado frente a un sillón para apoyarse. Ayudá al niño a despegar una pierna del piso de modo que quede parado en una sola pierna. Asistilo con apoyo para el equilibrio según sea necesario.', 118358),
  ('PEDIÁTRICO - INCORPORACIÓN ASISTIDA', NULL, true, 'activo_asistido', 'Especiales', NULL, 'Acostá al niño en el piso y estabilizale las piernas con tus rodillas. Animalo a incorporarse y dejá que inicie el movimiento, asistiéndolo según sea necesario. Si el niño no puede mantener la cabeza en la línea media, podés sostenerle la cabeza o aumentar el ángulo para que quede acostado en un plano inclinado con una almohada o una manta doblada. Ayudalo a volver a acostarse y repetí.', 118353),
  ('PEDIÁTRICO - EQUILIBRIO ASISTIDO DE PIE', NULL, true, 'activo_asistido', 'Especiales', NULL, 'Poné al niño parado sobre un almohadón, una almohada o una manta doblada y sostenelo desde la pelvis. Asistilo con el equilibrio de pie según sea necesario.', 118360),
  ('PEDIÁTRICO - SUBIDA ASISTIDA AL ESCALÓN', NULL, true, 'activo_asistido; fortalecimiento', 'Especiales', NULL, 'Ayudá al niño a subir a un almohadón o a un escalón.', 118402),
  ('PEDIÁTRICO - PUENTE', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Acostá al niño boca arriba con las rodillas flexionadas y después hacé que despegue la cola del piso o de la cama, formando un puente con el cuerpo. Mantené, bajá y repetí.', 118408),
  ('PEDIÁTRICO - ATAJAR Y LANZAR', NULL, true, 'activo', 'Especiales', NULL, 'Poné al niño de pie y después tirale una pelota para que la ataje. Pedile que te la devuelva. Repetí.', 118410),
  ('PEDIÁTRICO - ELEVACIÓN DE TALONES Y MANTENER', NULL, true, 'activo', 'Especiales', NULL, 'Poné al niño de pie y después hacé que eleve los talones del piso, como se muestra. Mantené la posición, bajá y repetí. Si le hace falta, el niño puede agarrarse de algo para tener apoyo.', 118412),
  ('PEDIÁTRICO - SALTOS', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Hacé que el niño salte con las dos piernas. Repetí. Si hace falta, podés poner un juguete apenas fuera de su alcance para motivarlo.', 118413),
  ('PEDIÁTRICO - SALTOS DE TIJERA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Hacé que el niño haga saltos de tijera. Empezá en posición de pie con los pies juntos y los brazos abajo al costado del cuerpo. Después saltá y caé con los pies separados. Al mismo tiempo, llevá los brazos hacia el costado y por encima de la cabeza. Después, saltá de nuevo y volvé a la posición inicial con los pies juntos y los brazos al costado del cuerpo. Repetí.', 118407),
  ('PEDIÁTRICO - ESTIRAMIENTO DE RODILLA AL PECHO', NULL, true, 'activo', 'Especiales', NULL, 'Acostá al niño en el piso y llevale las rodillas hacia el pecho para un estiramiento suave, como se muestra. Mantené, relajá y repetí.', 118411),
  ('PEDIÁTRICO - INCLINACIÓN LATERAL SENTADO', NULL, true, 'activo', 'Especiales', NULL, 'Sentado, empezá poniendo al niño sobre tu falda mientras le estabilizás la pelvis. Después, inclinale la pelvis hacia el costado. El niño debe intentar corregir con la columna y la cabeza, inclinándose hacia el lado contrario. Mantené y después volvé a la posición inicial y repetí.', 118357),
  ('PEDIÁTRICO - APOYO EN UNA PIERNA', NULL, true, 'activo', 'Especiales', NULL, 'Hacé que el niño se pare en una pierna y mantenga la posición mientras hace equilibrio. Tomale el tiempo para hacerlo más divertido.', 118415),
  ('PEDIÁTRICO - SALTOS EN UNA PIERNA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Hacé que el niño se pare en una pierna y después salte. Repetí sobre esa misma pierna.', 118414),
  ('PEDIÁTRICO - APOYO EN TÁNDEM', NULL, true, 'activo', 'Especiales', NULL, 'Hacé que el niño se pare y haga equilibrio con un pie justo delante del otro. Tratá de que el talón de un pie toque los dedos del otro. Se puede progresar de ojos abiertos a ojos cerrados.', 118417),
  ('ELEVACIONES DE BRAZO EN DECÚBITO VENTRAL SOBRE CODOS - TRASLADO DE PESO - POE', NULL, true, 'activo', 'Especiales', NULL, 'Acostado boca abajo, incorporate apoyándote sobre los codos. Después, inclinate hacia un costado y despegá un brazo del piso. Mantené, bajá y repetí.', 139350),
  ('ALCANCE EN DECÚBITO VENTRAL SOBRE CODOS - TRASLADO DE PESO - POE', NULL, true, 'activo', 'Especiales', NULL, 'Acostado boca abajo, incorporate apoyándote sobre los codos. Después, inclinate hacia un costado, despegá un brazo del piso y estiralo hacia adelante. Mantené, bajá y repetí.', 139354),
  ('TRASLADO DE PESO EN DECÚBITO VENTRAL SOBRE CODOS - POE', NULL, true, 'activo', 'Especiales', NULL, 'Acostado boca abajo, incorporate apoyándote sobre los codos. Inclinate hacia un costado para cargar más peso sobre ese hombro. Después, inclinate en la dirección contraria para cargar más peso sobre el otro hombro. Alterná los lados y repetí.', 139355),
  ('ESTIRAMIENTO DE PECTORAL EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Especiales', NULL, 'Empezá acostado boca abajo con el brazo a trabajar extendido hacia el costado y el codo estirado, como se muestra. Después, pasá la pierna del lado opuesto cruzando la línea media y usá el otro brazo para elevar y rotar el cuerpo hasta sentir un estiramiento suave en el hombro y el pecho del lado a trabajar. Mantené, volvé a la posición inicial y repetí.', 141158),
  ('ACTIVACIÓN DE CUÁDRICEPS - ESTIRAMIENTO EN EXTENSIÓN DE RODILLA - AMPUTADOS - INFRARROTULIANA', NULL, true, 'activo', 'Especiales', NULL, 'Sentado o acostado boca arriba, colocá una toalla enrollada debajo del muñón. Después, extendé completamente la rodilla imaginando que llevás la parte de atrás de la rodilla hacia el piso. Mantené, relajá y repetí.', 70655),
  ('LEVANTAR LAS CEJAS', NULL, true, 'activo', 'Especiales', NULL, 'Llevá las cejas hacia arriba como en gesto de sorpresa.', 383),
  ('BICICLETA RESTAURADORA', NULL, true, 'activo', 'Especiales', NULL, 'Colocá el pedaleador en el piso adelante tuyo. Asegurate de mantener una postura erguida. Después, colocá los pies firmes en los pedales y empezá a pedalear.', 75103),
  ('ANDAR EN BICICLETA', NULL, true, 'activo', 'Especiales', NULL, 'Andá en bicicleta sobre una superficie plana. Mantené la cola apoyada en el asiento. No subas ni bajes cordones. Pedaleá de manera pareja, con aceleraciones y desaceleraciones controladas.', 125280),
  ('CORRER', NULL, true, 'activo', 'Especiales', NULL, 'Empezá un programa de trote.', 6978),
  ('ARCO CORTO DE CUÁDRICEPS (SAQ) - AMPUTADOS - INFRARROTULIANA', NULL, true, 'activo', 'Especiales', NULL, 'Colocá una toalla enrollada o una almohada doblada debajo de la rodilla y elevá el muñón mientras estirás la rodilla. Mantené, bajá y repetí.', 70656),
  ('PUENTE CON PIERNA SANA - AMPUTADOS - SUPRARROTULIANA O INFRARROTULIANA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Acostate boca arriba con la rodilla sana flexionada y el pie apoyado en el piso. Después, activá los músculos abdominales bajos, apretá los glúteos y elevá la cola del piso o de la cama, formando un puente con el cuerpo. Mantené, bajá y repetí.', 70670),
  ('SUBIR Y PASAR EL ESCALÓN - CON APOYO', NULL, true, 'activo_asistido; fortalecimiento', 'Especiales', NULL, 'Parate frente a un escalón chico. Apoyá un pie sobre el escalón. Ese pie se queda ahí todo el tiempo. Después, pasá por encima del escalón con la otra pierna de modo que el pie caiga adelante del escalón. Después de apoyar, invertí el movimiento y pasá hacia atrás por encima del escalón para volver a la posición inicial. Usá un bastón de esquí o un palo de escoba como apoyo para el equilibrio. Repetí.', 139359),
  ('EXTENSIÓN DE CADERA ARRODILLADO', NULL, true, 'activo', 'Especiales', NULL, 'Arrodillate en el piso con postura erguida y con el brazo elevado y apuntando hacia adelante, como se muestra. Después, bajá la cola hacia los talones dejando que las rodillas y las caderas se flexionen. Sin llegar a sentarte sobre los talones, volvé a subir a la posición de rodillas erguido y repetí.', 139584),
  ('EQUIPO TENS', NULL, true, 'activo', 'Especiales', NULL, 'Aplicá el equipo TENS según las indicaciones de tu profesional.', 7137),
  ('POSTURA DEL ÁRBOL MODIFICADA - YOGA - VRKSASANA', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Activá los músculos abdominales llevando el ombligo hacia adentro, en dirección a la columna. Parate en una pierna y apoyá la planta del otro pie contra el costado de la pierna, como se muestra. Apoyá la planta del pie por debajo de la línea articular de la rodilla. La cadera de la pierna que no apoya debe estar rotada hacia afuera, de modo que la rodilla apunte hacia el costado. Juntá las palmas de las manos a la altura del pecho o por encima de la cabeza. Mantené esta posición. Respiración diafragmática lenta y profunda todo el tiempo.', 65025),
  ('POSTURA DEL TRIÁNGULO - YOGA - TRIKONASANA', NULL, true, 'activo', 'Especiales', NULL, 'Empezá en posición de pie y dá un paso adelante de modo que el pie de adelante apunte hacia adelante y el de atrás apunte hacia el costado. Las dos rodillas deben estar estiradas. Después, inclinate hacia adelante haciendo bisagra desde las caderas y apoyá la mano en el piso. Estirá el otro brazo hacia arriba, por encima de la cabeza, y girá la cabeza para mirar hacia arriba. Mantené esta posición. Respiración diafragmática lenta y profunda todo el tiempo.', 65072),
  ('POSTURA DEL TRIÁNGULO CON BLOQUE - YOGA - TRIKONASANA', NULL, true, 'activo', 'Especiales', NULL, 'Empezá en posición de pie y dá un paso adelante de modo que el pie de adelante apunte hacia adelante y el de atrás apunte hacia el costado. Las dos rodillas deben estar estiradas. Después, inclinate hacia adelante haciendo bisagra desde las caderas y agarrate de un bloque de yoga como apoyo. Estirá el otro brazo hacia arriba, por encima de la cabeza, y girá la cabeza para mirar hacia arriba. Mantené esta posición. Respiración diafragmática lenta y profunda todo el tiempo.', 65071),
  ('CARGA DE PESO EN EL BRAZO - SENTADO', NULL, true, 'activo', 'Especiales', NULL, 'Sentado al lado de una mesa, apoyá el codo, el antebrazo y la mano sobre la mesa con el codo flexionado. Si te hace falta, podés usar la otra mano para sostener el brazo y que no se deslice de la posición. Trasladá el peso del cuerpo sobre el antebrazo y el codo. Mantené y después volvé inclinándote hacia atrás a la posición inicial y repetí.', 140970),
  ('CARGA DE PESO EN MIEMBRO SUPERIOR - SENTADO', NULL, true, 'pasivo', 'Especiales', NULL, 'Sentado, apoyá la mano del lado afectado sobre el asiento al costado tuyo y sostené el codo en extensión completa con la otra mano, como se muestra. Trasladá el peso del cuerpo sobre el brazo afectado. Mantené, volvé a la posición inicial y repetí.', 140966),
  ('CARGA DE PESO EN MIEMBRO SUPERIOR - DE PIE, ADELANTANDO UN BRAZO', NULL, true, 'activo', 'Especiales', NULL, 'Parado frente a una mesa, apoyá ambas manos sobre la mesa manteniendo los codos en extensión completa. Trasladá parte del peso del cuerpo sobre los brazos. Deslizá hacia adelante la mano del brazo que no trabaja. Eso hace que se traslade más peso al brazo objetivo (el que no se movió). Mantené esta posición y después volvé a la posición inicial llevando el brazo que no trabaja a su lugar original, y repetí.', 140968),
  ('POSTURA DEL PERRO BOCA ARRIBA - YOGA - URDHVA MUKHA SVANASANA', NULL, true, 'activo', 'Especiales', NULL, 'Empezá acostado boca abajo. Después, empujá con las manos y elevá el pecho, la pelvis, los muslos y las rodillas despegándolos del piso. Extendé también la cabeza hacia arriba. Solo los dedos y el empeine de los pies y las manos deben estar en contacto con el piso. Mantené esta posición.', 65103),
  ('CANCELACIÓN VESTIBULAR', NULL, true, 'activo', 'Especiales', NULL, 'Entrelazá las manos extendidas por delante del pecho con los pulgares apuntando hacia arriba. Rotá el cuerpo de lado a lado moviendo los brazos y manteniendo la vista en los pulgares todo el tiempo.', 112012),
  ('SUSTITUCIÓN VESTIBULAR', NULL, true, 'activo', 'Especiales', NULL, 'Sostené en cada mano un papelito con una letra del alfabeto escrita, por delante de la cara. Extendé los brazos completamente hacia adelante, como se muestra. Ubicá uno del lado izquierdo y otro del lado derecho de la cara, separados unos 30 cm. Empezá mirando hacia un lado y después girá rápido la cabeza en dirección al papel. Después, movés solo los ojos hacia el otro lado para mirar la letra del otro papel. Después, girá rápido la cabeza hacia ese lado. Alterná mientras repetís de derecha a izquierda. Mantené la letra enfocada con claridad todo el tiempo.', 112011),
  ('VOR X1 CAMINANDO - REFLEJO VESTÍBULO-OCULAR', NULL, true, 'activo', 'Especiales', NULL, 'Sostené un papelito con una letra del alfabeto escrita por delante de la cara. Empezá girando la cabeza de lado a lado mientras mirás el objeto y seguí así mientras caminás hacia adelante. Mantené el foco en la letra todo el tiempo.', 112014),
  ('CAMINAR CON ROTACIONES CERVICALES', NULL, true, 'activo', 'Especiales', NULL, 'Caminá hacia adelante mientras girás la cabeza de lado a lado. Después, caminá hacia atrás girando la cabeza de lado a lado.', 164055),
  ('CAMINAR CON ROTACIONES CERVICALES Y FLEXIÓN/EXTENSIÓN', NULL, true, 'activo', 'Especiales', NULL, 'Caminá hacia adelante mientras movés la cabeza hacia arriba y abajo. Después, caminá hacia atrás siguiendo con ese movimiento de cabeza. Luego, caminá hacia adelante girando la cabeza de lado a lado. Después, caminá hacia atrás siguiendo con ese giro de cabeza.', 164277),
  ('POSTURA DEL GUERRERO 1 - YOGA - VIRABHADRASANA 1', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Empezá dando un paso a posición de estocada, de modo que la rodilla de adelante quede flexionada y la de atrás estirada. Activá los músculos abdominales llevando el ombligo hacia la columna. Elevá los brazos por encima de la cabeza. Los dedos del pie de adelante deben apuntar derecho hacia adelante y los del pie de atrás hacia el costado. El pecho, el tronco y la cabeza deben mirar hacia adelante. Mantené esta posición. Hacé respiración diafragmática lenta y profunda todo el tiempo.', 65027),
  ('POSTURA DEL GUERRERO 2 - YOGA - VIRABHADRASANA 2', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Empezá dando un paso a posición de estocada, de modo que la rodilla de adelante quede flexionada y la de atrás estirada. Los dedos del pie de adelante deben apuntar derecho hacia adelante y los del pie de atrás hacia el costado. Activá los músculos abdominales llevando el ombligo hacia la columna. Extendé un brazo hacia adelante y el otro hacia atrás. El pecho y el tronco deben quedar girados hacia el costado. La cabeza debe mirar hacia adelante. Mantené esta posición.', 65026),
  ('POSTURA DEL GUERRERO 3 - YOGA - VIRABHADRASANA 3', NULL, true, 'fortalecimiento', 'Especiales', NULL, 'Empezá con el brazo elevado por encima de la cabeza y en posición de estocada corta, con la rodilla de adelante flexionada y la de atrás estirada. Activá los músculos abdominales llevando el ombligo hacia la columna. Después, inclinate hacia adelante extendiendo la pierna de atrás y elevándola del piso hacia el techo mientras hacés equilibrio y una bisagra de cadera sobre la otra pierna. La pierna de atrás tiene que subir alineada con el tronco. Mantené esta posición.', 65028),
  ('ARRUGAR LA NARIZ', NULL, true, 'activo', 'Especiales', NULL, 'Llevá la nariz hacia arriba como en gesto de asco.', 384),
  ('FONDOS EN LA SILLA - AMPUTADOS - SUPRARROTULIANA O INFRARROTULIANA', NULL, true, 'fortalecimiento', 'Especiales', 'Amputados', 'Sentado en una silla con apoyabrazos, agarrá los apoyabrazos y empujá el cuerpo hacia arriba de modo que la cola se despegue del asiento y el pie sano se despegue del piso. Bajá y repetí.', 70650),
  ('GATO Y CAMELLO DINÁMICO - AMPUTADOS - INFRARROTULIANA', NULL, true, 'fortalecimiento', 'Especiales', 'Amputados', 'Empezá en posición de gateo (en cuatro apoyos), con las rodillas debajo de las caderas y las manos debajo de los hombros. Activá los músculos abdominales. Empezá flexionando la columna y llevando una cadera y rodilla hacia adentro, en dirección al pecho, mientras bajás la cabeza hacia la rodilla. Después, extendé la cadera y la rodilla hacia afuera y arriba mientras elevás la pierna y la cabeza en extensión. Repetí.', 71321),
  ('ACTIVACIÓN DE GLÚTEOS - DECÚBITO VENTRAL - AMPUTADOS - INFRARROTULIANA - SUPRARROTULIANA', NULL, true, 'fortalecimiento', 'Especiales', 'Amputados', 'Acostate boca abajo y apretá los glúteos. Mantené esta contracción, relajá y después repetí.', 71659),
  ('ADUCCIÓN DE CADERA - APRETAR ALMOHADA O TOALLA - DECÚBITO VENTRAL - AMPUTADOS - INFRARROTULIANA - SUPRARROTULIANA', NULL, true, 'fortalecimiento', 'Especiales', 'Amputados', 'Colocá una toalla enrollada o una almohada doblada entre los muslos y después acostate boca abajo. Apretá los muslos con firmeza. Mantené, relajá y repetí.', 71332),
  ('EXTENSIÓN DE CADERA - DE PIE - AMPUTADOS - INFRARROTULIANA - SUPRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'De pie, hacé equilibrio sobre una pierna y llevá el muñón hacia atrás. No balancees la pierna. Hacé movimientos suaves y controlados. Mantené el tronco estable y sin arquearse durante el movimiento. Si hace falta, usá los brazos como apoyo para el equilibrio y la seguridad.', 71330),
  ('ESTIRAMIENTO DE FLEXORES DE CADERA - DECÚBITO VENTRAL - AMPUTADOS - SUPRARROTULIANA O INFRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Acostate boca abajo y empujate hacia arriba con los brazos para permitir un estiramiento en la parte de adelante de las caderas. Mantené, relajá y repetí.', 70804),
  ('ESTIRAMIENTO DE FLEXORES DE CADERA CON TOALLA - DECÚBITO VENTRAL - AMPUTADOS - SUPRARROTULIANA O INFRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Acostate boca abajo y colocá una toalla enrollada debajo del muñón, como se muestra. Después, empujate hacia arriba con los brazos para permitir un estiramiento en la parte de adelante de las caderas. Mantené, relajá y repetí.', 70812),
  ('TRASLADO LATERAL DE PESO - AMPUTADOS - INFRARROTULIANA O SUPRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Sentado en una silla, elevá los brazos hacia los costados. Después, inclinate lentamente de lado a lado alternando el traslado del peso de un glúteo al otro mientras mantenés el equilibrio. Repetí.', 70792),
  ('EXTENSIÓN DE PIERNA - DECÚBITO VENTRAL - AMPUTADOS - SUPRARROTULIANA O INFRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Colocá una toalla enrollada o una almohada doblada entre los muslos y después acostate boca abajo. Después, elevá las piernas despegándolas del piso. Mantené, relajá y repetí.', 70796),
  ('ESTIRAMIENTO DE ISQUIOTIBIALES SENTADO CON PIERNAS EXTENDIDAS - AMPUTADOS - INFRARROTULIANA O SUPRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Sentate en una superficie plana y elevada donde puedas apoyar la pierna, como una camilla, un sillón o la cama. Inclinate lentamente hacia adelante desde el tronco y estirá las manos hacia adelante hasta sentir un estiramiento suave en la parte de atrás del muñón y de los glúteos. Mantené, volvé a la posición inicial y repetí.', 70671),
  ('FLEXIÓN DE BRAZOS MODIFICADA - AMPUTADOS - INFRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Acostado boca abajo, usá los brazos para empujarte hacia arriba, como se muestra. Mantené las rodillas en contacto con el piso y la espalda derecha todo el tiempo.', 70654),
  ('ELEVACIÓN PÉLVICA - DECÚBITO LATERAL - AMPUTADOS - INFRARROTULIANA O SUPRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Acostate del lado del muñón. Colocá una toalla debajo del muñón y usá el brazo de arriba para estabilizarte. Empezá elevando la pierna de arriba despegándola del piso. Después, elevá la cadera del piso empujando el muñón contra la toalla. Mantené, relajá y repetí.', 70788),
  ('FLEXIÓN DE BRAZOS - AMPUTADOS - INFRARROTULIANA O SUPRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Acostado boca abajo, usá los brazos para empujarte hacia arriba, como se muestra. Bajá y repetí. Mantené los dedos del pie sano en contacto con el piso y la espalda derecha todo el tiempo.', 70668),
  ('ACTIVACIÓN DE CUÁDRICEPS - DECÚBITO VENTRAL - AMPUTADOS - INFRARROTULIANA', NULL, true, 'pasivo', 'Especiales', 'Amputados', 'Acostate boca abajo con una toalla enrollada debajo de la pierna del muñón. Después, extendé completamente la rodilla. Mantené, relajá y repetí.', 70653),
  ('ACTIVACIÓN DE CUÁDRICEPS CON FLEXIÓN DE CADERA - DECÚBITO VENTRAL - AMPUTADOS - INFRARROTULIANA', NULL, true, 'pasivo', 'Especiales', 'Amputados', 'Acostate boca abajo con una toalla enrollada debajo de la pierna del muñón. Después, extendé completamente la rodilla y mantené mientras elevás la pelvis. Mantené, relajá y repetí.', 70652),
  ('ESTIRAMIENTO DE CUÁDRICEPS - DECÚBITO LATERAL - AMPUTADOS - INFRARROTULIANA', NULL, true, 'pasivo', 'Especiales', 'Amputados', 'Acostate de costado con el muñón arriba. Después, agarrá el muñón por debajo de la rodilla y llevá la rodilla a una posición más flexionada hasta sentir un estiramiento en la parte de adelante del muslo.', 70786),
  ('DESLIZARSE Y GIRAR - TRASLADO DE PESO - AMPUTADOS - INFRARROTULIANA O SUPRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Sentado en una silla, elevá los brazos hacia los costados. Después, inclinate lentamente hacia adelante y alterná el traslado del peso de un glúteo al otro mientras te deslizás hacia adelante en la silla. Después, invertí la dirección mientras te deslizás hacia atrás en la silla. Mantené el equilibrio todo el tiempo.', 70793),
  ('FONDOS SENTADO CON TOALLAS - AMPUTADOS - SUPRARROTULIANA O INFRARROTULIANA', NULL, true, 'fortalecimiento', 'Especiales', 'Amputados', 'Sentado en una superficie firme, colocá dos toallas enrolladas a cada lado tuyo, como se muestra. Después, apoyá las manos sobre las toallas y empujá el cuerpo hacia arriba de modo que la cola se despegue del asiento y el pie sano se despegue del piso. Bajá y repetí.', 70669),
  ('ADUCCIÓN DE CADERA EN DECÚBITO LATERAL - AMPUTADOS - SUPRARROTULIANA O INFRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Acostate de costado con el muñón abajo y después elevá el muñón hacia el techo. Bajá y repetí.', 70663),
  ('PUENTE A UNA PIERNA - AMPUTADOS - INFRARROTULIANA O SUPRARROTULIANA', NULL, true, 'fortalecimiento', 'Especiales', 'Amputados', 'Acostate boca arriba con una toalla enrollada debajo del muñón. Después, elevá la pierna sana despegándola del piso. Después, presioná el muñón hacia abajo contra la toalla mientras elevás la pelvis del piso. Mantené, bajá y repetí.', 70658),
  ('APOYO EN UNA PIERNA - AMPUTADOS - INFRARROTULIANA - SUPRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Parate en una pierna y mantené el equilibrio. Si hace falta, usá un andador o una mesada como apoyo adicional para el equilibrio.', 71656),
  ('EXTENSIÓN DE TRONCO Y PIERNA - DECÚBITO VENTRAL - AMPUTADOS - SUPRARROTULIANA O INFRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Colocá una toalla enrollada o una almohada doblada entre los muslos y después acostate boca abajo. Después, elevá la cabeza, el pecho y las piernas despegándolos del piso. Mantené, relajá y repetí.', 70795),
  ('ROTACIÓN DE TRONCO - DECÚBITO LATERAL - AMPUTADOS - SUPRARROTULIANA O INFRARROTULIANA', NULL, true, 'pasivo', 'Especiales', 'Amputados', 'Acostado de costado con el muñón arriba, agarrá el muslo del muñón con la mano de abajo. Después, llevá el brazo de arriba hacia atrás mientras rotás la cabeza y el tronco hasta sentir un estiramiento suave a lo largo de la columna y la cadera. Mantené, relajá y repetí.', 70794),
  ('TRASLADO DE PESO - ADELANTE Y ATRÁS - AMPUTADO - INFRARROTULIANA O SUPRARROTULIANA', NULL, true, 'activo', 'Especiales', 'Amputados', 'Sentado en una silla, elevá los brazos hacia los costados. Después, inclinate lentamente hacia adelante y hacia atrás manteniendo el equilibrio. Repetí.', 70791),
  ('SALTAR A LA SOGA - INVERSO', NULL, true, 'activo', 'Especiales', 'Cardio', 'Hacé girar la soga hacia atrás (por encima de la cabeza en dirección a la espalda) saltando por encima de ella con los dos pies. Repetí.', 61150),
  ('OXÍMETRO DE PULSO', NULL, true, 'activo', 'Especiales', 'Cardio', 'Hacé varias respiraciones profundas y después usá un oxímetro de pulso para controlar tu saturación de oxígeno (SpO2) y tu frecuencia cardíaca (FC). Los niveles normales de saturación de oxígeno van de 94% a 100%. La frecuencia cardíaca normal es de 60 a 100 latidos por minuto (LPM).', 82670),
  ('GOLPES CRUZADOS SENTADO', NULL, true, 'activo', 'Especiales', 'Cardio', 'Sentado en una silla, extendé el brazo hacia adelante y cruzando la línea media del cuerpo, como si dieras un golpe de puño. Repetí este movimiento alternando de lado a lado. Usá movimientos suaves y controlados.', 163288),
  ('TOQUES DE GLOBO - ARRODILLADO CON COMPAÑERO', NULL, true, 'activo', 'Especiales', 'Varios; Neurológico', 'Arrodillado, pedile a alguien que te tire un globo. Usá la mano y los dedos para devolvérselo con un toque a la persona que te ayuda. Repetí.', 147453),
  ('TOQUES DE GLOBO - SENTADO CON COMPAÑERO - UN SOLO BRAZO', NULL, true, 'activo', 'Especiales', 'Varios; Neurológico', 'Sentado, pedile a alguien que te tire un globo. Usá la mano y los dedos del brazo que querés trabajar para devolvérselo con un toque a la persona que te ayuda. Repetí.', 147361),
  ('TOQUES DE GLOBO - CON COMPAÑERO', NULL, true, 'activo', 'Especiales', 'Varios; Neurológico', 'De pie, pedile a alguien que te tire un globo. Usá la mano y los dedos para devolvérselo con un toque a la persona que te ayuda. Repetí.', 147378),
  ('TOQUES DE GLOBO - CON COMPAÑERO - UN SOLO BRAZO', NULL, true, 'activo', 'Especiales', 'Varios; Neurológico', 'De pie, pedile a alguien que te tire un globo. Usá la mano y los dedos del brazo que querés trabajar para devolvérselo con un toque a la persona que te ayuda. Repetí.', 147377),
  ('TOQUES DE GLOBO - MEDIA RODILLA CON COMPAÑERO', NULL, true, 'activo', 'Especiales', 'Neurológico', 'En posición de media rodilla, pedile a alguien que te tire un globo. Usá la mano y los dedos para devolvérselo con un toque a la persona que te ayuda. Repetí.', 147451),
  ('TOQUES DE GLOBO - SENTADO CON COMPAÑERO', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Sentado, pedile a alguien que te tire un globo. Usá la mano y los dedos para devolvérselo con un toque a la persona que te ayuda. Repetí.', 147359),
  ('TOQUES DE GLOBO CONTRA LA PARED', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Parate cerca de una pared y tirá un globo contra ella. Usá la mano y los dedos para golpear el globo repetidamente contra la pared sin dejar que caiga al piso.', 147357),
  ('CEPILLARSE O PEINARSE EL PELO', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Agarrá un cepillo o un peine y empezá a cepillarte o peinarte el pelo. Tratá de elevar el cepillo hasta la parte de arriba de la cabeza y peinarte por todos los costados.', 130982),
  ('APILADO DE VASOS - MULTIDIRECCIONAL', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Pegá trozos de cinta de color sobre una mesa para marcar el lugar donde vas a apilar los vasos. Empezá con todos los vasos apilados sobre uno de los trozos de cinta. Después, agarrá un vaso por vez y colocalo en otra zona de la mesa, de modo que cubra otro trozo de cinta. Repetí hasta que los vasos queden apilados y trasladados a todas las ubicaciones marcadas.', 139286),
  ('APILADO DE VASOS - PIRÁMIDE', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Colocá una pila de vasos sobre una mesa. Después, agarrá un vaso y llevalo al centro de la mesa. Seguí agarrando un vaso por vez y apilalos formando una pirámide, como se muestra. Una vez completada la pirámide, empezá a sacar los vasos de a uno y devolvelos a su posición original. Repetí.', 139287),
  ('APILADO DE VASOS CON CARGA DE PESO EN MIEMBRO SUPERIOR', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Sentate en una silla con una mesa de un lado y una pila chica de vasos del lado opuesto. Apoyá la mano sobre el asiento de la silla con el codo completamente extendido. Cargá peso sobre el brazo manteniendo el codo estirado. Se puede usar una férula de codo si el codo no logra mantener la extensión completa. Empezá agarrando un vaso por vez y pasándolo de un lado del cuerpo al otro, sobre la mesa. Repetí hasta apilar todos los vasos.', 139292),
  ('EQUILIBRIO ARRODILLADO', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Empezá en posición de gateo, sobre las manos y las rodillas. Elevate despegando las manos hasta quedar arrodillado, como se muestra. Mantené, volvé a la posición inicial y repetí.', 164054),
  ('PUENTE DESDE ASIENTO BAJO', NULL, true, 'fortalecimiento', 'Especiales', 'Neurológico', 'Sentate en un banquito con una silla detrás tuyo. Apoyá las manos sobre el asiento de la silla que está atrás, activá los músculos abdominales bajos, apretá los glúteos y después elevá la cola despegándola del banquito para formar un puente con el cuerpo. Mantené, después bajá hasta quedar sentado y repetí.', 139314),
  ('SENTADO A DE PIE PARCIAL - CUÑA', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Sentate en una silla y apoyá el pie del lado afectado sobre una cuña de espuma. Esto ayuda a reducir la inversión excesiva del tobillo. Colocá una cinta firme justo por encima de ambas rodillas. Esto ayuda a evitar que las rodillas y las caderas se separen. Colocá el otro pie al lado de la pierna afectada, separados al ancho de las caderas. Elevate hasta una posición de pie parcial, sin llegar a pararte del todo, y después volvé a sentarte y repetí. Si necesitás, podés agarrarte de otra silla o de una mesada.', 140969),
  ('SENTADO A DE PIE PARCIAL - CUÑA', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Sentate en una silla y apoyá el pie del lado afectado sobre una cuña de espuma. Esto puede ayudar a reducir la inversión excesiva del tobillo. Colocá el otro pie alineado con la pierna afectada. Después, elevate hasta una posición de pie parcial, sin llegar a pararte del todo, y después volvé a sentarte y repetí. Si necesitás, podés agarrarte de otra silla o de una mesada.', 139583),
  ('SENTADO A DE PIE PARCIAL - CUÑA Y BLOQUE', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Sentate en una silla y apoyá el pie del lado afectado sobre una cuña de espuma. Esto puede ayudar a reducir la inversión excesiva del tobillo. Apoyá el otro pie sobre un bloque de yoga, ya que esto ayuda a distribuir más peso sobre la pierna afectada (la que está sobre la cuña). Después, elevate hasta una posición de pie parcial, sin llegar a pararte del todo, y después volvé a sentarte y repetí. Si necesitás, podés agarrarte de otra silla o de una mesada.', 139581),
  ('SENTADO A DE PIE PARCIAL - CUÑA Y PIES EN TIJERA', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Sentate en una silla y apoyá el pie del lado afectado sobre una cuña de espuma. Esto ayuda a reducir la inversión excesiva del tobillo. Colocá el otro pie más adelantado respecto de la otra pierna. Esto ayuda a distribuir más peso sobre la pierna afectada (la que está sobre la cuña). Después, elevate hasta una posición de pie parcial, sin llegar a pararte del todo, y después volvé a sentarte y repetí. Si necesitás, podés agarrarte de otra silla o de una mesada.', 139582),
  ('DE PIE A SENTADO PARCIAL', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Parate con una silla detrás tuyo. Hacé una sentada parcial flexionando levemente las rodillas y las caderas, y después volvé a pararte del todo con las rodillas completamente estiradas. Repetí. Si necesitás, podés empujar el muslo hacia atrás con las manos mientras intentás pararte.', 139329),
  ('ESTIRAMIENTO DE ROTACIÓN EXTERNA EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Empezá acostado boca abajo con el brazo que querés trabajar hacia el costado y el codo flexionado, como se muestra. Después, pasá la pierna del lado opuesto cruzando la línea media y usá el otro brazo para levantar y rotar el cuerpo hasta sentir un estiramiento suave en el hombro y el pecho del lado trabajado. Mantené, volvé a la posición inicial y repetí.', 141157),
  ('FLEXIÓN DE HOMBRO CON BASTÓN DE 4 PATAS - SUJETO EN LOS CODOS', NULL, true, 'activo_asistido', 'Especiales', 'Neurológico', 'Acostate boca arriba. Sostené un bastón de 4 patas y colocá una cinta justo por encima de los codos, como se muestra. Esto ayuda a evitar que los brazos se abran demasiado hacia los costados. Elevá el bastón por encima de la cabeza y después bajá a la posición inicial. Repetí.', 141163),
  ('ABDUCCIÓN Y ADUCCIÓN HORIZONTAL DE HOMBRO - BASTÓN DE 4 PATAS INVERTIDO', NULL, true, 'activo_asistido', 'Especiales', 'Neurológico', 'Colocá un bastón de 4 patas invertido en el piso y pisá el mango. Colocá el brazo afectado entre las patas de la base del bastón. Movés el brazo de lado a lado mientras el bastón sostiene el brazo y pivotea sobre el piso.', 141156),
  ('ROTACIÓN INTERNA Y EXTERNA DE HOMBRO - BASTÓN DE 4 PATAS INVERTIDO', NULL, true, 'pasivo; activo_asistido', 'Especiales', 'Neurológico', 'Colocá un bastón de 4 patas invertido en el piso, al lado del pie. Colocá la mano afectada entre las patas de la base del bastón y sujetala firme con una cinta. Sostené el brazo contra el costado del cuerpo con la otra mano. Movés el brazo de lado a lado mientras el bastón sostiene el brazo y pivotea sobre el piso.', 141160),
  ('CARGA DE PESO EN MIEMBRO SUPERIOR - DE PIE DANDO UN PASO', NULL, true, 'activo', 'Especiales', 'Neurológico', 'De pie, apoyá la mano sobre una mesa que esté a tu lado manteniendo el codo completamente estirado. Trasladá el peso del cuerpo sobre el brazo apoyado y después dá un paso adelante con una pierna. Mantené, después volvé con el paso a la posición inicial y repetí.', 140967),
  ('CAMINAR CON FLEXIÓN Y EXTENSIÓN CERVICAL', NULL, true, 'activo', 'Especiales', 'Neurológico', 'Caminá hacia adelante mientras movés la cabeza hacia arriba y hacia abajo. Después, caminá hacia atrás siguiendo con el movimiento de la cabeza hacia arriba y abajo.', 164276),
  ('PEDIÁTRICO - MARCHA ASISTIDA INESTABLE', NULL, true, 'activo_asistido', 'Especiales', 'Pediátrico', 'Colocá almohadas, almohadones o una manta doblada en el piso y ayudá al chico a caminar por encima. Dejá que el chico haga la mayor parte del trabajo posible sin caerse.', 118356),
  ('PEDIÁTRICO - CAMINATA ASISTIDA', NULL, true, 'activo_asistido', 'Especiales', 'Pediátrico', 'Sentate en una silla o banqueta con ruedas y ayudá al chico a pararse y dar pasos.', 118404),
  ('PEDIÁTRICO - ESTIRAMIENTO EN INCLINACIÓN LATERAL CERVICAL', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al chico en el piso o la cama y sostené el hombro hacia abajo mientras llevás la cabeza hacia el lado opuesto, para un estiramiento suave del cuello, como se muestra.', 118406),
  ('PEDIÁTRICO - BEBÉ - ABDOMINALES ASISTIDOS', NULL, true, 'fortalecimiento', 'Especiales', 'Pediátrico', 'Acostá al bebé boca arriba. Colocá una mano detrás de la cabeza y la parte alta de la espalda del bebé y sostenele las manos, como se muestra. Después, ayudá al bebé a hacer un abdominal. Bajalo de nuevo y volvé a acostarlo boca arriba. Repetí.', 182560),
  ('PEDIÁTRICO - BEBÉ - BICICLETA', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al bebé boca arriba y agarrale las piernas por debajo de la rodilla, como se muestra. Movés suavemente las dos piernas en direcciones opuestas, como si pedaleara en bicicleta: estirá una pierna mientras flexionás la rodilla y la cadera de la otra hacia la panza del bebé.', 182119),
  ('PEDIÁTRICO - BEBÉ - DOBLE RODILLA AL PECHO', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al bebé boca arriba y agarrale los tobillos. Movés suavemente las dos piernas hacia la panza del bebé. Después, bajá las piernas de nuevo. Repetí.', 182120),
  ('PEDIÁTRICO - BEBÉ - AGARRARSE LOS PIES NIVEL 1', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Sentate en el piso con las rodillas flexionadas, como se muestra. Colocá al bebé sobre tu falda de modo que la pelvis del bebé quede en retroversión, apoyada contra tu panza. Ayudá al bebé a agarrarse sus propios pies, como se muestra. Hamacá las piernas del bebé hacia arriba y abajo y de lado a lado. Esto puede ayudar al bebé con la conciencia corporal, el posicionamiento en la línea media y la mirada hacia abajo.', 182885),
  ('PEDIÁTRICO - BEBÉ - AGARRARSE LOS PIES NIVEL 2', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Sentate en el piso con las piernas levemente flexionadas, como se muestra. Colocá al bebé sobre tu falda de modo que la pelvis quede sostenida en retroversión contra tu panza. Ayudá al bebé a agarrarse los propios pies, como se muestra. Hamacá las piernas del bebé hacia arriba y abajo y de lado a lado. Esto ayuda al bebé con la conciencia corporal, el posicionamiento en la línea media y la mirada hacia abajo.', 182887),
  ('PEDIÁTRICO - BEBÉ - AGARRARSE LOS PIES NIVEL 3', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Colocá al bebé en el piso. Ayudalo a agarrarse los propios pies, como se muestra. Hamacalo suavemente hacia adelante y atrás y también de lado a lado. Esto ayuda al bebé con la conciencia corporal, el posicionamiento en la línea media y la mirada hacia abajo.', 182888),
  ('PEDIÁTRICO - BEBÉ - MANO AL PIE', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al bebé boca arriba. Agarrá la mano del bebé y el pie contrario, como se muestra. Movés suavemente la mano y el pie uno hacia el otro hasta que se toquen. Volvé a la posición inicial y repetí.', 181850),
  ('PEDIÁTRICO - BEBÉ - HAMACADO LATERAL - CONTROL DE CABEZA Y CUELLO', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Colocá al bebé sobre tu falda mirando hacia afuera. Sostenelo alrededor del pecho y la panza, contra tu cuerpo. Después, hamacalo suavemente de lado a lado para que contraiga los músculos del cuello y trabaje la estabilización y el control cefálico.', 182117),
  ('PEDIÁTRICO - BEBÉ - HAMACADO LATERAL - CONTROL DE CABEZA Y CUELLO', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Sentá al bebé. Sostenelo alrededor del pecho y la panza, apoyando el tronco. Después, hamacalo suavemente de lado a lado para que contraiga los músculos del cuello y trabaje la estabilización y el control cefálico. Hamacá solo dentro del rango que el bebé pueda controlar.', 182561),
  ('PEDIÁTRICO - BEBÉ - ROTACIÓN CERVICAL Y SEGUIMIENTO EN DECÚBITO VENTRAL', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al bebé boca abajo, apoyado sobre los codos. Sostené un juguete nuevo o preferido y movelo despacio hacia un costado para estimular la rotación de la cabeza. Después, llevá el juguete hacia el otro lado de la cabeza para estimular la rotación hacia el lado contrario.', 182118),
  ('PEDIÁTRICO - BEBÉ - HAMACADO LATERAL EN DECÚBITO VENTRAL - CONTROL DE CABEZA Y CUELLO', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al bebé boca abajo, apoyado sobre los codos. Hamacalo despacio de lado a lado y hacia adelante y atrás para facilitar el control lateral de la cabeza y el cuello.', 182891),
  ('PEDIÁTRICO - BEBÉ - SENTADO - HAMACADO HACIA ADELANTE - CONTROL DE CABEZA Y CUELLO', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Sentá al bebé. Sostenelo alrededor del pecho y la panza, apoyando el tronco. Después, hamacalo suavemente hacia adelante y atrás para que contraiga los músculos del cuello y trabaje la estabilización y el control cefálico. Hamacá solo dentro del rango que el bebé pueda controlar.', 182565),
  ('PEDIÁTRICO - BEBÉ - HAMACADO SENTADO ADELANTE/ATRÁS - CONTROL DE CABEZA Y CUELLO', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Ubicá al bebé sentado sobre tu falda. Sostenelo alrededor del pecho. Hamacalo despacio hacia adelante y atrás para facilitar el control de la cabeza y el cuello.', 182115),
  ('PEDIÁTRICO - BEBÉ - HAMACADO LATERAL SENTADO - CONTROL DE CABEZA Y CUELLO', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Ubicá al bebé sentado sobre tu falda. Sostenelo alrededor de los hombros y usá los dedos índice para ayudar a mantener la cabeza erguida si hace falta. Hamacalo despacio de lado a lado para facilitar el control lateral de la cabeza y el cuello.', 182116),
  ('PEDIÁTRICO - BEBÉ - HAMACADO LATERAL SENTADO - CONTROL DE CABEZA Y CUELLO 2', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Colocá al bebé sentado sobre tu falda. Sostenelo alrededor del pecho y la panza. Hamacalo despacio de lado a lado y hacia adelante y atrás para facilitar el control lateral de la cabeza y el cuello.', 182892),
  ('PEDIÁTRICO - BEBÉ - ALCANCE SENTADO', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Sostené al bebé sentado sobre tu falda. Colocá un juguete nuevo o preferido adelante suyo para estimular que levante los brazos, se estire hacia adelante y acerque el juguete. Repetí.', 182566),
  ('PEDIÁTRICO - BEBÉ - ROTACIÓN CERVICAL Y SEGUIMIENTO EN DECÚBITO DORSAL', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al bebé boca arriba. Sostené un juguete nuevo o preferido y movelo despacio de lado a lado para estimular la rotación del cuello y la cabeza.', 182567),
  ('PEDIÁTRICO - BEBÉ - APERTURAS EN DECÚBITO DORSAL', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Empezá acostando al bebé boca arriba con los brazos arriba, sobre el pecho, como se muestra. Después, bajá los brazos horizontalmente hacia los costados. Repetí.', 181849),
  ('PEDIÁTRICO - BEBÉ - RODADOS DE TRONCO INFERIOR EN DECÚBITO DORSAL', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al bebé boca arriba y agarrá las piernas por debajo de las rodillas, como se muestra. Flexioná suavemente las caderas hacia arriba, cruzá por delante del cuerpo y después bajá las piernas, siguiendo este movimiento en un patrón circular. Hacelo varias veces y después invertí la dirección.', 182568),
  ('PEDIÁTRICO - BEBÉ - ROTACIONES DE TRONCO INFERIOR EN DECÚBITO DORSAL - LTR', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al bebé boca arriba y agarrá las piernas por debajo de las rodillas, como se muestra. Rotá suavemente las rodillas y el tronco inferior de lado a lado.', 181851),
  ('PEDIÁTRICO - BEBÉ - FLEXIÓN DE HOMBROS POR ENCIMA DE LA CABEZA EN DECÚBITO DORSAL', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al bebé boca arriba. Agarrá las manos o las muñecas del bebé y llevalas cerca de la panza. Después, subí los brazos hacia arriba y por encima de la cabeza. Volvé a la posición inicial y repetí.', 181848),
  ('PEDIÁTRICO - BEBÉ - RODADO DE DECÚBITO DORSAL A VENTRAL', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al bebé boca arriba. Agarrá la mano del bebé y tirá suavemente para ayudarlo a rodar y quedar boca abajo.', 182890),
  ('PEDIÁTRICO - ESTIRAMIENTO EN ROTACIÓN DE CUELLO', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Colocá al nene sobre tu falda, mirándote. Dejá que rote la cabeza hacia el costado y ayudalo a sostener esa posición para un estiramiento suave en rotación del cuello.', 118365),
  ('PEDIÁTRICO - ESTIRAMIENTO EN ROTACIÓN DE CUELLO 2', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Dejá que el nene rote la cabeza hacia el costado y ayudalo a sostener esa posición para un estiramiento suave en rotación. Podés cruzar un brazo por delante del pecho del nene y usar 2 dedos sobre el costado de la cabeza para acompañar el estiramiento. Se puede hacer sentado o de pie mientras lo sostenés.', 118366),
  ('PEDIÁTRICO - INCLINACIÓN LATERAL SENTADO SOBRE PELOTA', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Sentado, empezá colocando al nene sobre una pelota de ejercicios mientras le estabilizás la pelvis. Después, inclina la pelvis del nene hacia el costado. El nene tiene que intentar corregir la columna y la cabeza inclinándolas lateralmente hacia una posición más erguida. Mantené, volvé a la posición inicial y repetí.', 118370),
  ('PEDIÁTRICO - INCLINACIÓN HACIA ADELANTE SENTADO', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Sentado, empezá colocando al nene sobre tu falda mientras le estabilizás la pelvis. Después, inclina la pelvis del nene hacia adelante. El nene tiene que intentar corregir desde la columna y la cabeza, extendiéndolas para no caerse hacia adelante. Mantené, volvé a la posición inicial y repetí.', 118368),
  ('PEDIÁTRICO - ESTIRAMIENTO EN DESCENSO DE HOMBROS', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Acostá al nene en el piso y descendé los hombros, como se muestra. Mantené para un estiramiento suave. Relajá y repetí.', 118362),
  ('PEDIÁTRICO - ÁNGELES EN LA NIEVE', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Hacé que el nene se acueste en el piso. Empezá con los brazos al costado del cuerpo y las piernas juntas. Después, que deslice los brazos hacia arriba, por encima de la cabeza, mientras al mismo tiempo separa las piernas, como se muestra. Después, que deslice brazos y piernas a la posición inicial y repetí.', 118418),
  ('CARRETILLA SOBRE PELOTA MANÍ', NULL, true, 'activo', 'Especiales', 'Pediátrico', 'Colocá al nene boca abajo sobre una pelota maní y rodá la pelota hacia adelante para que pueda apoyar las manos en el piso. Estimulalo a mantener la cabeza en alto mientras carga algo de peso a través de los miembros superiores.', 118371),
  ('POSTURA DE LOS 8 APOYOS - YOGA - ASHTANGA NAMASKARA', NULL, true, 'activo', 'Especiales', 'Yoga', 'Empezá en posición de gateo y después bajá el pecho al piso de modo que el cuerpo toque el piso en 8 puntos (2 pies, 2 manos, 2 rodillas, mentón y pecho). Mantené la zona lumbar arqueada hacia adelante (en extensión). Sostené esta posición.', 65095),
  ('POSTURA DEL ARCO - YOGA - DHANURASANA', NULL, true, 'activo', 'Especiales', 'Yoga', 'Empezá boca abajo y flexioná las rodillas. Estirate hacia atrás, agarrate los pies con las manos y después empujá las piernas contra las manos mientras los brazos tiran hacia adelante. Elevá el pecho, las rodillas y la cabeza hacia el techo. Sostené esta posición.', 65097),
  ('POSTURA DEL PUENTE - YOGA - SETU BANDHASANA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Acostate boca arriba con las rodillas flexionadas y los pies separados al ancho de las caderas. Caminá con los pies lo más cerca posible de la cola. Agarrate los tobillos y después elevá la cola y la columna del piso lo más alto posible. Sostené esta posición.', 65098),
  ('POSTURA DEL CAMELLO - YOGA - USTRASANA', NULL, true, 'activo', 'Especiales', 'Yoga', 'Empezá arrodillado. Después, inclinate hacia atrás arqueando la columna en extensión mientras llevás cada brazo hacia atrás para agarrarte los talones. Dejá que la cabeza también se extienda. Sostené esta posición.', 65099),
  ('POSTURA DEL ÁGUILA - YOGA - GARUDASANA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Empezá en postura de la silla (rodillas flexionadas, bisagra desde las caderas sin que las rodillas pasen los dedos de los pies, brazos por encima de la cabeza). Activá los músculos abdominales llevando el ombligo hacia la columna. Después, llevá los brazos por delante del pecho y enroscalos uno alrededor del otro, como se muestra: un codo sobre el otro y las palmas enroscadas hasta tocarse. Después, parate sobre una pierna y enroscá la pierna libre alrededor de la pierna de apoyo, de adelante hacia atrás. Si no podés enroscar los brazos, cruzalos sobre el pecho con los codos apuntando hacia adelante. Si no podés enroscar la pierna libre por delante y atrás de la pierna de apoyo, cruzala solo por delante. Si te cuesta mantener el equilibrio en una pierna, apoyá el pie de la pierna libre sobre un bloque. Sostené esta posición. Respiración diafragmática lenta y profunda todo el tiempo.', 65023),
  ('POSTURA DEL ÁNGULO LATERAL EXTENDIDO - YOGA - MANO EN EL PISO - PARSVAKONASANA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Empezá parado en posición de estocada con los dedos del pie de adelante apuntando hacia adelante y los del pie de atrás apuntando hacia el costado (posición de pies del guerrero 2 de yoga). Después, inclinate hacia adelante y apoyá la mano o las yemas de los dedos en el piso, y estirá el otro brazo hacia arriba y por encima de la cabeza, como se muestra. Girá la cabeza para mirar la mano que está arriba. Sostené esta posición. Como variantes, la mano de adelante puede apoyarse en el piso hacia adentro de la rodilla para trabajar la cara interna del muslo, o por fuera de la rodilla para trabajar la cara externa. Si necesitás más apoyo para el equilibrio, apoyá la mano de adelante sobre un bloque de yoga en vez de directamente en el piso. Respiración diafragmática lenta y profunda todo el tiempo.', 65018),
  ('POSTURA DEL PEZ - YOGA - MATSYASANA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Acostate boca arriba. Después, colocá las manos debajo de la cola. Después, hacé un crunch parcial elevando el pecho y la cabeza. Después, arqueá la espalda y el cuello en extensión de modo que la cabeza quede apoyada en el piso y el pecho se eleve hacia el techo. Sostené esta posición.', 65100),
  ('POSTURA DE LA PLANCHA - YOGA - CHATURANGA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Empezá en posición de gateo. Después, activá los músculos abdominales y estirá las piernas para sostener el tronco en plancha completa. Las puntas de los pies y las manos deben sostener el cuerpo con la columna derecha. Después, bajá el cuerpo flexionando los codos hasta unos 90 grados. Los codos deben quedar cerca del costado del cuerpo. Las manos y las puntas de los pies sostienen el peso del cuerpo. Sostené esta posición.', 65127),
  ('POSTURA DE LA PLANCHA MODIFICADA - YOGA - CHATURANGA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Empezá en posición de gateo. Después, activá los músculos abdominales y bajá el tronco hacia el piso para alinear la columna. Después, flexioná los codos para bajar el cuerpo todavía más, hasta llegar a unos 90 grados de flexión de codos. No dejes que la panza toque el piso. Las rodillas y las manos deben sostener el cuerpo con la columna derecha. Sostené esta posición.', 65063),
  ('POSTURA DE LA PLANCHA CON BLOQUES - YOGA - CHATURANGA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Empezá en posición de gateo. Después, activá los músculos abdominales y estirá las piernas para sostener el tronco en plancha completa. Las puntas de los pies y las manos deben sostener el cuerpo con la columna derecha. Después, bajá el cuerpo flexionando los codos hasta unos 90 grados, de modo que los hombros queden apoyados sobre bloques de yoga, como se muestra. Los codos deben quedar cerca del costado del cuerpo. Las manos, las puntas de los pies y los hombros sobre los bloques sostienen el peso del cuerpo. Sostené esta posición.', 65061),
  ('POSTURA DE LA PLANCHA CON BLOQUES Y MANOS ELEVADAS - YOGA - CHATURANGA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Empezá en posición de gateo. Después, activá los músculos abdominales, estirá las piernas y sostené el tronco en posición de plancha completa. Las puntas de los pies y las manos deben sostener el cuerpo con la columna derecha. Después, bajá el cuerpo flexionando los codos hasta unos 90 grados, de modo que los hombros se apoyen sobre bloques de yoga, como se muestra. Los codos deben quedar cerca del costado del cuerpo. Por último, despegá las manos del piso y mantené esta posición. Solo las puntas de los pies y los hombros sobre los bloques deben sostener el peso del cuerpo. Mantené esta posición.', 65059),
  ('POSTURA DEL ARADO - YOGA - HALASANA', NULL, true, 'activo', 'Especiales', 'Yoga', 'Acostate boca arriba y después elevá las piernas hacia arriba y por encima de la cabeza con las rodillas estiradas. Usá las manos para ayudar a la espalda hacia arriba y dejá que las piernas lleguen por detrás de la cabeza hasta que los pies toquen el piso. Mantené esta posición.', 65101),
  ('POSTURA DEL GUERRERO INVERTIDO - YOGA - VIPARITA VIRABHADRASANA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Activá los músculos abdominales llevando el ombligo hacia adentro, en dirección a la columna. Parate en posición de estocada con los dedos del pie de adelante apuntando hacia adelante y los del pie de atrás hacia el costado (posición de pies del guerrero 2 de yoga). Colocá un brazo detrás de la espalda o deslizalo por la pierna de atrás. Estirá el otro brazo hacia arriba y por encima de la cabeza, alargando ese costado del tronco. Inclinate levemente hacia atrás con el tronco mientras mirás el brazo que está por encima de la cabeza. Mantené esta posición.', 65022),
  ('ESTIRAMIENTO DE ESPALDA SENTADO - YOGA', NULL, true, 'activo', 'Especiales', 'Yoga', 'Empezá sentado con las piernas cruzadas. Después, inclinate hacia adelante y apoyá las manos en el piso. Caminá con las manos hacia adelante hasta sentir un estiramiento suave a lo largo de la espalda. Mantené y después volvé a la posición inicial. Respiración diafragmática lenta y profunda todo el tiempo.', 65069),
  ('ESTIRAMIENTO DE ESPALDA SENTADO CON BLOQUE - YOGA', NULL, true, 'activo', 'Especiales', 'Yoga', 'Empezá sentado con las piernas cruzadas. Colocá un bloque de yoga debajo de la cola. Después, inclinate hacia adelante y apoyá las manos en el piso. Caminá con las manos hacia adelante hasta sentir un estiramiento suave a lo largo de la espalda. Mantené y después volvé a la posición inicial. Respiración diafragmática lenta y profunda todo el tiempo.', 65066),
  ('POSTURA DE LA VELA - YOGA - SARVANGASANA', NULL, true, 'activo', 'Especiales', 'Yoga', 'Acostate boca arriba y después elevá las piernas usando las manos para estabilizar la espalda. Las piernas deben apuntar derecho hacia el techo, como se muestra. Mantené esta posición.', 65102),
  ('POSTURA DEL ÁGUILA DORMIDA - YOGA - GARUDASANA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Empezá en postura de la silla (rodillas flexionadas, bisagra desde las caderas sin dejar que las rodillas pasen los dedos de los pies, brazos por encima de la cabeza). Activá los músculos abdominales llevando el ombligo hacia adentro, en dirección a la columna. Después, llevá los brazos por delante del pecho y enroscá un brazo alrededor del otro. Ubicá un codo por encima del otro con las manos enroscadas hasta tocarse. Después, parate en una pierna y enroscá la pierna libre alrededor de la pierna de apoyo, de adelante hacia atrás. Si no podés enroscar los brazos, simplemente cruzalos. Si no podés enroscar la pierna libre, simplemente cruzala por delante de la pierna de apoyo. Si te cuesta mantener el equilibrio en una pierna, apoyá el pie de la pierna libre sobre un bloque para tener más sostén. Esta es la postura del águila. Después podés pasar a la postura del águila dormida manteniendo esa posición y flexionándote hacia adelante para tocar el codo con alguna de las rodillas. Respiración diafragmática lenta y profunda todo el tiempo.', 65010),
  ('POSTURA DEL ÁRBOL - YOGA - VRKSASANA', NULL, true, 'fortalecimiento', 'Especiales', 'Yoga', 'Activá los músculos abdominales llevando el ombligo hacia adentro, en dirección a la columna. Parate en una pierna y apoyá la planta del pie sobre la cara interna del muslo de la pierna de apoyo, por encima de la línea articular de la rodilla, como se muestra. No apoyes el pie sobre la línea articular de la rodilla. La cadera de la pierna libre debe estar rotada hacia afuera, de modo que la rodilla apunte hacia el costado. Juntá las palmas de las manos a la altura del pecho o por encima de la cabeza. Mantené esta posición. Respiración diafragmática lenta y profunda todo el tiempo.', 65024),
  ('POSTURA LIBERADORA DE VIENTOS - YOGA - PAVANAMUKTASANA', NULL, true, 'activo', 'Especiales', 'Yoga', 'Acostate boca arriba y llevá las rodillas hacia el pecho. Abrazá las rodillas con los brazos. Después, elevá la cabeza hacia las rodillas. Mantené esta posición.', 65104),
  ('AVD - CEPILLARSE LOS DIENTES', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Cuando estés parado frente a la pileta para cepillarte los dientes, abrí la puerta del mueble y apoyá un pie sobre el estante para evitar flexionarte demasiado desde la cintura. Mantené la columna derecha. Si necesitás más apoyo, sostenete con el brazo en la mesada.', 49930),
  ('AVD - ARMADO ERGONÓMICO DEL ESCRITORIO DE PIE', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Parate frente al escritorio y usá un teclado ergonómico. El escritorio debe estar armado de modo que el monitor quede a la altura de los ojos o apenas por debajo. El codo debe estar flexionado a unos 90-110 grados. Se pueden hacer ajustes en la altura del monitor y del teclado (a través de la altura del escritorio) para lograr una alineación correcta. Si es posible, es preferible un escritorio eléctrico para poder ajustar la altura con solo apretar un botón.', 51417),
  ('AVD - ZONAS ERGONÓMICAS DEL ESCRITORIO', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Sentate derecho y armá el escritorio de modo que las cosas que más usás queden más cerca tuyo, en la zona frecuente. Las que usás menos seguido van más lejos. Tenés que poder alcanzar todos los elementos de la zona frecuente y de la zona menos frecuente solo estirando los brazos. La zona de uso raro puede quedar fuera del alcance de los brazos, lo que puede requerir flexionarte desde las caderas.', 49959),
  ('AVD - LEER UN LIBRO', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Cuando leas un libro, sentate con buena postura y elevá el libro para reducir la inclinación de la cabeza hacia abajo o hacia adelante.', 49952),
  ('AVD - USO DE CELULAR Y TABLET', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Cuando uses dispositivos electrónicos como una tablet o un celular, no te encorves ni dejes que la cabeza se adelante. Sostené el dispositivo en alto para verlo mejor y mantener una buena postura de la espalda y el cuello.', 50842),
  ('AVD - PASAR LA ASPIRADORA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Cuando pases la aspiradora, caminá con ella para reducir la necesidad de inclinarte. Además, extendé el mango, si es regulable, para mejorar el alcance. Mantené la columna derecha.', 49957),
  ('AVD - LAVAR LOS PLATOS - ALCANZAR ALACENAS ALTAS', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Cuando estés parado frente a la pileta, abrí las puertas del mueble de abajo y apoyá un pie sobre el estante. Esto reduce la presión sobre la espalda. Cuando te inclines hacia adelante, flexioná desde las caderas y no desde la espalda. Cuando tengas que alcanzar alacenas o estantes difíciles, subite a un banquito para evitar arquear la espalda. Mantené la columna derecha en todas las actividades.', 15323),
  ('MULETAS AXILARES - MARCHA EN DOS PUNTOS', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Adelantá la punta de la muleta de un lado mientras das un paso adelante con la pierna del lado contrario. Después, repetí del otro lado. Seguí con este patrón mientras caminás hacia adelante con las muletas. ALINEACIÓN: al dar un paso, el pie tiene que apoyarse en el piso alineado con la punta de la muleta del lado contrario.', 121179),
  ('MECÁNICA CORPORAL - LEVANTAR DESDE LA ALTURA DE LA RODILLA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Empezá parado cerca del objeto con los pies separados. Flexioná las rodillas y las caderas, NO la columna. Sostené el objeto cerca del cuerpo mientras usás las piernas para volver a pararte levantando el objeto. Caminá hasta la superficie donde lo querés apoyar y dejalo flexionando levemente las rodillas. No flexiones la columna. Además, asegurate de NO rotar la columna: pivoteá con los pies de modo que queden apuntando hacia donde querés dejar el objeto. Deslizá el objeto sobre el estante para descargar el cuerpo.', 14206),
  ('MECÁNICA CORPORAL - LEVANTAR POR ENCIMA DE LA CABEZA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Empezá parado cerca del objeto con los pies separados. Flexioná las rodillas y las caderas, NO la columna. Sostené el objeto cerca del cuerpo mientras usás las piernas para volver a pararte levantando el objeto. Caminá hasta la superficie donde lo querés apoyar y elevalo por encima de la cabeza con la técnica de una mano abajo y una mano arriba, como se muestra. Apoyalo y NO extiendas la columna. Además, asegurate de NO rotar la columna: pivoteá con los pies de modo que queden apuntando hacia donde querés dejar el objeto. Deslizá el objeto sobre el estante para descargar el cuerpo.', 14207),
  ('TÉCNICA DE RESPIRACIÓN', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Inspirá contando 4 segundos y espirá con los labios fruncidos contando 8 segundos.', 60874),
  ('TRANSFERENCIA AL AUTO', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Caminá hasta el lado del acompañante del vehículo. La ventanilla tiene que estar baja y el asiento corrido hacia atrás. Girá de modo que la parte de atrás de las piernas toque el auto. Pasá la mano al vehículo y después sentate. Después, apartá el andador y girá el tronco mientras subís las piernas hasta quedar sentado mirando hacia adelante.', 14083),
  ('ANATOMÍA CERVICAL', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Vértebras cervicales 1 a 7. A. Raíz nerviosa. B. Arteria vertebrobasilar.', 36743),
  ('TOALLA CERVICAL ENROLLADA DENTRO DE LA FUNDA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Enrollá una toalla chica de baño y colocala dentro de la funda de la almohada, cerca del borde inferior. Esto puede ayudar a mantener una buena curvatura de la columna cervical mientras estás acostado boca arriba o de costado. Ajustá el tamaño del rollo si hace falta para mayor comodidad.', 105296),
  ('MARCHA HACIA ADELANTE Y HACIA ATRÁS - MESADA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Caminá hacia adelante manteniendo una buena postura, usando la mesada como guía o apoyo para el equilibrio. Después, caminá hacia atrás usando la mano para el equilibrio si hace falta.', 165244),
  ('ENTRENAMIENTO DE LA MARCHA - SECUENCIA - APOYO NORMAL A PIE PLANO / ACEPTACIÓN DE CARGA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Empezá con ambos pies apoyados en el piso, separados unos centímetros. Después, trasladá el peso sobre el pie apoyado y balanceá la otra pierna hacia adelante. Apoyá suavemente el talón en el piso. Tratá de apoyar el talón en un lugar puntual y no arrastres el pie por el piso. Después, transferí el peso a ese pie y dejá que el apoyo del talón ruede hasta quedar plano en el piso. El otro pie debe terminar en apoyo terminal (dedos flexionados sobre la almohadilla del pie). Volvé a la posición inicial y repetí. Puede que necesites algo de dónde agarrarte para el equilibrio. También podés ampliar la base de apoyo si necesitás más sostén.', 95489),
  ('ENTRENAMIENTO DE LA MARCHA - SECUENCIA - APOYO TERMINAL A PIE PLANO / ACEPTACIÓN DE CARGA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Empezá con un pie apoyado en el piso y el otro sobre la almohadilla del pie con los dedos flexionados (apoyo terminal) y por detrás tuyo, como se ve en la imagen de arriba. Después, trasladá el peso sobre el pie apoyado y balanceá la otra pierna hacia adelante. Apoyá suavemente el talón en el piso. Tratá de apoyar el talón en un lugar puntual y no arrastres el pie por el piso. Después, transferí el peso a ese pie y dejá que el apoyo del talón ruede hasta quedar plano en el piso. El otro pie debe terminar en apoyo terminal (dedos flexionados sobre la almohadilla del pie). Volvé a la posición inicial y repetí. Puede que necesites algo de dónde agarrarte para el equilibrio. También podés ampliar la base de apoyo si necesitás más sostén.', 95495),
  ('ENTRENAMIENTO DE LA MARCHA - SECUENCIA - APOYO TERMINAL A CHOQUE DE TALÓN', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Empezá con un pie apoyado en el piso y el otro sobre la almohadilla del pie con los dedos flexionados (apoyo terminal) y por detrás tuyo, como se ve en la imagen de arriba. Después, trasladá el peso sobre el pie apoyado y balanceá la otra pierna hacia adelante (fase de balanceo). Apoyá suavemente el talón en el piso. Tratá de apoyar el talón en un lugar puntual y no arrastres el pie por el piso. Volvé a la posición inicial y repetí. Puede que necesites algo de dónde agarrarte para el equilibrio.', 95487),
  ('MARCHA CON BASTÓN - PATRÓN DE PASO HASTA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Adelantá el bastón y el pie afectado. El pie del lado afectado debe quedar alineado con el bastón. Después, empujá hacia abajo con los brazos y dá un paso adelante con la pierna sana de modo que quede alineada con la otra pierna. El bastón se usa en la mano contraria a la pierna afectada, salvo indicación distinta.', 14222),
  ('MARCHA CON MULETAS - SIN CARGA DE PESO (NWB)', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Mantené la pierna afectada sin tocar el piso. Adelantá las puntas de las muletas y después empujá hacia abajo con los brazos y saltá hacia adelante con la pierna sana. La pierna afectada no debe tocar el piso en ningún momento.', 14214),
  ('MARCHA CON MULETAS - CARGA DE PESO CON APOYO DE PUNTA (TTWB) - PATRÓN DE PASO A TRAVÉS', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Adelantá las puntas de las muletas y el pie afectado, pero permitiendo solo unos 5 a 10 kg de presión sobre la pierna afectada. Los dedos del pie afectado deben quedar alineados con las puntas de las muletas al avanzar. Después, empujá hacia abajo con los brazos y pasá con la pierna sana por delante de las puntas de las muletas. Repetí.', 14215),
  ('MARCHA CON MULETAS - CARGA DE PESO SEGÚN TOLERANCIA (WBAT) - PATRÓN DE PASO A TRAVÉS', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Adelantá las puntas de las muletas y el pie afectado. El pie del lado afectado debe quedar alineado con las puntas de las muletas. Después, empujá hacia abajo con los brazos y pasá con la pierna sana por delante de las puntas de las muletas. Podés cargar sobre la pierna afectada todo el peso que te resulte cómodo.', 14216),
  ('MARCHA CON ANDADOR CON RUEDAS DELANTERAS - SIN CARGA DE PESO (NWB)', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Mantené la pierna afectada sin tocar el piso. Adelantá el andador y después empujá hacia abajo con los brazos y saltá hacia adelante con la pierna sana. El pie sano debe apoyarse en el piso dentro del marco del andador. La pierna afectada no debe tocar el piso en ningún momento.', 14217),
  ('MARCHA CON ANDADOR CON RUEDAS DELANTERAS - CARGA DE PESO CON APOYO DE PUNTA (TTWB)', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Adelantá el andador y el pie afectado, pero apoyando solo los dedos y permitiendo unos 5 a 10 kg de presión. Los dedos deben apoyarse dentro del marco del andador. Después, empujá hacia abajo con los brazos y dá un paso adelante con la pierna sana de modo que quede alineada con el otro pie.', 14220),
  ('MARCHA CON ANDADOR CON RUEDAS DELANTERAS - CARGA DE PESO SEGÚN TOLERANCIA (WBAT) - PATRÓN DE PASO HASTA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Adelantá el andador y después dá un paso dentro del marco con la pierna afectada. Después, empujá hacia abajo con los brazos y dá un paso adelante con la pierna sana de modo que quede alineada con la otra pierna. Repetí. Podés cargar sobre la pierna afectada todo el peso que te resulte cómodo.', 14219),
  ('MARCHA CON BASTÓN DE UN PUNTO DE APOYO (SPC) - PATRÓN DE PASO A TRAVÉS', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Adelantá el bastón y el pie afectado. El pie del lado afectado debe quedar alineado con el bastón. Después, presioná el bastón hacia abajo con la mano y pasá con la pierna sana por delante de la punta del bastón. Podés dar pasos alternados naturales. El bastón se usa en la mano contraria a la pierna afectada, salvo indicación distinta.', 14221),
  ('MASAJE CON HIELO EN EL TENDÓN DE AQUILES', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Aplicá hielo directo con un vaso de masaje con hielo sobre el tendón de Aquiles. Movés el hielo en círculos por hasta 5 minutos (no más). Usá toallas para juntar el agua que gotea. Vas a sentir 4 etapas de sensaciones, empezando por... 1. Sensación incómoda de frío, después 2. Pinchazos, después 3. Ardor o dolor sordo, después 4. Adormecimiento. Si el dolor es demasiado, despegalo de la piel unos segundos, secá con la toalla y después volvé a apoyarlo unos círculos más y repetí. ***No lo hagas por más de 5 minutos o corrés riesgo de quemadura por frío y necrosis del tejido.', 55365),
  ('MASAJE CON HIELO EN EL LIGAMENTO ROTULIANO', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Aplicá hielo directo con un vaso de masaje con hielo sobre el ligamento rotuliano, que está justo debajo de la rótula. Movés el hielo en círculos por hasta 5 minutos (no más). Usá toallas para juntar el agua que gotea. Vas a sentir 4 etapas de sensaciones, empezando por... 1. Sensación incómoda de frío, después 2. Pinchazos, después 3. Ardor o dolor sordo, después 4. Adormecimiento. Si el dolor es demasiado, despegalo de la piel unos segundos, secá con la toalla y después volvé a apoyarlo unos círculos más y repetí. ***No lo hagas por más de 5 minutos o corrés riesgo de quemadura por frío y necrosis del tejido. Usá un cronómetro para mayor seguridad.', 55374),
  ('ANATOMÍA DE LA RODILLA - VISTA ANTEROLATERAL', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Músculo cuádriceps 2. Rótula (se cortó y levantó el ligamento rotuliano para exponer la rótula) 3. Menisco externo 4. Ligamento colateral externo - LCE 5. Ligamento cruzado anterior - LCA 6. Peroné 7. Ligamento rotuliano 8. Tibia 9. Menisco externo 10. Ligamento colateral interno - LCI', 36733),
  ('ANATOMÍA DE LA RODILLA - VISTA LATERAL', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Músculo cuádriceps 2. Tendón del cuádriceps 3. Ligamento colateral externo - LCE 4. Rótula 5. Ligamento colateral externo 6. Ligamento rotuliano 7. Peroné 8. Tibia', 36734),
  ('ANATOMÍA DE LA RODILLA - VISTA MEDIAL', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Músculo cuádriceps 2. Tendón del cuádriceps 3. Rótula 4. Ligamento colateral interno - LCI 5. Menisco interno 6. Ligamento rotuliano 7. Tibia', 36735),
  ('ANATOMÍA DE LA RODILLA - VISTA POSTERIOR', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Músculo cuádriceps 2. Ligamento cruzado anterior - LCA 3. Ligamento colateral interno - LCI 4. Ligamento colateral externo - LCE 5. Menisco interno 6. Menisco externo 7. Ligamento cruzado posterior - LCP 8. Peroné 9. Tibia', 36736),
  ('POSICIONAMIENTO LUMBAR EN DECÚBITO DORSAL CON SILLA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Acostate boca arriba y apoyá las piernas sobre una silla, como se muestra. Esto ayuda a reducir la presión en la zona lumbar y puede ofrecer una posición de alivio.', 60873),
  ('ANATOMÍA LUMBAR - HERNIA DE DISCO', NULL, true, 'sin_clasificar', 'Educación', NULL, '1-5 Vértebras lumbares A. Raíz nerviosa B. Protrusión discal', 36744),
  ('NO CRUZAR LAS PIERNAS - PRECAUCIÓN DE CADERA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'No cruces las piernas en ningún momento. **No cumplir con estas precauciones puede provocar que la cadera se luxe, lo que PUEDE requerir una cirugía para repararla.', 14464),
  ('NO ROTAR EN EXCESO - PRECAUCIÓN DE COLUMNA, CADERA Y RODILLA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'No rotes en exceso estando parado. ADVERTENCIA: no cumplir con estas precauciones puede provocar daño en las estructuras internas de la columna, la cadera o la rodilla.', 21686),
  ('NO FLEXIONAR LA CADERA MÁS DE 90 GRADOS - PRECAUCIÓN DE CADERA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'No flexiones la cadera más de 90 grados en ningún momento. **No cumplir con estas precauciones puede provocar que la cadera se luxe, lo que PUEDE requerir una cirugía para repararla.', 14465),
  ('NO ROTAR LA CADERA HACIA ADENTRO - PRECAUCIÓN DE CADERA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'No dejes que la cadera rote hacia adentro más allá de la posición neutra. **No cumplir con estas precauciones puede provocar que la cadera se luxe, lo que PUEDE requerir una cirugía para repararla.', 14466),
  ('ANATOMÍA DE LA PELVIS - VISTA ANTERIOR', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Cresta ilíaca del hueso ilíaco - hueso pélvico 2. Articulación sacroilíaca 3. Sacro 4. Espina ilíaca anterosuperior - EIAS 5. Espina ilíaca anteroinferior - EIAI 6. Tubérculo púbico del hueso ilíaco 7. Sínfisis púbica', 36741),
  ('ANATOMÍA DE LA PELVIS - VISTA POSTERIOR', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Articulación sacroilíaca - articulación SI 2. Espina ilíaca posterosuperior del hueso pélvico - EIPS 3. Cresta ilíaca del hueso pélvico 4. Espina ilíaca posteroinferior del hueso pélvico - EIPI 5. Sacro 6. Tuberosidad isquiática del hueso pélvico 7. Cóccix 8. Fémur', 36740),
  ('POSICIONAMIENTO - ACOSTADO BOCA ARRIBA - ALMOHADAS DEBAJO DE RODILLAS Y BRAZOS', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Cuando estés acostado boca arriba, colocá 1 o 2 almohadas debajo de las rodillas y una almohada debajo de cada brazo.', 59404),
  ('POSICIONAMIENTO - ACOSTADO DE COSTADO - ALMOHADA ENTRE LAS RODILLAS', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Cuando estés acostado de costado, colocá una almohada entre las rodillas.', 59403),
  ('POSICIONAMIENTO - ACOSTADO DE COSTADO - ALMOHADA ENTRE LAS RODILLAS Y DEBAJO DEL COSTADO', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Cuando estés acostado de costado, colocá una almohada entre las rodillas y otra debajo del costado del cuerpo.', 59406),
  ('DECÚBITO VENTRAL SOBRE ALMOHADA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Acostate boca abajo sobre una almohada, con los brazos al costado del cuerpo, y relajá completamente todos los músculos. Nota: al entrar y salir de esta posición, activá los músculos abdominales para minimizar el movimiento y el dolor en la columna.', 69315),
  ('MARCHA HACIA ATRÁS - MESADA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Caminá hacia atrás manteniendo una buena postura, usando la mesada como guía y apoyo para el equilibrio. Después, date vuelta y volvé a caminar hacia atrás, siguiendo con la mano de apoyo si hace falta.', 165245),
  ('MOVILIZACIÓN DE CICATRIZ - CÍRCULOS - LIBERACIÓN MIOFASCIAL', NULL, true, 'sin_clasificar', 'Educación', NULL, 'No lo hagas sobre una incisión o corte reciente. Esperá a que te saquen los puntos y a que las costras se caigan solas antes de empezar con las técnicas de masaje de cicatriz. Apoyá 2 o 3 dedos sobre la cicatriz y presioná suavemente mientras movés los dedos en círculos chicos. Hacelo en sentido horario y antihorario mientras recorrés toda la cicatriz. Usá presión suave para no reabrir la herida.', 103733),
  ('MOVILIZACIÓN DE CICATRIZ - LINEAL - LIBERACIÓN MIOFASCIAL', NULL, true, 'sin_clasificar', 'Educación', NULL, 'No lo hagas sobre incisiones o cortes recientes. Esperá a que te saquen los puntos y a que las costras se caigan solas antes de empezar con las técnicas de masaje de cicatriz. Apoyá 2 o 3 dedos sobre la piel cerca de la cicatriz y tirá suavemente de la piel alejándola de la cicatriz. Mantené esa posición y después soltá. Hacelo a lo largo de toda la cicatriz. Después cambiá la dirección del tironeo y repetí. Tirá hacia el costado, hacia arriba y abajo, y en diagonal. Usá un tironeo suave para no reabrir la herida.', 103734),
  ('ANATOMÍA DEL HOMBRO - VISTA ANTERIOR', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Ligamento coracoacromial 2. Ligamento coracoclavicular 3. Clavícula 4. Espacio subacromial 5. Tendón del supraespinoso 6. Músculo supraespinoso 7. Apófisis coracoides de la escápula 8. Músculo/tendón subescapular 9. Músculo/tendón del bíceps 10. Húmero 11. Borde medial de la escápula 12. Músculo/tendón redondo mayor', 36737),
  ('ANATOMÍA DEL HOMBRO - VISTA ANTEROLATERAL', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Espacio subacromial 2. Acromion de la escápula 3. Ligamento coracoacromial 4. Ligamento coracoclavicular 5. Clavícula 6. Tendón del supraespinoso 7. Tendón del subescapular 8. Músculo subescapular 9. Tendón del redondo mayor 10. Músculo redondo mayor 11. Húmero 12. Tendón del bíceps', 36738),
  ('ANATOMÍA DEL HOMBRO - VISTA POSTERIOR', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Ligamento acromioclavicular 2. Músculo supraespinoso 3. Acromion de la escápula 4. Espina de la escápula 5. Músculo infraespinoso 6. Borde medial de la escápula 7. Húmero 8. Músculo redondo mayor 9. Músculo redondo menor', 36739),
  ('TRANSFERENCIA A LA BAÑERA CON SILLA DE BAÑO', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA ENTRAR A LA BAÑERA: usando tu dispositivo de asistencia (andador, bastón o andador hemipléjico), caminá hasta el banco de modo que la parte de atrás de las piernas toque el borde de la bañera o el banco de ducha. Estirá la mano hacia atrás para agarrarte del borde de la bañera o del banco mientras bajás a sentarte usando la pierna sana para hacer el esfuerzo. Al bajar, deslizá la pierna afectada hacia adelante para no cargar peso sobre ella. Apartá el dispositivo de asistencia, pero dejalo al alcance para usarlo después. Una vez sentado, correte más atrás en el banco y girá para poder pasar una pierna adentro de la bañera. Correte más sobre el banco y después pasá la otra pierna. Ayudate con los brazos si hace falta para levantar las piernas. Usá barras de agarre bien fijadas durante la transferencia. PARA SALIR DE LA BAÑERA: sentado en la silla de ducha, pasá una pierna por encima del borde de la bañera. Después, correte más cerca del borde para poder pasar la otra pierna. Ayudate con los brazos si hace falta. Sentado, girá hasta quedar mirando hacia adelante en el borde de la bañera o el banco. Agarrá el dispositivo de asistencia y acercalo. Con una mano apoyada en el borde de la bañera, parate usando la pierna sana para hacer el esfuerzo.', 38411),
  ('SEGURIDAD CON BARRAS DE AGARRE EN LA DUCHA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Instalá y usá barras de agarre en la zona de la bañera por seguridad. Agarrate al menos de una barra en todo momento mientras te movés.', 38389),
  ('TRANSFERENCIA A BANCO DE BAÑERA DESDE SILLA DE RUEDAS', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA ENTRAR A LA BAÑERA: desde la silla de ruedas, acercate al costado de la bañera de modo que el lateral de la silla quede cerca del borde y del banco. Después, PONÉ LOS FRENOS y sacá el apoyabrazos del lado de la bañera. Después, corrête y levantate hacia la silla de ducha. Una vez sentado, correte más atrás en el banco y girá para poder pasar una pierna adentro de la bañera. Correte más sobre el banco y después pasá la otra pierna. Ayudate con los brazos si hace falta. Usá barras de agarre bien fijadas durante la transferencia. PARA SALIR DE LA BAÑERA: sentado en la silla de ducha, pasá una pierna por encima del borde de la bañera. Después, correte más cerca del borde para poder pasar la otra pierna. Ayudate con los brazos si hace falta. Seguí corriéndote y levantándote hasta quedar sentado en la silla de ruedas. Volvé a colocar el apoyabrazos y RECIÉN AL FINAL SACÁ LOS FRENOS para poder impulsar la silla.', 38412),
  ('DECÚBITO LATERAL CON ALMOHADAS SOSTENIENDO EL HOMBRO', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Cuando estés acostado de costado, colocá una almohada debajo del antebrazo y otra debajo del costado del cuerpo, como se muestra.', 59405),
  ('TRANSFERENCIA CON TABLA DESLIZANTE - DE LA SILLA DE RUEDAS A LA CAMA', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Ubicá el costado de la silla de ruedas junto a la cama, como se muestra. Poné los frenos y sacá el apoyabrazos. Si se puede, hacé la transferencia hacia el lado más fuerte o no afectado. 2. Inclinate hacia un costado y colocá la tabla deslizante debajo del glúteo y cruzando hacia la cama. 3. Usá los brazos para levantarte y deslizarte por la tabla hacia la cama. 4. Una vez que estés seguro sobre la cama, inclinate hacia el costado y sacá la tabla deslizante.', 38880),
  ('TRANSFERENCIA CON TABLA DESLIZANTE Y ASISTENCIA - DE LA SILLA DE RUEDAS A LA CAMA', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Ubicá el costado de la silla de ruedas junto a la cama, como se muestra. Poné los frenos y sacá el apoyabrazos. Si se puede, hacé la transferencia hacia el lado más fuerte o no afectado. Inclinate hacia un costado y colocá la tabla deslizante debajo del glúteo y cruzando hacia la cama. 2. Colocá el cinturón de marcha alrededor de la cintura o el pecho. 3. Pedile a la persona que ayude todo lo que pueda mientras la levantás y la deslizás hacia la cama. 4. Una vez que esté segura sobre la cama, inclinala hacia el costado y sacá la tabla deslizante.', 39034),
  ('ANATOMÍA DE LA COLUMNA - HERNIA DE DISCO', NULL, true, 'sin_clasificar', 'Educación', NULL, '1. Agujero intervertebral 2. Vértebra 3. Raíz nerviosa 4. Protrusión discal 5. Disco intervertebral', 36745),
  ('ANATOMÍA DE LA COLUMNA - VISTAS GENERALES', NULL, true, 'sin_clasificar', 'Educación', NULL, 'A. Vista posterior (de atrás) B. Vista lateral (de costado) C. Vista anterior (de adelante)', 36742),
  ('ENTRENAMIENTO EN ESCALERA CON MULETAS - JUNTAS - SIN CARGA DE PESO (NWB)', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA SUBIR Y BAJAR: sostené las dos muletas juntas en una mano, en paralelo como se muestra, y agarrate del pasamanos con la otra. Después, saltá al escalón con el pie sano. Repetí. No tenés que cargar nada de peso sobre la pierna afectada en ningún momento. CONSEJO: una forma fácil de acordarse es pensar "sube la buena y baja la mala". En una situación sin carga de peso, la "mala" son solamente las puntas de las muletas.', 120042),
  ('ENTRENAMIENTO EN ESCALERA CON MULETAS - SIN CARGA DE PESO (NWB) - SIN PASAMANOS', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA SUBIR: parate cerca del primer escalón sin apoyar la pierna afectada en el piso. Empujá hacia abajo con los brazos a través de las muletas y saltá al primer escalón con la pierna sana. Después, incorporate y estirá la rodilla sana mientras subís las muletas al mismo escalón. Repetí. PARA BAJAR: parate cerca del primer escalón manteniendo la pierna afectada sin carga de peso. Primero, apoyá las puntas de las muletas en el escalón de abajo. Después, empujá hacia abajo con los brazos a través de las muletas y saltá al escalón de abajo con la pierna sana. Repetí. CONSEJO: una forma fácil de acordarse es pensar "sube la buena y baja la mala". En una situación sin carga de peso, la "mala" son solamente las puntas de las muletas.', 121188),
  ('ENTRENAMIENTO EN ESCALERA CON MULETAS - CARGA DE PESO SEGÚN TOLERANCIA (WBAT) - JUNTAS', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA SUBIR: poné las dos muletas juntas en una mano, del lado opuesto al pasamanos, como se muestra. Mientras te agarrás del pasamanos, primero apoyá la pierna sana (la buena) en el escalón de arriba y después elevá el cuerpo para poder subir la pierna afectada y las muletas al mismo escalón. Repetí. PARA BAJAR: poné las dos muletas juntas en una mano, del lado opuesto al pasamanos, como se muestra. Mientras te agarrás del pasamanos, primero apoyá la pierna afectada (la mala) y las muletas en el escalón de abajo mientras bajás el cuerpo, y después bajá la pierna sana al mismo escalón. Repetí. CONSEJO: una forma fácil de acordarse es pensar "sube la buena y baja la mala".', 120045),
  ('ENTRENAMIENTO EN ESCALERA CON MULETAS - CARGA SEGÚN TOLERANCIA (WBAT) - SIN BARANDA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA SUBIR: Apoyá el pie/pierna sana en el escalón de arriba y después elevá el cuerpo para poder llevar la pierna afectada y las muletas al mismo escalón. Repetí. PARA BAJAR: Apoyá el pie/pierna afectada y las puntas de las muletas en el escalón de abajo y después bajá la pierna sana al mismo escalón. Repetí. CONSEJO: Una forma fácil de acordarse es pensar "subo con la buena y bajo con la mala".', 121182),
  ('ENTRENAMIENTO EN ESCALERA CON ANDADOR CON RUEDAS DELANTERAS (FWW) - CARGA SEGÚN TOLERANCIA (WBAT)', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA SUBIR: Plegá el andador y sostenelo del lado contrario a la baranda. Apoyá una punta del andador en un escalón más alto. Subí primero con el pie sano. Después elevá el cuerpo y llevá la pierna afectada y el andador al escalón de arriba. Repetí. PARA BAJAR: Plegá el andador y sostenelo del lado contrario a la baranda. Apoyá una punta del andador en un escalón más bajo. Bajá con el pie afectado. Después bajá el cuerpo y llevá la pierna sana y el andador al escalón de abajo. Repetí. CONSEJO: Una forma fácil de acordarse es pensar "subo con la buena y bajo con la mala".', 120049),
  ('ESCALERA CON MULETAS - SIN CARGA DE PESO (NWB)', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA SUBIR: Parate cerca del primer escalón manteniendo la pierna afectada sin carga de peso. Sostené las dos muletas con una mano, de modo que una quede en posición horizontal como se muestra, y agarrá la baranda con la otra. Después, saltá al escalón con el pie sano. Luego subí la punta de la muleta al mismo escalón. Repetí. No tenés que apoyar nada de peso sobre la pierna afectada en ningún momento. PARA BAJAR: Parate cerca del primer escalón manteniendo la pierna afectada sin carga de peso. Sostené las dos muletas con una mano, de modo que una quede en posición horizontal como se muestra, y agarrá la baranda con la otra. Apoyá las puntas de las muletas en el escalón de abajo. Después, empujá los brazos hacia abajo a través de las muletas y saltá al escalón de abajo con la pierna/pie sano. Repetí. CONSEJO: Una forma fácil de acordarse es pensar "subo con la buena y bajo con la mala". Cuando no se puede cargar peso, "la mala" son solamente las puntas de las muletas.', 14224),
  ('ESCALERA CON MULETAS - SIN CARGA DE PESO (NWB) - MÉTODO SENTADO Y DESLIZANDO', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA SUBIR Y BAJAR: Sostené las dos muletas con una mano y sentate usando solamente la pierna sana. Una vez sentado, deslizate hacia arriba o hacia abajo por los escalones usando la pierna sana y los dos brazos. No te olvides de llevar las muletas con vos. No tenés que apoyar nada de peso sobre la pierna afectada en ningún momento.', 14225),
  ('ESCALERA CON MULETAS - CARGA SEGÚN TOLERANCIA (WBAT)', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA SUBIR: Subí primero con el pie sano y después elevá el cuerpo; luego llevá la pierna afectada y la muleta al mismo escalón. Repetí. PARA BAJAR: Bajá primero con el pie afectado y la muleta y después bajá el cuerpo y la pierna sana al mismo escalón. Repetí. CONSEJO: Una forma fácil de acordarse es pensar "subo con la buena y bajo con la mala".', 14226),
  ('ESCALERA CON BASTÓN DE UN APOYO (SPC)', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA SUBIR: Subí primero con el pie sano y después elevá el cuerpo; luego llevá la pierna afectada y el bastón al mismo escalón. Repetí. PARA BAJAR: Bajá primero con el pie afectado y el bastón y después bajá el cuerpo y la pierna sana al mismo escalón. Repetí. CONSEJO: Una forma fácil de acordarse es pensar "subo con la buena y bajo con la mala".', 14223),
  ('TRANSFERENCIA - DE SENTADO A DE PIE DESDE LA SILLA - CON ASISTENCIA DE UNA MANO', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Pararte desde la silla: Inclinate de lado a lado mientras deslizás la cola hacia adelante hasta quedar sentado en el borde de la silla. Después, empujá con una mano sobre el apoyabrazos para ayudarte a subir a la posición de pie. Si no hay apoyabrazos, llevá la mano hacia atrás y empujá sobre el asiento. Sentarte en la silla: Parate frente a la silla de modo que la parte de atrás de las piernas toque la silla. Después, inclinate hacia adelante y flexioná las rodillas mientras llevás la mano hacia atrás y agarrás el apoyabrazos de la silla. Si no hay apoyabrazos, llevá la mano hacia atrás y apoyala sobre el asiento. Usá la mano para ayudarte a bajar hasta la posición sentada. Inclinate de lado a lado y deslizate más adentro de la silla.', 125317),
  ('TRANSFERENCIA - DE PIE A SENTADO - PROTECCIÓN DE LA PIERNA', NULL, true, 'sin_clasificar', 'Educación', NULL, 'Caminá hasta la silla con el andador y girá de modo que la parte de atrás de las piernas toque el asiento. Después, dá un pasito adelante con la pierna afectada y llevá la mano hacia atrás (la del lado contrario a la pierna afectada) para agarrarte de la silla mientras bajás a sentarte. La pierna afectada tiene que deslizarse hacia adelante mientras te sentás. ***Si te hicieron un reemplazo total de cadera, asegurate de no flexionar la cadera más de 90 grados al hacerlo.', 14682),
  ('ENTRENAMIENTO DE TRANSFERENCIA A BANQUETA DE BAÑERA CON HEMIPARESIA/ACV', NULL, true, 'sin_clasificar', 'Educación', NULL, 'PARA ENTRAR A LA BAÑERA: Estando en la silla de ruedas, acercate al costado de la bañera de modo que el lateral de la silla quede cerca de la pared de la bañera y de la banqueta. Después, PONÉ LOS FRENOS y sacá el apoyabrazos de la silla del lado de la bañera. Después, deslizate y elevate hacia la banqueta de ducha usando el brazo y la pierna sanos. Una vez sentado, deslizate más atrás sobre la banqueta y girá para poder levantar una pierna y meterla en la bañera. Deslizate más sobre la banqueta y después levantá la otra pierna hacia adentro de la bañera. Si hace falta, usá el brazo sano para ayudarte a levantar la o las piernas. Usá agarraderas bien fijadas durante la transferencia. PARA SALIR DE LA BAÑERA: Sentado en la banqueta de ducha, levantá una pierna por encima de la pared de la bañera. Después deslizate más cerca de la pared de la bañera para poder pasar la otra pierna también. Si hace falta, usá el brazo sano para ayudarte a levantar la pierna. Seguí deslizándote y elevándote hasta quedar sentado en la silla de ruedas. Volvé a poner el apoyabrazos de la silla y RECIÉN AL FINAL SACÁ LOS FRENOS para poder impulsar la silla.', 38416),
  ('AVD - LLEVAR BOLSOS O VALIJAS', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando lleves bolsos, asegurate de distribuir el peso de forma pareja entre el lado derecho y el izquierdo del cuerpo. Mantené la columna derecha. Si llevás un solo bolso, cambiá de lado cada tanto.', 49928),
  ('AVD - LIMPIAR UNA SUPERFICIE BAJA', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando limpies una superficie baja, como una mesa, ponete en posición de media rodilla, como se muestra. Tenés que tener una rodilla en el piso y la otra flexionada con el pie apoyado. Mantené la columna derecha. Si te resulta más cómodo, poné una almohada o una toalla doblada debajo de la rodilla que está en el piso.', 49933),
  ('AVD - TRABAJAR EN LA MESADA', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando trabajes en una mesada, parate cerca de la mesada para reducir al mínimo la inclinación desde la cintura. Mantené la columna derecha.', 49938),
  ('AVD - CAVAR CON PALA', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando caves con una pala, mantené la punta de la pala cerca del cuerpo y la columna derecha.', 49939),
  ('AVD - LAVAVAJILLAS', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando cargues y descargues la bandeja de abajo del lavavajillas, bajá a la posición de media rodilla, como se muestra. Tenés que tener una rodilla en el piso y la otra flexionada con el pie apoyado. Mantené la columna derecha. Si te resulta más cómodo, poné una almohada o una toalla doblada debajo de la rodilla que está en el piso.', 49940),
  ('AVD - SACAR EL POLVO', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Usá un plumero de mango largo para limpiar objetos de difícil alcance. Mantené la columna derecha.', 49942),
  ('AVD - BARRER CON PALA DE MANO', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Usá una pala de mano con mango largo para barrer el piso. Mantené la columna derecha.', 49941),
  ('AVD - PLANCHAR LA ROPA', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando planches la ropa, subí la tabla de planchar para reducir al mínimo la inclinación hacia adelante. Mantené la columna derecha.', 49947),
  ('AVD - LAVADERO - PONER LA ROPA EN EL SECARROPAS', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando pongas la ropa en el secarropas, apoyá una mano sobre el secarropas para sostenerte y llevá una pierna hacia atrás, como se muestra, para reducir al mínimo la flexión de la columna. Al inclinarte hacia adelante, hacé la bisagra desde la cadera y no desde la columna, en la medida de lo posible.', 39774),
  ('AVD - LAVADERO - SACAR LA ROPA DEL SECARROPAS', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando saques la ropa del secarropas, poné una toalla doblada o una almohada en el piso y arrodillate sobre ella con una rodilla. Apoyá una mano sobre el secarropas para sostenerte. Después, metete en el secarropas y pasá la ropa al canasto flexionando y rotando la columna lo menos posible.', 39775),
  ('AVD - LAVADERO - SACAR LA ROPA DEL LAVARROPAS', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando saques la ropa del lavarropas, apoyá una mano sobre el lavarropas para sostenerte y llevá una pierna hacia atrás al inclinarte, como se muestra, para reducir al mínimo la flexión de la columna. Al inclinarte hacia adelante, hacé la bisagra desde la cadera y no desde la columna, en la medida de lo posible.', 39773),
  ('AVD - CORTADORA DE PASTO', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando cortes el pasto, caminá con la máquina para reducir al mínimo la inclinación hacia adelante. Además, si el manubrio es regulable, extendelo para mejorar el alcance. Mantené la columna derecha.', 49949),
  ('AVD - JARDINERÍA BAJA', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando hagas jardinería con herramientas chicas o saques yuyos, ponete en posición de media rodilla, como se muestra. Tenés que tener una rodilla en el piso y la otra flexionada con el pie apoyado. Mantené la columna derecha. Si te resulta más cómodo, poné una almohada o una toalla doblada debajo de la rodilla que está en el piso.', 49950),
  ('AVD - RASTRILLAR', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando rastrilles, mantené los brazos cerca del centro del cuerpo y no te inclines desde la columna. Si hace falta, flexioná las rodillas y hacé una estocada. Mantené la columna derecha.', 49951),
  ('AVD - PINZA DE ALCANCE', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Usá una pinza de alcance para evitar agacharte hacia el piso. Sirve muy bien para objetos chicos como ropa, basura y otros elementos pequeños. Mantené la columna derecha.', 18215),
  ('AVD - HELADERA Y FREEZER', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando cargues y descargues cosas de los estantes bajos de la heladera o el freezer, bajá a la posición de media rodilla, como se muestra. Tenés que tener una rodilla en el piso y la otra flexionada con el pie apoyado. Mantené la columna derecha. Si te resulta más cómodo, poné una almohada o una toalla doblada debajo de la rodilla que está en el piso.', 49946),
  ('AVD - PALEAR', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando palees, movete en un patrón de estocada con un pie adelante del otro mientras flexionás las rodillas para ir hacia adelante y atrás. Mantené la columna derecha.', 49954),
  ('AVD - CEPILLO DE FREGAR', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Usá un cepillo de fregar con mango largo para limpiar superficies de difícil alcance, como la bañera. Ponete en posición de media rodilla, como se muestra. Tenés que tener una rodilla en el piso y la otra flexionada con el pie apoyado. Mantené la columna derecha. Si te resulta más cómodo, poné una almohada o una toalla doblada debajo de la rodilla que está en el piso.', 49956),
  ('AVD - AFEITARSE EN EL LAVATORIO', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando te afeites, parate cerca de la mesada para reducir al mínimo la inclinación desde la cintura. Además, apoyá un pie en el estante de abajo del mueble. Si hace falta, sostenete con la otra mano. Mantené la columna derecha.', 49953),
  ('AVD - USO DEL CELULAR', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Mientras usás dispositivos electrónicos como el celular, no te encorves ni dejes que la cabeza se adelante. Sostené el dispositivo en alto para verlo mejor y mantener una buena postura de la espalda y el cuello.', 50843),
  ('AVD - TELÉFONO', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando uses el teléfono, mantené una buena postura para que la cabeza no quede inclinada hacia el costado ni adelantada. No sostengas el teléfono contra la oreja con el hombro. Sostené el teléfono con la mano y mantené la columna y la cabeza derechas.', 49955),
  ('AVD - USAR ESCALERITAS PARA ZONAS ALTAS', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando tengas que alcanzar alacenas o estantes altos, subite a una escalerita para evitar arquear la espalda. Mantené la columna derecha en todas las actividades.', 150389),
  ('AVD - LAVAR LOS PLATOS', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando estés parado frente a la pileta, abrí las puertas del mueble de abajo y apoyá un pie sobre el estante. Esto reduce la presión sobre la espalda. Al inclinarte hacia adelante, hacé la bisagra desde las caderas y no desde la espalda.', 150202),
  ('AVD - CARRETILLA', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Cuando uses una carretilla, caminá con ella para ubicarla en su lugar y así reducir al mínimo la inclinación hacia adelante. No te inclines desde la columna. Mantené la columna derecha.', 49958),
  ('EMBARAZO - RODADO EN DECÚBITO LATERAL', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal', 'Estando acostada de costado, estirá la pierna de abajo y flexioná la rodilla de arriba. Rodá hacia la espalda. Ya boca arriba, mantené la rodilla estirada del lado hacia el que querés girar. Flexioná la otra rodilla y apoyá bien el pie para ayudarte a empujar y reacomodarte mientras rodás hacia el lado de la rodilla estirada.', 181345),
  ('AVD - ESCRITORIO ERGONÓMICO SENTADO SOBRE PELOTA DE EJERCICIOS', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal; Varios', 'Sentate en el escritorio sobre una pelota de ejercicios grande y usá un teclado ergonómico. El escritorio tiene que estar armado de modo que el monitor quede a la altura de los ojos o apenas por debajo. Los codos, las caderas y las rodillas flexionados entre 90 y 110 grados. Se pueden ajustar la altura del monitor, del teclado, del asiento, del escritorio o del apoyapiés para lograr una alineación correcta. Si está disponible, se prefiere un escritorio electrónico, para poder ajustar la altura apretando un botón.', 51416),
  ('AVD - VESTIRSE - ZAPATOS', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal; Varios', 'Usá un calzador de mango largo y un alcanzador para ponerte los zapatos. Agarrá la lengüeta del zapato con el alcanzador y meté el pie parcialmente adentro del zapato. Después, usá el calzador de mango largo para ayudar a que el talón entre en el zapato y completar el proceso.', 18217),
  ('AVD - VESTIRSE - MEDIAS', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal; Varios', 'Usá un calza-medias para ponerte las medias. Colocá la media completamente sobre el calza-medias. Después, sostené las cintas o la soga y bajá el calza-medias hasta el piso, adelante del pie. Tirá de las cintas o la soga para que el pie entre en la media y en el calza-medias. Seguí tirando hasta que la media quede completamente puesta y el calza-medias salga.', 18218),
  ('AVD - ESCRITORIO ELÉCTRICO REGULABLE - ALTERNAR SENTADO Y DE PIE', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal; Varios', 'Si tenés un escritorio eléctrico, subilo y bajalo cada tanto durante la jornada laboral para poder hacer pausas del sentado o el parado prolongado. Mantené la columna derecha y erguida. El escritorio tiene que estar armado de modo que el monitor quede a la altura de los ojos o apenas por debajo, y los codos flexionados a unos 90-110 grados. Podés ajustar la altura del monitor y del teclado regulando la altura del escritorio y usando un soporte de monitor, para lograr una alineación correcta.', 51418),
  ('AVD - PARADO PROLONGADO', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal; Varios', 'Cuando estés parado mucho tiempo, apoyá un pie sobre un banquito o una superficie elevada. Alterná con el otro pie cada tanto. Mantené la columna derecha.', 49960),
  ('AVD - USO DE TABLET', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal; Varios', 'Mientras usás dispositivos electrónicos como una tablet, no te encorves ni dejes que la cabeza se adelante. Sostené el dispositivo en alto para verlo mejor y mantener una buena postura de la espalda y el cuello.', 50844),
  ('PONERSE LA REMERA - PARÁLISIS DE BRAZO', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal; Varios', 'Apoyá la remera sobre la falda y meté el brazo afectado en la manga. Después, empezá a tirar de la remera hacia arriba para que el brazo afectado entre en la manga. Pasá la cabeza y después ponete la otra manga con el brazo sano.', 151566),
  ('PAUSAS DE PIE', NULL, true, 'sin_clasificar', 'Educación', 'Mecánica corporal; Varios', 'Si estás sentado mucho tiempo, hacé pausas de pie cada tanto. Esto disminuye la carga sobre la columna, ya que estar sentado suele generar más fuerzas sobre la columna que estar parado. Podés usar una alarma para acordarte de pararte.', 49931),
  ('MULETAS AXILARES - MARCHA EN CUATRO PUNTOS', NULL, true, 'sin_clasificar', 'Educación', 'Entrenamiento de la marcha', 'Adelantá la punta de una muleta de un lado primero. Después, dá un paso adelante con la pierna del lado contrario. Después repetí lo mismo del otro lado. Seguí con este patrón mientras caminás hacia adelante con las muletas. ALINEACIÓN: al dar un paso, el pie tiene que apoyar en el piso aproximadamente en línea con la punta de la muleta del lado contrario.', 121180),
  ('MARCHA HACIA ADELANTE - MESADA', NULL, true, 'sin_clasificar', 'Educación', 'Entrenamiento de la marcha', 'Caminá hacia adelante manteniendo una buena postura, usando la mesada como guía y apoyo para el equilibrio. Después, date vuelta y volvé a caminar hacia adelante, siguiendo con la mano de apoyo si hace falta.', 165246),
  ('MARCHA CON MULETAS - SIN CARGA DE PESO (NWB) - PATRÓN DE PASO HASTA', NULL, true, 'sin_clasificar', 'Educación', 'Entrenamiento de la marcha', 'Mantené la pierna afectada sin tocar el piso. Adelantá las puntas de las muletas y después empujá hacia abajo con los brazos y saltá hacia adelante con la pierna sana. El pie sano tiene que apoyar en el piso aproximadamente en línea con las puntas de las muletas. La pierna afectada no tiene que tocar el piso en ningún momento.', 121185),
  ('MARCHA CON MULETAS - CARGA DE PESO CON TOQUE DE PUNTA (TTWB) - PATRÓN DE PASO HASTA', NULL, true, 'sin_clasificar', 'Educación', 'Entrenamiento de la marcha', 'Adelantá las puntas de las muletas y el pie afectado, pero permitiendo solo unos 5 a 9 kg de presión sobre la pierna afectada. Los dedos del pie tienen que apoyar en el piso aproximadamente en línea con las puntas de las muletas. Después, empujá hacia abajo con los brazos y dá un paso adelante con la pierna sana, de modo que quede aproximadamente en línea con las puntas de las muletas y el pie afectado. Repetí.', 121195),
  ('CONTROL DE PRESIÓN ARTERIAL', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Controlá tu presión arterial. El valor ideal es 120/80 mmHg o menos. Entre 120/80 mmHg y 139/89 mmHg se considera un rango de normal a alto. Tu médico puede indicarte cuál es tu presión ideal según tu situación.', 92513),
  ('COMPRESA FRÍA - CÓMO PREPARAR UNA BOLSA DE HIELO', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Volcá 1 taza de alcohol y 2 tazas de agua en una bolsa hermética que se pueda cerrar. Mezclá el contenido y ponela en el congelador. Opcional: agregá unas gotas de colorante azul o verde para darle color.', 95121),
  ('TOSER CON PRECAUCIÓN ESTERNAL', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Sostené una almohada firmemente contra el pecho y el esternón mientras tosés.', 55364),
  ('RESPIRACIÓN PROFUNDA CON RETENCIÓN', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Tomá una respiración profunda por la nariz y retené el aire unos segundos. Después soltá el aire con los labios fruncidos. La exhalación tiene que durar más que la inhalación.', 91906),
  ('GIROS CON RESPIRACIÓN PROFUNDA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Colocá las manos entrelazadas adelante del cuerpo. Tomá una respiración profunda por la nariz y rotá el cuerpo de lado a lado mientras soltás el aire con los labios fruncidos.', 91903),
  ('DOBLE PELOTA DE MASAJE (MANÍ) - ARMADO CON MEDIA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Poné 2 pelotas de tenis o de paleta dentro de una media y usá gomitas en las puntas para mantenerlas juntas. CONSEJO: cuanto más larga sea la media, más largas van a quedar las puntas, lo que ayuda a acomodarla.', 99551),
  ('DOBLE PELOTA DE MASAJE (MANÍ) - ARMADO CON CINTA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Pegá 2 pelotas de tenis o de paleta con cinta. Cuando esté listo tiene que tener forma de maní. Se puede usar para las técnicas de automasaje.', 99554),
  ('INSPIRACIÓN RESISTIDA CON BANDA ELÁSTICA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Envolvé una banda elástica alrededor del pecho y sostené las puntas con una mano. Después, tomá una respiración profunda por la nariz mientras intentás expandir el pecho hacia los costados. Soltá el aire con los labios fruncidos y repetí.', 91908),
  ('CONTROL DE FRECUENCIA CARDÍACA - RELOJ ANALÓGICO O DIGITAL', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Controlá tu frecuencia cardíaca tomando el pulso con 2 dedos sobre la muñeca (del lado de la palma), por debajo de la zona del pulgar, como se muestra. CÓMO CALCULARLA: contá cuántos pulsos sentís en 10 segundos y multiplicá por 6. O contá cuántos pulsos sentís en 15 segundos y multiplicá por 4. FRECUENCIA CARDÍACA EN REPOSO NORMAL: el rango normal en reposo es de entre 50 y 100 latidos por minuto. Por encima de 100 se considera taquicardia (frecuencia rápida); por debajo de 60 se considera bradicardia (frecuencia lenta). FRECUENCIA EN REPOSO IDEAL: entre 50 y 70 latidos por minuto. Las personas deportistas suelen tener frecuencias más bajas. FRECUENCIA CARDÍACA MÁXIMA DE EJERCICIO: 220 menos tu edad. No la superes. FRECUENCIA CARDÍACA OBJETIVO (ideal para entrenar): 50-85% de tu frecuencia máxima. Tu médico puede indicarte los valores más adecuados según tu situación.', 92528),
  ('CONTROL DE FRECUENCIA CARDÍACA - RELOJ INTELIGENTE', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Controlá tu frecuencia cardíaca usando las funciones de tu reloj inteligente. FRECUENCIA CARDÍACA EN REPOSO NORMAL: el rango normal en reposo es de entre 50 y 100 latidos por minuto. Por encima de 100 se considera taquicardia (frecuencia rápida); por debajo de 60 se considera bradicardia (frecuencia lenta). FRECUENCIA EN REPOSO IDEAL: entre 50 y 70 latidos por minuto. Las personas deportistas suelen tener frecuencias bajas. FRECUENCIA CARDÍACA MÁXIMA DE EJERCICIO: 220 menos tu edad. No la superes. FRECUENCIA CARDÍACA OBJETIVO (ideal para entrenar): 50-85% de tu frecuencia máxima. Tu médico puede indicarte los valores más adecuados según tu situación.', 92531),
  ('TOS CON RESOPLIDO (HUFF)', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Tomá una respiración profunda y después soltá el aire con fuerza y gran volumen (resoplidos) unas cuantas veces. Después tomá otra respiración y tosé varias veces. El resoplido ayuda a movilizar las secreciones hacia la vía aérea superior y la tos ayuda a expulsarlas. No hagas esto con otras personas en la habitación. Conviene hacerlo sobre un pañuelo descartable o una toalla.', 91907),
  ('VASO DE HIELO PARA MASAJE - PREPARACIÓN', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Prepará vasos de hielo para masaje volcando agua en un vaso de papel chico y congelándolo. Una vez congelado, arrancá la parte de arriba del papel para dejar el hielo a la vista, pero dejá algo de papel para poder agarrarlo más fácil. Congelá varios de estos vasos para usarlos después.', 55366),
  ('MASAJE CON HIELO EN EL TENDÓN DISTAL DEL BÍCEPS', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Aplicá el hielo directo de un vaso de masaje sobre el pliegue de la parte de adelante del codo, donde el brazo se dobla con el antebrazo (zona del tendón distal del bíceps). Movés el hielo en círculos por hasta 5 minutos (no más). Usá toallas para juntar el agua que gotea. Vas a sentir 4 etapas de sensaciones: 1. Sensación incómoda de frío, después 2. Pinchazos, después 3. Ardor o dolor sordo, y después 4. Adormecimiento. Si el dolor es muy fuerte, despegá el hielo de la piel unos segundos, secá con la toalla y volvé a apoyarlo para hacer algunos círculos más, y repetí. ***No lo hagas por más de 5 minutos: podés correr riesgo de quemadura por frío y provocar la muerte del tejido. Usá una alarma por seguridad.', 55371),
  ('MASAJE CON HIELO EN EL EPICÓNDILO MEDIAL - TENDÓN FLEXOR COMÚN DE LA MUÑECA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Aplicá el hielo directo de un vaso de masaje sobre el epicóndilo medial del codo, como se muestra (zona del tendón flexor común de la muñeca). Movés el hielo en círculos por hasta 5 minutos (no más). Usá toallas para juntar el agua que gotea. Esta es habitualmente la zona de inflamación en la lesión conocida como codo de golfista. Vas a sentir 4 etapas de sensaciones: 1. Sensación incómoda de frío, después 2. Pinchazos, después 3. Ardor o dolor sordo, y después 4. Adormecimiento. Si el dolor es muy fuerte, despegá el hielo de la piel unos segundos, secá con la toalla y volvé a apoyarlo para hacer algunos círculos más, y repetí. ***No lo hagas por más de 5 minutos: podés correr riesgo de quemadura por frío y provocar la muerte del tejido. Usá una alarma por seguridad.', 55373),
  ('MASAJE CON HIELO EN EL TENDÓN PROXIMAL DEL BÍCEPS', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Apoyá el brazo sobre una mesa con la palma hacia arriba. Aplicá el hielo directo de un vaso de masaje sobre la parte de adelante del hombro (zona del tendón proximal del bíceps). Movés el hielo en círculos por hasta 5 minutos (no más). Usá toallas para juntar el agua que gotea. Vas a sentir 4 etapas de sensaciones: 1. Sensación incómoda de frío, después 2. Pinchazos, después 3. Ardor o dolor sordo, y después 4. Adormecimiento. Si el dolor es muy fuerte, despegá el hielo de la piel unos segundos, secá con la toalla y volvé a apoyarlo para hacer algunos círculos más, y repetí. ***No lo hagas por más de 5 minutos: podés correr riesgo de quemadura por frío y provocar la muerte del tejido. Usá una alarma por seguridad.', 55376),
  ('MASAJE CON HIELO EN EL SUPRAESPINOSO', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Apoyá el brazo sobre una mesa. Aplicá el hielo directo de un vaso de masaje sobre el costado del hombro, como se muestra. Movés el hielo en círculos por hasta 5 minutos (no más). Usá toallas para juntar el agua que gotea. Vas a sentir 4 etapas de sensaciones: 1. Sensación incómoda de frío, después 2. Pinchazos, después 3. Ardor o dolor sordo, y después 4. Adormecimiento. Si el dolor es muy fuerte, despegá el hielo de la piel unos segundos, secá con la toalla y volvé a apoyarlo para hacer algunos círculos más, y repetí. ***No lo hagas por más de 5 minutos: podés correr riesgo de quemadura por frío y provocar la muerte del tejido. Usá una alarma por seguridad.', 55380),
  ('MASAJE CON HIELO EN LA ATM', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Aplicá el hielo directo de un vaso de masaje sobre la mandíbula, justo por debajo de la oreja (zona de la ATM). Movés el hielo en círculos por hasta 5 minutos (no más). Usá toallas para juntar el agua que gotea. Vas a sentir 4 etapas de sensaciones: 1. Sensación incómoda de frío, después 2. Pinchazos, después 3. Ardor o dolor sordo, y después 4. Adormecimiento. Si el dolor es muy fuerte, despegá el hielo de la piel unos segundos, secá con la toalla y volvé a apoyarlo para hacer algunos círculos más, y repetí. ***No lo hagas por más de 5 minutos: podés correr riesgo de quemadura por frío y provocar la muerte del tejido. Usá una alarma por seguridad.', 55381),
  ('MASAJE CON HIELO EN EL TRÍCEPS', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Apoyá el brazo sobre una mesa. Aplicá el hielo directo de un vaso de masaje sobre la parte de atrás del codo, justo por encima de la zona ósea del codo (zona del tendón del tríceps). Movés el hielo en círculos por hasta 5 minutos (no más). Usá toallas para juntar el agua que gotea. Vas a sentir 4 etapas de sensaciones: 1. Sensación incómoda de frío, después 2. Pinchazos, después 3. Ardor o dolor sordo, y después 4. Adormecimiento. Si el dolor es muy fuerte, despegá el hielo de la piel unos segundos, secá con la toalla y volvé a apoyarlo para hacer algunos círculos más, y repetí. ***No lo hagas por más de 5 minutos: podés correr riesgo de quemadura por frío y provocar la muerte del tejido. Usá una alarma por seguridad.', 55382),
  ('MASAJE CON HIELO EN LA MUÑECA / TÚNEL CARPIANO', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Aplicá el hielo directo de un vaso de masaje sobre la parte de adelante de la muñeca (zona del túnel carpiano). Movés el hielo en círculos por hasta 5 minutos (no más). Usá toallas para juntar el agua que gotea. Vas a sentir 4 etapas de sensaciones: 1. Sensación incómoda de frío, después 2. Pinchazos, después 3. Ardor o dolor sordo, y después 4. Adormecimiento. Si el dolor es muy fuerte, despegá el hielo de la piel unos segundos, secá con la toalla y volvé a apoyarlo para hacer algunos círculos más, y repetí. ***No lo hagas por más de 5 minutos: podés correr riesgo de quemadura por frío y provocar la muerte del tejido. Usá una alarma por seguridad.', 55367),
  ('INSPIRÓMETRO INCENTIVADOR', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Sentate derecho y exhalá completamente. Después, rodeá la boquilla con los labios e inhalá lento y profundo para que el pistón suba hasta el nivel objetivo. Tratá de llevar el marcador de flujo a la posición "Mejor" o "Bueno". Al final de la inhalación, retené el aire 3 a 5 segundos, después soltá el aire de los pulmones y repetí.', 60880),
  ('ELEVADOR DE PIERNA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Ajustá el elevador de pierna de modo que el lazo quede abierto y listo para pasarlo por el pie. Sostené una punta y enganchá el pie con el lazo abierto. Usá los brazos para subir o bajar la pierna desde la cama, el sillón, la bañera, el auto o donde necesites ayuda para mover la pierna.', 39577),
  ('NO CRUZAR LAS PIERNAS AL ESTAR SENTADO - PRECAUCIÓN DE RODILLA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'No cruces las piernas mientras estás sentado, como se muestra. ADVERTENCIA: no cumplir con estas precauciones puede dañar estructuras internas de la columna y/o la rodilla.', 21675),
  ('NO HACER FLEXIONES PROFUNDAS DE RODILLA - PRECAUCIÓN DE RODILLA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'No flexiones profundamente las rodillas estando de pie. Además, no dejes que la rótula pase por delante de la punta del zapato al flexionar, en ningún momento. ADVERTENCIA: no cumplir con estas precauciones puede dañar estructuras internas de la rodilla.', 21676),
  ('NO INCLINARSE EXCESIVAMENTE HACIA ADELANTE AL ESTAR SENTADO - PRECAUCIÓN DE COLUMNA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Estando sentado, no te inclines hacia adelante desde la cintura más allá de 90 grados en ningún momento. ADVERTENCIA: no cumplir con estas precauciones puede dañar estructuras internas de la columna y/o la cadera.', 21673),
  ('NO FLEXIONARSE EXCESIVAMENTE HACIA ADELANTE DE PIE - PRECAUCIÓN DE COLUMNA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'De pie, no te flexiones hacia adelante desde la cintura más allá de 90 grados. ADVERTENCIA: no cumplir con estas precauciones puede provocar daño en las estructuras internas de la columna.', 21674),
  ('NO ARRODILLARSE - PRECAUCIÓN DE RODILLA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'No te arrodilles sobre la rodilla en ningún momento. ADVERTENCIA: no cumplir con estas precauciones puede provocar daño en las estructuras internas de la rodilla.', 21672),
  ('NO LEVANTAR PESO - PRECAUCIÓN DE COLUMNA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'No levantes objetos de más de 4,5 kg en ningún momento. Nota: un litro de leche pesa alrededor de 1 kg; no levantes nada más pesado que eso. ADVERTENCIA: no cumplir con estas precauciones puede provocar daño en las estructuras internas de la columna.', 21678),
  ('NO PERMANECER SENTADO MUCHO TIEMPO - PRECAUCIÓN DE COLUMNA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'No te quedes sentado durante períodos prolongados. ADVERTENCIA: no cumplir con estas precauciones puede provocar daño en las estructuras internas de la columna.', 21685),
  ('NO ESTIRARSE HACIA ADELANTE - PRECAUCIÓN DE COLUMNA Y CADERA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Estando sentado, no te estires hacia adelante con el tronco más allá de una flexión de 90 grados en las caderas. ADVERTENCIA: no cumplir con estas precauciones puede provocar daño en las estructuras internas de la columna y/o la cadera.', 21677),
  ('NADA DEBAJO DE LA RODILLA - PRECAUCIÓN DE RODILLA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Cuando estés acostado, no coloques nada debajo de la rodilla. Mantené la rodilla estirada para favorecer el aumento del rango de extensión.', 39678),
  ('PRECAUCIONES CON MARCAPASOS', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Durante las 6 a 8 semanas posteriores a la cirugía de marcapasos: NO empujes, tires ni levantes nada de 4 kg o más. NO eleves el brazo por encima de la cabeza. NO lleves el brazo hacia el costado del cuerpo. NO pongas el brazo detrás de la espalda. NO te impulses con el brazo para levantarte de una silla. NO alces mascotas ni chicos. NO manejes.', 93287),
  ('ALMOHADA DEBAJO DE LA PIERNA - PRECAUCIÓN DE RODILLA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Cuando estés acostado, PODÉS colocar una almohada a lo largo debajo de la pierna, pero NO la pongas debajo de la rodilla de manera que la haga flexionarse. Mantené la rodilla estirada para favorecer el aumento del rango de extensión.', 39679),
  ('MOVILIZACIÓN DE CICATRIZ - RODADO DE PIEL - LIBERACIÓN MIOFASCIAL', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'No lo hagas sobre una incisión o corte reciente. Esperá a que te saquen los puntos y a que las costras se caigan solas antes de empezar con las técnicas de masaje de cicatriz. Colocá 2 o 3 dedos sobre la cicatriz, pellizcá suavemente la piel que la cubre e intentá rodarla a lo largo de la cicatriz. Podés hacerlo hacia arriba y abajo siguiendo la cicatriz (en paralelo) y también de lado a lado cruzándola (en perpendicular). Pellizcá muy suave mientras rodás la piel. Usá presión suave para evitar que la cicatriz se vuelva a abrir.', 103735),
  ('MOVILIZACIÓN DE CICATRIZ - TORSIÓN - LIBERACIÓN MIOFASCIAL', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'No lo hagas sobre una incisión o corte reciente. Esperá a que te saquen los puntos y a que las costras se caigan solas antes de empezar con las técnicas de masaje de cicatriz. Colocá los dedos a ambos lados de la cicatriz y torcé la piel como se muestra, formando una S con la cicatriz. Mantené esta posición y después soltá. Hacelo a lo largo de toda la cicatriz. Después repetí en la dirección contraria. Usá presión suave para evitar que la cicatriz se vuelva a abrir.', 103736),
  ('PREPARACIÓN DE LA DUCHA Y LA BAÑERA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', '1. BARRALES DE APOYO: instalá barrales firmes en los lugares que te resulten cómodos. Normalmente van dentro de la bañera, sobre la pared principal y adelante o atrás, según cómo entres y salgas. 2. DUCHA DE MANO CON MANGUERA LARGA: instalá una ducha de mano para poder sentarte en un banco o silla de baño y lavarte sin necesidad de estar parado. 3. ESPONJA CON MANGO LARGO: usala para poder lavarte las zonas del cuerpo difíciles de alcanzar. 4. SILLA DE DUCHA: se usa para poder sentarte y lavarte.', 38422),
  ('COLLAR BLANDO', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Usá un collar blando cada vez que...', 50544),
  ('PRECAUCIONES ESTERNALES', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Durante las 6 a 8 semanas posteriores a una cirugía cardíaca a corazón abierto: NO empujes, tires ni levantes nada de 4 kg o más. NO eleves los brazos por encima de la cabeza. NO lleves los brazos hacia el costado del cuerpo. NO pongas los brazos detrás de la espalda. NO te impulses con los brazos para levantarte de una silla. NO alces mascotas ni chicos. NO rotes el cuerpo ni la columna. NO manejes.', 93284),
  ('PELOTAS DE TENIS CON CINTA - AUTOMASAJE', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Colocá dos pelotas de tenis una al lado de la otra y pegalas con cinta. Podés usar cinta deportiva, cinta de papel u otra cinta ancha y blanda. Podés ubicarla en distintas partes del cuerpo para hacerte un automasaje.', 167403),
  ('PELOTAS DE TENIS EN UNA MEDIA - AUTOMASAJE', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Colocá dos pelotas de tenis dentro de una media y hacé un nudo para que queden firmes. Podés ubicarla en distintas partes del cuerpo para hacerte un automasaje.', 167404),
  ('TRX - PREPARACIÓN EN DECÚBITO DORSAL', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Para colocarte fácilmente las cintas del TRX en los pies para los ejercicios boca arriba, empezá sentado de frente a las manijas. Después, colocá los talones en las cintas más bajas de las manijas.', 32699),
  ('MODIFICACIÓN DE LA CORTINA DE BAÑO PARA BANCO DE TRANSFERENCIA', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Hacé un corte en la parte de abajo de la cortina interna de la ducha para que pueda pasar alrededor del banco de transferencia. Esto ayuda a que la cortina quede bien acomodada cuando estás sentado y usás la ducha de mano.', 38401),
  ('LAVARSE LAS MANOS', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'La higiene es importante. Usá jabón y hacé espuma. Lavate las manos durante al menos 20 segundos. Enjuagate bien las manos y las muñecas. Secate las manos y las muñecas. Cambiá la toalla por una limpia con frecuencia.', 91904),
  ('AGUA - HIDRATACIÓN', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Mantenete hidratado y tomá agua.', 72312),
  ('SILLA DE RUEDAS - TRASLADO LATERAL DEL PESO', NULL, true, 'sin_clasificar', 'Educación', 'Varios', 'Cuando estás sentado mucho tiempo en una silla de ruedas, hacen falta descargas de presión en la cola para evitar que se formen lesiones en la piel. La presión prolongada del peso del cuerpo sobre la piel reduce la irrigación de sangre en esa zona. Para mejorar la circulación en la cola, inclinate hacia un costado y usá los brazos para descargar parte del peso de ese lado. Mantené y después hacelo del otro lado.', 104778),
  ('SILLA DE RUEDAS - TRASLADO DEL PESO HACIA ADELANTE', NULL, true, 'sin_clasificar', 'Educación', 'Varios; Posicionamiento', 'Cuando estás sentado mucho tiempo en una silla de ruedas, hacen falta descargas de presión en la cola para evitar que se formen lesiones en la piel. La presión prolongada del peso del cuerpo sobre la piel reduce la irrigación de sangre en esa zona. Para mejorar la circulación en la cola, inclinate hacia adelante para descargar parte del peso. Mantené, relajá y repetí.', 104779),
  ('SILLA DE RUEDAS - DESPLAZARSE EN EL ASIENTO', NULL, true, 'sin_clasificar', 'Educación', 'Varios; Posicionamiento', 'Para desplazarte hacia adelante en la silla de ruedas cuando tenés poca fuerza, empezá trasladando el peso del cuerpo hacia un costado. Después, apoyate contra el respaldo y adelantá la nalga del lado contrario. Luego trasladá el peso hacia el otro costado y repetí hasta lograr avanzar en la silla. Para desplazarte hacia atrás, trasladá el peso hacia un costado mientras usás los brazos, las piernas y/o el cuerpo para retroceder. Después trasladá el peso hacia el otro costado y repetí.', 105326)
